INSERT INTO "devotionals" ("id", "created_date", "updated_date", "created_by_id", "created_by", "title", "scripture_reference", "verse_text", "content", "reading_date", "language", "image_url") VALUES
  ('6aabb8eb2fe1ca910845f236', '2026-09-17T09:54:51.938Z', '2026-09-17T20:48:20.549Z', '6aa138d4e963d9e5f59d838d', NULL, 'Verset du Jour ', 'Ésaïe 28:9-10', 'A qui veut-on enseigner la sagesse? A qui veut-on donner des leçons? Est-ce à des enfants qui viennent d''être sevrés, Qui viennent de quitter la mamelle? Car c''est précepte sur précepte, précepte sur précepte, Règle sur règle, règle sur règle, Un peu ici, un peu là. -', 'À méditer. ', '2026-09-16', 'fr', NULL),
  ('6aadc8fb95c33c224c974f57', '2026-09-18T23:27:55.245Z', '2026-09-25T13:50:20.218Z', '6aa138d4e963d9e5f59d838d', NULL, '1 Chroniques 21:24', '1 Chroniques 21:24', 'Mais le roi David dit à Ornan: Non! je veux l''acheter contre sa valeur en argent, car je ne présenterai point à l''Eternel ce qui est à toi, et je n''offrirai point un holocauste qui ne me coûte rien.', 'Mais le roi David dit à Ornan: Non! je veux l''acheter contre sa valeur en argent, car je ne présenterai point à l''Eternel ce qui est à toi, et je n''offrirai point un holocauste qui ne me coûte rien.', '2026-09-25', 'fr', ''),
  ('6ab66ba202f2f7b2931bf347', '2026-09-25T12:40:02.858Z', '2026-09-25T12:40:02.858Z', '6aa138d4e963d9e5f59d838d', NULL, 'Romains 10:9', 'Romains 10:9', 'Si tu confesses de ta bouche le Seigneur Jésus, et si tu crois dans ton coeur que Dieu l''a ressuscité des morts, tu seras sauvé.', 'Si tu confesses de ta bouche le Seigneur Jésus, et si tu crois dans ton coeur que Dieu l''a ressuscité des morts, tu seras sauvé.', '2026-09-26', 'fr', NULL),
  ('6ab66bc061d239dc88c5ad3a', '2026-09-25T12:40:32.476Z', '2026-09-25T12:40:32.476Z', '6aa138d4e963d9e5f59d838d', NULL, 'Jean 6:45', 'Jean 6:45', 'Il est écrit dans les prophètes: Ils seront tous enseignés de Dieu. Ainsi quiconque a entendu le Père et a reçu son enseignement vient à moi.', 'Il est écrit dans les prophètes: Ils seront tous enseignés de Dieu. Ainsi quiconque a entendu le Père et a reçu son enseignement vient à moi.', '2026-09-27', 'fr', NULL),
  ('6ab66bd5c50ff0079e45bb9c', '2026-09-25T12:40:53.600Z', '2026-09-25T12:40:53.600Z', '6aa138d4e963d9e5f59d838d', NULL, 'Jean 6:44', 'Jean 6:44', 'Nul ne peut venir à moi, si le Père qui m''a envoyé ne l''attire; et je le ressusciterai au dernier jour.', 'Nul ne peut venir à moi, si le Père qui m''a envoyé ne l''attire; et je le ressusciterai au dernier jour.', '2026-09-28', 'fr', NULL),
  ('6ab66c18331db6a82aadfcb2', '2026-09-25T12:42:00.877Z', '2026-09-25T12:42:00.877Z', '6aa138d4e963d9e5f59d838d', NULL, '1 Timothée 4:12', '1 Timothée 4:12', 'Que personne ne méprise ta jeunesse; mais sois un modèle pour les fidèles, en parole, en conduite, en charité, en foi, en pureté.', 'Que personne ne méprise ta jeunesse; mais sois un modèle pour les fidèles, en parole, en conduite, en charité, en foi, en pureté.', '2026-09-29', 'fr', NULL),
  ('6ab66c58d6a4754167c9e4c3', '2026-09-25T12:43:04.904Z', '2026-09-25T12:43:04.904Z', '6aa138d4e963d9e5f59d838d', NULL, 'Psaumes 73:25', 'Psaumes 73:25', 'Quel autre ai-je au ciel que Toi! Et sur la terre je ne prends plaisir qu’en toi.', 'Quel autre ai-je au ciel que Toi! Et sur la terre je ne prends plaisir qu’en toi.', '2026-09-30', 'fr', NULL),
  ('6ab66e03382eaec02ad07f59', '2026-09-25T12:50:11.646Z', '2026-09-25T12:50:11.646Z', '6aa138d4e963d9e5f59d838d', NULL, '1 Corinthians 14:1', '1 Corinthians 14:1', 'Recherchez la charité. Aspirez aussi aux dons spirituels, mais surtout à celui de prophétie.', 'Recherchez la charité. Aspirez aussi aux dons spirituels, mais surtout à celui de prophétie.', '2026-10-01', 'fr', NULL),
  ('6ab66e3eb82349a5c2c224bb', '2026-09-25T12:51:10.074Z', '2026-09-25T12:51:10.074Z', '6aa138d4e963d9e5f59d838d', NULL, 'Proverbes 19:21', 'Proverbes 19:21', 'Il y a dans le coeur de l''homme beaucoup de projets, Mais c''est le dessein de l''Éternel qui s''accomplit.', 'Il y a dans le coeur de l''homme beaucoup de projets, Mais c''est le dessein de l''Éternel qui s''accomplit.', '2026-10-02', 'fr', NULL),
  ('6ab66e6de7d26d23caa7ec52', '2026-09-25T12:51:57.317Z', '2026-09-25T12:51:57.317Z', '6aa138d4e963d9e5f59d838d', NULL, 'Genèse 3:7', 'Genèse 3:7', 'Les yeux de l''un et de l''autre s''ouvrirent, ils connurent qu''ils étaient nus, et ayant cousu des feuilles de figuier, ils s''en firent des ceintures.', 'Les yeux de l''un et de l''autre s''ouvrirent, ils connurent qu''ils étaient nus, et ayant cousu des feuilles de figuier, ils s''en firent des ceintures.', '2026-10-03', 'fr', NULL),
  ('6ab66eb63b68a9ac7db9192a', '2026-09-25T12:53:10.400Z', '2026-09-25T12:53:10.400Z', '6aa138d4e963d9e5f59d838d', NULL, 'Ézéchiel 36:1', 'Ézéchiel 36:1', 'Et toi, fils de l''homme, prophétise sur les montagnes d''Israël! Tu diras: Montagnes d''Israël, écoutez la parole de l''Éternel!', 'Et toi, fils de l''homme, prophétise sur les montagnes d''Israël! Tu diras: Montagnes d''Israël, écoutez la parole de l''Éternel!', '2026-10-04', 'fr', NULL),
  ('6ab66ecd8ce82eea3ebdeb79', '2026-09-25T12:53:33.219Z', '2026-09-25T12:53:33.219Z', '6aa138d4e963d9e5f59d838d', NULL, '1 Thessaloniciens 5:20-21', '1 Thessaloniciens 5:20-21', 'Ne méprisez pas les prophéties.
