  ('6aac5d5b8315a2f0527385fb', '2026-09-17T21:36:27.120Z', '2026-09-17T21:36:27.120Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', 'NOMBRES', 4, 26, 29, 'Fils de Manassé: de Makir descend la famille des Makirites. Makir engendra Galaad. De Galaad descend la famille des Galaadites.', 'fils de manasse: de makir descend la famille des makirites. makir engendra galaad. de galaad descend la famille des galaadites.'),
