  ('6aac5dbbfff1b31404b4e4cf', '2026-09-17T21:38:03.530Z', '2026-09-17T21:38:03.530Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 1, 1, 'Adam, Seth, Énosch,', 'adam, seth, enosch,'),
  ('6aac5dbb5b0fd96c21558c0c', '2026-09-17T21:38:03.866Z', '2026-09-17T21:38:03.866Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 3, 'Fils de Juda: Er, Onan, Schéla; ces trois lui naquirent de la fille de Schua, la Cananéenne. Er, premier-né de Juda, était méchant aux yeux de l’Éternel, qui le fit mourir.', 'fils de juda: er, onan, schela; ces trois lui naquirent de la fille de schua, la cananeenne. er, premier-ne de juda, etait mechant aux yeux de l’eternel, qui le fit mourir.'),
