  ('6aac5dbb5b0fd96c21558c3b', '2026-09-17T21:38:03.867Z', '2026-09-17T21:38:03.867Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 50, 'Ceux-ci furent fils de Caleb: Schobal, fils de Hur, premier-né d’Éphrata, et père de Kirjath-Jearim;', 'ceux-ci furent fils de caleb: schobal, fils de hur, premier-ne d’ephrata, et pere de kirjath-jearim;'),
  ('6aac5dbb5b0fd96c21558c3a', '2026-09-17T21:38:03.867Z', '2026-09-17T21:38:03.867Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 49, 'Elle enfanta encore Schaaph, père de Madmanna, et Scheva, père de Macbéna et père de Guibea. La fille de Caleb était Acsa.', 'elle enfanta encore schaaph, pere de madmanna, et scheva, pere de macbena et pere de guibea. la fille de caleb etait acsa.'),
  ('6aac5dbb5b0fd96c21558c39', '2026-09-17T21:38:03.867Z', '2026-09-17T21:38:03.867Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 48, 'Maaca, concubine de Caleb, enfanta Schéber et Tirchana.', 'maaca, concubine de caleb, enfanta scheber et tirchana.'),
