  ('6aac5dbb5b0fd96c21558c2c', '2026-09-17T21:38:03.867Z', '2026-09-17T21:38:03.867Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 35, 'Et Schéschan donna sa fille pour femme à Jarcha, son esclave, à qui elle enfanta Attaï.', 'et scheschan donna sa fille pour femme a jarcha, son esclave, a qui elle enfanta attai.'),
