  ('6aac5dbb5b0fd96c21558c2a', '2026-09-17T21:38:03.867Z', '2026-09-17T21:38:03.867Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 33, 'Fils de Jonathan: Péleth et Zara. Ce sont là les fils de Jerachmeel.', 'fils de jonathan: peleth et zara. ce sont la les fils de jerachmeel.'),
  ('6aac5dbb5b0fd96c21558c29', '2026-09-17T21:38:03.867Z', '2026-09-17T21:38:03.867Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 32, 'Fils de Jada, frère de Schammaï: Jéther et Jonathan. Jéther mourut sans fils.', 'fils de jada, frere de schammai: jether et jonathan. jether mourut sans fils.'),
  ('6aac5dbb5b0fd96c21558c28', '2026-09-17T21:38:03.867Z', '2026-09-17T21:38:03.867Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 2, 31, 'Fils d’Appaïm: Jischeï. Fils de Jischeï: Schéschan. Fils de Schéschan: Achlaï.', 'fils d’appaim: jischei. fils de jischei: scheschan. fils de scheschan: achlai.'),
