  ('6aac5dbc79846514eeca5e4b', '2026-09-17T21:38:04.177Z', '2026-09-17T21:38:04.177Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 3, 15, 'Fils de Josias: le premier-né, Jochanan; le second, Jojakim; le troisième, Sédécias; le quatrième, Schallum.', 'fils de josias: le premier-ne, jochanan; le second, jojakim; le troisieme, sedecias; le quatrieme, schallum.'),
  ('6aac5dbc79846514eeca5e4a', '2026-09-17T21:38:04.177Z', '2026-09-17T21:38:04.177Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 3, 14, 'Amon, son fils; Josias, son fils.', 'amon, son fils; josias, son fils.'),
