  ('6aac5dbd8ddee07f7aafd910', '2026-09-17T21:38:05.135Z', '2026-09-17T21:38:05.135Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', '1 CHRONIQUES', 13, 6, 2, 'Fils de Kehath: Amram, Jitsehar, Hébron et Uziel.', 'fils de kehath: amram, jitsehar, hebron et uziel.'),
