  ('6aac5dd6b943b679456303c4', '2026-09-17T21:38:30.679Z', '2026-09-17T21:38:30.679Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', 'NÉHÉMIE', 16, 7, 55, 'les fils de Barkos, les fils de Sisera, les fils de Thamach,', 'les fils de barkos, les fils de sisera, les fils de thamach,'),
  ('6aac5dd6b943b679456303bf', '2026-09-17T21:38:30.679Z', '2026-09-17T21:38:30.679Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', 'NÉHÉMIE', 16, 7, 50, 'les fils de Reaja, les fils de Retsin, les fils de Nekoda,', 'les fils de reaja, les fils de retsin, les fils de nekoda,'),
  ('6aac5dd6b943b679456303bd', '2026-09-17T21:38:30.679Z', '2026-09-17T21:38:30.679Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', 'NÉHÉMIE', 16, 7, 48, 'les fils de Lebana, les fils de Hagaba, les fils de Salmaï,', 'les fils de lebana, les fils de hagaba, les fils de salmai,'),
