  ('6aac5dd6b943b679456303b0', '2026-09-17T21:38:30.679Z', '2026-09-17T21:38:30.679Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', 'NÉHÉMIE', 16, 7, 35, 'les fils de Harim, trois cent vingt;', 'les fils de harim, trois cent vingt;'),
