  ('6aac5de2b1cfaded734ff3b3', '2026-09-17T21:38:42.667Z', '2026-09-17T21:38:42.667Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', 'JOB', 18, 13, 18, 'Me voici prêt à plaider ma cause; Je sais que j’ai raison.', 'me voici pret a plaider ma cause; je sais que j’ai raison.'),
