  ('6aac5eaa14aa9eaad3d2e68d', '2026-09-17T21:42:02.405Z', '2026-09-17T21:42:02.405Z', '6aa138d4e963d9e5f59d838d', NULL, 'lsg1910', 'LUC', 42, 3, 32, 'fils d’Isaï, fils de Jobed, fils de Booz, fils de Salmon, fils de Naasson,', 'fils d’isai, fils de jobed, fils de booz, fils de salmon, fils de naasson,'),
