  ('6aadc7260a2ea6260a7ccc57', '2026-09-18T23:20:06.843Z', '2026-09-18T23:20:06.843Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 1, 20, 'Ny taranak’i Robena lahimatoan’i Israely, dia nalahatra araka ny anarany sy ny fianakaviany ary ny fianakaviambeny. Nisaina tsirairay ny lehilahy rehetra 20 taona no ho miakatra efa afaka nanompo tao amin’ny tafika,', 'ny taranak’i robena lahimatoan’i israely, dia nalahatra araka ny anarany sy ny fianakaviany ary ny fianakaviambeny. nisaina tsirairay ny lehilahy rehetra 20 taona no ho miakatra efa afaka nanompo tao amin’ny tafika,'),
  ('6aadc7260a2ea6260a7ccc56', '2026-09-18T23:20:06.843Z', '2026-09-18T23:20:06.843Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 1, 19, 'araka ny didy nomen’i Jehovah an’i Mosesy. Nosoratany tany an-tany efitr’i Sinay àry ny anaran’izy ireny.', 'araka ny didy nomen’i jehovah an’i mosesy. nosoratany tany an-tany efitr’i sinay àry ny anaran’izy ireny.'),
  ('6aadc7260a2ea6260a7ccc55', '2026-09-18T23:20:06.843Z', '2026-09-18T23:20:06.843Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 1, 18, 'Dia novorin’izy ireo daholo ny vahoaka manontolo, tamin’ny andro voalohan’ny volana faharoa, mba hosoratana anarana tsirairay isam-pianakaviana sy isaky ny fianakaviambeny. Ny anaran’izay 20 taona no ho miakatra no nosoratan’izy ireo,', 'dia novorin’izy ireo daholo ny vahoaka manontolo, tamin’ny andro voalohan’ny volana faharoa, mba hosoratana anarana tsirairay isam-pianakaviana sy isaky ny fianakaviambeny. ny anaran’izay 20 taona no ho miakatra no nosoratan’izy ireo,'),
  ('6aadc7260a2ea6260a7ccc54', '2026-09-18T23:20:06.843Z', '2026-09-18T23:20:06.843Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 1, 17, 'Nalain’i Mosesy sy Arona àry ireo lehilahy voatonona anarana ireo.', 'nalain’i mosesy sy arona àry ireo lehilahy voatonona anarana ireo.'),
  ('6aadc7260a2ea6260a7ccc53', '2026-09-18T23:20:06.843Z', '2026-09-18T23:20:06.843Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 1, 16, 'Ireo no voantso avy amin’ny vahoaka. Samy mpiadidy eo amin’ny fokon’ny rainy izy ireo, sady mpifehy ny arivo eo amin’ny Israely.”', 'ireo no voantso avy amin’ny vahoaka. samy mpiadidy eo amin’ny fokon’ny rainy izy ireo, sady mpifehy ny arivo eo amin’ny israely.”'),
