  ('6aadc72af0d6fc751ec29ba5', '2026-09-18T23:20:10.671Z', '2026-09-18T23:20:10.671Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 7, 43, 'no nanao fanatitra, dia vilia volafotsy iray milanja 130 sekely, sy vilia baolina volafotsy iray milanja 70 sekely, araka ny sekely fampiasa ao amin’ny toerana masina, ary samy feno lafarinina tsara toto nafangaro menaka ireo vilia ireo, mba hatao fanatitra varimbazaha;', 'no nanao fanatitra, dia vilia volafotsy iray milanja 130 sekely, sy vilia baolina volafotsy iray milanja 70 sekely, araka ny sekely fampiasa ao amin’ny toerana masina, ary samy feno lafarinina tsara toto nafangaro menaka ireo vilia ireo, mba hatao fanatitra varimbazaha;'),
