  ('6aadc731fce26bea14d89a18', '2026-09-18T23:20:17.181Z', '2026-09-18T23:20:17.181Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 13, 11, 'Gady zanak’i Sosy no avy amin’ny fokon’i Josefa, izany hoe avy amin’ny fokon’i Manase;', 'gady zanak’i sosy no avy amin’ny fokon’i josefa, izany hoe avy amin’ny fokon’i manase;'),
