  ('6aadc73ca81a43d4c77c5ac9', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 28, 'niainga avy tao Tera, dia nitoby tao Mitka;', 'niainga avy tao tera, dia nitoby tao mitka;'),
  ('6aadc73ca81a43d4c77c5abb', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 14, 'niainga avy tao Alosy, dia nitoby tao Refidima. Tsy nisy rano hosotroin’ny olona tao tamin’izay.', 'niainga avy tao alosy, dia nitoby tao refidima. tsy nisy rano hosotroin’ny olona tao tamin’izay.'),
  ('6aadc73ca81a43d4c77c5ae1', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 52, 'Roahy eo anatrehanareo daholo ny mponina ao amin’ilay tany, dia poteho daholo ny sarivongana vato namboarin’izy ireo. Poteho daholo koa ny sarivongana metaly sy ny toerana avo masina ao.', 'roahy eo anatrehanareo daholo ny mponina ao amin’ilay tany, dia poteho daholo ny sarivongana vato namboarin’izy ireo. poteho daholo koa ny sarivongana metaly sy ny toerana avo masina ao.'),
  ('6aadc73ca81a43d4c77c5ad5', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 40, 'Dia henon’ilay Kananita mpanjakan’i Arada, izay nipetraka tany Negeba, tany Kanana, fa tonga ny Israelita.', 'dia henon’ilay kananita mpanjakan’i arada, izay nipetraka tany negeba, tany kanana, fa tonga ny israelita.'),
  ('6aadc73ca81a43d4c77c5ac1', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 20, 'niainga avy tao Rimona-pereza, dia nitoby tao Libna;', 'niainga avy tao rimona-pereza, dia nitoby tao libna;'),
  ('6aadc73ca81a43d4c77c5ac2', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 21, 'niainga avy tao Libna, dia nitoby tao Risa;', 'niainga avy tao libna, dia nitoby tao risa;'),
  ('6aadc73ca81a43d4c77c5abe', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 17, 'niainga avy tao Kibrota-hatava, dia nitoby tao Hazerota;', 'niainga avy tao kibrota-hatava, dia nitoby tao hazerota;'),
  ('6aadc73ca81a43d4c77c5ad4', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 39, 'Ary 123 taona i Arona tamin’izy maty tao amin’ny Tendrombohitra Hora.', 'ary 123 taona i arona tamin’izy maty tao amin’ny tendrombohitra hora.'),
  ('6aadc73ca81a43d4c77c5ab6', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 9, 'Avy eo dia niainga avy tao Mara izy ireo, dia tonga tao Elima. Nisy loharano 12 sy hazo palmie 70 tao Elima, ka nitoby tao izy ireo.', 'avy eo dia niainga avy tao mara izy ireo, dia tonga tao elima. nisy loharano 12 sy hazo palmie 70 tao elima, ka nitoby tao izy ireo.'),
  ('6aadc73ca81a43d4c77c5aaf', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 2, 'Nosoratan’i Mosesy foana izay toerana niaingana isaky ny lalana nandalovan’izy ireo, araka ny baikon’i Jehovah. Ireto avy izany lalana izany, niainga avy teo amin’ny toerana anankiray mankany amin’ny anankiray:', 'nosoratan’i mosesy foana izay toerana niaingana isaky ny lalana nandalovan’izy ireo, araka ny baikon’i jehovah. ireto avy izany lalana izany, niainga avy teo amin’ny toerana anankiray mankany amin’ny anankiray:'),
  ('6aadc73ca81a43d4c77c5adb', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 46, 'niainga avy tao Dibona-gada, dia nitoby tao Almona-diblataima;', 'niainga avy tao dibona-gada, dia nitoby tao almona-diblataima;'),
  ('6aadc73ca81a43d4c77c5ad1', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 36, 'ary niainga avy tao Eziona-gebera, dia nitoby tao an-tany efitr’i Zina, izany hoe Kadesy.', 'ary niainga avy tao eziona-gebera, dia nitoby tao an-tany efitr’i zina, izany hoe kadesy.'),
  ('6aadc73ca81a43d4c77c5ad0', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 35, 'niainga avy tao Abrona, dia nitoby tao Eziona-gebera;', 'niainga avy tao abrona, dia nitoby tao eziona-gebera;'),
  ('6aadc73ca81a43d4c77c5ac5', '2026-09-18T23:20:28.210Z', '2026-09-18T23:20:28.210Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 33, 24, 'Niainga avy teo amin’ny Tendrombohitra Sapera indray izy ireo, dia nitoby tao Harada;', 'niainga avy teo amin’ny tendrombohitra sapera indray izy ireo, dia nitoby tao harada;'),
  ('6aadc73d791ceee89c754f3e', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 11, 'Hanomboka eo Sefama ilay izy ka hitohy hatrany Ribla, hatrany atsinanan’i Aina, ary hidina ihany ka hanapaka ny tehezan-kavoana eny atsinanan’ny Ranomasin’i Kinereta,', 'hanomboka eo sefama ilay izy ka hitohy hatrany ribla, hatrany atsinanan’i aina, ary hidina ihany ka hanapaka ny tehezan-kavoana eny atsinanan’ny ranomasin’i kinereta,'),
  ('6aadc73d791ceee89c754f34', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 1, 'Hoy koa i Jehovah tamin’i Mosesy:', 'hoy koa i jehovah tamin’i mosesy:'),
  ('6aadc73d791ceee89c754f50', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 29, 'Ireo no nasain’i Jehovah nizara an’ilay tany ho an’ny Israelita tao Kanana.', 'ireo no nasain’i jehovah nizara an’ilay tany ho an’ny israelita tao kanana.'),
  ('6aadc73d791ceee89c754f49', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 22, 'Boky mpiadidy zanak’i Jogly no avy amin’ny fokon’ny taranak’i Dana;', 'boky mpiadidy zanak’i jogly no avy amin’ny fokon’ny taranak’i dana;'),
  ('6aadc73d791ceee89c754f42', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 15, 'Ireo foko roa sy sasany ireo dia efa naka ny lovany etỳ atsinanan’ny faritr’i Jordana, tandrifin’i Jeriko, manandrify ny fiposahan’ny masoandro.”', 'ireo foko roa sy sasany ireo dia efa naka ny lovany etỳ atsinanan’ny faritr’i jordana, tandrifin’i jeriko, manandrify ny fiposahan’ny masoandro.”'),
  ('6aadc73d791ceee89c754f3d', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 10, '“‘Farito ny sisin-taninareo any atsinanana, manomboka eo Hazara-enana ka hatrany Sefama.', '“‘farito ny sisin-taninareo any atsinanana, manomboka eo hazara-enana ka hatrany sefama.'),
  ('6aadc73d791ceee89c754f3b', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 8, 'ary avy eo amin’ny Tendrombohitra Hora ka hatrany Lebo-hamata, ary any Zedada ny farany.', 'ary avy eo amin’ny tendrombohitra hora ka hatrany lebo-hamata, ary any zedada ny farany.'),
  ('6aadc73d791ceee89c754f46', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 19, 'Dia ireto no anaran’ireo lehilahy ireo: Kaleba zanak’i Jefone no avy amin’ny fokon’i Joda;', 'dia ireto no anaran’ireo lehilahy ireo: kaleba zanak’i jefone no avy amin’ny fokon’i joda;'),
  ('6aadc73d791ceee89c754f4d', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 26, 'Paltiela mpiadidy zanak’i Azana no avy amin’ny fokon’ny taranak’i Isakara;', 'paltiela mpiadidy zanak’i azana no avy amin’ny fokon’ny taranak’i isakara;'),
  ('6aadc73d791ceee89c754f4f', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 28, 'ary Pedahela mpiadidy zanak’i Amihoda no avy amin’ny fokon’ny taranak’i Naftaly.”', 'ary pedahela mpiadidy zanak’i amihoda no avy amin’ny fokon’ny taranak’i naftaly.”'),
  ('6aadc73d791ceee89c754f48', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 21, 'Elidada zanak’i Kislona no avy amin’ny fokon’i Benjamina;', 'elidada zanak’i kislona no avy amin’ny fokon’i benjamina;'),
  ('6aadc73d791ceee89c754f40', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 13, 'Nomen’i Mosesy toromarika àry ny Israelita hoe: “Io ilay tany hozarainareo ho fanananareo, ka hatao antsapaka ny fizarana azy, araka ilay didy nomen’i Jehovah hoe homena ny foko sivy sy sasany io tany io.', 'nomen’i mosesy toromarika àry ny israelita hoe: “io ilay tany hozarainareo ho fanananareo, ka hatao antsapaka ny fizarana azy, araka ilay didy nomen’i jehovah hoe homena ny foko sivy sy sasany io tany io.'),
  ('6aadc73d791ceee89c754f4a', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 23, 'ny avy amin’ny taranak’i Josefa: Haniela mpiadidy zanak’i Efoda no avy amin’ny fokon’ny taranak’i Manase,', 'ny avy amin’ny taranak’i josefa: haniela mpiadidy zanak’i efoda no avy amin’ny fokon’ny taranak’i manase,'),
  ('6aadc73d791ceee89c754f3c', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 9, 'Dia hitohy hatrany Zifrona ilay izy ka any Hazara-enana ny farany. Io no ho sisiny avaratra amin’ny taninareo.', 'dia hitohy hatrany zifrona ilay izy ka any hazara-enana ny farany. io no ho sisiny avaratra amin’ny taninareo.'),
  ('6aadc73d791ceee89c754f39', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 6, '“‘Ny Ranomasina Lehibe sy ny morontsiraka indray no ho sisiny andrefana amin’ny taninareo. Io no ho sisiny andrefana amin’ny taninareo.', '“‘ny ranomasina lehibe sy ny morontsiraka indray no ho sisiny andrefana amin’ny taninareo. io no ho sisiny andrefana amin’ny taninareo.'),
  ('6aadc73d791ceee89c754f43', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 16, 'Hoy koa i Jehovah tamin’i Mosesy:', 'hoy koa i jehovah tamin’i mosesy:'),
  ('6aadc73d791ceee89c754f38', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 5, 'Dia eo Azmona ilay izy no hivily mankany amin’ny Reniranon’i Ejipta, ary any amin’ny Ranomasina ny farany.', 'dia eo azmona ilay izy no hivily mankany amin’ny reniranon’i ejipta, ary any amin’ny ranomasina ny farany.'),
  ('6aadc73d791ceee89c754f4c', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 25, 'Elizafana mpiadidy zanak’i Parnaka no avy amin’ny fokon’ny taranak’i Zebolona;', 'elizafana mpiadidy zanak’i parnaka no avy amin’ny fokon’ny taranak’i zebolona;'),
  ('6aadc73d791ceee89c754f45', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 18, 'Ary haka mpiadidy iray isam-poko ianareo mba hizara an’ilay tany ho lovanareo.', 'ary haka mpiadidy iray isam-poko ianareo mba hizara an’ilay tany ho lovanareo.'),
  ('6aadc73d791ceee89c754f36', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 3, '“‘Ny sisiny atsimo amin’ny taninareo dia hanomboka any amin’ny tany efitr’i Zina eo akaikin’i Edoma. Ary hanomboka any amin’ny faran’ny Ranomasin-tsira ilay izy, any atsinanana.', '“‘ny sisiny atsimo amin’ny taninareo dia hanomboka any amin’ny tany efitr’i zina eo akaikin’i edoma. ary hanomboka any amin’ny faran’ny ranomasin-tsira ilay izy, any atsinanana.'),
  ('6aadc73d791ceee89c754f4e', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 27, 'Ahihoda mpiadidy zanak’i Selomy no avy amin’ny fokon’ny taranak’i Asera;', 'ahihoda mpiadidy zanak’i selomy no avy amin’ny fokon’ny taranak’i asera;'),
  ('6aadc73d791ceee89c754f47', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 20, 'Semoela zanak’i Amihoda no avy amin’ny fokon’ny taranak’i Simeona;', 'semoela zanak’i amihoda no avy amin’ny fokon’ny taranak’i simeona;'),
  ('6aadc73d791ceee89c754f3a', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 7, '“‘Izao kosa no ho sisiny avaratra amin’ny taninareo: Manomboka eo amin’ny Ranomasina Lehibe ilay izy, ka hatrany amin’ny Tendrombohitra Hora,', '“‘izao kosa no ho sisiny avaratra amin’ny taninareo: manomboka eo amin’ny ranomasina lehibe ilay izy, ka hatrany amin’ny tendrombohitra hora,'),
  ('6aadc73d791ceee89c754f37', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 4, 'Hivily eo atsimon’ilay fiakarana Akrabima ny sisin-taninareo, dia hitohy hatrany Zina, ary any atsimon’i Kadesi-barnea ny farany. Hitatra hatrany Hazara-adara ilay izy ka hitohy hatrany Azmona.', 'hivily eo atsimon’ilay fiakarana akrabima ny sisin-taninareo, dia hitohy hatrany zina, ary any atsimon’i kadesi-barnea ny farany. hitatra hatrany hazara-adara ilay izy ka hitohy hatrany azmona.'),
  ('6aadc73d791ceee89c754f44', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 17, '“Ireto no anaran’ny lehilahy hizara an’ilay tany ho fanananareo: Eleazara mpisorona sy Josoa zanak’i Nona.', '“ireto no anaran’ny lehilahy hizara an’ilay tany ho fanananareo: eleazara mpisorona sy josoa zanak’i nona.'),
  ('6aadc73d791ceee89c754f41', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 14, 'Efa naka ny lovany mantsy ny fokon’ny taranaky ny Robenita isaky ny fianakaviambeny, sy ny fokon’ny taranaky ny Gadita isaky ny fianakaviambeny, ary ny antsasaky ny fokon’i Manase.', 'efa naka ny lovany mantsy ny fokon’ny taranaky ny robenita isaky ny fianakaviambeny, sy ny fokon’ny taranaky ny gadita isaky ny fianakaviambeny, ary ny antsasaky ny fokon’i manase.'),
  ('6aadc73d791ceee89c754f4b', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 24, 'ary Kemoela mpiadidy zanak’i Siftana no avy amin’ny fokon’ny taranak’i Efraima;', 'ary kemoela mpiadidy zanak’i siftana no avy amin’ny fokon’ny taranak’i efraima;'),
  ('6aadc73d791ceee89c754f3f', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 12, 'dia hitohy hatrany amin’ny Reniranon’i Jordana, ka any amin’ny Ranomasin-tsira ny farany. Izany no ho taninareo miaraka amin’ny sisin-tany manodidina azy.’”', 'dia hitohy hatrany amin’ny reniranon’i jordana, ka any amin’ny ranomasin-tsira ny farany. izany no ho taninareo miaraka amin’ny sisin-tany manodidina azy.’”');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6aadc73d791ceee89c754f35', '2026-09-18T23:20:29.526Z', '2026-09-18T23:20:29.526Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 34, 2, '“Omeo an’izao toromarika izao ny Israelita: ‘Hiditra ao Kanana ianareo, ka ireto avy ny sisin’ny tany Kanana, ilay tany homena ho lovanareo.', '“omeo an’izao toromarika izao ny israelita: ‘hiditra ao kanana ianareo, ka ireto avy ny sisin’ny tany kanana, ilay tany homena ho lovanareo.'),
  ('6aadc73e027cf300a4fb5536', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 7, 'Tanàna 48 miaraka amin’ny kijanany àry no homenareo ny Levita.', 'tanàna 48 miaraka amin’ny kijanany àry no homenareo ny levita.'),
  ('6aadc73e027cf300a4fb5531', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 2, '“Teneno ny Israelita hoe omeo tanàna avy amin’ny lovany ny Levita mba hipetrahany. Homen’izy ireo ho an’ny Levita koa ny kijana manodidina an’ireo tanàna ireo.', '“teneno ny israelita hoe omeo tanàna avy amin’ny lovany ny levita mba hipetrahany. homen’izy ireo ho an’ny levita koa ny kijana manodidina an’ireo tanàna ireo.'),
  ('6aadc73e027cf300a4fb5533', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 4, 'Ataovy 1 000 hakiho miala avy eo amin’ny manda manodidina ny tanàna ny kijana homenareo ny Levita.', 'ataovy 1 000 hakiho miala avy eo amin’ny manda manodidina ny tanàna ny kijana homenareo ny levita.'),
  ('6aadc73e027cf300a4fb5535', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 6, '“Ny tanàna homenareo ny Levita dia tanàna fialokalofana 6 handosiran’izay nahafaty olona, miampy tanàna 42 ankoatra an’ireo.', '“ny tanàna homenareo ny levita dia tanàna fialokalofana 6 handosiran’izay nahafaty olona, miampy tanàna 42 ankoatra an’ireo.'),
  ('6aadc73e027cf300a4fb5534', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 5, 'Any ivelan’ny tanàna, dia handrefy 2 000 hakiho amin’ny lafiny atsinanana ianareo, 2 000 hakiho amin’ny lafiny atsimo, 2 000 hakiho amin’ny lafiny andrefana, ary 2 000 hakiho amin’ny lafiny avaratra, ka ny tanàna no eo afovoany. Ireo no ho kijanan’ny tanànan’izy ireo.', 'any ivelan’ny tanàna, dia handrefy 2 000 hakiho amin’ny lafiny atsinanana ianareo, 2 000 hakiho amin’ny lafiny atsimo, 2 000 hakiho amin’ny lafiny andrefana, ary 2 000 hakiho amin’ny lafiny avaratra, ka ny tanàna no eo afovoany. ireo no ho kijanan’ny tanànan’izy ireo.'),
  ('6aadc73e027cf300a4fb5530', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 1, 'Hoy koa i Jehovah tamin’i Mosesy, teo amin’ny lemaka karakaina any Moaba, teo akaikin’ny Reniranon’i Jordana, tandrifin’i Jeriko:', 'hoy koa i jehovah tamin’i mosesy, teo amin’ny lemaka karakaina any moaba, teo akaikin’ny reniranon’i jordana, tandrifin’i jeriko:'),
  ('6aadc73e027cf300a4fb5532', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 3, 'Hipetraka ao amin’ireny tanàna ireny ny Levita, fa ny kijana kosa ho an’ny biby fiompiny sy ny fananany ary ny bibiny hafa rehetra.', 'hipetraka ao amin’ireny tanàna ireny ny levita, fa ny kijana kosa ho an’ny biby fiompiny sy ny fananany ary ny bibiny hafa rehetra.'),
  ('6aadc73e027cf300a4fb5537', '2026-09-18T23:20:30.613Z', '2026-09-18T23:20:30.613Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 8, 'Avy amin’ny tanin’ny Israelita ireo tanàna homenareo ny Levita ireo. Izay foko lehibe kokoa no hakanareo betsaka, ary izay foko kely kokoa hakanareo kely. Samy hanome amin’ny tanànany ho an’ny Levita ny foko tsirairay, arakaraka ny lova azony.”', 'avy amin’ny tanin’ny israelita ireo tanàna homenareo ny levita ireo. izay foko lehibe kokoa no hakanareo betsaka, ary izay foko kely kokoa hakanareo kely. samy hanome amin’ny tanànany ho an’ny levita ny foko tsirairay, arakaraka ny lova azony.”'),
  ('6aadc73e027cf300a4fb5551', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 34, 'Aza mandoto an’ilay tany ipetrahanareo, izay sady onenako koa. Fa izaho Jehovah dia monina eo afovoan’ny vahoakan’Israely.’”', 'aza mandoto an’ilay tany ipetrahanareo, izay sady onenako koa. fa izaho jehovah dia monina eo afovoan’ny vahoakan’israely.’”'),
  ('6aadc73e027cf300a4fb554c', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 29, 'Izany no lalàna harahinareo hatramin’ny taranakareo fara aman-dimby, rehefa mitsara an’ireo raharaha ireo ianareo, any amin’izay tany ipetrahanareo.', 'izany no lalàna harahinareo hatramin’ny taranakareo fara aman-dimby, rehefa mitsara an’ireo raharaha ireo ianareo, any amin’izay tany ipetrahanareo.'),
  ('6aadc73e027cf300a4fb553f', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 16, '“‘Raha fitaovana vy no namelezany an’ilay olona ka maty ilay olona, dia mpamono olona izy. Tsy maintsy vonoina ho faty ilay mpamono olona.', '“‘raha fitaovana vy no namelezany an’ilay olona ka maty ilay olona, dia mpamono olona izy. tsy maintsy vonoina ho faty ilay mpamono olona.'),
  ('6aadc73e027cf300a4fb553b', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 12, 'Ho fialokalofana ho anareo ireny tanàna ireny, mba tsy ho tratran’ny mpamaly ra ianareo. Amin’izay dia tsy ho faty izay nahafaty olona, alohan’ny hitsarana azy eo anatrehan’ny vahoaka.', 'ho fialokalofana ho anareo ireny tanàna ireny, mba tsy ho tratran’ny mpamaly ra ianareo. amin’izay dia tsy ho faty izay nahafaty olona, alohan’ny hitsarana azy eo anatrehan’ny vahoaka.'),
  ('6aadc73e027cf300a4fb5548', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 25, 'Avy eo dia hovonjen’ny fiangonana mba tsy ho tratran’ny mpamaly ra ilay nahafaty olona, ka haverina any amin’ilay tanàna fialokalofana efa nalehany tamin’izy nandositra. Hipetraka any izy mandra-pahafatin’ny mpisoronabe izay nohosorana menaka masina.', 'avy eo dia hovonjen’ny fiangonana mba tsy ho tratran’ny mpamaly ra ilay nahafaty olona, ka haverina any amin’ilay tanàna fialokalofana efa nalehany tamin’izy nandositra. hipetraka any izy mandra-pahafatin’ny mpisoronabe izay nohosorana menaka masina.'),
  ('6aadc73e027cf300a4fb553e', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 15, 'Ho fialokalofana ho an’ny Israelita sy ny vahiny ary ny mpiavy ireo tanàna enina ireo, mba handosiran’izay nahafaty olona tsy nahy.', 'ho fialokalofana ho an’ny israelita sy ny vahiny ary ny mpiavy ireo tanàna enina ireo, mba handosiran’izay nahafaty olona tsy nahy.'),
  ('6aadc73e027cf300a4fb554e', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 31, 'Aza mandray vidim-panavotana hamonjena ny ain’ny mpamono olona izay mendrika ny ho faty. Tsy maintsy vonoina ho faty mantsy izy.', 'aza mandray vidim-panavotana hamonjena ny ain’ny mpamono olona izay mendrika ny ho faty. tsy maintsy vonoina ho faty mantsy izy.'),
  ('6aadc73e027cf300a4fb5544', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 21, 'na raha nasiany ilay olona satria halany ka maty, dia tsy maintsy vonoina ho faty ilay namely. Mpamono olona izy. Hamono azy ho faty ny mpamaly ra rehefa mahita azy.', 'na raha nasiany ilay olona satria halany ka maty, dia tsy maintsy vonoina ho faty ilay namely. mpamono olona izy. hamono azy ho faty ny mpamaly ra rehefa mahita azy.'),
  ('6aadc73e027cf300a4fb553d', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 14, 'Tanàna telo no homenareo etỳ ampitan’i Jordana, ary telo kosa any Kanana, mba hatao tanàna fialokalofana.', 'tanàna telo no homenareo etỳ ampitan’i jordana, ary telo kosa any kanana, mba hatao tanàna fialokalofana.'),
  ('6aadc73e027cf300a4fb5550', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 33, '“‘Aza mandoto ny tany misy anareo. Mandoto ny tany mantsy ny ra. Tsy misy fandrakofam-pahotana ho an’ilay tany raha misy ra nalatsaka teo amin’ilay izy, afa-tsy ny ran’izay nandatsaka an’izany ihany.', '“‘aza mandoto ny tany misy anareo. mandoto ny tany mantsy ny ra. tsy misy fandrakofam-pahotana ho an’ilay tany raha misy ra nalatsaka teo amin’ilay izy, afa-tsy ny ran’izay nandatsaka an’izany ihany.'),
  ('6aadc73e027cf300a4fb5549', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 26, '“‘Raha mivoaka an’ilay faritry ny tanàna fialokalofana nalehany anefa ilay nahafaty olona,', '“‘raha mivoaka an’ilay faritry ny tanàna fialokalofana nalehany anefa ilay nahafaty olona,'),
  ('6aadc73e027cf300a4fb5547', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 24, 'dia hotsarain’ny fiangonana araka ireo didy ireo ilay namely sy ny mpamaly ra.', 'dia hotsarain’ny fiangonana araka ireo didy ireo ilay namely sy ny mpamaly ra.'),
  ('6aadc73e027cf300a4fb553a', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 11, 'Fidio izay tanàna mety aminareo, mba hatao tanàna fialokalofana handosiran’izay nahafaty olona tsy nahy.', 'fidio izay tanàna mety aminareo, mba hatao tanàna fialokalofana handosiran’izay nahafaty olona tsy nahy.'),
  ('6aadc73e027cf300a4fb5545', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 22, '“‘Raha tsy nampoiziny kosa fa voatosiny ilay olona na voatorany zavatra, nefa tsy halany na tsy tiany hovonoina,', '“‘raha tsy nampoiziny kosa fa voatosiny ilay olona na voatorany zavatra, nefa tsy halany na tsy tiany hovonoina,'),
  ('6aadc73e027cf300a4fb553c', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 13, 'Izany no hampiasana ny tanàna fialokalofana enina homenareo.', 'izany no hampiasana ny tanàna fialokalofana enina homenareo.'),
  ('6aadc73e027cf300a4fb554f', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 32, 'Ary aza mandray vidim-panavotana homen’izay nandositra tany amin’ny tanàna fialokalofana mba hamelana azy hody any amin’ny taniny alohan’ny hahafatesan’ny mpisoronabe.', 'ary aza mandray vidim-panavotana homen’izay nandositra tany amin’ny tanàna fialokalofana mba hamelana azy hody any amin’ny taniny alohan’ny hahafatesan’ny mpisoronabe.'),
  ('6aadc73e027cf300a4fb554d', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 30, '“‘Izay mahafaty olona dia tokony hovonoina ho faty, satria mpamono olona. Tokony hisy vavolombelona manamarina an’izany anefa. Tsy misy azo vonoina ho faty kosa raha iray monja ny vavolombelona.', '“‘izay mahafaty olona dia tokony hovonoina ho faty, satria mpamono olona. tokony hisy vavolombelona manamarina an’izany anefa. tsy misy azo vonoina ho faty kosa raha iray monja ny vavolombelona.'),
  ('6aadc73e027cf300a4fb5543', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 20, 'Ary raha maty ilay olona fa natosiny satria halany, na notorahany satria tiany hovonoina,', 'ary raha maty ilay olona fa natosiny satria halany, na notorahany satria tiany hovonoina,'),
  ('6aadc73e027cf300a4fb5542', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 19, '“‘Ny mpamaly ra no hamono ho faty an’ilay mpamono olona. Izy no hamono azy ho faty rehefa mahita azy.', '“‘ny mpamaly ra no hamono ho faty an’ilay mpamono olona. izy no hamono azy ho faty rehefa mahita azy.'),
  ('6aadc73e027cf300a4fb5541', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 18, 'Ary raha fitaovana vita amin’ny hazo mety hahafaty no namelezany azy ka maty ilay olona, dia mpamono olona izy. Tsy maintsy vonoina ho faty ilay mpamono olona.', 'ary raha fitaovana vita amin’ny hazo mety hahafaty no namelezany azy ka maty ilay olona, dia mpamono olona izy. tsy maintsy vonoina ho faty ilay mpamono olona.'),
  ('6aadc73e027cf300a4fb5539', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 10, '“Teneno ny Israelita hoe: ‘Hiampita an’i Jordana izao ianareo, dia ho any Kanana.', '“teneno ny israelita hoe: ‘hiampita an’i jordana izao ianareo, dia ho any kanana.'),
  ('6aadc73e027cf300a4fb554b', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 28, 'Tsy maintsy mipetraka ao amin’ny tanàna fialokalofana mantsy ilay nahafaty olona, mandra-pahafatin’ny mpisoronabe. Fa rehefa maty ilay mpisoronabe, dia mahazo miverina any amin’ny taniny izy.', 'tsy maintsy mipetraka ao amin’ny tanàna fialokalofana mantsy ilay nahafaty olona, mandra-pahafatin’ny mpisoronabe. fa rehefa maty ilay mpisoronabe, dia mahazo miverina any amin’ny taniny izy.'),
  ('6aadc73e027cf300a4fb554a', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 27, 'ary hitan’ny mpamaly ra any ivelan’ny faritr’ilay tanàna izy ka vonoiny, dia tsy ho meloka ho nandatsa-dra ilay mpamaly ra.', 'ary hitan’ny mpamaly ra any ivelan’ny faritr’ilay tanàna izy ka vonoiny, dia tsy ho meloka ho nandatsa-dra ilay mpamaly ra.'),
  ('6aadc73e027cf300a4fb5540', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 17, 'Raha vato mety hahafaty no namelezany azy ka maty ilay olona, dia mpamono olona izy. Tsy maintsy vonoina ho faty ilay mpamono olona.', 'raha vato mety hahafaty no namelezany azy ka maty ilay olona, dia mpamono olona izy. tsy maintsy vonoina ho faty ilay mpamono olona.'),
  ('6aadc73e027cf300a4fb5546', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 23, 'na raha tsy hitany ilay olona ka voazerany vato, nefa izy tsy fahavalon’ilay olona na te hanisy ratsy azy, ka maty ilay olona,', 'na raha tsy hitany ilay olona ka voazerany vato, nefa izy tsy fahavalon’ilay olona na te hanisy ratsy azy, ka maty ilay olona,'),
  ('6aadc73e027cf300a4fb5538', '2026-09-18T23:20:30.614Z', '2026-09-18T23:20:30.614Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 35, 9, 'Hoy koa i Jehovah tamin’i Mosesy:', 'hoy koa i jehovah tamin’i mosesy:'),
  ('6aadc73f119e47fb4757c449', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 4, 'Ary rehefa tonga ny Jobily ho an’ny vahoakan’Israely, dia hatambatra amin’ny lovan’ny fokon’izay olona ho vadiny ny lovan-dry zareo, ka hesorina amin’ny lovan’ny fokon’ny razambenay.”', 'ary rehefa tonga ny jobily ho an’ny vahoakan’israely, dia hatambatra amin’ny lovan’ny fokon’izay olona ho vadiny ny lovan-dry zareo, ka hesorina amin’ny lovan’ny fokon’ny razambenay.”'),
  ('6aadc73f119e47fb4757c44e', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 9, 'Tsy misy lova tokony hafindrafindra foko eo amin’ny Israelita, fa samy tokony hitazona ny lovany avy ny fokon’ny Israely.’”', 'tsy misy lova tokony hafindrafindra foko eo amin’ny israelita, fa samy tokony hitazona ny lovany avy ny fokon’ny israely.’”'),
  ('6aadc73f119e47fb4757c447', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 2, 'Dia hoy izy ireo: “Nomen’i Jehovah didy ny tompoko mba hizara ny tany ho lovan’ny Israelita amin’ny alalan’ny antsapaka. Nodidian’i Jehovah koa ny tompoko mba hanome ny lovan’i Zelofada rahalahinay ho an’ny zanany vavy.', 'dia hoy izy ireo: “nomen’i jehovah didy ny tompoko mba hizara ny tany ho lovan’ny israelita amin’ny alalan’ny antsapaka. nodidian’i jehovah koa ny tompoko mba hanome ny lovan’i zelofada rahalahinay ho an’ny zanany vavy.'),
  ('6aadc73f119e47fb4757c450', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 11, 'Nanambady an’ireo zanaky ny rahalahin-drainy àry i Mahala sy Tirza sy Hogla sy Milka ary Noa, zanakavavin’i Zelofada.', 'nanambady an’ireo zanaky ny rahalahin-drainy àry i mahala sy tirza sy hogla sy milka ary noa, zanakavavin’i zelofada.'),
  ('6aadc73f119e47fb4757c44f', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 10, 'Dia nanao an’izay nandidian’i Jehovah an’i Mosesy ny zanakavavin’i Zelofada.', 'dia nanao an’izay nandidian’i jehovah an’i mosesy ny zanakavavin’i zelofada.'),
  ('6aadc73f119e47fb4757c44a', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 5, 'Dia notenenin’i Mosesy ny Israelita, araka ny baikon’i Jehovah, hoe: “Marina izany tenin’ny fokon’ny taranak’i Josefa izany.', 'dia notenenin’i mosesy ny israelita, araka ny baikon’i jehovah, hoe: “marina izany tenin’ny fokon’ny taranak’i josefa izany.'),
  ('6aadc73f119e47fb4757c44d', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 8, 'Izay anisan’ny taranaky ny fokon’ny rainy ihany no tokony ho vadin’ny zanakavavy rehetra manana lova eo amin’ny fokon’ny Israely. Amin’izay dia samy hitazona ny lovan’ny razambeny ny Israelita.', 'izay anisan’ny taranaky ny fokon’ny rainy ihany no tokony ho vadin’ny zanakavavy rehetra manana lova eo amin’ny fokon’ny israely. amin’izay dia samy hitazona ny lovan’ny razambeny ny israelita.'),
  ('6aadc73f119e47fb4757c451', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 12, 'Lasa vadin’ny lehilahy tao amin’ny fianakavian’ny taranak’i Manase, zanak’i Josefa, izy ireo. Amin’izay dia hijanona ao amin’ny fokon’ny fianakavian’ny rainy ihany ny lovan’izy ireo.', 'lasa vadin’ny lehilahy tao amin’ny fianakavian’ny taranak’i manase, zanak’i josefa, izy ireo. amin’izay dia hijanona ao amin’ny fokon’ny fianakavian’ny rainy ihany ny lovan’izy ireo.'),
  ('6aadc73f119e47fb4757c452', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 13, 'Ireo no didy sy didim-pitsarana nomen’i Jehovah ny Israelita tamin’ny alalan’i Mosesy, teo amin’ny lemaka karakaina any Moaba, teo akaikin’ny Reniranon’i Jordana, tandrifin’i Jeriko.', 'ireo no didy sy didim-pitsarana nomen’i jehovah ny israelita tamin’ny alalan’i mosesy, teo amin’ny lemaka karakaina any moaba, teo akaikin’ny reniranon’i jordana, tandrifin’i jeriko.'),
  ('6aadc73f119e47fb4757c44b', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 6, 'Izao àry no didin’i Jehovah ho an’ny zanakavavin’i Zelofada: ‘Afaka manambady an’izay tiany izy ireo, nefa tokony ho ao amin’ny fianakavian’ny fokon’ny rainy ihany.', 'izao àry no didin’i jehovah ho an’ny zanakavavin’i zelofada: ‘afaka manambady an’izay tiany izy ireo, nefa tokony ho ao amin’ny fianakavian’ny fokon’ny rainy ihany.'),
  ('6aadc73f119e47fb4757c448', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 3, 'Raha manambady lehilahy avy amin’ny foko hafa amin’ny Israelita anefa izy ireo, dia hesorina amin’ny lovan’ny razambenay ny lovan-dry zareo, ka hitambatra amin’ny lovan’ny fokon’izay olona ho vadiny. Dia hesorina amin’ny lova nomena anay tamin’ny antsapaka izany.', 'raha manambady lehilahy avy amin’ny foko hafa amin’ny israelita anefa izy ireo, dia hesorina amin’ny lovan’ny razambenay ny lovan-dry zareo, ka hitambatra amin’ny lovan’ny fokon’izay olona ho vadiny. dia hesorina amin’ny lova nomena anay tamin’ny antsapaka izany.'),
  ('6aadc73f119e47fb4757c44c', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 7, 'Tsy misy lova tokony hafindrafindra foko eo amin’ny Israelita, fa samy tokony hitazona ny lovan’ny fokon’ny razambeny izy ireo.', 'tsy misy lova tokony hafindrafindra foko eo amin’ny israelita, fa samy tokony hitazona ny lovan’ny fokon’ny razambeny izy ireo.'),
  ('6aadc73f119e47fb4757c446', '2026-09-18T23:20:31.600Z', '2026-09-18T23:20:31.600Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nomery', 4, 36, 1, 'Dia nanatona an’i Mosesy sy ireo mpiadidy teo amin’ny Israelita ny lohan’ny fianakaviamben’ny taranak’i Gileada, zanak’i Makira, zanak’i Manase, avy tamin’ny fianakaviamben’ny taranak’i Josefa.', 'dia nanatona an’i mosesy sy ireo mpiadidy teo amin’ny israelita ny lohan’ny fianakaviamben’ny taranak’i gileada, zanak’i makira, zanak’i manase, avy tamin’ny fianakaviamben’ny taranak’i josefa.'),
  ('6aadc74015b0abb57fb22d20', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 5, 'Tao amin’ny faritr’i Jordana, any Moaba, i Mosesy no nanazava an’izao Lalàna izao:', 'tao amin’ny faritr’i jordana, any moaba, i mosesy no nanazava an’izao lalàna izao:'),
  ('6aadc74015b0abb57fb22d3f', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 36, 'afa-tsy i Kaleba zanak’i Jefone. Hahita azy io izy ary homeko azy sy ny taranany ilay tany nandehanany, satria nanaraka an’i Jehovah tamin’ny fony manontolo izy.', 'afa-tsy i kaleba zanak’i jefone. hahita azy io izy ary homeko azy sy ny taranany ilay tany nandehanany, satria nanaraka an’i jehovah tamin’ny fony manontolo izy.'),
  ('6aadc74015b0abb57fb22d3a', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 31, 'Hitanareo tany an-tany efitra koa fa tahaka ny fitondran’ny olona an-janany no nitondran’i Jehovah Andriamanitrareo anareo, na taiza na taiza nalehanareo mandra-pahatonganareo teto.’', 'hitanareo tany an-tany efitra koa fa tahaka ny fitondran’ny olona an-janany no nitondran’i jehovah andriamanitrareo anareo, na taiza na taiza nalehanareo mandra-pahatonganareo teto.’'),
  ('6aadc74015b0abb57fb22d39', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 30, 'Fa handeha eo alohanareo i Jehovah Andriamanitrareo ary hiady ho anareo, hoatran’ny efa hitanareo nataony tany Ejipta.', 'fa handeha eo alohanareo i jehovah andriamanitrareo ary hiady ho anareo, hoatran’ny efa hitanareo nataony tany ejipta.'),
  ('6aadc74015b0abb57fb22d37', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 28, 'Koa inona no mbola handehanantsika any amin’izany toerana izany? Efa nampihorohoro ny fontsika mantsy ny rahalahintsika rehefa nilaza hoe: “Vaventy sy lava noho isika ry zareo. Lehibe koa ny tanànany sady misy manda manakatra ny lanitra. Hitanay tany koa ny taranaky ny Anakita.”’', 'koa inona no mbola handehanantsika any amin’izany toerana izany? efa nampihorohoro ny fontsika mantsy ny rahalahintsika rehefa nilaza hoe: “vaventy sy lava noho isika ry zareo. lehibe koa ny tanànany sady misy manda manakatra ny lanitra. hitanay tany koa ny taranaky ny anakita.”’'),
  ('6aadc74015b0abb57fb22d36', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 27, 'Dia nimenomenona foana ianareo tao an-tranolainareo, hoe: ‘Halan’i Jehovah isika matoa nentiny nivoaka avy tany Ejipta, mba hatolony ho eo am-pelatanan’ny Amorita dia haringan’izy ireo.', 'dia nimenomenona foana ianareo tao an-tranolainareo, hoe: ‘halan’i jehovah isika matoa nentiny nivoaka avy tany ejipta, mba hatolony ho eo am-pelatanan’ny amorita dia haringan’izy ireo.'),
  ('6aadc74015b0abb57fb22d25', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 10, 'Efa nataon’i Jehovah Andriamanitrareo nihabetsaka ianareo, ka izao ianareo lasa be dia be hoatran’ny kintana eny amin’ny lanitra.', 'efa nataon’i jehovah andriamanitrareo nihabetsaka ianareo, ka izao ianareo lasa be dia be hoatran’ny kintana eny amin’ny lanitra.'),
  ('6aadc74015b0abb57fb22d47', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 44, 'Kanjo nivoaka hiady taminareo ny Amorita nipetraka tany amin’ilay tendrombohitra, ka nanenjika anareo toy ny tantely, dia nanaparitaka anareo tany Seira ka hatrany Horma.', 'kanjo nivoaka hiady taminareo ny amorita nipetraka tany amin’ilay tendrombohitra, ka nanenjika anareo toy ny tantely, dia nanaparitaka anareo tany seira ka hatrany horma.'),
  ('6aadc74015b0abb57fb22d2f', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 20, 'Dia hoy aho taminareo: ‘Tonga eto amin’ity faritra be tendrombohitra misy ny Amorita ity ianareo, ary homen’i Jehovah Andriamanitsika antsika izy ity.', 'dia hoy aho taminareo: ‘tonga eto amin’ity faritra be tendrombohitra misy ny amorita ity ianareo, ary homen’i jehovah andriamanitsika antsika izy ity.'),
  ('6aadc74015b0abb57fb22d46', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 43, 'Dia niteny taminareo aho nefa tsy nohenoinareo. Nikomy tsy nanaraka ny baikon’i Jehovah kosa ianareo, dia sahisahy ratsy niakatra tany an-tendrombohitra ihany.', 'dia niteny taminareo aho nefa tsy nohenoinareo. nikomy tsy nanaraka ny baikon’i jehovah kosa ianareo, dia sahisahy ratsy niakatra tany an-tendrombohitra ihany.'),
  ('6aadc74015b0abb57fb22d35', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 26, 'Tsy nety niakatra anefa ianareo, fa nikomy tsy nanaraka ny baikon’i Jehovah Andriamanitrareo.', 'tsy nety niakatra anefa ianareo, fa nikomy tsy nanaraka ny baikon’i jehovah andriamanitrareo.'),
  ('6aadc74015b0abb57fb22d34', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 25, 'Dia nakan-dry zareo ny vokatr’ilay tany, ka nentiny tany amintsika. Ary nanao tatitra tamintsika ry zareo hoe: ‘Tsara ilay tany homen’i Jehovah Andriamanitsika antsika.’', 'dia nakan-dry zareo ny vokatr’ilay tany, ka nentiny tany amintsika. ary nanao tatitra tamintsika ry zareo hoe: ‘tsara ilay tany homen’i jehovah andriamanitsika antsika.’'),
  ('6aadc74015b0abb57fb22d2c', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 17, 'Aza miangatra rehefa mitsara, fa henoy sahala amin’ny lehibe ihany ny madinika. Aza matahotra olona, fa an’Andriamanitra ny fitsarana. Raha misy raharaha sarotra loatra aminareo, dia ento atỳ amiko, fa izaho no hihaino an’izany.’', 'aza miangatra rehefa mitsara, fa henoy sahala amin’ny lehibe ihany ny madinika. aza matahotra olona, fa an’andriamanitra ny fitsarana. raha misy raharaha sarotra loatra aminareo, dia ento atỳ amiko, fa izaho no hihaino an’izany.’'),
  ('6aadc74015b0abb57fb22d2a', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 15, 'Koa nalaiko ireo lehiben’ny fokonareo ireo, dia lehilahy hendry sy za-draharaha, ka notendreko ho lehibenareo, izany hoe lehiben’ny arivo, lehiben’ny zato, lehiben’ny dimampolo, lehiben’ny folo, ary mpifehy ny fokonareo.', 'koa nalaiko ireo lehiben’ny fokonareo ireo, dia lehilahy hendry sy za-draharaha, ka notendreko ho lehibenareo, izany hoe lehiben’ny arivo, lehiben’ny zato, lehiben’ny dimampolo, lehiben’ny folo, ary mpifehy ny fokonareo.'),
  ('6aadc74015b0abb57fb22d28', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 13, 'Mifidiana àry lehilahy hendry sy malina ary za-draharaha eo amin’ny fokonareo, mba hotendreko ho lehibenareo.’', 'mifidiana àry lehilahy hendry sy malina ary za-draharaha eo amin’ny fokonareo, mba hotendreko ho lehibenareo.’'),
  ('6aadc74015b0abb57fb22d40', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 37, 'Tezitra tamiko mihitsy koa aza i Jehovah noho ny nataonareo, ka niteny hoe: “Ianao koa tsy hiditra any,', 'tezitra tamiko mihitsy koa aza i jehovah noho ny nataonareo, ka niteny hoe: “ianao koa tsy hiditra any,'),
  ('6aadc74015b0abb57fb22d3e', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 35, '‘Tsy hisy amin’ity taranaka ratsy fanahy ity na iray aza hahita an’ilay tany tsara, izay nianianako homena ny razambenareo,', '‘tsy hisy amin’ity taranaka ratsy fanahy ity na iray aza hahita an’ilay tany tsara, izay nianianako homena ny razambenareo,'),
  ('6aadc74015b0abb57fb22d24', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 9, '“Hoy aho taminareo tamin’izay: ‘Tsy vitako irery ny mitondra anareo.', '“hoy aho taminareo tamin’izay: ‘tsy vitako irery ny mitondra anareo.'),
  ('6aadc74015b0abb57fb22d1d', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 2, 'Lalana 11 andro avy any Horeba ny mankany Kadesi-barnea, raha any an-tendrombohitra Seira no lalana.', 'lalana 11 andro avy any horeba ny mankany kadesi-barnea, raha any an-tendrombohitra seira no lalana.'),
  ('6aadc74015b0abb57fb22d23', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 8, 'Efa nataoko io alohanareo io ilay tany. Midira ao dia alaivo ho anareo izy io. Io ilay tany nianianan’i Jehovah tamin’ny razambenareo, dia tamin’i Abrahama sy Isaka ary Jakoba hoe homeny azy ireo sy ny taranany.’', 'efa nataoko io alohanareo io ilay tany. midira ao dia alaivo ho anareo izy io. io ilay tany nianianan’i jehovah tamin’ny razambenareo, dia tamin’i abrahama sy isaka ary jakoba hoe homeny azy ireo sy ny taranany.’'),
  ('6aadc74015b0abb57fb22d21', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 6, '“Hoy i Jehovah Andriamanitsika tamintsika tany Horeba: ‘Efa ela ihany izay ianareo no nijanona teo amin’io faritra be tendrombohitra io.', '“hoy i jehovah andriamanitsika tamintsika tany horeba: ‘efa ela ihany izay ianareo no nijanona teo amin’io faritra be tendrombohitra io.'),
  ('6aadc74015b0abb57fb22d49', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 46, 'Dia izany no nahatonga anareo hipetraka ela be tany Kadesy.', 'dia izany no nahatonga anareo hipetraka ela be tany kadesy.'),
  ('6aadc74015b0abb57fb22d30', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 21, 'Efa nomen’i Jehovah Andriamanitrareo anareo ity tany ity. Koa miakara dia alaivo ho anareo izy io, araka ny tenin’i Jehovah Andriamanitry ny razambenareo taminareo. Aza matahotra na mihorohoro.’', 'efa nomen’i jehovah andriamanitrareo anareo ity tany ity. koa miakara dia alaivo ho anareo izy io, araka ny tenin’i jehovah andriamanitry ny razambenareo taminareo. aza matahotra na mihorohoro.’'),
  ('6aadc74015b0abb57fb22d3b', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 32, 'Mbola tsy nino an’i Jehovah Andriamanitrareo ihany anefa ianareo, na teo aza izany rehetra izany.', 'mbola tsy nino an’i jehovah andriamanitrareo ihany anefa ianareo, na teo aza izany rehetra izany.'),
  ('6aadc74015b0abb57fb22d33', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 24, 'Koa lasa ry zareo niakatra ho any amin’ilay faritra be tendrombohitra, ary tonga tany amin’ny Lohasahan’i Eskola, ka nitsikilo an’ilay tany.', 'koa lasa ry zareo niakatra ho any amin’ilay faritra be tendrombohitra, ary tonga tany amin’ny lohasahan’i eskola, ka nitsikilo an’ilay tany.'),
  ('6aadc74015b0abb57fb22d29', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 14, 'Dia hoy ianareo tamiko: ‘Tsara izany asainao ataonay izany.’', 'dia hoy ianareo tamiko: ‘tsara izany asainao ataonay izany.’'),
  ('6aadc74015b0abb57fb22d27', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 12, 'Mavesatra sady mafy be amiko ny mitondra anareo sy mandamina ny adinareo, koa ahoana no hahavitako irery an’izany?', 'mavesatra sady mafy be amiko ny mitondra anareo sy mandamina ny adinareo, koa ahoana no hahavitako irery an’izany?'),
  ('6aadc74015b0abb57fb22d26', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 11, 'Enga anie i Jehovah Andriamanitry ny razambenareo hampitombo ny isanareo ho avo arivo heny noho izao, ka hitahy anareo araka izay nampanantenainy anareo!', 'enga anie i jehovah andriamanitry ny razambenareo hampitombo ny isanareo ho avo arivo heny noho izao, ka hitahy anareo araka izay nampanantenainy anareo!'),
  ('6aadc74015b0abb57fb22d45', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 42, 'Hoy anefa i Jehovah tamiko: ‘Lazao amin’izy ireo hoe: “Aza miakatra hiady fa tsy hanampy anareo aho. Raha miakatra any ianareo, dia ho resin’ny fahavalonareo.”’', 'hoy anefa i jehovah tamiko: ‘lazao amin’izy ireo hoe: “aza miakatra hiady fa tsy hanampy anareo aho. raha miakatra any ianareo, dia ho resin’ny fahavalonareo.”’'),
  ('6aadc74015b0abb57fb22d3d', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 34, '“Henon’i Jehovah daholo ny teninareo tamin’izay, dia tezitra izy ka nianiana hoe:', '“henon’i jehovah daholo ny teninareo tamin’izay, dia tezitra izy ka nianiana hoe:'),
  ('6aadc74015b0abb57fb22d3c', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 33, 'Nandeha teo alohanareo anefa izy teny an-dalana, mba hitady toerana hitobianareo. Nasehony hoe teo aminareo izy, ka afo no nampiasainy rehefa alina ary rahona rehefa antoandro, amin’izay dia hitanareo ny lalana tokony halehanareo.', 'nandeha teo alohanareo anefa izy teny an-dalana, mba hitady toerana hitobianareo. nasehony hoe teo aminareo izy, ka afo no nampiasainy rehefa alina ary rahona rehefa antoandro, amin’izay dia hitanareo ny lalana tokony halehanareo.'),
  ('6aadc74015b0abb57fb22d31', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 22, '“Nanatona ahy daholo anefa ianareo, ka niteny hoe: ‘Andao isika haniraka olona handeha mialoha antsika. Dia hasaintsika hijery taratra an’ilay tany izy, ka hanao tatitra atỳ amintsika hoe aiza ny lalana tokony harahintsika ary tanàna hoatran’ny ahoana no ho hitantsika.’', '“nanatona ahy daholo anefa ianareo, ka niteny hoe: ‘andao isika haniraka olona handeha mialoha antsika. dia hasaintsika hijery taratra an’ilay tany izy, ka hanao tatitra atỳ amintsika hoe aiza ny lalana tokony harahintsika ary tanàna hoatran’ny ahoana no ho hitantsika.’'),
  ('6aadc74015b0abb57fb22d2e', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 19, '“Dia niala tany Horeba isika, araka ny didy nomen’i Jehovah Andriamanitsika, ka nandeha namakivaky an’ilay tany efitra lehibe sady mampahatahotra. Hitanareo io tany efitra io tamin’isika teny an-dalana ho any amin’ny faritra be tendrombohitra misy ny Amorita. Farany, dia tonga tao Kadesi-barnea isika.', '“dia niala tany horeba isika, araka ny didy nomen’i jehovah andriamanitsika, ka nandeha namakivaky an’ilay tany efitra lehibe sady mampahatahotra. hitanareo io tany efitra io tamin’isika teny an-dalana ho any amin’ny faritra be tendrombohitra misy ny amorita. farany, dia tonga tao kadesi-barnea isika.'),
  ('6aadc74015b0abb57fb22d2b', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 16, '“Izao no nampianariko ny mpitsaranareo tamin’izay: ‘Rehefa misy adin’ny rahalahinareo entiny eo aminareo, dia tsarao araka ny rariny izay manana ady amin’ny rahalahiny, na amin’ny vahiny miara-monina aminy.', '“izao no nampianariko ny mpitsaranareo tamin’izay: ‘rehefa misy adin’ny rahalahinareo entiny eo aminareo, dia tsarao araka ny rariny izay manana ady amin’ny rahalahiny, na amin’ny vahiny miara-monina aminy.'),
  ('6aadc74015b0abb57fb22d22', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 7, 'Mandehana any amin’ny faritra be tendrombohitra misy ny Amorita sy ny faritra rehetra manodidina, izany hoe Araba sy ny faritra be tendrombohitra, Sefela, Negeba, ary ny morontsiraka. Mandehana any amin’ireo tanin’ny Kananita ireo, hatrany Libàna sy ilay renirano lehibe, dia ny reniranon’i Eofrata.', 'mandehana any amin’ny faritra be tendrombohitra misy ny amorita sy ny faritra rehetra manodidina, izany hoe araba sy ny faritra be tendrombohitra, sefela, negeba, ary ny morontsiraka. mandehana any amin’ireo tanin’ny kananita ireo, hatrany libàna sy ilay renirano lehibe, dia ny reniranon’i eofrata.'),
  ('6aadc74015b0abb57fb22d42', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 39, 'Ary ny zanakareo izay nolazainareo hoe ho lasa babo, sy ny zanakareo izay mbola tsy mahalala ny tsara sy ny ratsy akory, dia ireo no hiditra any. Homeko an-dry zareo ilay tany, ka ho lasany.', 'ary ny zanakareo izay nolazainareo hoe ho lasa babo, sy ny zanakareo izay mbola tsy mahalala ny tsara sy ny ratsy akory, dia ireo no hiditra any. homeko an-dry zareo ilay tany, ka ho lasany.'),
  ('6aadc74015b0abb57fb22d1f', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 4, 'Tamin’izay i Mosesy efa avy nandresy an’i Sihona mpanjakan’ny Amorita, ilay nipetraka tany Hesbona, sy Oga mpanjakan’i Basana, ilay nipetraka tany Astarota, tany Edrehy.', 'tamin’izay i mosesy efa avy nandresy an’i sihona mpanjakan’ny amorita, ilay nipetraka tany hesbona, sy oga mpanjakan’i basana, ilay nipetraka tany astarota, tany edrehy.'),
  ('6aadc74015b0abb57fb22d1c', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 1, 'Ireto ny tenin’i Mosesy tamin’ny Israely rehetra tao amin’ny faritr’i Jordana, tany an-tany efitra, teny amin’ny lemaka karakaina tandrifin’i Sofa, anelanelan’i Parana, Tofela, Labana, Hazerota, ary Dizahaba.', 'ireto ny tenin’i mosesy tamin’ny israely rehetra tao amin’ny faritr’i jordana, tany an-tany efitra, teny amin’ny lemaka karakaina tandrifin’i sofa, anelanelan’i parana, tofela, labana, hazerota, ary dizahaba.'),
  ('6aadc74015b0abb57fb22d43', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 40, 'Fa ianareo kosa, miverena dia mankanesa any an-tany efitra, ka ilay lalana mankany amin’ny Ranomasina Mena no araho.’', 'fa ianareo kosa, miverena dia mankanesa any an-tany efitra, ka ilay lalana mankany amin’ny ranomasina mena no araho.’'),
  ('6aadc74015b0abb57fb22d32', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 23, 'Dia hitako hoe tsara ilay hevitra, ka nifidy 12 lahy teo aminareo aho, izany hoe iray isaky ny foko.', 'dia hitako hoe tsara ilay hevitra, ka nifidy 12 lahy teo aminareo aho, izany hoe iray isaky ny foko.'),
  ('6aadc74015b0abb57fb22d2d', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 18, 'Natoroko anareo daholo koa tamin’izay ny zavatra rehetra tokony hataonareo.', 'natoroko anareo daholo koa tamin’izay ny zavatra rehetra tokony hataonareo.'),
  ('6aadc74015b0abb57fb22d1e', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 3, 'Tamin’ny andro voalohan’ny volana faha-11, tamin’ny taona faha-40, dia nolazain’i Mosesy tamin’ny Israelita izay rehetra nasain’i Jehovah nolazaina tamin’izy ireo.', 'tamin’ny andro voalohan’ny volana faha-11, tamin’ny taona faha-40, dia nolazain’i mosesy tamin’ny israelita izay rehetra nasain’i jehovah nolazaina tamin’izy ireo.'),
  ('6aadc74015b0abb57fb22d48', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 45, 'Koa niverina ianareo ka nitomany teo anatrehan’i Jehovah. Tsy nihaino anareo anefa i Jehovah sady tsy niraharaha anareo.', 'koa niverina ianareo ka nitomany teo anatrehan’i jehovah. tsy nihaino anareo anefa i jehovah sady tsy niraharaha anareo.'),
  ('6aadc74015b0abb57fb22d44', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 41, '“Dia hoy ianareo tamiko: ‘Efa nanota tamin’i Jehovah izahay. Hiakatra hiady izao izahay, araka ny baiko nomen’i Jehovah Andriamanitsika!’ Dia samy nitondra ny fitaovam-piadianareo avy ianareo, ary nieritreritra hoe ho mora ny hiakatra an’ilay tendrombohitra.', '“dia hoy ianareo tamiko: ‘efa nanota tamin’i jehovah izahay. hiakatra hiady izao izahay, araka ny baiko nomen’i jehovah andriamanitsika!’ dia samy nitondra ny fitaovam-piadianareo avy ianareo, ary nieritreritra hoe ho mora ny hiakatra an’ilay tendrombohitra.'),
  ('6aadc74015b0abb57fb22d41', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 38, 'fa i Josoa zanak’i Nona, izay mitsangana eo anatrehanao, no hiditra any.’ Ampaherezo izy, fa izy no hitarika ny Israely handova an’ilay tany.”', 'fa i josoa zanak’i nona, izay mitsangana eo anatrehanao, no hiditra any.’ ampaherezo izy, fa izy no hitarika ny israely handova an’ilay tany.”'),
  ('6aadc74015b0abb57fb22d38', '2026-09-18T23:20:32.605Z', '2026-09-18T23:20:32.605Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 1, 29, '“Dia hoy aho taminareo: ‘Aza mihorohoro noho ny aminy na matahotra azy.', '“dia hoy aho taminareo: ‘aza mihorohoro noho ny aminy na matahotra azy.'),
  ('6aadc7417369b9bab60fbe40', '2026-09-18T23:20:33.319Z', '2026-09-18T23:20:33.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 4, 'Ary lazao amin’ny vahoaka ilay didy hoe: “Izao ianareo dia handalo any akaikin’ny sisin-tanin’ny rahalahinareo, dia ny taranak’i Esao, izay mipetraka any Seira. Hatahotra anareo izy ireo, nefa mitandrema tsara.', 'ary lazao amin’ny vahoaka ilay didy hoe: “izao ianareo dia handalo any akaikin’ny sisin-tanin’ny rahalahinareo, dia ny taranak’i esao, izay mipetraka any seira. hatahotra anareo izy ireo, nefa mitandrema tsara.'),
  ('6aadc7417369b9bab60fbe41', '2026-09-18T23:20:33.319Z', '2026-09-18T23:20:33.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 5, 'Aza mila ady aminy, fa tsy hisy homeko anareo ny taniny na dia eram-paladia aza. Efa nomeko ho an’i Esao mantsy ny Tendrombohitra Seira.', 'aza mila ady aminy, fa tsy hisy homeko anareo ny taniny na dia eram-paladia aza. efa nomeko ho an’i esao mantsy ny tendrombohitra seira.'),
  ('6aadc7417369b9bab60fbe3e', '2026-09-18T23:20:33.319Z', '2026-09-18T23:20:33.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 2, 'Dia hoy i Jehovah tamiko:', 'dia hoy i jehovah tamiko:'),
  ('6aadc7417369b9bab60fbe42', '2026-09-18T23:20:33.319Z', '2026-09-18T23:20:33.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 6, 'Tokony haloanareo vola izay sakafo hohaninareo, ary tokony hovidinareo aminy koa ny rano hosotroinareo.', 'tokony haloanareo vola izay sakafo hohaninareo, ary tokony hovidinareo aminy koa ny rano hosotroinareo.'),
  ('6aadc7417369b9bab60fbe3f', '2026-09-18T23:20:33.319Z', '2026-09-18T23:20:33.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 3, '‘Efa ela izay ianareo no nandeha nanodidina an’io tendrombohitra io, ka mandehana mianavaratra.', '‘efa ela izay ianareo no nandeha nanodidina an’io tendrombohitra io, ka mandehana mianavaratra.'),
  ('6aadc7417369b9bab60fbe3d', '2026-09-18T23:20:33.319Z', '2026-09-18T23:20:33.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 1, '“Dia nivily nankany an-tany efitra isika. Ny lalana mankany amin’ny Ranomasina Mena no narahintsika, araka ny tenin’i Jehovah tamiko. Ary nandeha teny amin’ny manodidina ny Tendrombohitra Seira isika, nandritra ny andro maro.', '“dia nivily nankany an-tany efitra isika. ny lalana mankany amin’ny ranomasina mena no narahintsika, araka ny tenin’i jehovah tamiko. ary nandeha teny amin’ny manodidina ny tendrombohitra seira isika, nandritra ny andro maro.'),
  ('6aadc7417369b9bab60fbe50', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 20, 'Noheverin’ny olona hoe tanin’ny Refaima koa izy io. Ny Refaima mantsy taloha no nipetraka tao, ary nantsoin’ny Amonita hoe Zamzomita izy ireo.', 'noheverin’ny olona hoe tanin’ny refaima koa izy io. ny refaima mantsy taloha no nipetraka tao, ary nantsoin’ny amonita hoe zamzomita izy ireo.'),
  ('6aadc7417369b9bab60fbe45', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 9, 'Hoy i Jehovah tamiko avy eo: ‘Aza mila vaniny na miady amin’ny Moabita, fa tsy hisy homeko ho anareo ny taniny. Efa nomeko ho an’ny taranak’i Lota mantsy i Ara.', 'hoy i jehovah tamiko avy eo: ‘aza mila vaniny na miady amin’ny moabita, fa tsy hisy homeko ho anareo ny taniny. efa nomeko ho an’ny taranak’i lota mantsy i ara.'),
  ('6aadc7417369b9bab60fbe5c', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 32, 'Rehefa nivoaka hiady tamintsika tao Jahaza i Sihona sy ny vahoakany manontolo,', 'rehefa nivoaka hiady tamintsika tao jahaza i sihona sy ny vahoakany manontolo,'),
  ('6aadc7417369b9bab60fbe56', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 26, '“Ary naniraka olona avy any an-tany efitr’i Kedemota aho hankany amin’i Sihona mpanjakan’i Hesbona, mba hiteny aminy hoe mitady fihavanana isika, ka hilaza hoe:', '“ary naniraka olona avy any an-tany efitr’i kedemota aho hankany amin’i sihona mpanjakan’i hesbona, mba hiteny aminy hoe mitady fihavanana isika, ka hilaza hoe:'),
  ('6aadc7417369b9bab60fbe58', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 28, 'Izay sakafo hamidinao amiko ihany no hohaniko, ary izay rano hamidinao amiko ihany no hosotroiko. Fa avelao fotsiny aho handalo ao amin’ny taninao.', 'izay sakafo hamidinao amiko ihany no hohaniko, ary izay rano hamidinao amiko ihany no hosotroiko. fa avelao fotsiny aho handalo ao amin’ny taninao.'),
  ('6aadc7417369b9bab60fbe48', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 12, 'Ny Horita no nipetraka tany Seira taloha. Naka ny tanin’izy ireo anefa ny taranak’i Esao dia nandringana azy. Dia ny taranak’i Esao indray no nipetraka tany, hoatran’ny hataon’ny Israely amin’ilay tany homen’i Jehovah ho azy ireo.', 'ny horita no nipetraka tany seira taloha. naka ny tanin’izy ireo anefa ny taranak’i esao dia nandringana azy. dia ny taranak’i esao indray no nipetraka tany, hoatran’ny hataon’ny israely amin’ilay tany homen’i jehovah ho azy ireo.'),
  ('6aadc7417369b9bab60fbe4b', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 15, 'Namely azy ireo ny tanan’i Jehovah mba handringanana azy, mandra-paharipany.', 'namely azy ireo ny tanan’i jehovah mba handringanana azy, mandra-paharipany.'),
  ('6aadc7417369b9bab60fbe44', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 8, 'Nandalo teny akaikin’ireo rahalahintsika àry isika, izany hoe teny akaikin’ny taranak’i Esao, izay mipetraka any Seira, ary nanalavitra an’ilay lalana mankany Araba sy Elata ary Eziona-gebera. “Dia nivily isika ka nandeha tamin’ny lalana mankany an-tany efitr’i Moaba.', 'nandalo teny akaikin’ireo rahalahintsika àry isika, izany hoe teny akaikin’ny taranak’i esao, izay mipetraka any seira, ary nanalavitra an’ilay lalana mankany araba sy elata ary eziona-gebera. “dia nivily isika ka nandeha tamin’ny lalana mankany an-tany efitr’i moaba.'),
  ('6aadc7417369b9bab60fbe5b', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 31, '“Dia hoy i Jehovah tamiko: ‘Efa nomeko anao i Sihona sy ny taniny. Koa alaivo ho anareo ny taniny.’', '“dia hoy i jehovah tamiko: ‘efa nomeko anao i sihona sy ny taniny. koa alaivo ho anareo ny taniny.’'),
  ('6aadc7417369b9bab60fbe55', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 25, 'Ary manomboka izao dia hataoko mihorohoro sy matahotra anao ny olona rehetra eny ambanin’ny lanitra, rehefa maheno ny momba anao. Dia hitebiteby sy hihorohoro izy ireo noho ny aminao.’', 'ary manomboka izao dia hataoko mihorohoro sy matahotra anao ny olona rehetra eny ambanin’ny lanitra, rehefa maheno ny momba anao. dia hitebiteby sy hihorohoro izy ireo noho ny aminao.’'),
  ('6aadc7417369b9bab60fbe43', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 7, 'Fa nitahy anareo i Jehovah Andriamanitrareo tamin’izay rehetra nataonareo. Fantany tsara fa nandeha namakivaky an’ity tany efitra lehibe ity ianareo. Nanampy anareo foana i Jehovah Andriamanitrareo nandritra an’izay 40 taona izay, ka tsy ory na inona na inona ianareo.”’', 'fa nitahy anareo i jehovah andriamanitrareo tamin’izay rehetra nataonareo. fantany tsara fa nandeha namakivaky an’ity tany efitra lehibe ity ianareo. nanampy anareo foana i jehovah andriamanitrareo nandritra an’izay 40 taona izay, ka tsy ory na inona na inona ianareo.”’'),
  ('6aadc7417369b9bab60fbe4e', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 18, '‘Izao ianao dia handalo ny faritr’i Moaba, izany hoe Ara.', '‘izao ianao dia handalo ny faritr’i moaba, izany hoe ara.'),
  ('6aadc7417369b9bab60fbe61', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 37, 'Ianao anefa tsy nanakaiky ny tanin’ny Amonita, dia ny sisiny rehetra amin’ny Lohasahan’i Jaboka, sy ireo tanàna ao amin’ny faritra be tendrombohitra. Tsy nanakaiky an’izay toerana nandraran’i Jehovah Andriamanitsika antsika koa ianao.', 'ianao anefa tsy nanakaiky ny tanin’ny amonita, dia ny sisiny rehetra amin’ny lohasahan’i jaboka, sy ireo tanàna ao amin’ny faritra be tendrombohitra. tsy nanakaiky an’izay toerana nandraran’i jehovah andriamanitsika antsika koa ianao.'),
  ('6aadc7417369b9bab60fbe54', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 24, '“‘Mitsangàna, dia mandehana miampita ny Lohasahan’i Arnona. Efa hataoko resinao i Sihona Amorita mpanjakan’i Hesbona. Dia alaivo ho anao ny taniny, ary miadia aminy.', '“‘mitsangàna, dia mandehana miampita ny lohasahan’i arnona. efa hataoko resinao i sihona amorita mpanjakan’i hesbona. dia alaivo ho anao ny taniny, ary miadia aminy.'),
  ('6aadc7417369b9bab60fbe4f', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 19, 'Rehefa mandalo eny akaikin’ny Amonita ianao, dia aza mila vaniny na mila ady aminy. Fa tsy hisy homeko ho anao ny taniny, satria efa nomeko ho an’ny taranak’i Lota izany.', 'rehefa mandalo eny akaikin’ny amonita ianao, dia aza mila vaniny na mila ady aminy. fa tsy hisy homeko ho anao ny taniny, satria efa nomeko ho an’ny taranak’i lota izany.'),
  ('6aadc7417369b9bab60fbe5e', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 34, 'Azontsika daholo ny tanànany tamin’izay fotoana izay, ka noravantsika tanteraka ny tanàna tsirairay, ary naringantsika ny lehilahy sy ny vehivavy ary ny ankizy. Tsy nasiantsika niangana izy ireo na iray aza.', 'azontsika daholo ny tanànany tamin’izay fotoana izay, ka noravantsika tanteraka ny tanàna tsirairay, ary naringantsika ny lehilahy sy ny vehivavy ary ny ankizy. tsy nasiantsika niangana izy ireo na iray aza.'),
  ('6aadc7417369b9bab60fbe52', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 22, 'Izany no nataon’Andriamanitra ho an’ny taranak’i Esao, izay mipetraka any Seira. Naringany tsy ho eo anatrehan’izy ireo mantsy ny Horita, dia amin’izay lasan’izy ireo ny taniny ka izy ireo indray no mipetraka any hatramin’izao.', 'izany no nataon’andriamanitra ho an’ny taranak’i esao, izay mipetraka any seira. naringany tsy ho eo anatrehan’izy ireo mantsy ny horita, dia amin’izay lasan’izy ireo ny taniny ka izy ireo indray no mipetraka any hatramin’izao.'),
  ('6aadc7417369b9bab60fbe4d', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 17, 'dia hoy indray i Jehovah tamiko:', 'dia hoy indray i jehovah tamiko:'),
  ('6aadc7417369b9bab60fbe4a', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 14, 'Ary naharitra 38 taona ny diantsika avy tany Kadesi-barnea ka hatramin’ny niampitantsika an’ilay Lohasahan’i Zareda. Nandeha teny foana isika mandra-paharipak’ilay taranaka manontolo, dia ny lehilahy mpiady rehetra tao an-toby, araka izay efa nianianan’i Jehovah taminy.', 'ary naharitra 38 taona ny diantsika avy tany kadesi-barnea ka hatramin’ny niampitantsika an’ilay lohasahan’i zareda. nandeha teny foana isika mandra-paharipak’ilay taranaka manontolo, dia ny lehilahy mpiady rehetra tao an-toby, araka izay efa nianianan’i jehovah taminy.'),
  ('6aadc7417369b9bab60fbe60', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 36, 'Nanomboka tany Aroera, eo amin’ny sisin’ny Lohasahan’i Arnona, sy ny tanàna eo amin’ilay lohasaha, ka hatrany Gileada, dia tsy nisy tanàna tsy resintsika. Nataon’i Jehovah Andriamanitsika resintsika daholo izy rehetra.', 'nanomboka tany aroera, eo amin’ny sisin’ny lohasahan’i arnona, sy ny tanàna eo amin’ilay lohasaha, ka hatrany gileada, dia tsy nisy tanàna tsy resintsika. nataon’i jehovah andriamanitsika resintsika daholo izy rehetra.'),
  ('6aadc7417369b9bab60fbe59', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 29, 'Ny taranak’i Esao mipetraka any Seira sy ny Moabita any Ara koa mantsy namela ahy handalo tao amin’ny taniny, mandra-piampitako ny Reniranon’i Jordana mba ho any amin’ilay tany homen’ i Jehovah Andriamanitray anay.’', 'ny taranak’i esao mipetraka any seira sy ny moabita any ara koa mantsy namela ahy handalo tao amin’ny taniny, mandra-piampitako ny reniranon’i jordana mba ho any amin’ilay tany homen’ i jehovah andriamanitray anay.’'),
  ('6aadc7417369b9bab60fbe57', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 27, '‘Mba avelao aho handalo ao amin’ny taninao. Amin’ny lalambe ihany aho no handeha fa tsy hivily hiankavanana na hiankavia.', '‘mba avelao aho handalo ao amin’ny taninao. amin’ny lalambe ihany aho no handeha fa tsy hivily hiankavanana na hiankavia.'),
  ('6aadc7417369b9bab60fbe47', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 11, 'Ny Refaima koa hoatran’ny Anakita, ka nantsoin’ny Moabita hoe Emima.', 'ny refaima koa hoatran’ny anakita, ka nantsoin’ny moabita hoe emima.'),
  ('6aadc7417369b9bab60fbe46', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 10, 'Ny Emima no nipetraka tany taloha. Natanjaka izy ireo sady be dia be, ary lava ranjanana hoatran’ny Anakita.', 'ny emima no nipetraka tany taloha. natanjaka izy ireo sady be dia be, ary lava ranjanana hoatran’ny anakita.'),
  ('6aadc7417369b9bab60fbe4c', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 16, '“Rehefa maty daholo ny lehilahy mpiady rehetra teo amin’ny vahoaka,', '“rehefa maty daholo ny lehilahy mpiady rehetra teo amin’ny vahoaka,'),
  ('6aadc7417369b9bab60fbe5f', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 35, 'Ny biby fiompy sy ny fananana ihany no nalaintsika ho babo tao amin’ireo tanàna resintsika.', 'ny biby fiompy sy ny fananana ihany no nalaintsika ho babo tao amin’ireo tanàna resintsika.'),
  ('6aadc7417369b9bab60fbe5d', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 33, 'dia nataon’i Jehovah Andriamanitsika resintsika ry zareo. Dia resintsika izy sy ny zanany ary ny vahoakany manontolo.', 'dia nataon’i jehovah andriamanitsika resintsika ry zareo. dia resintsika izy sy ny zanany ary ny vahoakany manontolo.'),
  ('6aadc7417369b9bab60fbe5a', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 30, 'Tsy namela antsika handalo tao amin’ny taniny anefa i Sihona mpanjakan’i Hesbona. Navelan’i Jehovah Andriamanitrareo hiziriziry amin’ny heviny sy hanamafy ny fony mantsy izy, satria tiany ho resinao. Dia izany tokoa izao no mitranga.', 'tsy namela antsika handalo tao amin’ny taniny anefa i sihona mpanjakan’i hesbona. navelan’i jehovah andriamanitrareo hiziriziry amin’ny heviny sy hanamafy ny fony mantsy izy, satria tiany ho resinao. dia izany tokoa izao no mitranga.'),
  ('6aadc7417369b9bab60fbe51', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 21, 'Natanjaka sady be dia be izy ireo, ary lava ranjanana hoatran’ny Anakita. Naringan’i Jehovah tsy ho eo anatrehan’ny Amonita anefa ry zareo. Koa noroahin’ny Amonita izy ireny, ary ny Amonita indray no nipetraka teo amin’ny taniny.', 'natanjaka sady be dia be izy ireo, ary lava ranjanana hoatran’ny anakita. naringan’i jehovah tsy ho eo anatrehan’ny amonita anefa ry zareo. koa noroahin’ny amonita izy ireny, ary ny amonita indray no nipetraka teo amin’ny taniny.'),
  ('6aadc7417369b9bab60fbe53', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 23, 'Ny Avita kosa nipetraka tao amin’ny tanàna kely hatrany Gaza. Nandringana azy ireo anefa ny Kaftorima avy tany Kaftora, ka izy ireo indray no nipetraka tao amin’ny tanànany.', 'ny avita kosa nipetraka tao amin’ny tanàna kely hatrany gaza. nandringana azy ireo anefa ny kaftorima avy tany kaftora, ka izy ireo indray no nipetraka tao amin’ny tanànany.'),
  ('6aadc7417369b9bab60fbe49', '2026-09-18T23:20:33.320Z', '2026-09-18T23:20:33.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 2, 13, 'Mandehana àry miampita ny Lohasahan’i Zareda.’ Koa niampita an’ilay lohasaha isika.', 'mandehana àry miampita ny lohasahan’i zareda.’ koa niampita an’ilay lohasaha isika.'),
  ('6aadc7412e0f4660d9d7b0db', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 23, '“Dia nitalaho tamin’i Jehovah aho tamin’izay hoe:', '“dia nitalaho tamin’i jehovah aho tamin’izay hoe:'),
  ('6aadc7412e0f4660d9d7b0ca', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 6, 'Naringantsika tanteraka anefa ireny, toy ny nataontsika tamin’i Sihona mpanjakan’i Hesbona. Noravantsika tanteraka mantsy ny tanànany rehetra, ary naringantsika ny lehilahy sy ny vehivavy ary ny ankizy.', 'naringantsika tanteraka anefa ireny, toy ny nataontsika tamin’i sihona mpanjakan’i hesbona. noravantsika tanteraka mantsy ny tanànany rehetra, ary naringantsika ny lehilahy sy ny vehivavy ary ny ankizy.'),
  ('6aadc7412e0f4660d9d7b0d4', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 16, 'Nomeko ho an’ny Robenita sy ny Gadita kosa ny faritra manomboka eo Gileada ka hatreo amin’ny Lohasahan’i Arnona, ary eo afovoan’ilay lohasaha ny sisin-tany. Nomeko azy ireo koa ilay faritra hatrany Jaboka, ilay lohasaha izay sisin-tanin’ny Amonita.', 'nomeko ho an’ny robenita sy ny gadita kosa ny faritra manomboka eo gileada ka hatreo amin’ny lohasahan’i arnona, ary eo afovoan’ilay lohasaha ny sisin-tany. nomeko azy ireo koa ilay faritra hatrany jaboka, ilay lohasaha izay sisin-tanin’ny amonita.'),
  ('6aadc7412e0f4660d9d7b0d7', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 19, 'Ny vadinareo sy ny zanakareo ary ny biby fiompinareo ihany no hijanona ao amin’ireo tanàna nomeko anareo—fantatro tsara fa maro be ny biby fiompinareo—', 'ny vadinareo sy ny zanakareo ary ny biby fiompinareo ihany no hijanona ao amin’ireo tanàna nomeko anareo—fantatro tsara fa maro be ny biby fiompinareo—'),
  ('6aadc7412e0f4660d9d7b0ce', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 10, 'Nalaintsika daholo koa ny tanàna teny amin’ny lembalemba sy nanerana an’i Gileada sy Basana, hatrany Saleka sy Edrehy, izay tanàna tao amin’ny fanjakan’i Oga tany Basana.', 'nalaintsika daholo koa ny tanàna teny amin’ny lembalemba sy nanerana an’i gileada sy basana, hatrany saleka sy edrehy, izay tanàna tao amin’ny fanjakan’i oga tany basana.'),
  ('6aadc7412e0f4660d9d7b0cc', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 8, '“Tamin’izay dia nalaintsika ny tanin’ireo mpanjakan’ny Amorita anankiroa tany amin’ny faritr’i Jordana, nanomboka teo amin’ny Lohasahan’i Arnona ka hatrany amin’ny Tendrombohitra Hermona.', '“tamin’izay dia nalaintsika ny tanin’ireo mpanjakan’ny amorita anankiroa tany amin’ny faritr’i jordana, nanomboka teo amin’ny lohasahan’i arnona ka hatrany amin’ny tendrombohitra hermona.'),
  ('6aadc7412e0f4660d9d7b0c7', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 3, 'Dia nataon’i Jehovah Andriamanitsika resintsika koa i Oga mpanjakan’i Basana sy ny tafiny manontolo. Dia nasiantsika ry zareo ka nataontsika tsy nisy niangana na iray aza.', 'dia nataon’i jehovah andriamanitsika resintsika koa i oga mpanjakan’i basana sy ny tafiny manontolo. dia nasiantsika ry zareo ka nataontsika tsy nisy niangana na iray aza.'),
  ('6aadc7412e0f4660d9d7b0cf', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 11, 'I Oga mpanjakan’i Basana no sisa tavela tamin’ny Refaima. Vita tamin’ny vy ilay filanjana ny fatiny, ary mbola ao Raba tanànan’ny Amonita ilay izy. Sivy hakiho ny lavan’izy io, ary efatra hakiho ny sakany, araka ny hakiho mahazatra.', 'i oga mpanjakan’i basana no sisa tavela tamin’ny refaima. vita tamin’ny vy ilay filanjana ny fatiny, ary mbola ao raba tanànan’ny amonita ilay izy. sivy hakiho ny lavan’izy io, ary efatra hakiho ny sakany, araka ny hakiho mahazatra.'),
  ('6aadc7412e0f4660d9d7b0d6', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 18, '“Dia nanome an’izao didy izao anareo aho: ‘Efa nomen’i Jehovah Andriamanitrareo anareo ity tany ity mba halainareo ho anareo. Handray ny fiadiany daholo ny lehilahy mahery fo eo aminareo, dia hiampita eo alohan’ny Israelita rahalahinareo.', '“dia nanome an’izao didy izao anareo aho: ‘efa nomen’i jehovah andriamanitrareo anareo ity tany ity mba halainareo ho anareo. handray ny fiadiany daholo ny lehilahy mahery fo eo aminareo, dia hiampita eo alohan’ny israelita rahalahinareo.'),
  ('6aadc7412e0f4660d9d7b0e0', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 28, 'Tendreo hisolo anao i Josoa ka ampaherezo sy hatanjaho, satria izy no hitarika an’ity vahoaka ity ho any amin’ilay tany, amin’izay izy ireo ho afaka handova azy io.’', 'tendreo hisolo anao i josoa ka ampaherezo sy hatanjaho, satria izy no hitarika an’ity vahoaka ity ho any amin’ilay tany, amin’izay izy ireo ho afaka handova azy io.’'),
  ('6aadc7412e0f4660d9d7b0da', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 22, 'Aza matahotra an-dry zareo, fa i Jehovah Andriamanitrareo no miady ho anareo.’', 'aza matahotra an-dry zareo, fa i jehovah andriamanitrareo no miady ho anareo.’'),
  ('6aadc7412e0f4660d9d7b0c8', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 4, 'Nalaintsika ny tanànany rehetra, ka azontsika daholo ireo tanàna 60 nanerana ny faritr’i Argoba, tao amin’ny fanjakan’i Oga tany Basana.', 'nalaintsika ny tanànany rehetra, ka azontsika daholo ireo tanàna 60 nanerana ny faritr’i argoba, tao amin’ny fanjakan’i oga tany basana.'),
  ('6aadc7412e0f4660d9d7b0d9', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 21, '“Nandidy an’i Josoa aho tamin’izay hoe: ‘Efa hitan’ny masonao izay rehetra nataon’i Jehovah Andriamanitrareo tamin’ireny mpanjaka roa ireny. Hataon’i Jehovah hoatr’izany koa izay fanjakana rehetra handalovanao.', '“nandidy an’i josoa aho tamin’izay hoe: ‘efa hitan’ny masonao izay rehetra nataon’i jehovah andriamanitrareo tamin’ireny mpanjaka roa ireny. hataon’i jehovah hoatr’izany koa izay fanjakana rehetra handalovanao.'),
  ('6aadc7412e0f4660d9d7b0d5', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 17, 'Ary nomeko azy ireo i Araba sy ny Reniranon’i Jordana sy ny morony, manomboka any Kinereta ka hatrany amin’ny Ranomasin’i Araba, dia ny Ranomasin-tsira eo am-pototry ny havoanan’i Pisga manandrify ny atsinanana.', 'ary nomeko azy ireo i araba sy ny reniranon’i jordana sy ny morony, manomboka any kinereta ka hatrany amin’ny ranomasin’i araba, dia ny ranomasin-tsira eo am-pototry ny havoanan’i pisga manandrify ny atsinanana.'),
  ('6aadc7412e0f4660d9d7b0d1', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 13, 'Nomeko ho an’ny antsasaky ny fokon’i Manase kosa ny ambiny amin’i Gileada sy ny faritr’i Basana manontolo, izay anisan’ny fanjakan’i Oga. Tanin’ny Refaima no nahafantarana ny faritr’i Argoba manontolo, izay anisan’i Basana.', 'nomeko ho an’ny antsasaky ny fokon’i manase kosa ny ambiny amin’i gileada sy ny faritr’i basana manontolo, izay anisan’ny fanjakan’i oga. tanin’ny refaima no nahafantarana ny faritr’i argoba manontolo, izay anisan’i basana.'),
  ('6aadc7412e0f4660d9d7b0c9', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 5, 'Tanàna voaro mafy misy manda avo sy vavahady misy bara hidiny daholo ireo, miaraka amin’ny tanàna kely be dia be tany ambanivohitra.', 'tanàna voaro mafy misy manda avo sy vavahady misy bara hidiny daholo ireo, miaraka amin’ny tanàna kely be dia be tany ambanivohitra.'),
  ('6aadc7412e0f4660d9d7b0dd', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 25, 'Mba avelao re aho hiampita dia hahita an’ilay tany tsara erỳ ampitan’i Jordana e, ilay faritra be tendrombohitra sady tsara tarehy, dia avy eo koa i Libàna!’', 'mba avelao re aho hiampita dia hahita an’ilay tany tsara erỳ ampitan’i jordana e, ilay faritra be tendrombohitra sady tsara tarehy, dia avy eo koa i libàna!’'),
  ('6aadc7412e0f4660d9d7b0d2', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 14, '“Nalain’i Jaira zanak’i Manase ny faritr’i Argoba manontolo hatrany amin’ny sisin-tanin’ny Gesorita sy ny Makatita. Ary nampitondrainy ny anarany ireny tanàna kely any Basana ireny, ka nantsoiny hoe Havota-jaira hatramin’izao.', '“nalain’i jaira zanak’i manase ny faritr’i argoba manontolo hatrany amin’ny sisin-tanin’ny gesorita sy ny makatita. ary nampitondrainy ny anarany ireny tanàna kely any basana ireny, ka nantsoiny hoe havota-jaira hatramin’izao.'),
  ('6aadc7412e0f4660d9d7b0d0', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 12, 'Tamin’izay dia nalaintsika ho antsika ilay tany, manomboka eo Aroera, eo akaikin’ny Lohasahan’i Arnona, sy ny antsasaky ny faritra be tendrombohitr’i Gileada. Nomeko ho an’ny Robenita sy ny Gadita ny tanàna tany.', 'tamin’izay dia nalaintsika ho antsika ilay tany, manomboka eo aroera, eo akaikin’ny lohasahan’i arnona, sy ny antsasaky ny faritra be tendrombohitr’i gileada. nomeko ho an’ny robenita sy ny gadita ny tanàna tany.'),
  ('6aadc7412e0f4660d9d7b0cd', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 9, 'Io ilay tendrombohitra nantsoin’ny Sidonianina hoe Siriona, fa nantsoin’ny Amorita kosa hoe Senira.', 'io ilay tendrombohitra nantsoin’ny sidonianina hoe siriona, fa nantsoin’ny amorita kosa hoe senira.'),
  ('6aadc7412e0f4660d9d7b0df', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 27, 'Miakara eny an-tampon’i Pisga, ary mijere miankandrefana sy mianavaratra ary mianatsimo sy miantsinanana, dia jereo ilay tany, satria tsy hiampita an’io Jordana io ianao.', 'miakara eny an-tampon’i pisga, ary mijere miankandrefana sy mianavaratra ary mianatsimo sy miantsinanana, dia jereo ilay tany, satria tsy hiampita an’io jordana io ianao.'),
  ('6aadc7412e0f4660d9d7b0cb', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 7, 'Nalaintsika daholo koa ny biby fiompy sy ny fananana tao amin’ireo tanàna ireo.', 'nalaintsika daholo koa ny biby fiompy sy ny fananana tao amin’ireo tanàna ireo.'),
  ('6aadc7412e0f4660d9d7b0e1', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 29, 'Tamin’isika nipetraka tany amin’ilay lohasaha tandrifin’i Beti-peora no nitranga izany rehetra izany.', 'tamin’isika nipetraka tany amin’ilay lohasaha tandrifin’i beti-peora no nitranga izany rehetra izany.'),
  ('6aadc7412e0f4660d9d7b0d8', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 20, 'mandra-pahazon’ny rahalahinareo an’ilay tany homen’i Jehovah Andriamanitrareo azy eny ampitan’i Jordana. Hataon’i Jehovah milamina ny fiainan’izy ireo amin’izay, hoatran’ny nataony taminareo ihany. Aorian’izay ianareo vao hiverina any amin’ny tany efa nomeko anareo avy.’', 'mandra-pahazon’ny rahalahinareo an’ilay tany homen’i jehovah andriamanitrareo azy eny ampitan’i jordana. hataon’i jehovah milamina ny fiainan’izy ireo amin’izay, hoatran’ny nataony taminareo ihany. aorian’izay ianareo vao hiverina any amin’ny tany efa nomeko anareo avy.’'),
  ('6aadc7412e0f4660d9d7b0c6', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 2, 'Hoy àry i Jehovah tamiko: ‘Aza matahotra azy fa hataoko resinao izy sy ny tafiny manontolo ary homeko anao ny taniny. Hataonao hoatran’i Sihona izy, dia ilay mpanjakan’ny Amorita nipetraka tao Hesbona.’', 'hoy àry i jehovah tamiko: ‘aza matahotra azy fa hataoko resinao izy sy ny tafiny manontolo ary homeko anao ny taniny. hataonao hoatran’i sihona izy, dia ilay mpanjakan’ny amorita nipetraka tao hesbona.’'),
  ('6aadc7412e0f4660d9d7b0de', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 26, 'Mbola tezitra tamiko foana anefa i Jehovah noho ny nataonareo, ka tsy nety nihaino ahy. Fa hoy i Jehovah tamiko: ‘Aoka izay! Aza miresaka amiko momba an’izany intsony.', 'mbola tezitra tamiko foana anefa i jehovah noho ny nataonareo, ka tsy nety nihaino ahy. fa hoy i jehovah tamiko: ‘aoka izay! aza miresaka amiko momba an’izany intsony.'),
  ('6aadc7412e0f4660d9d7b0dc', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 24, '‘Ry Jehovah Tompo Fara Tampony ô! Efa nanomboka nasehonao tamin’ny mpanomponao hoe tena miavaka ianao sady manana sandry mahery. Fa iza no andriamanitra mahavita an’ireny asa lehibe vitanao ireny, na any an-danitra na etỳ an-tany?', '‘ry jehovah tompo fara tampony ô! efa nanomboka nasehonao tamin’ny mpanomponao hoe tena miavaka ianao sady manana sandry mahery. fa iza no andriamanitra mahavita an’ireny asa lehibe vitanao ireny, na any an-danitra na etỳ an-tany?'),
  ('6aadc7412e0f4660d9d7b0d3', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 15, 'Ary nomeko an’i Makira i Gileada.', 'ary nomeko an’i makira i gileada.'),
  ('6aadc7412e0f4660d9d7b0c5', '2026-09-18T23:20:33.876Z', '2026-09-18T23:20:33.876Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 3, 1, '“Nivily lalana isika avy eo, ka niakatra nanaraka an’ilay Lalan’i Basana. Dia nivoaka hiady tamintsika tao Edrehy i Oga mpanjakan’i Basana sy ny tafiny manontolo.', '“nivily lalana isika avy eo, ka niakatra nanaraka an’ilay lalan’i basana. dia nivoaka hiady tamintsika tao edrehy i oga mpanjakan’i basana sy ny tafiny manontolo.'),
  ('6aadc74245d2a85474eb25de', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 17, 'na sarim-biby eto an-tany, na sarim-borona manidina eny amin’ny lanitra,', 'na sarim-biby eto an-tany, na sarim-borona manidina eny amin’ny lanitra,'),
  ('6aadc74245d2a85474eb25d2', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 5, 'Efa nampianariko fitsipika sy didim-pitsarana ianareo, araka ny didy nomen’i Jehovah Andriamanitro ahy, amin’izay dia hankatò an’ireny ianareo any amin’ilay tany halainareo ho anareo.', 'efa nampianariko fitsipika sy didim-pitsarana ianareo, araka ny didy nomen’i jehovah andriamanitro ahy, amin’izay dia hankatò an’ireny ianareo any amin’ilay tany halainareo ho anareo.'),
  ('6aadc74245d2a85474eb25d1', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 4, 'Fa mbola velona daholo kosa izao ianareo izay mifikitra amin’i Jehovah Andriamanitrareo.', 'fa mbola velona daholo kosa izao ianareo izay mifikitra amin’i jehovah andriamanitrareo.'),
  ('6aadc74245d2a85474eb25dd', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 16, 'sao manao ratsy ianareo, izany hoe manao sary sokitra ho anareo, na sarin’inona izany na sarin’inona, na sarin-dehilahy na sarim-behivavy,', 'sao manao ratsy ianareo, izany hoe manao sary sokitra ho anareo, na sarin’inona izany na sarin’inona, na sarin-dehilahy na sarim-behivavy,'),
  ('6aadc74245d2a85474eb25d6', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 9, '“Fa mitandrema fotsiny, dia tandremo tsara sao hadinoinao ny zavatra efa hitan’ny masonao, ary sao hiala ao am-ponao izany mandritra ny androm-piainanao. Ampahafantaro ny zanakao sy ny zafinao koa izany.', '“fa mitandrema fotsiny, dia tandremo tsara sao hadinoinao ny zavatra efa hitan’ny masonao, ary sao hiala ao am-ponao izany mandritra ny androm-piainanao. ampahafantaro ny zanakao sy ny zafinao koa izany.'),
  ('6aadc74245d2a85474eb25ce', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 1, '“Henoy, ry Israely, ny fitsipika sy ny didim-pitsarana ampianariko anareo, dia ankatoavy. Amin’izay ho velona ianareo, ka hiditra ao amin’ilay tany homen’i Jehovah Andriamanitry ny razambenareo anareo, ary haka an’izany ho anareo.', '“henoy, ry israely, ny fitsipika sy ny didim-pitsarana ampianariko anareo, dia ankatoavy. amin’izay ho velona ianareo, ka hiditra ao amin’ilay tany homen’i jehovah andriamanitry ny razambenareo anareo, ary haka an’izany ho anareo.'),
  ('6aadc74245d2a85474eb25d4', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 7, 'Fa iza no firenena lehibe manana andriamanitra akaiky azy, hoatran’i Jehovah Andriamanitsika izay akaiky antsika ka mamaly antsika isaky ny miantso azy isika?', 'fa iza no firenena lehibe manana andriamanitra akaiky azy, hoatran’i jehovah andriamanitsika izay akaiky antsika ka mamaly antsika isaky ny miantso azy isika?'),
  ('6aadc74245d2a85474eb25d7', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 10, 'Fa tamin’ianao nijoro teo anatrehan’i Jehovah Andriamanitrao tany Horeba, dia hoy i Jehovah tamiko: ‘Vorio ho etỳ amiko ny vahoaka fa tiako hihaino ny teniko, mba hianarany hatahotra ahy mandritra ny andro rehetra hiainany eo amin’ilay tany, ary mba hampianarany ny zanany.’', 'fa tamin’ianao nijoro teo anatrehan’i jehovah andriamanitrao tany horeba, dia hoy i jehovah tamiko: ‘vorio ho etỳ amiko ny vahoaka fa tiako hihaino ny teniko, mba hianarany hatahotra ahy mandritra ny andro rehetra hiainany eo amin’ilay tany, ary mba hampianarany ny zanany.’'),
  ('6aadc74245d2a85474eb25d3', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 6, 'Araho tsara ireny, satria izany no hahitan’ny firenen-kafa hoe hendry sy mahira-tsaina ianareo. Haheno an’ireny fitsipika rehetra ireny mantsy ry zareo, dia hiteny hoe: ‘Ary tena hendry sy mahira-tsaina io firenena lehibe io!’', 'araho tsara ireny, satria izany no hahitan’ny firenen-kafa hoe hendry sy mahira-tsaina ianareo. haheno an’ireny fitsipika rehetra ireny mantsy ry zareo, dia hiteny hoe: ‘ary tena hendry sy mahira-tsaina io firenena lehibe io!’'),
  ('6aadc74245d2a85474eb25d8', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 11, '“Dia nanatona ianareo, ka nitsangana teo am-pototry ny tendrombohitra. Ary nirehitra ilay tendrombohitra, ka nisy afo nanakatra ny lanitra, sady nisy haizina sy rahona ary haizim-pito.', '“dia nanatona ianareo, ka nitsangana teo am-pototry ny tendrombohitra. ary nirehitra ilay tendrombohitra, ka nisy afo nanakatra ny lanitra, sady nisy haizina sy rahona ary haizim-pito.'),
  ('6aadc74245d2a85474eb25d5', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 8, 'Ary iza no firenena lehibe manana fitsipika sy didim-pitsarana marina hoatran’ilay Lalàna manontolo omeko anareo anio?', 'ary iza no firenena lehibe manana fitsipika sy didim-pitsarana marina hoatran’ilay lalàna manontolo omeko anareo anio?'),
  ('6aadc74245d2a85474eb25d0', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 3, '“Ny masonareo mihitsy no nahita an’izay nataon’i Jehovah tamin’ny olona rehetra nanaraka an’i Balan’i Peora. Naringan’i Jehovah Andriamanitrareo teo aminareo daholo ry zareo.', '“ny masonareo mihitsy no nahita an’izay nataon’i jehovah tamin’ny olona rehetra nanaraka an’i balan’i peora. naringan’i jehovah andriamanitrareo teo aminareo daholo ry zareo.'),
  ('6aadc74245d2a85474eb25dc', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 15, '“Tamin’ilay andro niresahan’i Jehovah taminareo avy tao anaty afo, tany Horeba, dia tsy nahita ny endriny ianareo. Koa mitandrema tsara', '“tamin’ilay andro niresahan’i jehovah taminareo avy tao anaty afo, tany horeba, dia tsy nahita ny endriny ianareo. koa mitandrema tsara'),
  ('6aadc74245d2a85474eb25db', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 14, 'Dia nasain’i Jehovah nampianatra anareo fitsipika sy didim-pitsarana aho tamin’izay. Tokony hankatoavinareo ireny, any amin’ilay tany halehanareo sy halainareo ho anareo.', 'dia nasain’i jehovah nampianatra anareo fitsipika sy didim-pitsarana aho tamin’izay. tokony hankatoavinareo ireny, any amin’ilay tany halehanareo sy halainareo ho anareo.'),
  ('6aadc74245d2a85474eb25cf', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 2, 'Aza anampiana ny teny andidiako anareo ary aza analana, fa araho tsara ny didin’i Jehovah Andriamanitrareo izay andidiako anareo.', 'aza anampiana ny teny andidiako anareo ary aza analana, fa araho tsara ny didin’i jehovah andriamanitrareo izay andidiako anareo.'),
  ('6aadc74245d2a85474eb25da', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 13, 'Ary nolazainy taminareo ilay fifanekena nasainy harahinareo, dia ny Didy Folo. Nosoratany teo amin’ny takela-bato roa ilay izy avy eo.', 'ary nolazainy taminareo ilay fifanekena nasainy harahinareo, dia ny didy folo. nosoratany teo amin’ny takela-bato roa ilay izy avy eo.'),
  ('6aadc74245d2a85474eb25d9', '2026-09-18T23:20:34.319Z', '2026-09-18T23:20:34.319Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 12, 'Dia niteny taminareo avy tao anaty afo i Jehovah, ka naheno feo ianareo saingy tsy nahita an’ilay niteny. Feo ihany no henonareo.', 'dia niteny taminareo avy tao anaty afo i jehovah, ka naheno feo ianareo saingy tsy nahita an’ilay niteny. feo ihany no henonareo.'),
  ('6aadc74245d2a85474eb25fc', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 47, 'Ary nalain’izy ireo ny tanin’i Sihona sy ny tanin’i Oga mpanjakan’i Basana, dia ny mpanjakan’ny Amorita anankiroa, tany amin’ny faritra atsinanan’i Jordana,', 'ary nalain’izy ireo ny tanin’i sihona sy ny tanin’i oga mpanjakan’i basana, dia ny mpanjakan’ny amorita anankiroa, tany amin’ny faritra atsinanan’i jordana,'),
  ('6aadc74245d2a85474eb25f1', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 36, 'Nataony henonareo avy any an-danitra ny feony mba hanitsiana anareo. Ary nasehony anareo teto an-tany ny afo miredareda, dia henonareo avy tao anatin’ilay afo ny teniny.', 'nataony henonareo avy any an-danitra ny feony mba hanitsiana anareo. ary nasehony anareo teto an-tany ny afo miredareda, dia henonareo avy tao anatin’ilay afo ny teniny.'),
  ('6aadc74245d2a85474eb25e5', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 24, 'Fa afo mandevona i Jehovah Andriamanitrareo, ilay Andriamanitra mitaky ny hanompoana azy irery ihany.', 'fa afo mandevona i jehovah andriamanitrareo, ilay andriamanitra mitaky ny hanompoana azy irery ihany.'),
  ('6aadc74245d2a85474eb25e1', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 20, 'Fa ianareo no nalain’i Jehovah sy nentiny nivoaka avy tao amin’ilay fatana fandrendrehana vy, izany hoe avy tany Ejipta, mba ho lasa fananany manokana hoatr’izao androany izao.', 'fa ianareo no nalain’i jehovah sy nentiny nivoaka avy tao amin’ilay fatana fandrendrehana vy, izany hoe avy tany ejipta, mba ho lasa fananany manokana hoatr’izao androany izao.'),
  ('6aadc74245d2a85474eb25e4', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 23, 'Tandremo sao hadinoinareo ilay fifanekena nataon’i Jehovah Andriamanitrareo taminareo. Aza manao sary sokitra ho anareo, dia zavatra mitovy bika amin’ireo zavatra nandraran’i Jehovah Andriamanitrareo anareo ireo.', 'tandremo sao hadinoinareo ilay fifanekena nataon’i jehovah andriamanitrareo taminareo. aza manao sary sokitra ho anareo, dia zavatra mitovy bika amin’ireo zavatra nandraran’i jehovah andriamanitrareo anareo ireo.'),
  ('6aadc74245d2a85474eb25ec', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 31, 'Fa Andriamanitra mamindra fo i Jehovah Andriamanitrao, ka tsy hahafoy anao na handringana anao na hanadino an’ilay fifanekena nianianany tamin’ny razambenao.', 'fa andriamanitra mamindra fo i jehovah andriamanitrao, ka tsy hahafoy anao na handringana anao na hanadino an’ilay fifanekena nianianany tamin’ny razambenao.'),
  ('6aadc74245d2a85474eb25f9', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 44, 'Ary izao no Lalàna napetrak’i Mosesy teo anatrehan’ny vahoakan’Israely.', 'ary izao no lalàna napetrak’i mosesy teo anatrehan’ny vahoakan’israely.'),
  ('6aadc74245d2a85474eb25e2', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 21, '“Tezitra tamiko i Jehovah noho ny nataonareo, ka nianiana hoe tsy hiampita an’i Jordana aho, na hiditra ao amin’ilay tany tsara homen’i Jehovah Andriamanitrareo anareo ho lovanareo.', '“tezitra tamiko i jehovah noho ny nataonareo, ka nianiana hoe tsy hiampita an’i jordana aho, na hiditra ao amin’ilay tany tsara homen’i jehovah andriamanitrareo anareo ho lovanareo.'),
  ('6aadc74245d2a85474eb25f3', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 38, 'Noroahiny niala teo anatrehanao izay firenena lehibe sy matanjaka noho ianao. Amin’izay ianao no hampidirina ao amin’ny tanin’izy ireo, ka homeny anao ilay izy mba ho lovanao, hoatr’izao androany izao.', 'noroahiny niala teo anatrehanao izay firenena lehibe sy matanjaka noho ianao. amin’izay ianao no hampidirina ao amin’ny tanin’izy ireo, ka homeny anao ilay izy mba ho lovanao, hoatr’izao androany izao.'),
  ('6aadc74245d2a85474eb25eb', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 30, 'Rehefa mitranga aminao daholo ireo zavatra voalaza rehetra ireo any aoriana any ka mafy be ny mahazo anao, dia hiverina amin’i Jehovah Andriamanitrao ianao ka hihaino ny feony.', 'rehefa mitranga aminao daholo ireo zavatra voalaza rehetra ireo any aoriana any ka mafy be ny mahazo anao, dia hiverina amin’i jehovah andriamanitrao ianao ka hihaino ny feony.'),
  ('6aadc74245d2a85474eb25e6', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 25, '“Raha miteraka sy manan-jafikely ianareo ka efa ela no nipetraka teo amin’ilay tany, nefa manao ratsy ka manao sary sokitra na sarin’inona izany na sarin’inona, ary manao izay ratsy eo imason’i Jehovah Andriamanitrareo ka mampahatezitra azy,', '“raha miteraka sy manan-jafikely ianareo ka efa ela no nipetraka teo amin’ilay tany, nefa manao ratsy ka manao sary sokitra na sarin’inona izany na sarin’inona, ary manao izay ratsy eo imason’i jehovah andriamanitrareo ka mampahatezitra azy,'),
  ('6aadc74245d2a85474eb25e3', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 22, 'Ho faty eto amin’ity tany ity mantsy aho fa tsy hiampita an’i Jordana. Fa ianareo no hiampita dia haka an’io tany tsara io ho anareo.', 'ho faty eto amin’ity tany ity mantsy aho fa tsy hiampita an’i jordana. fa ianareo no hiampita dia haka an’io tany tsara io ho anareo.'),
  ('6aadc74245d2a85474eb25f4', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 39, 'Fantaro àry dia ataovy ao am-ponao androany, fa i Jehovah no tena Andriamanitra any amin’ny lanitra ambony sy etỳ amin’ny tany ambany. Tsy misy afa-tsy izy.', 'fantaro àry dia ataovy ao am-ponao androany, fa i jehovah no tena andriamanitra any amin’ny lanitra ambony sy etỳ amin’ny tany ambany. tsy misy afa-tsy izy.'),
  ('6aadc74245d2a85474eb25ed', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 32, '“Tadidio ange ny andro taloha e, tamin’ianareo mbola tsy nisy, hatramin’ny andro namoronan’Andriamanitra ny olona teto an-tany! Mandehana mikaroka any amin’ny faravodilanitra iray ka hatrany amin’ny faravodilanitra iray. Angaha efa nisy zavatra miavaka be hoatr’izao, sa efa mba nisy naheno zavatra hoatr’izao?', '“tadidio ange ny andro taloha e, tamin’ianareo mbola tsy nisy, hatramin’ny andro namoronan’andriamanitra ny olona teto an-tany! mandehana mikaroka any amin’ny faravodilanitra iray ka hatrany amin’ny faravodilanitra iray. angaha efa nisy zavatra miavaka be hoatr’izao, sa efa mba nisy naheno zavatra hoatr’izao?'),
  ('6aadc74245d2a85474eb25f8', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 43, 'Ireto avy izany tanàna izany: I Bezera any an-tany efitra, eny amin’ny lembalemba, no ho an’ny Robenita. I Ramota any Gileada no ho an’ny Gadita. Ary i Golana any Basana no ho an’ny Manasita.', 'ireto avy izany tanàna izany: i bezera any an-tany efitra, eny amin’ny lembalemba, no ho an’ny robenita. i ramota any gileada no ho an’ny gadita. ary i golana any basana no ho an’ny manasita.'),
  ('6aadc74245d2a85474eb25ef', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 34, 'Sa Andriamanitra efa mba nanandrana naka firenena ho an’ny tenany avy tamin’ny firenena iray, ka namoaka didim-pitsarana sy nanao famantarana sy fahagagana ary niady, sady nampiasa ny tanany matanjaka sy ny sandriny mahery, ary nanao zavatra mampahatahotra? Efa nanao toy izany ve i Jehovah Andriamanitrareo, hoatran’ny nataony taminareo tany Ejipta teo imasonareo?', 'sa andriamanitra efa mba nanandrana naka firenena ho an’ny tenany avy tamin’ny firenena iray, ka namoaka didim-pitsarana sy nanao famantarana sy fahagagana ary niady, sady nampiasa ny tanany matanjaka sy ny sandriny mahery, ary nanao zavatra mampahatahotra? efa nanao toy izany ve i jehovah andriamanitrareo, hoatran’ny nataony taminareo tany ejipta teo imasonareo?'),
  ('6aadc74245d2a85474eb25ea', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 29, '“Raha mitady an’i Jehovah Andriamanitrao anefa ianao any, dia tena hahita azy tokoa raha mitady azy amin’ny fonao manontolo sy ny tenanao manontolo.', '“raha mitady an’i jehovah andriamanitrao anefa ianao any, dia tena hahita azy tokoa raha mitady azy amin’ny fonao manontolo sy ny tenanao manontolo.'),
  ('6aadc74245d2a85474eb25e9', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 28, 'Hanompo andriamanitra vato aman-kazo nataon’olona ianareo any, dia andriamanitra tsy mahita na maheno na mihinana na mandre fofona.', 'hanompo andriamanitra vato aman-kazo nataon’olona ianareo any, dia andriamanitra tsy mahita na maheno na mihinana na mandre fofona.'),
  ('6aadc74245d2a85474eb25e0', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 19, 'Ary rehefa mitraka mijery ny lanitra ianao ka mahita ny masoandro sy ny volana ary ny kintana, izany hoe izay rehetra eny amin’ny lanitra, dia tandremo sao miankohoka eo anatrehan’ireny sy manompo azy satria hoe manintona anao ireny. Nomen’i Jehovah Andriamanitrao ho an’ny firenena rehetra eny ambanin’ny lanitra manontolo mantsy ireny.', 'ary rehefa mitraka mijery ny lanitra ianao ka mahita ny masoandro sy ny volana ary ny kintana, izany hoe izay rehetra eny amin’ny lanitra, dia tandremo sao miankohoka eo anatrehan’ireny sy manompo azy satria hoe manintona anao ireny. nomen’i jehovah andriamanitrao ho an’ny firenena rehetra eny ambanin’ny lanitra manontolo mantsy ireny.'),
  ('6aadc74245d2a85474eb25fd', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 48, 'manomboka any Aroera, eo an-tsisin’ny Lohasahan’i Arnona, ka hatrany amin’ny Tendrombohitra Siona, izany hoe Hermona,', 'manomboka any aroera, eo an-tsisin’ny lohasahan’i arnona, ka hatrany amin’ny tendrombohitra siona, izany hoe hermona,'),
  ('6aadc74245d2a85474eb25f5', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 40, 'Araho ny fitsipiny sy ny didiny izay andidiako anao anio, mba handeha tsara foana ny fiainanao sy ny an’ny taranakao. Dia ho ela velona eo amin’ilay tany homen’i Jehovah Andriamanitrao anao ianao.”', 'araho ny fitsipiny sy ny didiny izay andidiako anao anio, mba handeha tsara foana ny fiainanao sy ny an’ny taranakao. dia ho ela velona eo amin’ilay tany homen’i jehovah andriamanitrao anao ianao.”'),
  ('6aadc74245d2a85474eb25ee', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 33, 'Efa nisy vahoaka naheno ny feon’Andriamanitra niteny avy tao anaty afo hoatr’ireny henonao ireny ve, ka mbola velona ihany?', 'efa nisy vahoaka naheno ny feon’andriamanitra niteny avy tao anaty afo hoatr’ireny henonao ireny ve, ka mbola velona ihany?'),
  ('6aadc74245d2a85474eb25fb', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 46, 'tany amin’ny faritr’i Jordana, teo amin’ilay lohasaha tandrifin’i Beti-peora, tao amin’ny tanin’i Sihona mpanjakan’ny Amorita izay nipetraka tao Hesbona, dia ilay resin’i Mosesy sy ny Israelita, rehefa tafavoaka avy tany Ejipta izy ireo.', 'tany amin’ny faritr’i jordana, teo amin’ilay lohasaha tandrifin’i beti-peora, tao amin’ny tanin’i sihona mpanjakan’ny amorita izay nipetraka tao hesbona, dia ilay resin’i mosesy sy ny israelita, rehefa tafavoaka avy tany ejipta izy ireo.'),
  ('6aadc74245d2a85474eb25f7', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 42, 'Raha misy olona mahafaty olona tsy nahy nefa tsy nankahala an’ilay olona talohan’izay, dia handositra any amin’ny iray amin’ireo tanàna ireo izy, ka ho velona.', 'raha misy olona mahafaty olona tsy nahy nefa tsy nankahala an’ilay olona talohan’izay, dia handositra any amin’ny iray amin’ireo tanàna ireo izy, ka ho velona.'),
  ('6aadc74245d2a85474eb25f2', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 37, '“Tiany ny razambenao ka nofidiny ny taranak’izy ireo. Dia nentiny nivoaka avy tany Ejipta teo anatrehany tamin-kery lehibe ianao.', '“tiany ny razambenao ka nofidiny ny taranak’izy ireo. dia nentiny nivoaka avy tany ejipta teo anatrehany tamin-kery lehibe ianao.'),
  ('6aadc74245d2a85474eb25fe', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 49, 'sy Araba manontolo any amin’ny faritra atsinanan’i Jordana, ka hatrany amin’ny Ranomasin’i Araba, eo am-pototry ny havoanan’i Pisga.', 'sy araba manontolo any amin’ny faritra atsinanan’i jordana, ka hatrany amin’ny ranomasin’i araba, eo am-pototry ny havoanan’i pisga.'),
  ('6aadc74245d2a85474eb25df', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 18, 'na sarim-biby mandady amin’ny tany, na sarin-trondro any anaty rano ambanin’ny tany.', 'na sarim-biby mandady amin’ny tany, na sarin-trondro any anaty rano ambanin’ny tany.'),
  ('6aadc74245d2a85474eb25f6', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 41, 'Nanokana tanàna telo teny ampita atsinanan’i Jordana i Mosesy, tamin’izay fotoana izay.', 'nanokana tanàna telo teny ampita atsinanan’i jordana i mosesy, tamin’izay fotoana izay.'),
  ('6aadc74245d2a85474eb25e7', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 26, 'dia hataoko vavolombelona hiampanga anareo ny lanitra sy ny tany anio, hoe tsy ho ela ianareo dia tsy maintsy ho ripaka eo amin’ilay tany izay halainareo ho anareo eny ampitan’i Jordana. Tsy ho ela velona eo ianareo, fa ho ringana tanteraka.', 'dia hataoko vavolombelona hiampanga anareo ny lanitra sy ny tany anio, hoe tsy ho ela ianareo dia tsy maintsy ho ripaka eo amin’ilay tany izay halainareo ho anareo eny ampitan’i jordana. tsy ho ela velona eo ianareo, fa ho ringana tanteraka.'),
  ('6aadc74245d2a85474eb25fa', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 45, 'Ireto avy ny fampahatsiahivana sy ny fitsipika ary ny didim-pitsarana nomen’i Mosesy ny Israelita, rehefa tafavoaka avy tany Ejipta izy ireo,', 'ireto avy ny fampahatsiahivana sy ny fitsipika ary ny didim-pitsarana nomen’i mosesy ny israelita, rehefa tafavoaka avy tany ejipta izy ireo,'),
  ('6aadc74245d2a85474eb25f0', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 35, 'Ianareo ihany no nampisehoana an’izany rehetra izany mba ho fantatrareo fa i Jehovah no tena Andriamanitra, ary tsy misy ankoatra azy.', 'ianareo ihany no nampisehoana an’izany rehetra izany mba ho fantatrareo fa i jehovah no tena andriamanitra, ary tsy misy ankoatra azy.'),
  ('6aadc74245d2a85474eb25e8', '2026-09-18T23:20:34.320Z', '2026-09-18T23:20:34.320Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 4, 27, 'Haparitak’i Jehovah any amin’ny firenen-kafa ianareo, ka ho vitsy kely sisa ianareo no ho velona, any amin’ireo firenena handefasan’i Jehovah anareo.', 'haparitak’i jehovah any amin’ny firenen-kafa ianareo, ka ho vitsy kely sisa ianareo no ho velona, any amin’ireo firenena handefasan’i jehovah anareo.'),
  ('6aadc742ce42d7c2587c3008', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 19, '“‘Aza mangalatra.', '“‘aza mangalatra.'),
  ('6aadc742ce42d7c2587c3003', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 14, 'Fa ny andro fahafito kosa Sabata ho an’i Jehovah Andriamanitrao. Aza manao asa na inona na inona, na ianao, na ny zanakao lahy, na ny zanakao vavy, na ny mpanompolahinao, na ny mpanompovavinao, na ny ombinao, na ny ampondranao, na ny biby fiompinao, na ny vahiny mipetraka ao an-tanànanao. Amin’izay dia ho afaka hiala sasatra hoatr’anao koa ny mpanompolahinao sy ny mpanompovavinao.', 'fa ny andro fahafito kosa sabata ho an’i jehovah andriamanitrao. aza manao asa na inona na inona, na ianao, na ny zanakao lahy, na ny zanakao vavy, na ny mpanompolahinao, na ny mpanompovavinao, na ny ombinao, na ny ampondranao, na ny biby fiompinao, na ny vahiny mipetraka ao an-tanànanao. amin’izay dia ho afaka hiala sasatra hoatr’anao koa ny mpanompolahinao sy ny mpanompovavinao.'),
  ('6aadc742ce42d7c2587c2ffc', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 7, 'Aza manana andriamani-kafa ankoatra ahy mihitsy.', 'aza manana andriamani-kafa ankoatra ahy mihitsy.'),
  ('6aadc742ce42d7c2587c2ff8', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 3, 'Tsy tamin’ny razambentsika no nanaovan’i Jehovah an’izany fifanekena izany fa tamintsika, dia isika rehetra mbola velona eto.', 'tsy tamin’ny razambentsika no nanaovan’i jehovah an’izany fifanekena izany fa tamintsika, dia isika rehetra mbola velona eto.'),
  ('6aadc742ce42d7c2587c3006', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 17, '“‘Aza mamono olona.', '“‘aza mamono olona.'),
  ('6aadc742ce42d7c2587c2ffe', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 9, 'Aza miankohoka eo anatrehan’ireny, na manaiky ho voatarika hanompo azy, fa izaho Jehovah Andriamanitrao dia Andriamanitra mitaky ny hanompoana ahy irery ihany. Koa raha misy raim-pianakaviana mankahala ahy, dia hosaziko noho ny fahadisoany ny zanany sy ny zafikeliny ary ny zafiafiny.', 'aza miankohoka eo anatrehan’ireny, na manaiky ho voatarika hanompo azy, fa izaho jehovah andriamanitrao dia andriamanitra mitaky ny hanompoana ahy irery ihany. koa raha misy raim-pianakaviana mankahala ahy, dia hosaziko noho ny fahadisoany ny zanany sy ny zafikeliny ary ny zafiafiny.'),
  ('6aadc742ce42d7c2587c3005', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 16, '“‘Hajao ny rainao sy ny reninao, araka ny didy nomen’i Jehovah Andriamanitrao anao, mba ho ela velona ianao, ary mba handeha tsara ny fiainanao eo amin’ilay tany homen’i Jehovah Andriamanitrao anao.', '“‘hajao ny rainao sy ny reninao, araka ny didy nomen’i jehovah andriamanitrao anao, mba ho ela velona ianao, ary mba handeha tsara ny fiainanao eo amin’ilay tany homen’i jehovah andriamanitrao anao.'),
  ('6aadc742ce42d7c2587c2fff', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 10, 'Fa raha misy kosa tia ahy sy mankatò ny didiko, dia ho tiako foana ny taranany, hatramin’ny taranany faharivo.', 'fa raha misy kosa tia ahy sy mankatò ny didiko, dia ho tiako foana ny taranany, hatramin’ny taranany faharivo.'),
  ('6aadc742ce42d7c2587c2ffa', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 5, 'Nitsangana teo anelanelanareo sy Jehovah aho tamin’izay, mba hampita aminareo ny tenin’i Jehovah. Natahotra an’ilay afo mantsy ianareo, ka tsy niakatra teo amin’ilay tendrombohitra. Hoy izy tamin’izay:', 'nitsangana teo anelanelanareo sy jehovah aho tamin’izay, mba hampita aminareo ny tenin’i jehovah. natahotra an’ilay afo mantsy ianareo, ka tsy niakatra teo amin’ilay tendrombohitra. hoy izy tamin’izay:'),
  ('6aadc742ce42d7c2587c2ff7', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 2, 'Nanao fifanekena tamintsika i Jehovah Andriamanitsika, tany Horeba.', 'nanao fifanekena tamintsika i jehovah andriamanitsika, tany horeba.'),
  ('6aadc742ce42d7c2587c3013', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 30, 'Mandehana lazao aminy hoe: “Modia any amin’ny tranolainareo.”', 'mandehana lazao aminy hoe: “modia any amin’ny tranolainareo.”'),
  ('6aadc742ce42d7c2587c3009', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 20, '“‘Aza mijoro ho vavolombelona mandainga hiampanga ny namanao.', '“‘aza mijoro ho vavolombelona mandainga hiampanga ny namanao.'),
  ('6aadc742ce42d7c2587c3000', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 11, '“‘Aza manao tsinontsinona ny anaran’i Jehovah Andriamanitrao, fa tsy hisy havelan’i Jehovah ho afa-maina izay manao tsinontsinona ny anarany.', '“‘aza manao tsinontsinona ny anaran’i jehovah andriamanitrao, fa tsy hisy havelan’i jehovah ho afa-maina izay manao tsinontsinona ny anarany.'),
  ('6aadc742ce42d7c2587c3015', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 32, 'Koa araho tsara izay efa nandidian’i Jehovah Andriamanitrareo anareo. Aza miala amin’izany na mivily miankavanana na miankavia.', 'koa araho tsara izay efa nandidian’i jehovah andriamanitrareo anareo. aza miala amin’izany na mivily miankavanana na miankavia.'),
  ('6aadc742ce42d7c2587c3012', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 29, 'Raha mba maniry hatahotra ahy sy hankatò ny didiko rehetra foana mantsy ny fony, dia handeha tsara mandrakizay ny fiainany sy ny an’ny taranany!', 'raha mba maniry hatahotra ahy sy hankatò ny didiko rehetra foana mantsy ny fony, dia handeha tsara mandrakizay ny fiainany sy ny an’ny taranany!'),
  ('6aadc742ce42d7c2587c3010', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 27, 'Fa mandehana ianao mihaino an’izay rehetra holazain’i Jehovah Andriamanitsika. Dia ianao no hiteny aminay izay rehetra lazain’i Jehovah Andriamanitsika aminao, ary hohenoinay izany ka harahinay.’', 'fa mandehana ianao mihaino an’izay rehetra holazain’i jehovah andriamanitsika. dia ianao no hiteny aminay izay rehetra lazain’i jehovah andriamanitsika aminao, ary hohenoinay izany ka harahinay.’'),
  ('6aadc742ce42d7c2587c300f', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 26, 'Fa iza tamin’ny olona rehetra no hoatr’antsika ka hoe efa naheno ny feon’ilay Andriamanitra velona niteny avy tao anaty afo, nefa mbola velona ihany?', 'fa iza tamin’ny olona rehetra no hoatr’antsika ka hoe efa naheno ny feon’ilay andriamanitra velona niteny avy tao anaty afo, nefa mbola velona ihany?'),
  ('6aadc742ce42d7c2587c300c', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 23, '“Raha vao henonareo anefa ilay feo avy tao anaty haizina, tamin’ilay tendrombohitra mbola nirehitra, dia nanatona ahy daholo ny lehibem-poko sy ny anti-panahy teo aminareo.', '“raha vao henonareo anefa ilay feo avy tao anaty haizina, tamin’ilay tendrombohitra mbola nirehitra, dia nanatona ahy daholo ny lehibem-poko sy ny anti-panahy teo aminareo.'),
  ('6aadc742ce42d7c2587c300a', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 21, '“‘Ary aza mitsiriritra ny vadin’ny namanao. Aza tia tena ka mitsiriritra ny tranon’ny namanao, na ny taniny, na ny mpanompolahiny, na ny mpanompovaviny, na ny ombiny, na ny ampondrany, na inona na inona fananany.’', '“‘ary aza mitsiriritra ny vadin’ny namanao. aza tia tena ka mitsiriritra ny tranon’ny namanao, na ny taniny, na ny mpanompolahiny, na ny mpanompovaviny, na ny ombiny, na ny ampondrany, na inona na inona fananany.’'),
  ('6aadc742ce42d7c2587c3007', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 18, '“‘Aza manitsakitsa-bady.', '“‘aza manitsakitsa-bady.'),
  ('6aadc742ce42d7c2587c3001', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 12, '“‘Tandremo ny andro sabata mba ho masina foana io andro io, araka ny didy nomen’i Jehovah Andriamanitrao anao.', '“‘tandremo ny andro sabata mba ho masina foana io andro io, araka ny didy nomen’i jehovah andriamanitrao anao.'),
  ('6aadc742ce42d7c2587c300e', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 25, 'Matahotra anefa izahay sao ho faty, satria mety handevona anay io afo lehibe io. Tena ho faty mihitsy izahay, raha mbola maheno ny feon’i Jehovah Andriamanitsika.', 'matahotra anefa izahay sao ho faty, satria mety handevona anay io afo lehibe io. tena ho faty mihitsy izahay, raha mbola maheno ny feon’i jehovah andriamanitsika.'),
  ('6aadc742ce42d7c2587c3014', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 31, 'Ianao kosa mijanòna eto amiko, fa holazaiko aminao daholo ny didy sy ny fitsipika ary ny didim-pitsarana tokony hampianarinao azy sy tokony hankatoaviny any amin’ilay tany homeko azy.’', 'ianao kosa mijanòna eto amiko, fa holazaiko aminao daholo ny didy sy ny fitsipika ary ny didim-pitsarana tokony hampianarinao azy sy tokony hankatoaviny any amin’ilay tany homeko azy.’'),
  ('6aadc742ce42d7c2587c2ffb', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 6, '“‘Izaho no Jehovah Andriamanitrao izay nitondra anao nivoaka avy tany Ejipta, tany amin’ny toerana nanandevozana anao.', '“‘izaho no jehovah andriamanitrao izay nitondra anao nivoaka avy tany ejipta, tany amin’ny toerana nanandevozana anao.'),
  ('6aadc742ce42d7c2587c2ff6', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 1, 'Dia nantsoin’i Mosesy ny Israely rehetra, ka hoy izy: “Ry Israely ô, henoy ny fitsipika sy ny didim-pitsarana lazaiko aminareo anio, dia ianaro sy araho tsara.', 'dia nantsoin’i mosesy ny israely rehetra, ka hoy izy: “ry israely ô, henoy ny fitsipika sy ny didim-pitsarana lazaiko aminareo anio, dia ianaro sy araho tsara.'),
  ('6aadc742ce42d7c2587c300d', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 24, 'Dia hoy ianareo: ‘Efa nasehon’i Jehovah Andriamanitsika antsika ny voninahiny sy ny heriny, ary efa henontsika ny feony niteny avy tao anaty afo. Androany isika no nahita fa afaka miteny amin’olona Andriamanitra, kanefa mbola velona ihany ilay olona.', 'dia hoy ianareo: ‘efa nasehon’i jehovah andriamanitsika antsika ny voninahiny sy ny heriny, ary efa henontsika ny feony niteny avy tao anaty afo. androany isika no nahita fa afaka miteny amin’olona andriamanitra, kanefa mbola velona ihany ilay olona.'),
  ('6aadc742ce42d7c2587c300b', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 22, '“Ireo didy ireo no nolazain’i Jehovah taminareo rehetra tafavory teo amin’ilay tendrombohitra, ary nilaza an’izany tamin’ny feo mafy avy tao anaty afo sy rahona ary haizim-pito izy. Tsy nasiany fanampiny ireo didy ireo. Dia nosoratany teo amin’ny takela-bato roa ireo ka nomeny ahy.', '“ireo didy ireo no nolazain’i jehovah taminareo rehetra tafavory teo amin’ilay tendrombohitra, ary nilaza an’izany tamin’ny feo mafy avy tao anaty afo sy rahona ary haizim-pito izy. tsy nasiany fanampiny ireo didy ireo. dia nosoratany teo amin’ny takela-bato roa ireo ka nomeny ahy.'),
  ('6aadc742ce42d7c2587c3002', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 13, 'Enina andro ianao no hiasa sy hanao ny raharahanao rehetra.', 'enina andro ianao no hiasa sy hanao ny raharahanao rehetra.'),
  ('6aadc742ce42d7c2587c2ff9', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 4, 'Niteny mivantana taminareo avy tao anaty afo i Jehovah, teo amin’ilay tendrombohitra.', 'niteny mivantana taminareo avy tao anaty afo i jehovah, teo amin’ilay tendrombohitra.'),
  ('6aadc742ce42d7c2587c3016', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 33, 'Araho tsara ny lalana asain’i Jehovah Andriamanitrareo halehanareo, mba ho velona ianareo ka handeha tsara ny fiainanareo, ary ho ela velona eo amin’ilay tany halainareo ho anareo ianareo.', 'araho tsara ny lalana asain’i jehovah andriamanitrareo halehanareo, mba ho velona ianareo ka handeha tsara ny fiainanareo, ary ho ela velona eo amin’ilay tany halainareo ho anareo ianareo.'),
  ('6aadc742ce42d7c2587c3011', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 28, '“Henon’i Jehovah àry ny teny nolazainareo tamiko, ka hoy i Jehovah tamiko: ‘Efa henoko ny tenin’ity vahoaka ity taminao. Mety daholo izany teniny izany.', '“henon’i jehovah àry ny teny nolazainareo tamiko, ka hoy i jehovah tamiko: ‘efa henoko ny tenin’ity vahoaka ity taminao. mety daholo izany teniny izany.'),
  ('6aadc742ce42d7c2587c3004', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 15, 'Tadidio fa andevo tany Ejipta ianao, ka nampiasa ny tanany matanjaka sy ny sandriny mahery i Jehovah Andriamanitrao rehefa nitondra anao niala tany. Izany no antony nandidian’i Jehovah Andriamanitrao anao hitandrina ny andro sabata.', 'tadidio fa andevo tany ejipta ianao, ka nampiasa ny tanany matanjaka sy ny sandriny mahery i jehovah andriamanitrao rehefa nitondra anao niala tany. izany no antony nandidian’i jehovah andriamanitrao anao hitandrina ny andro sabata.'),
  ('6aadc742ce42d7c2587c2ffd', '2026-09-18T23:20:34.814Z', '2026-09-18T23:20:34.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 5, 8, '“‘Aza manao sary sokitra ho anao, na manamboatra zavatra mitovy bika amin’izay eny amin’ny lanitra ambony, na izay etỳ amin’ny tany ambany, na izay any anaty rano ambanin’ny tany.', '“‘aza manao sary sokitra ho anao, na manamboatra zavatra mitovy bika amin’izay eny amin’ny lanitra ambony, na izay etỳ amin’ny tany ambany, na izay any anaty rano ambanin’ny tany.'),
  ('6aadc7436ee842fb255f9dda', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 15, 'satria i Jehovah Andriamanitrao izay eo aminao dia Andriamanitra mitaky ny hanompoana azy irery ihany. Fa raha manompo andriamani-kafa ianao, dia ho tezitra be aminao i Jehovah Andriamanitrao, ka haringany ianao dia tsy hisy intsony eny ambonin’ny tany.', 'satria i jehovah andriamanitrao izay eo aminao dia andriamanitra mitaky ny hanompoana azy irery ihany. fa raha manompo andriamani-kafa ianao, dia ho tezitra be aminao i jehovah andriamanitrao, ka haringany ianao dia tsy hisy intsony eny ambonin’ny tany.'),
  ('6aadc7436ee842fb255f9dd4', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 9, 'Soraty eo amin’ny tolàm-baravaran’ny tranonao sy eo amin’ny vavahadinao koa izany.', 'soraty eo amin’ny tolàm-baravaran’ny tranonao sy eo amin’ny vavahadinao koa izany.'),
  ('6aadc7436ee842fb255f9dd8', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 13, 'I Jehovah Andriamanitrao no tokony hatahoranao, izy no tokony hotompoinao, ary amin’ny anarany ianao no tokony hianiana.', 'i jehovah andriamanitrao no tokony hatahoranao, izy no tokony hotompoinao, ary amin’ny anarany ianao no tokony hianiana.'),
  ('6aadc7436ee842fb255f9dd7', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 12, 'Tandremo anefa sao hadinoinao i Jehovah, ilay nitondra anao nivoaka avy tany Ejipta, avy tany amin’ny toerana nanandevozana anao.', 'tandremo anefa sao hadinoinao i jehovah, ilay nitondra anao nivoaka avy tany ejipta, avy tany amin’ny toerana nanandevozana anao.'),
  ('6aadc7436ee842fb255f9dd6', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 11, 'Hahazo trano feno zavatra tsara isan-karazany izay tsy nisasaranao koa ianao, sy lavaka fanangonan-drano tsy nolavahanao, sy tanimboaloboka tsy novolenao, ary hazo oliva tsy nambolenao. Dia hihinana ianao ka ho voky.', 'hahazo trano feno zavatra tsara isan-karazany izay tsy nisasaranao koa ianao, sy lavaka fanangonan-drano tsy nolavahanao, sy tanimboaloboka tsy novolenao, ary hazo oliva tsy nambolenao. dia hihinana ianao ka ho voky.'),
  ('6aadc7436ee842fb255f9dd0', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 5, 'Tiavo i Jehovah Andriamanitrao amin’ny fonao manontolo sy ny tenanao manontolo ary ny herinao manontolo.', 'tiavo i jehovah andriamanitrao amin’ny fonao manontolo sy ny tenanao manontolo ary ny herinao manontolo.'),
  ('6aadc7436ee842fb255f9dd1', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 6, 'Ataovy ao am-ponao ireto teny andidiako anao anio ireto.', 'ataovy ao am-ponao ireto teny andidiako anao anio ireto.'),
  ('6aadc7436ee842fb255f9dcd', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 2, 'Dia amin’izay hatahotra an’i Jehovah Andriamanitrareo ianareo sy ny zanakareo ary ny zafinareo, ka hanaraka ny lalàny sy ny didiny rehetra andidiako anareo ianareo mandritra ny androm-piainanareo, mba ho ela velona.', 'dia amin’izay hatahotra an’i jehovah andriamanitrareo ianareo sy ny zanakareo ary ny zafinareo, ka hanaraka ny lalàny sy ny didiny rehetra andidiako anareo ianareo mandritra ny androm-piainanareo, mba ho ela velona.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6aadc7436ee842fb255f9dd5', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 10, '“Rehefa entin’i Jehovah Andriamanitrao any amin’ilay tany efa nianianany tamin’i Abrahama sy Isaka ary Jakoba razambenao hoe homena anao ianao, dia hahazo tanàna lehibe sady tsara tarehy izay tsy naorinao.', '“rehefa entin’i jehovah andriamanitrao any amin’ilay tany efa nianianany tamin’i abrahama sy isaka ary jakoba razambenao hoe homena anao ianao, dia hahazo tanàna lehibe sady tsara tarehy izay tsy naorinao.'),
  ('6aadc7436ee842fb255f9dd2', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 7, 'Dia alenteho tsikelikely ao an-tsain’ny zanakao izany ary resaho na rehefa mipetraka ao an-tranonao ianao, na mandeha eny an-dalana, na hatory, na mifoha.', 'dia alenteho tsikelikely ao an-tsain’ny zanakao izany ary resaho na rehefa mipetraka ao an-tranonao ianao, na mandeha eny an-dalana, na hatory, na mifoha.'),
  ('6aadc7436ee842fb255f9dd3', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 8, 'Afatory eo amin’ny tananao izany mba ho fampahatsiahivana ho anao, ary ataovy fehiloha eo amin’ny handrinao.', 'afatory eo amin’ny tananao izany mba ho fampahatsiahivana ho anao, ary ataovy fehiloha eo amin’ny handrinao.'),
  ('6aadc7436ee842fb255f9dcf', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 4, '“Henoy izao, ry Israely ô: I Jehovah Andriamanitsika dia Jehovah iray ihany.', '“henoy izao, ry israely ô: i jehovah andriamanitsika dia jehovah iray ihany.'),
  ('6aadc7436ee842fb255f9dce', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 3, 'Dia henoy izao, ry Israely ô, ka araho tsara mba handeha tsara ny fiainanareo, ary ho lasa be dia be ianareo any amin’ilay tany tondra-dronono sy tantely, araka ny efa nampanantenain’i Jehovah Andriamanitry ny razambenareo anareo.', 'dia henoy izao, ry israely ô, ka araho tsara mba handeha tsara ny fiainanareo, ary ho lasa be dia be ianareo any amin’ilay tany tondra-dronono sy tantely, araka ny efa nampanantenain’i jehovah andriamanitry ny razambenareo anareo.'),
  ('6aadc7436ee842fb255f9dd9', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 14, 'Aza manompo andriamani-kafa, dia ny andriamanitr’ireo firenena manodidina anao,', 'aza manompo andriamani-kafa, dia ny andriamanitr’ireo firenena manodidina anao,'),
  ('6aadc7436ee842fb255f9dcc', '2026-09-18T23:20:35.378Z', '2026-09-18T23:20:35.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 1, '“Izao no didy sy fitsipika ary didim-pitsarana asain’i Jehovah Andriamanitrareo ampianarina anareo, mba harahinareo rehefa miampita any amin’ilay tany halainareo ho anareo ianareo.', '“izao no didy sy fitsipika ary didim-pitsarana asain’i jehovah andriamanitrareo ampianarina anareo, mba harahinareo rehefa miampita any amin’ilay tany halainareo ho anareo ianareo.'),
  ('6aadc7436ee842fb255f9de2', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 23, 'Dia navoakany avy tany isika ka nentiny eto mba homeny an’ilay tany efa nianianany tamin’ny razambentsika.', 'dia navoakany avy tany isika ka nentiny eto mba homeny an’ilay tany efa nianianany tamin’ny razambentsika.'),
  ('6aadc7436ee842fb255f9de3', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 24, 'Nandidy antsika i Jehovah avy eo mba hankatò an’ireo fitsipika rehetra ireo, sady hatahotra an’i Jehovah Andriamanitsika. Handeha tsara foana ny fiainantsika amin’izay, dia ho velona foana isika hoatr’izao androany izao.', 'nandidy antsika i jehovah avy eo mba hankatò an’ireo fitsipika rehetra ireo, sady hatahotra an’i jehovah andriamanitsika. handeha tsara foana ny fiainantsika amin’izay, dia ho velona foana isika hoatr’izao androany izao.'),
  ('6aadc7436ee842fb255f9ddd', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 18, 'Izay tsara sy mety eo imason’i Jehovah no ataovy mba handeha tsara ny fiainanao, ka hiditra ao amin’ilay tany tsara nianianan’i Jehovah tamin’ny razambenao ianao. Dia halainao ho anao izy io,', 'izay tsara sy mety eo imason’i jehovah no ataovy mba handeha tsara ny fiainanao, ka hiditra ao amin’ilay tany tsara nianianan’i jehovah tamin’ny razambenao ianao. dia halainao ho anao izy io,'),
  ('6aadc7436ee842fb255f9ddb', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 16, '“Aza mitsapa toetra an’i Jehovah Andriamanitrareo, hoatran’ny nataonareo tao Masa.', '“aza mitsapa toetra an’i jehovah andriamanitrareo, hoatran’ny nataonareo tao masa.'),
  ('6aadc7436ee842fb255f9ddf', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 20, '“Raha manontany anao ny zanakao any aoriana any hoe: ‘Inona no dikan’ireny fampahatsiahivana sy fitsipika ary didim-pitsarana nandidian’i Jehovah Andriamanitsika anareo ireny?’,', '“raha manontany anao ny zanakao any aoriana any hoe: ‘inona no dikan’ireny fampahatsiahivana sy fitsipika ary didim-pitsarana nandidian’i jehovah andriamanitsika anareo ireny?’,'),
  ('6aadc7436ee842fb255f9ddc', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 17, 'Araho an-tsakany sy an-davany ny didin’i Jehovah Andriamanitrareo sy ny fampahatsiahivany ary ny fitsipiny izay nasainy narahinareo.', 'araho an-tsakany sy an-davany ny didin’i jehovah andriamanitrareo sy ny fampahatsiahivany ary ny fitsipiny izay nasainy narahinareo.'),
  ('6aadc7436ee842fb255f9de1', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 22, 'Koa nanao famantarana sy fahagagana lehibe i Jehovah mba handripahana an’i Ejipta sy Farao ary ny ankohonany manontolo, ary hitan’ny masontsika mihitsy izany.', 'koa nanao famantarana sy fahagagana lehibe i jehovah mba handripahana an’i ejipta sy farao ary ny ankohonany manontolo, ary hitan’ny masontsika mihitsy izany.'),
  ('6aadc7436ee842fb255f9de0', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 21, 'dia izao no holazainao aminy: ‘Andevon’i Farao isika tany Ejipta, nefa nentin’i Jehovah nivoaka avy tany tamin’ny herin-tsandriny.', 'dia izao no holazainao aminy: ‘andevon’i farao isika tany ejipta, nefa nentin’i jehovah nivoaka avy tany tamin’ny herin-tsandriny.'),
  ('6aadc7436ee842fb255f9de4', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 25, 'Ho olo-marina koa isika, raha mitandrina tsara an’izany didy rehetra izany satria mankatò an’i Jehovah Andriamanitsika, araka ny didy nomeny antsika.’', 'ho olo-marina koa isika, raha mitandrina tsara an’izany didy rehetra izany satria mankatò an’i jehovah andriamanitsika, araka ny didy nomeny antsika.’'),
  ('6aadc7436ee842fb255f9dde', '2026-09-18T23:20:35.379Z', '2026-09-18T23:20:35.379Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 6, 19, 'ka horoahinao hiala eo anatrehanao daholo ny fahavalonao, araka ny efa nampanantenain’i Jehovah.', 'ka horoahinao hiala eo anatrehanao daholo ny fahavalonao, araka ny efa nampanantenain’i jehovah.'),
  ('6aadc74493d811290fd4a57a', '2026-09-18T23:20:36.396Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 1, '“Rehefa ampidirin’i Jehovah Andriamanitrao any amin’ilay tany efa halainao ho anao ianao, dia horoahiny hiala eo aminao koa ireto firenena be mponina ireto: Ny Hetita, ny Girgasita, ny Amorita, ny Kananita, ny Perizita, ny Hivita, ary ny Jebosita, izany hoe firenena fito be mponina sady mahery noho ianao.', '“rehefa ampidirin’i jehovah andriamanitrao any amin’ilay tany efa halainao ho anao ianao, dia horoahiny hiala eo aminao koa ireto firenena be mponina ireto: ny hetita, ny girgasita, ny amorita, ny kananita, ny perizita, ny hivita, ary ny jebosita, izany hoe firenena fito be mponina sady mahery noho ianao.'),
  ('6aadc74493d811290fd4a591', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 24, 'Dia hataony resinao ny mpanjakany, ka hofoananao etỳ ambanin’ny lanitra ny anaran’ireny. Tsy hisy hahavita hanohitra anao, mandra-pandringanao tanteraka an’ireny.', 'dia hataony resinao ny mpanjakany, ka hofoananao etỳ ambanin’ny lanitra ny anaran’ireny. tsy hisy hahavita hanohitra anao, mandra-pandringanao tanteraka an’ireny.'),
  ('6aadc74493d811290fd4a585', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 12, '“Raha mihaino an’izany didim-pitsarana izany foana ianareo ka manaraka tsara sy mankatò azy ireny, dia hotanterahin’i Jehovah Andriamanitrareo ilay fifanekena nataony, ary ho tia anareo sy tsy hivadika aminareo izy, araka ilay fianianana nataony tamin’ny razambenareo.', '“raha mihaino an’izany didim-pitsarana izany foana ianareo ka manaraka tsara sy mankatò azy ireny, dia hotanterahin’i jehovah andriamanitrareo ilay fifanekena nataony, ary ho tia anareo sy tsy hivadika aminareo izy, araka ilay fianianana nataony tamin’ny razambenareo.'),
  ('6aadc74493d811290fd4a582', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 9, 'Fantatrao tsara fa i Jehovah Andriamanitrao no tena Andriamanitra, ilay Andriamanitra mendri-pitokisana sady manaja ny fifanekena nataony. Tena tia an’izay tia azy sy izay mankatò ny didiny koa izy sady tsy mba mivadika amin’izy ireny mihitsy, na dia hatrany amin’ny taranaka faharivo aza.', 'fantatrao tsara fa i jehovah andriamanitrao no tena andriamanitra, ilay andriamanitra mendri-pitokisana sady manaja ny fifanekena nataony. tena tia an’izay tia azy sy izay mankatò ny didiny koa izy sady tsy mba mivadika amin’izy ireny mihitsy, na dia hatrany amin’ny taranaka faharivo aza.'),
  ('6aadc74493d811290fd4a580', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 7, '“Tsy hoe satria ianareo no maro an’isa indrindra amin’ny firenena rehetra dia miraiki-po aminareo sy nifidy anareo i Jehovah. Ianareo tsinona no vitsy indrindra amin’ny firenena rehetra.', '“tsy hoe satria ianareo no maro an’isa indrindra amin’ny firenena rehetra dia miraiki-po aminareo sy nifidy anareo i jehovah. ianareo tsinona no vitsy indrindra amin’ny firenena rehetra.'),
  ('6aadc74493d811290fd4a57d', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 4, 'Fa hitarika ny zanakao lahy hiala amiko sy hanompo andriamani-kafa ireny, dia ho tezitra be aminao i Jehovah, ka horinganiny ao anatin’ny fotoana fohy ianao.', 'fa hitarika ny zanakao lahy hiala amiko sy hanompo andriamani-kafa ireny, dia ho tezitra be aminao i jehovah, ka horinganiny ao anatin’ny fotoana fohy ianao.'),
  ('6aadc74493d811290fd4a587', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 14, 'Ianao no hotahina indrindra amin’ny firenena rehetra. Hanan-janaka daholo na ny lehilahy na ny vehivavy eo aminao, na ny biby fiompinao.', 'ianao no hotahina indrindra amin’ny firenena rehetra. hanan-janaka daholo na ny lehilahy na ny vehivavy eo aminao, na ny biby fiompinao.'),
  ('6aadc74493d811290fd4a57e', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 5, '“Fa izao kosa no hataonareo amin’ireny: Arodano ny alitarany, potipoteho ny tsangambatony masina, kapao ny tsato-kazony masina, ary dory ny sary sokitra ivavahany.', '“fa izao kosa no hataonareo amin’ireny: arodano ny alitarany, potipoteho ny tsangambatony masina, kapao ny tsato-kazony masina, ary dory ny sary sokitra ivavahany.'),
  ('6aadc74493d811290fd4a588', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 15, 'Hesorin’i Jehovah eo aminao ny aretina rehetra. Ary hataony tsy misy mahazo anao ny aretina faran’izay ratsy efa fantatrao tany Ejipta. Fa izay rehetra mankahala anao kosa no hataony voan’izany.', 'hesorin’i jehovah eo aminao ny aretina rehetra. ary hataony tsy misy mahazo anao ny aretina faran’izay ratsy efa fantatrao tany ejipta. fa izay rehetra mankahala anao kosa no hataony voan’izany.'),
  ('6aadc74493d811290fd4a57b', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 2, 'Ary hatolotr’i Jehovah Andriamanitrao eo am-pelatananao ireny ka ho resinao. Tsy maintsy haringanao tanteraka izy ireny. Aza manao fifanekena aminy na miantra azy.', 'ary hatolotr’i jehovah andriamanitrao eo am-pelatananao ireny ka ho resinao. tsy maintsy haringanao tanteraka izy ireny. aza manao fifanekena aminy na miantra azy.'),
  ('6aadc74493d811290fd4a58a', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 17, '“Raha mieritreritra ianao hoe: ‘Betsaka lavitra noho izahay ireo firenena ireo, ka ho vitanay ve ny handroaka an’ireo?’,', '“raha mieritreritra ianao hoe: ‘betsaka lavitra noho izahay ireo firenena ireo, ka ho vitanay ve ny handroaka an’ireo?’,'),
  ('6aadc74493d811290fd4a58f', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 22, '“Horoahin’i Jehovah Andriamanitrao hiala tsikelikely eo anatrehanao ireny firenena ireny. Tsy mahazo mandringana azy ao anatin’ny fotoana fohy anefa ianao, sao ho lasa be dia be ny bibidia ka ho laniny ianao.', '“horoahin’i jehovah andriamanitrao hiala tsikelikely eo anatrehanao ireny firenena ireny. tsy mahazo mandringana azy ao anatin’ny fotoana fohy anefa ianao, sao ho lasa be dia be ny bibidia ka ho laniny ianao.'),
  ('6aadc74493d811290fd4a58e', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 21, 'Aza mihorohoro noho ny amin’ireny, fa manampy anao i Jehovah Andriamanitrao, ilay Andriamanitra tena miavaka sy mendrika hatahorana.', 'aza mihorohoro noho ny amin’ireny, fa manampy anao i jehovah andriamanitrao, ilay andriamanitra tena miavaka sy mendrika hatahorana.'),
  ('6aadc74493d811290fd4a58d', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 20, 'Hataon’i Jehovah Andriamanitrao koa izay hahakivy azy ireny, mandra-pahafatin’izay sisa tavela sy izay niafina anao.', 'hataon’i jehovah andriamanitrao koa izay hahakivy azy ireny, mandra-pahafatin’izay sisa tavela sy izay niafina anao.'),
  ('6aadc74493d811290fd4a584', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 11, 'Tandremo tsara àry ny didy sy ny fitsipika ary ny didim-pitsarana andidiako anao anio, dia ankatoavy izy ireny.', 'tandremo tsara àry ny didy sy ny fitsipika ary ny didim-pitsarana andidiako anao anio, dia ankatoavy izy ireny.'),
  ('6aadc74493d811290fd4a586', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 13, 'Dia ho tia sy hitahy anao tokoa izy, ary hataony lasa be dia be ianao. Tena hotahiny tokoa ianao ka hataony lasa be dia be ny zanakao, ny vokatry ny taninao, ny varimbazahanao, ny divainao vaovao, ny menakao, ny zanak’ombinao, ary ny zanak’ondrinao, any amin’ilay tany nianianany tamin’ny razambenao hoe homena anao.', 'dia ho tia sy hitahy anao tokoa izy, ary hataony lasa be dia be ianao. tena hotahiny tokoa ianao ka hataony lasa be dia be ny zanakao, ny vokatry ny taninao, ny varimbazahanao, ny divainao vaovao, ny menakao, ny zanak’ombinao, ary ny zanak’ondrinao, any amin’ilay tany nianianany tamin’ny razambenao hoe homena anao.'),
  ('6aadc74493d811290fd4a57f', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 6, 'Fa vahoaka masina ianareo amin’i Jehovah Andriamanitrareo, ary nofidin’i Jehovah Andriamanitrareo avy tamin’ny firenena rehetra etỳ ambonin’ny tany, mba ho vahoakany sy ho fananany manokana.', 'fa vahoaka masina ianareo amin’i jehovah andriamanitrareo, ary nofidin’i jehovah andriamanitrareo avy tamin’ny firenena rehetra etỳ ambonin’ny tany, mba ho vahoakany sy ho fananany manokana.'),
  ('6aadc74493d811290fd4a590', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 23, 'Hanolotra azy ireny eo am-pelatananao i Jehovah Andriamanitrao ka handresy azy tanteraka, mandra-paharipaka an’ireny.', 'hanolotra azy ireny eo am-pelatananao i jehovah andriamanitrao ka handresy azy tanteraka, mandra-paharipaka an’ireny.'),
  ('6aadc74493d811290fd4a593', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 26, 'Aza mitondra zava-maharikoriko ho ao an-tranonao, sao haringana hoatr’izany zavatra izany koa ianao. Tokony haharikoriko tanteraka anao izany sady ho tena halanao, satria zavatra voatokana haringana.', 'aza mitondra zava-maharikoriko ho ao an-tranonao, sao haringana hoatr’izany zavatra izany koa ianao. tokony haharikoriko tanteraka anao izany sady ho tena halanao, satria zavatra voatokana haringana.'),
  ('6aadc74493d811290fd4a589', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 16, 'Tokony haringanao daholo ny firenena rehetra hataon’i Jehovah Andriamanitrao resinao. Aza miantra azy ianao ary aza manompo ny andriamaniny, fa ho fandrika ho anao izany.', 'tokony haringanao daholo ny firenena rehetra hataon’i jehovah andriamanitrao resinao. aza miantra azy ianao ary aza manompo ny andriamaniny, fa ho fandrika ho anao izany.'),
  ('6aadc74493d811290fd4a583', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 10, 'Izay mankahala azy kosa hovaliany ka haringany. Tsy hiandry ela izy rehefa hanasazy an’izay mankahala azy, fa hataony hitan’izy ireo tsara ny hamaliany azy.', 'izay mankahala azy kosa hovaliany ka haringany. tsy hiandry ela izy rehefa hanasazy an’izay mankahala azy, fa hataony hitan’izy ireo tsara ny hamaliany azy.'),
  ('6aadc74493d811290fd4a581', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 8, 'Fa tia anareo kosa i Jehovah sady nanaja an’ilay fianianana nataony tamin’ny razambenareo. Dia izany no nahatonga an’i Jehovah hampiasa ny herin-tsandriny mba hitondrana anareo sy hanavotana anareo avy tany amin’ilay toerana nanandevozana anareo, dia avy teo ambany fahefan’i Farao mpanjakan’i Ejipta.', 'fa tia anareo kosa i jehovah sady nanaja an’ilay fianianana nataony tamin’ny razambenareo. dia izany no nahatonga an’i jehovah hampiasa ny herin-tsandriny mba hitondrana anareo sy hanavotana anareo avy tany amin’ilay toerana nanandevozana anareo, dia avy teo ambany fahefan’i farao mpanjakan’i ejipta.'),
  ('6aadc74493d811290fd4a592', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 25, 'Tokony hodoranareo ny sary sokitra ataony andriamanitra. Aza mitsiriritra ny volafotsy na ny volamena eo amin’ireny, na maka an’izany ho anao, sao ho voafandrik’izany ianao. Zavatra maharikoriko an’i Jehovah Andriamanitrao mantsy izany.', 'tokony hodoranareo ny sary sokitra ataony andriamanitra. aza mitsiriritra ny volafotsy na ny volamena eo amin’ireny, na maka an’izany ho anao, sao ho voafandrik’izany ianao. zavatra maharikoriko an’i jehovah andriamanitrao mantsy izany.'),
  ('6aadc74493d811290fd4a58c', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 19, 'dia ny sazy lehibe efa hitan’ny masonao, ny famantarana sy fahagagana nataon’i Jehovah Andriamanitrao, ny tanana matanjaka sy herin-tsandry nampiasainy mba hitondrana anao hivoaka avy tany. Hoatr’izany no hataon’i Jehovah Andriamanitrao amin’ny firenena rehetra atahoranao.', 'dia ny sazy lehibe efa hitan’ny masonao, ny famantarana sy fahagagana nataon’i jehovah andriamanitrao, ny tanana matanjaka sy herin-tsandry nampiasainy mba hitondrana anao hivoaka avy tany. hoatr’izany no hataon’i jehovah andriamanitrao amin’ny firenena rehetra atahoranao.'),
  ('6aadc74493d811290fd4a57c', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 3, 'Aza manao fifanarahana aminy, ka hoe omenao ho vadin’ny zanany lahy ny zanakao vavy, ary alainao ho vadin’ny zanakao lahy ny zanany vavy.', 'aza manao fifanarahana aminy, ka hoe omenao ho vadin’ny zanany lahy ny zanakao vavy, ary alainao ho vadin’ny zanakao lahy ny zanany vavy.'),
  ('6aadc74493d811290fd4a58b', '2026-09-18T23:20:36.397Z', '2026-09-18T23:20:36.397Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Deoteronomia', 5, 7, 18, 'dia aza matahotra azy. Tadidio foana izay nataon’i Jehovah Andriamanitrao tamin’i Farao sy Ejipta manontolo,', 'dia aza matahotra azy. tadidio foana izay nataon’i jehovah andriamanitrao tamin’i farao sy ejipta manontolo,'),
  ('6aadc75abedd82e18cdc0500', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 13, 'Nitso-drano an’i Kaleba zanak’i Jefone àry i Josoa, ka nomeny ho lovany i Hebrona.', 'nitso-drano an’i kaleba zanak’i jefone àry i josoa, ka nomeny ho lovany i hebrona.'),
  ('6aadc75abedd82e18cdc04f8', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 5, 'Dia nozarain’ny Israelita ilay tany, araka izay nandidian’i Jehovah an’i Mosesy.', 'dia nozarain’ny israelita ilay tany, araka izay nandidian’i jehovah an’i mosesy.'),
  ('6aadc75abedd82e18cdc04f4', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 1, 'Dia naka ny lovany tao amin’ny tany Kanana ny Israelita. I Eleazara mpisorona sy Josoa zanak’i Nona ary ireo lohan’ny fianakaviamben’ireo fokon’ny Israely no nanome azy ireo an’izany.', 'dia naka ny lovany tao amin’ny tany kanana ny israelita. i eleazara mpisorona sy josoa zanak’i nona ary ireo lohan’ny fianakaviamben’ireo fokon’ny israely no nanome azy ireo an’izany.'),
  ('6aadc75abedd82e18cdc0502', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 15, 'Kiriata-arba no anaran’i Hebrona talohan’izay.—Lehilahy niavaka indrindra teo amin’ny Anakita izany Arba izany.—Dia nilamina ilay tany, ary tsy nisy ady intsony.', 'kiriata-arba no anaran’i hebrona talohan’izay.—lehilahy niavaka indrindra teo amin’ny anakita izany arba izany.—dia nilamina ilay tany, ary tsy nisy ady intsony.'),
  ('6aadc75abedd82e18cdc04fc', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 9, 'Nianiana i Mosesy tamin’izay andro izay hoe: ‘Ho lasa lovanao sy ny taranakao foana ny tany nohitsahin’ny tongotrao, satria ianao nanaraka an’i Jehovah Andriamanitro tamin’ny fonao manontolo.’', 'nianiana i mosesy tamin’izay andro izay hoe: ‘ho lasa lovanao sy ny taranakao foana ny tany nohitsahin’ny tongotrao, satria ianao nanaraka an’i jehovah andriamanitro tamin’ny fonao manontolo.’'),
  ('6aadc75abedd82e18cdc04fb', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 8, 'Nanaraka an’i Jehovah Andriamanitro tamin’ny foko manontolo aho, na dia nampatahotra ny vahoaka aza ny tenin’ireo rahalahiko niara-niakatra tamiko.', 'nanaraka an’i jehovah andriamanitro tamin’ny foko manontolo aho, na dia nampatahotra ny vahoaka aza ny tenin’ireo rahalahiko niara-niakatra tamiko.'),
  ('6aadc75abedd82e18cdc04fa', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 7, 'Tamin’izaho 40 taona no nirahin’i Mosesy mpanompon’i Jehovah, avy tao Kadesi-barnea, mba hitsikilo an’ity tany ity. Dia nanao tatitra marina tsara aho rehefa niverina.', 'tamin’izaho 40 taona no nirahin’i mosesy mpanompon’i jehovah, avy tao kadesi-barnea, mba hitsikilo an’ity tany ity. dia nanao tatitra marina tsara aho rehefa niverina.'),
  ('6aadc75abedd82e18cdc0501', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 14, 'Izany no nahatonga an’i Hebrona ho lovan’i Kaleba zanak’i Jefone Kenizita hatramin’izao. Nanaraka an’i Jehovah Andriamanitry ny Israely tamin’ny fony manontolo mantsy izy.', 'izany no nahatonga an’i hebrona ho lovan’i kaleba zanak’i jefone kenizita hatramin’izao. nanaraka an’i jehovah andriamanitry ny israely tamin’ny fony manontolo mantsy izy.'),
  ('6aadc75abedd82e18cdc04fe', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 11, 'Mbola matanjaka aho, hoatran’ny tamin’ilay andro nanirahan’i Mosesy ahy ihany. Sahala amin’ny heriko tamin’izany ihany ny heriko amin’izao, na rehefa miady aho na rehefa manao zavatra hafa.', 'mbola matanjaka aho, hoatran’ny tamin’ilay andro nanirahan’i mosesy ahy ihany. sahala amin’ny heriko tamin’izany ihany ny heriko amin’izao, na rehefa miady aho na rehefa manao zavatra hafa.'),
  ('6aadc75abedd82e18cdc04f7', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 4, 'Nisaina ho foko roa ny taranak’i Josefa, dia i Manase sy Efraima. Tsy nomena anjara tao amin’ilay tany kosa ny Levita, afa-tsy tanàna honenana sy kijana ho an’ny biby fiompiny sy ny fananany.', 'nisaina ho foko roa ny taranak’i josefa, dia i manase sy efraima. tsy nomena anjara tao amin’ilay tany kosa ny levita, afa-tsy tanàna honenana sy kijana ho an’ny biby fiompiny sy ny fananany.'),
  ('6aadc75abedd82e18cdc04f5', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 2, 'Tamin’ny antsapaka no nizarana ny lovan’izy ireo, araka ny didy nomen’i Jehovah tamin’ny alalan’i Mosesy momba an’ireo foko sivy sy ny antsasaky ny foko iray.', 'tamin’ny antsapaka no nizarana ny lovan’izy ireo, araka ny didy nomen’i jehovah tamin’ny alalan’i mosesy momba an’ireo foko sivy sy ny antsasaky ny foko iray.'),
  ('6aadc75abedd82e18cdc04ff', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 12, 'Omeo ahy àry irỳ faritra be tendrombohitra irỳ, izay nampanantenain’i Jehovah tamin’iny andro iny. Marina fa efa henonao tamin’iny andro iny fa nisy Anakita tao, sady nisy tanàna lehibe voaro mafy. Tena hanampy ahy anefa i Jehovah ka horoahiko izy ireo, araka ny nampanantenain’i Jehovah.”', 'omeo ahy àry irỳ faritra be tendrombohitra irỳ, izay nampanantenain’i jehovah tamin’iny andro iny. marina fa efa henonao tamin’iny andro iny fa nisy anakita tao, sady nisy tanàna lehibe voaro mafy. tena hanampy ahy anefa i jehovah ka horoahiko izy ireo, araka ny nampanantenain’i jehovah.”'),
  ('6aadc75abedd82e18cdc04fd', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 10, 'Araka ny nampanantenainy, dia nitsimbina ny aiko i Jehovah nandritra izay 45 taona izay, nanomboka tamin’ny nilazan’i Jehovah an’izany fampanantenana izany tamin’i Mosesy, rehefa nandeha namakivaky ny tany efitra ny Israely. Mbola velona aho izao, ary efa 85 taona.', 'araka ny nampanantenainy, dia nitsimbina ny aiko i jehovah nandritra izay 45 taona izay, nanomboka tamin’ny nilazan’i jehovah an’izany fampanantenana izany tamin’i mosesy, rehefa nandeha namakivaky ny tany efitra ny israely. mbola velona aho izao, ary efa 85 taona.'),
  ('6aadc75abedd82e18cdc04f6', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 3, 'Efa nomen’i Mosesy an’ireo foko roa hafa sy ny antsasaky ny fokon’i Manase ny lovan’izy ireo, teny ampitan’ny Reniranon’i Jordana. Tsy nomeny lova teo amin’izy ireo kosa ny Levita.', 'efa nomen’i mosesy an’ireo foko roa hafa sy ny antsasaky ny fokon’i manase ny lovan’izy ireo, teny ampitan’ny reniranon’i jordana. tsy nomeny lova teo amin’izy ireo kosa ny levita.'),
  ('6aadc75abedd82e18cdc04f9', '2026-09-18T23:20:58.647Z', '2026-09-18T23:20:58.647Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 14, 6, 'Dia nanatona an’i Josoa tao Gilgala ny fokon’i Joda, ary hoy i Kaleba zanak’i Jefone Kenizita taminy: “Fantatrao tsara izay nolazain’i Jehovah tamin’i Mosesy, lehilahin’Andriamanitra, momba ahy sy ianao tany Kadesi-barnea.', 'dia nanatona an’i josoa tao gilgala ny fokon’i joda, ary hoy i kaleba zanak’i jefone kenizita taminy: “fantatrao tsara izay nolazain’i jehovah tamin’i mosesy, lehilahin’andriamanitra, momba ahy sy ianao tany kadesi-barnea.'),
  ('6aadc75bf8d642c3cae0e3a7', '2026-09-18T23:20:59.033Z', '2026-09-18T23:20:59.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 4, 'dia nitohy hatrany Azmona ka tonga hatrany amin’ny Reniranon’i Ejipta, ary hatrany amin’ny Ranomasina ny farany. Izany no sisin-taniny atsimo.', 'dia nitohy hatrany azmona ka tonga hatrany amin’ny reniranon’i ejipta, ary hatrany amin’ny ranomasina ny farany. izany no sisin-taniny atsimo.'),
  ('6aadc75bf8d642c3cae0e3a5', '2026-09-18T23:20:59.033Z', '2026-09-18T23:20:59.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 2, 'Ny sisin-taniny atsimo dia nanomboka teo amin’ny sisin’ny Ranomasin-tsira, eo amin’ilay helodrano mitodika mianatsimo,', 'ny sisin-taniny atsimo dia nanomboka teo amin’ny sisin’ny ranomasin-tsira, eo amin’ilay helodrano mitodika mianatsimo,'),
  ('6aadc75bf8d642c3cae0e3a6', '2026-09-18T23:20:59.033Z', '2026-09-18T23:20:59.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 3, 'ary nianatsimo nankany amin’ny fiakarana Akrabima ka nandalo an’i Zina, dia niakatra avy teo atsimo nankany Kadesi-barnea ka nitohy hatrany Hezrona, dia niakatra nankany Adara ka nivily nankany Karka,', 'ary nianatsimo nankany amin’ny fiakarana akrabima ka nandalo an’i zina, dia niakatra avy teo atsimo nankany kadesi-barnea ka nitohy hatrany hezrona, dia niakatra nankany adara ka nivily nankany karka,'),
  ('6aadc75bf8d642c3cae0e3a4', '2026-09-18T23:20:59.033Z', '2026-09-18T23:20:59.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 1, 'Tonga hatrany amin’ny sisin-tanin’i Edoma sy ny tany efitr’i Zina ary ny farany atsimon’i Negeba ny tany azon’ny fokon’i Joda, mba ho an’ny fianakavian’izy ireo.', 'tonga hatrany amin’ny sisin-tanin’i edoma sy ny tany efitr’i zina ary ny farany atsimon’i negeba ny tany azon’ny fokon’i joda, mba ho an’ny fianakavian’izy ireo.'),
  ('6aadc75bf8d642c3cae0e3e1', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 62, 'Nibsana, sy ilay Tanànan-tsira ary En-jedy, izany hoe tanàna enina sy ny tanàna keliny.', 'nibsana, sy ilay tanànan-tsira ary en-jedy, izany hoe tanàna enina sy ny tanàna keliny.'),
  ('6aadc75bf8d642c3cae0e3cd', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 42, 'Anisany koa i Libna, Etera, Asana,', 'anisany koa i libna, etera, asana,'),
  ('6aadc75bf8d642c3cae0e3ca', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 39, 'Lakisy, Bozkata, Eglona,', 'lakisy, bozkata, eglona,'),
  ('6aadc75bf8d642c3cae0e3b2', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 15, 'Ary niakatra avy tao i Kaleba dia nandeha niady tamin’ny mponin’i Debira. Kiriata-sefera no anaran’i Debira talohan’izay.', 'ary niakatra avy tao i kaleba dia nandeha niady tamin’ny mponin’i debira. kiriata-sefera no anaran’i debira talohan’izay.'),
  ('6aadc75bf8d642c3cae0e3df', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 60, 'Mbola anisany koa i Kiriata-bala, izany hoe Kiriata-jearima, sy Raba, izany hoe tanàna roa sy ny tanàna keliny.', 'mbola anisany koa i kiriata-bala, izany hoe kiriata-jearima, sy raba, izany hoe tanàna roa sy ny tanàna keliny.'),
  ('6aadc75bf8d642c3cae0e3d0', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 45, 'Anisany koa i Ekrona sy ireo tanàna niankina taminy ary ny tanàna keliny,', 'anisany koa i ekrona sy ireo tanàna niankina taminy ary ny tanàna keliny,'),
  ('6aadc75bf8d642c3cae0e3ae', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 11, 'dia tonga hatrany amin’ny tehezany avaratra amin’i Ekrona, ary avy teo Sikerona no nitohy teo amin’ny Tendrombohitra Balaha ary nankany Jabniela, dia tany amin’ny ranomasina ny farany.', 'dia tonga hatrany amin’ny tehezany avaratra amin’i ekrona, ary avy teo sikerona no nitohy teo amin’ny tendrombohitra balaha ary nankany jabniela, dia tany amin’ny ranomasina ny farany.'),
  ('6aadc75bf8d642c3cae0e3c9', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 38, 'Dilana, Mizpe, Joktela,', 'dilana, mizpe, joktela,'),
  ('6aadc75bf8d642c3cae0e3c6', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 35, 'Jarmota, Adolama, Soko, Azeka,', 'jarmota, adolama, soko, azeka,'),
  ('6aadc75bf8d642c3cae0e3b8', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 21, 'Ireto avy ny tanàna teny amin’ny sisiny indrindra amin’ny tanin’ny fokon’i Joda, tandrifin’ny sisin-tanin’i Edoma any atsimo: Kabzela, Edera, Jagora,', 'ireto avy ny tanàna teny amin’ny sisiny indrindra amin’ny tanin’ny fokon’i joda, tandrifin’ny sisin-tanin’i edoma any atsimo: kabzela, edera, jagora,'),
  ('6aadc75bf8d642c3cae0e3d6', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 51, 'Gosena, Holona, ary Gilo, izany hoe tanàna 11 sy ny tanàna keliny.', 'gosena, holona, ary gilo, izany hoe tanàna 11 sy ny tanàna keliny.'),
  ('6aadc75bf8d642c3cae0e3d4', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 49, 'Dana, Kiriata-sana, izany hoe Debira,', 'dana, kiriata-sana, izany hoe debira,'),
  ('6aadc75bf8d642c3cae0e3bd', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 26, 'Amama, Sema, Molada,', 'amama, sema, molada,'),
  ('6aadc75bf8d642c3cae0e3a8', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 5, 'Ny sisin-tany atsinanana dia ny Ranomasin-tsira hatrany amin’ny faran’ny Reniranon’i Jordana. Ary ny sisin-tany tamin’ny zorony avaratra dia nanomboka teo amin’ny helodranomasina, eo amin’ny faran’ny Reniranon’i Jordana.', 'ny sisin-tany atsinanana dia ny ranomasin-tsira hatrany amin’ny faran’ny reniranon’i jordana. ary ny sisin-tany tamin’ny zorony avaratra dia nanomboka teo amin’ny helodranomasina, eo amin’ny faran’ny reniranon’i jordana.'),
  ('6aadc75bf8d642c3cae0e3e0', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 61, 'Ary ireto avy no tany an-tany efitra: Beti-araba, Midina, Sekaka,', 'ary ireto avy no tany an-tany efitra: beti-araba, midina, sekaka,'),
  ('6aadc75bf8d642c3cae0e3dc', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 57, 'Kaina, Gibea, ary Timna, izany hoe tanàna folo sy ny tanàna keliny.', 'kaina, gibea, ary timna, izany hoe tanàna folo sy ny tanàna keliny.'),
