  ('6aadc75bf8d642c3cae0e3b9', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 22, 'Kina, Dimona, Adada,', 'kina, dimona, adada,'),
