  ('6aadc75bf8d642c3cae0e3b5', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 18, 'Rehefa nankany an-tranon’i Otniela i Aksa, dia nampirisihiny hangataka saha tamin’i Kaleba rainy i Otniela. Dia niala teo ambony ampondrany i Aksa, ka hoy ny rainy: “Inona no ilainao?”', 'rehefa nankany an-tranon’i otniela i aksa, dia nampirisihiny hangataka saha tamin’i kaleba rainy i otniela. dia niala teo ambony ampondrany i aksa, ka hoy ny rainy: “inona no ilainao?”'),
