  ('6aadc75bf8d642c3cae0e3ce', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 43, 'Jifta, Asna, Neziba,', 'jifta, asna, neziba,'),
  ('6aadc75bf8d642c3cae0e3af', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 12, 'Ary ny sisin-tany andrefana dia ny Ranomasina Lehibe sy ny morontsirany. Izany no sisin-tanin’ny lova nozaraina tamin’ny taranak’i Joda, araka ny fianakaviany avy.', 'ary ny sisin-tany andrefana dia ny ranomasina lehibe sy ny morontsirany. izany no sisin-tanin’ny lova nozaraina tamin’ny taranak’i joda, araka ny fianakaviany avy.'),
