  ('6aadc75bf8d642c3cae0e3b3', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 16, 'Dia hoy i Kaleba: “Izay lehilahy maharesy an’i Kiriata-sefera ka mahazo an’io tanàna io, dia homeko ho vadiny i Aksa zanako vavy.”', 'dia hoy i kaleba: “izay lehilahy maharesy an’i kiriata-sefera ka mahazo an’io tanàna io, dia homeko ho vadiny i aksa zanako vavy.”'),
