  ('6aadc75bf8d642c3cae0e3be', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 27, 'Hazara-gada, Hesmona, Beti-paleta,', 'hazara-gada, hesmona, beti-paleta,'),
