  ('6aadc75bf8d642c3cae0e3b4', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 17, 'I Otniela, zanak’i Kenaza rahalahin’i Kaleba, no nahazo an’ilay tanàna, ka nomen’i Kaleba azy ho vadiny i Aksa zanany vavy.', 'i otniela, zanak’i kenaza rahalahin’i kaleba, no nahazo an’ilay tanàna, ka nomen’i kaleba azy ho vadiny i aksa zanany vavy.'),
  ('6aadc75bf8d642c3cae0e3b1', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 14, 'Dia noroahin’i Kaleba niala tao ny zanak’i Anàka telo lahy, dia i Sesay sy Ahimana ary Talmay, izay taranak’i Anàka.', 'dia noroahin’i kaleba niala tao ny zanak’i anàka telo lahy, dia i sesay sy ahimana ary talmay, izay taranak’i anàka.'),
