  ('6aadc75bf8d642c3cae0e3c1', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 30, 'Eltolada, Kesila, Horma,', 'eltolada, kesila, horma,'),
  ('6aadc75bf8d642c3cae0e3ab', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 8, 'Nitohy ihany ilay sisin-tany ka niakatra nankany amin’ny Lohasahan’ny Taranak’i Hinoma, nankeo amin’ny ilany atsimo amin’ny tehezan-kavoanan’ny Jebosita, izany hoe i Jerosalema, ary niakatra nankeo amin’ny tampon-tendrombohitra tandrifin’ny ilany andrefana amin’ny Lohasahan’i Hinoma. Eo amin’ny sisiny avaratra amin’ny Lohasahan’ny Refaima io tendrombohitra io.', 'nitohy ihany ilay sisin-tany ka niakatra nankany amin’ny lohasahan’ny taranak’i hinoma, nankeo amin’ny ilany atsimo amin’ny tehezan-kavoanan’ny jebosita, izany hoe i jerosalema, ary niakatra nankeo amin’ny tampon-tendrombohitra tandrifin’ny ilany andrefana amin’ny lohasahan’i hinoma. eo amin’ny sisiny avaratra amin’ny lohasahan’ny refaima io tendrombohitra io.'),
