  ('6aadc75bf8d642c3cae0e3da', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 55, 'Anisany koa i Maona, Karmela, Zifa, Jota,', 'anisany koa i maona, karmela, zifa, jota,'),
  ('6aadc75bf8d642c3cae0e3bc', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 25, 'Hazora-hadata, Keriota-hezrona, izany hoe Hazora,', 'hazora-hadata, keriota-hezrona, izany hoe hazora,'),
  ('6aadc75bf8d642c3cae0e3b7', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 20, 'Izany no lova nozaraina tamin’ny fokon’i Joda, araka ny fianakaviany avy.', 'izany no lova nozaraina tamin’ny fokon’i joda, araka ny fianakaviany avy.'),
  ('6aadc75bf8d642c3cae0e3ac', '2026-09-18T23:20:59.034Z', '2026-09-18T23:20:59.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 15, 9, 'Avy eo an-tampon’ilay tendrombohitra ilay sisin-tany no mankany amin’ny loharanon’i Neftoa, ary tonga hatrany amin’ireo tanàna teny amin’ny Tendrombohitra Efrona, ka nitohy hatrany Balaha, izany hoe Kiriata-jearima.', 'avy eo an-tampon’ilay tendrombohitra ilay sisin-tany no mankany amin’ny loharanon’i neftoa, ary tonga hatrany amin’ireo tanàna teny amin’ny tendrombohitra efrona, ka nitohy hatrany balaha, izany hoe kiriata-jearima.'),
  ('6aadc75c42d2193f06839daf', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 3, 'dia nidina niankandrefana nankany amin’ny sisin-tanin’ny Jafletita ka nitohy hatrany amin’ny sisin’i Beti-horona Ambany sy Gazera, ary nifarana tany amin’ny ranomasina.', 'dia nidina niankandrefana nankany amin’ny sisin-tanin’ny jafletita ka nitohy hatrany amin’ny sisin’i beti-horona ambany sy gazera, ary nifarana tany amin’ny ranomasina.'),
  ('6aadc75c42d2193f06839db2', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 6, 'ary tonga hatrany amin’ny ranomasina. I Mikmeta kosa no tany amin’ny sisiny avaratra. Ary nivily niantsinanana nankany Tanata-silo ilay sisin-tany, ka niantsinanana nankany Janoha,', 'ary tonga hatrany amin’ny ranomasina. i mikmeta kosa no tany amin’ny sisiny avaratra. ary nivily niantsinanana nankany tanata-silo ilay sisin-tany, ka niantsinanana nankany janoha,'),
  ('6aadc75c42d2193f06839db0', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 4, 'Naka ny taniny àry i Manase sy Efraima taranak’i Josefa.', 'naka ny taniny àry i manase sy efraima taranak’i josefa.'),
  ('6aadc75c42d2193f06839db6', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 10, 'Tsy noroahin’izy ireo anefa ny Kananita nipetraka tao Gazera. Mbola miara-mipetraka amin’ny fokon’i Efraima ihany àry ny Kananita hatramin’izao, saingy ampanaovina asa an-terivozona.', 'tsy noroahin’izy ireo anefa ny kananita nipetraka tao gazera. mbola miara-mipetraka amin’ny fokon’i efraima ihany àry ny kananita hatramin’izao, saingy ampanaovina asa an-terivozona.'),
  ('6aadc75c42d2193f06839db1', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 5, 'Ary izao ny sisin-tanin’ny lova nozaraina tamin’ny taranak’i Efraima, araka ny fianakaviany avy: Ny sisin-taniny atsinanana dia i Atarota-adara hatrany Beti-horona Ambony,', 'ary izao ny sisin-tanin’ny lova nozaraina tamin’ny taranak’i efraima, araka ny fianakaviany avy: ny sisin-taniny atsinanana dia i atarota-adara hatrany beti-horona ambony,'),
  ('6aadc75c42d2193f06839db3', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 7, 'dia nidina avy teo Janoha ka nankany Atarota sy Nara, ary nitohy tany Jeriko ka tonga hatrany amin’i Jordana.', 'dia nidina avy teo janoha ka nankany atarota sy nara, ary nitohy tany jeriko ka tonga hatrany amin’i jordana.'),
  ('6aadc75c42d2193f06839dae', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 2, 'Tonga hatrany Betelan’i Lozy izany ka nitohy hatrany amin’ny sisin-tanin’ny Arkita ao Atarota,', 'tonga hatrany betelan’i lozy izany ka nitohy hatrany amin’ny sisin-tanin’ny arkita ao atarota,'),
  ('6aadc75c42d2193f06839db5', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 9, 'Nanana tanàna tao amin’ny lovan’i Manase koa ny taranak’i Efraima, dia ny tanàna rehetra sy ny tanàna keliny.', 'nanana tanàna tao amin’ny lovan’i manase koa ny taranak’i efraima, dia ny tanàna rehetra sy ny tanàna keliny.'),
  ('6aadc75c42d2193f06839dad', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 1, 'Ary ny tany azon’ny taranak’i Josefa tamin’ny antsapaka dia nanomboka teo amin’ny Reniranon’i Jordana akaikin’i Jeriko, nankany atsinanan’ny ranon’i Jeriko, dia nandalo an’ilay tany efitra niakatra avy teo Jeriko, ka nankany amin’ny faritra be tendrombohitr’i Betela.', 'ary ny tany azon’ny taranak’i josefa tamin’ny antsapaka dia nanomboka teo amin’ny reniranon’i jordana akaikin’i jeriko, nankany atsinanan’ny ranon’i jeriko, dia nandalo an’ilay tany efitra niakatra avy teo jeriko, ka nankany amin’ny faritra be tendrombohitr’i betela.'),
  ('6aadc75c42d2193f06839db4', '2026-09-18T23:21:00.169Z', '2026-09-18T23:21:00.169Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 16, 8, 'Avy teo Tapoa kosa ilay sisin-tany no niankandrefana nankany amin’ny Lohasahan’i Kana, ka nifarana tany amin’ny ranomasina. Izany no lova nozaraina tamin’ny fokon’i Efraima, araka ny fianakaviany avy.', 'avy teo tapoa kosa ilay sisin-tany no niankandrefana nankany amin’ny lohasahan’i kana, ka nifarana tany amin’ny ranomasina. izany no lova nozaraina tamin’ny fokon’i efraima, araka ny fianakaviany avy.'),
  ('6aadc75e5d3d4cc79c854c9a', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 2, 'Nahazo ny anjarany tamin’ny antsapaka koa ny sisa tamin’ny taranak’i Manase, araka ny fianakaviany avy. Ireto avy izany: Ny taranak’i Abi-ezera, ny taranak’i Heleka, ny taranak’i Asriela, ny taranak’i Sekema, ny taranak’i Hefera, ary ny taranak’i Semida. Ireo lehilahy ireo no taranak’i Manase zanak’i Josefa, araka ny fianakaviany avy.', 'nahazo ny anjarany tamin’ny antsapaka koa ny sisa tamin’ny taranak’i manase, araka ny fianakaviany avy. ireto avy izany: ny taranak’i abi-ezera, ny taranak’i heleka, ny taranak’i asriela, ny taranak’i sekema, ny taranak’i hefera, ary ny taranak’i semida. ireo lehilahy ireo no taranak’i manase zanak’i josefa, araka ny fianakaviany avy.'),
  ('6aadc75e5d3d4cc79c854ca5', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 13, 'Rehefa nihanahery kosa ny Israelita, dia nampanaoviny asa an-terivozona ny Kananita, fa tsy noroahiny daholo.', 'rehefa nihanahery kosa ny israelita, dia nampanaoviny asa an-terivozona ny kananita, fa tsy noroahiny daholo.'),
  ('6aadc75e5d3d4cc79c854ca3', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 11, 'Ireto avy ny tanàna nomena an’i Manase tao amin’ny faritry ny tanin’i Isakara sy Asera: Beti-sana sy ny tanàna niankina taminy, Ibleama sy ny tanàna niankina taminy, Dora sy ny mponina tao aminy ary ny tanàna niankina taminy, En-dora sy ny mponina tao aminy ary ny tanàna niankina taminy, Tanàka sy ny mponina tao aminy ary ny tanàna niankina taminy, ary Megido sy ny mponina tao aminy ary ny tanàna niankina taminy. An’i Manase ny telo amin’ireo faritra be havoana.', 'ireto avy ny tanàna nomena an’i manase tao amin’ny faritry ny tanin’i isakara sy asera: beti-sana sy ny tanàna niankina taminy, ibleama sy ny tanàna niankina taminy, dora sy ny mponina tao aminy ary ny tanàna niankina taminy, en-dora sy ny mponina tao aminy ary ny tanàna niankina taminy, tanàka sy ny mponina tao aminy ary ny tanàna niankina taminy, ary megido sy ny mponina tao aminy ary ny tanàna niankina taminy. an’i manase ny telo amin’ireo faritra be havoana.'),
  ('6aadc75e5d3d4cc79c854ca0', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 8, 'Dia lasan’i Manase ny tanin’i Tapoa. Fa an’ny taranak’i Efraima kosa ny tanànan’i Tapoa, eo amin’ny sisin-tanin’i Manase.', 'dia lasan’i manase ny tanin’i tapoa. fa an’ny taranak’i efraima kosa ny tanànan’i tapoa, eo amin’ny sisin-tanin’i manase.'),
  ('6aadc75e5d3d4cc79c854ca2', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 10, 'An’i Efraima ny atsimo, fa an’i Manase kosa ny avaratra, ary ny ranomasina no sisin-taniny. Tonga hatrany amin’ny faritry ny tanin’i Asera izy ireo tany avaratra, ary hatrany amin’ny faritry ny tanin’i Isakara tany atsinanana.', 'an’i efraima ny atsimo, fa an’i manase kosa ny avaratra, ary ny ranomasina no sisin-taniny. tonga hatrany amin’ny faritry ny tanin’i asera izy ireo tany avaratra, ary hatrany amin’ny faritry ny tanin’i isakara tany atsinanana.'),
  ('6aadc75e5d3d4cc79c854ca6', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 14, 'Ary hoy ny taranak’i Josefa tamin’i Josoa: “Fa maninona no anjara tany iray ihany no lova nomenao anay tamin’ny antsapaka? Izahay ange be dia be satria notahin’i Jehovah izahay hatramin’izao e!”', 'ary hoy ny taranak’i josefa tamin’i josoa: “fa maninona no anjara tany iray ihany no lova nomenao anay tamin’ny antsapaka? izahay ange be dia be satria notahin’i jehovah izahay hatramin’izao e!”'),
  ('6aadc75e5d3d4cc79c854ca4', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 12, 'Tsy vitan’ny taranak’i Manase anefa ny naka an’ireo tanàna ireo ho fananany. Ary tsy nety niala tao amin’izany tany izany ny Kananita.', 'tsy vitan’ny taranak’i manase anefa ny naka an’ireo tanàna ireo ho fananany. ary tsy nety niala tao amin’izany tany izany ny kananita.'),
  ('6aadc75e5d3d4cc79c854c9f', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 7, 'Ary ny sisin-tanin’i Manase dia nanomboka teo Asera ka hatrany Mikmeta tandrifin’i Sekema, ka nitohy nianatsimo hatrany amin’ny tanin’ny mponin’i En-Tapoa.', 'ary ny sisin-tanin’i manase dia nanomboka teo asera ka hatrany mikmeta tandrifin’i sekema, ka nitohy nianatsimo hatrany amin’ny tanin’ny mponin’i en-tapoa.'),
  ('6aadc75e5d3d4cc79c854ca9', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 17, 'Hoy àry i Josoa tamin’ny taranak’i Josefa, dia i Efraima sy Manase: “Be dia be ianareo sady mahery. Tsy ho iray monja ny anjaranareo,', 'hoy àry i josoa tamin’ny taranak’i josefa, dia i efraima sy manase: “be dia be ianareo sady mahery. tsy ho iray monja ny anjaranareo,'),
  ('6aadc75e5d3d4cc79c854c9e', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 6, 'satria ny zanakavavy tao amin’ny taranak’i Manase dia nahazo anjara lova hoatran’ny zanakalahy. Ary lasa fananan’ny sisa tamin’ny taranak’i Manase i Gileada.', 'satria ny zanakavavy tao amin’ny taranak’i manase dia nahazo anjara lova hoatran’ny zanakalahy. ary lasa fananan’ny sisa tamin’ny taranak’i manase i gileada.'),
  ('6aadc75e5d3d4cc79c854c9d', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 5, 'Mbola nahazo anjara tany folo i Manase, ankoatra an’i Gileada sy Basana, izay eny ampitan’i Jordana,', 'mbola nahazo anjara tany folo i manase, ankoatra an’i gileada sy basana, izay eny ampitan’i jordana,'),
  ('6aadc75e5d3d4cc79c854c9b', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 3, 'Fa i Zelofada zanak’i Hefera, zanak’i Gileada, zanak’i Makira, zanak’i Manase, kosa tsy nanana zanakalahy fa vavy ihany. Ireto avy ny anaran’izy ireo: Mahala, Noa, Hogla, Milka, ary Tirza.', 'fa i zelofada zanak’i hefera, zanak’i gileada, zanak’i makira, zanak’i manase, kosa tsy nanana zanakalahy fa vavy ihany. ireto avy ny anaran’izy ireo: mahala, noa, hogla, milka, ary tirza.'),
  ('6aadc75e5d3d4cc79c854caa', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 18, 'fa ho anareo koa ilay faritra be tendrombohitra manontolo. Marina fa rakotra ala ilay izy. Hokapainareo anefa ilay ala, dia io faritra io no ho sisin-taninareo. Fa horoahinareo ny Kananita, na dia matanjaka sy manana kalesin’ady misy lelan’antsy aza.”', 'fa ho anareo koa ilay faritra be tendrombohitra manontolo. marina fa rakotra ala ilay izy. hokapainareo anefa ilay ala, dia io faritra io no ho sisin-taninareo. fa horoahinareo ny kananita, na dia matanjaka sy manana kalesin’ady misy lelan’antsy aza.”'),
  ('6aadc75e5d3d4cc79c854c9c', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 4, 'Dia nankeo anatrehan’i Eleazara mpisorona sy Josoa zanak’i Nona ary ny mpiadidy izy ireo, ka niteny hoe: “I Jehovah efa nandidy an’i Mosesy hanome anay lova hoatran’ny nomeny an’ireo anadahinay.” Nomena lova hoatran’ireo rahalahin-drainy àry izy ireo, araka ny baikon’i Jehovah.', 'dia nankeo anatrehan’i eleazara mpisorona sy josoa zanak’i nona ary ny mpiadidy izy ireo, ka niteny hoe: “i jehovah efa nandidy an’i mosesy hanome anay lova hoatran’ny nomeny an’ireo anadahinay.” nomena lova hoatran’ireo rahalahin-drainy àry izy ireo, araka ny baikon’i jehovah.'),
  ('6aadc75e5d3d4cc79c854c99', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 1, 'Dia nahazo ny anjarany tamin’ny antsapaka ny fokon’i Manase satria izy no lahimatoan’i Josefa. I Makira lahimatoan’i Manase sady rain’i Gileada, no nahazo an’i Gileada sy Basana. Lehilahy mpiady mantsy izy.', 'dia nahazo ny anjarany tamin’ny antsapaka ny fokon’i manase satria izy no lahimatoan’i josefa. i makira lahimatoan’i manase sady rain’i gileada, no nahazo an’i gileada sy basana. lehilahy mpiady mantsy izy.'),
  ('6aadc75e5d3d4cc79c854ca7', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 15, 'Dia hoy i Josoa tamin’izy ireo: “Raha be dia be àry ianareo, dia mandehana kapao ny ala ao amin’ny tanin’ny Perizita sy ny Refaima mba hahazoanareo tany hipetrahana, satria kely loatra ho anareo ilay faritra be tendrombohitr’i Efraima.”', 'dia hoy i josoa tamin’izy ireo: “raha be dia be àry ianareo, dia mandehana kapao ny ala ao amin’ny tanin’ny perizita sy ny refaima mba hahazoanareo tany hipetrahana, satria kely loatra ho anareo ilay faritra be tendrombohitr’i efraima.”'),
  ('6aadc75e5d3d4cc79c854ca1', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 9, 'Ary nidina nankany amin’ny Lohasahan’i Kana, tany atsimon’ilay lohasaha, ilay sisin-tany. Nisy tanànan’i Efraima tao amin’ireo tanànan’i Manase. Ary teo avaratr’ilay lohasaha ny sisin-tanin’i Manase, ka nifarana tany amin’ny ranomasina.', 'ary nidina nankany amin’ny lohasahan’i kana, tany atsimon’ilay lohasaha, ilay sisin-tany. nisy tanànan’i efraima tao amin’ireo tanànan’i manase. ary teo avaratr’ilay lohasaha ny sisin-tanin’i manase, ka nifarana tany amin’ny ranomasina.'),
  ('6aadc75e5d3d4cc79c854ca8', '2026-09-18T23:21:02.087Z', '2026-09-18T23:21:02.087Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 17, 16, 'Ary hoy ny taranak’i Josefa: “Tsy ampy ho anay tokoa ilay faritra be tendrombohitra. Izao anefa: Manana kalesin’ady misy lelan’antsy ny Kananita rehetra mipetraka eny amin’ny lohasaha, na ireo any Beti-sana sy ny tanàna miankina aminy, na ireo eny amin’ny Lohasahan’i Jezirela.”', 'ary hoy ny taranak’i josefa: “tsy ampy ho anay tokoa ilay faritra be tendrombohitra. izao anefa: manana kalesin’ady misy lelan’antsy ny kananita rehetra mipetraka eny amin’ny lohasaha, na ireo any beti-sana sy ny tanàna miankina aminy, na ireo eny amin’ny lohasahan’i jezirela.”'),
  ('6aadc75f9a5c84f4d3031594', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 8, 'Dia niomana handeha ireo lehilahy hanao ny sarin’ilay tany, ary izao no baiko nomen’i Josoa azy ireo: “Mandehana tetezo ilay tany ka ataovy sary, dia miverena atỳ amiko. Ary hanao antsapaka ho anareo eo anatrehan’i Jehovah eto Silo aho.”', 'dia niomana handeha ireo lehilahy hanao ny sarin’ilay tany, ary izao no baiko nomen’i josoa azy ireo: “mandehana tetezo ilay tany ka ataovy sary, dia miverena atỳ amiko. ary hanao antsapaka ho anareo eo anatrehan’i jehovah eto silo aho.”'),
  ('6aadc75f9a5c84f4d303158f', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 3, 'Hoy àry i Josoa tamin’ny Israelita: “Mandra-pahoviana ianareo no hangataka andro hoatr’izao? Maninona ianareo no mbola tsy mandeha maka an’ilay tany nomen’i Jehovah Andriamanitry ny razambenareo anareo ihany?', 'hoy àry i josoa tamin’ny israelita: “mandra-pahoviana ianareo no hangataka andro hoatr’izao? maninona ianareo no mbola tsy mandeha maka an’ilay tany nomen’i jehovah andriamanitry ny razambenareo anareo ihany?'),
  ('6aadc75f9a5c84f4d303158d', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 1, 'Ary nivory tao Silo ny vahoaka manontolo, izany hoe ny Israelita. Dia natsangan’izy ireo tao ny tranolay fihaonana, satria efa resin’izy ireo ilay tany.', 'ary nivory tao silo ny vahoaka manontolo, izany hoe ny israelita. dia natsangan’izy ireo tao ny tranolay fihaonana, satria efa resin’izy ireo ilay tany.'),
  ('6aadc75f9a5c84f4d3031595', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 9, 'Dia lasa nitety an’ilay tany ireo lehilahy ireo. Nataon’izy ireo sary ilay tany dia nozarainy fito, ary nosoratany tao anaty boky ny mombamomba an’ireo tanàna tao. Dia niverina tany amin’i Josoa tao an-toby tany Silo izy ireo.', 'dia lasa nitety an’ilay tany ireo lehilahy ireo. nataon’izy ireo sary ilay tany dia nozarainy fito, ary nosoratany tao anaty boky ny mombamomba an’ireo tanàna tao. dia niverina tany amin’i josoa tao an-toby tany silo izy ireo.'),
  ('6aadc75f9a5c84f4d3031591', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 5, 'Tokony hifampizaran’izy ireo ilay tany, ka hozarainy fito. Hijanona any amin’ny faritry ny taniny any atsimo i Joda, ary ny taranak’i Josefa hijanona any amin’ny faritry ny taniny any avaratra.', 'tokony hifampizaran’izy ireo ilay tany, ka hozarainy fito. hijanona any amin’ny faritry ny taniny any atsimo i joda, ary ny taranak’i josefa hijanona any amin’ny faritry ny taniny any avaratra.'),
  ('6aadc75f9a5c84f4d303158e', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 2, 'Mbola nisy foko fito tsy nahazo ny lovany anefa tamin’ ny Israelita.', 'mbola nisy foko fito tsy nahazo ny lovany anefa tamin’ ny israelita.'),
  ('6aadc75f9a5c84f4d3031593', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 7, 'Tsy manana anjara eo aminareo anefa ny Levita, satria ny asa fisoronana naorin’i Jehovah no lovan’izy ireo. I Gada sy Robena ary ny antsasaky ny fokon’i Manase koa efa naka ny lovany teny ampita atsinanan’i Jordana, izay nomen’i Mosesy mpanompon’i Jehovah azy.”', 'tsy manana anjara eo aminareo anefa ny levita, satria ny asa fisoronana naorin’i jehovah no lovan’izy ireo. i gada sy robena ary ny antsasaky ny fokon’i manase koa efa naka ny lovany teny ampita atsinanan’i jordana, izay nomen’i mosesy mpanompon’i jehovah azy.”'),
  ('6aadc75f9a5c84f4d3031590', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 4, 'Andefaso telo lahy isam-poko aho mba hirahiko. Handeha hitety an’ilay tany ry zareo ka hanao ny sarin’izy io, araka ny lovan’izy ireo. Dia hiverina atỳ amiko izy ireo avy eo.', 'andefaso telo lahy isam-poko aho mba hirahiko. handeha hitety an’ilay tany ry zareo ka hanao ny sarin’izy io, araka ny lovan’izy ireo. dia hiverina atỳ amiko izy ireo avy eo.'),
  ('6aadc75f9a5c84f4d3031592', '2026-09-18T23:21:03.031Z', '2026-09-18T23:21:03.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 6, 'Dia izao no ataonareo: Ataovy sary ilay tany dia zarao fito. Ary ento atỳ amiko izany, ka eto aho no hanao antsapaka ho anareo, eo anatrehan’i Jehovah Andriamanitsika.', 'dia izao no ataonareo: ataovy sary ilay tany dia zarao fito. ary ento atỳ amiko izany, ka eto aho no hanao antsapaka ho anareo, eo anatrehan’i jehovah andriamanitsika.'),
  ('6aadc75f9a5c84f4d303159d', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 17, 'Ary nianavaratra izany ka tonga hatrany En-semesy, ary nitohy hatrany Gelilota tandrifin’ny fiakarana Adomima, dia nidina hatrany amin’ilay vaton’i Bohana zanak’i Robena.', 'ary nianavaratra izany ka tonga hatrany en-semesy, ary nitohy hatrany gelilota tandrifin’ny fiakarana adomima, dia nidina hatrany amin’ilay vaton’i bohana zanak’i robena.'),
  ('6aadc75f9a5c84f4d3031597', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 11, 'Natao ny antsapaka ka nahazo anjara ny fokon’i Benjamina, araka ny fianakaviany avy. Teo anelanelan’ny faritry ny tanin’ny taranak’i Joda sy ny an’ny taranak’i Josefa ny tany azony.', 'natao ny antsapaka ka nahazo anjara ny fokon’i benjamina, araka ny fianakaviany avy. teo anelanelan’ny faritry ny tanin’ny taranak’i joda sy ny an’ny taranak’i josefa ny tany azony.'),
  ('6aadc75f9a5c84f4d30315a3', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 23, 'Avima, Para, Ofra,', 'avima, para, ofra,'),
  ('6aadc75f9a5c84f4d30315a5', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 25, 'Anisany koa i Gibeona, Rama, Berota,', 'anisany koa i gibeona, rama, berota,'),
  ('6aadc75f9a5c84f4d30315a4', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 24, 'Kefara-hamony, Ofny, ary Geba, izany hoe tanàna 12 sy ny tanàna keliny.', 'kefara-hamony, ofny, ary geba, izany hoe tanàna 12 sy ny tanàna keliny.'),
  ('6aadc75f9a5c84f4d30315a2', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 22, 'Beti-araba, Zemaraima, Betela,', 'beti-araba, zemaraima, betela,'),
  ('6aadc75f9a5c84f4d3031596', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 10, 'Nanao antsapaka ho azy ireo tao Silo, teo anatrehan’i Jehovah, i Josoa avy eo. Tao no nizarany an’ilay tany ho an’ny Israelita, araka ny anjarany avy.', 'nanao antsapaka ho azy ireo tao silo, teo anatrehan’i jehovah, i josoa avy eo. tao no nizarany an’ilay tany ho an’ny israelita, araka ny anjarany avy.'),
  ('6aadc75f9a5c84f4d303159a', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 14, 'Avy teo amin’ilay tendrombohitra tandrifin’ny ilany atsimo amin’i Beti-horona no nivily nianatsimo ny ilany andrefan’ilay sisin-tany, ka nifarana tany Kiriata-bala, izany hoe Kiriata-jearima, tanànan’i Joda. Izany no ilany andrefana.', 'avy teo amin’ilay tendrombohitra tandrifin’ny ilany atsimo amin’i beti-horona no nivily nianatsimo ny ilany andrefan’ilay sisin-tany, ka nifarana tany kiriata-bala, izany hoe kiriata-jearima, tanànan’i joda. izany no ilany andrefana.'),
  ('6aadc75f9a5c84f4d30315a0', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 20, 'Ary i Jordana no sisin-tany amin’ny ilany atsinanana. Izany no sisin-tanin’ny lovan’ny taranak’i Benjamina, araka ny fianakaviany avy.', 'ary i jordana no sisin-tany amin’ny ilany atsinanana. izany no sisin-tanin’ny lovan’ny taranak’i benjamina, araka ny fianakaviany avy.'),
  ('6aadc75f9a5c84f4d303159f', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 19, 'dia nitohy hatrany amin’ny ilany avaratra amin’ny tehezan’i Beti-hogla, ka nifarana tany amin’ny helodrano avaratra amin’ny Ranomasin-tsira, eo amin’ny farany atsimo amin’ny Reniranon’i Jordana. Izany no sisin-tany atsimo.', 'dia nitohy hatrany amin’ny ilany avaratra amin’ny tehezan’i beti-hogla, ka nifarana tany amin’ny helodrano avaratra amin’ny ranomasin-tsira, eo amin’ny farany atsimo amin’ny reniranon’i jordana. izany no sisin-tany atsimo.'),
  ('6aadc75f9a5c84f4d303159e', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 18, 'Dia nitohy hatrany amin’ny ilany avaratra amin’ilay tehezan-kavoana tandrifin’i Araba izany, ka nidina nankany Araba,', 'dia nitohy hatrany amin’ny ilany avaratra amin’ilay tehezan-kavoana tandrifin’i araba izany, ka nidina nankany araba,'),
  ('6aadc75f9a5c84f4d303159c', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 16, 'Ary nidina nankany amin’ny sisin’ilay tendrombohitra tandrifin’ny Lohasahan’ny Taranak’i Hinoma izany. Eo amin’ny ilany avaratra amin’ny Lohasahan’ny Refaima io tendrombohitra io. Nidina nankany amin’ny Lohasahan’i Hinoma ilay sisin-tany, dia nankeo amin’ny ilany atsimo amin’ny tehezan-kavoanan’ny Jebosita, ary nidina nankany En-rogela.', 'ary nidina nankany amin’ny sisin’ilay tendrombohitra tandrifin’ny lohasahan’ny taranak’i hinoma izany. eo amin’ny ilany avaratra amin’ny lohasahan’ny refaima io tendrombohitra io. nidina nankany amin’ny lohasahan’i hinoma ilay sisin-tany, dia nankeo amin’ny ilany atsimo amin’ny tehezan-kavoanan’ny jebosita, ary nidina nankany en-rogela.'),
  ('6aadc75f9a5c84f4d30315a8', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 28, 'Zela, Ha-elefa, Jebosa, izany hoe Jerosalema, Gibea, ary Kiriata, izany hoe tanàna 14 sy ny tanàna keliny. Izany no lova nozaraina ho an’ny taranak’i Benjamina, araka ny fianakaviany avy.', 'zela, ha-elefa, jebosa, izany hoe jerosalema, gibea, ary kiriata, izany hoe tanàna 14 sy ny tanàna keliny. izany no lova nozaraina ho an’ny taranak’i benjamina, araka ny fianakaviany avy.'),
  ('6aadc75f9a5c84f4d30315a1', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 21, 'Ireto avy ny tanàna nozaraina tamin’ny fokon’i Benjamina, araka ny fianakaviany avy: Jeriko, Beti-hogla, Emeka-keziza,', 'ireto avy ny tanàna nozaraina tamin’ny fokon’i benjamina, araka ny fianakaviany avy: jeriko, beti-hogla, emeka-keziza,'),
  ('6aadc75f9a5c84f4d303159b', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 15, 'Ny ilany atsimo dia nanomboka teo amin’ny sisin’i Kiriata-jearima no niankandrefana, ary tonga hatreo amin’ny loharanon’i Neftoa.', 'ny ilany atsimo dia nanomboka teo amin’ny sisin’i kiriata-jearima no niankandrefana, ary tonga hatreo amin’ny loharanon’i neftoa.'),
  ('6aadc75f9a5c84f4d3031599', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 13, 'Avy teo ilay sisin-tany dia nitohy hatrany amin’ny tehezany atsimo amin’i Lozy, izany hoe Betela, ka nidina nankany Atarota-adara, teo amin’ilay tendrombohitra eo atsimon’i Beti-horona Ambany.', 'avy teo ilay sisin-tany dia nitohy hatrany amin’ny tehezany atsimo amin’i lozy, izany hoe betela, ka nidina nankany atarota-adara, teo amin’ilay tendrombohitra eo atsimon’i beti-horona ambany.'),
  ('6aadc75f9a5c84f4d30315a7', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 27, 'Rekema, Iripela, Tarala,', 'rekema, iripela, tarala,'),
  ('6aadc75f9a5c84f4d3031598', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 12, 'Nanomboka teo amin’ny Reniranon’i Jordana ny ilany avaratra amin’ny tanin’izy ireo, ka niakatra hatrany amin’ny tehezany avaratra amin’i Jeriko, dia niakatra niankandrefana nanaraka ny tendrombohitra, ary tonga hatrany an-tany efitr’i Beti-avena.', 'nanomboka teo amin’ny reniranon’i jordana ny ilany avaratra amin’ny tanin’izy ireo, ka niakatra hatrany amin’ny tehezany avaratra amin’i jeriko, dia niakatra niankandrefana nanaraka ny tendrombohitra, ary tonga hatrany an-tany efitr’i beti-avena.'),
  ('6aadc75f9a5c84f4d30315a6', '2026-09-18T23:21:03.032Z', '2026-09-18T23:21:03.032Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 18, 26, 'Mizpe, Kefira, Moza,', 'mizpe, kefira, moza,'),
  ('6aadc75fd7c26042a3b09ea3', '2026-09-18T23:21:03.419Z', '2026-09-18T23:21:03.419Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 19, 15, 'Katata, Nahalala, Simrona, Idala, ary Betlehema, izany hoe tanàna 12 sy ny tanàna keliny.', 'katata, nahalala, simrona, idala, ary betlehema, izany hoe tanàna 12 sy ny tanàna keliny.'),
  ('6aadc75fd7c26042a3b09e95', '2026-09-18T23:21:03.419Z', '2026-09-18T23:21:03.419Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 19, 1, 'Ary natao ny antsapaka faharoa ka nahazo anjara i Simeona, izany hoe ny fokon’i Simeona, araka ny fianakaviany avy. Tao amin’ny lovan’i Joda ny lovan’izy ireo.', 'ary natao ny antsapaka faharoa ka nahazo anjara i simeona, izany hoe ny fokon’i simeona, araka ny fianakaviany avy. tao amin’ny lovan’i joda ny lovan’izy ireo.'),
  ('6aadc75fd7c26042a3b09ea1', '2026-09-18T23:21:03.419Z', '2026-09-18T23:21:03.419Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 19, 13, 'dia nitohy niantsinanana tandrifin’ny fiposahan’ny masoandro hatrany Gata-hefera sy Ita-kazina, ary nankany Rimona, ka tonga hatrany Nea.', 'dia nitohy niantsinanana tandrifin’ny fiposahan’ny masoandro hatrany gata-hefera sy ita-kazina, ary nankany rimona, ka tonga hatrany nea.'),
  ('6aadc75fd7c26042a3b09ea8', '2026-09-18T23:21:03.419Z', '2026-09-18T23:21:03.419Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Josoa', 6, 19, 20, 'Rabita, Kisiona, Abeza,', 'rabita, kisiona, abeza,'),
