  ('6ab25a6d06246d0525e65eb1', '2026-09-22T10:37:33.283Z', '2026-09-22T10:37:33.283Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 4, 16, 'Ary ny zanakalahin’i Jehalalila dia i Zifa sy Zifaha sy Tiria ary Asarela.', 'ary ny zanakalahin’i jehalalila dia i zifa sy zifaha sy tiria ary asarela.'),
  ('6ab25a6d06246d0525e65ea5', '2026-09-22T10:37:33.283Z', '2026-09-22T10:37:33.283Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 4, 4, 'Penoela rain’i Gedora, ary Ezera rain’i Hosa. Ireo no zanak’i Hora, izay lahimatoan’i Efrata sady rain’i Betlehema.', 'penoela rain’i gedora, ary ezera rain’i hosa. ireo no zanak’i hora, izay lahimatoan’i efrata sady rain’i betlehema.'),
  ('6ab25a6d142473c77d8cf86b', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 25, 'Ary nivadika tamin’ilay Andriamanitry ny razany izy ireo, ka nanana fifandraisana mamoafady tamin’ny andriamanitry ny mponin’ilay tany, dia ny mponina efa naringan’Andriamanitra tsy ho eo anatrehan’izy ireo.', 'ary nivadika tamin’ilay andriamanitry ny razany izy ireo, ka nanana fifandraisana mamoafady tamin’ny andriamanitry ny mponin’ilay tany, dia ny mponina efa naringan’andriamanitra tsy ho eo anatrehan’izy ireo.'),
  ('6ab25a6d142473c77d8cf864', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 18, 'Ary tamin’ny taranak’i Robena sy ny Gadita ary ny antsasaky ny fokon’i Manase, dia nisy enimpolo sy fitonjato sy efatra arivo sy efatra alina no niditra tamin’ny tafika. Lehilahy nahery fo izy ireo, nirongo ampinga sy sabatra ary tsipìka, sady zatra ady.', 'ary tamin’ny taranak’i robena sy ny gadita ary ny antsasaky ny fokon’i manase, dia nisy enimpolo sy fitonjato sy efatra arivo sy efatra alina no niditra tamin’ny tafika. lehilahy nahery fo izy ireo, nirongo ampinga sy sabatra ary tsipìka, sady zatra ady.'),
  ('6ab25a6d142473c77d8cf863', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 17, 'Voasoratra tao amin’ny tetirazana avokoa izy ireo tamin’ny andron’i Jotama mpanjakan’ny Joda sy tamin’ny andron’i Jeroboama mpanjakan’ny Israely.', 'voasoratra tao amin’ny tetirazana avokoa izy ireo tamin’ny andron’i jotama mpanjakan’ny joda sy tamin’ny andron’i jeroboama mpanjakan’ny israely.'),
  ('6ab25a6d142473c77d8cf860', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 14, 'Ireo no zanakalahin’i Abihaila zanak’i Hory, zanak’i Jaroa, zanak’i Gileada, zanak’i Mikaela, zanak’i Jesisay, zanak’i Jado, zanak’i Boza.', 'ireo no zanakalahin’i abihaila zanak’i hory, zanak’i jaroa, zanak’i gileada, zanak’i mikaela, zanak’i jesisay, zanak’i jado, zanak’i boza.'),
  ('6ab25a6d142473c77d8cf855', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 3, 'Ireto avy ny zanakalahin’i Robena lahimatoan’i Israely: Hanoka sy Palo sy Hezrona ary Karmy.', 'ireto avy ny zanakalahin’i robena lahimatoan’i israely: hanoka sy palo sy hezrona ary karmy.'),
  ('6ab25a6d142473c77d8cf854', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 2, 'Ary ambony noho ny rahalahiny i Joda, ka izy no niavian’ilay mpitarika, nefa lasan’i Josefa kosa ny zon’ny lahimatoa.', 'ary ambony noho ny rahalahiny i joda, ka izy no niavian’ilay mpitarika, nefa lasan’i josefa kosa ny zon’ny lahimatoa.'),
  ('6ab25a6d142473c77d8cf85e', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 12, 'I Joela no lohany, ary i Safama no faharoa, avy eo i Janay sy Safata tany Basana.', 'i joela no lohany, ary i safama no faharoa, avy eo i janay sy safata tany basana.'),
  ('6ab25a6d142473c77d8cf85b', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 9, 'Ary nonina tany atsinanana koa izy, hatrany amin’ny fidirana amin’ny tany efitra eo amoron’ny reniranon’i Eofrata. Lasa maro be mantsy ny biby fiompiny tany Gileada.', 'ary nonina tany atsinanana koa izy, hatrany amin’ny fidirana amin’ny tany efitra eo amoron’ny reniranon’i eofrata. lasa maro be mantsy ny biby fiompiny tany gileada.'),
  ('6ab25a6d142473c77d8cf85a', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 8, 'sy Bela zanak’i Azaza, zanak’i Sema, zanak’i Joela. Ary i Bela nonina tany Aroera ka hatrany Nebo sy Bala-meona.', 'sy bela zanak’i azaza, zanak’i sema, zanak’i joela. ary i bela nonina tany aroera ka hatrany nebo sy bala-meona.'),
  ('6ab25a6d142473c77d8cf859', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 7, 'Ary ireo rahalahiny, araka ny fianakaviany avy izay voasoratra tao amin’ny tetirazana, araka ny taranaka misy azy, dia i Jeiela no lohany, avy eo Zakaria,', 'ary ireo rahalahiny, araka ny fianakaviany avy izay voasoratra tao amin’ny tetirazana, araka ny taranaka misy azy, dia i jeiela no lohany, avy eo zakaria,'),
  ('6ab25a6d142473c77d8cf867', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 21, 'Koa nobaboiny ny biby fiompin’ireny, dia rameva dimy alina, sy ondry dimy alina sy roa hetsy, ary ampondra roa arivo, mbamin’ny olona iray hetsy.', 'koa nobaboiny ny biby fiompin’ireny, dia rameva dimy alina, sy ondry dimy alina sy roa hetsy, ary ampondra roa arivo, mbamin’ny olona iray hetsy.'),
  ('6ab25a6d142473c77d8cf865', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 19, 'Ary niady tamin’ny Hagarita sy tamin’i Jetora sy Nafisy ary Nodaba izy ireo.', 'ary niady tamin’ny hagarita sy tamin’i jetora sy nafisy ary nodaba izy ireo.'),
  ('6ab25a6d142473c77d8cf85d', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 11, 'Ary ny taranak’i Gada kosa nonina tandrifin’izy ireo, tany Basana ka hatrany Saleka.', 'ary ny taranak’i gada kosa nonina tandrifin’izy ireo, tany basana ka hatrany saleka.'),
  ('6ab25a6d142473c77d8cf85c', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 10, 'Ary niady tamin’ny Hagarita izy ireo tamin’ny andron’i Saoly, ka naharesy azy. Koa nonina an-tranolay nanerana ny faritra atsinanan’i Gileada izy ireo.', 'ary niady tamin’ny hagarita izy ireo tamin’ny andron’i saoly, ka naharesy azy. koa nonina an-tranolay nanerana ny faritra atsinanan’i gileada izy ireo.'),
  ('6ab25a6d142473c77d8cf856', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 4, 'Ary i Joela niteraka an’i Semaia, ary i Semaia niteraka an’i Goga, ary i Goga niteraka an’i Simey,', 'ary i joela niteraka an’i semaia, ary i semaia niteraka an’i goga, ary i goga niteraka an’i simey,'),
  ('6ab25a6d142473c77d8cf868', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 22, 'Maro ny olona ripaka, satria an’ilay tena Andriamanitra ilay ady. Ary nonina tany izy ireo ka nisolo toerana an’ireny, mandra-pahatongan’ny sesitany.', 'maro ny olona ripaka, satria an’ilay tena andriamanitra ilay ady. ary nonina tany izy ireo ka nisolo toerana an’ireny, mandra-pahatongan’ny sesitany.'),
  ('6ab25a6d142473c77d8cf85f', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 13, 'Ary ny rahalahiny anisan’ny fianakaviambe avy amin’ireo rainy, dia i Mikaela, Mesolama sy Sheba, Joray, Jakana, Zia, ary Ebera, ka fito ireo.', 'ary ny rahalahiny anisan’ny fianakaviambe avy amin’ireo rainy, dia i mikaela, mesolama sy sheba, joray, jakana, zia, ary ebera, ka fito ireo.'),
  ('6ab25a6d142473c77d8cf857', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 5, 'ary i Simey niteraka an’i Mika, ary i Mika niteraka an’i Reaia, ary i Reaia niteraka an’i Bala,', 'ary i simey niteraka an’i mika, ary i mika niteraka an’i reaia, ary i reaia niteraka an’i bala,'),
  ('6ab25a6d142473c77d8cf869', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 23, 'Ary ny taranaky ny antsasaky ny fokon’i Manase kosa nonina hatrany Basana ka hatrany Bala-hermona sy Senira ary ny Tendrombohitra Hermona. Lasa maro be koa izy ireo.', 'ary ny taranaky ny antsasaky ny fokon’i manase kosa nonina hatrany basana ka hatrany bala-hermona sy senira ary ny tendrombohitra hermona. lasa maro be koa izy ireo.'),
  ('6ab25a6d142473c77d8cf861', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 15, 'Ary i Ahia dia zanak’i Abdiela, zanak’i Gony, lohan’ny fianakaviambe avy amin’ireo rainy.', 'ary i ahia dia zanak’i abdiela, zanak’i gony, lohan’ny fianakaviambe avy amin’ireo rainy.'),
  ('6ab25a6d142473c77d8cf858', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 6, 'ary i Bala niteraka an’i Bera izay nataon’i Tilgato-pilnesera, mpanjakan’i Asyria, sesitany. Mpiadidy teo amin’ny Robenita i Bera.', 'ary i bala niteraka an’i bera izay nataon’i tilgato-pilnesera, mpanjakan’i asyria, sesitany. mpiadidy teo amin’ny robenita i bera.'),
  ('6ab25a6d142473c77d8cf86c', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 26, 'Koa nampirisihin’ilay Andriamanitry ny Israely i Pola mpanjakan’i Asyria, dia i Tilgato-pilnesera mpanjakan’i Asyria, mba hanao sesitany ny Robenita sy ny Gadita ary ny antsasaky ny fokon’i Manase. Dia nentin’izy io nankany Hala sy Habora sy Hara ary tany amin’ny reniranon’i Gozana izy ireo, ka mbola any mandraka androany.', 'koa nampirisihin’ilay andriamanitry ny israely i pola mpanjakan’i asyria, dia i tilgato-pilnesera mpanjakan’i asyria, mba hanao sesitany ny robenita sy ny gadita ary ny antsasaky ny fokon’i manase. dia nentin’izy io nankany hala sy habora sy hara ary tany amin’ny reniranon’i gozana izy ireo, ka mbola any mandraka androany.'),
  ('6ab25a6d142473c77d8cf866', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 20, 'Ary nahazo fanampiana izy ireo tamin’ny fanafihany ny Hagarita sy izay rehetra niandany taminy, ka natolotra teo an-tanany ireny. Niantso vonjy tamin’Andriamanitra mantsy izy ireo tamin’ilay ady, ka nohenoiny ny fitalahoany satria natoky azy izy ireo.', 'ary nahazo fanampiana izy ireo tamin’ny fanafihany ny hagarita sy izay rehetra niandany taminy, ka natolotra teo an-tanany ireny. niantso vonjy tamin’andriamanitra mantsy izy ireo tamin’ilay ady, ka nohenoiny ny fitalahoany satria natoky azy izy ireo.'),
  ('6ab25a6d142473c77d8cf862', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 16, 'Dia nonina tany Gileada sy Basana sy tany amin’ireo tanàna niankina taminy ary tany amin’ny kijanan’i Sarôna rehetra hatrany amin’ny sisiny indrindra, izy ireo.', 'dia nonina tany gileada sy basana sy tany amin’ireo tanàna niankina taminy ary tany amin’ny kijanan’i sarôna rehetra hatrany amin’ny sisiny indrindra, izy ireo.'),
  ('6ab25a6d142473c77d8cf853', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 1, 'Ary i Robena no lahimatoan’i Israely. Izy no lahimatoa, nefa nolotoiny ny farafaran-drainy. Dia nomena ny zanak’i Josefa, zanak’i Israely, ny zony amin’ny maha lahimatoa. Koa tsy voasoratra ho manana ny zon’ny lahimatoa izy tao amin’ny tetirazana.', 'ary i robena no lahimatoan’i israely. izy no lahimatoa, nefa nolotoiny ny farafaran-drainy. dia nomena ny zanak’i josefa, zanak’i israely, ny zony amin’ny maha lahimatoa. koa tsy voasoratra ho manana ny zon’ny lahimatoa izy tao amin’ny tetirazana.'),
  ('6ab25a6d142473c77d8cf86a', '2026-09-22T10:37:33.718Z', '2026-09-22T10:37:33.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 5, 24, 'Ary ireto avy ny lohan’ny fianakaviambe avy amin’ireo rainy: Efera, Jisy, Eliela, Azriela, Jeremia, Hodavia, ary Jadiela, dia lehilahy natanjaka sy nahery fo ary nalaza, izay lohan’ny fianakaviambe avy amin’ireo rainy.', 'ary ireto avy ny lohan’ny fianakaviambe avy amin’ireo rainy: efera, jisy, eliela, azriela, jeremia, hodavia, ary jadiela, dia lehilahy natanjaka sy nahery fo ary nalaza, izay lohan’ny fianakaviambe avy amin’ireo rainy.'),
  ('6ab25a6ec0c58389fac23656', '2026-09-22T10:37:34.495Z', '2026-09-22T10:37:34.495Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 6, 1, 'Ary ny zanakalahin’i Levy dia i Gersona sy Kehata ary Merary.', 'ary ny zanakalahin’i levy dia i gersona sy kehata ary merary.'),
  ('6ab25a6ec0c58389fac23657', '2026-09-22T10:37:34.495Z', '2026-09-22T10:37:34.495Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 6, 2, 'Ary ny zanakalahin’i Kehata dia i Amrama sy Jizara sy Hebrona ary Oziela.', 'ary ny zanakalahin’i kehata dia i amrama sy jizara sy hebrona ary oziela.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25a6ec0c58389fac23658', '2026-09-22T10:37:34.495Z', '2026-09-22T10:37:34.495Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 6, 3, 'Ary ny zanak’i Amrama dia i Arona sy Mosesy ary koa Miriama. Ary ny zanakalahin’i Arona dia i Nadaba sy Abiho sy Eleazara ary Itamara.', 'ary ny zanak’i amrama dia i arona sy mosesy ary koa miriama. ary ny zanakalahin’i arona dia i nadaba sy abiho sy eleazara ary itamara.'),
  ('6ab25a6ec0c58389fac23659', '2026-09-22T10:37:34.495Z', '2026-09-22T10:37:34.495Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 6, 4, 'Ary i Eleazara niteraka an’i Finehasa, ary i Finehasa niteraka an’i Abisoa,', 'ary i eleazara niteraka an’i finehasa, ary i finehasa niteraka an’i abisoa,'),
  ('6ab25a6ec0c58389fac2365a', '2026-09-22T10:37:34.495Z', '2026-09-22T10:37:34.495Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 6, 5, 'ary i Abisoa niteraka an’i Boky, ary i Boky niteraka an’i Ozy,', 'ary i abisoa niteraka an’i boky, ary i boky niteraka an’i ozy,'),
  ('6ab25a6ec0c58389fac2365b', '2026-09-22T10:37:34.495Z', '2026-09-22T10:37:34.495Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 6, 6, 'ary i Ozy niteraka an’i Zerahia, ary i Zerahia niteraka an’i Meraiota,', 'ary i ozy niteraka an’i zerahia, ary i zerahia niteraka an’i meraiota,'),
  ('6ab25a6ec0c58389fac2365c', '2026-09-22T10:37:34.495Z', '2026-09-22T10:37:34.495Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', '1 Tantara', 13, 6, 7, 'ary i Meraiota niteraka an’i Amaria, ary i Amaria niteraka an’i Ahitoba,', 'ary i meraiota niteraka an’i amaria, ary i amaria niteraka an’i ahitoba,'),
