  ('6ab25a9985acdbcc9d486bdc', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 7, 'Nomen’izy ireo vola ny mpipai-bato sy ny mpanao asa tanana. Ary nomeny sakafo sy zava-pisotro ary menaka ny olona avy any Sidona sy Tyro. Ireo mantsy no nandefa hazo sedera teny amin’ny ranomasina avy any Libàna ka hatrany Jopa, araka ny fanomezan-dalana nomen’i Kyrosy mpanjakan’i Persa azy.', 'nomen’izy ireo vola ny mpipai-bato sy ny mpanao asa tanana. ary nomeny sakafo sy zava-pisotro ary menaka ny olona avy any sidona sy tyro. ireo mantsy no nandefa hazo sedera teny amin’ny ranomasina avy any libàna ka hatrany jopa, araka ny fanomezan-dalana nomen’i kyrosy mpanjakan’i persa azy.'),
  ('6ab25a9985acdbcc9d486bda', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 5, 'Nataon’izy ireo koa ny fanatitra dorana atolotra tsy tapaka, sy ny fanatitra fanao amin’ny tsinam-bolana sy amin’ny fotoanan’ny fety masina rehetra ho an’i Jehovah, ary ny fanatitra nomen’izay te hanolotra fanatitra an-tsitrapo ho an’i Jehovah.', 'nataon’izy ireo koa ny fanatitra dorana atolotra tsy tapaka, sy ny fanatitra fanao amin’ny tsinam-bolana sy amin’ny fotoanan’ny fety masina rehetra ho an’i jehovah, ary ny fanatitra nomen’izay te hanolotra fanatitra an-tsitrapo ho an’i jehovah.'),
  ('6ab25a9985acdbcc9d486be2', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 13, 'Koa tsy hay intsony ny nanavaka ny feon’izay faly sy nihorakoraka sy izay nitomany, satria nitabataba be ny olona ka heno hatrany lavitra be ilay feo.', 'koa tsy hay intsony ny nanavaka ny feon’izay faly sy nihorakoraka sy izay nitomany, satria nitabataba be ny olona ka heno hatrany lavitra be ilay feo.'),
  ('6ab25a9985acdbcc9d486bde', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 9, 'Dia niara-niasa mba hanara-maso an’ireo niasa tao amin’ny tranon’ilay tena Andriamanitra i Jesoa sy ny zanany sy ny rahalahiny, Kadmiela sy ny zanany, izay taranak’i Joda, ary ny taranak’i Henadada sy ny zanak’ireo ary ny rahalahiny, izay samy Levita.', 'dia niara-niasa mba hanara-maso an’ireo niasa tao amin’ny tranon’ilay tena andriamanitra i jesoa sy ny zanany sy ny rahalahiny, kadmiela sy ny zanany, izay taranak’i joda, ary ny taranak’i henadada sy ny zanak’ireo ary ny rahalahiny, izay samy levita.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25a9985acdbcc9d486bdb', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 6, 'Koa nanolotra sorona dorana ho an’i Jehovah izy ireo, nanomboka tamin’ny andro voalohan’ny volana fahafito, na dia mbola tsy napetraka aza ny fototry ny tempolin’i Jehovah.', 'koa nanolotra sorona dorana ho an’i jehovah izy ireo, nanomboka tamin’ny andro voalohan’ny volana fahafito, na dia mbola tsy napetraka aza ny fototry ny tempolin’i jehovah.'),
  ('6ab25a9985acdbcc9d486bdd', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 8, 'Tamin’ny volana faharoan’ny taona faharoa, taorian’ny nahatongavan’izy ireo teo amin’ny tranon’ilay tena Andriamanitra tany Jerosalema, dia nanomboka an’ilay asa i Zerobabela zanak’i Sealtiela, sy Jesoa zanak’i Jozadaka, sy ny rahalahin’izy ireo hafa, dia ny mpisorona sy ny Levita ary izay rehetra babo ka niverina tany Jerosalema. Notendren’ izy ireo ho mpanara-maso ny asa tao an-tranon’i Jehovah ny Levita 20 taona no ho miakatra.', 'tamin’ny volana faharoan’ny taona faharoa, taorian’ny nahatongavan’izy ireo teo amin’ny tranon’ilay tena andriamanitra tany jerosalema, dia nanomboka an’ilay asa i zerobabela zanak’i sealtiela, sy jesoa zanak’i jozadaka, sy ny rahalahin’izy ireo hafa, dia ny mpisorona sy ny levita ary izay rehetra babo ka niverina tany jerosalema. notendren’ izy ireo ho mpanara-maso ny asa tao an-tranon’i jehovah ny levita 20 taona no ho miakatra.'),
  ('6ab25a9985acdbcc9d486bd6', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 1, 'Efa samy tany amin’ny tanànany avy ny Israelita, tamin’ny volana fahafito. Dia niray saina izy ireo ka nivory tao Jerosalema.', 'efa samy tany amin’ny tanànany avy ny israelita, tamin’ny volana fahafito. dia niray saina izy ireo ka nivory tao jerosalema.'),
  ('6ab25a9985acdbcc9d486bd8', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 3, 'Dia nataon’izy ireo teo amin’ilay toerany taloha ilay alitara, na dia natahotra ny mponina manodidina aza izy ireo. Ary nanolotra sorona dorana ho an’i Jehovah teo ambonin’ilay alitara izy ireo, dia ny sorona dorana amin’ny maraina sy hariva.', 'dia nataon’izy ireo teo amin’ilay toerany taloha ilay alitara, na dia natahotra ny mponina manodidina aza izy ireo. ary nanolotra sorona dorana ho an’i jehovah teo ambonin’ilay alitara izy ireo, dia ny sorona dorana amin’ny maraina sy hariva.'),
  ('6ab25a9985acdbcc9d486be1', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 12, 'Be dia be tamin’ny mpisorona sy ny Levita ary ny lohan’ireo fianakaviambe, izany hoe tamin’ireo lehilahy zokiolona nahita an’ilay trano taloha, no nigogogogo nitomany rehefa nahita hoe tafapetraka ny fototr’ilay trano. Be dia be koa anefa ny olon-kafa nihoby mafy.', 'be dia be tamin’ny mpisorona sy ny levita ary ny lohan’ireo fianakaviambe, izany hoe tamin’ireo lehilahy zokiolona nahita an’ilay trano taloha, no nigogogogo nitomany rehefa nahita hoe tafapetraka ny fototr’ilay trano. be dia be koa anefa ny olon-kafa nihoby mafy.'),
  ('6ab25a9985acdbcc9d486bdf', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 10, 'Ary nandatsaka ny fototry ny tempolin’i Jehovah ny mpanorina. Dia nijoro teo mba hidera an’i Jehovah ny mpisorona sy ny Levita taranak’i Asafa, araka ny toromarik’i Davida mpanjakan’ny Israely. Nanao akanjona mpisorona ny mpisorona tamin’izay sady nitondra trompetra, fa ny Levita kosa nitondra kipantsona.', 'ary nandatsaka ny fototry ny tempolin’i jehovah ny mpanorina. dia nijoro teo mba hidera an’i jehovah ny mpisorona sy ny levita taranak’i asafa, araka ny toromarik’i davida mpanjakan’ny israely. nanao akanjona mpisorona ny mpisorona tamin’izay sady nitondra trompetra, fa ny levita kosa nitondra kipantsona.'),
  ('6ab25a9985acdbcc9d486bd9', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 4, 'Dia nankalaza ny Fetin’ny Trano Rantsankazo araka izay voasoratra izy ireo, ka nanao sorona dorana isan’andro, araka ny isa notakina ho an’ny andro tsirairay.', 'dia nankalaza ny fetin’ny trano rantsankazo araka izay voasoratra izy ireo, ka nanao sorona dorana isan’andro, araka ny isa notakina ho an’ny andro tsirairay.'),
  ('6ab25a9985acdbcc9d486be0', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 11, 'Ary nanao hira nifamaly izy ireo ka nidera sy nisaotra an’i Jehovah, “fa tsara izy; tia ny Israely izy sady tsy mivadika aminy mandrakizay.” Dia nihoby mafy nidera an’i Jehovah ny olona rehetra, satria tafapetraka ny fototry ny tranon’i Jehovah.', 'ary nanao hira nifamaly izy ireo ka nidera sy nisaotra an’i jehovah, “fa tsara izy; tia ny israely izy sady tsy mivadika aminy mandrakizay.” dia nihoby mafy nidera an’i jehovah ny olona rehetra, satria tafapetraka ny fototry ny tranon’i jehovah.'),
  ('6ab25a9985acdbcc9d486bd7', '2026-09-22T10:38:17.012Z', '2026-09-22T10:38:17.012Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 3, 2, 'Ary nanorina ny alitaran’ilay Andriamanitry ny Israely i Jesoa zanak’i Jozadaka, sy ny mpisorona hafa, ary Zerobabela zanak’i Sealtiela sy ireo rahalahiny. Amin’izay izy ireo ho afaka hanolotra sorona dorana eo ambonin’izy io, araka izay voasoratra ao amin’ny Lalàn’i Mosesy, lehilahin’Andriamanitra.', 'ary nanorina ny alitaran’ilay andriamanitry ny israely i jesoa zanak’i jozadaka, sy ny mpisorona hafa, ary zerobabela zanak’i sealtiela sy ireo rahalahiny. amin’izay izy ireo ho afaka hanolotra sorona dorana eo ambonin’izy io, araka izay voasoratra ao amin’ny lalàn’i mosesy, lehilahin’andriamanitra.'),
  ('6ab25a9a9f2b1f97b10a153f', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 13, 'Tokony ho fantatry ny mpanjaka fa raha voaorina indray io tanàna io ary vita ny mandany, dia tsy handoa hetra na haba na hetran-dalana izy ireo, ka hiteraka fatiantoka ho an’ny tahirim-bolam-panjakana izany.', 'tokony ho fantatry ny mpanjaka fa raha voaorina indray io tanàna io ary vita ny mandany, dia tsy handoa hetra na haba na hetran-dalana izy ireo, ka hiteraka fatiantoka ho an’ny tahirim-bolam-panjakana izany.'),
  ('6ab25a9a9f2b1f97b10a153a', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 8, '* Nanoratra taratasy hiampangana ny mponin’i Jerosalema tany amin’i Artaksersesy Mpanjaka i Rehoma lehiben’ny tompon’andraiki-panjakana sy Simsay mpanoratra. Izao ilay taratasy:', '* nanoratra taratasy hiampangana ny mponin’i jerosalema tany amin’i artaksersesy mpanjaka i rehoma lehiben’ny tompon’andraiki-panjakana sy simsay mpanoratra. izao ilay taratasy:'),
  ('6ab25a9a9f2b1f97b10a1538', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 6, 'Ary nanoratra taratasy hiampangana ny mponin’i Joda sy Jerosalema izy ireny, raha vao nanjaka i Ahasoerosy.', 'ary nanoratra taratasy hiampangana ny mponin’i joda sy jerosalema izy ireny, raha vao nanjaka i ahasoerosy.'),
  ('6ab25a9a9f2b1f97b10a153b', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 9, '—Ireto avy no nanoratra: I Rehoma lehiben’ny tompon’andraiki-panjakana sy Simsay mpanoratra, sy ny mpiara-miasa aminy sasany, ny mpitsara, ny governora lefitra, ny mpitan-tsoratra, ny olona any Ereka, ny Babylonianina, ny mponin’i Sosa, izany hoe ny Elamita,', '—ireto avy no nanoratra: i rehoma lehiben’ny tompon’andraiki-panjakana sy simsay mpanoratra, sy ny mpiara-miasa aminy sasany, ny mpitsara, ny governora lefitra, ny mpitan-tsoratra, ny olona any ereka, ny babylonianina, ny mponin’i sosa, izany hoe ny elamita,'),
  ('6ab25a9a9f2b1f97b10a1536', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 4, 'Ary nanakivy sy nanaketraka ny mponin’i Joda foana ny olona manodidina, amin’izay izy ireo tsy hazoto hanorina intsony.', 'ary nanakivy sy nanaketraka ny mponin’i joda foana ny olona manodidina, amin’izay izy ireo tsy hazoto hanorina intsony.'),
  ('6ab25a9a9f2b1f97b10a153d', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 11, 'ity ny dika mitovy amin’ilay taratasy nalefan’izy ireo tany aminy.— “Ho an’i Artaksersesy Mpanjaka. Manoratra ho anao ny mpanomponao atỳ amin’ny faritra Ampitan’ny Renirano.', 'ity ny dika mitovy amin’ilay taratasy nalefan’izy ireo tany aminy.— “ho an’i artaksersesy mpanjaka. manoratra ho anao ny mpanomponao atỳ amin’ny faritra ampitan’ny renirano.'),
  ('6ab25a9a9f2b1f97b10a1533', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 1, 'Henon’ny fahavalon’ny Joda sy Benjamina fa nanorina tempoly ho an’i Jehovah Andriamanitry ny Israely ny olona nody avy tany an-tsesitany.', 'henon’ny fahavalon’ny joda sy benjamina fa nanorina tempoly ho an’i jehovah andriamanitry ny israely ny olona nody avy tany an-tsesitany.'),
  ('6ab25a9a9f2b1f97b10a1541', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 15, 'Amin’izay ianao mba mikaroka ao amin’ny boky mirakitra ny tantaran’ny razambenao. Dia ho hitanao ao amin’ilay boky ka ho fantatrao fa tanànan’ny mpikomy izy io, ary mitondra fatiantoka ho an’ny mpanjaka sy ny faritany. Efa hatry ny ela be no nisy mpitarika fikomiana tao. Dia izany no antony nandravana an’io tanàna io.', 'amin’izay ianao mba mikaroka ao amin’ny boky mirakitra ny tantaran’ny razambenao. dia ho hitanao ao amin’ilay boky ka ho fantatrao fa tanànan’ny mpikomy izy io, ary mitondra fatiantoka ho an’ny mpanjaka sy ny faritany. efa hatry ny ela be no nisy mpitarika fikomiana tao. dia izany no antony nandravana an’io tanàna io.'),
  ('6ab25a9a9f2b1f97b10a1535', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 3, 'Hoy anefa i Zerobabela sy Jesoa ary ny sisa tamin’ireo lohan’ny fianakaviamben’ny Israely: “Tsy manan-jo hiaraka aminay hanorina trano ho an’ny Andriamanitray ianareo. Fa izahay ihany no hanorina azy ho an’i Jehovah Andriamanitry ny Israely, araka ny didin’i Kyrosy mpanjakan’i Persa.”', 'hoy anefa i zerobabela sy jesoa ary ny sisa tamin’ireo lohan’ny fianakaviamben’ny israely: “tsy manan-jo hiaraka aminay hanorina trano ho an’ny andriamanitray ianareo. fa izahay ihany no hanorina azy ho an’i jehovah andriamanitry ny israely, araka ny didin’i kyrosy mpanjakan’i persa.”'),
  ('6ab25a9a9f2b1f97b10a1540', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 14, 'Izahay mantsy mandray karama avy any an-dapa, ary tsy mety aminay koa ny mijery fotsiny hoe ho matiantoka ny mpanjaka. Dia mandefa an’izao taratasy izao izahay mba hampahafantarana an’izany amin’ny mpanjaka.', 'izahay mantsy mandray karama avy any an-dapa, ary tsy mety aminay koa ny mijery fotsiny hoe ho matiantoka ny mpanjaka. dia mandefa an’izao taratasy izao izahay mba hampahafantarana an’izany amin’ny mpanjaka.'),
  ('6ab25a9a9f2b1f97b10a1534', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 2, 'Dia nanatona an’i Zerobabela sy ireo lohan’ny fianakaviambe avy hatrany izy ireo, ka nilaza hoe: “Avelao izahay hiara-manorina aminareo. Fa manompo an’ilay Andriamanitrareo koa izahay, hoatr’anareo ihany. Ary izy no anoloranay sorona, efa hatramin’ny andron’i Esara-hadona mpanjakan’i Asyria, ilay nitondra anay tatỳ.”', 'dia nanatona an’i zerobabela sy ireo lohan’ny fianakaviambe avy hatrany izy ireo, ka nilaza hoe: “avelao izahay hiara-manorina aminareo. fa manompo an’ilay andriamanitrareo koa izahay, hoatr’anareo ihany. ary izy no anoloranay sorona, efa hatramin’ny andron’i esara-hadona mpanjakan’i asyria, ilay nitondra anay tatỳ.”'),
  ('6ab25a9a9f2b1f97b10a1542', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 16, 'Ampahafantarinay anao, ry mpanjaka, fa raha voaorina indray io tanàna io ka vita ny mandany, dia tsy ho voafehinao intsony ny faritra atỳ Ampitan’ny Renirano.”', 'ampahafantarinay anao, ry mpanjaka, fa raha voaorina indray io tanàna io ka vita ny mandany, dia tsy ho voafehinao intsony ny faritra atỳ ampitan’ny renirano.”'),
  ('6ab25a9a9f2b1f97b10a1539', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 7, 'Nanoratra ho an’i Artaksersesy mpanjakan’i Persa koa ry Bislama sy Mitredata sy Tabela ary ny mpiara-miasa aminy sasany, tamin’ny andron’i Artaksersesy. Nadikany tamin’ny fiteny aramianina ilay taratasy, ka soratra aramianina no nanoratany azy.', 'nanoratra ho an’i artaksersesy mpanjakan’i persa koa ry bislama sy mitredata sy tabela ary ny mpiara-miasa aminy sasany, tamin’ny andron’i artaksersesy. nadikany tamin’ny fiteny aramianina ilay taratasy, ka soratra aramianina no nanoratany azy.'),
  ('6ab25a9a9f2b1f97b10a1537', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 5, 'Nanakarama mpanolo-tsaina hanohitra azy ireo koa izy ireny tamin’ny andro rehetra nanjakan’i Kyrosy mpanjakan’i Persa, ka hatramin’ny nanjakan’i Dariosy mpanjakan’i Persa, mba tsy ho tanteraka ilay tetikasa.', 'nanakarama mpanolo-tsaina hanohitra azy ireo koa izy ireny tamin’ny andro rehetra nanjakan’i kyrosy mpanjakan’i persa, ka hatramin’ny nanjakan’i dariosy mpanjakan’i persa, mba tsy ho tanteraka ilay tetikasa.'),
  ('6ab25a9a9f2b1f97b10a153e', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 12, 'Tokony ho fantatry ny mpanjaka fa ireo Jiosy niala tany aminao ka nankatỳ aminay dia efa tonga any Jerosalema. Manorina indray an’ilay tanànan’ny mpikomy sy ny olon-dratsy izy ireo, ary efa mamita ny manda sady manamboatra ny fototra.', 'tokony ho fantatry ny mpanjaka fa ireo jiosy niala tany aminao ka nankatỳ aminay dia efa tonga any jerosalema. manorina indray an’ilay tanànan’ny mpikomy sy ny olon-dratsy izy ireo, ary efa mamita ny manda sady manamboatra ny fototra.'),
  ('6ab25a9a9f2b1f97b10a153c', '2026-09-22T10:38:18.101Z', '2026-09-22T10:38:18.101Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 10, 'ny sisa tavela amin’ireo firenena natao sesitany, izay napetrak’i Asnapara lehibe sady mendri-kaja tany amin’ireo tanànan’i Samaria, ary ny sisa tavela tany amin’ny faritra Ampitan’ny Renirano. Ary', 'ny sisa tavela amin’ireo firenena natao sesitany, izay napetrak’i asnapara lehibe sady mendri-kaja tany amin’ireo tanànan’i samaria, ary ny sisa tavela tany amin’ny faritra ampitan’ny renirano. ary'),
  ('6ab25a9a9f2b1f97b10a1548', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 22, 'Tandremo sao hataonareo tsirambina izany, sao vao mainka matiantoka ny mpanjaka.”', 'tandremo sao hataonareo tsirambina izany, sao vao mainka matiantoka ny mpanjaka.”'),
  ('6ab25a9a9f2b1f97b10a1549', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 23, 'Rehefa voavaky teo anatrehan’i Rehoma sy Simsay mpanoratra ary ny namany ny dika mitovy amin’ilay taratasin’i Artaksersesy Mpanjaka, dia lasa haingana izy ireo nankany amin’ny Jiosy tany Jerosalema. Dia notereny hanajanona an’ilay asa ny Jiosy.', 'rehefa voavaky teo anatrehan’i rehoma sy simsay mpanoratra ary ny namany ny dika mitovy amin’ilay taratasin’i artaksersesy mpanjaka, dia lasa haingana izy ireo nankany amin’ny jiosy tany jerosalema. dia notereny hanajanona an’ilay asa ny jiosy.'),
  ('6ab25a9a9f2b1f97b10a1547', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 21, 'Koa omeo baiko ireo lehilahy ireo mba hanajanona an’ilay asa, ka tsy hanorina an’io tanàna io indray raha tsy izaho no manome baiko.', 'koa omeo baiko ireo lehilahy ireo mba hanajanona an’ilay asa, ka tsy hanorina an’io tanàna io indray raha tsy izaho no manome baiko.'),
  ('6ab25a9a9f2b1f97b10a1546', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 20, 'Nisy mpanjaka nahery tao Jerosalema, ary ny faritra Ampitan’ny Renirano manontolo no nanjakan’izy ireo, ka nandoavana hetra sy haba ary hetran-dalana izy ireo.', 'nisy mpanjaka nahery tao jerosalema, ary ny faritra ampitan’ny renirano manontolo no nanjakan’izy ireo, ka nandoavana hetra sy haba ary hetran-dalana izy ireo.'),
  ('6ab25a9a9f2b1f97b10a1544', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 18, 'Efa voavaky tsara teto anatrehako ilay taratasy nalefanareo tatỳ aminay.', 'efa voavaky tsara teto anatrehako ilay taratasy nalefanareo tatỳ aminay.'),
  ('6ab25a9a9f2b1f97b10a154a', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 24, 'Tamin’izay àry ilay asa tao amin’ny tranon’Andriamanitra tany Jerosalema no nijanona. Mbola niato ilay izy hatramin’ny taona faharoa nanjakan’i Dariosy mpanjakan’i Persa.', 'tamin’izay àry ilay asa tao amin’ny tranon’andriamanitra tany jerosalema no nijanona. mbola niato ilay izy hatramin’ny taona faharoa nanjakan’i dariosy mpanjakan’i persa.'),
  ('6ab25a9a9f2b1f97b10a1543', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 17, 'Izao no taratasy nalefan’ny mpanjaka ho an’i Rehoma lehiben’ny tompon’andraiki-panjakana, sy Simsay mpanoratra, sy ny mpiara-miasa aminy sasany nipetraka tany Samaria, ary ny olona sisa tavela tatỳ amin’ny faritra Ampitan’ny Renirano: “Miarahaba anareo aho!', 'izao no taratasy nalefan’ny mpanjaka ho an’i rehoma lehiben’ny tompon’andraiki-panjakana, sy simsay mpanoratra, sy ny mpiara-miasa aminy sasany nipetraka tany samaria, ary ny olona sisa tavela tatỳ amin’ny faritra ampitan’ny renirano: “miarahaba anareo aho!'),
  ('6ab25a9a9f2b1f97b10a1545', '2026-09-22T10:38:18.102Z', '2026-09-22T10:38:18.102Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 4, 19, 'Koa nampanao fikarohana aho, ka hita fa efa hatry ny ela be io tanàna io no nanohitra mpanjaka sady nikomy imbetsaka.', 'koa nampanao fikarohana aho, ka hita fa efa hatry ny ela be io tanàna io no nanohitra mpanjaka sady nikomy imbetsaka.'),
  ('6ab25a9b082adbdc79e9de19', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 15, 'Hoy i Kyrosy taminy: “Ento ireo fitaovana ireo ka apetraho ao amin’ilay tempoly any Jerosalema. Dia aoreno indray eo amin’ilay toerany taloha ny tranon’Andriamanitra.”', 'hoy i kyrosy taminy: “ento ireo fitaovana ireo ka apetraho ao amin’ilay tempoly any jerosalema. dia aoreno indray eo amin’ilay toerany taloha ny tranon’andriamanitra.”'),
  ('6ab25a9b082adbdc79e9de12', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 8, 'Tsara ho fantatry ny mpanjaka fa nankany amin’ny faritanin’i Joda izahay, tany an-tranon’ilay Andriamanitra tena miavaka. Misy manorina izy io, ka vato lehibe nakodiadia no anaovana azy, ary efa napetraka ireo hazo ao anaty rindrina. Mazoto manao an’ilay asa ny olona, ary mandroso haingana ilay izy.', 'tsara ho fantatry ny mpanjaka fa nankany amin’ny faritanin’i joda izahay, tany an-tranon’ilay andriamanitra tena miavaka. misy manorina izy io, ka vato lehibe nakodiadia no anaovana azy, ary efa napetraka ireo hazo ao anaty rindrina. mazoto manao an’ilay asa ny olona, ary mandroso haingana ilay izy.'),
  ('6ab25a9b082adbdc79e9de17', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 13, 'Tamin’ny taona voalohany nanjakan’i Kyrosy mpanjakan’i Babylona anefa, dia nanome baiko mba hanorenana indray an’ity tranon’Andriamanitra ity i Kyrosy Mpanjaka.', 'tamin’ny taona voalohany nanjakan’i kyrosy mpanjakan’i babylona anefa, dia nanome baiko mba hanorenana indray an’ity tranon’andriamanitra ity i kyrosy mpanjaka.'),
  ('6ab25a9b082adbdc79e9de10', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 6, 'Intỳ ny dika mitovy amin’ilay taratasy ho an’i Dariosy Mpanjaka, izay nalefan’i Tatenay Governora tatỳ amin’ny faritra Ampitan’ny Renirano, sy Setara-bozenay, ary ny mpiara-miasa aminy, izay governora lefitra tatỳ amin’ny faritra Ampitan’ny Renirano.', 'intỳ ny dika mitovy amin’ilay taratasy ho an’i dariosy mpanjaka, izay nalefan’i tatenay governora tatỳ amin’ny faritra ampitan’ny renirano, sy setara-bozenay, ary ny mpiara-miasa aminy, izay governora lefitra tatỳ amin’ny faritra ampitan’ny renirano.'),
  ('6ab25a9b082adbdc79e9de11', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 7, 'Nandefasan’izy ireo tatitra izy, ka izao no voasoratra tao: “Ho an’i Dariosy Mpanjaka: “Fiadanana anie ho anao!', 'nandefasan’izy ireo tatitra izy, ka izao no voasoratra tao: “ho an’i dariosy mpanjaka: “fiadanana anie ho anao!'),
  ('6ab25a9b082adbdc79e9de16', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 12, 'Nampahatezitra an’ilay Andriamanitry ny lanitra anefa ny razambenay, ka nataony resin’i Nebokadnezara Kaldeanina, mpanjakan’i Babylona. Dia noravan’i Nebokadnezara ity trano ity, ary nataony sesitany tany Babylona ny vahoaka.', 'nampahatezitra an’ilay andriamanitry ny lanitra anefa ny razambenay, ka nataony resin’i nebokadnezara kaldeanina, mpanjakan’i babylona. dia noravan’i nebokadnezara ity trano ity, ary nataony sesitany tany babylona ny vahoaka.'),
  ('6ab25a9b082adbdc79e9de0e', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 4, 'Hoy koa izy ireo: “Iza avy no anaran’ny lehilahy manao an’io trano io?”', 'hoy koa izy ireo: “iza avy no anaran’ny lehilahy manao an’io trano io?”'),
  ('6ab25a9b082adbdc79e9de0c', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 2, 'Tamin’izay i Zerobabela zanak’i Sealtiela sy Jesoa zanak’i Jozadaka no nanomboka nanorina indray an’ilay tranon’Andriamanitra tany Jerosalema. Ary nisy mpaminanin’Andriamanitra niaraka taminy sy nanampy azy.', 'tamin’izay i zerobabela zanak’i sealtiela sy jesoa zanak’i jozadaka no nanomboka nanorina indray an’ilay tranon’andriamanitra tany jerosalema. ary nisy mpaminanin’andriamanitra niaraka taminy sy nanampy azy.'),
  ('6ab25a9b082adbdc79e9de15', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 11, '“Dia izao no navalin’izy ireo anay: ‘Mpanompon’ilay Andriamanitry ny lanitra sy ny tany izahay, ka manorina indray an’ilay trano namboarina taona maro lasa izay. Mpanjaka niavaka iray teo amin’ny Israely no nanorina sy namita azy io.', '“dia izao no navalin’izy ireo anay: ‘mpanompon’ilay andriamanitry ny lanitra sy ny tany izahay, ka manorina indray an’ilay trano namboarina taona maro lasa izay. mpanjaka niavaka iray teo amin’ny israely no nanorina sy namita azy io.'),
  ('6ab25a9b082adbdc79e9de14', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 10, 'Nanontanianay koa ny anaran’izy ireo mba hahafahanay hanoratra ny anaran’izay lehilahy mitarika azy, ka hampahafantarinay anao.', 'nanontanianay koa ny anaran’izy ireo mba hahafahanay hanoratra ny anaran’izay lehilahy mitarika azy, ka hampahafantarinay anao.'),
  ('6ab25a9b082adbdc79e9de0f', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 5, 'Nitsinjo an’ireo anti-panahin’ny Jiosy anefa Andriamanitra, ka tsy nisy nahasakana azy ireo tsy hanohy an’ilay asa, mandra-pandefa tatitra tany amin’i Dariosy sy mandra-pahazo valin-taratasy momba an’izany.', 'nitsinjo an’ireo anti-panahin’ny jiosy anefa andriamanitra, ka tsy nisy nahasakana azy ireo tsy hanohy an’ilay asa, mandra-pandefa tatitra tany amin’i dariosy sy mandra-pahazo valin-taratasy momba an’izany.'),
  ('6ab25a9b082adbdc79e9de18', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 14, 'Navoakan’i Kyrosy Mpanjaka avy tao amin’ny tempolin’i Babylona koa ny fitaovana volamena sy volafotsy tato amin’ny tranon’Andriamanitra. Efa nalain’i Nebokadnezara tato amin’ny tempolin’i Jerosalema ireny, dia nentiny tany amin’ny tempolin’i Babylona. Nomena an’i Sesbazara ireny, dia ilay lehilahy nataon’i Kyrosy governora.', 'navoakan’i kyrosy mpanjaka avy tao amin’ny tempolin’i babylona koa ny fitaovana volamena sy volafotsy tato amin’ny tranon’andriamanitra. efa nalain’i nebokadnezara tato amin’ny tempolin’i jerosalema ireny, dia nentiny tany amin’ny tempolin’i babylona. nomena an’i sesbazara ireny, dia ilay lehilahy nataon’i kyrosy governora.'),
  ('6ab25a9b082adbdc79e9de0d', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 3, 'Tamin’izay fotoana izay dia tonga teo aminy i Tatenay Governora tatỳ amin’ny faritra Ampitan’ny Renirano sy Setara-bozenay ary ny mpiara-miasa aminy, ka nanontany hoe: “Iza no nanome baiko anareo hanorina an’io trano io sy handrafitra an’io zavatra io?”', 'tamin’izay fotoana izay dia tonga teo aminy i tatenay governora tatỳ amin’ny faritra ampitan’ny renirano sy setara-bozenay ary ny mpiara-miasa aminy, ka nanontany hoe: “iza no nanome baiko anareo hanorina an’io trano io sy handrafitra an’io zavatra io?”'),
  ('6ab25a9b082adbdc79e9de0b', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 1, 'Ary naminany tamin’ny Jiosy tany Joda sy Jerosalema i Hagay mpaminany sy Zakaria mpaminany zafikelin’i Ido. Naminany tamin’ny anaran’ilay Andriamanitry ny Israely nitarika azy ireo izy roa lahy.', 'ary naminany tamin’ny jiosy tany joda sy jerosalema i hagay mpaminany sy zakaria mpaminany zafikelin’i ido. naminany tamin’ny anaran’ilay andriamanitry ny israely nitarika azy ireo izy roa lahy.'),
  ('6ab25a9b082adbdc79e9de13', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 9, 'Dia nanontanianay ny anti-panahy teo amin’izy ireo hoe: ‘Iza no nanome baiko anareo hanorina an’io trano io sy handrafitra an’io zavatra io?’', 'dia nanontanianay ny anti-panahy teo amin’izy ireo hoe: ‘iza no nanome baiko anareo hanorina an’io trano io sy handrafitra an’io zavatra io?’'),
  ('6ab25a9b082adbdc79e9de1b', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 17, '“Raha mety amin’ny mpanjaka àry, dia maniraha olona hikaroka ao amin’ny fitehirizana ny zava-tsarobidin’ny mpanjaka ao Babylona, mba hahitana raha tena namoaka baiko tokoa i Kyrosy Mpanjaka hoe haorina indray io tranon’Andriamanitra any Jerosalema io. Dia aleo alefa atỳ aminay izay tapaky ny mpanjaka momba an’izany.”', '“raha mety amin’ny mpanjaka àry, dia maniraha olona hikaroka ao amin’ny fitehirizana ny zava-tsarobidin’ny mpanjaka ao babylona, mba hahitana raha tena namoaka baiko tokoa i kyrosy mpanjaka hoe haorina indray io tranon’andriamanitra any jerosalema io. dia aleo alefa atỳ aminay izay tapaky ny mpanjaka momba an’izany.”'),
  ('6ab25a9b082adbdc79e9de1a', '2026-09-22T10:38:19.628Z', '2026-09-22T10:38:19.628Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 5, 16, 'Dia tonga io Sesbazara io ka nandatsaka ny fototry ny tranon’Andriamanitra teto Jerosalema. Efa naorina ilay trano tamin’izay, nefa mbola tsy vita hatramin’izao.’', 'dia tonga io sesbazara io ka nandatsaka ny fototry ny tranon’andriamanitra teto jerosalema. efa naorina ilay trano tamin’izay, nefa mbola tsy vita hatramin’izao.’'),
  ('6ab25a9c66af6a7b47c62964', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 1, 'Tamin’izay i Dariosy Mpanjaka no nanome baiko, ka nisy nanao fikarohana tao amin’ny trano fitehirizana taratasy, izay nametrahana ny harena notehirizina tany Babylona.', 'tamin’izay i dariosy mpanjaka no nanome baiko, ka nisy nanao fikarohana tao amin’ny trano fitehirizana taratasy, izay nametrahana ny harena notehirizina tany babylona.'),
  ('6ab25a9c66af6a7b47c62965', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 2, 'Dia nisy horonam-boky hita tao amin’ilay tanàna voaro mafy tao Ekbatana, tany amin’ny faritanin’i Media, ka izao no didy voasoratra tao:', 'dia nisy horonam-boky hita tao amin’ilay tanàna voaro mafy tao ekbatana, tany amin’ny faritanin’i media, ka izao no didy voasoratra tao:'),
  ('6ab25a9c66af6a7b47c62979', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 22, 'Nankalaza ny Fetin’ny Mofo Tsy Misy Lalivay nandritra ny fito andro koa izy ireo sady falifaly be. Nataon’i Jehovah mantsy izay hahafaly azy ireo. Nataony tsara fanahy tamin’izy ireo koa ny mpanjakan’i Asyria, ka nanampy azy ireo tamin’ilay asa fanorenana ny tranon’ilay tena Andriamanitra, dia ny Andriamanitry ny Israely.', 'nankalaza ny fetin’ny mofo tsy misy lalivay nandritra ny fito andro koa izy ireo sady falifaly be. nataon’i jehovah mantsy izay hahafaly azy ireo. nataony tsara fanahy tamin’izy ireo koa ny mpanjakan’i asyria, ka nanampy azy ireo tamin’ilay asa fanorenana ny tranon’ilay tena andriamanitra, dia ny andriamanitry ny israely.'),
  ('6ab25a9c66af6a7b47c62967', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 4, 'Ny rindrina kosa ataovy amin’ny vato ngezabe, izay nakodiadia haka toerana. Ataovy telo andalana ireo vato ireo ary iray andalana ny vatan-kazo. Avy ao amin’ny tranon’ny mpanjaka ihany no handoavana ny lany.', 'ny rindrina kosa ataovy amin’ny vato ngezabe, izay nakodiadia haka toerana. ataovy telo andalana ireo vato ireo ary iray andalana ny vatan-kazo. avy ao amin’ny tranon’ny mpanjaka ihany no handoavana ny lany.'),
  ('6ab25a9c66af6a7b47c62966', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 3, '“Tamin’ny taona voalohany nanjakan’i Kyrosy Mpanjaka, dia nanome an’izao baiko izao momba ny tranon’Andriamanitra any Jerosalema i Kyrosy Mpanjaka: ‘Aoreno indray ilay trano ka ao no hanaovana sorona. Ataovy mafy tsara ny fototr’ilay trano. Tokony hatao 60 hakiho ny haavony, ary 60 hakiho ny sakany.', '“tamin’ny taona voalohany nanjakan’i kyrosy mpanjaka, dia nanome an’izao baiko izao momba ny tranon’andriamanitra any jerosalema i kyrosy mpanjaka: ‘aoreno indray ilay trano ka ao no hanaovana sorona. ataovy mafy tsara ny fototr’ilay trano. tokony hatao 60 hakiho ny haavony, ary 60 hakiho ny sakany.'),
  ('6ab25a9c66af6a7b47c6296e', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 11, 'Manome baiko koa aho fa izay tsy manaraka an’izao didy izao, dia hakana hazo iray ny tranony ary hahantona eo amin’ilay hazo izy. Ny tranony kosa hatao kabinem-bahoaka.', 'manome baiko koa aho fa izay tsy manaraka an’izao didy izao, dia hakana hazo iray ny tranony ary hahantona eo amin’ilay hazo izy. ny tranony kosa hatao kabinem-bahoaka.'),
  ('6ab25a9c66af6a7b47c62968', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 5, 'Tokony haverina koa ny fitaovana volamena sy volafotsy tao an-tranon’Andriamanitra, izay nalain’i Nebokadnezara tao amin’ny tempoly tany Jerosalema ka nentiny tany Babylona. Amin’izay dia haverina amin’ny toerany ao amin’ny tempoly any Jerosalema ireny, dia hapetraka ao an-tranon’Andriamanitra.’', 'tokony haverina koa ny fitaovana volamena sy volafotsy tao an-tranon’andriamanitra, izay nalain’i nebokadnezara tao amin’ny tempoly tany jerosalema ka nentiny tany babylona. amin’izay dia haverina amin’ny toerany ao amin’ny tempoly any jerosalema ireny, dia hapetraka ao an-tranon’andriamanitra.’'),
  ('6ab25a9c66af6a7b47c62977', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 20, 'Samy nanadio ny tenany ny mpisorona sy ny Levita, ka nadio daholo. Koa novonoin’izy ireo ny biby hatao sorona hankalazana ny Paska, ho an’ny olona rehetra avy natao sesitany sy ho an’ireo mpisorona hafa ary ho an’ny tenany.', 'samy nanadio ny tenany ny mpisorona sy ny levita, ka nadio daholo. koa novonoin’izy ireo ny biby hatao sorona hankalazana ny paska, ho an’ny olona rehetra avy natao sesitany sy ho an’ireo mpisorona hafa ary ho an’ny tenany.'),
  ('6ab25a9c66af6a7b47c62976', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 19, 'Nankalaza ny Paska ny olona avy natao sesitany, tamin’ny andro faha-14 amin’ny volana voalohany.', 'nankalaza ny paska ny olona avy natao sesitany, tamin’ny andro faha-14 amin’ny volana voalohany.'),
  ('6ab25a9c66af6a7b47c62975', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 18, 'Dia notendren’izy ireo araka ny sokajiny avy ny mpisorona, ary araka ny fizarany avy ny Levita mba hanao ny fanompoana an’Andriamanitra tao Jerosalema, araka izay voasoratra ao amin’ny bokin’i Mosesy.', 'dia notendren’izy ireo araka ny sokajiny avy ny mpisorona, ary araka ny fizarany avy ny levita mba hanao ny fanompoana an’andriamanitra tao jerosalema, araka izay voasoratra ao amin’ny bokin’i mosesy.'),
  ('6ab25a9c66af6a7b47c6296d', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 10, 'Amin’izay izy ireo ho afaka hanolotra fanatitra tsy tapaka, izay mampifaly an’ilay Andriamanitry ny lanitra, sady ho afaka hivavaka ho an’ny mpanjaka sy ny zanany.', 'amin’izay izy ireo ho afaka hanolotra fanatitra tsy tapaka, izay mampifaly an’ilay andriamanitry ny lanitra, sady ho afaka hivavaka ho an’ny mpanjaka sy ny zanany.'),
  ('6ab25a9c66af6a7b47c62970', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 13, 'Tonga dia nanatanteraka ny baiko rehetra nomen’i Dariosy Mpanjaka i Tatenay governoran’ny faritra Ampitan’ny Renirano sy Setara-bozenay ary ny mpiara-miasa aminy.', 'tonga dia nanatanteraka ny baiko rehetra nomen’i dariosy mpanjaka i tatenay governoran’ny faritra ampitan’ny renirano sy setara-bozenay ary ny mpiara-miasa aminy.'),
  ('6ab25a9c66af6a7b47c6296f', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 12, 'Ary ilay Andriamanitra izay nametraka ny anarany any Jerosalema anie, hanongana an’izay mpanjaka na olona mitady handika an’izao didy izao sy mitady handrava an’ilay tranon’Andriamanitra any! Izaho Dariosy no manome baiko, ka ataovy avy hatrany izany.”', 'ary ilay andriamanitra izay nametraka ny anarany any jerosalema anie, hanongana an’izay mpanjaka na olona mitady handika an’izao didy izao sy mitady handrava an’ilay tranon’andriamanitra any! izaho dariosy no manome baiko, ka ataovy avy hatrany izany.”'),
  ('6ab25a9c66af6a7b47c62974', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 17, 'Izao avy no natolotr’izy ireo tamin’ny fitokanana an’io tranon’Andriamanitra io: Omby 100, ondrilahy 200, zanak’ondry 400, ary osilahy 12 ho fanatitra noho ny ota ho an’ny Israely rehetra, mifanaraka amin’ny isan’ny fokon’ny Israely.', 'izao avy no natolotr’izy ireo tamin’ny fitokanana an’io tranon’andriamanitra io: omby 100, ondrilahy 200, zanak’ondry 400, ary osilahy 12 ho fanatitra noho ny ota ho an’ny israely rehetra, mifanaraka amin’ny isan’ny fokon’ny israely.'),
  ('6ab25a9c66af6a7b47c6296c', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 9, 'Tsy maintsy homena azy ireo foana isan’andro koa izay ilainy, dia vantotr’ombilahy sy ondrilahy ary zanak’ondry atao fanatitra dorana ho an’ilay Andriamanitry ny lanitra, varimbazaha, sira, divay, ary menaka, araka izay lazain’ireo mpisorona any Jerosalema.', 'tsy maintsy homena azy ireo foana isan’andro koa izay ilainy, dia vantotr’ombilahy sy ondrilahy ary zanak’ondry atao fanatitra dorana ho an’ilay andriamanitry ny lanitra, varimbazaha, sira, divay, ary menaka, araka izay lazain’ireo mpisorona any jerosalema.'),
  ('6ab25a9c66af6a7b47c6296a', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 7, 'Aza sakantsakanana ny asa ao amin’io tranon’Andriamanitra io. Fa hanorina indray ny tranon’Andriamanitra eo amin’ny toerany taloha ny governora sy ny anti-panahin’ny Jiosy.', 'aza sakantsakanana ny asa ao amin’io tranon’andriamanitra io. fa hanorina indray ny tranon’andriamanitra eo amin’ny toerany taloha ny governora sy ny anti-panahin’ny jiosy.'),
  ('6ab25a9c66af6a7b47c62969', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 6, '“Aza midikiditra amin’izany àry ianareo, ry Tatenay governoran’ny faritra Ampitan’ny Renirano sy Setara-bozenay ary ny mpiara-miasa aminareo, dia ireo governora lefitra any amin’ny faritra Ampitan’ny Renirano.', '“aza midikiditra amin’izany àry ianareo, ry tatenay governoran’ny faritra ampitan’ny renirano sy setara-bozenay ary ny mpiara-miasa aminareo, dia ireo governora lefitra any amin’ny faritra ampitan’ny renirano.'),
  ('6ab25a9c66af6a7b47c62978', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 21, 'Dia nihinana tamin’izany ny Israelita nody avy any an-tsesitany, sy ny olona rehetra niaraka tamin’izy ireo. Efa tsy nanao intsony an’izay zavatra mandoto fanaon’ny firenena teo amin’ilay tany ireny olona ireny, mba hanompoany an’i Jehovah Andriamanitry ny Israely.', 'dia nihinana tamin’izany ny israelita nody avy any an-tsesitany, sy ny olona rehetra niaraka tamin’izy ireo. efa tsy nanao intsony an’izay zavatra mandoto fanaon’ny firenena teo amin’ilay tany ireny olona ireny, mba hanompoany an’i jehovah andriamanitry ny israely.'),
  ('6ab25a9c66af6a7b47c62973', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 16, 'Dia nitokana an’ilay tranon’Andriamanitra ny Israelita, izany hoe ny mpisorona sy ny Levita ary ny sisa tavela tamin’ny olona avy natao sesitany. Faly be izy ireo tamin’izay.', 'dia nitokana an’ilay tranon’andriamanitra ny israelita, izany hoe ny mpisorona sy ny levita ary ny sisa tavela tamin’ny olona avy natao sesitany. faly be izy ireo tamin’izay.'),
  ('6ab25a9c66af6a7b47c6296b', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 8, 'Manome an’izao baiko izao koa aho ny amin’izay tokony hataonareo amin’ireo anti-panahin’ny Jiosy ireo, mba hanorenana indray an’io tranon’Andriamanitra io: Tokony homena an’ireo lehilahy ireo avy hatrany ny vola holanina amin’ilay asa, mba hitohy foana ilay izy. Avy amin’ny trano fitehirizana ny harenan’ny mpanjaka ilay izy no halaina, izany hoe avy amin’ny hetra voangona any amin’ny faritra Ampitan’ny Renirano.', 'manome an’izao baiko izao koa aho ny amin’izay tokony hataonareo amin’ireo anti-panahin’ny jiosy ireo, mba hanorenana indray an’io tranon’andriamanitra io: tokony homena an’ireo lehilahy ireo avy hatrany ny vola holanina amin’ilay asa, mba hitohy foana ilay izy. avy amin’ny trano fitehirizana ny harenan’ny mpanjaka ilay izy no halaina, izany hoe avy amin’ny hetra voangona any amin’ny faritra ampitan’ny renirano.'),
  ('6ab25a9c66af6a7b47c62972', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 15, 'Vitany tanteraka ilay trano tamin’ny andro fahatelon’ny volana Adara, tamin’ny taona fahenina nanjakan’i Dariosy Mpanjaka.', 'vitany tanteraka ilay trano tamin’ny andro fahatelon’ny volana adara, tamin’ny taona fahenina nanjakan’i dariosy mpanjaka.'),
  ('6ab25a9c66af6a7b47c62971', '2026-09-22T10:38:20.030Z', '2026-09-22T10:38:20.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 6, 14, 'Ary nanohy an’ilay asa fanorenana foana ny anti-panahin’ny Jiosy, ka nandroso tsara ilay izy. Nampahery azy ireo mantsy ny faminanian’i Hagay mpaminany sy Zakaria zafikelin’i Ido. Dia vitan’izy ireo ilay trano, noho ny baikon’ilay Andriamanitry ny Israely sy ny baikon’i Kyrosy sy Dariosy ary Artaksersesy mpanjakan’i Persa.', 'ary nanohy an’ilay asa fanorenana foana ny anti-panahin’ny jiosy, ka nandroso tsara ilay izy. nampahery azy ireo mantsy ny faminanian’i hagay mpaminany sy zakaria zafikelin’i ido. dia vitan’izy ireo ilay trano, noho ny baikon’ilay andriamanitry ny israely sy ny baikon’i kyrosy sy dariosy ary artaksersesy mpanjakan’i persa.'),
  ('6ab25a9cbebb1ae30b79474e', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 14, 'Fa irahin’ny mpanjaka sy ny mpanolo-tsainy fito ianao mba hanadihady any Joda sy Jerosalema, raha ampiharina tokoa ny Lalàn’ny Andriamanitrao, izay nankinina taminao.', 'fa irahin’ny mpanjaka sy ny mpanolo-tsainy fito ianao mba hanadihady any joda sy jerosalema, raha ampiharina tokoa ny lalàn’ny andriamanitrao, izay nankinina taminao.'),
  ('6ab25a9cbebb1ae30b794742', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 2, 'zanak’i Saloma, zanak’i Zadoka, zanak’i Ahitoba,', 'zanak’i saloma, zanak’i zadoka, zanak’i ahitoba,'),
  ('6ab25a9cbebb1ae30b794757', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 23, 'Tanteraho daholo ny baikon’ilay Andriamanitry ny lanitra ho an’ny tranony. Tokony hafana fo ianareo rehefa manao an’izany, amin’izay ilay Andriamanitry ny lanitra tsy ho tezitra amin’ny vahoaka ao amin’ny fanjakan’ny mpanjaka sy amin’ny zanaky ny mpanjaka.', 'tanteraho daholo ny baikon’ilay andriamanitry ny lanitra ho an’ny tranony. tokony hafana fo ianareo rehefa manao an’izany, amin’izay ilay andriamanitry ny lanitra tsy ho tezitra amin’ny vahoaka ao amin’ny fanjakan’ny mpanjaka sy amin’ny zanaky ny mpanjaka.'),
  ('6ab25a9cbebb1ae30b79475c', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 28, 'Sady tia ahy Izy no tsy nivadika tamiko, ka nataony nahazo sitraka tamin’ny mpanjaka sy ny mpanolo-tsainy ary ny andriana rehetra miaraka amin’ny mpanjaka aho. Lasa be herim-po àry aho, satria nanampy ahy ny tanan’i Jehovah Andriamanitro. Ary novoriko ireo lehilahy mpitarika teo amin’ny Israely mba hiara-miakatra amiko.', 'sady tia ahy izy no tsy nivadika tamiko, ka nataony nahazo sitraka tamin’ny mpanjaka sy ny mpanolo-tsainy ary ny andriana rehetra miaraka amin’ny mpanjaka aho. lasa be herim-po àry aho, satria nanampy ahy ny tanan’i jehovah andriamanitro. ary novoriko ireo lehilahy mpitarika teo amin’ny israely mba hiara-miakatra amiko.'),
  ('6ab25a9cbebb1ae30b79475a', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 26, 'Fa na iza na iza tsy mety mankatò ny Lalàn’ny Andriamanitrao sy ny lalàn’ny mpanjaka, dia tokony hampiharina aminy avy hatrany ny didim-pitsarana, ka hovonoina ho faty izy na horoahina, na hampandoavina sazy na hogadraina.”', 'fa na iza na iza tsy mety mankatò ny lalàn’ny andriamanitrao sy ny lalàn’ny mpanjaka, dia tokony hampiharina aminy avy hatrany ny didim-pitsarana, ka hovonoina ho faty izy na horoahina, na hampandoavina sazy na hogadraina.”'),
  ('6ab25a9cbebb1ae30b794756', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 22, 'Omeo azy izay angatahiny na dia hatramin’ny volafotsy 100 talenta, varimbazaha 100 kora, divay 100 bata, ary menaka 100 bata aza. Omeo azy koa izay sira rehetra ilaina.', 'omeo azy izay angatahiny na dia hatramin’ny volafotsy 100 talenta, varimbazaha 100 kora, divay 100 bata, ary menaka 100 bata aza. omeo azy koa izay sira rehetra ilaina.'),
  ('6ab25a9cbebb1ae30b794755', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 21, '“Izaho, Artaksersesy Mpanjaka, dia manome baiko anareo mpitahiry ny harenam-panjakana rehetra any amin’ny faritra Ampitan’ny Renirano, hoe tokony homenareo avy hatrany izay rehetra angatahin’i Ezra mpisorona, ilay mpanao dika soratra ny Lalàn’ilay Andriamanitry ny lanitra.', '“izaho, artaksersesy mpanjaka, dia manome baiko anareo mpitahiry ny harenam-panjakana rehetra any amin’ny faritra ampitan’ny renirano, hoe tokony homenareo avy hatrany izay rehetra angatahin’i ezra mpisorona, ilay mpanao dika soratra ny lalàn’ilay andriamanitry ny lanitra.'),
  ('6ab25a9cbebb1ae30b794751', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 17, 'Ampiasao avy hatrany izany vola izany mba hividianana ombilahy sy ondrilahy sy zanak’ondry, ary fanatitra varimbazaha sy fanatitra zava-pisotro ilaina miaraka amin’ireo. Dia atolory eo amin’ny alitaran’ny tranon’ny Andriamanitrareo any Jerosalema izany.', 'ampiasao avy hatrany izany vola izany mba hividianana ombilahy sy ondrilahy sy zanak’ondry, ary fanatitra varimbazaha sy fanatitra zava-pisotro ilaina miaraka amin’ireo. dia atolory eo amin’ny alitaran’ny tranon’ny andriamanitrareo any jerosalema izany.'),
  ('6ab25a9cbebb1ae30b79474f', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 15, 'Ento koa ny volafotsy sy ny volamena avy any amin’ny mpanjaka sy ny mpanolo-tsainy, nomen’izy ireo an-tsitrapo ho an’ilay Andriamanitry ny Israely, izay any Jerosalema.', 'ento koa ny volafotsy sy ny volamena avy any amin’ny mpanjaka sy ny mpanolo-tsainy, nomen’izy ireo an-tsitrapo ho an’ilay andriamanitry ny israely, izay any jerosalema.'),
  ('6ab25a9cbebb1ae30b794748', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 8, 'Ary tonga tany Jerosalema i Ezra tamin’ny volana fahadimy, tamin’ny taona fahafito nanjakan’io mpanjaka io.', 'ary tonga tany jerosalema i ezra tamin’ny volana fahadimy, tamin’ny taona fahafito nanjakan’io mpanjaka io.'),
  ('6ab25a9cbebb1ae30b794759', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 25, '“Ary ianao, ry Ezra, ampiasao ny fahendrena nomen’ilay Andriamanitrao anao, dia manendre mpahay lalàna sy mpitsara, mba hitsara ny olona rehetra any amin’ny faritra Ampitan’ny Renirano, dia izay rehetra mahalala ny lalàn’ny Andriamanitrao. Tokony hampianarinao kosa izay tsy mahalala an’izany.', '“ary ianao, ry ezra, ampiasao ny fahendrena nomen’ilay andriamanitrao anao, dia manendre mpahay lalàna sy mpitsara, mba hitsara ny olona rehetra any amin’ny faritra ampitan’ny renirano, dia izay rehetra mahalala ny lalàn’ny andriamanitrao. tokony hampianarinao kosa izay tsy mahalala an’izany.'),
  ('6ab25a9cbebb1ae30b794752', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 18, '“Azonao sy ny rahalahinao ampiasaina amin’izay hitanareo fa mety ny ambin’ny volafotsy sy volamena, araka ny sitrapon’ilay Andriamanitrareo.', '“azonao sy ny rahalahinao ampiasaina amin’izay hitanareo fa mety ny ambin’ny volafotsy sy volamena, araka ny sitrapon’ilay andriamanitrareo.'),
  ('6ab25a9cbebb1ae30b794754', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 20, 'Izay zavatra hafa mbola ilaina ao an-tranon’ny Andriamanitrao ka tokony homenao, dia alaivo ao amin’ny trano fitehirizana ny harenan’ny mpanjaka.', 'izay zavatra hafa mbola ilaina ao an-tranon’ny andriamanitrao ka tokony homenao, dia alaivo ao amin’ny trano fitehirizana ny harenan’ny mpanjaka.'),
  ('6ab25a9cbebb1ae30b794746', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 6, 'Niala avy tany Babylona io Ezra io. Mpanao dika soratra izy, ary tena nahay tsara ny Lalàn’i Mosesy, izay nomen’i Jehovah Andriamanitry ny Israely. Nomen’ny mpanjaka azy izay rehetra nangatahiny, satria nanampy azy ny tanan’i Jehovah Andriamaniny.', 'niala avy tany babylona io ezra io. mpanao dika soratra izy, ary tena nahay tsara ny lalàn’i mosesy, izay nomen’i jehovah andriamanitry ny israely. nomen’ny mpanjaka azy izay rehetra nangatahiny, satria nanampy azy ny tanan’i jehovah andriamaniny.'),
  ('6ab25a9cbebb1ae30b79474d', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 13, 'Nanome baiko aho hoe na iza na iza amin’ny vahoakan’Israely sy ny mpisorony ary ny Levita eto amin’ny fanjakako, ka te hiaraka aminao ho any Jerosalema, dia mahazo mandeha.', 'nanome baiko aho hoe na iza na iza amin’ny vahoakan’israely sy ny mpisorony ary ny levita eto amin’ny fanjakako, ka te hiaraka aminao ho any jerosalema, dia mahazo mandeha.'),
  ('6ab25a9cbebb1ae30b79474a', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 10, 'Efa nanomana ny fony i Ezra mba handinika sy hampihatra ny Lalàn’i Jehovah, ary hampianatra ny fitsipika sy ny didim-pitsarana ao amin’izy io, tany Israely.', 'efa nanomana ny fony i ezra mba handinika sy hampihatra ny lalàn’i jehovah, ary hampianatra ny fitsipika sy ny didim-pitsarana ao amin’izy io, tany israely.'),
  ('6ab25a9cbebb1ae30b79474c', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 12, '* “Avy amin’i Artaksersesy, ilay mpanjakan’ny mpanjaka, ho an’i Ezra mpisorona, mpanao dika soratra ny Lalàn’ilay Andriamanitry ny lanitra: Fiadanana anie ho anao!', '* “avy amin’i artaksersesy, ilay mpanjakan’ny mpanjaka, ho an’i ezra mpisorona, mpanao dika soratra ny lalàn’ilay andriamanitry ny lanitra: fiadanana anie ho anao!'),
  ('6ab25a9cbebb1ae30b794743', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 3, 'zanak’i Amaria, zanak’i Azaria, zanak’i Meraiota,', 'zanak’i amaria, zanak’i azaria, zanak’i meraiota,'),
  ('6ab25a9cbebb1ae30b794758', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 24, 'Ilazana koa ianareo fa tsy azo atao ny mitaky hetra na haba na hetran-dalana amin’ny mpisorona, ny Levita, ny mpitendry zavamaneno, ny mpiandry varavarana, ny mpanompo ao amin’ny tempoly, ary ny mpiasa ao amin’io tranon’Andriamanitra io.', 'ilazana koa ianareo fa tsy azo atao ny mitaky hetra na haba na hetran-dalana amin’ny mpisorona, ny levita, ny mpitendry zavamaneno, ny mpiandry varavarana, ny mpanompo ao amin’ny tempoly, ary ny mpiasa ao amin’io tranon’andriamanitra io.'),
  ('6ab25a9cbebb1ae30b794753', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 19, 'Ary atolory eo anatrehan’Andriamanitra any Jerosalema daholo ny fitaovana nomena anao mba hampiasaina amin’ny fanompoana ao an-tranon’ny Andriamanitrao.', 'ary atolory eo anatrehan’andriamanitra any jerosalema daholo ny fitaovana nomena anao mba hampiasaina amin’ny fanompoana ao an-tranon’ny andriamanitrao.'),
  ('6ab25a9cbebb1ae30b794745', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 5, 'zanak’i Abisoa, zanak’i Finehasa, zanak’i Eleazara, zanak’i Arona lehiben’ny mpisorona.', 'zanak’i abisoa, zanak’i finehasa, zanak’i eleazara, zanak’i arona lehiben’ny mpisorona.'),
  ('6ab25a9cbebb1ae30b794750', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 16, 'Ento koa ny volafotsy sy ny volamena rehetra azonao manerana ny faritanin’i Babylona, sy ny fanomezana avy amin’ny olona sy ny mpisorona, omen’izy ireo an-tsitrapo ho an’ny tranon’ny Andriamaniny any Jerosalema.', 'ento koa ny volafotsy sy ny volamena rehetra azonao manerana ny faritanin’i babylona, sy ny fanomezana avy amin’ny olona sy ny mpisorona, omen’izy ireo an-tsitrapo ho an’ny tranon’ny andriamaniny any jerosalema.'),
  ('6ab25a9cbebb1ae30b79474b', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 11, 'Intỳ ny dika mitovy amin’ilay taratasy nomen’i Artaksersesy Mpanjaka an’i Ezra, izay mpisorona sady mpanao dika soratra, ary mpandalina ny didin’i Jehovah sy ny fitsipiny ho an’ny Israely:', 'intỳ ny dika mitovy amin’ilay taratasy nomen’i artaksersesy mpanjaka an’i ezra, izay mpisorona sady mpanao dika soratra, ary mpandalina ny didin’i jehovah sy ny fitsipiny ho an’ny israely:'),
  ('6ab25a9cbebb1ae30b794744', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 4, 'zanak’i Zerahia, zanak’i Ozy, zanak’i Boky,', 'zanak’i zerahia, zanak’i ozy, zanak’i boky,'),
  ('6ab25a9cbebb1ae30b79475b', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 27, 'Hoderaina anie i Jehovah Andriamanitry ny razambentsika, izay nanao an’izany tao am-pon’ny mpanjaka mba hahatsara tarehy ny tranon’i Jehovah any Jerosalema!', 'hoderaina anie i jehovah andriamanitry ny razambentsika, izay nanao an’izany tao am-pon’ny mpanjaka mba hahatsara tarehy ny tranon’i jehovah any jerosalema!'),
  ('6ab25a9cbebb1ae30b794749', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 9, 'Tamin’ny andro voalohan’ny volana voalohany i Ezra no nanomboka an’ilay diany avy tany Babylona, ary tonga tany Jerosalema izy tamin’ny andro voalohan’ny volana fahadimy. Nanampy azy mantsy ny tanan’ny Andriamaniny.', 'tamin’ny andro voalohan’ny volana voalohany i ezra no nanomboka an’ilay diany avy tany babylona, ary tonga tany jerosalema izy tamin’ny andro voalohan’ny volana fahadimy. nanampy azy mantsy ny tanan’ny andriamaniny.'),
  ('6ab25a9cbebb1ae30b794747', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 7, 'Niakatra nankany Jerosalema ny sasany tamin’ny Israelita, ny mpisorona, ny Levita, ny mpihira, ny mpiandry vavahady, ary ny mpanompo tao amin’ny tempoly, tamin’ny taona fahafito nanjakan’i Artaksersesy Mpanjaka.', 'niakatra nankany jerosalema ny sasany tamin’ny israelita, ny mpisorona, ny levita, ny mpihira, ny mpiandry vavahady, ary ny mpanompo tao amin’ny tempoly, tamin’ny taona fahafito nanjakan’i artaksersesy mpanjaka.'),
  ('6ab25a9cbebb1ae30b794741', '2026-09-22T10:38:20.506Z', '2026-09-22T10:38:20.506Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 7, 1, 'Ary niverina i Ezra tatỳ aoriana, tamin’ny fotoana nanjakan’i Artaksersesy mpanjakan’i Persa. I Ezra dia zanak’i Seraia, zanak’i Azaria, zanak’i Hilkia,', 'ary niverina i ezra tatỳ aoriana, tamin’ny fotoana nanjakan’i artaksersesy mpanjakan’i persa. i ezra dia zanak’i seraia, zanak’i azaria, zanak’i hilkia,'),
  ('6ab25a9dd1ed0d1ad582e918', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 1, 'Ireto avy ny lohan’ireo fianakaviambe sy ireo voasoratra tao amin’ny tetirazana, izay niaraka tamiko niala avy tany Babylona, tamin’ny andro nanjakan’i Artaksersesy Mpanjaka:', 'ireto avy ny lohan’ireo fianakaviambe sy ireo voasoratra tao amin’ny tetirazana, izay niaraka tamiko niala avy tany babylona, tamin’ny andro nanjakan’i artaksersesy mpanjaka:'),
  ('6ab25a9dd1ed0d1ad582e920', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 9, 'Obadia zanak’i Jehiela, avy amin’ny taranak’i Joaba, ary nisy 218 lahy niaraka taminy;', 'obadia zanak’i jehiela, avy amin’ny taranak’i joaba, ary nisy 218 lahy niaraka taminy;'),
  ('6ab25a9dd1ed0d1ad582e91b', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 4, 'Eliho-enay zanak’i Zerahia, avy amin’ny taranak’i Pahata-moaba, ary nisy 200 lahy niaraka taminy;', 'eliho-enay zanak’i zerahia, avy amin’ny taranak’i pahata-moaba, ary nisy 200 lahy niaraka taminy;'),
  ('6ab25a9dd1ed0d1ad582e928', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 17, 'Ary nomeko baiko izy ireo ho any amin’i Ido, ilay mpitarika tao amin’ilay toerana atao hoe Kasifia. Nasaiko niteny tamin’i Ido sy ny rahalahiny, izay mpanompo tao amin’ny tempoly nipetraka tao Kasifia, izy ireo, mba hitondra olona hanompo ao an-tranon’ilay Andriamanitray.', 'ary nomeko baiko izy ireo ho any amin’i ido, ilay mpitarika tao amin’ilay toerana atao hoe kasifia. nasaiko niteny tamin’i ido sy ny rahalahiny, izay mpanompo tao amin’ny tempoly nipetraka tao kasifia, izy ireo, mba hitondra olona hanompo ao an-tranon’ilay andriamanitray.'),
  ('6ab25a9dd1ed0d1ad582e91d', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 6, 'Ebeda zanak’i Jonatana, avy amin’ny taranak’i Adina, ary nisy 50 lahy niaraka taminy;', 'ebeda zanak’i jonatana, avy amin’ny taranak’i adina, ary nisy 50 lahy niaraka taminy;'),
  ('6ab25a9dd1ed0d1ad582e92b', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 20, 'Ary nisy 220 ny mpanompo tao amin’ny tempoly, izay samy voasoratra anarana. I Davida sy ny andriana no efa nanome mpanompo tao amin’ny tempoly mba hanampy ny Levita.', 'ary nisy 220 ny mpanompo tao amin’ny tempoly, izay samy voasoratra anarana. i davida sy ny andriana no efa nanome mpanompo tao amin’ny tempoly mba hanampy ny levita.'),
  ('6ab25a9dd1ed0d1ad582e929', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 18, 'Nanampy anay ny tanan’ilay Andriamanitray, ka nentin’izy ireo tany aminay ilay lehilahy malina atao hoe Serebia, avy amin’ny taranak’i Maly zafikelin’i Levy, zanak’i Israely. Nentin’izy ireo koa ny zanak’i Serebia sy ny rahalahiny, 18 lahy;', 'nanampy anay ny tanan’ilay andriamanitray, ka nentin’izy ireo tany aminay ilay lehilahy malina atao hoe serebia, avy amin’ny taranak’i maly zafikelin’i levy, zanak’i israely. nentin’izy ireo koa ny zanak’i serebia sy ny rahalahiny, 18 lahy;'),
  ('6ab25a9dd1ed0d1ad582e923', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 12, 'Johanana zanak’i Hakatana, avy amin’ny taranak’i Azgada, ary nisy 110 lahy niaraka taminy;', 'johanana zanak’i hakatana, avy amin’ny taranak’i azgada, ary nisy 110 lahy niaraka taminy;'),
  ('6ab25a9dd1ed0d1ad582e91f', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 8, 'Zebadia zanak’i Mikaela, avy amin’ny taranak’i Sefatia, ary nisy 80 lahy niaraka taminy;', 'zebadia zanak’i mikaela, avy amin’ny taranak’i sefatia, ary nisy 80 lahy niaraka taminy;'),
  ('6ab25a9dd1ed0d1ad582e92c', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 21, 'Dia nasaiko nifady hanina teo amin’ny reniranon’i Ahava ny olona. Tianay mantsy ny hanetry tena teo anatrehan’Andriamanitray, sy hangataka azy hitarika ny dianay, dia izahay sy ny zanakay miaraka amin’ny fanananay rehetra.', 'dia nasaiko nifady hanina teo amin’ny reniranon’i ahava ny olona. tianay mantsy ny hanetry tena teo anatrehan’andriamanitray, sy hangataka azy hitarika ny dianay, dia izahay sy ny zanakay miaraka amin’ny fanananay rehetra.'),
