  ('6ab25a9dd1ed0d1ad582e927', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 16, 'Dia nampanantsoiko i Eliezera, Ariela, Semaia, Elnatana, Jariba, Elnatana, Natana, Zakaria, ary Mesolama izay samy lehilahy mpitarika, ary Joariba sy Elnatana izay samy mpampianatra.', 'dia nampanantsoiko i eliezera, ariela, semaia, elnatana, jariba, elnatana, natana, zakaria, ary mesolama izay samy lehilahy mpitarika, ary joariba sy elnatana izay samy mpampianatra.'),
  ('6ab25a9dd1ed0d1ad582e91c', '2026-09-22T10:38:21.555Z', '2026-09-22T10:38:21.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ezra', 15, 8, 5, 'Sekania zanak’i Jahaziela, avy amin’ny taranak’i Zato, ary nisy 300 lahy niaraka taminy;', 'sekania zanak’i jahaziela, avy amin’ny taranak’i zato, ary nisy 300 lahy niaraka taminy;'),
