  ('6ab25aa5236472c122a1c221', '2026-09-22T10:38:29.333Z', '2026-09-22T10:38:29.333Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Nehemia', 16, 11, 27, 'Hazara-soala, Beri-sheba sy ny tanàna niankina taminy,', 'hazara-soala, beri-sheba sy ny tanàna niankina taminy,'),
