  ('6ab25aceaef2f056bc5a2e8d', '2026-09-22T10:39:10.817Z', '2026-09-22T10:39:10.817Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 7, 8, 'Hamoaka didim-pitsarana hampiharina amin’ireo firenena i Jehovah. Jehovah ô, tsarao araka ny fahamarinako Sy ny tsy fivadihako aho.', 'hamoaka didim-pitsarana hampiharina amin’ireo firenena i jehovah. jehovah ô, tsarao araka ny fahamarinako sy ny tsy fivadihako aho.'),
