  ('6ab25acf4bd94ebece5ca909', '2026-09-22T10:39:11.273Z', '2026-09-22T10:39:11.273Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 8, 1, 'Ry Jehovah Tomponay ô, heni-kaja eran-tany ny anaranao; Ataonao avo noho ny lanitra ny voninahitrao!', 'ry jehovah tomponay ô, heni-kaja eran-tany ny anaranao; ataonao avo noho ny lanitra ny voninahitrao!'),
