  ('6ab25acf1f41de91124ce981', '2026-09-22T10:39:11.732Z', '2026-09-22T10:39:11.732Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 9, 14, 'Mba hanambarako eo am-bavahadin’i Ziona zanakavavy ny asa mendri-piderana ataonao, Sy hifaliako noho ny asa famonjena ataonao. ט [ Teta ]', 'mba hanambarako eo am-bavahadin’i ziona zanakavavy ny asa mendri-piderana ataonao, sy hifaliako noho ny asa famonjena ataonao. ט [ teta ]'),
  ('6ab25acf1f41de91124ce97c', '2026-09-22T10:39:11.732Z', '2026-09-22T10:39:11.732Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 9, 9, 'Ho fialofana azo antoka i Jehovah ho an’izay ampahorina, Dia fialofana azo antoka amin’ny fotoan-tsarotra.', 'ho fialofana azo antoka i jehovah ho an’izay ampahorina, dia fialofana azo antoka amin’ny fotoan-tsarotra.'),
