  ('6ab25acf1f41de91124ce986', '2026-09-22T10:39:11.733Z', '2026-09-22T10:39:11.733Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 9, 19, 'Mitsangàna, Jehovah ô! Aza avela handresy ny olombelona mety maty. Enga anie hotsaraina eo anatrehanao ireo firenena!', 'mitsangàna, jehovah ô! aza avela handresy ny olombelona mety maty. enga anie hotsaraina eo anatrehanao ireo firenena!'),
