  ('6ab25ad8bf1654e727853894', '2026-09-22T10:39:20.456Z', '2026-09-22T10:39:20.456Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 24, 9, 'Ry vavahady ô, ataovy avo be ny tamponareo; Misokafa, ry varavarana efa nisy hatry ny ela, Mba hidiran’ilay Mpanjaka be voninahitra!', 'ry vavahady ô, ataovy avo be ny tamponareo; misokafa, ry varavarana efa nisy hatry ny ela, mba hidiran’ilay mpanjaka be voninahitra!'),
  ('6ab25ad8bf1654e72785388f', '2026-09-22T10:39:20.456Z', '2026-09-22T10:39:20.456Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 24, 4, 'Izay tsy manan-tsiny amin’izay ataon’ny tanany sady madio fo, Ary tsy mianiana lainga amin’ny anarako, Na mianiana mba hamitahana.', 'izay tsy manan-tsiny amin’izay ataon’ny tanany sady madio fo, ary tsy mianiana lainga amin’ny anarako, na mianiana mba hamitahana.'),
