  ('6ab25ad9ee81adb6df3d67f4', '2026-09-22T10:39:21.528Z', '2026-09-22T10:39:21.528Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 25, 22, 'Andriamanitra ô, vonjeo amin’ny fahoriany rehetra ny Israely.', 'andriamanitra ô, vonjeo amin’ny fahoriany rehetra ny israely.'),
