  ('6ab25ae32fa5a4baf5c21c3b', '2026-09-22T10:39:31.839Z', '2026-09-22T10:39:31.839Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 42, 3, 'Ny ranomasoko no sakafoko na andro na alina; Maneso ahy tontolo andro ny olona hoe: “Aiza ny Andriamanitrao?”', 'ny ranomasoko no sakafoko na andro na alina; maneso ahy tontolo andro ny olona hoe: “aiza ny andriamanitrao?”'),
