  ('6ab25ae32fa5a4baf5c21c42', '2026-09-22T10:39:31.839Z', '2026-09-22T10:39:31.839Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 42, 10, 'Maneso ahy ny fahavaloko, ka mankahala ahy sy mifofo ny aiko; Maneso ahy tontolo andro izy ireo hoe: “Aiza ny Andriamanitrao?”', 'maneso ahy ny fahavaloko, ka mankahala ahy sy mifofo ny aiko; maneso ahy tontolo andro izy ireo hoe: “aiza ny andriamanitrao?”'),
  ('6ab25ae32fa5a4baf5c21c40', '2026-09-22T10:39:31.839Z', '2026-09-22T10:39:31.839Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 42, 8, 'Amin’ny antoandro, dia hasehon’i Jehovah hoe tia ahy sy tsy mivadika amiko izy, Ary amin’ny alina, dia hihira momba azy aho—hivavaka amin’ilay Andriamanitra nanome aina ahy.', 'amin’ny antoandro, dia hasehon’i jehovah hoe tia ahy sy tsy mivadika amiko izy, ary amin’ny alina, dia hihira momba azy aho—hivavaka amin’ilay andriamanitra nanome aina ahy.'),
  ('6ab25ae32fa5a4baf5c21c39', '2026-09-22T10:39:31.839Z', '2026-09-22T10:39:31.839Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 42, 1, 'Toy ny serfa mitady mafy renirano, Dia mba mitady mafy anao koa aho, Andriamanitra ô!', 'toy ny serfa mitady mafy renirano, dia mba mitady mafy anao koa aho, andriamanitra ô!'),
