  ('6ab25b0db9504e351c613d4b', '2026-09-22T10:40:13.281Z', '2026-09-22T10:40:13.281Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 2, 'Nampahafantatra ny famonjeny i Jehovah; Naharihariny teo anatrehan’ireo firenena ny fahamarinany.', 'nampahafantatra ny famonjeny i jehovah; naharihariny teo anatrehan’ireo firenena ny fahamarinany.'),
  ('6ab25b0db9504e351c613d4a', '2026-09-22T10:40:13.281Z', '2026-09-22T10:40:13.281Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 1, 'Mihirà hira vaovao ho an’i Jehovah, Fa nanao zava-mahagaga izy. Nahavonjy ny tanany ankavanana, dia ny sandriny masina.', 'mihirà hira vaovao ho an’i jehovah, fa nanao zava-mahagaga izy. nahavonjy ny tanany ankavanana, dia ny sandriny masina.'),
  ('6ab25b0db9504e351c613d4c', '2026-09-22T10:40:13.281Z', '2026-09-22T10:40:13.281Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 3, 'Tadidiny hoe tiany ny taranak’Israely sady tsy nivadika tamin’izy ireo izy. Nahita ny famonjen’Andriamanitsika ny vazan-tany efatra.', 'tadidiny hoe tiany ny taranak’israely sady tsy nivadika tamin’izy ireo izy. nahita ny famonjen’andriamanitsika ny vazan-tany efatra.'),
  ('6ab25b0db9504e351c613d50', '2026-09-22T10:40:13.282Z', '2026-09-22T10:40:13.282Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 7, 'Aoka hihoby ny ranomasina sy izay rehetra ao aminy, Ary ny tany sy izay monina eo aminy.', 'aoka hihoby ny ranomasina sy izay rehetra ao aminy, ary ny tany sy izay monina eo aminy.'),
  ('6ab25b0db9504e351c613d4f', '2026-09-22T10:40:13.282Z', '2026-09-22T10:40:13.282Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 6, 'Tsofy ny trompetra sy ny anjombona, Ka manaova horakora-pandresena eo anatrehan’ny Mpanjaka, dia i Jehovah.', 'tsofy ny trompetra sy ny anjombona, ka manaova horakora-pandresena eo anatrehan’ny mpanjaka, dia i jehovah.'),
  ('6ab25b0db9504e351c613d4d', '2026-09-22T10:40:13.282Z', '2026-09-22T10:40:13.282Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 4, 'Manaova horakora-pandresena ho an’i Jehovah, ry tany manontolo. Mifalia sy mihobia ary manaova hira fiderana.', 'manaova horakora-pandresena ho an’i jehovah, ry tany manontolo. mifalia sy mihobia ary manaova hira fiderana.'),
  ('6ab25b0db9504e351c613d4e', '2026-09-22T10:40:13.282Z', '2026-09-22T10:40:13.282Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 5, 'Manaova hira fiderana ho an’i Jehovah amin’ny harpa, Eny, amin’ny harpa sy ny hira mahafinaritra.', 'manaova hira fiderana ho an’i jehovah amin’ny harpa, eny, amin’ny harpa sy ny hira mahafinaritra.'),
  ('6ab25b0db9504e351c613d51', '2026-09-22T10:40:13.282Z', '2026-09-22T10:40:13.282Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 8, 'Aoka hitehaka ny renirano; Aoka ny tendrombohitra hiara-mihoby', 'aoka hitehaka ny renirano; aoka ny tendrombohitra hiara-mihoby'),
  ('6ab25b0db9504e351c613d52', '2026-09-22T10:40:13.282Z', '2026-09-22T10:40:13.282Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 98, 9, 'Eo anatrehan’i Jehovah, fa tonga hitsara ny tany izy. Hotsarainy araka ny rariny ny tany misy mponina, Ary hotsarainy araka ny hitsiny ireo firenena.', 'eo anatrehan’i jehovah, fa tonga hitsara ny tany izy. hotsarainy araka ny rariny ny tany misy mponina, ary hotsarainy araka ny hitsiny ireo firenena.'),
  ('6ab25b0d701c5f96e92d1e04', '2026-09-22T10:40:13.844Z', '2026-09-22T10:40:13.844Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 99, 8, 'Namaly azy ireo ianao, Jehovah Andriamanitray ô! Andriamanitra namela ny helok’izy ireo ianao, Nefa koa nanasazy azy ireo noho ny ratsy nataony.', 'namaly azy ireo ianao, jehovah andriamanitray ô! andriamanitra namela ny helok’izy ireo ianao, nefa koa nanasazy azy ireo noho ny ratsy nataony.'),
  ('6ab25b0d701c5f96e92d1e00', '2026-09-22T10:40:13.844Z', '2026-09-22T10:40:13.844Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 99, 4, 'Mpanjaka mahery izy sady tia rariny. Nataonao mafy orina ny fahitsiana. Nampihatra ny rariny sy ny hitsiny tamin’i Jakoba ianao.', 'mpanjaka mahery izy sady tia rariny. nataonao mafy orina ny fahitsiana. nampihatra ny rariny sy ny hitsiny tamin’i jakoba ianao.'),
  ('6ab25b0d701c5f96e92d1e03', '2026-09-22T10:40:13.844Z', '2026-09-22T10:40:13.844Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 99, 7, 'Niresaka tamin’izy ireo tao anatin’ny andry rahona izy. Narahin’izy ireo ny fampahatsiahivana sy ny didy nomeny azy.', 'niresaka tamin’izy ireo tao anatin’ny andry rahona izy. narahin’izy ireo ny fampahatsiahivana sy ny didy nomeny azy.'),
  ('6ab25b0d701c5f96e92d1e02', '2026-09-22T10:40:13.844Z', '2026-09-22T10:40:13.844Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 99, 6, 'Anisan’ny mpisorony i Mosesy sy Arona, Ary anisan’ny niantso ny anarany i Samoela. Niantso an’i Jehovah izy ireo, Dia namaly azy ireo izy.', 'anisan’ny mpisorony i mosesy sy arona, ary anisan’ny niantso ny anarany i samoela. niantso an’i jehovah izy ireo, dia namaly azy ireo izy.'),
  ('6ab25b0d701c5f96e92d1e01', '2026-09-22T10:40:13.844Z', '2026-09-22T10:40:13.844Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 99, 5, 'Asandrato i Jehovah Andriamanitsika, ary miankohofa eo amin’ny fitoeran-tongony; Masina izy.', 'asandrato i jehovah andriamanitsika, ary miankohofa eo amin’ny fitoeran-tongony; masina izy.'),
