  ('6ab25b0fdeb60b1d98cb480f', '2026-09-22T10:40:15.406Z', '2026-09-22T10:40:15.406Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 102, 22, 'Rehefa miangona mba hanompo an’i Jehovah Ireo firenena sy fanjakana.', 'rehefa miangona mba hanompo an’i jehovah ireo firenena sy fanjakana.'),
