  ('6ab25b1d0cc9c58df55bda4d', '2026-09-22T10:40:29.106Z', '2026-09-22T10:40:29.106Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 118, 6, 'Manohana ahy i Jehovah, ka tsy hatahotra aho. Inona moa no azon’ny olona atao amiko?', 'manohana ahy i jehovah, ka tsy hatahotra aho. inona moa no azon’ny olona atao amiko?'),
  ('6ab25b1d0cc9c58df55bda4c', '2026-09-22T10:40:29.106Z', '2026-09-22T10:40:29.106Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 118, 5, 'Niantso an’i Jah aho tao anatin’ny sarotra, Dia namaly ahy i Jah ka nitondra ahy nankeo amin’ny toerana tsy mampidi-doza.', 'niantso an’i jah aho tao anatin’ny sarotra, dia namaly ahy i jah ka nitondra ahy nankeo amin’ny toerana tsy mampidi-doza.'),
  ('6ab25b1d0cc9c58df55bda58', '2026-09-22T10:40:29.107Z', '2026-09-22T10:40:29.107Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 118, 17, 'Tsy ho faty aho fa ho velona, Mba hanambara ny asan’i Jah.', 'tsy ho faty aho fa ho velona, mba hanambara ny asan’i jah.'),
  ('6ab25b1d0cc9c58df55bda62', '2026-09-22T10:40:29.107Z', '2026-09-22T10:40:29.107Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 118, 27, 'I Jehovah no Andriamanitra; Manome antsika hazavana izy. Mitondrà rantsankazo eny an-tananao, ary mandehana milahatra miaraka amin’ireo mpanao fety Hatreny amin’ny tandroky ny alitara.', 'i jehovah no andriamanitra; manome antsika hazavana izy. mitondrà rantsankazo eny an-tananao, ary mandehana milahatra miaraka amin’ireo mpanao fety hatreny amin’ny tandroky ny alitara.'),
  ('6ab25b1d0cc9c58df55bda59', '2026-09-22T10:40:29.107Z', '2026-09-22T10:40:29.107Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 118, 18, 'Nanafay mafy ahy i Jah, Nefa tsy namela ahy ho faty.', 'nanafay mafy ahy i jah, nefa tsy namela ahy ho faty.'),
  ('6ab25b1d0cc9c58df55bda61', '2026-09-22T10:40:29.107Z', '2026-09-22T10:40:29.107Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 118, 26, 'Hotahina anie ilay tonga amin’ny anaran’i Jehovah! Avy ao an-tranon’i Jehovah izahay no mitso-drano anareo.', 'hotahina anie ilay tonga amin’ny anaran’i jehovah! avy ao an-tranon’i jehovah izahay no mitso-drano anareo.'),
