  ('6ab25b1dbd989c49817525b4', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 73, 'Ny tananao no nanao sy namolavola ahy. Ataovy mahira-tsaina aho Mba hianarako ny didinao.', 'ny tananao no nanao sy namolavola ahy. ataovy mahira-tsaina aho mba hianarako ny didinao.'),
  ('6ab25b1dbd989c49817525ad', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 66, 'Ampianaro hisaina tsara sy hanam-pahalalana aho, Fa atokisako ny didinao.', 'ampianaro hisaina tsara sy hanam-pahalalana aho, fa atokisako ny didinao.'),
