  ('6ab25b1dbd989c49817525b1', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 70, 'Tsy mihontsina ny fon’ireny, Fa izaho kosa finaritra amin’ny lalànao.', 'tsy mihontsina ny fon’ireny, fa izaho kosa finaritra amin’ny lalànao.'),
  ('6ab25b1dbd989c49817525a8', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 61, 'Mihodidina amiko ny tadin’ny ratsy fanahy, Nefa tsy hadinoko ny lalànao.', 'mihodidina amiko ny tadin’ny ratsy fanahy, nefa tsy hadinoko ny lalànao.'),
  ('6ab25b1dbd989c4981752595', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 42, 'Dia hovaliako ilay manaratsy ahy, Fa matoky ny teninao aho.', 'dia hovaliako ilay manaratsy ahy, fa matoky ny teninao aho.'),
