  ('6ab25b1dbd989c49817525bc', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 81, 'Tsy andriko izay hamonjenao ahy, Satria ny teninao no antenaiko.', 'tsy andriko izay hamonjenao ahy, satria ny teninao no antenaiko.'),
  ('6ab25b1dbd989c49817525ba', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 79, 'Aoka hiaraka amiko indray ireo matahotra anao, Dia ireo mahafantatra ny fampahatsiahivanao.', 'aoka hiaraka amiko indray ireo matahotra anao, dia ireo mahafantatra ny fampahatsiahivanao.'),
  ('6ab25b1dbd989c498175258b', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 32, 'Ho mailaka hampihatra ny didinao aho eo amin’ny fiainako, Satria halalahinao ny foko mba ho afaka handray an’izany. ה [ He ]', 'ho mailaka hampihatra ny didinao aho eo amin’ny fiainako, satria halalahinao ny foko mba ho afaka handray an’izany. ה [ he ]'),
  ('6ab25b1dbd989c49817525ac', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 65, 'Manao soa amin’ny mpanomponao ianao, Jehovah ô, araka ny efa nolazainao.', 'manao soa amin’ny mpanomponao ianao, jehovah ô, araka ny efa nolazainao.'),
  ('6ab25b1dbd989c49817525a6', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 59, 'Dinihiko tsara ny lalako, Mba hanitsiako ny diako ka hanarahako indray ny fampahatsiahivanao.', 'dinihiko tsara ny lalako, mba hanitsiako ny diako ka hanarahako indray ny fampahatsiahivanao.'),
