  ('6ab25b1dbd989c49817525b8', '2026-09-22T10:40:29.649Z', '2026-09-22T10:40:29.649Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 119, 77, 'Amindrao fo aho mba ho velona foana, Fa mahafinaritra ahy ny lalànao.', 'amindrao fo aho mba ho velona foana, fa mahafinaritra ahy ny lalànao.'),
