  ('6ab25b1e899c2e80bb864582', '2026-09-22T10:40:30.898Z', '2026-09-22T10:40:30.898Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 121, 3, 'Tsy havelany hibolisatra mihitsy ny tongotrao. Tsy ho rendremana mihitsy Ilay mpiambina anao.', 'tsy havelany hibolisatra mihitsy ny tongotrao. tsy ho rendremana mihitsy ilay mpiambina anao.'),
  ('6ab25b1e899c2e80bb864584', '2026-09-22T10:40:30.898Z', '2026-09-22T10:40:30.898Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 121, 5, 'I Jehovah no miambina anao. I Jehovah no manome alokaloka anao, eo ankavananao.', 'i jehovah no miambina anao. i jehovah no manome alokaloka anao, eo ankavananao.'),
  ('6ab25b1f1212d89b204cf2ee', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 7, 'Hisy fiadanana foana anie ao anatin’ny dongon-tany miaro anao, Ary tsy hanana ahiahy mihitsy anie izay ao anatin’ireo tilikambonao voaro mafy!', 'hisy fiadanana foana anie ao anatin’ny dongon-tany miaro anao, ary tsy hanana ahiahy mihitsy anie izay ao anatin’ireo tilikambonao voaro mafy!'),
  ('6ab25b1f1212d89b204cf2e9', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 2, 'Ary izao ny tongotray dia mijoro Eo am-bavahadinao, ry Jerosalema ô!', 'ary izao ny tongotray dia mijoro eo am-bavahadinao, ry jerosalema ô!'),
  ('6ab25b1f1212d89b204cf2ef', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 8, 'Noho ny amin’ny rahalahiko sy ny namako no hilazako hoe: “Hisy fiadanana anie ao aminao!”', 'noho ny amin’ny rahalahiko sy ny namako no hilazako hoe: “hisy fiadanana anie ao aminao!”'),
  ('6ab25b1f1212d89b204cf2f0', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 9, 'Noho ny amin’ny tranon’i Jehovah Andriamanitsika, Dia hitady izay hahasoa anao aho.', 'noho ny amin’ny tranon’i jehovah andriamanitsika, dia hitady izay hahasoa anao aho.'),
  ('6ab25b1f1212d89b204cf2ea', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 3, 'Naorina ho tanàna i Jerosalema, Izay natambatra ho iray.', 'naorina ho tanàna i jerosalema, izay natambatra ho iray.'),
  ('6ab25b1f1212d89b204cf2ec', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 5, 'Fa any no nametrahana ny sezan’ny mpitsara, Dia ny seza fiandrianan’ny taranak’i Davida.', 'fa any no nametrahana ny sezan’ny mpitsara, dia ny seza fiandrianan’ny taranak’i davida.'),
  ('6ab25b1f1212d89b204cf2eb', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 4, 'Niakatra nankany ireo foko, Dia ireo fokon’i Jah, Araka ny fampahatsiahivana nomeny ho an’ny Israely, Mba hisaotra ny anaran’i Jehovah.', 'niakatra nankany ireo foko, dia ireo fokon’i jah, araka ny fampahatsiahivana nomeny ho an’ny israely, mba hisaotra ny anaran’i jehovah.'),
  ('6ab25b1f1212d89b204cf2ed', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 6, 'Mangataha fiadanana ho an’i Jerosalema! Tsy hanana ahiahy izay tia anao.', 'mangataha fiadanana ho an’i jerosalema! tsy hanana ahiahy izay tia anao.'),
  ('6ab25b1f1212d89b204cf2e8', '2026-09-22T10:40:31.378Z', '2026-09-22T10:40:31.378Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 122, 1, 'Faly aho rehefa niteny tamiko izy ireo hoe: “Andao isika ho any an-tranon’i Jehovah!”', 'faly aho rehefa niteny tamiko izy ireo hoe: “andao isika ho any an-tranon’i jehovah!”'),
  ('6ab25b22bfe8609bf413661f', '2026-09-22T10:40:34.425Z', '2026-09-22T10:40:34.425Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 123, 4, 'Tototry ny fanesoana tafahoatra ataon’ireo matoky tena izahay, Sy ny fanambaniana ataon’ireo mirehareha.', 'tototry ny fanesoana tafahoatra ataon’ireo matoky tena izahay, sy ny fanambaniana ataon’ireo mirehareha.'),
  ('6ab25b22bfe8609bf413661d', '2026-09-22T10:40:34.425Z', '2026-09-22T10:40:34.425Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 123, 2, 'Toy ny ijeren’ny mpanompo ny tanan’ny tompony, Sy toy ny ijeren’ny mpanompovavy ny tanan’ny tompovaviny, No ijerenay an’i Jehovah Andriamanitray Mandra-piantrany anay.', 'toy ny ijeren’ny mpanompo ny tanan’ny tompony, sy toy ny ijeren’ny mpanompovavy ny tanan’ny tompovaviny, no ijerenay an’i jehovah andriamanitray mandra-piantrany anay.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25b22bfe8609bf413661c', '2026-09-22T10:40:34.425Z', '2026-09-22T10:40:34.425Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 123, 1, 'Mitraka mijery anao aho, Dia ianao ilay mipetraka eo amin’ny seza fiandrianana any an-danitra.', 'mitraka mijery anao aho, dia ianao ilay mipetraka eo amin’ny seza fiandrianana any an-danitra.'),
  ('6ab25b22bfe8609bf413661e', '2026-09-22T10:40:34.425Z', '2026-09-22T10:40:34.425Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 123, 3, 'Iantrao izahay, Jehovah ô, iantrao izahay, Fa tototry ny fanambaniana be loatra.', 'iantrao izahay, jehovah ô, iantrao izahay, fa tototry ny fanambaniana be loatra.'),
  ('6ab25b235081bb2edf6f76e8', '2026-09-22T10:40:35.464Z', '2026-09-22T10:40:35.464Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 1, '“Raha tsy nanampy antsika i Jehovah”, —Aoka ny Israely hilaza hoe—', '“raha tsy nanampy antsika i jehovah”, —aoka ny israely hilaza hoe—'),
  ('6ab25b235081bb2edf6f76e9', '2026-09-22T10:40:35.465Z', '2026-09-22T10:40:35.465Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 2, '“Raha tsy nanampy antsika i Jehovah Rehefa nisy olona nitsangana hanafika antsika,', '“raha tsy nanampy antsika i jehovah rehefa nisy olona nitsangana hanafika antsika,'),
  ('6ab25b235081bb2edf6f76ea', '2026-09-22T10:40:35.465Z', '2026-09-22T10:40:35.465Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 3, 'Dia ho efa natelin’izy ireo velona isika, Tamin’izy ireo tezitra be tamintsika.', 'dia ho efa natelin’izy ireo velona isika, tamin’izy ireo tezitra be tamintsika.'),
  ('6ab25b235081bb2edf6f76ef', '2026-09-22T10:40:35.465Z', '2026-09-22T10:40:35.465Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 8, 'Ahazoantsika fanampiana ny anaran’i Jehovah, Ilay Mpanao ny lanitra sy ny tany.”', 'ahazoantsika fanampiana ny anaran’i jehovah, ilay mpanao ny lanitra sy ny tany.”'),
  ('6ab25b235081bb2edf6f76eb', '2026-09-22T10:40:35.465Z', '2026-09-22T10:40:35.465Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 4, 'Dia ho nofaohin’ny rano isika, Ary ho nanafotra antsika ny riaka be.', 'dia ho nofaohin’ny rano isika, ary ho nanafotra antsika ny riaka be.'),
  ('6ab25b235081bb2edf6f76ec', '2026-09-22T10:40:35.465Z', '2026-09-22T10:40:35.465Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 5, 'Ho nandifotra antsika ny rano mahery be.', 'ho nandifotra antsika ny rano mahery be.'),
  ('6ab25b235081bb2edf6f76ee', '2026-09-22T10:40:35.465Z', '2026-09-22T10:40:35.465Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 7, 'Isika dia toy ny vorona afa-nandositra Avy tao amin’ny fandriky ny mpamandri-borona; Tapaka ilay fandrika, Ka afa-nandositra isika.', 'isika dia toy ny vorona afa-nandositra avy tao amin’ny fandriky ny mpamandri-borona; tapaka ilay fandrika, ka afa-nandositra isika.'),
  ('6ab25b235081bb2edf6f76ed', '2026-09-22T10:40:35.465Z', '2026-09-22T10:40:35.465Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 124, 6, 'Hoderaina anie i Jehovah, Satria tsy navelany horotidrotehin’ny nifin’izy ireo isika!', 'hoderaina anie i jehovah, satria tsy navelany horotidrotehin’ny nifin’izy ireo isika!'),
  ('6ab25b2378e33bc89f336597', '2026-09-22T10:40:35.913Z', '2026-09-22T10:40:35.913Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 125, 2, 'Hoatran’ny tendrombohitra manodidina an’i Jerosalema, Dia toy izany koa fa manodidina ny vahoakany i Jehovah, Manomboka izao ka ho mandrakizay.', 'hoatran’ny tendrombohitra manodidina an’i jerosalema, dia toy izany koa fa manodidina ny vahoakany i jehovah, manomboka izao ka ho mandrakizay.'),
  ('6ab25b2378e33bc89f33659a', '2026-09-22T10:40:35.913Z', '2026-09-22T10:40:35.913Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 125, 5, 'Fa izay mivily hanaraka lalana tsy mahitsy kosa Hesorin’i Jehovah miaraka amin’ny mpanao ratsy. Enga anie ka hiadana ny Israely!', 'fa izay mivily hanaraka lalana tsy mahitsy kosa hesorin’i jehovah miaraka amin’ny mpanao ratsy. enga anie ka hiadana ny israely!'),
  ('6ab25b2378e33bc89f336599', '2026-09-22T10:40:35.913Z', '2026-09-22T10:40:35.913Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 125, 4, 'Jehovah ô, manaova soa amin’ny olona tsara toetra Sy amin’ny mahitsy fo.', 'jehovah ô, manaova soa amin’ny olona tsara toetra sy amin’ny mahitsy fo.'),
  ('6ab25b2378e33bc89f336598', '2026-09-22T10:40:35.913Z', '2026-09-22T10:40:35.913Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 125, 3, 'Tsy hijanona eo amin’ny anjara tanin’ny olo-marina ny tehim-panjakan’ny ratsy fanahy, Mba tsy ho lasa hanao ratsy ny olo-marina.', 'tsy hijanona eo amin’ny anjara tanin’ny olo-marina ny tehim-panjakan’ny ratsy fanahy, mba tsy ho lasa hanao ratsy ny olo-marina.'),
  ('6ab25b2378e33bc89f336596', '2026-09-22T10:40:35.913Z', '2026-09-22T10:40:35.913Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 125, 1, 'Izay matoky an’i Jehovah Dia mitovy amin’ny Tendrombohitra Ziona, izay tsy voahozongozona Fa ho eo foana mandrakizay.', 'izay matoky an’i jehovah dia mitovy amin’ny tendrombohitra ziona, izay tsy voahozongozona fa ho eo foana mandrakizay.'),
  ('6ab25b251a422f17942dae8b', '2026-09-22T10:40:37.505Z', '2026-09-22T10:40:37.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 126, 5, 'Izay mitomany rehefa mamafy, Dia hihoby rehefa mijinja.', 'izay mitomany rehefa mamafy, dia hihoby rehefa mijinja.'),
  ('6ab25b251a422f17942dae88', '2026-09-22T10:40:37.505Z', '2026-09-22T10:40:37.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 126, 2, 'Nihomehy be mihitsy isika tamin’izay, Sady nihoby ny lelantsika. Nifampiresaka ny olona tany amin’ireo firenena tamin’izay hoe: “Nanao zavatra niavaka ho an-dry zareo i Jehovah!”', 'nihomehy be mihitsy isika tamin’izay, sady nihoby ny lelantsika. nifampiresaka ny olona tany amin’ireo firenena tamin’izay hoe: “nanao zavatra niavaka ho an-dry zareo i jehovah!”'),
  ('6ab25b251a422f17942dae8c', '2026-09-22T10:40:37.505Z', '2026-09-22T10:40:37.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 126, 6, 'Izay mivoaka mankany an-tsaha, na dia mitomany aza, Sady mitondra masomboly eran’ny harona, Dia tsy maintsy hihoby sy ho faly rehefa mody Sady hitondra amboaram-bokatra.', 'izay mivoaka mankany an-tsaha, na dia mitomany aza, sady mitondra masomboly eran’ny harona, dia tsy maintsy hihoby sy ho faly rehefa mody sady hitondra amboaram-bokatra.'),
  ('6ab25b251a422f17942dae89', '2026-09-22T10:40:37.505Z', '2026-09-22T10:40:37.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 126, 3, 'Nanao zavatra niavaka ho antsika tokoa i Jehovah, Ka faly be mihitsy isika.', 'nanao zavatra niavaka ho antsika tokoa i jehovah, ka faly be mihitsy isika.'),
  ('6ab25b251a422f17942dae8a', '2026-09-22T10:40:37.505Z', '2026-09-22T10:40:37.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 126, 4, 'Ampodio ireo lasa babo teo aminay, Jehovah ô, Toy ny amerenanao ny renirano ao Negeba.', 'ampodio ireo lasa babo teo aminay, jehovah ô, toy ny amerenanao ny renirano ao negeba.'),
  ('6ab25b251a422f17942dae87', '2026-09-22T10:40:37.505Z', '2026-09-22T10:40:37.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 126, 1, 'Rehefa nampodin’i Jehovah ny mponin’i Ziona lasa babo, Dia hoatran’ny nanonofy isika.', 'rehefa nampodin’i jehovah ny mponin’i ziona lasa babo, dia hoatran’ny nanonofy isika.'),
  ('6ab25b251cf7e594093d47c0', '2026-09-22T10:40:37.974Z', '2026-09-22T10:40:37.974Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 127, 5, 'Sambatra izay lehilahy mameno ny tranon-jana-tsipìkany amin’ireny. Tsy ho menatra izy ireo, Satria hiteny eo anatrehan’ny fahavalo eny am-bavahadin’ny tanàna ireny.', 'sambatra izay lehilahy mameno ny tranon-jana-tsipìkany amin’ireny. tsy ho menatra izy ireo, satria hiteny eo anatrehan’ny fahavalo eny am-bavahadin’ny tanàna ireny.'),
  ('6ab25b251cf7e594093d47bd', '2026-09-22T10:40:37.974Z', '2026-09-22T10:40:37.974Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 127, 2, 'Very maina ny hifohazanareo vao maraina, Sy ny hiaretanareo tory hatramin’ny alina be, Ary ny hiasanareo mafy mba hahazoana sakafo, Satria manome izay ilain’ny olona tiany izy sady manome azy ireo torimaso mamy.', 'very maina ny hifohazanareo vao maraina, sy ny hiaretanareo tory hatramin’ny alina be, ary ny hiasanareo mafy mba hahazoana sakafo, satria manome izay ilain’ny olona tiany izy sady manome azy ireo torimaso mamy.'),
  ('6ab25b251cf7e594093d47be', '2026-09-22T10:40:37.974Z', '2026-09-22T10:40:37.974Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 127, 3, 'Lova avy amin’i Jehovah ny zanaka maro, Ary valisoa ny aloaky ny kibo.', 'lova avy amin’i jehovah ny zanaka maro, ary valisoa ny aloaky ny kibo.'),
  ('6ab25b251cf7e594093d47bc', '2026-09-22T10:40:37.974Z', '2026-09-22T10:40:37.974Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 127, 1, 'Raha tsy i Jehovah no manao ny trano, Dia ho very maina ny asa mafy ataon’ny mpanorina azy. Ary raha tsy i Jehovah no miambina ny tanàna, Dia ho very maina ny fiaretan-torin’ny mpiambina.', 'raha tsy i jehovah no manao ny trano, dia ho very maina ny asa mafy ataon’ny mpanorina azy. ary raha tsy i jehovah no miambina ny tanàna, dia ho very maina ny fiaretan-torin’ny mpiambina.'),
  ('6ab25b251cf7e594093d47bf', '2026-09-22T10:40:37.974Z', '2026-09-22T10:40:37.974Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 127, 4, 'Toy ny zana-tsipìka eny an-tanan’ny lehilahy mahery Ny zanaky ny fahatanorana.', 'toy ny zana-tsipìka eny an-tanan’ny lehilahy mahery ny zanaky ny fahatanorana.'),
  ('6ab25b26c2cb0e9f9b3cab2f', '2026-09-22T10:40:38.410Z', '2026-09-22T10:40:38.410Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 128, 6, 'Ary ho hitanao ny zafikelinao! Enga anie ka hiadana ny Israely!', 'ary ho hitanao ny zafikelinao! enga anie ka hiadana ny israely!'),
  ('6ab25b26c2cb0e9f9b3cab2e', '2026-09-22T10:40:38.410Z', '2026-09-22T10:40:38.410Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 128, 5, 'Hitahy anao avy ao Ziona i Jehovah. Enga anie ka ho hitanao hoe mandroso be i Jerosalema, mandritra ny androm-piainanao,', 'hitahy anao avy ao ziona i jehovah. enga anie ka ho hitanao hoe mandroso be i jerosalema, mandritra ny androm-piainanao,'),
  ('6ab25b26c2cb0e9f9b3cab2d', '2026-09-22T10:40:38.410Z', '2026-09-22T10:40:38.410Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 128, 4, 'Toy izany no hitahiana Ny lehilahy matahotra an’i Jehovah.', 'toy izany no hitahiana ny lehilahy matahotra an’i jehovah.'),
  ('6ab25b26c2cb0e9f9b3cab2b', '2026-09-22T10:40:38.410Z', '2026-09-22T10:40:38.410Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 128, 2, 'Hihinana an’izay nisasaran’ny tananao ianao. Ho sambatra ianao sady hiadana.', 'hihinana an’izay nisasaran’ny tananao ianao. ho sambatra ianao sady hiadana.'),
