  ('6ab25b358add7e7bd064200e', '2026-09-22T10:40:53.902Z', '2026-09-22T10:40:53.902Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Salamo', 19, 149, 7, 'Mba hamaliana an’ireo firenena Sy hanasaziana ny vahoaka,', 'mba hamaliana an’ireo firenena sy hanasaziana ny vahoaka,'),
