  ('6ab25b379efd9497a1167b1a', '2026-09-22T10:40:55.503Z', '2026-09-22T10:40:55.503Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 1, 18, 'Izany no mahatonga azy ireo hiafina mba handatsa-dra. Miafina mba hanala ain’olona izy ireo.', 'izany no mahatonga azy ireo hiafina mba handatsa-dra. miafina mba hanala ain’olona izy ireo.'),
