  ('6ab25b551b8d9bd932e73251', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 11, 'Matoky azy amin’ny fony manontolo ny vadiny, Sady manana an’izay rehetra ilainy. ג [ Gimela ]', 'matoky azy amin’ny fony manontolo ny vadiny, sady manana an’izay rehetra ilainy. ג [ gimela ]'),
  ('6ab25b551b8d9bd932e7324e', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 8, 'Mitenena mba hiaro an’izay tsy afaka miteny, Ary arovy ny zon’izay rehetra efa ho faty.', 'mitenena mba hiaro an’izay tsy afaka miteny, ary arovy ny zon’izay rehetra efa ho faty.'),
  ('6ab25b551b8d9bd932e7324a', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 4, 'Tsy tsara ho an’ny mpanjaka, ry Lemoela ô, Tsy tsara ho an’ny mpanjaka ny misotro divay, Na ho an’ny mpitondra ny manontany hoe: “Aiza ny toakako?”', 'tsy tsara ho an’ny mpanjaka, ry lemoela ô, tsy tsara ho an’ny mpanjaka ny misotro divay, na ho an’ny mpitondra ny manontany hoe: “aiza ny toakako?”'),
  ('6ab25b551b8d9bd932e73262', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 28, 'Mitsangana ny zanany, ka milaza azy hoe sambatra. Mitsangana koa ny vadiny, ka midera azy hoe: ר [ Resa ]', 'mitsangana ny zanany, ka milaza azy hoe sambatra. mitsangana koa ny vadiny, ka midera azy hoe: ר [ resa ]'),
  ('6ab25b551b8d9bd932e73253', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 13, 'Mitady volonondry sy lamba rongony ilay vehivavy, Ary mahafinaritra azy ny miasa amin’ny tanany. ה [ He ]', 'mitady volonondry sy lamba rongony ilay vehivavy, ary mahafinaritra azy ny miasa amin’ny tanany. ה [ he ]'),
  ('6ab25b551b8d9bd932e73248', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 2, 'Inona no holazaiko aminao, anaka? Inona no holazaiko, ry ilay naloaky ny kiboko, Ilay zanaka azoko tamin’ny voady?', 'inona no holazaiko aminao, anaka? inona no holazaiko, ry ilay naloaky ny kiboko, ilay zanaka azoko tamin’ny voady?'),
  ('6ab25b551b8d9bd932e7325e', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 24, 'Manamboatra akanjo rongony izy, dia mivarotra an’izany. Mamatsy fehikibo ho an’ny mpivaro-mandeha koa izy. ע [ Aina ]', 'manamboatra akanjo rongony izy, dia mivarotra an’izany. mamatsy fehikibo ho an’ny mpivaro-mandeha koa izy. ע [ aina ]'),
  ('6ab25b551b8d9bd932e7324f', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 9, 'Mitenena ka mitsarà araka ny rariny. Arovy ny zon’ny madinika sy ny mahantra. א [ Alefa ]', 'mitenena ka mitsarà araka ny rariny. arovy ny zon’ny madinika sy ny mahantra. א [ alefa ]'),
  ('6ab25b551b8d9bd932e73249', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 3, 'Aza mandany ny herinao amin’ny vehivavy, Ary aza manaraka fomba fiaina ratsy, fa izany no mahatonga ny mpanjaka ho ripaka.', 'aza mandany ny herinao amin’ny vehivavy, ary aza manaraka fomba fiaina ratsy, fa izany no mahatonga ny mpanjaka ho ripaka.'),
  ('6ab25b551b8d9bd932e73258', '2026-09-22T10:41:25.432Z', '2026-09-22T10:41:25.432Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Ohabolana', 20, 31, 18, 'Hitany fa ahazoany tombony ny varotra ataony, Ary tsy maty jiro izy mandritra ny alina. י [ Yôda ]', 'hitany fa ahazoany tombony ny varotra ataony, ary tsy maty jiro izy mandritra ny alina. י [ yôda ]');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25b56358e42e293b74a3b', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 17, 'Niezaka tamin’ny foko manontolo aho hahalala ny atao hoe fahendrena sy ny atao hoe hadalana ary ny hoe manao adaladala. Misambo-drivotra fotsiny koa anefa izany.', 'niezaka tamin’ny foko manontolo aho hahalala ny atao hoe fahendrena sy ny atao hoe hadalana ary ny hoe manao adaladala. misambo-drivotra fotsiny koa anefa izany.'),
  ('6ab25b56358e42e293b74a35', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 11, 'Tsy misy mahatadidy an’izay olona efa tany aloha tany. Izay mbola ho avy koa tsy ho tadidin’izay handimby azy, Ary na ireo handimby ireo koa aza tsy ho tadidin’izay ho avy any aoriany.', 'tsy misy mahatadidy an’izay olona efa tany aloha tany. izay mbola ho avy koa tsy ho tadidin’izay handimby azy, ary na ireo handimby ireo koa aza tsy ho tadidin’izay ho avy any aoriany.'),
  ('6ab25b56358e42e293b74a2d', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 3, 'Inona no tombony azon’ny olona avy amin’ny asa mafy rehetra ataony, Dia izay isasarany etỳ ambanin’ny masoandro?', 'inona no tombony azon’ny olona avy amin’ny asa mafy rehetra ataony, dia izay isasarany etỳ ambanin’ny masoandro?'),
  ('6ab25b56358e42e293b74a32', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 8, 'Mandreraka daholo ny zava-drehetra, Ka tsy misy mahavita mitanisa an’izany. Tsy leon’ny mijery ny maso, Ary tsy leon’ny mihaino koa ny sofina.', 'mandreraka daholo ny zava-drehetra, ka tsy misy mahavita mitanisa an’izany. tsy leon’ny mijery ny maso, ary tsy leon’ny mihaino koa ny sofina.'),
  ('6ab25b56358e42e293b74a2b', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 1, 'Ny tenin’ilay mpamory vahoaka, ilay zanak’i Davida, ilay mpanjaka eto Jerosalema.', 'ny tenin’ilay mpamory vahoaka, ilay zanak’i davida, ilay mpanjaka eto jerosalema.'),
  ('6ab25b56358e42e293b74a2e', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 4, 'Lasa ny taranaka iray, ary mandimby azy ny taranaka iray, Fa ny tany kosa maharitra mandrakizay.', 'lasa ny taranaka iray, ary mandimby azy ny taranaka iray, fa ny tany kosa maharitra mandrakizay.'),
  ('6ab25b56358e42e293b74a2f', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 5, 'Miposaka ny masoandro, ary milentika, Dia avy eo miverina haingana any amin’ilay toerana iposahany indray.', 'miposaka ny masoandro, ary milentika, dia avy eo miverina haingana any amin’ilay toerana iposahany indray.'),
  ('6ab25b56358e42e293b74a3a', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 16, 'Dia hoy aho anakampo: “Nahazo fahendrena be aho, mihoatra noho izay rehetra talohako teto Jerosalema. Manana fahendrena sy fahalalana be koa aho ato am-poko.”', 'dia hoy aho anakampo: “nahazo fahendrena be aho, mihoatra noho izay rehetra talohako teto jerosalema. manana fahendrena sy fahalalana be koa aho ato am-poko.”'),
  ('6ab25b56358e42e293b74a36', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 12, 'Izaho mpamory vahoaka dia mpanjakan’ny Israely eto Jerosalema.', 'izaho mpamory vahoaka dia mpanjakan’ny israely eto jerosalema.'),
  ('6ab25b56358e42e293b74a31', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 7, 'Mikoriana mankany an-dranomasina daholo ny renirano, nefa tsy tondraka ny ranomasina. Any amin’izay niavian’ny renirano ihany no iverenany, dia avy any indray izy no mikoriana.', 'mikoriana mankany an-dranomasina daholo ny renirano, nefa tsy tondraka ny ranomasina. any amin’izay niavian’ny renirano ihany no iverenany, dia avy any indray izy no mikoriana.'),
  ('6ab25b56358e42e293b74a3c', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 18, 'Fa rehefa be ny fahendrena dia be koa ny fahasosorana. Rehefa mitombo àry ny fahalalana, dia mitombo koa ny fahoriana.', 'fa rehefa be ny fahendrena dia be koa ny fahasosorana. rehefa mitombo àry ny fahalalana, dia mitombo koa ny fahoriana.'),
  ('6ab25b56358e42e293b74a39', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 15, 'Izay mibilaka dia tsy azo ahitsy, Ary izay tsy eo tsy azo isaina.', 'izay mibilaka dia tsy azo ahitsy, ary izay tsy eo tsy azo isaina.'),
  ('6ab25b56358e42e293b74a38', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 14, 'Nodinihiko izay rehetra atao etỳ ambanin’ny masoandro, Ka hitako hoe tsisy dikany ny zava-drehetra fa misambo-drivotra fotsiny.', 'nodinihiko izay rehetra atao etỳ ambanin’ny masoandro, ka hitako hoe tsisy dikany ny zava-drehetra fa misambo-drivotra fotsiny.'),
  ('6ab25b56358e42e293b74a30', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 6, 'Mianatsimo ny rivotra, ary mihodina mianavaratra. Mihodinkodina foana izy, ary mihodinkodina tsy an-kijanona.', 'mianatsimo ny rivotra, ary mihodina mianavaratra. mihodinkodina foana izy, ary mihodinkodina tsy an-kijanona.'),
  ('6ab25b56358e42e293b74a2c', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 2, '“Tena tsisy dikany!”, hoy ilay mpamory vahoaka, “Tena tsisy dikany! Tsisy dikany ny zava-drehetra!”', '“tena tsisy dikany!”, hoy ilay mpamory vahoaka, “tena tsisy dikany! tsisy dikany ny zava-drehetra!”'),
  ('6ab25b56358e42e293b74a34', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 10, 'Angaha misy zavatra azon’ny olona lazaina hoe vaovao? Tsy misy fa efa nisy hatry ny ela ilay izy, Efa ela be talohan’izao androntsika izao.', 'angaha misy zavatra azon’ny olona lazaina hoe vaovao? tsy misy fa efa nisy hatry ny ela ilay izy, efa ela be talohan’izao androntsika izao.'),
  ('6ab25b56358e42e293b74a37', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 13, 'Niezaka tamin’ny foko manontolo aho nampiasa ny fahendreko, ka nandinika an’izay rehetra atao etỳ ambanin’ny lanitra. Nohadihadiko tsara koa ny asa nomen’Andriamanitra ny zanak’olombelona, izany hoe ny asa mampijaly ilofosan’izy ireo.', 'niezaka tamin’ny foko manontolo aho nampiasa ny fahendreko, ka nandinika an’izay rehetra atao etỳ ambanin’ny lanitra. nohadihadiko tsara koa ny asa nomen’andriamanitra ny zanak’olombelona, izany hoe ny asa mampijaly ilofosan’izy ireo.'),
  ('6ab25b56358e42e293b74a33', '2026-09-22T10:41:26.450Z', '2026-09-22T10:41:26.450Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 1, 9, 'Izay efa nitranga ihany no mbola hitranga, Ary izay efa natao ihany no mbola hatao. Tsy misy zava-baovao etỳ ambanin’ny masoandro.', 'izay efa nitranga ihany no mbola hitranga, ary izay efa natao ihany no mbola hatao. tsy misy zava-baovao etỳ ambanin’ny masoandro.'),
  ('6ab25b5712727b6911eea313', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 9, 'Vao mainka àry aho lasa ambony ka nihoarako daholo izay talohako teto Jerosalema. Mbola nanam-pahendrena foana anefa aho.', 'vao mainka àry aho lasa ambony ka nihoarako daholo izay talohako teto jerosalema. mbola nanam-pahendrena foana anefa aho.'),
  ('6ab25b5712727b6911eea31e', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 20, 'Dia namoy fo aho noho ny asa mafy rehetra nisasarako tetỳ ambanin’ny masoandro.', 'dia namoy fo aho noho ny asa mafy rehetra nisasarako tetỳ ambanin’ny masoandro.'),
  ('6ab25b5712727b6911eea314', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 10, 'Tsy mba nihafihafy mihitsy aho rehefa nisy zavatra niriko. Nataoko daholo izao zavatra mahafinaritra rehetra izao, satria nahafaly ny foko ny asa mafy rehetra nataoko. Izany no valisoa azoko, noho ny asa mafy rehetra nataoko.', 'tsy mba nihafihafy mihitsy aho rehefa nisy zavatra niriko. nataoko daholo izao zavatra mahafinaritra rehetra izao, satria nahafaly ny foko ny asa mafy rehetra nataoko. izany no valisoa azoko, noho ny asa mafy rehetra nataoko.'),
  ('6ab25b5712727b6911eea31a', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 16, 'Na ny hendry mantsy na ny adala, dia tsy hoe hotsaroana foana. Samy ho hadino daholo ny olona, rehefa any aoriana any. Ary ahoana no hahafatesan’ny hendry? Mitovy amin’ny hahafatesan’ny adala ihany.', 'na ny hendry mantsy na ny adala, dia tsy hoe hotsaroana foana. samy ho hadino daholo ny olona, rehefa any aoriana any. ary ahoana no hahafatesan’ny hendry? mitovy amin’ny hahafatesan’ny adala ihany.'),
  ('6ab25b5712727b6911eea322', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 24, 'Tsy misy mahasoa ny olona mihoatra noho ny hoe mihinana sy misotro, dia mankafy ny asa mafy ataony. Lasa fantatro koa fa avy amin’ilay tena Andriamanitra izany.', 'tsy misy mahasoa ny olona mihoatra noho ny hoe mihinana sy misotro, dia mankafy ny asa mafy ataony. lasa fantatro koa fa avy amin’ilay tena andriamanitra izany.'),
  ('6ab25b5712727b6911eea320', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 22, 'Fa inona no mba tombony azon’ny olona amin’ny asa mafy rehetra ataony sy ny fikirizany hiasa mafy, etỳ ambanin’ny masoandro?', 'fa inona no mba tombony azon’ny olona amin’ny asa mafy rehetra ataony sy ny fikirizany hiasa mafy, etỳ ambanin’ny masoandro?'),
  ('6ab25b5712727b6911eea30f', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 5, 'nanao zaridaina sy saha, dia namboly voankazo isan-karazany tao,', 'nanao zaridaina sy saha, dia namboly voankazo isan-karazany tao,'),
  ('6ab25b5712727b6911eea310', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 6, 'ary nanamboatra dobo be dia be hanondrahana ala kely mandrobona.', 'ary nanamboatra dobo be dia be hanondrahana ala kely mandrobona.'),
  ('6ab25b5712727b6911eea324', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 26, 'Ny olona mampifaly an’Andriamanitra no omeny fahendrena sy fahalalana ary fifaliana. Fa ny mpanota kosa ampiasainy hanangona fananana fotsiny, mba homena an’izay mampifaly an’ilay tena Andriamanitra. Tsisy dikany koa izany fa misambo-drivotra fotsiny.', 'ny olona mampifaly an’andriamanitra no omeny fahendrena sy fahalalana ary fifaliana. fa ny mpanota kosa ampiasainy hanangona fananana fotsiny, mba homena an’izay mampifaly an’ilay tena andriamanitra. tsisy dikany koa izany fa misambo-drivotra fotsiny.'),
  ('6ab25b5712727b6911eea319', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 15, 'Avy eo dia hoy aho anakampo: “Izay hiafaran’ny adala ihany no hiafarako.” Koa inona ny tombony azoko na dia lasa hendry be tahaka ny inona aza aho? Dia hoy aho anakampo: “Mbola tsisy dikany koa izany.”', 'avy eo dia hoy aho anakampo: “izay hiafaran’ny adala ihany no hiafarako.” koa inona ny tombony azoko na dia lasa hendry be tahaka ny inona aza aho? dia hoy aho anakampo: “mbola tsisy dikany koa izany.”'),
  ('6ab25b5712727b6911eea317', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 13, 'Dia hitako fa misy tombony kokoa noho ny hadalana ny fahendrena, mitovy amin’ny hoe misy tombony kokoa noho ny haizina ny hazavana.', 'dia hitako fa misy tombony kokoa noho ny hadalana ny fahendrena, mitovy amin’ny hoe misy tombony kokoa noho ny haizina ny hazavana.'),
  ('6ab25b5712727b6911eea316', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 12, 'Dia nofantariko indray ny atao hoe fahendrena sy hadalana ary ny hoe very saina. Inona moa no mba ho vitan’izay olona handimby ny mpanjaka? Izay efa natao teo aloha ihany.', 'dia nofantariko indray ny atao hoe fahendrena sy hadalana ary ny hoe very saina. inona moa no mba ho vitan’izay olona handimby ny mpanjaka? izay efa natao teo aloha ihany.'),
  ('6ab25b5712727b6911eea321', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 23, 'Fa mankarary ny fony sy mahasosotra azy foana izay ataony, mandritra ny androm-piainany. Na amin’ny alina aza dia mbola tsy tony koa ny fony. Tsisy dikany koa izany.', 'fa mankarary ny fony sy mahasosotra azy foana izay ataony, mandritra ny androm-piainany. na amin’ny alina aza dia mbola tsy tony koa ny fony. tsisy dikany koa izany.'),
  ('6ab25b5712727b6911eea318', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 14, 'Mahita tsara an’izay lalana halehany ny hendry, fa mirenireny ao amin’ny maizina kosa ny adala. Lasa fantatro koa fa mitovy ihany ny hiafaran’izy rehetra.', 'mahita tsara an’izay lalana halehany ny hendry, fa mirenireny ao amin’ny maizina kosa ny adala. lasa fantatro koa fa mitovy ihany ny hiafaran’izy rehetra.'),
  ('6ab25b5712727b6911eea312', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 8, 'Nahangona volafotsy sy volamena aho, dia ny harenan’ny mpanjaka sy ny an’ny faritany. Nahazo mpihira lahy sy vavy be dia be aho, sady nanana an’ilay tena mahafinaritra ny zanak’olombelona, dia ny vehivavy, ary vehivavy be dia be mihitsy aza.', 'nahangona volafotsy sy volamena aho, dia ny harenan’ny mpanjaka sy ny an’ny faritany. nahazo mpihira lahy sy vavy be dia be aho, sady nanana an’ilay tena mahafinaritra ny zanak’olombelona, dia ny vehivavy, ary vehivavy be dia be mihitsy aza.'),
  ('6ab25b5712727b6911eea30c', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 2, 'Hoy aho momba ny fihomehezana: “Hadalana fotsiny izany!” Ary hoy aho momba ny fahafinaretana: “Tsy mitondra mankaiza akory!”', 'hoy aho momba ny fihomehezana: “hadalana fotsiny izany!” ary hoy aho momba ny fahafinaretana: “tsy mitondra mankaiza akory!”'),
  ('6ab25b5712727b6911eea30d', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 3, 'Namantatra an’izany hoe manaram-po misotro divay izany aho, nefa mbola niezaka ny ho hendry koa. Nanandrana nanao hadalana mihitsy aza aho, mba hahafantarako an’izay zavatra tsara indrindra tokony hataon’ny olombelona etỳ ambanin’ny lanitra, mandritra ny andro vitsy iainany.', 'namantatra an’izany hoe manaram-po misotro divay izany aho, nefa mbola niezaka ny ho hendry koa. nanandrana nanao hadalana mihitsy aza aho, mba hahafantarako an’izay zavatra tsara indrindra tokony hataon’ny olombelona etỳ ambanin’ny lanitra, mandritra ny andro vitsy iainany.'),
  ('6ab25b5712727b6911eea30b', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 1, 'Dia hoy aho anakampo: “Andeha aho mba hanao izay mahafinaritra ahy, dia ho hitako eo raha tsara ny vokany.” Hitako anefa fa tsisy dikany koa izany.', 'dia hoy aho anakampo: “andeha aho mba hanao izay mahafinaritra ahy, dia ho hitako eo raha tsara ny vokany.” hitako anefa fa tsisy dikany koa izany.'),
  ('6ab25b5712727b6911eea323', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 25, 'Fa iza no nihinana sy nisotro zavatra tsara kokoa noho izaho?', 'fa iza no nihinana sy nisotro zavatra tsara kokoa noho izaho?'),
  ('6ab25b5712727b6911eea31f', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 21, 'Fa mety hiasa mafy ny olona iray ka hampiasa ny fahendreny sy ny fahalalany ary ny fahaizany, nefa avy eo izy voatery hanome ny fananany ho an’ny olona tsy nisasatra tamin’izany akory. Tsisy dikany koa izany ary tena loza.', 'fa mety hiasa mafy ny olona iray ka hampiasa ny fahendreny sy ny fahalalany ary ny fahaizany, nefa avy eo izy voatery hanome ny fananany ho an’ny olona tsy nisasatra tamin’izany akory. tsisy dikany koa izany ary tena loza.'),
  ('6ab25b5712727b6911eea31d', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 19, 'Ary iza no mahalala raha ho hendry izany olona izany na ho adala? Izaho no nikely aina niasa mafy sady nampiasa ny fahendreko rehetra, nefa dia izy no hanjaka amin’ny zavatra rehetra azoko tetỳ ambanin’ny masoandro. Tsisy dikany koa izany.', 'ary iza no mahalala raha ho hendry izany olona izany na ho adala? izaho no nikely aina niasa mafy sady nampiasa ny fahendreko rehetra, nefa dia izy no hanjaka amin’ny zavatra rehetra azoko tetỳ ambanin’ny masoandro. tsisy dikany koa izany.'),
  ('6ab25b5712727b6911eea31c', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 18, 'Lasa halako ny zavatra rehetra nisasarako tetỳ ambanin’ny masoandro, satria tsy maintsy avelako ho an’izay olona handimby ahy.', 'lasa halako ny zavatra rehetra nisasarako tetỳ ambanin’ny masoandro, satria tsy maintsy avelako ho an’izay olona handimby ahy.'),
  ('6ab25b5712727b6911eea31b', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 17, 'Lasa halako àry ny fiainana, satria hoatran’ny manorisory ahy daholo izay zavatra atao etỳ ambanin’ny masoandro. Fa tsisy dikany ny zava-drehetra fa misambo-drivotra fotsiny.', 'lasa halako àry ny fiainana, satria hoatran’ny manorisory ahy daholo izay zavatra atao etỳ ambanin’ny masoandro. fa tsisy dikany ny zava-drehetra fa misambo-drivotra fotsiny.'),
  ('6ab25b5712727b6911eea311', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 7, 'Nahazo mpanompo lahy sy vavy maro aho, ary nanana mpanompo teraka tao an-tranoko. Nanana biby fiompy be dia be koa aho, dia omby sy ondry aman’osy, mihoatra noho ny an’izay rehetra talohako teto Jerosalema.', 'nahazo mpanompo lahy sy vavy maro aho, ary nanana mpanompo teraka tao an-tranoko. nanana biby fiompy be dia be koa aho, dia omby sy ondry aman’osy, mihoatra noho ny an’izay rehetra talohako teto jerosalema.'),
  ('6ab25b5712727b6911eea315', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 11, 'Rehefa nisaintsaina ny zavatra rehetra nataon’ny tanako sy ny asa mafy rehetra nisasarako anefa aho, dia hitako hoe tsisy dikany ny zava-drehetra fa misambo-drivotra fotsiny. Tsy misy zavatra mba tena hoe misy vidiny etỳ ambanin’ny masoandro.', 'rehefa nisaintsaina ny zavatra rehetra nataon’ny tanako sy ny asa mafy rehetra nisasarako anefa aho, dia hitako hoe tsisy dikany ny zava-drehetra fa misambo-drivotra fotsiny. tsy misy zavatra mba tena hoe misy vidiny etỳ ambanin’ny masoandro.'),
  ('6ab25b5712727b6911eea30e', '2026-09-22T10:41:27.553Z', '2026-09-22T10:41:27.553Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 2, 4, 'Nanao zavatra miavaka be aho: Nanorina trano be dia be, nanao tanimboaloboka maro,', 'nanao zavatra miavaka be aho: nanorina trano be dia be, nanao tanimboaloboka maro,'),
  ('6ab25b5847edc5d699612bb3', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 16, 'Izao koa no hitako etỳ ambanin’ny masoandro: Ao amin’izay tokony hanjakan’ny rariny no misy faharatsiana, ary ao amin’izay tokony hanjakan’ny fahamarinana no misy faharatsiana.', 'izao koa no hitako etỳ ambanin’ny masoandro: ao amin’izay tokony hanjakan’ny rariny no misy faharatsiana, ary ao amin’izay tokony hanjakan’ny fahamarinana no misy faharatsiana.'),
  ('6ab25b5847edc5d699612bb1', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 14, 'Fantatro fa haharitra mandrakizay ny zava-drehetra nataon’ilay tena Andriamanitra. Tsy azo anampiana na analana izany. Nataon’Andriamanitra hoatr’izany mihitsy ny zava-drehetra, mba hahatonga ny olona hatahotra azy.', 'fantatro fa haharitra mandrakizay ny zava-drehetra nataon’ilay tena andriamanitra. tsy azo anampiana na analana izany. nataon’andriamanitra hoatr’izany mihitsy ny zava-drehetra, mba hahatonga ny olona hatahotra azy.'),
  ('6ab25b5847edc5d699612bae', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 11, 'Nataon’Andriamanitra tsara be daholo ny zava-drehetra, sady tamin’ny fotoanany avy. Nataony ao am-pon’ny olombelona mihitsy aza ny faniriana hiaina mandrakizay. Tsy ho takatry ny sain’ny olombelona hatramin’ny voalohany ka hatramin’ny farany mihitsy anefa izay ataon’ilay tena Andriamanitra.', 'nataon’andriamanitra tsara be daholo ny zava-drehetra, sady tamin’ny fotoanany avy. nataony ao am-pon’ny olombelona mihitsy aza ny faniriana hiaina mandrakizay. tsy ho takatry ny sain’ny olombelona hatramin’ny voalohany ka hatramin’ny farany mihitsy anefa izay ataon’ilay tena andriamanitra.'),
  ('6ab25b5847edc5d699612bb8', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 21, 'Iza no tena mahalala raha miakatra any ambony na tsia ny hery mamelona ny olombelona, ary raha midina amin’ny tany na tsia ny hery mamelona ny biby?', 'iza no tena mahalala raha miakatra any ambony na tsia ny hery mamelona ny olombelona, ary raha midina amin’ny tany na tsia ny hery mamelona ny biby?'),
  ('6ab25b5847edc5d699612bb6', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 19, 'Fa manam-piafarana ny olombelona ary manam-piafarana koa ny biby. Mitovy ihany ny hiafaran’izy ireo. Fa toy ny ahafatesan’ny biby ihany no ahafatesan’ny olona, ary iray ihany ny hery mamelona azy ireo. Tsy misy maha ambony ny olona amin’ny biby àry, fa tsisy dikany ny zava-drehetra.', 'fa manam-piafarana ny olombelona ary manam-piafarana koa ny biby. mitovy ihany ny hiafaran’izy ireo. fa toy ny ahafatesan’ny biby ihany no ahafatesan’ny olona, ary iray ihany ny hery mamelona azy ireo. tsy misy maha ambony ny olona amin’ny biby àry, fa tsisy dikany ny zava-drehetra.'),
  ('6ab25b5847edc5d699612bb0', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 13, 'Fantatro koa fa tokony hihinana sy hisotro ary hankafy ny asa mafy rehetra ataony daholo ny olona. Fanomezana avy amin’Andriamanitra izany.', 'fantatro koa fa tokony hihinana sy hisotro ary hankafy ny asa mafy rehetra ataony daholo ny olona. fanomezana avy amin’andriamanitra izany.'),
  ('6ab25b5847edc5d699612baf', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 12, 'Fantatro àry izao fa tsy misy mahasoa azy ireo mihoatra noho ny mifalifaly sy manao izay tsara mandritra ny androm-piainany.', 'fantatro àry izao fa tsy misy mahasoa azy ireo mihoatra noho ny mifalifaly sy manao izay tsara mandritra ny androm-piainany.'),
  ('6ab25b5847edc5d699612ba9', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 6, 'Misy fotoana itadiavana ary misy fotoana amoizana an’izay very. Misy fotoana itehirizana ary misy fotoana anariana.', 'misy fotoana itadiavana ary misy fotoana amoizana an’izay very. misy fotoana itehirizana ary misy fotoana anariana.'),
  ('6ab25b5847edc5d699612ba8', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 5, 'Misy fotoana anariana vato ary misy fotoana anangonana vato. Misy fotoana amihinana ary misy fotoana tsy amihinana.', 'misy fotoana anariana vato ary misy fotoana anangonana vato. misy fotoana amihinana ary misy fotoana tsy amihinana.'),
  ('6ab25b5847edc5d699612ba6', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 3, 'Misy fotoana amonoana ary misy fotoana anasitranana. Misy fotoana andravana ary misy fotoana anorenana.', 'misy fotoana amonoana ary misy fotoana anasitranana. misy fotoana andravana ary misy fotoana anorenana.'),
  ('6ab25b5847edc5d699612bb4', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 17, 'Dia hoy aho anakampo: “Samy hotsarain’ilay tena Andriamanitra ny olo-marina sy ny ratsy fanahy. Misy fotoanany avy mantsy ny zava-drehetra atao sy ny asa rehetra.”', 'dia hoy aho anakampo: “samy hotsarain’ilay tena andriamanitra ny olo-marina sy ny ratsy fanahy. misy fotoanany avy mantsy ny zava-drehetra atao sy ny asa rehetra.”'),
  ('6ab25b5847edc5d699612ba5', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 2, 'Misy fotoana ahaterahana ary misy fotoana ahafatesana. Misy fotoana ambolena ary misy fotoana anongotana an’izay nambolena.', 'misy fotoana ahaterahana ary misy fotoana ahafatesana. misy fotoana ambolena ary misy fotoana anongotana an’izay nambolena.'),
  ('6ab25b5847edc5d699612bb5', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 18, 'Ary niteny anakampo aho hoe hotsapain’Andriamanitra ny zanak’olombelona, ary hampahafantariny azy ireo fa toy ny biby ihany izy ireo.', 'ary niteny anakampo aho hoe hotsapain’andriamanitra ny zanak’olombelona, ary hampahafantariny azy ireo fa toy ny biby ihany izy ireo.'),
  ('6ab25b5847edc5d699612ba4', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 1, 'Misy fotoanany avy ny zava-drehetra, Eny, misy fotoanany daholo ny zava-drehetra atao etỳ ambanin’ny lanitra:', 'misy fotoanany avy ny zava-drehetra, eny, misy fotoanany daholo ny zava-drehetra atao etỳ ambanin’ny lanitra:'),
  ('6ab25b5847edc5d699612ba7', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 4, 'Misy fotoana itomaniana ary misy fotoana ihomehezana. Misy fotoana idradradradrana ary misy fotoana andihizana.', 'misy fotoana itomaniana ary misy fotoana ihomehezana. misy fotoana idradradradrana ary misy fotoana andihizana.'),
  ('6ab25b5847edc5d699612baa', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 7, 'Misy fotoana androvitana ary misy fotoana anjairana. Misy fotoana anginana ary misy fotoana itenenana.', 'misy fotoana androvitana ary misy fotoana anjairana. misy fotoana anginana ary misy fotoana itenenana.'),
  ('6ab25b5847edc5d699612bb7', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 20, 'Samy mankany amin’ny toerana iray izy rehetra. Avy tamin’ny vovoka daholo izy rehetra, ary hiverina ho vovoka daholo.', 'samy mankany amin’ny toerana iray izy rehetra. avy tamin’ny vovoka daholo izy rehetra, ary hiverina ho vovoka daholo.'),
  ('6ab25b5847edc5d699612bb2', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 15, 'Izay efa nitranga ihany no mitranga, ary izay efa nisy ihany no mbola hisy. Izay nokatsahin’ny olona ihany anefa no karohin’Andriamanitra.', 'izay efa nitranga ihany no mitranga, ary izay efa nisy ihany no mbola hisy. izay nokatsahin’ny olona ihany anefa no karohin’andriamanitra.'),
  ('6ab25b5847edc5d699612bb9', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 22, 'Hitako fa tsy misy mahasoa ny olona mihoatra noho ny mankafy ny asa ataony, satria izany no valisoany. Fa iza moa no afaka mampiseho azy an’izay hitranga rehefa maty izy?', 'hitako fa tsy misy mahasoa ny olona mihoatra noho ny mankafy ny asa ataony, satria izany no valisoany. fa iza moa no afaka mampiseho azy an’izay hitranga rehefa maty izy?'),
  ('6ab25b5847edc5d699612bad', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 10, 'Efa hitako ny asa nomen’Andriamanitra ny zanak’olombelona mba hataon’izy ireo.', 'efa hitako ny asa nomen’andriamanitra ny zanak’olombelona mba hataon’izy ireo.'),
  ('6ab25b5847edc5d699612bac', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 9, 'Inona no mba tombony azon’ny mpiasa amin’ny ezaka mafy rehetra ataony?', 'inona no mba tombony azon’ny mpiasa amin’ny ezaka mafy rehetra ataony?'),
  ('6ab25b5847edc5d699612bab', '2026-09-22T10:41:28.645Z', '2026-09-22T10:41:28.645Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 3, 8, 'Misy fotoana itiavana ary misy fotoana ankahalana. Misy fotoana iadiana ary misy fotoana ihavanana.', 'misy fotoana itiavana ary misy fotoana ankahalana. misy fotoana iadiana ary misy fotoana ihavanana.'),
  ('6ab25b594e7dcc3438302f6d', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 7, 'Nodinihiko indray ny zavatra hafa tsisy dikany etỳ ambanin’ny masoandro, ka izao no hitako:', 'nodinihiko indray ny zavatra hafa tsisy dikany etỳ ambanin’ny masoandro, ka izao no hitako:'),
  ('6ab25b594e7dcc3438302f6a', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 4, 'Ary hitako fa rehefa mifaninana ny olona, dia mahavita miezaka be sy mahavita asa tsara. Tsisy dikany koa izany fa misambo-drivotra fotsiny.', 'ary hitako fa rehefa mifaninana ny olona, dia mahavita miezaka be sy mahavita asa tsara. tsisy dikany koa izany fa misambo-drivotra fotsiny.'),
  ('6ab25b594e7dcc3438302f70', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 10, 'Fa raha lavo ny iray, dia afaka manampy azy hiarina ilay namany. Fa inona kosa no hanjo azy raha tsy misy manampy azy hiarina?', 'fa raha lavo ny iray, dia afaka manampy azy hiarina ilay namany. fa inona kosa no hanjo azy raha tsy misy manampy azy hiarina?'),
  ('6ab25b594e7dcc3438302f68', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 2, 'Amiko dia sambatra ny olona efa maty, raha oharina amin’izay mbola velona.', 'amiko dia sambatra ny olona efa maty, raha oharina amin’izay mbola velona.'),
  ('6ab25b594e7dcc3438302f73', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 13, 'Aleo ankizy mahantra nefa hendry, toy izay mpanjaka antitra nefa adala, ka tsy mahatsapa intsony hoe mila manaraka fampitandremana.', 'aleo ankizy mahantra nefa hendry, toy izay mpanjaka antitra nefa adala, ka tsy mahatsapa intsony hoe mila manaraka fampitandremana.'),
  ('6ab25b594e7dcc3438302f6c', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 6, 'Aleo fialan-tsasatra eran’ny tanan’ila, toy izay asa mafy eran’ny tanan-droa nefa misambo-drivotra fotsiny.', 'aleo fialan-tsasatra eran’ny tanan’ila, toy izay asa mafy eran’ny tanan-droa nefa misambo-drivotra fotsiny.'),
  ('6ab25b594e7dcc3438302f76', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 16, 'Tsy voaisa ny olona mpanohana azy. Atỳ aoriana anefa, dia tsy ho faly aminy intsony ny vahoaka. Tsisy dikany koa izany fa misambo-drivotra fotsiny.', 'tsy voaisa ny olona mpanohana azy. atỳ aoriana anefa, dia tsy ho faly aminy intsony ny vahoaka. tsisy dikany koa izany fa misambo-drivotra fotsiny.'),
  ('6ab25b594e7dcc3438302f75', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 15, 'Nodinihiko izay nitranga tamin’ny velona rehetra mandehandeha etỳ ambanin’ ny masoandro, sy tamin’ilay ankizy nandimby an’ilay mpanjaka.', 'nodinihiko izay nitranga tamin’ny velona rehetra mandehandeha etỳ ambanin’ ny masoandro, sy tamin’ilay ankizy nandimby an’ilay mpanjaka.'),
  ('6ab25b594e7dcc3438302f74', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 14, 'Fa avy nigadra izy no lasa mpanjaka, nefa nahantra izy tamin’izy teraka nandritra ny fitondran’io mpanjaka io.', 'fa avy nigadra izy no lasa mpanjaka, nefa nahantra izy tamin’izy teraka nandritra ny fitondran’io mpanjaka io.'),
  ('6ab25b594e7dcc3438302f6b', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 5, 'Kamo miasa ny tsisy saina, ka mahatonga loza ho an’ny tenany.', 'kamo miasa ny tsisy saina, ka mahatonga loza ho an’ny tenany.'),
  ('6ab25b594e7dcc3438302f67', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 1, 'Dia nodinihiko indray ny fampijaliana rehetra mitranga etỳ ambanin’ny masoandro. Hitako ny ranomason’ny olona ampijalina, nefa tsy mba nisy olona nampionona azy. Nanana fahefana mantsy ny mpampijaly azy, ka tsy mba nisy olona nampionona azy.', 'dia nodinihiko indray ny fampijaliana rehetra mitranga etỳ ambanin’ny masoandro. hitako ny ranomason’ny olona ampijalina, nefa tsy mba nisy olona nampionona azy. nanana fahefana mantsy ny mpampijaly azy, ka tsy mba nisy olona nampionona azy.'),
  ('6ab25b594e7dcc3438302f72', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 12, 'Ny olon-tokana mety ho resin’ny olona iray, fa raha olon-droa kosa hahatohitra azy. Ary tsy mora tapahina ny tady randran-telo.', 'ny olon-tokana mety ho resin’ny olona iray, fa raha olon-droa kosa hahatohitra azy. ary tsy mora tapahina ny tady randran-telo.'),
  ('6ab25b594e7dcc3438302f6f', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 9, 'Tsara ny roa noho ny iray, satria ahazoan’izy ireo valisoa lehibe ny asa mafy ataony.', 'tsara ny roa noho ny iray, satria ahazoan’izy ireo valisoa lehibe ny asa mafy ataony.'),
  ('6ab25b594e7dcc3438302f71', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 11, 'Raha miara-matory ny roa dia hafana. Fa ahoana kosa no hampahafana olona iray ihany?', 'raha miara-matory ny roa dia hafana. fa ahoana kosa no hampahafana olona iray ihany?'),
  ('6ab25b594e7dcc3438302f69', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 3, 'Mbola sambatra noho ireo anefa izay mbola tsy teraka, satria tsy mahita ny zava-dratsy mitranga etỳ ambanin’ny masoandro.', 'mbola sambatra noho ireo anefa izay mbola tsy teraka, satria tsy mahita ny zava-dratsy mitranga etỳ ambanin’ny masoandro.'),
  ('6ab25b594e7dcc3438302f6e', '2026-09-22T10:41:29.117Z', '2026-09-22T10:41:29.117Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 4, 8, 'Misy olona irery sady tsy mba mana-namana. Tsy mba manan-janaka na rahalahy koa izy, nefa tsy misy farany ny asa mafy ataony. Tsy mety afa-po amin’ny harena mihitsy ny masony. Mba mieritreritra anefa ve izy hoe: ‘Ho an’iza moa no iasako mafy hoatr’izao? Ary ho an’iza no mahatonga ahy hihafy sy tsy hankafy zavatra tsara’? Tsisy dikany koa izany sady asa mampahory.', 'misy olona irery sady tsy mba mana-namana. tsy mba manan-janaka na rahalahy koa izy, nefa tsy misy farany ny asa mafy ataony. tsy mety afa-po amin’ny harena mihitsy ny masony. mba mieritreritra anefa ve izy hoe: ‘ho an’iza moa no iasako mafy hoatr’izao? ary ho an’iza no mahatonga ahy hihafy sy tsy hankafy zavatra tsara’? tsisy dikany koa izany sady asa mampahory.'),
  ('6ab25b59355f0c708edfa593', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 9, 'Ifampizaran’izy rehetra koa ny tombony azo avy amin’ny tany. Ary na ny mpanjaka aza mila ny vokatra avy eny an-tsaha.', 'ifampizaran’izy rehetra koa ny tombony azo avy amin’ny tany. ary na ny mpanjaka aza mila ny vokatra avy eny an-tsaha.'),
  ('6ab25b59355f0c708edfa592', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 8, 'Aza gaga ianao raha mahita hoe ampijalina ny mahantra ary hitsakitsahina ny rariny sy ny hitsiny, ao amin’ny faritaninao. Fa ny manam-pahefana ambony toy izany dia dinihin’ny olona ambony kokoa noho izy, ary mbola misy ambony kokoa noho izy ireo.', 'aza gaga ianao raha mahita hoe ampijalina ny mahantra ary hitsakitsahina ny rariny sy ny hitsiny, ao amin’ny faritaninao. fa ny manam-pahefana ambony toy izany dia dinihin’ny olona ambony kokoa noho izy, ary mbola misy ambony kokoa noho izy ireo.'),
  ('6ab25b59355f0c708edfa59b', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 17, 'Misakafo ao anatin’ny haizina izy isan’andro, sady sorena be sy marary ary tezitra.', 'misakafo ao anatin’ny haizina izy isan’andro, sady sorena be sy marary ary tezitra.'),
  ('6ab25b59355f0c708edfa597', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 13, 'Izao no tena loza hitako etỳ ambanin’ny masoandro: Ny harena nangonin’ny tompony ihany no mampidi-kizo azy.', 'izao no tena loza hitako etỳ ambanin’ny masoandro: ny harena nangonin’ny tompony ihany no mampidi-kizo azy.'),
  ('6ab25b59355f0c708edfa58d', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 3, 'Fa ny adin-tsaina be loatra no mahatonga nofy, ary lasa miteniteny foana ny tsisy saina rehefa be resaka loatra.', 'fa ny adin-tsaina be loatra no mahatonga nofy, ary lasa miteniteny foana ny tsisy saina rehefa be resaka loatra.'),
  ('6ab25b59355f0c708edfa598', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 14, 'Ary ritra izany harena izany satria tsy nahomby ny zavatra nataony. Dia lasa tsy manana na inona na inona intsony izy rehefa manan-janaka lahy.', 'ary ritra izany harena izany satria tsy nahomby ny zavatra nataony. dia lasa tsy manana na inona na inona intsony izy rehefa manan-janaka lahy.'),
  ('6ab25b59355f0c708edfa58b', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 1, 'Mitandrema tsara ianao isaky ny mankao an-tranon’ilay tena Andriamanitra. Fa aleo mankao mba hihaino, toy izay manao sorona hoatran’ny ataon’ny tsisy saina. Tsy fantany akory mantsy hoe ratsy ny ataony.', 'mitandrema tsara ianao isaky ny mankao an-tranon’ilay tena andriamanitra. fa aleo mankao mba hihaino, toy izay manao sorona hoatran’ny ataon’ny tsisy saina. tsy fantany akory mantsy hoe ratsy ny ataony.'),
  ('6ab25b59355f0c708edfa591', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 7, 'Fa ny adin-tsaina be loatra no mahatonga nofy, dia hoatr’izany koa fa lasa miteniteny foana izay be resaka loatra. Matahora anefa an’ilay tena Andriamanitra.', 'fa ny adin-tsaina be loatra no mahatonga nofy, dia hoatr’izany koa fa lasa miteniteny foana izay be resaka loatra. matahora anefa an’ilay tena andriamanitra.'),
  ('6ab25b59355f0c708edfa59c', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 18, 'Izao no zavatra hitako hoe tsara sy mety: Tokony hihinana sy hisotro ary hankafy ny asa mafy isasarany etỳ ambanin’ny masoandro ny olona, mandritra ny andro vitsy omen’Andriamanitra azy, fa izany no valisoany.', 'izao no zavatra hitako hoe tsara sy mety: tokony hihinana sy hisotro ary hankafy ny asa mafy isasarany etỳ ambanin’ny masoandro ny olona, mandritra ny andro vitsy omen’andriamanitra azy, fa izany no valisoany.'),
  ('6ab25b59355f0c708edfa599', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 15, 'Mitanjaka ny olona rehefa nivoaka avy tao an-kibon-dreniny, ary toy izany koa izy rehefa maty. Tsy afaka mitondra na inona na inona avy amin’ny asa mafy nataony izy.', 'mitanjaka ny olona rehefa nivoaka avy tao an-kibon-dreniny, ary toy izany koa izy rehefa maty. tsy afaka mitondra na inona na inona avy amin’ny asa mafy nataony izy.'),
  ('6ab25b59355f0c708edfa58e', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 4, 'Raha mivoady amin’Andriamanitra ianao, dia aza miandry ela vao manatanteraka, satria tsy mahafaly azy ny tsisy saina. Koa tanteraho ny voadinao.', 'raha mivoady amin’andriamanitra ianao, dia aza miandry ela vao manatanteraka, satria tsy mahafaly azy ny tsisy saina. koa tanteraho ny voadinao.'),
  ('6ab25b59355f0c708edfa596', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 12, 'Mamy ny torimason’ny mpanompo, na kely na betsaka ny sakafony, fa ny habetsahan’ny fananan’ny mpanankarena kosa no tsy ahitany tory.', 'mamy ny torimason’ny mpanompo, na kely na betsaka ny sakafony, fa ny habetsahan’ny fananan’ny mpanankarena kosa no tsy ahitany tory.'),
  ('6ab25b59355f0c708edfa59e', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 20, 'Fa tsy tena ho tsapany hoe mandalo ihany ny androm-piainany, satria ataon’ilay tena Andriamanitra revo amin’ny zavatra mahafaly ny fony izy.', 'fa tsy tena ho tsapany hoe mandalo ihany ny androm-piainany, satria ataon’ilay tena andriamanitra revo amin’ny zavatra mahafaly ny fony izy.'),
  ('6ab25b59355f0c708edfa595', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 11, 'Rehefa mitombo ny harena, dia mitombo koa ny mpihinana azy. Dia inona moa no soa azon’ny tompony amin’izany afa-tsy ny mijery an’ilay izy fotsiny?', 'rehefa mitombo ny harena, dia mitombo koa ny mpihinana azy. dia inona moa no soa azon’ny tompony amin’izany afa-tsy ny mijery an’ilay izy fotsiny?'),
  ('6ab25b59355f0c708edfa594', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 10, 'Tsy ho afa-po amin’izay volafotsy ananany mihitsy izay tia volafotsy. Ary tsy ho afa-po amin’izay harena azony izay tia harena. Tsisy dikany koa izany.', 'tsy ho afa-po amin’izay volafotsy ananany mihitsy izay tia volafotsy. ary tsy ho afa-po amin’izay harena azony izay tia harena. tsisy dikany koa izany.'),
  ('6ab25b59355f0c708edfa59a', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 16, 'Izao koa ny tena loza: Hoatran’ny tamin’izy teraka ihany ny olona rehefa lasa. Koa inona moa no tombony azon’izay miasa mafy ho an’ny rivotra fotsiny?', 'izao koa ny tena loza: hoatran’ny tamin’izy teraka ihany ny olona rehefa lasa. koa inona moa no tombony azon’izay miasa mafy ho an’ny rivotra fotsiny?'),
  ('6ab25b59355f0c708edfa58f', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 5, 'Aleo tsy mivoady, toy izay mivoady nefa tsy manatanteraka.', 'aleo tsy mivoady, toy izay mivoady nefa tsy manatanteraka.'),
  ('6ab25b59355f0c708edfa590', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 6, 'Aza avela hampanota anao ny vavanao, ary aza miteny eo anatrehan’ny anjely hoe: “Diso aho tamin’iny.” Maninona ianao no mampahatezitra an’Andriamanitra amin’izay lazainao, ka voatery handrava ny asan’ny tananao izy?', 'aza avela hampanota anao ny vavanao, ary aza miteny eo anatrehan’ny anjely hoe: “diso aho tamin’iny.” maninona ianao no mampahatezitra an’andriamanitra amin’izay lazainao, ka voatery handrava ny asan’ny tananao izy?'),
  ('6ab25b59355f0c708edfa58c', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 2, 'Aza faingam-bava, ary aza entim-po fotsiny ka lasa maika hiteny eo anatrehan’ilay tena Andriamanitra. Fa izy any an-danitra ary ianao kosa etỳ an-tany, ka tsy tokony hiteny betsaka ianao.', 'aza faingam-bava, ary aza entim-po fotsiny ka lasa maika hiteny eo anatrehan’ilay tena andriamanitra. fa izy any an-danitra ary ianao kosa etỳ an-tany, ka tsy tokony hiteny betsaka ianao.'),
  ('6ab25b59355f0c708edfa59d', '2026-09-22T10:41:29.788Z', '2026-09-22T10:41:29.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 5, 19, 'Rehefa omen’Andriamanitra harena sy fananana ny olona sady avelany hankafy an’ireny, dia tokony handray ny valisoany izy ka hifaly amin’ny asa mafy ataony. Fanomezana avy amin’Andriamanitra izany.', 'rehefa omen’andriamanitra harena sy fananana ny olona sady avelany hankafy an’ireny, dia tokony handray ny valisoany izy ka hifaly amin’ny asa mafy ataony. fanomezana avy amin’andriamanitra izany.'),
  ('6ab25b5a0b8a4ecb4fa45656', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 11, 'Arakaraka ny itenenana be no mampiteniteny foana. Dia inona no tombony azon’ny olona amin’izany?', 'arakaraka ny itenenana be no mampiteniteny foana. dia inona no tombony azon’ny olona amin’izany?'),
  ('6ab25b5a0b8a4ecb4fa45653', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 8, 'Inona no tombony ananan’ny hendry raha oharina amin’ny adala? Ary inona no soa azon’ny mahantra raha mahay mitady izay hahavelona azy fotsiny izy?', 'inona no tombony ananan’ny hendry raha oharina amin’ny adala? ary inona no soa azon’ny mahantra raha mahay mitady izay hahavelona azy fotsiny izy?'),
  ('6ab25b5a0b8a4ecb4fa45654', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 9, 'Aleo mifaly amin’izay hitan’ny maso toy izay mitsiriritra zavatra tsy ho azo. Tsisy dikany koa izany fa misambo-drivotra fotsiny.', 'aleo mifaly amin’izay hitan’ny maso toy izay mitsiriritra zavatra tsy ho azo. tsisy dikany koa izany fa misambo-drivotra fotsiny.'),
  ('6ab25b5a0b8a4ecb4fa45657', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 12, 'Iza no mahalala hoe inona ny zavatra tsara indrindra tokony hataon’ny olona mandritra ny andro vitsy iainany, amin’izao fiainana poakaty sy mandalo toy ny aloka izao? Fa iza no afaka milaza amin’ny olona an’izay hitranga etỳ ambanin’ny masoandro rehefa maty izy?', 'iza no mahalala hoe inona ny zavatra tsara indrindra tokony hataon’ny olona mandritra ny andro vitsy iainany, amin’izao fiainana poakaty sy mandalo toy ny aloka izao? fa iza no afaka milaza amin’ny olona an’izay hitranga etỳ ambanin’ny masoandro rehefa maty izy?'),
  ('6ab25b5a0b8a4ecb4fa4564c', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 1, 'Misy loza hafa koa hitako etỳ ambanin’ny masoandro, sady fahita eo amin’ny olona:', 'misy loza hafa koa hitako etỳ ambanin’ny masoandro, sady fahita eo amin’ny olona:'),
  ('6ab25b5a0b8a4ecb4fa4564d', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 2, 'Misy olona omen’ilay tena Andriamanitra harena sy fananana ary voninahitra, ka azony daholo izay iriny. Tsy avelan’Andriamanitra hankafy an’ireny akory anefa izy, fa olon-kafa indray no mankafy azy. Tsisy dikany izany sady tena mampalahelo.', 'misy olona omen’ilay tena andriamanitra harena sy fananana ary voninahitra, ka azony daholo izay iriny. tsy avelan’andriamanitra hankafy an’ireny akory anefa izy, fa olon-kafa indray no mankafy azy. tsisy dikany izany sady tena mampalahelo.'),
  ('6ab25b5a0b8a4ecb4fa45652', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 7, 'Ny asa mafy rehetra ataon’ny olona dia mba hahavoky ny kibony, nefa tsy mety afa-po mihitsy izy.', 'ny asa mafy rehetra ataon’ny olona dia mba hahavoky ny kibony, nefa tsy mety afa-po mihitsy izy.'),
  ('6ab25b5a0b8a4ecb4fa45650', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 5, 'Tsy nahita masoandro mihitsy izy sady tsy nahalala na inona na inona, nefa aleo ny nanjo azy toy izay ny nanjo an’ilay lehilahy tratrantitra.', 'tsy nahita masoandro mihitsy izy sady tsy nahalala na inona na inona, nefa aleo ny nanjo azy toy izay ny nanjo an’ilay lehilahy tratrantitra.'),
  ('6ab25b5a0b8a4ecb4fa45651', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 6, 'Inona moa no tombony azo raha hoe velona arivo taona, na roa arivo taona aza, nefa tsy mankafy fiainana akory? Angaha tsy mitovy ihany ny toerana alehan’ny olona rehetra?', 'inona moa no tombony azo raha hoe velona arivo taona, na roa arivo taona aza, nefa tsy mankafy fiainana akory? angaha tsy mitovy ihany ny toerana alehan’ny olona rehetra?'),
  ('6ab25b5a0b8a4ecb4fa4564f', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 4, 'Tsisy dikany ny nahatongavan’ilay zaza ary tao anaty haizina izy no lasa, sady rakotry ny haizina ny anarany.', 'tsisy dikany ny nahatongavan’ilay zaza ary tao anaty haizina izy no lasa, sady rakotry ny haizina ny anarany.'),
  ('6ab25b5a0b8a4ecb4fa4564e', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 3, 'Na dia miteraka zato aza ny lehilahy iray, ary ela velona sy tratrantitra, nefa tsy mankafy ny zavatra tsara ananany izy raha mbola tsy tonga any am-pasana, dia hoy aho hoe ny zaza maty tao an-kibon-dreniny aza mbola tsara kokoa noho izy.', 'na dia miteraka zato aza ny lehilahy iray, ary ela velona sy tratrantitra, nefa tsy mankafy ny zavatra tsara ananany izy raha mbola tsy tonga any am-pasana, dia hoy aho hoe ny zaza maty tao an-kibon-dreniny aza mbola tsara kokoa noho izy.'),
  ('6ab25b5a0b8a4ecb4fa45655', '2026-09-22T10:41:30.409Z', '2026-09-22T10:41:30.409Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 6, 10, 'Izay misy amin’izao dia efa nomena anarana taloha ihany, ary lasa fantatra tsara hoe hoatran’ny ahoana marina ny olona. Tsy afaka mifamaly amin’izay mahery noho izy koa izy.', 'izay misy amin’izao dia efa nomena anarana taloha ihany, ary lasa fantatra tsara hoe hoatran’ny ahoana marina ny olona. tsy afaka mifamaly amin’izay mahery noho izy koa izy.'),
  ('6ab25b5ba76b9717ef0255a4', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 21, 'Aza raisina am-po daholo ny teny rehetra lazain’ny olona, sao ianao haheno ny mpanomponao manozona anao.', 'aza raisina am-po daholo ny teny rehetra lazain’ny olona, sao ianao haheno ny mpanomponao manozona anao.'),
  ('6ab25b5ba76b9717ef025597', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 8, 'Aleo ny fiafaran’ny raharaha toy izay ny fiandohany. Aleo olona manam-paharetana toy izay olona manambony tena.', 'aleo ny fiafaran’ny raharaha toy izay ny fiandohany. aleo olona manam-paharetana toy izay olona manambony tena.'),
  ('6ab25b5ba76b9717ef0255aa', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 27, '“Izao no hitako”, hoy ilay mpamory vahoaka, “rehefa avy nodinihiko tsirairay ny zava-drehetra mba hahitako an’izay hamintinako azy,', '“izao no hitako”, hoy ilay mpamory vahoaka, “rehefa avy nodinihiko tsirairay ny zava-drehetra mba hahitako an’izay hamintinako azy,'),
  ('6ab25b5ba76b9717ef025598', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 9, 'Aza mora tezitra, fa toetran’ny adala izany mora tezitra izany.', 'aza mora tezitra, fa toetran’ny adala izany mora tezitra izany.'),
  ('6ab25b5ba76b9717ef025595', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 6, 'Fa toy ny tsilo mirehitra sady mipoapoaka ao ambany vilany ny fihomehezan’ny adala. Tsisy dikany koa izany.', 'fa toy ny tsilo mirehitra sady mipoapoaka ao ambany vilany ny fihomehezan’ny adala. tsisy dikany koa izany.'),
  ('6ab25b5ba76b9717ef025594', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 5, 'Aleo mihaino ny anatra mafy omen’ny olon-kendry toy izay mihaino ny hiran’ny adala.', 'aleo mihaino ny anatra mafy omen’ny olon-kendry toy izay mihaino ny hiran’ny adala.'),
  ('6ab25b5ba76b9717ef0255a9', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 26, 'Dia izao no hitako: Mangidy noho ny fahafatesana ny vehivavy hoatran’ny harato famandrihana, nefa koa ny fony toy ny harato tarihina, ary ny tanany toy ny gadra vy. Ny olona mampifaly an’ilay tena Andriamanitra no ho afaka hiala aminy, fa ny mpanota kosa azony.', 'dia izao no hitako: mangidy noho ny fahafatesana ny vehivavy hoatran’ny harato famandrihana, nefa koa ny fony toy ny harato tarihina, ary ny tanany toy ny gadra vy. ny olona mampifaly an’ilay tena andriamanitra no ho afaka hiala aminy, fa ny mpanota kosa azony.'),
  ('6ab25b5ba76b9717ef02559e', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 15, 'Efa hitako daholo ny zava-drehetra, nandritra ny fiainana poakaty niainako. Hitako ny olo-marina maty nefa nanao ny tsara, ary hitako koa ny ratsy fanahy ela velona nefa manao ratsy.', 'efa hitako daholo ny zava-drehetra, nandritra ny fiainana poakaty niainako. hitako ny olo-marina maty nefa nanao ny tsara, ary hitako koa ny ratsy fanahy ela velona nefa manao ratsy.'),
  ('6ab25b5ba76b9717ef025596', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 7, 'Mety hanaonao foana anefa ny hendry rehefa ampijalina. Ary mety hanimba ny fo ny kolikoly.', 'mety hanaonao foana anefa ny hendry rehefa ampijalina. ary mety hanimba ny fo ny kolikoly.'),
  ('6ab25b5ba76b9717ef025593', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 4, 'Ao amin’ny trano misy fisaonana ny fon’ny hendry, fa ao amin’ny trano misy fety kosa ny fon’ny adala.', 'ao amin’ny trano misy fisaonana ny fon’ny hendry, fa ao amin’ny trano misy fety kosa ny fon’ny adala.'),
  ('6ab25b5ba76b9717ef02559b', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 12, 'Fiarovana hoatran’ny vola ihany mantsy ny fahendrena. Izao anefa ny tombony azo amin’ny fahalalana: Rehefa ampiarahina amin’ny fahendrena izy io, dia miaro ny ain’izay manana azy.', 'fiarovana hoatran’ny vola ihany mantsy ny fahendrena. izao anefa ny tombony azo amin’ny fahalalana: rehefa ampiarahina amin’ny fahendrena izy io, dia miaro ny ain’izay manana azy.'),
  ('6ab25b5ba76b9717ef0255ac', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 29, 'Izao ihany no hitako: Mahitsy fo no nanaovan’ilay tena Andriamanitra ny olombelona, saingy naleon’izy ireo namorona tetika be dia be.”', 'izao ihany no hitako: mahitsy fo no nanaovan’ilay tena andriamanitra ny olombelona, saingy naleon’izy ireo namorona tetika be dia be.”'),
  ('6ab25b5ba76b9717ef0255ab', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 28, 'nefa tsy hitako akory izay efa nokarohiko foana: Tamin’ny olona arivo, dia nahita lehilahy iray manao ny marina aho, fa tsy nahita vehivavy manao ny marina na iray aza.', 'nefa tsy hitako akory izay efa nokarohiko foana: tamin’ny olona arivo, dia nahita lehilahy iray manao ny marina aho, fa tsy nahita vehivavy manao ny marina na iray aza.'),
  ('6ab25b5ba76b9717ef0255a5', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 22, 'Fantatrao tsara mantsy fa na ianao koa aza mba efa imbetsaka no nanozona ny hafa.', 'fantatrao tsara mantsy fa na ianao koa aza mba efa imbetsaka no nanozona ny hafa.'),
  ('6ab25b5ba76b9717ef02559a', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 11, 'Tsara sady tombony ho an’izay mahita masoandro ny fahendrena raha mbola ampiana lova.', 'tsara sady tombony ho an’izay mahita masoandro ny fahendrena raha mbola ampiana lova.'),
  ('6ab25b5ba76b9717ef0255a7', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 24, 'Tsy takatry ny saina ny zava-mitranga rehetra fa lalina dia lalina. Iza no mahatakatra an’izany?', 'tsy takatry ny saina ny zava-mitranga rehetra fa lalina dia lalina. iza no mahatakatra an’izany?'),
  ('6ab25b5ba76b9717ef0255a1', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 18, 'Tena tsara raha arahinao ilay anatra voalohany, sady tsy lavinao koa ilay faharoa. Fa izay matahotra an’Andriamanitra no hanaraka an’ireo anatra roa ireo.', 'tena tsara raha arahinao ilay anatra voalohany, sady tsy lavinao koa ilay faharoa. fa izay matahotra an’andriamanitra no hanaraka an’ireo anatra roa ireo.'),
  ('6ab25b5ba76b9717ef0255a0', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 17, 'Aza ratsy toetra loatra, ary aza manao adaladala. Fa nahoana ianao no ho faty aloha be?', 'aza ratsy toetra loatra, ary aza manao adaladala. fa nahoana ianao no ho faty aloha be?'),
  ('6ab25b5ba76b9717ef0255a2', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 19, 'Ny fahendrena no mahatonga ny lehilahy hendry iray hahery kokoa noho ny lehilahy matanjaka folo ao amin’ny tanàna iray.', 'ny fahendrena no mahatonga ny lehilahy hendry iray hahery kokoa noho ny lehilahy matanjaka folo ao amin’ny tanàna iray.'),
  ('6ab25b5ba76b9717ef02559c', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 13, 'Diniho ny asan’ilay tena Andriamanitra, fa iza no afaka manitsy an’izay efa nataony mibilaka?', 'diniho ny asan’ilay tena andriamanitra, fa iza no afaka manitsy an’izay efa nataony mibilaka?'),
  ('6ab25b5ba76b9717ef0255a8', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 25, 'Tapa-kevitra aho ny hamantatra sy handinika ary hikaroka ny atao hoe fahendrena sy ny antony mampisy ny zava-drehetra. Niezaka mafy koa aho ny hahatakatra fa ratsy ny hoe tsisy saina ary hadalana ny hoe very saina.', 'tapa-kevitra aho ny hamantatra sy handinika ary hikaroka ny atao hoe fahendrena sy ny antony mampisy ny zava-drehetra. niezaka mafy koa aho ny hahatakatra fa ratsy ny hoe tsisy saina ary hadalana ny hoe very saina.'),
  ('6ab25b5ba76b9717ef0255a6', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 23, 'Nampiasa ny fahendreko aho ka nodinihiko izany rehetra izany. Dia hoy aho: “Ho hendry aho.” Tsy lasa hendry mihitsy anefa aho.', 'nampiasa ny fahendreko aho ka nodinihiko izany rehetra izany. dia hoy aho: “ho hendry aho.” tsy lasa hendry mihitsy anefa aho.'),
  ('6ab25b5ba76b9717ef025599', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 10, 'Aza miteny hoe: “Fa maninona re no tsara noho ny amin’izao ny taloha e?” Tsy fahendrena ho anao mantsy ny manontany an’izany.', 'aza miteny hoe: “fa maninona re no tsara noho ny amin’izao ny taloha e?” tsy fahendrena ho anao mantsy ny manontany an’izany.'),
  ('6ab25b5ba76b9717ef0255a3', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 20, 'Tsy misy olo-marina mahavita manao ny tsara foana mantsy eto ambonin’ny tany, fa tsy maintsy manota ihany izy.', 'tsy misy olo-marina mahavita manao ny tsara foana mantsy eto ambonin’ny tany, fa tsy maintsy manota ihany izy.'),
  ('6ab25b5ba76b9717ef025591', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 2, 'Aleo mankany amin’ny trano misy fisaonana toy izay mankany amin’ny trano misy fanasana, satria fahafatesana no hiafaran’ny olombelona rehetra, ka tokony hisaintsaina an’izany ny velona.', 'aleo mankany amin’ny trano misy fisaonana toy izay mankany amin’ny trano misy fanasana, satria fahafatesana no hiafaran’ny olombelona rehetra, ka tokony hisaintsaina an’izany ny velona.'),
  ('6ab25b5ba76b9717ef02559f', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 16, 'Aza marina loatra, ary aza miseho ho hendry loatra. Fa nahoana ianao no dia mampidi-kizo ny tenanao?', 'aza marina loatra, ary aza miseho ho hendry loatra. fa nahoana ianao no dia mampidi-kizo ny tenanao?'),
  ('6ab25b5ba76b9717ef02559d', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 14, 'Amin’ny fotoana mahafaly dia mifalia ka manehoa toetra tsara. Amin’ny fotoan-tsarotra kosa dia tadidio fa samy nataon’Andriamanitra ireo fotoana ireo mba tsy hahafantaran’ny olona an’izay hitranga aminy any aoriana any.', 'amin’ny fotoana mahafaly dia mifalia ka manehoa toetra tsara. amin’ny fotoan-tsarotra kosa dia tadidio fa samy nataon’andriamanitra ireo fotoana ireo mba tsy hahafantaran’ny olona an’izay hitranga aminy any aoriana any.'),
  ('6ab25b5ba76b9717ef025592', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 3, 'Aleo alahelo toy izay fihomehezana, satria mahatsara fo ny endrika malahelohelo.', 'aleo alahelo toy izay fihomehezana, satria mahatsara fo ny endrika malahelohelo.'),
  ('6ab25b5ba76b9717ef025590', '2026-09-22T10:41:31.047Z', '2026-09-22T10:41:31.047Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 7, 1, 'Aleo laza tsara toy izay menaka manitra, ary aleo ny andro ahafatesana toy izay ny andro ahaterahana.', 'aleo laza tsara toy izay menaka manitra, ary aleo ny andro ahafatesana toy izay ny andro ahaterahana.'),
  ('6ab25b5b011a028de332c816', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 6, 'Fa be loatra ny olana mahazo ny olombelona, ka tokony halaminy amin’ny fotoana mety sy araka ny tokony ho izy daholo ny zava-drehetra.', 'fa be loatra ny olana mahazo ny olombelona, ka tokony halaminy amin’ny fotoana mety sy araka ny tokony ho izy daholo ny zava-drehetra.'),
  ('6ab25b5b011a028de332c820', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 16, 'Niezaka tamin’ny foko manontolo aho mba hanam-pahendrena sy handinika an’izay rehetra atao etỳ ambonin’ny tany. Indraindray aza aho tsy matory andro aman’alina mihitsy.', 'niezaka tamin’ny foko manontolo aho mba hanam-pahendrena sy handinika an’izay rehetra atao etỳ ambonin’ny tany. indraindray aza aho tsy matory andro aman’alina mihitsy.'),
  ('6ab25b5b011a028de332c81f', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 15, 'Nampirisihiko hifalifaly àry ny olona, satria tsy misy tsara noho ny hoe mihinana sy misotro dia mifalifaly, etỳ ambanin’ny masoandro. Izany no tokony hataony rehefa miasa mafy, mandritra ny androm-piainana nomen’Andriamanitra azy etỳ ambanin’ny masoandro.', 'nampirisihiko hifalifaly àry ny olona, satria tsy misy tsara noho ny hoe mihinana sy misotro dia mifalifaly, etỳ ambanin’ny masoandro. izany no tokony hataony rehefa miasa mafy, mandritra ny androm-piainana nomen’andriamanitra azy etỳ ambanin’ny masoandro.'),
  ('6ab25b5b011a028de332c81a', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 10, 'Hitako ny nandevenana ny ratsy fanahy, izany hoe ny olona nivezivezy nivoaka sy niditra tao amin’ny toerana masina. Vetivety anefa izy ireny dia hadino tao amin’ilay tanàna nanaovany ny asa ratsiny. Tsisy dikany koa izany.', 'hitako ny nandevenana ny ratsy fanahy, izany hoe ny olona nivezivezy nivoaka sy niditra tao amin’ny toerana masina. vetivety anefa izy ireny dia hadino tao amin’ilay tanàna nanaovany ny asa ratsiny. tsisy dikany koa izany.'),
  ('6ab25b5b011a028de332c814', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 4, 'Ny mpanjaka mantsy no tompon’ny teny farany. Koa iza no afaka milaza aminy hoe: ‘Inona ity ataonao?’”', 'ny mpanjaka mantsy no tompon’ny teny farany. koa iza no afaka milaza aminy hoe: ‘inona ity ataonao?’”'),
  ('6ab25b5b011a028de332c812', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 2, 'Hoy aho: “Ankatoavy ny didin’ny mpanjaka, satria nianiana tamin’Andriamanitra ianao.', 'hoy aho: “ankatoavy ny didin’ny mpanjaka, satria nianiana tamin’andriamanitra ianao.'),
  ('6ab25b5b011a028de332c819', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 9, 'Efa hitako izany rehetra izany, ary nodinihiko daholo ny zavatra atao etỳ ambanin’ny masoandro. Nandritra izany fotoana izany, dia nifampitondra ny olona samy olona ka nijaly ny vahoaka.', 'efa hitako izany rehetra izany, ary nodinihiko daholo ny zavatra atao etỳ ambanin’ny masoandro. nandritra izany fotoana izany, dia nifampitondra ny olona samy olona ka nijaly ny vahoaka.'),
  ('6ab25b5b011a028de332c818', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 8, 'Tsy misy olona manana fahefana amin’ny ainy na mahavita mitazona ny ainy. Hoatr’izany koa fa tsy misy olona afaka mifidy ny andro ahafatesany. Tsy misy afa-miala tsy handeha hiady rehefa misy ady, dia hoatr’izany koa fa tsy ho afa-maina amin’ny vokatry ny ataony izay zatra manao ratsy.', 'tsy misy olona manana fahefana amin’ny ainy na mahavita mitazona ny ainy. hoatr’izany koa fa tsy misy olona afaka mifidy ny andro ahafatesany. tsy misy afa-miala tsy handeha hiady rehefa misy ady, dia hoatr’izany koa fa tsy ho afa-maina amin’ny vokatry ny ataony izay zatra manao ratsy.'),
  ('6ab25b5b011a028de332c821', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 17, 'Dia nodinihiko ny zavatra rehetra nataon’ilay tena Andriamanitra, ka hitako fa tsy ho azon’ny olombelona izay mitranga etỳ ambanin’ny masoandro. Na miezaka mafy tahaka ny inona aza izy, dia tsy ho azony izany. Na dia miteny aza izy hoe manam-pahendrena ka mahalala an’izany, dia tsy tena azony izany.', 'dia nodinihiko ny zavatra rehetra nataon’ilay tena andriamanitra, ka hitako fa tsy ho azon’ny olombelona izay mitranga etỳ ambanin’ny masoandro. na miezaka mafy tahaka ny inona aza izy, dia tsy ho azony izany. na dia miteny aza izy hoe manam-pahendrena ka mahalala an’izany, dia tsy tena azony izany.'),
  ('6ab25b5b011a028de332c817', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 7, 'Na izay hitranga amin’ny hoavy aza tsy misy mahalala, koa mainka fa ny fomba hitrangan’izany!', 'na izay hitranga amin’ny hoavy aza tsy misy mahalala, koa mainka fa ny fomba hitrangan’izany!'),
  ('6ab25b5b011a028de332c81d', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 13, 'Ho ratsy fiafara kosa ny ratsy fanahy, ary tsy ho vitany koa ny hanalava ny androm-piainany izay toy ny aloka, satria izy tsy matahotra an’Andriamanitra.', 'ho ratsy fiafara kosa ny ratsy fanahy, ary tsy ho vitany koa ny hanalava ny androm-piainany izay toy ny aloka, satria izy tsy matahotra an’andriamanitra.'),
  ('6ab25b5b011a028de332c813', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 3, 'Aza maika hiala eo anatrehan’ny mpanjaka. Ary aza mikiry manao ratsy, fa azon’ny mpanjaka atao daholo ange izay tiany hatao e!', 'aza maika hiala eo anatrehan’ny mpanjaka. ary aza mikiry manao ratsy, fa azon’ny mpanjaka atao daholo ange izay tiany hatao e!'),
  ('6ab25b5b011a028de332c81c', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 12, 'Na dia manao ratsy injato aza ny mpanota, ary mbola ela velona ihany, dia fantatro fa ho tsara fiafara izay matahotra an’ilay tena Andriamanitra, satria matahotra Azy.', 'na dia manao ratsy injato aza ny mpanota, ary mbola ela velona ihany, dia fantatro fa ho tsara fiafara izay matahotra an’ilay tena andriamanitra, satria matahotra azy.'),
  ('6ab25b5b011a028de332c81b', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 11, 'Rehefa tsy tonga dia sazina amin’ny ratsy nataony ny olona, dia vao mainka mikiry manao ratsy ny fony.', 'rehefa tsy tonga dia sazina amin’ny ratsy nataony ny olona, dia vao mainka mikiry manao ratsy ny fony.'),
  ('6ab25b5b011a028de332c81e', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 14, 'Izao koa ny zavatra tsisy dikany mitranga eto ambonin’ny tany: Misy olo-marina atao hoatran’ny hoe nanao ratsy, dia misy indray ratsy fanahy atao hoatran’ny hoe nanao ny tsara. Dia hoy aho: “Tsisy dikany koa izany.”', 'izao koa ny zavatra tsisy dikany mitranga eto ambonin’ny tany: misy olo-marina atao hoatran’ny hoe nanao ratsy, dia misy indray ratsy fanahy atao hoatran’ny hoe nanao ny tsara. dia hoy aho: “tsisy dikany koa izany.”'),
  ('6ab25b5b011a028de332c815', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 5, 'Tsy mba hisy zava-dratsy hanjo an’izay mankatò ny didy. Ary ho fantatry ny olona manana fo hendry ny fotoana mety sy izay tokony hatao.', 'tsy mba hisy zava-dratsy hanjo an’izay mankatò ny didy. ary ho fantatry ny olona manana fo hendry ny fotoana mety sy izay tokony hatao.'),
  ('6ab25b5b011a028de332c811', '2026-09-22T10:41:31.555Z', '2026-09-22T10:41:31.555Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 8, 1, 'Iza no mitovy amin’ny olon-kendry? Iza no mahay mamaha olana? Hita eny amin’ny tarehin’ny olona hoe manam-pahendrena izy, ary lasa miramirana ilay endriny masiaka.', 'iza no mitovy amin’ny olon-kendry? iza no mahay mamaha olana? hita eny amin’ny tarehin’ny olona hoe manam-pahendrena izy, ary lasa miramirana ilay endriny masiaka.'),
  ('6ab25b5cd59c6efe55c76fc5', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 17, 'Aleo manaraka ny teny malefaka lazain’ny hendry, toy izay manaraka ny antsoantson’ny olona manjaka eo amin’ny adala.', 'aleo manaraka ny teny malefaka lazain’ny hendry, toy izay manaraka ny antsoantson’ny olona manjaka eo amin’ny adala.'),
  ('6ab25b5cd59c6efe55c76fba', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 6, 'Efa foana koa ny fitiavany sy ny fankahalany ary ny fialonany. Tsy mandray anjara amin’izay atao etỳ ambanin’ny masoandro intsony izy.', 'efa foana koa ny fitiavany sy ny fankahalany ary ny fialonany. tsy mandray anjara amin’izay atao etỳ ambanin’ny masoandro intsony izy.'),
  ('6ab25b5cd59c6efe55c76fbd', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 9, 'Ankafizo ny fiainanao miaraka amin’ny vady malalanao, mandritra ny fiainana poakaty nomen’Andriamanitra anao etỳ ambanin’ny masoandro, mandritra ny androm-piainanao, izay tsisy dikany. Izany mantsy no valisoanao eo amin’ny fiainana, sy valisoanao noho ny asa mafy isasaranao etỳ ambanin’ny masoandro.', 'ankafizo ny fiainanao miaraka amin’ny vady malalanao, mandritra ny fiainana poakaty nomen’andriamanitra anao etỳ ambanin’ny masoandro, mandritra ny androm-piainanao, izay tsisy dikany. izany mantsy no valisoanao eo amin’ny fiainana, sy valisoanao noho ny asa mafy isasaranao etỳ ambanin’ny masoandro.'),
  ('6ab25b5cd59c6efe55c76fc4', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 16, 'Dia hoy aho anakampo: ‘Aleo fahendrena toy izay tanjaka. Atao tsinontsinona anefa ny fahendren’ny mahantra, ary tsy mba raharahiana ny teniny.’', 'dia hoy aho anakampo: ‘aleo fahendrena toy izay tanjaka. atao tsinontsinona anefa ny fahendren’ny mahantra, ary tsy mba raharahiana ny teniny.’'),
  ('6ab25b5cd59c6efe55c76fc0', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 12, 'Fa tsy fantatry ny olombelona ny fotoana hahafatesany. Toy ny trondro azon’ny harato sy vorona azon’ny fandrika ny zanak’olombelona, satria voafandrika izy amin’ny fotoana itrangan’ny loza, rehefa tratran’ny loza tampoka.', 'fa tsy fantatry ny olombelona ny fotoana hahafatesany. toy ny trondro azon’ny harato sy vorona azon’ny fandrika ny zanak’olombelona, satria voafandrika izy amin’ny fotoana itrangan’ny loza, rehefa tratran’ny loza tampoka.'),
  ('6ab25b5cd59c6efe55c76fbb', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 7, 'Mandehana, hano amim-pifaliana ny sakafonao, ary sotroy amin’ny fo falifaly ny divainao, satria mahafinaritra an’ilay tena Andriamanitra ny zavatra ataonao.', 'mandehana, hano amim-pifaliana ny sakafonao, ary sotroy amin’ny fo falifaly ny divainao, satria mahafinaritra an’ilay tena andriamanitra ny zavatra ataonao.'),
  ('6ab25b5cd59c6efe55c76fb9', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 5, 'Fa fantatry ny velona hoe ho faty izy, fa ny maty kosa tsy mahalala na inona na inona, sady tsy mahazo valisoa intsony, satria hadino daholo izay nahatsiarovana azy.', 'fa fantatry ny velona hoe ho faty izy, fa ny maty kosa tsy mahalala na inona na inona, sady tsy mahazo valisoa intsony, satria hadino daholo izay nahatsiarovana azy.'),
  ('6ab25b5cd59c6efe55c76fb8', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 4, 'Raha mbola anisan’ny velona ny olona iray dia mbola misy fanantenana, satria aleo alika velona toy izay liona maty.', 'raha mbola anisan’ny velona ny olona iray dia mbola misy fanantenana, satria aleo alika velona toy izay liona maty.'),
  ('6ab25b5cd59c6efe55c76fb7', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 3, 'Izao no zavatra mahakivy etỳ ambanin’ny masoandro: Koa satria mitovy ihany ny hiafaran’ny olona rehetra, dia ny hanao ratsy foana no mibahana ao am-pony. Misy hadalana ao am-pony mandritra ny androm-piainany, dia avy eo izy maty!', 'izao no zavatra mahakivy etỳ ambanin’ny masoandro: koa satria mitovy ihany ny hiafaran’ny olona rehetra, dia ny hanao ratsy foana no mibahana ao am-pony. misy hadalana ao am-pony mandritra ny androm-piainany, dia avy eo izy maty!'),
  ('6ab25b5cd59c6efe55c76fc1', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 13, 'Izao koa no tena nampiaiky ahy etỳ ambanin’ny masoandro, momba ny fahendrena:', 'izao koa no tena nampiaiky ahy etỳ ambanin’ny masoandro, momba ny fahendrena:'),
  ('6ab25b5cd59c6efe55c76fbe', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 10, 'Izay rehetra azonao atao, dia ataovy amin’ny herinao manontolo. Fa tsy misy afaka miasa, na mikasa hanao zavatra, na mahazo fahalalana, na maneho fahendrena, any amin’ny Fasana halehanao.', 'izay rehetra azonao atao, dia ataovy amin’ny herinao manontolo. fa tsy misy afaka miasa, na mikasa hanao zavatra, na mahazo fahalalana, na maneho fahendrena, any amin’ny fasana halehanao.'),
  ('6ab25b5cd59c6efe55c76fbf', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 11, 'Izao koa no hitako etỳ ambanin’ny masoandro: Tsy hoe maharesy foana izay mahavita mihazakazaka be, na mandresy foana izay matanjaka, na manana sakafo foana izay hendry, na manan-karena foana izay marani-tsaina, na tafita foana izay manam-pahalalana. Mety ho tratran’ny sampona mantsy izy rehetra amin’ny fotoana tsy ampoizina.', 'izao koa no hitako etỳ ambanin’ny masoandro: tsy hoe maharesy foana izay mahavita mihazakazaka be, na mandresy foana izay matanjaka, na manana sakafo foana izay hendry, na manan-karena foana izay marani-tsaina, na tafita foana izay manam-pahalalana. mety ho tratran’ny sampona mantsy izy rehetra amin’ny fotoana tsy ampoizina.'),
  ('6ab25b5cd59c6efe55c76fc6', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 18, 'Aleo fahendrena toy izay fitaovam-piadiana. Mpanota iray fotsiny anefa dia mahavita manimba zavatra tsara be dia be.', 'aleo fahendrena toy izay fitaovam-piadiana. mpanota iray fotsiny anefa dia mahavita manimba zavatra tsara be dia be.'),
  ('6ab25b5cd59c6efe55c76fc2', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 14, 'Nisy tanàna kely iray nisy lehilahy vitsivitsy. Dia nisy mpanjaka mahery tonga nanafika an’ilay tanàna, ka nanodidina azy ary nanorina manda hanaovana fahirano azy.', 'nisy tanàna kely iray nisy lehilahy vitsivitsy. dia nisy mpanjaka mahery tonga nanafika an’ilay tanàna, ka nanodidina azy ary nanorina manda hanaovana fahirano azy.'),
  ('6ab25b5cd59c6efe55c76fbc', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 8, 'Ataovy fotsy foana ny akanjonao, ary asio menaka foana ny lohanao.', 'ataovy fotsy foana ny akanjonao, ary asio menaka foana ny lohanao.'),
  ('6ab25b5cd59c6efe55c76fb5', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 1, 'Izao àry no hitako, ka nataoko tao am-poko: Samy eo am-pelatanan’ilay tena Andriamanitra ny olo-marina sy ny hendry ary ny asan’izy ireo. Samy tsy fantatry ny olombelona na ny fitiavana na ny fankahalana nisy tany aloha tany.', 'izao àry no hitako, ka nataoko tao am-poko: samy eo am-pelatanan’ilay tena andriamanitra ny olo-marina sy ny hendry ary ny asan’izy ireo. samy tsy fantatry ny olombelona na ny fitiavana na ny fankahalana nisy tany aloha tany.'),
  ('6ab25b5cd59c6efe55c76fc3', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 15, 'Nisy lehilahy mahantra nefa hendry koa tao, ary ny fahendreny no nahavoavonjy an’ilay tanàna. Tsy mba nisy nahatsiaro an’ilay lehilahy mahantra anefa.', 'nisy lehilahy mahantra nefa hendry koa tao, ary ny fahendreny no nahavoavonjy an’ilay tanàna. tsy mba nisy nahatsiaro an’ilay lehilahy mahantra anefa.'),
  ('6ab25b5cd59c6efe55c76fb6', '2026-09-22T10:41:32.099Z', '2026-09-22T10:41:32.099Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 9, 2, 'Mitovy daholo ny hiafaran’ny olon-drehetra, dia ny olo-marina sy ny ratsy fanahy, ny olona tsara toetra sy ny madio ary ny maloto, ary ny manao sorona sy ny tsy manao. Mitovy ihany ny tsara fanahy sy ny mpanota, ary mitovy koa ny maimay hianiana sy izay mitandrina tsara vao mianiana.', 'mitovy daholo ny hiafaran’ny olon-drehetra, dia ny olo-marina sy ny ratsy fanahy, ny olona tsara toetra sy ny madio ary ny maloto, ary ny manao sorona sy ny tsy manao. mitovy ihany ny tsara fanahy sy ny mpanota, ary mitovy koa ny maimay hianiana sy izay mitandrina tsara vao mianiana.'),
  ('6ab25b5c6402c08d2049cb96', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 5, 'Ity misy zavatra mahakivy hitako etỳ ambanin’ny masoandro, ary fahadisoana fanaon’ny manam-pahefana ilay izy:', 'ity misy zavatra mahakivy hitako etỳ ambanin’ny masoandro, ary fahadisoana fanaon’ny manam-pahefana ilay izy:'),
  ('6ab25b5c6402c08d2049cb9c', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 11, 'Raha manaikitra alohan’ny hibaikoana azy ny bibilava, dia tsy misy tombony ho an’ilay olona mahay mibaiko azy.', 'raha manaikitra alohan’ny hibaikoana azy ny bibilava, dia tsy misy tombony ho an’ilay olona mahay mibaiko azy.'),
  ('6ab25b5c6402c08d2049cba2', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 17, 'Sambatra kosa ny tany raha zanaky ny olona ambony ny mpanjakany, ary raha mihinana sy misotro amin’ny fotoana mety ny andrianany mba hahazo hery, fa tsy hoe mba ho mamo.', 'sambatra kosa ny tany raha zanaky ny olona ambony ny mpanjakany, ary raha mihinana sy misotro amin’ny fotoana mety ny andrianany mba hahazo hery, fa tsy hoe mba ho mamo.'),
  ('6ab25b5c6402c08d2049cba1', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 16, 'Hahita loza ny tany raha zaza no mpanjakany, ary raha manaram-po misakafo vao maraina ny andrianany!', 'hahita loza ny tany raha zaza no mpanjakany, ary raha manaram-po misakafo vao maraina ny andrianany!'),
  ('6ab25b5c6402c08d2049cb99', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 8, 'Izay mihady lavaka no mety ho latsaka ao, ary izay managorobaka manda vato no mety hokaikerin’ny bibilava.', 'izay mihady lavaka no mety ho latsaka ao, ary izay managorobaka manda vato no mety hokaikerin’ny bibilava.'),
  ('6ab25b5c6402c08d2049cb98', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 7, 'Ny mpanompo indray no hitako mitaingin-tsoavaly, fa ny andriana kosa mandeha an-tongotra toy ny mpanompo.', 'ny mpanompo indray no hitako mitaingin-tsoavaly, fa ny andriana kosa mandeha an-tongotra toy ny mpanompo.'),
  ('6ab25b5c6402c08d2049cb93', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 2, 'Ny fon’ny hendry mitarika azy hanao ny tsara, fa ny fon’ny adala kosa mitarika azy hanao ratsy.', 'ny fon’ny hendry mitarika azy hanao ny tsara, fa ny fon’ny adala kosa mitarika azy hanao ratsy.'),
  ('6ab25b5c6402c08d2049cba3', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 18, 'Ny hakamoana be loatra no mahatonga ny hazo manohana ny tafo hiletsy, ary ny hakamoan’ny tanana no mampitete ny tafo.', 'ny hakamoana be loatra no mahatonga ny hazo manohana ny tafo hiletsy, ary ny hakamoan’ny tanana no mampitete ny tafo.'),
  ('6ab25b5c6402c08d2049cb95', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 4, 'Raha misafoaka aminao ny mpitondra, dia aza miala eo amin’ny toeranao. Tsy dia mampisy fahotana lehibe mantsy ny fahatoniana.', 'raha misafoaka aminao ny mpitondra, dia aza miala eo amin’ny toeranao. tsy dia mampisy fahotana lehibe mantsy ny fahatoniana.'),
  ('6ab25b5c6402c08d2049cba5', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 20, 'Aza manozona ny mpanjaka na dia any an-tsainao aza, ary aza manozona ny mpanankarena na dia ao amin’ny efitra fatorianao aza. Fa na ny vorona aza mety hitatitra an’izay nolazainao, ary izay manana elatra mety hitantara an’izay noteneninao.', 'aza manozona ny mpanjaka na dia any an-tsainao aza, ary aza manozona ny mpanankarena na dia ao amin’ny efitra fatorianao aza. fa na ny vorona aza mety hitatitra an’izay nolazainao, ary izay manana elatra mety hitantara an’izay noteneninao.'),
  ('6ab25b5c6402c08d2049cba4', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 19, 'Natao hampifalifaly ny sakafo, ary mahafinaritra erỳ ny fiainana rehefa misotro divay. Ny vola kosa no ahazoana an’izay rehetra ilaina.', 'natao hampifalifaly ny sakafo, ary mahafinaritra erỳ ny fiainana rehefa misotro divay. ny vola kosa no ahazoana an’izay rehetra ilaina.'),
  ('6ab25b5c6402c08d2049cb9a', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 9, 'Izay mamaky vato no mety haratran’ny vato, ary izay mamaky vatan-kazo no mety hahita loza.', 'izay mamaky vato no mety haratran’ny vato, ary izay mamaky vatan-kazo no mety hahita loza.'),
  ('6ab25b5c6402c08d2049cb9d', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 12, 'Ahazoana fankasitrahana ny teny aloaky ny vavan’ny hendry, fa ny tenin’ny adala kosa mampidi-kizo ny tenany.', 'ahazoana fankasitrahana ny teny aloaky ny vavan’ny hendry, fa ny tenin’ny adala kosa mampidi-kizo ny tenany.'),
  ('6ab25b5c6402c08d2049cb9b', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 10, 'Raha dombo ny famaky nefa tsy rangitina, dia ho be kokoa ny hery tsy maintsy ampiasaina. Fa hahomby kosa izay manam-pahendrena.', 'raha dombo ny famaky nefa tsy rangitina, dia ho be kokoa ny hery tsy maintsy ampiasaina. fa hahomby kosa izay manam-pahendrena.'),
  ('6ab25b5c6402c08d2049cb92', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 1, 'Fatin-dalitra no mahamaimbo sy manimba ny menaky ny mpanao ranomanitra. Hadalana kely koa dia manimba ny laza tsaran’izay malaza ho hendry sy hajain’olona.', 'fatin-dalitra no mahamaimbo sy manimba ny menaky ny mpanao ranomanitra. hadalana kely koa dia manimba ny laza tsaran’izay malaza ho hendry sy hajain’olona.'),
  ('6ab25b5c6402c08d2049cb9f', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 14, 'Miteny foana anefa ny olona adala. Tsy misy olona mahalala an’izay hitranga. Koa iza no afaka milaza aminy an’izay hitranga rehefa maty izy?', 'miteny foana anefa ny olona adala. tsy misy olona mahalala an’izay hitranga. koa iza no afaka milaza aminy an’izay hitranga rehefa maty izy?'),
  ('6ab25b5c6402c08d2049cb97', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 6, 'Ny adala no omena toerana ambony, fa ny olona mahay kosa mitana toerana ambany foana.', 'ny adala no omena toerana ambony, fa ny olona mahay kosa mitana toerana ambany foana.'),
  ('6ab25b5c6402c08d2049cb94', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 3, 'Hita amin’izay rehetra ataon’ny adala fa tsy ampy saina izy, sady ataony fantatry ny olona rehetra hoe adala izy.', 'hita amin’izay rehetra ataon’ny adala fa tsy ampy saina izy, sady ataony fantatry ny olona rehetra hoe adala izy.'),
  ('6ab25b5c6402c08d2049cba0', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 15, 'Ny asa mafy ataon’ny tsisy saina no mandreraka azy, satria na ny lalana mankany an-tanàna aza tsy hitany akory.', 'ny asa mafy ataon’ny tsisy saina no mandreraka azy, satria na ny lalana mankany an-tanàna aza tsy hitany akory.'),
  ('6ab25b5c6402c08d2049cb9e', '2026-09-22T10:41:32.545Z', '2026-09-22T10:41:32.545Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 10, 13, 'Hadalana ny teny voalohany avoakan’ny vavany, ary hadalana mampidi-doza koa ny teny farany lazainy.', 'hadalana ny teny voalohany avoakan’ny vavany, ary hadalana mampidi-doza koa ny teny farany lazainy.'),
  ('6ab25b5e32d7607d5258393f', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 7, 'Mahafinaritra ny hazavana, ary tsara ho an’ny maso ny mijery tara-masoandro.', 'mahafinaritra ny hazavana, ary tsara ho an’ny maso ny mijery tara-masoandro.'),
  ('6ab25b5e32d7607d5258393e', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 6, 'Mamafaza voa amin’ny maraina, ary aza avela haka aina ny tananao mandra-paharivan’ny andro. Fa tsy fantatrao izay ho vanona, na itỳ na irỳ, na samy ho vanona izy roa.', 'mamafaza voa amin’ny maraina, ary aza avela haka aina ny tananao mandra-paharivan’ny andro. fa tsy fantatrao izay ho vanona, na itỳ na irỳ, na samy ho vanona izy roa.'),
  ('6ab25b5e32d7607d52583940', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 8, 'Raha ela velona ny olona iray, dia aleo izy hankafy an’izany taona rehetra iainany izany. Tokony hotsaroany anefa fa mety ho be dia be koa ny andro manjombona. Tsisy dikany daholo mantsy izay mbola ho avy.', 'raha ela velona ny olona iray, dia aleo izy hankafy an’izany taona rehetra iainany izany. tokony hotsaroany anefa fa mety ho be dia be koa ny andro manjombona. tsisy dikany daholo mantsy izay mbola ho avy.'),
  ('6ab25b5e32d7607d5258393c', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 4, 'Izay mandinika ny rivotra dia tsy hamafy, ary izay mijery ny rahona tsy hijinja.', 'izay mandinika ny rivotra dia tsy hamafy, ary izay mijery ny rahona tsy hijinja.'),
  ('6ab25b5e32d7607d52583939', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 1, 'Atsipazo eny ambony rano ny mofonao, fa ho hitanao indray ilay izy rehefa afaka andro maro.', 'atsipazo eny ambony rano ny mofonao, fa ho hitanao indray ilay izy rehefa afaka andro maro.'),
  ('6ab25b5e32d7607d52583941', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 9, 'Mifalia ry tanora dieny mbola tanora ianao, ary ataovy izay mampifalifaly ny fonao amin’ny andro fahatanoranao. Ataovy izay irin’ny fonao sy izay mahafinaritra ny masonao. Fantaro anefa fa hotsarain’ilay tena Andriamanitra ianao amin’izany rehetra izany.', 'mifalia ry tanora dieny mbola tanora ianao, ary ataovy izay mampifalifaly ny fonao amin’ny andro fahatanoranao. ataovy izay irin’ny fonao sy izay mahafinaritra ny masonao. fantaro anefa fa hotsarain’ilay tena andriamanitra ianao amin’izany rehetra izany.'),
  ('6ab25b5e32d7607d52583942', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 10, 'Koa esory ao am-ponao izay zavatra mampanahy, ary aza avela hikasika ny vatanao izay zavatra mampijaly. Tsisy dikany mantsy ny fahatanorana sy ny tanjaky ny tanora.', 'koa esory ao am-ponao izay zavatra mampanahy, ary aza avela hikasika ny vatanao izay zavatra mampijaly. tsisy dikany mantsy ny fahatanorana sy ny tanjaky ny tanora.'),
  ('6ab25b5e32d7607d5258393a', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 2, 'Anomezo ho an’olona fito ny fanananao, na ho an’olona valo aza, fa tsy fantatrao izay loza hitranga eto an-tany.', 'anomezo ho an’olona fito ny fanananao, na ho an’olona valo aza, fa tsy fantatrao izay loza hitranga eto an-tany.'),
  ('6ab25b5e32d7607d5258393b', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 3, 'Rehefa vonton-drano ny rahona, dia handrotsaka orana amin’ny tany. Ary raha mianjera mianatsimo na mianavaratra ny hazo, dia eo amin’izay ianjerany ihany no hisy azy.', 'rehefa vonton-drano ny rahona, dia handrotsaka orana amin’ny tany. ary raha mianjera mianatsimo na mianavaratra ny hazo, dia eo amin’izay ianjerany ihany no hisy azy.'),
  ('6ab25b5e32d7607d5258393d', '2026-09-22T10:41:34.048Z', '2026-09-22T10:41:34.048Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 11, 5, 'Tsy fantatrao ny fiasan’ny hery mamelona ao amin’ny taolan’ny zaza ao an-kibon’ny vehivavy bevohoka. Hoatr’izany koa fa tsy fantatrao ny asan’ilay tena Andriamanitra izay manao ny zava-drehetra.', 'tsy fantatrao ny fiasan’ny hery mamelona ao amin’ny taolan’ny zaza ao an-kibon’ny vehivavy bevohoka. hoatr’izany koa fa tsy fantatrao ny asan’ilay tena andriamanitra izay manao ny zava-drehetra.'),
  ('6ab25b5eefc9f34102861ff6', '2026-09-22T10:41:34.482Z', '2026-09-22T10:41:34.482Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 2, 'dieny mbola tsy maizina ny hazavan’ny masoandro sy ny volana ary ny kintana, ary dieny mbola tsy mandrahona indray ny andro aorian’ny oram-be mivatravatra.', 'dieny mbola tsy maizina ny hazavan’ny masoandro sy ny volana ary ny kintana, ary dieny mbola tsy mandrahona indray ny andro aorian’ny oram-be mivatravatra.'),
  ('6ab25b5eefc9f34102861ff8', '2026-09-22T10:41:34.482Z', '2026-09-22T10:41:34.482Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 4, 'mikatona ny varavarana mankeny an-dalana, tsy heno tsara intsony ny feon’ny vato fikosoham-bary, manaitra amin’ny torimaso na dia ny feom-boronkely fotsiny aza, ary lasa iva kely ny feon’ny vehivavy mpihira rehetra.', 'mikatona ny varavarana mankeny an-dalana, tsy heno tsara intsony ny feon’ny vato fikosoham-bary, manaitra amin’ny torimaso na dia ny feom-boronkely fotsiny aza, ary lasa iva kely ny feon’ny vehivavy mpihira rehetra.'),
  ('6ab25b5eefc9f34102861ff9', '2026-09-22T10:41:34.482Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 5, 'Mampahatahotra koa ny toerana avo, ary misy zavatra mampitebiteby eny an-dalana. Mamony koa ny hazo amandie, miresaresa ny valala rehefa mandeha, ary mamelana ny kapra, satria mandeha ho any amin’ny trano hipetrahany maharitra ny olona, ary mandehandeha eny an-dalana ny olona misaona.', 'mampahatahotra koa ny toerana avo, ary misy zavatra mampitebiteby eny an-dalana. mamony koa ny hazo amandie, miresaresa ny valala rehefa mandeha, ary mamelana ny kapra, satria mandeha ho any amin’ny trano hipetrahany maharitra ny olona, ary mandehandeha eny an-dalana ny olona misaona.'),
  ('6ab25b5eefc9f34102861ff5', '2026-09-22T10:41:34.482Z', '2026-09-22T10:41:34.482Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 1, 'Tsarovy àry ilay Mpamorona Be Voninahitra nanao anao. Tsarovy izy amin’ny andro fahatanoranao, dieny mbola tsy tonga ny andro mampahory sy ireo taona izay hitenenanao hoe: “Tsy tiako mihitsy izao fiainako izao!”,', 'tsarovy àry ilay mpamorona be voninahitra nanao anao. tsarovy izy amin’ny andro fahatanoranao, dieny mbola tsy tonga ny andro mampahory sy ireo taona izay hitenenanao hoe: “tsy tiako mihitsy izao fiainako izao!”,'),
  ('6ab25b5eefc9f34102861ff7', '2026-09-22T10:41:34.482Z', '2026-09-22T10:41:34.482Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 3, 'Amin’izay fotoana izay dia lasa mangozohozo ireo mpiambina trano, manjoko ireo lehilahy matanjaka, tsy afaka mitoto intsony ny vehivavy satria efa lasa vitsy, ary maizina izay jeren’ny vehivavy mitazana eo am-baravarankely,', 'amin’izay fotoana izay dia lasa mangozohozo ireo mpiambina trano, manjoko ireo lehilahy matanjaka, tsy afaka mitoto intsony ny vehivavy satria efa lasa vitsy, ary maizina izay jeren’ny vehivavy mitazana eo am-baravarankely,'),
  ('6ab25b5eefc9f34102861ffb', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 7, 'Dia hiverina amin’ny tany toy ny teo aloha ny vovoka, fa ny hery mamelona kosa hiverina amin’ilay tena Andriamanitra izay nanome azy.', 'dia hiverina amin’ny tany toy ny teo aloha ny vovoka, fa ny hery mamelona kosa hiverina amin’ilay tena andriamanitra izay nanome azy.'),
  ('6ab25b5eefc9f34102861fff', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 11, 'Hoatran’ny hazo fanindronana omby ny tenin’ny hendry, ary toy ny fantsika milentika mafy tsara ny teny voafantina lazainy. Avy tamin’ny mpiandry iray ihany izy ireny.', 'hoatran’ny hazo fanindronana omby ny tenin’ny hendry, ary toy ny fantsika milentika mafy tsara ny teny voafantina lazainy. avy tamin’ny mpiandry iray ihany izy ireny.'),
  ('6ab25b5eefc9f34102862002', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 14, 'Fa ilay tena Andriamanitra no hitsara hoe tsara sa ratsy ny zavatra atao rehetra, anisan’izany ny zava-miafina rehetra.', 'fa ilay tena andriamanitra no hitsara hoe tsara sa ratsy ny zavatra atao rehetra, anisan’izany ny zava-miafina rehetra.'),
  ('6ab25b5eefc9f34102861ffd', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 9, 'Lasa hendry ilay mpamory vahoaka, sady mbola nampianariny an’izay fantany foana ny olona. Nisaintsaina sy nanao fikarohana lalina koa izy, mba hahafahany handahatra ohabolana be dia be.', 'lasa hendry ilay mpamory vahoaka, sady mbola nampianariny an’izay fantany foana ny olona. nisaintsaina sy nanao fikarohana lalina koa izy, mba hahafahany handahatra ohabolana be dia be.'),
  ('6ab25b5eefc9f34102862000', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 12, 'Ankoatra izany, anaka, dia izao no ampitandremako anao: Tsy ho tapitra ny boky mivoaka, ka mandreraka ny vatana ny mifantoka be amin’ireny.', 'ankoatra izany, anaka, dia izao no ampitandremako anao: tsy ho tapitra ny boky mivoaka, ka mandreraka ny vatana ny mifantoka be amin’ireny.'),
  ('6ab25b5eefc9f34102861ffe', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 10, 'Niezaka nitady teny mahafinaritra ilay mpamory vahoaka, sady niezaka nanoratra teny marina tsara tsy misy diso.', 'niezaka nitady teny mahafinaritra ilay mpamory vahoaka, sady niezaka nanoratra teny marina tsara tsy misy diso.'),
  ('6ab25b5eefc9f34102861ffa', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 6, 'Koa tsarovy ny Mpamorona anao, dieny mbola tsy tapaka ny tady volafotsy, mbola tsy potika ny vilia baolina volamena, mbola tsy vaky ny siny eny amin’ny loharano, ary mbola tsy potika ny fitaovana fihodinan’ny tady eo amin’ny lavadrano.', 'koa tsarovy ny mpamorona anao, dieny mbola tsy tapaka ny tady volafotsy, mbola tsy potika ny vilia baolina volamena, mbola tsy vaky ny siny eny amin’ny loharano, ary mbola tsy potika ny fitaovana fihodinan’ny tady eo amin’ny lavadrano.'),
  ('6ab25b5eefc9f34102862001', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 13, 'Izao no famaranan-teny rehefa heno izany rehetra izany: Matahora an’ilay tena Andriamanitra ka ankatoavy ny didiny. Izany mantsy no adidy lehibe indrindra tokony hataon’ny olombelona.', 'izao no famaranan-teny rehefa heno izany rehetra izany: matahora an’ilay tena andriamanitra ka ankatoavy ny didiny. izany mantsy no adidy lehibe indrindra tokony hataon’ny olombelona.'),
  ('6ab25b5eefc9f34102861ffc', '2026-09-22T10:41:34.483Z', '2026-09-22T10:41:34.483Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Mpitoriteny', 21, 12, 8, '“Tena tsisy dikany”, hoy ilay mpamory vahoaka, “tsisy dikany ny zava-drehetra!”', '“tena tsisy dikany”, hoy ilay mpamory vahoaka, “tsisy dikany ny zava-drehetra!”'),
  ('6ab25b5f0e57745a1c6bf85c', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 1, 'Ny tononkira tsara indrindra nataon’i Solomona:', 'ny tononkira tsara indrindra nataon’i solomona:'),
  ('6ab25b5f0e57745a1c6bf864', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 9, '“Mitovy amin’ny soavalivavy mitarika ny kalesin’i Farao ianao, ry malalako.', '“mitovy amin’ny soavalivavy mitarika ny kalesin’i farao ianao, ry malalako.'),
  ('6ab25b5f0e57745a1c6bf85e', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 3, 'Manitra erỳ ny menakao! Sahala amin’ny menaka manitra araraka ny anaranao, Dia izany no itiavan’ny ankizivavy anao.', 'manitra erỳ ny menakao! sahala amin’ny menaka manitra araraka ny anaranao, dia izany no itiavan’ny ankizivavy anao.'),
  ('6ab25b5f0e57745a1c6bf860', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 5, 'Mainty aho nefa mahafatifaty, ry zanakavavin’i Jerosalema ô, Hoatran’ny tranolain’i Kedara, hoatran’ny lamba nanaovana ny tranolain’i Solomona.', 'mainty aho nefa mahafatifaty, ry zanakavavin’i jerosalema ô, hoatran’ny tranolain’i kedara, hoatran’ny lamba nanaovana ny tranolain’i solomona.'),
  ('6ab25b5f0e57745a1c6bf865', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 10, 'Mahafatifaty erỳ ny takolakao misy firavaka, Ary tsara tarehy erỳ izato vozonao misy vakana!', 'mahafatifaty erỳ ny takolakao misy firavaka, ary tsara tarehy erỳ izato vozonao misy vakana!'),
  ('6ab25b5f0e57745a1c6bf863', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 8, '“Raha tsy fantatrao, ry ilay tsara tarehy indrindra amin’ny vehivavy ô, Dia mandehana manaraka ny dian’ondry, Ka andraso eo akaikin’ny tranolain’ny mpiandry ondry ny zanak’osinao.”', '“raha tsy fantatrao, ry ilay tsara tarehy indrindra amin’ny vehivavy ô, dia mandehana manaraka ny dian’ondry, ka andraso eo akaikin’ny tranolain’ny mpiandry ondry ny zanak’osinao.”'),
  ('6ab25b5f0e57745a1c6bf85f', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 4, 'Ento manaraka anao aho, dia andao isika hitsoaka, Fa nentin’ny mpanjaka tao amin’ny efitranony anatiny aho! Andao isika hiaraka hifalifaly sy hiravoravo. Andao horesahintsika ny fomba anehoanao fitiavana, fa tsara noho ny divay ireny. Tsy mahagaga raha tian’ny ankizivavy ianao.', 'ento manaraka anao aho, dia andao isika hitsoaka, fa nentin’ny mpanjaka tao amin’ny efitranony anatiny aho! andao isika hiaraka hifalifaly sy hiravoravo. andao horesahintsika ny fomba anehoanao fitiavana, fa tsara noho ny divay ireny. tsy mahagaga raha tian’ny ankizivavy ianao.'),
  ('6ab25b5f0e57745a1c6bf86c', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 17, 'Hazo sedera no nanaovana ny tranontsika, Ary hazo zenevrie no nanaovana ny tafontranontsika.', 'hazo sedera no nanaovana ny tranontsika, ary hazo zenevrie no nanaovana ny tafontranontsika.'),
  ('6ab25b5f0e57745a1c6bf869', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 14, 'Amiko ilay mamin’ny foko dia sahala amin’ny vonin’ny moina Eo amin’ny tanimboalobok’i En-jedy.”', 'amiko ilay mamin’ny foko dia sahala amin’ny vonin’ny moina eo amin’ny tanimboalobok’i en-jedy.”'),
  ('6ab25b5f0e57745a1c6bf866', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 11, 'Hanamboaranay firavaka volamena ianao, Firavaka nasiana haingony volafotsy.”', 'hanamboaranay firavaka volamena ianao, firavaka nasiana haingony volafotsy.”'),
  ('6ab25b5f0e57745a1c6bf862', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 7, 'Mba lazao ahy, ry ilay tena tiako, Hoe aiza ny toerana iandrasanao ondry, Sy ny toerana ampatorinao ny andian’ondry, amin’ny mitataovovonana. Fa maninona aho no handehandeha eny amin’ny andian’ondrin’ny namanao eny, Hoatran’ny vehivavy manarona ny tarehiny amin’ny voaly?”', 'mba lazao ahy, ry ilay tena tiako, hoe aiza ny toerana iandrasanao ondry, sy ny toerana ampatorinao ny andian’ondry, amin’ny mitataovovonana. fa maninona aho no handehandeha eny amin’ny andian’ondrin’ny namanao eny, hoatran’ny vehivavy manarona ny tarehiny amin’ny voaly?”'),
  ('6ab25b5f0e57745a1c6bf867', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 12, '“Raha iny mbola mipetraka eo amin’ny latabany boribory iny ny mpanjaka, Dia mamerovero erỳ ny ranomanitro!', '“raha iny mbola mipetraka eo amin’ny latabany boribory iny ny mpanjaka, dia mamerovero erỳ ny ranomanitro!'),
  ('6ab25b5f0e57745a1c6bf85d', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 2, '“Enga anie izy hanoroka ahy amin’ny molony, Fa tsara noho ny divay ny fomba anehoanao fitiavana!', '“enga anie izy hanoroka ahy amin’ny molony, fa tsara noho ny divay ny fomba anehoanao fitiavana!'),
  ('6ab25b5f0e57745a1c6bf86a', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 15, '“Tena tsara tarehy ianao, ry malalako. Tena tsara tarehy ianao. Toy ny masom-boromailala ny masonao.”', '“tena tsara tarehy ianao, ry malalako. tena tsara tarehy ianao. toy ny masom-boromailala ny masonao.”'),
  ('6ab25b5f0e57745a1c6bf86b', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 16, '“Tena tsara tarehy ianao, ry ilay mamin’ny foko, sady mahafinaritra. Ravinkazo no fandrianantsika.', '“tena tsara tarehy ianao, ry ilay mamin’ny foko, sady mahafinaritra. ravinkazo no fandrianantsika.'),
  ('6ab25b5f0e57745a1c6bf861', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 6, 'Aza jerijerena aho satria hoe mivalomainty, Fa main’ny masoandro aho. Tezitra tamiko ny zanakalahin’i Neny, Ka nasainy niambina tanimboaloboka aho, Nefa ny tanimboaloboko aza tsy mba nambenako.', 'aza jerijerena aho satria hoe mivalomainty, fa main’ny masoandro aho. tezitra tamiko ny zanakalahin’i neny, ka nasainy niambina tanimboaloboka aho, nefa ny tanimboaloboko aza tsy mba nambenako.'),
  ('6ab25b5f0e57745a1c6bf868', '2026-09-22T10:41:35.010Z', '2026-09-22T10:41:35.010Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 1, 13, 'Amiko ilay mamin’ny foko dia toy ny miora manitra eran’ny kitapo kely Eo anelanelan’ny nonoko mandritra ny alina.', 'amiko ilay mamin’ny foko dia toy ny miora manitra eran’ny kitapo kely eo anelanelan’ny nonoko mandritra ny alina.'),
  ('6ab25b5f4d0ce7aa7308dab0', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 10, 'Dia hoy ilay mamin’ny foko: ‘Mitsangàna, ry malalako, Andao hiaraka amiko, ry ilay tsara tarehiko.', 'dia hoy ilay mamin’ny foko: ‘mitsangàna, ry malalako, andao hiaraka amiko, ry ilay tsara tarehiko.'),
  ('6ab25b5f4d0ce7aa7308dab5', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 15, '“Sambory ny amboadia, Dia ireo amboadia kely mpanimba tanimboaloboka, Fa efa mamony ny voalobokay.”', '“sambory ny amboadia, dia ireo amboadia kely mpanimba tanimboaloboka, fa efa mamony ny voalobokay.”'),
  ('6ab25b5f4d0ce7aa7308dab7', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 17, 'Dieny mbola tsy mandrivodrivotra ny andro, ary mbola tsy lasa ny aloka, Dia miverena haingana, ry ilay mamin’ny foko, Hoatran’ny gazela na ny zanaka serfa eny amin’ny tendrombohitry ny fisarahana.', 'dieny mbola tsy mandrivodrivotra ny andro, ary mbola tsy lasa ny aloka, dia miverena haingana, ry ilay mamin’ny foko, hoatran’ny gazela na ny zanaka serfa eny amin’ny tendrombohitry ny fisarahana.'),
  ('6ab25b5f4d0ce7aa7308daa9', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 3, '“Hoatran’ny paoma maniry any anaty ala ny malalako. Hafa raha samy ankizilahy izy. Mba tiako erỳ ny hipetraka hialokaloka eo ambaniny, Ary mamy ao am-bavako ny voany!', '“hoatran’ny paoma maniry any anaty ala ny malalako. hafa raha samy ankizilahy izy. mba tiako erỳ ny hipetraka hialokaloka eo ambaniny, ary mamy ao am-bavako ny voany!'),
  ('6ab25b5f4d0ce7aa7308daa8', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 2, '“Toy ny lisy eny amin’ny tsilo ny malalako. Hafa raha samy ankizivavy izy.”', '“toy ny lisy eny amin’ny tsilo ny malalako. hafa raha samy ankizivavy izy.”'),
  ('6ab25b5f4d0ce7aa7308daaa', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 4, 'Nentiny tao amin’ny trano misy fanasambe aho, Ary toy ny saina kely mikopakopaka eo amboniko ny fitiavany.', 'nentiny tao amin’ny trano misy fanasambe aho, ary toy ny saina kely mikopakopaka eo amboniko ny fitiavany.'),
  ('6ab25b5f4d0ce7aa7308dab1', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 11, 'Jereo fa efa lasa ny ririnina, Ary efa nijanona sady efa lasa ny orana.', 'jereo fa efa lasa ny ririnina, ary efa nijanona sady efa lasa ny orana.'),
  ('6ab25b5f4d0ce7aa7308daad', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 7, 'Ry zanakavavin’i Jerosalema ô! Asaiko mianiana amin’ny gazela sy amin’ny serfavavy any an-tsaha ianareo Mba tsy hitady hanaitra na hampitsiry fitiavana ato amiko, fa avelao ilay izy hitsiry ho azy.', 'ry zanakavavin’i jerosalema ô! asaiko mianiana amin’ny gazela sy amin’ny serfavavy any an-tsaha ianareo mba tsy hitady hanaitra na hampitsiry fitiavana ato amiko, fa avelao ilay izy hitsiry ho azy.'),
  ('6ab25b5f4d0ce7aa7308daae', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 8, 'Izany ny feon’ny malalako! Iny tamy iny izy, Mianika tendrombohitra sady mitsambikimbikina eny an-kavoana.', 'izany ny feon’ny malalako! iny tamy iny izy, mianika tendrombohitra sady mitsambikimbikina eny an-kavoana.'),
  ('6ab25b5f4d0ce7aa7308daa7', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 1, '“Voninkazodia eny amin’ny lemaka amoron-tsiraka ihany aho, Ary lisy eny an-dohasaha.”', '“voninkazodia eny amin’ny lemaka amoron-tsiraka ihany aho, ary lisy eny an-dohasaha.”'),
  ('6ab25b5f4d0ce7aa7308daaf', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 9, 'Hoatran’ny gazela ny malalako, hoatran’ny zanaka serfa. Io mijoro ao ambadiky ny rindrinay io izy! Mijery eo am-baravarankely izy, Sady mitsirika eo amin’ny makarakara.', 'hoatran’ny gazela ny malalako, hoatran’ny zanaka serfa. io mijoro ao ambadiky ny rindrinay io izy! mijery eo am-baravarankely izy, sady mitsirika eo amin’ny makarakara.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25b5f4d0ce7aa7308daab', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 5, 'Omeo mofo vita amin’ny voaloboka maina aho mba ho velombelona, Ary omeo paoma mba hatanjaka, Fa azon’ny tazom-pitia aho.', 'omeo mofo vita amin’ny voaloboka maina aho mba ho velombelona, ary omeo paoma mba hatanjaka, fa azon’ny tazom-pitia aho.'),
  ('6ab25b5f4d0ce7aa7308dab4', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 14, 'Ry voromailalako miafina eny an-tsefatsefaky ny harambato, Eny anelanelan’ny vatolampy amoron-tevana, Avelao aho mba hijery anao dia haheno ny feonao, Fa mahafinaritra erỳ ny feonao ary mahafatifaty ny bikanao!’”', 'ry voromailalako miafina eny an-tsefatsefaky ny harambato, eny anelanelan’ny vatolampy amoron-tevana, avelao aho mba hijery anao dia haheno ny feonao, fa mahafinaritra erỳ ny feonao ary mahafatifaty ny bikanao!’”'),
  ('6ab25b5f4d0ce7aa7308dab3', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 13, 'Masaka koa ny aviavy vokatra voalohany. Mamelana ny voaloboka, sady manitra mamerovero. Mitsangàna, ry malalako, dia avia! Andao hiaraka amiko, ry ilay tsara tarehiko.', 'masaka koa ny aviavy vokatra voalohany. mamelana ny voaloboka, sady manitra mamerovero. mitsangàna, ry malalako, dia avia! andao hiaraka amiko, ry ilay tsara tarehiko.'),
  ('6ab25b5f4d0ce7aa7308dab2', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 12, 'Efa mamelana ny voninkazo eto amin’ny tanintsika, Efa tonga ny fotoana fandrantsanana voaloboka, Ary heno eto amin’ny tanintsika ny hiran’ny domohina.', 'efa mamelana ny voninkazo eto amin’ny tanintsika, efa tonga ny fotoana fandrantsanana voaloboka, ary heno eto amin’ny tanintsika ny hiran’ny domohina.'),
  ('6ab25b5f4d0ce7aa7308daac', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 6, 'Iondanako ny tanany ankavia, Ary mamihina ahy ny tanany ankavanana.', 'iondanako ny tanany ankavia, ary mamihina ahy ny tanany ankavanana.'),
  ('6ab25b5f4d0ce7aa7308dab6', '2026-09-22T10:41:35.505Z', '2026-09-22T10:41:35.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 2, 16, '“Ahy ny malalako, ary azy aho. Miandry ondry eny amin’ny toerana feno lisy izy.', '“ahy ny malalako, ary azy aho. miandry ondry eny amin’ny toerana feno lisy izy.'),
  ('6ab25b60d3dac2ab966471d0', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 8, 'Manana sabatra izy rehetra, Sady efa voaofana hiady. Samy mitondra ny sabany eo amin’ny andilany izy ireo, Satria misy zavatra mampahatahotra amin’ny alina.”', 'manana sabatra izy rehetra, sady efa voaofana hiady. samy mitondra ny sabany eo amin’ny andilany izy ireo, satria misy zavatra mampahatahotra amin’ny alina.”'),
  ('6ab25b60d3dac2ab966471cf', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 7, '“Iny ny filanjana an’i Solomona, Voahodidina lehilahy matanjaka 60 Avy amin’ny lehilahy israelita matanjaka.', '“iny ny filanjana an’i solomona, voahodidina lehilahy matanjaka 60 avy amin’ny lehilahy israelita matanjaka.'),
  ('6ab25b60d3dac2ab966471c9', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 1, '“Nitady an’ilay olon-tiako aho isak’alina, Tamin’izaho tao am-pandriana. Nitady azy aho fa tsy nahita.', '“nitady an’ilay olon-tiako aho isak’alina, tamin’izaho tao am-pandriana. nitady azy aho fa tsy nahita.'),
  ('6ab25b60d3dac2ab966471d2', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 10, 'Nataony volafotsy ny andrin’ilay izy, Ary volamena ny fiankinana. Natao tamin’ny volonondry volomparasy ny fipetrahana, Ary ny ao anatiny kosa Nasian’ny zanakavavin’i Jerosalema haingonkaingony tamim-pitiavana.”', 'nataony volafotsy ny andrin’ilay izy, ary volamena ny fiankinana. natao tamin’ny volonondry volomparasy ny fipetrahana, ary ny ao anatiny kosa nasian’ny zanakavavin’i jerosalema haingonkaingony tamim-pitiavana.”'),
  ('6ab25b60d3dac2ab966471cd', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 5, 'Ry zanakavavin’i Jerosalema ô! Asaiko mianiana amin’ny gazela sy amin’ny serfavavy any an-tsaha ianareo Mba tsy hitady hanaitra na hampitsiry fitiavana ato amiko, fa avelao ilay izy hitsiry ho azy.”', 'ry zanakavavin’i jerosalema ô! asaiko mianiana amin’ny gazela sy amin’ny serfavavy any an-tsaha ianareo mba tsy hitady hanaitra na hampitsiry fitiavana ato amiko, fa avelao ilay izy hitsiry ho azy.”'),
  ('6ab25b60d3dac2ab966471cb', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 3, 'Hitan’ny mpiambina aho, tamin’izy ireo nandehandeha nanao fisafoana tao an-tanàna. Dia hoy aho tamin’izy ireo: ‘Sao dia mba hitanareo ilay olon-tiako?’', 'hitan’ny mpiambina aho, tamin’izy ireo nandehandeha nanao fisafoana tao an-tanàna. dia hoy aho tamin’izy ireo: ‘sao dia mba hitanareo ilay olon-tiako?’'),
  ('6ab25b60d3dac2ab966471ce', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 6, '“Inona iny hoatran’ny setroka be miakatra avy any an-tany efitra iny? Manitra be ilay izy, manitra miora sy ditin-kazo manitra Ary vovoka zava-manitra isan-karazany amidin’ny mpivarotra.”', '“inona iny hoatran’ny setroka be miakatra avy any an-tany efitra iny? manitra be ilay izy, manitra miora sy ditin-kazo manitra ary vovoka zava-manitra isan-karazany amidin’ny mpivarotra.”'),
  ('6ab25b60d3dac2ab966471d1', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 9, '“Iny ilay filanjana an’i Solomona Mpanjaka! Hazon’i Libàna no nanaovany azy.', '“iny ilay filanjana an’i solomona mpanjaka! hazon’i libàna no nanaovany azy.'),
  ('6ab25b60d3dac2ab966471cc', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 4, 'Vao niala kely teo amin’izy ireo anefa aho, Dia hitako ilay olon-tiako. Notazoniko izy ka tsy navelako nandeha Raha tsy tongako tany an-tranon’i Neny, Dia tao amin’ny efitranon’ilay niteraka ahy.', 'vao niala kely teo amin’izy ireo anefa aho, dia hitako ilay olon-tiako. notazoniko izy ka tsy navelako nandeha raha tsy tongako tany an-tranon’i neny, dia tao amin’ny efitranon’ilay niteraka ahy.'),
  ('6ab25b60d3dac2ab966471d3', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 11, '“Mivoaha, ry zanakavavin’i Ziona ô! Jereo i Solomona Mpanjaka Fa manao an’ilay satroboninahitra namboarin’ny reniny ho azy, Tamin’ny fampakaram-badiny, Tamin’ny andro nifalian’ny fony.”', '“mivoaha, ry zanakavavin’i ziona ô! jereo i solomona mpanjaka fa manao an’ilay satroboninahitra namboarin’ny reniny ho azy, tamin’ny fampakaram-badiny, tamin’ny andro nifalian’ny fony.”'),
  ('6ab25b60d3dac2ab966471ca', '2026-09-22T10:41:36.014Z', '2026-09-22T10:41:36.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 3, 2, 'Handeha hiarina aho, dia handehandeha eran’ny tanàna. Aleo hotadiaviko eny an-dalambe Sy eny amin’ny tany malalaka ilay olon-tiako. Nitady azy aho fa tsy nahita.', 'handeha hiarina aho, dia handehandeha eran’ny tanàna. aleo hotadiaviko eny an-dalambe sy eny amin’ny tany malalaka ilay olon-tiako. nitady azy aho fa tsy nahita.'),
  ('6ab25b6082a66cde6d5f2855', '2026-09-22T10:41:36.650Z', '2026-09-22T10:41:36.650Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 3, 'Hoatran’ny kofehy mena midorehitra ny molotrao, Ary mahafinaritra ny teninao. Hoatran’ny silaka ampongabendanitra Ny takolakao ao anaty voaly.', 'hoatran’ny kofehy mena midorehitra ny molotrao, ary mahafinaritra ny teninao. hoatran’ny silaka ampongabendanitra ny takolakao ao anaty voaly.'),
  ('6ab25b6082a66cde6d5f2857', '2026-09-22T10:41:36.650Z', '2026-09-22T10:41:36.650Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 5, 'Ny nononao roa dia toy ny zana-gazela roa, Toy ny zana-gazela kambana Miraoka ahitra eny amin’ny lisy.”', 'ny nononao roa dia toy ny zana-gazela roa, toy ny zana-gazela kambana miraoka ahitra eny amin’ny lisy.”'),
  ('6ab25b6082a66cde6d5f2854', '2026-09-22T10:41:36.650Z', '2026-09-22T10:41:36.650Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 2, 'Ny nifinao dia toy ny andian’ondry vao nohetezana, Izay miakatra avy ao anaty rano nanasana azy. Miteraka kambana izy rehetra, Ary tsy misy tsy mahavanona anaka.', 'ny nifinao dia toy ny andian’ondry vao nohetezana, izay miakatra avy ao anaty rano nanasana azy. miteraka kambana izy rehetra, ary tsy misy tsy mahavanona anaka.'),
  ('6ab25b6082a66cde6d5f2856', '2026-09-22T10:41:36.650Z', '2026-09-22T10:41:36.650Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 4, 'Ny vozonao dia sahala amin’ny tilikambon’i Davida, Izay vita rarivato Sady ihantonan’ny ampinga arivo, Dia ny ampinga boribory rehetra fampiasan’ny lehilahy matanjaka.', 'ny vozonao dia sahala amin’ny tilikambon’i davida, izay vita rarivato sady ihantonan’ny ampinga arivo, dia ny ampinga boribory rehetra fampiasan’ny lehilahy matanjaka.'),
  ('6ab25b6082a66cde6d5f2853', '2026-09-22T10:41:36.650Z', '2026-09-22T10:41:36.650Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 1, '“Tena tsara tarehy ianao, ry malalako. Tena tsara tarehy ianao. Toy ny masom-boromailala ny masonao ao anatin’ny voalinao. Ny volonao kosa hoatran’ny andian’osy Miara-midina ny tendrombohitr’i Gileada.', '“tena tsara tarehy ianao, ry malalako. tena tsara tarehy ianao. toy ny masom-boromailala ny masonao ao anatin’ny voalinao. ny volonao kosa hoatran’ny andian’osy miara-midina ny tendrombohitr’i gileada.'),
  ('6ab25b6082a66cde6d5f2859', '2026-09-22T10:41:36.650Z', '2026-09-22T10:41:36.650Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 7, '“Tsara tarehy be mihitsy ianao, ry malalako, Sady tsy misy tsininy.', '“tsara tarehy be mihitsy ianao, ry malalako, sady tsy misy tsininy.'),
  ('6ab25b6082a66cde6d5f2858', '2026-09-22T10:41:36.650Z', '2026-09-22T10:41:36.650Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 6, '“Dieny mbola tsy mandrivodrivotra ny andro ary mbola tsy lasa ny aloka, Dia ho any amin’ny tendrombohitra misy miora aho, Ary ho any amin’ny havoana misy ditin-kazo manitra.”', '“dieny mbola tsy mandrivodrivotra ny andro ary mbola tsy lasa ny aloka, dia ho any amin’ny tendrombohitra misy miora aho, ary ho any amin’ny havoana misy ditin-kazo manitra.”'),
  ('6ab25b6082a66cde6d5f285d', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 11, 'Mamy noho ny tantely avy ao amin’ny toho-tantely ny molotrao, ry ilay ampakariko. Tantely sy ronono no ao ambany lelanao, Ary toy ny hanitr’i Libàna ny hanitry ny akanjonao.', 'mamy noho ny tantely avy ao amin’ny toho-tantely ny molotrao, ry ilay ampakariko. tantely sy ronono no ao ambany lelanao, ary toy ny hanitr’i libàna ny hanitry ny akanjonao.'),
  ('6ab25b6082a66cde6d5f2861', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 15, 'Loharano ao an-jaridaina ianao, lavadrano misy rano madio, Ary rano mikoriana avy any Libàna.', 'loharano ao an-jaridaina ianao, lavadrano misy rano madio, ary rano mikoriana avy any libàna.'),
  ('6ab25b6082a66cde6d5f285e', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 12, 'Toy ny zaridaina mihidy ianao, rahavako, ry ilay ampakariko, Dia zaridaina mihidy sy loharano misarona.', 'toy ny zaridaina mihidy ianao, rahavako, ry ilay ampakariko, dia zaridaina mihidy sy loharano misarona.'),
  ('6ab25b6082a66cde6d5f285c', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 10, 'Mamy erỳ ny fomba anehoanao fitiavana, rahavako, ry ilay ampakariko! Tsara lavitra noho ny divay ny fitiavanao, Ary mamerovero noho ny zava-manitra ny ranomanitrao!', 'mamy erỳ ny fomba anehoanao fitiavana, rahavako, ry ilay ampakariko! tsara lavitra noho ny divay ny fitiavanao, ary mamerovero noho ny zava-manitra ny ranomanitrao!'),
  ('6ab25b6082a66cde6d5f2862', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 16, 'Mifohaza, ry rivotra avy any avaratra ô! Midira, ry rivotra avy any atsimo ô! Aoka ianareo hitsoka moramora ao an-jaridainako. Enga anie hiparitaka ny fofony manitra!” “Enga anie ilay mamin’ny foko hiditra ao an-jaridainany, Ka hihinana ny voankazo faran’izay tsara ao.”', 'mifohaza, ry rivotra avy any avaratra ô! midira, ry rivotra avy any atsimo ô! aoka ianareo hitsoka moramora ao an-jaridainako. enga anie hiparitaka ny fofony manitra!” “enga anie ilay mamin’ny foko hiditra ao an-jaridainany, ka hihinana ny voankazo faran’izay tsara ao.”'),
  ('6ab25b6082a66cde6d5f2860', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 14, 'Narda sy safrona, fantàkamanitra sy kanelina, Ny karazan-kazo rehetra misy ditiny manitra, miora, aloesy, Ary ny zava-manitra rehetra faran’izay tsara.', 'narda sy safrona, fantàkamanitra sy kanelina, ny karazan-kazo rehetra misy ditiny manitra, miora, aloesy, ary ny zava-manitra rehetra faran’izay tsara.'),
  ('6ab25b6082a66cde6d5f285f', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 13, 'Hoatran’ny paradisa kely feno ampongabendanitra ny tsimoka avy aminao, Sady misy voankazo faran’izay tsara, moina sy narda maniry,', 'hoatran’ny paradisa kely feno ampongabendanitra ny tsimoka avy aminao, sady misy voankazo faran’izay tsara, moina sy narda maniry,'),
  ('6ab25b6082a66cde6d5f285a', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 8, 'Andao isika hiala atỳ Libàna, ry ilay ampakariko, Andao hiala atỳ Libàna! Midìna avy eny an-tampon’i Amana, Avy eny an-tampon’i Senira, eny an-tampon’i Hermona, Avy eny amin’ny tendrombohitra ipetrahan’ny liona sy ny leopara.', 'andao isika hiala atỳ libàna, ry ilay ampakariko, andao hiala atỳ libàna! midìna avy eny an-tampon’i amana, avy eny an-tampon’i senira, eny an-tampon’i hermona, avy eny amin’ny tendrombohitra ipetrahan’ny liona sy ny leopara.'),
  ('6ab25b6082a66cde6d5f285b', '2026-09-22T10:41:36.651Z', '2026-09-22T10:41:36.651Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 4, 9, 'Babonao ny foko, rahavako, ry ilay ampakariko. Babonao ny foko raha vao nitopy indray mandeha tetỳ amiko ny masonao, Raha vao hitako ny mason-drojo iray amin’ilay rojo iambozonanao.', 'babonao ny foko, rahavako, ry ilay ampakariko. babonao ny foko raha vao nitopy indray mandeha tetỳ amiko ny masonao, raha vao hitako ny mason-drojo iray amin’ilay rojo iambozonanao.'),
  ('6ab25b62576e94d3c3b8bd30', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 6, 'Namoha varavarana an’ilay mamin’ny foko aho, Saingy efa tsy teo intsony izy fa efa lasa. Kivy be aho rehefa lasa izy. Nitady azy aho fa tsy nahita. Niantso azy aho, fa tsy namaly izy.', 'namoha varavarana an’ilay mamin’ny foko aho, saingy efa tsy teo intsony izy fa efa lasa. kivy be aho rehefa lasa izy. nitady azy aho fa tsy nahita. niantso azy aho, fa tsy namaly izy.'),
  ('6ab25b62576e94d3c3b8bd2d', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 3, 'Efa nesoriko ny akanjoko ivelany, Dia hanaovako indray ve? Efa nosasako ny tongotro, Dia holotoiko indray ve?', 'efa nesoriko ny akanjoko ivelany, dia hanaovako indray ve? efa nosasako ny tongotro, dia holotoiko indray ve?'),
  ('6ab25b62576e94d3c3b8bd2c', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 2, '“Matory aho nefa mahatsiaro ihany ny foko. Izany mandondòna izany ilay mamin’ny foko! ‘Vohay aho, rahavako, ry malalako, Ry voromailalako, ry ilay tsy misy tsiniko, Fa lenan’ny ando ny lohako, Ary kotsan’ny andon’ny alina ny voloko.’', '“matory aho nefa mahatsiaro ihany ny foko. izany mandondòna izany ilay mamin’ny foko! ‘vohay aho, rahavako, ry malalako, ry voromailalako, ry ilay tsy misy tsiniko, fa lenan’ny ando ny lohako, ary kotsan’ny andon’ny alina ny voloko.’'),
  ('6ab25b62576e94d3c3b8bd32', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 8, 'Ry zanakavavin’i Jerosalema ô! Asaiko mianiana ianareo: Raha hitanareo ilay mamin’ny foko, Dia ilazao izy fa azon’ny tazom-pitia aho.”', 'ry zanakavavin’i jerosalema ô! asaiko mianiana ianareo: raha hitanareo ilay mamin’ny foko, dia ilazao izy fa azon’ny tazom-pitia aho.”'),
  ('6ab25b62576e94d3c3b8bd2f', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 5, 'Nitsangana àry aho hamoha varavarana an’ilay mamin’ny foko. Nitete miora ny tanako, Ary nitete ranona miora ny rantsantanako, Teo amin’ny tahon’ny hidim-baravarana.', 'nitsangana àry aho hamoha varavarana an’ilay mamin’ny foko. nitete miora ny tanako, ary nitete ranona miora ny rantsantanako, teo amin’ny tahon’ny hidim-baravarana.'),
  ('6ab25b62576e94d3c3b8bd2e', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 4, 'Nesorin’ilay mamin’ny foko teo amin’ny lavaky ny hidim-baravarana ny tanany, Dia nidobodoboka be ny foko.', 'nesorin’ilay mamin’ny foko teo amin’ny lavaky ny hidim-baravarana ny tanany, dia nidobodoboka be ny foko.'),
  ('6ab25b62576e94d3c3b8bd31', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 7, 'Hitan’ny mpiambina aho, tamin’izy ireo nandehandeha nanao fisafoana tao an-tanàna. Dia nokapohiny aho ka naratra. Nanendaka ny saly nanaovako ny mpitily teny ambony manda.', 'hitan’ny mpiambina aho, tamin’izy ireo nandehandeha nanao fisafoana tao an-tanàna. dia nokapohiny aho ka naratra. nanendaka ny saly nanaovako ny mpitily teny ambony manda.'),
  ('6ab25b62576e94d3c3b8bd2b', '2026-09-22T10:41:38.678Z', '2026-09-22T10:41:38.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 1, '“Efa niditra ato an-jaridainako aho, rahavako, Ry ilay ampakariko. Efa nioty miora sy zava-manitra aho. Efa nihinana ny tantely avy amin’ny toho-tanteliko aho, Ary efa nisotro ny divaiko sy ny rononoko.” “Mihinàna, ry izy roa kely! Misotroa, ary aoka ianareo ho mamon’ny fitiavana!”', '“efa niditra ato an-jaridainako aho, rahavako, ry ilay ampakariko. efa nioty miora sy zava-manitra aho. efa nihinana ny tantely avy amin’ny toho-tanteliko aho, ary efa nisotro ny divaiko sy ny rononoko.” “mihinàna, ry izy roa kely! misotroa, ary aoka ianareo ho mamon’ny fitiavana!”'),
  ('6ab25b62576e94d3c3b8bd34', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 10, '“Tsara tarehy be ilay mamin’ny foko, sady somary mena. Miavaka amin’ny olona iray alina izy.', '“tsara tarehy be ilay mamin’ny foko, sady somary mena. miavaka amin’ny olona iray alina izy.'),
  ('6ab25b62576e94d3c3b8bd36', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 12, 'Ny masony dia tahaka ny voromailala eo amoron-drano, Dia voromailala mandro ao anaty ronono, Sady mipetraka eo amoron’ny dobo feno rano.', 'ny masony dia tahaka ny voromailala eo amoron-drano, dia voromailala mandro ao anaty ronono, sady mipetraka eo amoron’ny dobo feno rano.'),
  ('6ab25b62576e94d3c3b8bd33', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 9, '“Fa inona loatra no mampiavaka an’ilay mamin’ny fonao amin’ny lehilahy hafa rehetra, Ry ilay vehivavy tsara tarehy indrindra ô? Fa inona loatra no mampiavaka an’ilay mamin’ny fonao amin’ny lehilahy hafa rehetra, No asainao mianiana hoatr’izany izahay?”', '“fa inona loatra no mampiavaka an’ilay mamin’ny fonao amin’ny lehilahy hafa rehetra, ry ilay vehivavy tsara tarehy indrindra ô? fa inona loatra no mampiavaka an’ilay mamin’ny fonao amin’ny lehilahy hafa rehetra, no asainao mianiana hoatr’izany izahay?”'),
  ('6ab25b62576e94d3c3b8bd3a', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 16, 'Mamy dia mamy ny vavany, Ary mahafinaritra daholo izay rehetra mombamomba azy. Hoatr’izany ilay mamin’ny foko. Izany ilay malalako, ry zanakavavin’i Jerosalema ô!”', 'mamy dia mamy ny vavany, ary mahafinaritra daholo izay rehetra mombamomba azy. hoatr’izany ilay mamin’ny foko. izany ilay malalako, ry zanakavavin’i jerosalema ô!”'),
  ('6ab25b62576e94d3c3b8bd37', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 13, 'Ny takolany indray toy ny zaridaina feno zava-manitra, Sy toy ny dongon-tany novolena zava-manitra. Ny molony kosa sahala amin’ny lisy mitete ranona miora.', 'ny takolany indray toy ny zaridaina feno zava-manitra, sy toy ny dongon-tany novolena zava-manitra. ny molony kosa sahala amin’ny lisy mitete ranona miora.'),
  ('6ab25b62576e94d3c3b8bd39', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 15, 'Ny ranjony indray toy ny andry marbra mitsatoka eo amin’ny faladia volamena faran’izay tsara. Tsara tarehy hoatran’i Libàna izy, sady tsy manan-tsahala toy ny hazo sedera.', 'ny ranjony indray toy ny andry marbra mitsatoka eo amin’ny faladia volamena faran’izay tsara. tsara tarehy hoatran’i libàna izy, sady tsy manan-tsahala toy ny hazo sedera.'),
  ('6ab25b62576e94d3c3b8bd35', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 11, 'Hoatran’ny volamena ny lohany, dia volamena faran’izay tsara, Ary ny volony hoatran’ny ravina palmie mikopakopaka, Sady mainty toy ny volon’ny goaika.', 'hoatran’ny volamena ny lohany, dia volamena faran’izay tsara, ary ny volony hoatran’ny ravina palmie mikopakopaka, sady mainty toy ny volon’ny goaika.'),
  ('6ab25b62576e94d3c3b8bd38', '2026-09-22T10:41:38.679Z', '2026-09-22T10:41:38.679Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 5, 14, 'Volamena ny rantsantanany ary noravahana krizolita. Ny kibony dia toy ny ivoara nokosehina hangirana sady voarakotra safira.', 'volamena ny rantsantanany ary noravahana krizolita. ny kibony dia toy ny ivoara nokosehina hangirana sady voarakotra safira.'),
  ('6ab25b63b9435b67b7bfe5fa', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 8, 'Na eo aza ireo vehivavy 60 vadin’ny mpanjaka, Sy ny vadikeliny 80, Ary ny ankizivaviny tsy hita isa,', 'na eo aza ireo vehivavy 60 vadin’ny mpanjaka, sy ny vadikeliny 80, ary ny ankizivaviny tsy hita isa,'),
  ('6ab25b63b9435b67b7bfe5f7', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 5, 'Avilio tsy hijery ahy ny masonao, Fa babon’ny masonao tanteraka aho. Ny volonao dia hoatran’ny andian’osy Miara-midina avy eny Gileada.', 'avilio tsy hijery ahy ny masonao, fa babon’ny masonao tanteraka aho. ny volonao dia hoatran’ny andian’osy miara-midina avy eny gileada.'),
  ('6ab25b63b9435b67b7bfe5f3', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 1, '“Lasa aiza ilay malalanao, Ry vehivavy tsara tarehy indrindra ô? Nivily aiza ilay malalanao? Andao isika hitady azy.”', '“lasa aiza ilay malalanao, ry vehivavy tsara tarehy indrindra ô? nivily aiza ilay malalanao? andao isika hitady azy.”'),
  ('6ab25b63b9435b67b7bfe5fc', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 10, '‘Iza io vehivavy mamirapiratra hoatran’ny hazavana vao maraina io? Tsara tarehy toy ny volana fenomanana izy, Sady madio tahaka ny tara-masoandro, Ary mahavariana toy ny tafika milahatra manodidina ny sainany.’”', '‘iza io vehivavy mamirapiratra hoatran’ny hazavana vao maraina io? tsara tarehy toy ny volana fenomanana izy, sady madio tahaka ny tara-masoandro, ary mahavariana toy ny tafika milahatra manodidina ny sainany.’”'),
  ('6ab25b63b9435b67b7bfe5ff', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 13, '“Miverena! Miverena, ry Solemita ô! Miverena re e! Miverena, Mba hijerenay anao indray!” “Fa maninona ianareo no mandinika an’ilay Solemita?” “Hoatran’ny dihin’ny toby roa izy!”', '“miverena! miverena, ry solemita ô! miverena re e! miverena, mba hijerenay anao indray!” “fa maninona ianareo no mandinika an’ilay solemita?” “hoatran’ny dihin’ny toby roa izy!”'),
  ('6ab25b63b9435b67b7bfe5fe', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 12, 'Tena te hahita an’izany aho, Ka tsy nampoiziko akory Dia tonga teny amin’ny kalesin’ny olona ambony aho.”', 'tena te hahita an’izany aho, ka tsy nampoiziko akory dia tonga teny amin’ny kalesin’ny olona ambony aho.”'),
  ('6ab25b63b9435b67b7bfe5f8', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 6, 'Ny nifinao dia toy ny andian’ondry Izay miakatra avy ao anaty rano nanasana azy. Miteraka kambana izy rehetra, Ary tsy misy tsy mahavanona anaka.', 'ny nifinao dia toy ny andian’ondry izay miakatra avy ao anaty rano nanasana azy. miteraka kambana izy rehetra, ary tsy misy tsy mahavanona anaka.'),
  ('6ab25b63b9435b67b7bfe5f5', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 3, 'An’ny malalako aho, Ary ahy ny malalako. Miandry ondry eny amin’ny toerana feno lisy izy.”', 'an’ny malalako aho, ary ahy ny malalako. miandry ondry eny amin’ny toerana feno lisy izy.”'),
  ('6ab25b63b9435b67b7bfe5f4', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 2, '“Lasa nidina any an-jaridainany ny malalako, Any amin’ny zaridaina feno zava-manitra. Fa hiandry ondry any izy, Sady hioty lisy.', '“lasa nidina any an-jaridainany ny malalako, any amin’ny zaridaina feno zava-manitra. fa hiandry ondry any izy, sady hioty lisy.'),
  ('6ab25b63b9435b67b7bfe5f6', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 4, '“Tsara tarehy hoatran’i Tirza ianao, ry malalako, Kanto hoatran’i Jerosalema, Ary mahavariana toy ny tafika milahatra manodidina ny sainany.', '“tsara tarehy hoatran’i tirza ianao, ry malalako, kanto hoatran’i jerosalema, ary mahavariana toy ny tafika milahatra manodidina ny sainany.'),
  ('6ab25b63b9435b67b7bfe5fd', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 11, '“Nidina nankany amin’ny saha feno voanjoala aho, Mba hijery ny zavamaniry vao mitsiry eny an-dohasaha, Sy hijery raha efa mitsimoka ny voaloboka, Ary efa mamony ny ampongabendanitra.', '“nidina nankany amin’ny saha feno voanjoala aho, mba hijery ny zavamaniry vao mitsiry eny an-dohasaha, sy hijery raha efa mitsimoka ny voaloboka, ary efa mamony ny ampongabendanitra.'),
  ('6ab25b63b9435b67b7bfe5f9', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 7, 'Hoatran’ny silaka ampongabendanitra Ny takolakao ao anaty voaly.', 'hoatran’ny silaka ampongabendanitra ny takolakao ao anaty voaly.'),
  ('6ab25b63b9435b67b7bfe5fb', '2026-09-22T10:41:39.747Z', '2026-09-22T10:41:39.747Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 6, 9, 'Dia iray ihany no voromailalako, ilay tsy misy tsininy. Vavitokan’ny reniny izy, Ary izy no zanaka tena tian’ilay niteraka azy. Nahita azy ny ankizivavy, ka nilaza hoe sambatra izy. Nidera azy koa ny vadin’ny mpanjaka sy ny vadikeliny hoe:', 'dia iray ihany no voromailalako, ilay tsy misy tsininy. vavitokan’ny reniny izy, ary izy no zanaka tena tian’ilay niteraka azy. nahita azy ny ankizivavy, ka nilaza hoe sambatra izy. nidera azy koa ny vadin’ny mpanjaka sy ny vadikeliny hoe:'),
  ('6ab25b64de807985973409dc', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 8, 'Hoy aho: ‘Hianika an’ilay hazo palmie aho, Mba haka ny tahony misy voany.’ Enga anie ho tahaka ny voaloboka amin’ny tangozany ny nononao, Ho manitra hoatran’ny paoma ny fofonainao,', 'hoy aho: ‘hianika an’ilay hazo palmie aho, mba haka ny tahony misy voany.’ enga anie ho tahaka ny voaloboka amin’ny tangozany ny nononao, ho manitra hoatran’ny paoma ny fofonainao,'),
  ('6ab25b64de807985973409db', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 7, 'Hoatran’ny hazo palmie ny fijoronao, Ary toy ny antrendry ny nononao.', 'hoatran’ny hazo palmie ny fijoronao, ary toy ny antrendry ny nononao.'),
  ('6ab25b64de807985973409d9', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 5, 'Tsara tarehy hoatran’ny Tendrombohitra Karmela ny lohanao, Ary tahaka ny volonondry volomparasy ny volonao. Babon’ny volonao mihofahofa ny mpanjaka.', 'tsara tarehy hoatran’ny tendrombohitra karmela ny lohanao, ary tahaka ny volonondry volomparasy ny volonao. babon’ny volonao mihofahofa ny mpanjaka.'),
  ('6ab25b64de807985973409d7', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 3, 'Ny nononao roa dia toy ny zana-gazela roa, Dia zana-gazela kambana.', 'ny nononao roa dia toy ny zana-gazela roa, dia zana-gazela kambana.'),
  ('6ab25b64de807985973409df', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 11, 'Avia, ry ilay mamin’ny foko, Andao isika ho any an-tsaha. Andao isika hipetraka eny ambanin’ny moina.', 'avia, ry ilay mamin’ny foko, andao isika ho any an-tsaha. andao isika hipetraka eny ambanin’ny moina.'),
  ('6ab25b64de807985973409de', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 10, 'An’ny malalako aho, Ary izaho no iriny.', 'an’ny malalako aho, ary izaho no iriny.'),
  ('6ab25b64de807985973409da', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 6, 'Tena tsara tarehy sy mahafinaritra ianao, ry tovovavy malalako, Mbola kanto noho izay mety ho kanto!', 'tena tsara tarehy sy mahafinaritra ianao, ry tovovavy malalako, mbola kanto noho izay mety ho kanto!'),
  ('6ab25b64de807985973409d6', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 2, 'Boribory hoatran’ny vilia baolina ny foitranao. Enga anie hisy divay misy fangarony foana eo! Ary ny kibonao dia toy ny antontam-barimbazaha Voahodidin’ny lisy.', 'boribory hoatran’ny vilia baolina ny foitranao. enga anie hisy divay misy fangarony foana eo! ary ny kibonao dia toy ny antontam-barimbazaha voahodidin’ny lisy.'),
  ('6ab25b64de807985973409d8', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 4, 'Ny vozonao indray hoatran’ny tilikambo ivoara, Ary ny masonao toy ny dobo any Hesbona, Eo akaikin’ny vavahadin’i Bata-rabima. Ny oronao kosa tahaka ny tilikambon’i Libàna, Izay tandrifin’i Damaskosy.', 'ny vozonao indray hoatran’ny tilikambo ivoara, ary ny masonao toy ny dobo any hesbona, eo akaikin’ny vavahadin’i bata-rabima. ny oronao kosa tahaka ny tilikambon’i libàna, izay tandrifin’i damaskosy.'),
  ('6ab25b64de807985973409e1', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 13, 'Manitra erỳ ny angividia! Ary misy voankazo tsara be isan-karazany eo am-baravarantsika. Na ny vaovao na ny efa ela, Dia samy notehiriziko ho anao, ry ilay mamin’ny foko.', 'manitra erỳ ny angividia! ary misy voankazo tsara be isan-karazany eo am-baravarantsika. na ny vaovao na ny efa ela, dia samy notehiriziko ho anao, ry ilay mamin’ny foko.'),
  ('6ab25b64de807985973409dd', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 9, 'Ary ho toy ny divay faran’izay tsara ny vavanao!” “Enga anie ilay divay hidina moramora ao an-tendan’ilay mamin’ny foko, Ary hikoriana moramora eo amin’ny molotr’izay matory!”', 'ary ho toy ny divay faran’izay tsara ny vavanao!” “enga anie ilay divay hidina moramora ao an-tendan’ilay mamin’ny foko, ary hikoriana moramora eo amin’ny molotr’izay matory!”'),
  ('6ab25b64de807985973409d5', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 1, '“Tsara erỳ ny tongotrao ao anatin’ilay kapanao, Ry tovovavy mendri-kaja! Toy ny firavaka notefen’ny mpanao asa tanana Ny bikan’ny fenao.', '“tsara erỳ ny tongotrao ao anatin’ilay kapanao, ry tovovavy mendri-kaja! toy ny firavaka notefen’ny mpanao asa tanana ny bikan’ny fenao.'),
  ('6ab25b64de807985973409e0', '2026-09-22T10:41:40.788Z', '2026-09-22T10:41:40.788Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 7, 12, 'Andao isika hifoha maraina ho any an-tanimboaloboka, Mba hijery raha mitsimoka ny voaloboka, Ary raha efa mamelana ny zavamaniry, Na efa mamony ny ampongabendanitra. Any aho no haneho ny fitiavako anao.', 'andao isika hifoha maraina ho any an-tanimboaloboka, mba hijery raha mitsimoka ny voaloboka, ary raha efa mamelana ny zavamaniry, na efa mamony ny ampongabendanitra. any aho no haneho ny fitiavako anao.'),
  ('6ab25b65054bd4f8a5a60272', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 1, '“Raha mba hoatran’ny anadahiko mantsy ianao, Ka ninono tamin’i Neny, Dia hanoroka anao aho raha mahita anao eny ivelany eny, Nefa tsy hisy olona hanome tsiny ahy.', '“raha mba hoatran’ny anadahiko mantsy ianao, ka ninono tamin’i neny, dia hanoroka anao aho raha mahita anao eny ivelany eny, nefa tsy hisy olona hanome tsiny ahy.'),
  ('6ab25b65054bd4f8a5a60278', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 7, 'Na dia rano manonja be aza tsy mahafaty ny afom-pitiavana. Na renirano koa aza tsy mahavita manongotra azy. Raha misy olona manome ny harena rehetra ao an-tranony mba hividianana fitiavana, Dia tena hatao tsinontsinona izany.”', 'na dia rano manonja be aza tsy mahafaty ny afom-pitiavana. na renirano koa aza tsy mahavita manongotra azy. raha misy olona manome ny harena rehetra ao an-tranony mba hividianana fitiavana, dia tena hatao tsinontsinona izany.”'),
  ('6ab25b65054bd4f8a5a60276', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 5, '“Iza iny miakatra avy any an-tany efitra iny, Iny mitehina amin’ny malalany iny?” “Teo ambany paoma ianao no nofohaziko. Teo ny reninao no nihetsi-jaza niteraka anao. Teo ilay niteraka anao no nihetsi-jaza.', '“iza iny miakatra avy any an-tany efitra iny, iny mitehina amin’ny malalany iny?” “teo ambany paoma ianao no nofohaziko. teo ny reninao no nihetsi-jaza niteraka anao. teo ilay niteraka anao no nihetsi-jaza.'),
  ('6ab25b65054bd4f8a5a6027e', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 13, '“Ry ilay mipetraka ao an-jaridaina ô! Tena te hihaino ny feonao ny namako. Izaho koa te haheno ny feonao.”', '“ry ilay mipetraka ao an-jaridaina ô! tena te hihaino ny feonao ny namako. izaho koa te haheno ny feonao.”'),
  ('6ab25b65054bd4f8a5a60273', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 2, 'Hoentiko ianao, Hoentiko any an-tranon’i Neny, Ilay nampianatra ahy. Horosoako divay nasiana zava-manitra ianao, Sady homeko ranon’ampongabendanitra vao avy natao.', 'hoentiko ianao, hoentiko any an-tranon’i neny, ilay nampianatra ahy. horosoako divay nasiana zava-manitra ianao, sady homeko ranon’ampongabendanitra vao avy natao.'),
  ('6ab25b65054bd4f8a5a6027f', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 14, '“Tongava haingana, ry malalako! Mihazakazaha mafy hoatran’ny gazela Na hoatran’ny zanaka serfa Eny an-tendrombohitry ny zava-manitra.””', '“tongava haingana, ry malalako! mihazakazaha mafy hoatran’ny gazela na hoatran’ny zanaka serfa eny an-tendrombohitry ny zava-manitra.””'),
  ('6ab25b65054bd4f8a5a6027d', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 12, 'Anao, ry Solomona, ny volafotsy arivo sekely, Ary ny roanjato kosa an’izay mikarakara ny vokatra. Fa izaho kosa manana tanimboaloboka azoko ampiasaina amin’izay itiavako azy.”', 'anao, ry solomona, ny volafotsy arivo sekely, ary ny roanjato kosa an’izay mikarakara ny vokatra. fa izaho kosa manana tanimboaloboka azoko ampiasaina amin’izay itiavako azy.”'),
  ('6ab25b65054bd4f8a5a60275', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 4, 'Ry zanakavavin’i Jerosalema ô! Asaiko mianiana ianareo Mba tsy hitady hanaitra na hampitsiry fitiavana ato amiko, fa avelao ilay izy hitsiry ho azy.”', 'ry zanakavavin’i jerosalema ô! asaiko mianiana ianareo mba tsy hitady hanaitra na hampitsiry fitiavana ato amiko, fa avelao ilay izy hitsiry ho azy.”'),
  ('6ab25b65054bd4f8a5a60279', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 8, '“Manana anabavy kely Mbola tsy misy nono izahay. Hataonay ahoana izy Rehefa misy mangataka indray andro any?”', '“manana anabavy kely mbola tsy misy nono izahay. hataonay ahoana izy rehefa misy mangataka indray andro any?”'),
  ('6ab25b65054bd4f8a5a60274', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 3, 'Hiondanako ny tanany ankavia, Ary hamihina ahy ny tanany ankavanana.', 'hiondanako ny tanany ankavia, ary hamihina ahy ny tanany ankavanana.'),
  ('6ab25b65054bd4f8a5a6027b', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 10, '“Manda aho, Ary hoatran’ny tilikambo ny nonoko. Mijery ahy ilay malalako, Dia hitany hoe milamin-tsaina aho.', '“manda aho, ary hoatran’ny tilikambo ny nonoko. mijery ahy ilay malalako, dia hitany hoe milamin-tsaina aho.'),
  ('6ab25b65054bd4f8a5a6027a', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 9, '“Raha manda izy, Dia hanorenantsika tampony volafotsy eo amboniny. Fa raha varavarana kosa izy, Dia hosakanantsika amin’ny hazo fisaka sedera.”', '“raha manda izy, dia hanorenantsika tampony volafotsy eo amboniny. fa raha varavarana kosa izy, dia hosakanantsika amin’ny hazo fisaka sedera.”'),
  ('6ab25b65054bd4f8a5a6027c', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 11, 'Nanana tanimboaloboka tany Bala-hamona i Solomona, Ary nisy olona nasainy nikarakara an’ilay izy. Samy nanome volafotsy arivo sekely avy izy rehetra, rehefa niakatra ny vokatra.', 'nanana tanimboaloboka tany bala-hamona i solomona, ary nisy olona nasainy nikarakara an’ilay izy. samy nanome volafotsy arivo sekely avy izy rehetra, rehefa niakatra ny vokatra.'),
  ('6ab25b65054bd4f8a5a60277', '2026-09-22T10:41:41.363Z', '2026-09-22T10:41:41.363Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Tononkiran''i Solomona', 22, 8, 6, 'Ataovy hoatran’ny tombo-kase eo amin’ny fonao aho, Hoatran’ny tombo-kase eo amin’ny sandrinao. Fa mahery toy ny fahafatesana ny fitiavana, Ary tsy mety milefitra mihitsy hoatran’ny Fasana ny fitiavan’ny olona tokam-po. Toy ny lelafo miredareda izany, dia lelafo avy amin’i Jah.', 'ataovy hoatran’ny tombo-kase eo amin’ny fonao aho, hoatran’ny tombo-kase eo amin’ny sandrinao. fa mahery toy ny fahafatesana ny fitiavana, ary tsy mety milefitra mihitsy hoatran’ny fasana ny fitiavan’ny olona tokam-po. toy ny lelafo miredareda izany, dia lelafo avy amin’i jah.'),
  ('6ab25b65a57615c7378228d5', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 10, 'Henoy ny tenin’i Jehovah, ry mpitondra jadona ao Sodoma! Ary henoy tsara ny lalàn’ilay Andriamanitsika, ry mponin’i Gomora.', 'henoy ny tenin’i jehovah, ry mpitondra jadona ao sodoma! ary henoy tsara ny lalàn’ilay andriamanitsika, ry mponin’i gomora.'),
  ('6ab25b65a57615c7378228d7', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 12, 'Miseho eo anatrehako ianareo, Nefa iza no niteny taminareo hoe Tongava hanitsakitsaka ny tokotaniko?', 'miseho eo anatrehako ianareo, nefa iza no niteny taminareo hoe tongava hanitsakitsaka ny tokotaniko?'),
  ('6ab25b65a57615c7378228d4', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 9, 'Raha tsy i Jehovah Tompon’ny tafika no namela sisa niangana tamintsika, Dia ho efa lasa hoatran’i Sodoma isika, Ary ho efa lasa hoatran’i Gomora.', 'raha tsy i jehovah tompon’ny tafika no namela sisa niangana tamintsika, dia ho efa lasa hoatran’i sodoma isika, ary ho efa lasa hoatran’i gomora.'),
  ('6ab25b65a57615c7378228e8', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 29, 'Hahamenatra anareo ny hazo ngezabe nirinareo, Ary ho afa-baraka ianareo noho ny zaridaina nofidinareo.', 'hahamenatra anareo ny hazo ngezabe nirinareo, ary ho afa-baraka ianareo noho ny zaridaina nofidinareo.'),
  ('6ab25b65a57615c7378228e5', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 26, 'Haveriko ho toy ny tamin’ny voalohany ny mpitsara ao aminao, Ary haveriko ho hoatran’ny taloha ny mpanolo-tsaina anao. Dia hantsoina hoe Tanànan’ny Fahamarinana sy Tanàna Tsy Mivadika Amin’Andriamanitra ianao.', 'haveriko ho toy ny tamin’ny voalohany ny mpitsara ao aminao, ary haveriko ho hoatran’ny taloha ny mpanolo-tsaina anao. dia hantsoina hoe tanànan’ny fahamarinana sy tanàna tsy mivadika amin’andriamanitra ianao.'),
  ('6ab25b65a57615c7378228dc', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 17, 'Mianara manao ny tsara, manaova ny rariny, Anaro ny mpampijaly, Arovy ny zon’ny kamboty ray, Dia arovy koa ny mpitondratena mba hahazo rariny.”', 'mianara manao ny tsara, manaova ny rariny, anaro ny mpampijaly, arovy ny zon’ny kamboty ray, dia arovy koa ny mpitondratena mba hahazo rariny.”'),
  ('6ab25b65a57615c7378228cf', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 4, 'Hahita loza ilay firenena mpanota, Ilay vahoaka efa vesaran’ny fahadisoany, Taranaka ratsy fanahy sy zanaka tena ratsy toetra! Efa nahafoy an’i Jehovah izy ireo, Sady naniratsira an’Ilay Masin’ny Israely, Ary efa nanome lamosina azy.', 'hahita loza ilay firenena mpanota, ilay vahoaka efa vesaran’ny fahadisoany, taranaka ratsy fanahy sy zanaka tena ratsy toetra! efa nahafoy an’i jehovah izy ireo, sady naniratsira an’ilay masin’ny israely, ary efa nanome lamosina azy.'),
  ('6ab25b65a57615c7378228e4', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 25, 'Dia hosaziko ianao, Ary hesoriko tanteraka ny tain-drendrika eo aminao. Hesoriko daholo koa ny loto eo aminao.', 'dia hosaziko ianao, ary hesoriko tanteraka ny tain-drendrika eo aminao. hesoriko daholo koa ny loto eo aminao.'),
  ('6ab25b65a57615c7378228e2', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 23, 'Mafy loha ny andriananao, sady naman’ny mpangalatra. Samy tia mandray kolikoly izy ireo, sady te hahazo fanomezana foana. Tsy omeny rariny ny kamboty ray, Ary tsy raharahiany mihitsy ny fitorian’ny mpitondratena.', 'mafy loha ny andriananao, sady naman’ny mpangalatra. samy tia mandray kolikoly izy ireo, sady te hahazo fanomezana foana. tsy omeny rariny ny kamboty ray, ary tsy raharahiany mihitsy ny fitorian’ny mpitondratena.'),
  ('6ab25b65a57615c7378228dd', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 18, '“Avia hifandamina isika”, hoy i Jehovah. “Fa na mena midorehitra aza ny fahotanareo, Dia hatao fotsy mangatsakatsaka. Ary na hoatran’ny ravin-damba mena antitra aza, Dia ho toy ny volonondry fotsy.', '“avia hifandamina isika”, hoy i jehovah. “fa na mena midorehitra aza ny fahotanareo, dia hatao fotsy mangatsakatsaka. ary na hoatran’ny ravin-damba mena antitra aza, dia ho toy ny volonondry fotsy.'),
  ('6ab25b65a57615c7378228d6', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 11, '“Hataoko inona koa izay sorona be dia be atolotrareo?”, hoy i Jehovah. “Leon’ny ondrilahy ataonareo fanatitra dorana aho, sady tofoky ny tavin’ny biby nohatavezina, Ary tsy mahafinaritra ahy ny ran’ny vantotr’ombilahy sy ny ran’ny zanak’ondry ary ny ran’ny osilahy.', '“hataoko inona koa izay sorona be dia be atolotrareo?”, hoy i jehovah. “leon’ny ondrilahy ataonareo fanatitra dorana aho, sady tofoky ny tavin’ny biby nohatavezina, ary tsy mahafinaritra ahy ny ran’ny vantotr’ombilahy sy ny ran’ny zanak’ondry ary ny ran’ny osilahy.'),
  ('6ab25b65a57615c7378228d1', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 6, 'Tsy misy tsy marary hatrany an-tampon-doha ka hatrany am-paladia, Sady feno ratra sy mangana ary fery. Tsy nisy notsaboina anefa ireny, na nofehezina lamba, sady tsy nohosorana menaka.', 'tsy misy tsy marary hatrany an-tampon-doha ka hatrany am-paladia, sady feno ratra sy mangana ary fery. tsy nisy notsaboina anefa ireny, na nofehezina lamba, sady tsy nohosorana menaka.'),
  ('6ab25b65a57615c7378228ce', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 3, 'Mahalala tsara ny tompony ny omby, Ary ny ampondra mahalala tsara ny fihinanam-bilona natokan’ny tompony ho azy. Ny Israely kosa tsy mahalala ahy, Ary ny vahoakako tsy mba misaina.”', 'mahalala tsara ny tompony ny omby, ary ny ampondra mahalala tsara ny fihinanam-bilona natokan’ny tompony ho azy. ny israely kosa tsy mahalala ahy, ary ny vahoakako tsy mba misaina.”'),
  ('6ab25b65a57615c7378228e7', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 28, 'Hotorotoroina miaraka ny mpikomy sy ny mpanota, Ary ho ringana izay mahafoy an’i Jehovah.', 'hotorotoroina miaraka ny mpikomy sy ny mpanota, ary ho ringana izay mahafoy an’i jehovah.'),
  ('6ab25b65a57615c7378228e1', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 22, 'Lasa tain-drendrika ny volafotsinao, Ary mitampoka rano ny labieranao.', 'lasa tain-drendrika ny volafotsinao, ary mitampoka rano ny labieranao.'),
  ('6ab25b65a57615c7378228da', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 15, 'Rehefa mamelatra ny tananareo ianareo, Dia tampenako tsy hijery anareo ny masoko. Na mivavaka imbetsaka aza ianareo, Dia tsy hihaino aho, Fa feno ran’olona ny tananareo.', 'rehefa mamelatra ny tananareo ianareo, dia tampenako tsy hijery anareo ny masoko. na mivavaka imbetsaka aza ianareo, dia tsy hihaino aho, fa feno ran’olona ny tananareo.'),
  ('6ab25b65a57615c7378228d9', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 14, 'Halako ny tsinam-bolana sy ny fety ankalazainareo. Lasa enta-mavesatra amiko ireny, Ka reraka aho mitondra azy.', 'halako ny tsinam-bolana sy ny fety ankalazainareo. lasa enta-mavesatra amiko ireny, ka reraka aho mitondra azy.'),
  ('6ab25b65a57615c7378228cd', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 2, 'Mihainoa, ry lanitra, ary mihainoa tsara, ry tany! Fa izao no nolazain’i Jehovah: “Efa nitaiza sy nahalehibe zanaka aho, Nefa nikomy tamiko izy ireo.', 'mihainoa, ry lanitra, ary mihainoa tsara, ry tany! fa izao no nolazain’i jehovah: “efa nitaiza sy nahalehibe zanaka aho, nefa nikomy tamiko izy ireo.'),
  ('6ab25b65a57615c7378228cc', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 1, 'Ny fahitan’i Isaia zanak’i Amoza momba an’i Joda sy Jerosalema, tamin’ny andron’i Ozia, Jotama, Ahaza, ary Hezekia, izay samy mpanjakan’ny Joda:', 'ny fahitan’i isaia zanak’i amoza momba an’i joda sy jerosalema, tamin’ny andron’i ozia, jotama, ahaza, ary hezekia, izay samy mpanjakan’ny joda:'),
  ('6ab25b65a57615c7378228e6', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 27, 'Ny rariny no hanavotana an’i Ziona, Ary ny fahamarinana no hanavotana ny mponina tao, izay miverina.', 'ny rariny no hanavotana an’i ziona, ary ny fahamarinana no hanavotana ny mponina tao, izay miverina.'),
  ('6ab25b65a57615c7378228d8', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 13, 'Aza mitondra fanatitra varimbazaha tsy misy dikany intsony. Maharikoriko ahy ny emboka manitra ataonareo. Mankalaza tsinam-bolana sy mitandrina sabata ianareo, ary manao fivoriambe, Nefa tsy zakako ny ataonareo, satria sady mampiasa herin’ny maizina ianareo no manao fivoriambe makotrokotroka.', 'aza mitondra fanatitra varimbazaha tsy misy dikany intsony. maharikoriko ahy ny emboka manitra ataonareo. mankalaza tsinam-bolana sy mitandrina sabata ianareo, ary manao fivoriambe, nefa tsy zakako ny ataonareo, satria sady mampiasa herin’ny maizina ianareo no manao fivoriambe makotrokotroka.'),
  ('6ab25b65a57615c7378228db', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 16, 'Misasà ka diovy ny tenanareo. Esory tsy ho eo imasoko ny zava-dratsy ataonareo, Ary aza manao ratsy intsony.', 'misasà ka diovy ny tenanareo. esory tsy ho eo imasoko ny zava-dratsy ataonareo, ary aza manao ratsy intsony.'),
  ('6ab25b65a57615c7378228ea', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 31, 'Dia ho toy ny mololo ny lehilahy matanjaka, Ary ho lasa hoatran’ny pitik’afo ny zavatra ataony. Samy ho may daholo izy roa ireo, Ary tsy hisy hahavita hamono an’ilay afo.”', 'dia ho toy ny mololo ny lehilahy matanjaka, ary ho lasa hoatran’ny pitik’afo ny zavatra ataony. samy ho may daholo izy roa ireo, ary tsy hisy hahavita hamono an’ilay afo.”'),
  ('6ab25b65a57615c7378228d2', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 7, 'Tsy misy mponina ny taninareo, Sady kilan’ny afo ny tanànanareo. Arapaky ny hafa firenena eo imasonareo ny taninareo, Ka lasa ngazana hoatran’ny tany noravaravan’ny hafa firenena.', 'tsy misy mponina ny taninareo, sady kilan’ny afo ny tanànanareo. arapaky ny hafa firenena eo imasonareo ny taninareo, ka lasa ngazana hoatran’ny tany noravaravan’ny hafa firenena.'),
  ('6ab25b65a57615c7378228e0', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 21, 'Indrisy fa lasa mpivaro-tena ilay tanàna tsy nivadika! Ny rariny no nanjaka tao, Ary nanao ny marina daholo ny olona tao, Nefa izao mpamono olona daholo no ao.', 'indrisy fa lasa mpivaro-tena ilay tanàna tsy nivadika! ny rariny no nanjaka tao, ary nanao ny marina daholo ny olona tao, nefa izao mpamono olona daholo no ao.'),
  ('6ab25b65a57615c7378228df', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 20, 'Fa raha tsy manaiky anefa ianareo fa mikomy, Dia haripaky ny sabatra, Satria i Jehovah no efa niteny.”', 'fa raha tsy manaiky anefa ianareo fa mikomy, dia haripaky ny sabatra, satria i jehovah no efa niteny.”'),
  ('6ab25b65a57615c7378228e3', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 24, 'Izao àry no tenin’i Jehovah Tompon’ny tafika, ilay tena Tompo, Dia ilay Maherin’ny Israely: “Haripako ny fahavaloko, Ka hovaliako araka izay nataony izy.', 'izao àry no tenin’i jehovah tompon’ny tafika, ilay tena tompo, dia ilay maherin’ny israely: “haripako ny fahavaloko, ka hovaliako araka izay nataony izy.'),
  ('6ab25b65a57615c7378228d0', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 5, 'Aiza indray no tianareo hikapohana anareo fa mbola mikomy ihany ianareo? Efa marary ny loha manontolo, Sady marary koa ny fo manontolo.', 'aiza indray no tianareo hikapohana anareo fa mbola mikomy ihany ianareo? efa marary ny loha manontolo, sady marary koa ny fo manontolo.'),
  ('6ab25b65a57615c7378228e9', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 30, 'Fa ho toy ny hazobe feno ravina malazo ianareo, Ary ho lasa hoatran’ny zaridaina tsy misy rano.', 'fa ho toy ny hazobe feno ravina malazo ianareo, ary ho lasa hoatran’ny zaridaina tsy misy rano.'),
  ('6ab25b65a57615c7378228de', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 19, 'Raha manaiky hihaino ianareo, Dia hihinana ny vokatra tsara avy amin’ny tany.', 'raha manaiky hihaino ianareo, dia hihinana ny vokatra tsara avy amin’ny tany.'),
  ('6ab25b65a57615c7378228d3', '2026-09-22T10:41:41.854Z', '2026-09-22T10:41:41.854Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 1, 8, 'Ary i Ziona zanakavavy dia nilaozana hoatran’ny tranokely fialokalofana eny an-tanimboaloboka, Sy toy ny trano rantsankazo eny amin’ny saha fambolena kôkômbra, Ary hoatran’ny tanàna atao fahirano.', 'ary i ziona zanakavavy dia nilaozana hoatran’ny tranokely fialokalofana eny an-tanimboaloboka, sy toy ny trano rantsankazo eny amin’ny saha fambolena kôkômbra, ary hoatran’ny tanàna atao fahirano.'),
  ('6ab25b66443c5c698060e9c1', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 19, 'Dia hiditra any anaty lava-bato Sy ao anaty lavaka any ambanin’ny tany ny olona. Fa mampahatahotra ny fahatezeran’i Jehovah, Ary mamirapiratra ny fahalehibeazany, Rehefa mitsangana mba hampangovitra sy hampitahotra ny tany izy.', 'dia hiditra any anaty lava-bato sy ao anaty lavaka any ambanin’ny tany ny olona. fa mampahatahotra ny fahatezeran’i jehovah, ary mamirapiratra ny fahalehibeazany, rehefa mitsangana mba hampangovitra sy hampitahotra ny tany izy.'),
  ('6ab25b66443c5c698060e9b9', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 11, 'Haetry ny mason’ny olona mianjonanjona, Ary ho lasa ambany ny olona manambony tena. Fa i Jehovah irery ihany no hasandratra amin’izany andro izany.', 'haetry ny mason’ny olona mianjonanjona, ary ho lasa ambany ny olona manambony tena. fa i jehovah irery ihany no hasandratra amin’izany andro izany.'),
  ('6ab25b66443c5c698060e9b8', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 10, 'Midira ao anaty vatolampy ary miafena ao amin’ny vovoka, Fa mampahatahotra ny fahatezeran’i Jehovah, Ary mamirapiratra ny fahalehibeazany.', 'midira ao anaty vatolampy ary miafena ao amin’ny vovoka, fa mampahatahotra ny fahatezeran’i jehovah, ary mamirapiratra ny fahalehibeazany.'),
  ('6ab25b66443c5c698060e9c3', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 21, 'Dia hiditra any anaty lava-bato Sy any an-tsefatsefaky ny harambato izy ireo. Fa mampahatahotra ny fahatezeran’i Jehovah, Ary mamirapiratra ny fahalehibeazany, Rehefa mitsangana mba hampangovitra sy hampitahotra ny tany izy.', 'dia hiditra any anaty lava-bato sy any an-tsefatsefaky ny harambato izy ireo. fa mampahatahotra ny fahatezeran’i jehovah, ary mamirapiratra ny fahalehibeazany, rehefa mitsangana mba hampangovitra sy hampitahotra ny tany izy.'),
  ('6ab25b66443c5c698060e9c4', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 22, 'Raha tsy te hahita loza àry ianareo, dia aza matoky olombelona intsony. Fa fofonaina ihany no eo am-bavorony, Ka misy dikany inona moa izy?', 'raha tsy te hahita loza àry ianareo, dia aza matoky olombelona intsony. fa fofonaina ihany no eo am-bavorony, ka misy dikany inona moa izy?'),
  ('6ab25b66443c5c698060e9b6', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 8, 'Feno andriamanitra tsy misy dikany ny taniny. Miankohoka amin’ny zavatra nataon’ny tanany ihany izy ireo, Dia amin’ny zavatra nataon’ny rantsantanany ihany.', 'feno andriamanitra tsy misy dikany ny taniny. miankohoka amin’ny zavatra nataon’ny tanany ihany izy ireo, dia amin’ny zavatra nataon’ny rantsantanany ihany.'),
  ('6ab25b66443c5c698060e9bb', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 13, 'Amin’ny sedera avo be mijoalajoala rehetra any Libàna, Amin’ny hazo oaka rehetra any Basana,', 'amin’ny sedera avo be mijoalajoala rehetra any libàna, amin’ny hazo oaka rehetra any basana,'),
  ('6ab25b66443c5c698060e9ba', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 12, 'Andron’i Jehovah Tompon’ny tafika mantsy izany, Ka ho tonga amin’izay mirehareha sy manambony tena, Amin’ny olona rehetra, na ambony izy na ambany,', 'andron’i jehovah tompon’ny tafika mantsy izany, ka ho tonga amin’izay mirehareha sy manambony tena, amin’ny olona rehetra, na ambony izy na ambany,'),
  ('6ab25b66443c5c698060e9b5', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 7, 'Feno volafotsy sy volamena ny taniny, Ary tsy mety lany ny harenany. Feno soavaly koa ny taniny, Sady tsy voaisa ny kalesiny.', 'feno volafotsy sy volamena ny taniny, ary tsy mety lany ny harenany. feno soavaly koa ny taniny, sady tsy voaisa ny kalesiny.'),
  ('6ab25b66443c5c698060e9b0', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 2, 'Any am-parany any, Ilay tendrombohitra misy ny tranon’i Jehovah Dia ho mafy orina sady ho avo noho ny tampon’ireo tendrombohitra, Ka hasandratra ho avo noho ireo havoana. Ary hiaraka ho any ny firenena rehetra.', 'any am-parany any, ilay tendrombohitra misy ny tranon’i jehovah dia ho mafy orina sady ho avo noho ny tampon’ireo tendrombohitra, ka hasandratra ho avo noho ireo havoana. ary hiaraka ho any ny firenena rehetra.'),
  ('6ab25b66443c5c698060e9bf', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 17, 'Dia haetry ny olona mianjonanjona, Ary ho lasa ambany ny olona manambony tena. Fa i Jehovah irery ihany no hasandratra amin’izany andro izany.', 'dia haetry ny olona mianjonanjona, ary ho lasa ambany ny olona manambony tena. fa i jehovah irery ihany no hasandratra amin’izany andro izany.'),
  ('6ab25b66443c5c698060e9bd', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 15, 'Amin’ny tilikambo avo rehetra sy ny manda voaro mafy rehetra,', 'amin’ny tilikambo avo rehetra sy ny manda voaro mafy rehetra,'),
  ('6ab25b66443c5c698060e9bc', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 14, 'Amin’ny tendrombohitra avo rehetra, Amin’ny havoana rehetra,', 'amin’ny tendrombohitra avo rehetra, amin’ny havoana rehetra,'),
  ('6ab25b66443c5c698060e9af', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 1, 'Izao no hitan’i Isaia zanak’i Amoza momba an’i Joda sy Jerosalema:', 'izao no hitan’i isaia zanak’i amoza momba an’i joda sy jerosalema:'),
  ('6ab25b66443c5c698060e9b1', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 3, 'Be dia be ny olona ho any, ka hiteny hoe: “Avia! Andao isika hiakatra ho any an-tendrombohitr’i Jehovah, Ho any an-tranon’Andriamanitr’i Jakoba. Hampianatra antsika ny lalany izy, Dia handeha amin’ny lalana atorony isika.” Fa avy ao Ziona no hivoahan’ny lalàna, Ary avy ao Jerosalema ny tenin’i Jehovah.', 'be dia be ny olona ho any, ka hiteny hoe: “avia! andao isika hiakatra ho any an-tendrombohitr’i jehovah, ho any an-tranon’andriamanitr’i jakoba. hampianatra antsika ny lalany izy, dia handeha amin’ny lalana atorony isika.” fa avy ao ziona no hivoahan’ny lalàna, ary avy ao jerosalema ny tenin’i jehovah.'),
  ('6ab25b66443c5c698060e9be', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 16, 'Amin’ny sambon’i Tarsisy rehetra Ary amin’ny sambo mirenty rehetra.', 'amin’ny sambon’i tarsisy rehetra ary amin’ny sambo mirenty rehetra.'),
  ('6ab25b66443c5c698060e9b3', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 5, 'Ry taranak’i Jakoba ô, Andao isika hanaraka ny hazavana avy amin’i Jehovah!', 'ry taranak’i jakoba ô, andao isika hanaraka ny hazavana avy amin’i jehovah!'),
  ('6ab25b66443c5c698060e9b7', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 9, 'Manambany ny tenany àry ny olona ka afa-baraka, Dia tsy ho afaka hamela ny helony ianao.', 'manambany ny tenany àry ny olona ka afa-baraka, dia tsy ho afaka hamela ny helony ianao.'),
  ('6ab25b66443c5c698060e9c0', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 18, 'Hanjavona tanteraka ireo andriamanitra tsy misy dikany.', 'hanjavona tanteraka ireo andriamanitra tsy misy dikany.'),
  ('6ab25b66443c5c698060e9b4', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 6, 'Fa nafoinao ny vahoakanao, dia ny taranak’i Jakoba, Satria lasa feno zavatra avy any Atsinanana ny taniny. Mampiasa herin’ny maizina hoatran’ny ataon’ny Filistinina koa izy ireo, Ary feno zanaky ny hafa firenena eo aminy.', 'fa nafoinao ny vahoakanao, dia ny taranak’i jakoba, satria lasa feno zavatra avy any atsinanana ny taniny. mampiasa herin’ny maizina hoatran’ny ataon’ny filistinina koa izy ireo, ary feno zanaky ny hafa firenena eo aminy.'),
  ('6ab25b66443c5c698060e9b2', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 4, 'Hamoaka didim-pitsarana eo amin’ireo firenena izy, Ka hanitsy an’izay tsy mety eo amin’izy ireo. Dia hanefy ny sabany ho angadinomby izy ireo, Ary ny lefony ho antsy fandrantsanam-boaloboka. Tsy hifamely amin’ny sabatra intsony ireo firenena, Sady tsy hianatra ady intsony.', 'hamoaka didim-pitsarana eo amin’ireo firenena izy, ka hanitsy an’izay tsy mety eo amin’izy ireo. dia hanefy ny sabany ho angadinomby izy ireo, ary ny lefony ho antsy fandrantsanam-boaloboka. tsy hifamely amin’ny sabatra intsony ireo firenena, sady tsy hianatra ady intsony.'),
  ('6ab25b66443c5c698060e9c2', '2026-09-22T10:41:42.279Z', '2026-09-22T10:41:42.279Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 2, 20, 'Amin’izany andro izany, dia halain’ny olona ny andriamaniny volafotsy sy volamena tsy misy dikany, Izay nataony hiankohofana, Ka hariany any amin’ny voalavo matsoko vava sy ny ramanavy.', 'amin’izany andro izany, dia halain’ny olona ny andriamaniny volafotsy sy volamena tsy misy dikany, izay nataony hiankohofana, ka hariany any amin’ny voalavo matsoko vava sy ny ramanavy.'),
  ('6ab25b664239aa9c6bbb178f', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 9, 'Na ny endrik’izy ireo aza dia efa miampanga ny tenany. Resahiny daholo ny fahotany, hoatran’ny nataon’ny mponin’i Sodoma, Fa tsy afeniny. Hahita loza izy ireo, fa izy ihany no mampiditra loza ho an’ny tenany!', 'na ny endrik’izy ireo aza dia efa miampanga ny tenany. resahiny daholo ny fahotany, hoatran’ny nataon’ny mponin’i sodoma, fa tsy afeniny. hahita loza izy ireo, fa izy ihany no mampiditra loza ho an’ny tenany!'),
  ('6ab25b664239aa9c6bbb179e', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 24, 'Fofona masiso no ho solon’ny hanitry ny menaka balsama, Tady no ho solon’ny fehikibo, Loha sola no ho solon’ny volo namboarina tsara, Lamba gony no ho solon’ny akanjo lafo vidy, Ary tomboka amin’ny vy mahamay no ho solon’ny hatsaran-tarehy.', 'fofona masiso no ho solon’ny hanitry ny menaka balsama, tady no ho solon’ny fehikibo, loha sola no ho solon’ny volo namboarina tsara, lamba gony no ho solon’ny akanjo lafo vidy, ary tomboka amin’ny vy mahamay no ho solon’ny hatsaran-tarehy.'),
  ('6ab25b664239aa9c6bbb178b', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 5, 'Dia hampijaly ny namany avy ny olona. Samy hanao hoatr’izany amin’ny namany avy izy rehetra. Ny ankizilahy hihetraketraka amin’ny lehilahy efa zokiolona, Ary ny olona tsisy fotony ho sahy haniratsira ny olona manan-kaja.', 'dia hampijaly ny namany avy ny olona. samy hanao hoatr’izany amin’ny namany avy izy rehetra. ny ankizilahy hihetraketraka amin’ny lehilahy efa zokiolona, ary ny olona tsisy fotony ho sahy haniratsira ny olona manan-kaja.'),
  ('6ab25b664239aa9c6bbb1788', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 2, 'Ny lehilahy matanjaka sy ny miaramila, Ny mpitsara sy ny mpaminany, ny mpisikidy sy ny anti-panahy,', 'ny lehilahy matanjaka sy ny miaramila, ny mpitsara sy ny mpaminany, ny mpisikidy sy ny anti-panahy,'),
  ('6ab25b664239aa9c6bbb1798', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 18, 'Amin’izany andro izany, dia hesorin’i Jehovah ny firavak’izy ireo: Ny rojokely haingon-tongotra, ny fehiloha, ny ravaka hoatran’ny volan-tsinana,', 'amin’izany andro izany, dia hesorin’i jehovah ny firavak’izy ireo: ny rojokely haingon-tongotra, ny fehiloha, ny ravaka hoatran’ny volan-tsinana,'),
  ('6ab25b664239aa9c6bbb1795', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 15, 'Dia sahinareo ve ny mamotika ny vahoakako, Sy mampihosina ny tarehiny ao anaty vovoka?”, hoy i Jehovah Tompon’ny tafika, ilay Tompo Fara Tampony.', 'dia sahinareo ve ny mamotika ny vahoakako, sy mampihosina ny tarehiny ao anaty vovoka?”, hoy i jehovah tompon’ny tafika, ilay tompo fara tampony.'),
  ('6ab25b664239aa9c6bbb179a', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 20, 'Ny saron-doha, ny rojon-tongotra, ny fehikibo, Ny fitoeran-dranomanitra, ny ody fiaro,', 'ny saron-doha, ny rojon-tongotra, ny fehikibo, ny fitoeran-dranomanitra, ny ody fiaro,'),
  ('6ab25b664239aa9c6bbb1792', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 12, 'Mampijaly ny vahoakako ny mpanery azy hiasa, Ary vehivavy no mpitondra azy. Mampirenireny anareo ny mpitarika anareo, ry vahoakako, Dia ataony tsy hitanareo hoe aiza ny lalana haleha.', 'mampijaly ny vahoakako ny mpanery azy hiasa, ary vehivavy no mpitondra azy. mampirenireny anareo ny mpitarika anareo, ry vahoakako, dia ataony tsy hitanareo hoe aiza ny lalana haleha.'),
  ('6ab25b664239aa9c6bbb178d', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 7, 'Tsy hanaiky anefa izy amin’izany andro izany, ka hiteny hoe: “Tsy hitsabo ny ferinareo aho, Ary tsy misy sakafo na akanjo ao an-tranoko. Dia aza atao mpitondra vahoaka aho.”', 'tsy hanaiky anefa izy amin’izany andro izany, ka hiteny hoe: “tsy hitsabo ny ferinareo aho, ary tsy misy sakafo na akanjo ao an-tranoko. dia aza atao mpitondra vahoaka aho.”'),
  ('6ab25b664239aa9c6bbb178c', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 6, 'Samy hitazona ny sandrin’ny rahalahiny ao an-tranon-drainy ny olona, ka hiteny hoe: “Manana akanjo ivelany ianao. Mbà maneke re ho mpitondra anay e! Dia raiso ho andraikitrao ity toerana rava ity.”', 'samy hitazona ny sandrin’ny rahalahiny ao an-tranon-drainy ny olona, ka hiteny hoe: “manana akanjo ivelany ianao. mbà maneke re ho mpitondra anay e! dia raiso ho andraikitrao ity toerana rava ity.”'),
  ('6ab25b664239aa9c6bbb1793', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 13, 'Maka toerana i Jehovah mba hiampanga olona, Ary mitsangana mba hamoaka didim-pitsarana hampiharina amin’ireo firenena.', 'maka toerana i jehovah mba hiampanga olona, ary mitsangana mba hamoaka didim-pitsarana hampiharina amin’ireo firenena.'),
  ('6ab25b664239aa9c6bbb178e', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 8, 'Fa lavo i Jerosalema, Ary nianjera i Joda, Satria manohitra an’i Jehovah amin’ny teniny sy ny ataony izy ireo, Sady mikomy eo imason’Ilay Be Voninahitra.', 'fa lavo i jerosalema, ary nianjera i joda, satria manohitra an’i jehovah amin’ny teniny sy ny ataony izy ireo, sady mikomy eo imason’ilay be voninahitra.'),
  ('6ab25b664239aa9c6bbb1797', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 17, 'Hataon’i Jehovah feno takopery àry ny tampon-dohan’ny zanakavavin’i Ziona, Ary hataon’i Jehovah miharihary ny tampon-kandriny.', 'hataon’i jehovah feno takopery àry ny tampon-dohan’ny zanakavavin’i ziona, ary hataon’i jehovah miharihary ny tampon-kandriny.'),
  ('6ab25b664239aa9c6bbb1790', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 10, 'Lazao ny olo-marina hoe hahita soa izy ireo, Ary homena valisoa noho izay ataony.', 'lazao ny olo-marina hoe hahita soa izy ireo, ary homena valisoa noho izay ataony.'),
  ('6ab25b664239aa9c6bbb1789', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 3, 'Ny lehiben’ny 50, ny olo-manan-kaja, ny mpanolo-tsaina, Ny mpimasy tena mahay, ary ny olona mahay mibaiko bibilava.', 'ny lehiben’ny 50, ny olo-manan-kaja, ny mpanolo-tsaina, ny mpimasy tena mahay, ary ny olona mahay mibaiko bibilava.'),
  ('6ab25b664239aa9c6bbb1787', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 1, 'I Jehovah Tompon’ny Tafika no tena Tompo. Esoriny ao Jerosalema sy Joda ny andry iankinana sy ny vatsy rehetra, Dia ny sakafo sy ny rano rehetra,', 'i jehovah tompon’ny tafika no tena tompo. esoriny ao jerosalema sy joda ny andry iankinana sy ny vatsy rehetra, dia ny sakafo sy ny rano rehetra,'),
  ('6ab25b664239aa9c6bbb179b', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 21, 'Ny peratra, ny kavin’orona,', 'ny peratra, ny kavin’orona,'),
  ('6ab25b664239aa9c6bbb178a', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 4, 'Ankizilahy no hataoko ho andrianan’izy ireo, Ary olona miovaova hevitra no ho mpitondra azy.', 'ankizilahy no hataoko ho andrianan’izy ireo, ary olona miovaova hevitra no ho mpitondra azy.'),
  ('6ab25b664239aa9c6bbb179d', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 23, 'Ny fitaratra, ny akanjo rongony, Ny satroka lamba, ary ny voaly.', 'ny fitaratra, ny akanjo rongony, ny satroka lamba, ary ny voaly.'),
  ('6ab25b664239aa9c6bbb179c', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 22, 'Ny akanjo mihaja be, ny akanjo lava, ny akanjo ivelany, ny kitapom-bola,', 'ny akanjo mihaja be, ny akanjo lava, ny akanjo ivelany, ny kitapom-bola,'),
  ('6ab25b664239aa9c6bbb179f', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 25, 'Ho fatin’ny sabatra ny lehilahy ao aminao, Ary ho faty any an’ady ny lehilahy matanjaka.', 'ho fatin’ny sabatra ny lehilahy ao aminao, ary ho faty any an’ady ny lehilahy matanjaka.'),
  ('6ab25b664239aa9c6bbb17a0', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 26, 'Hisaona sy halahelo be ny vavahadin’ny tanàna. Ho lasa tsy misy mponina ilay tanàna, ka hipetraka amin’ny tany i Ziona.”', 'hisaona sy halahelo be ny vavahadin’ny tanàna. ho lasa tsy misy mponina ilay tanàna, ka hipetraka amin’ny tany i ziona.”'),
  ('6ab25b664239aa9c6bbb1796', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 16, 'Hoy koa i Jehovah: “Mianjonanjona ireo zanakavavin’i Ziona, Ary milanjalanja loha rehefa mandeha. Manao maso mambabo izy ireo sady jejojejo erỳ rehefa mamindra, Ka mampikorintsana ny rojo eny an-tongony.', 'hoy koa i jehovah: “mianjonanjona ireo zanakavavin’i ziona, ary milanjalanja loha rehefa mandeha. manao maso mambabo izy ireo sady jejojejo erỳ rehefa mamindra, ka mampikorintsana ny rojo eny an-tongony.'),
  ('6ab25b664239aa9c6bbb1794', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 14, 'Hanameloka ny anti-panahy sy ny andrianan’ny vahoakany i Jehovah. “Nodoranareo ny tanimboaloboka, Ary ao an-tranonareo ny zavatra nangalarinareo tamin’ny mahantra.', 'hanameloka ny anti-panahy sy ny andrianan’ny vahoakany i jehovah. “nodoranareo ny tanimboaloboka, ary ao an-tranonareo ny zavatra nangalarinareo tamin’ny mahantra.'),
  ('6ab25b664239aa9c6bbb1799', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 19, 'Ny kavina, ny brasele, ny voaly,', 'ny kavina, ny brasele, ny voaly,'),
  ('6ab25b664239aa9c6bbb1791', '2026-09-22T10:41:42.776Z', '2026-09-22T10:41:42.776Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 3, 11, 'Hahita loza ny ratsy fanahy! Hahita loza izy, Fa izay nataony ihany no havaly aminy!', 'hahita loza ny ratsy fanahy! hahita loza izy, fa izay nataony ihany no havaly aminy!'),
  ('6ab25b678b06166ab7a22d9e', '2026-09-22T10:41:43.411Z', '2026-09-22T10:41:43.411Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 4, 5, 'Ankoatra izany, dia hasian’i Jehovah rahona sy setroka eo ambonin’ny Tendrombohitra Ziona manontolo sy eo ambonin’ny toerana fanaovany fivoriambe, mandritra ny andro, fa hasiany afo mirehitra mazava be kosa mandritra ny alina. Hisy fialofana mantsy hanarona an’ilay toerana be voninahitra manontolo.', 'ankoatra izany, dia hasian’i jehovah rahona sy setroka eo ambonin’ny tendrombohitra ziona manontolo sy eo ambonin’ny toerana fanaovany fivoriambe, mandritra ny andro, fa hasiany afo mirehitra mazava be kosa mandritra ny alina. hisy fialofana mantsy hanarona an’ilay toerana be voninahitra manontolo.'),
  ('6ab25b678b06166ab7a22d9b', '2026-09-22T10:41:43.411Z', '2026-09-22T10:41:43.411Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 4, 2, 'Amin’izany andro izany, dia hampitsimoka zavamaniry tsara tarehy sy mahafinaritra i Jehovah. Hirehareha sy ho falifaly izay sisa velona amin’ny Israely noho ny vokatry ny tany.', 'amin’izany andro izany, dia hampitsimoka zavamaniry tsara tarehy sy mahafinaritra i jehovah. hirehareha sy ho falifaly izay sisa velona amin’ny israely noho ny vokatry ny tany.'),
  ('6ab25b678b06166ab7a22d9a', '2026-09-22T10:41:43.411Z', '2026-09-22T10:41:43.411Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 4, 1, 'Amin’izany andro izany, dia hisy vehivavy fito hitazona lehilahy iray, ka hiteny hoe: “Ny sakafonay ihany no hohaninay, Ary ny akanjonay ihany no hanaovanay, Fa mba avelao fotsiny izahay hantsoina amin’ny anaranao, Mba tsy ho afa-baraka intsony.”', 'amin’izany andro izany, dia hisy vehivavy fito hitazona lehilahy iray, ka hiteny hoe: “ny sakafonay ihany no hohaninay, ary ny akanjonay ihany no hanaovanay, fa mba avelao fotsiny izahay hantsoina amin’ny anaranao, mba tsy ho afa-baraka intsony.”'),
  ('6ab25b678b06166ab7a22d9f', '2026-09-22T10:41:43.411Z', '2026-09-22T10:41:43.411Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 4, 6, 'Ary hisy trano rantsankazo hanalokaloka amin’ny hafanana migaingaina mandritra ny andro, sady ho fialofana sy fiarovana amin’ny oram-baratra sy ny ranonorana.', 'ary hisy trano rantsankazo hanalokaloka amin’ny hafanana migaingaina mandritra ny andro, sady ho fialofana sy fiarovana amin’ny oram-baratra sy ny ranonorana.'),
  ('6ab25b678b06166ab7a22d9d', '2026-09-22T10:41:43.411Z', '2026-09-22T10:41:43.411Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 4, 4, 'Ho tezitra be amin’i Jerosalema i Jehovah ka hotsarainy ny zanakavavin’i Ziona. Izany no fomba hanasany azy ho afaka amin’ny lotony sy hanadiovany azy ho afaka amin’ny ra nalatsaka tao.', 'ho tezitra be amin’i jerosalema i jehovah ka hotsarainy ny zanakavavin’i ziona. izany no fomba hanasany azy ho afaka amin’ny lotony sy hanadiovany azy ho afaka amin’ny ra nalatsaka tao.'),
  ('6ab25b678b06166ab7a22d9c', '2026-09-22T10:41:43.411Z', '2026-09-22T10:41:43.411Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 4, 3, 'Ary hantsoina hoe masina izay sisa tavela ao Ziona sy izay sisa tafajanona ao Jerosalema, izany hoe izay rehetra ao Jerosalema ka voasoratra anarana hoe mbola velona.', 'ary hantsoina hoe masina izay sisa tavela ao ziona sy izay sisa tafajanona ao jerosalema, izany hoe izay rehetra ao jerosalema ka voasoratra anarana hoe mbola velona.'),
  ('6ab25b715e0bc3f00355dca9', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 10, 'Dia hisainareo ny trano ao Jerosalema, ka harodanareo mba hanamafisana an’ilay manda.', 'dia hisainareo ny trano ao jerosalema, ka harodanareo mba hanamafisana an’ilay manda.'),
  ('6ab25b715e0bc3f00355dca5', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 6, 'Raisin’i Elama ny tranon-jana-tsipìka, Ary iny izy fa mitaingina kalesin’ady tarihin’ny soavaly. Dia esorin’i Kira ny saron’ny ampinga.', 'raisin’i elama ny tranon-jana-tsipìka, ary iny izy fa mitaingina kalesin’ady tarihin’ny soavaly. dia esorin’i kira ny saron’ny ampinga.'),
  ('6ab25b715e0bc3f00355dcb4', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 21, 'Hampanaoviko azy ny akanjom-boninahitrao, dia hafatotro tsara aminy ny fehikibo lamba nanaovanao, ary hatolotro eo am-pelatanany ny fahefanao. Ary ho rain’ny mponin’i Jerosalema sy ny taranak’i Joda izy.', 'hampanaoviko azy ny akanjom-boninahitrao, dia hafatotro tsara aminy ny fehikibo lamba nanaovanao, ary hatolotro eo am-pelatanany ny fahefanao. ary ho rain’ny mponin’i jerosalema sy ny taranak’i joda izy.'),
  ('6ab25b715e0bc3f00355dcaa', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 11, 'Hanamboatra fanangonan-drano eo anelanelan’ny manda roa ianareo, mba hanangonana ny rano avy ao amin’ilay dobo taloha. Tsy mba hitodika any amin’Ilay Be Voninahitra Mpanao an’izany anefa ianareo, sady tsy mba hijery an’Ilay namorona an’izany taloha ela be.', 'hanamboatra fanangonan-drano eo anelanelan’ny manda roa ianareo, mba hanangonana ny rano avy ao amin’ilay dobo taloha. tsy mba hitodika any amin’ilay be voninahitra mpanao an’izany anefa ianareo, sady tsy mba hijery an’ilay namorona an’izany taloha ela be.'),
  ('6ab25b715e0bc3f00355dcb3', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 20, '“‘Amin’izany andro izany, dia hantsoiko i Eliakima mpanompoko, zanak’i Hilkia.', '“‘amin’izany andro izany, dia hantsoiko i eliakima mpanompoko, zanak’i hilkia.'),
  ('6ab25b715e0bc3f00355dca2', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 3, 'Niara-nandositra daholo ny mpitondra jadona teo aminao. Nosamborina izy ireo ka nogadraina, nefa tsy nampiasana tsipìka akory. Nentina hogadraina daholo izay tratra, Na dia efa nandositra lavitra be aza.', 'niara-nandositra daholo ny mpitondra jadona teo aminao. nosamborina izy ireo ka nogadraina, nefa tsy nampiasana tsipìka akory. nentina hogadraina daholo izay tratra, na dia efa nandositra lavitra be aza.'),
  ('6ab25b715e0bc3f00355dca1', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 2, 'Feno tabataba tao aminao, Ry tanàna mikotaba sy mirehareha! Tsy matin’ny sabatra ny olona ripaka tao aminao, Sady tsy maty tany an’ady.', 'feno tabataba tao aminao, ry tanàna mikotaba sy mirehareha! tsy matin’ny sabatra ny olona ripaka tao aminao, sady tsy maty tany an’ady.'),
  ('6ab25b715e0bc3f00355dcb2', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 19, 'Ary haongako hiala amin’ny toeranao ianao, dia hesoriko amin’ny andraikitrao.', 'ary haongako hiala amin’ny toeranao ianao, dia hesoriko amin’ny andraikitrao.'),
  ('6ab25b715e0bc3f00355dca0', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 1, 'Ny fanambarana momba ny Lohasahan’ny Fahitana: Fa inona ity manjo anao no miakatra eny an-tampon-trano daholo ny olona ao aminao?', 'ny fanambarana momba ny lohasahan’ny fahitana: fa inona ity manjo anao no miakatra eny an-tampon-trano daholo ny olona ao aminao?'),
  ('6ab25b715e0bc3f00355dcae', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 15, 'Hoy i Jehovah Tompon’ny tafika, ilay Tompo Fara Tampony: “Mankanesa ao amin’io Sebna mpiandraikitra ny trano io, ka ilazao izy hoe:', 'hoy i jehovah tompon’ny tafika, ilay tompo fara tampony: “mankanesa ao amin’io sebna mpiandraikitra ny trano io, ka ilazao izy hoe:'),
  ('6ab25b715e0bc3f00355dca3', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 4, 'Izany no antony nilazako hoe: “Aza mijery ahy intsony. Hitomany aho fa malahelo be. Dia aza misisika hampionona ahy, Amin’izao fandringanana ny zanakavavin’ny fireneko izao.', 'izany no antony nilazako hoe: “aza mijery ahy intsony. hitomany aho fa malahelo be. dia aza misisika hampionona ahy, amin’izao fandringanana ny zanakavavin’ny fireneko izao.'),
  ('6ab25b715e0bc3f00355dcb7', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 24, 'Dia hahantona eo aminy daholo ny voninahitry ny ankohonan-drainy: Ny taranaka fara aman-dimby, ny fitaovana madinika rehetra, ny vilia baolina, ary ny siny lehibe rehetra.', 'dia hahantona eo aminy daholo ny voninahitry ny ankohonan-drainy: ny taranaka fara aman-dimby, ny fitaovana madinika rehetra, ny vilia baolina, ary ny siny lehibe rehetra.'),
  ('6ab25b715e0bc3f00355dcb6', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 23, 'Hataoko hoatran’ny fantsika fanantonan-javatra izay milentika eo amin’ny toerana mafy tsara izy, sady ho lasa toy ny seza fiandrianana be voninahitra ho an’ny ankohonan-drainy.', 'hataoko hoatran’ny fantsika fanantonan-javatra izay milentika eo amin’ny toerana mafy tsara izy, sady ho lasa toy ny seza fiandrianana be voninahitra ho an’ny ankohonan-drainy.'),
  ('6ab25b715e0bc3f00355dcb0', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 17, '‘Hobatain’i Jehovah anefa ianao, ralehilahy, dia hatsipiny mafy amin’ny tany.', '‘hobatain’i jehovah anefa ianao, ralehilahy, dia hatsipiny mafy amin’ny tany.'),
  ('6ab25b715e0bc3f00355dcac', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 13, 'Tsy izany anefa no ataonareo fa ilaozanareo manao fety sy mifalifaly, Mamono omby aman’ondry, Ary mihinan-kena sy misotro divay. Dia hoy ianareo: ‘Andao isika hihinana sy hisotro, fa rahampitso dia ho faty.’”', 'tsy izany anefa no ataonareo fa ilaozanareo manao fety sy mifalifaly, mamono omby aman’ondry, ary mihinan-kena sy misotro divay. dia hoy ianareo: ‘andao isika hihinana sy hisotro, fa rahampitso dia ho faty.’”'),
  ('6ab25b715e0bc3f00355dcb8', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 25, '“‘Amin’izany andro izany’, hoy i Jehovah Tompon’ny tafika, ‘dia hesorina ilay fantsika fanantonan-javatra efa nalentika teo amin’ny toerana mafy tsara. Hokapaina ilay fantsika ka hianjera. Dia hianjera daholo ny entana mihantona eo aminy ka ho potika, fa i Jehovah no efa niteny.’”', '“‘amin’izany andro izany’, hoy i jehovah tompon’ny tafika, ‘dia hesorina ilay fantsika fanantonan-javatra efa nalentika teo amin’ny toerana mafy tsara. hokapaina ilay fantsika ka hianjera. dia hianjera daholo ny entana mihantona eo aminy ka ho potika, fa i jehovah no efa niteny.’”'),
  ('6ab25b715e0bc3f00355dca6', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 7, 'Ho lasa feno kalesy fitondra miady Eny amin’ny lohasaha tsara indrindra eo aminao. Ary haka ny toerany eny am-bavahady ny soavaly.', 'ho lasa feno kalesy fitondra miady eny amin’ny lohasaha tsara indrindra eo aminao. ary haka ny toerany eny am-bavahady ny soavaly.'),
  ('6ab25b715e0bc3f00355dcab', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 12, 'Amin’izany andro izany, dia izao no hasaina hataonareo, araka ny baikon’i Jehovah Tompon’ny tafika, ilay Tompo Fara Tampony: Mila mitomany sy misaona ianareo, Ary mila manasola loha sy mitafy lamba gony.', 'amin’izany andro izany, dia izao no hasaina hataonareo, araka ny baikon’i jehovah tompon’ny tafika, ilay tompo fara tampony: mila mitomany sy misaona ianareo, ary mila manasola loha sy mitafy lamba gony.'),
  ('6ab25b715e0bc3f00355dca8', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 9, 'Dia ho hitanareo fa misy triatra be dia be ny mandan’ny Tanànan’i Davida. Hanangona rano ao amin’ny dobo ambany koa ianareo.', 'dia ho hitanareo fa misy triatra be dia be ny mandan’ny tanànan’i davida. hanangona rano ao amin’ny dobo ambany koa ianareo.'),
  ('6ab25b715e0bc3f00355dca4', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 5, 'Fa andron’ny sahotaka sy ny faharesena ary ny tahotra izany, Ary i Jehovah Tompon’ny tafika, ilay Tompo Fara Tampony, no mahatonga an’izany, Ao amin’ilay Lohasahan’ny Fahitana. Misy mandrodana ny manda, Ary misy antsoantso heno hatrany an-tendrombohitra.', 'fa andron’ny sahotaka sy ny faharesena ary ny tahotra izany, ary i jehovah tompon’ny tafika, ilay tompo fara tampony, no mahatonga an’izany, ao amin’ilay lohasahan’ny fahitana. misy mandrodana ny manda, ary misy antsoantso heno hatrany an-tendrombohitra.'),
  ('6ab25b715e0bc3f00355dcad', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 14, 'Ary henoko ny feon’i Jehovah Tompon’ny tafika niteny hoe: “‘Tsy hisy fandrakofam-pahotana ho anareo amin’izany fahadisoanareo izany, mandra-pahafatinareo’, hoy i Jehovah Tompon’ny tafika, ilay Tompo Fara Tampony.”', 'ary henoko ny feon’i jehovah tompon’ny tafika niteny hoe: “‘tsy hisy fandrakofam-pahotana ho anareo amin’izany fahadisoanareo izany, mandra-pahafatinareo’, hoy i jehovah tompon’ny tafika, ilay tompo fara tampony.”'),
  ('6ab25b715e0bc3f00355dcaf', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 16, '‘Misy anjaranao angaha eto? Fa iza no manome alalana anao handavaka fasana eto?’ Mandavaka ny fasany eny amin’ny toerana avo mantsy izy, ary mandavaka toerana fialan-tsasatra ho azy eny amin’ny harambato.', '‘misy anjaranao angaha eto? fa iza no manome alalana anao handavaka fasana eto?’ mandavaka ny fasany eny amin’ny toerana avo mantsy izy, ary mandavaka toerana fialan-tsasatra ho azy eny amin’ny harambato.'),
  ('6ab25b715e0bc3f00355dcb5', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 22, 'Hapetrako eo an-tsorony koa ny lakilen’ny taranak’i Davida. Izay hosokafany dia tsy hisy hanidy, ary izay hohidiany tsy hisy hanokatra.', 'hapetrako eo an-tsorony koa ny lakilen’ny taranak’i davida. izay hosokafany dia tsy hisy hanidy, ary izay hohidiany tsy hisy hanokatra.'),
  ('6ab25b715e0bc3f00355dcb1', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 18, 'Hahorongorony mafy be ianao, ka hatsipiny hoatran’ny baolina eny amin’ny tany malalaka. Dia any ianao no ho faty, ary ho any koa ny kalesinao mirenty be, ka ho afa-baraka ny ankohonan’ny tomponao.', 'hahorongorony mafy be ianao, ka hatsipiny hoatran’ny baolina eny amin’ny tany malalaka. dia any ianao no ho faty, ary ho any koa ny kalesinao mirenty be, ka ho afa-baraka ny ankohonan’ny tomponao.'),
  ('6ab25b715e0bc3f00355dca7', '2026-09-22T10:41:53.073Z', '2026-09-22T10:41:53.073Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 22, 8, 'Hesorina koa ny zavatra miaro an’i Joda. “Amin’izany andro izany, dia hitodika any amin’ny fitehirizam-piadiana ao amin’ny Trano Alan’i Libàna ianao.', 'hesorina koa ny zavatra miaro an’i joda. “amin’izany andro izany, dia hitodika any amin’ny fitehirizam-piadiana ao amin’ny trano alan’i libàna ianao.'),
  ('6ab25b72d1ed0d1ad582ea2d', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 6, 'Hanao fanasambe ho an’ny firenena rehetra i Jehovah Tompon’ny tafika, eto amin’ity tendrombohitra ity, Dia fanasambe misy hanim-pito loha, Fanasambe misy divay tena tsara, Sy hanim-pito loha sady be tsoka, Ary divay tena tsara efa notantavanina.', 'hanao fanasambe ho an’ny firenena rehetra i jehovah tompon’ny tafika, eto amin’ity tendrombohitra ity, dia fanasambe misy hanim-pito loha, fanasambe misy divay tena tsara, sy hanim-pito loha sady be tsoka, ary divay tena tsara efa notantavanina.'),
  ('6ab25b72d1ed0d1ad582ea2c', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 5, 'Toy ny hafanana migaingaina any amin’ny tany karakaina, Dia ataonao mangina ny tabataban’ny vahiny. Hoatran’ny hafanana mihamalefaka rehefa tratry ny aloky ny rahona, Dia ampanginina koa ny hiran’ny mpanjakazaka.', 'toy ny hafanana migaingaina any amin’ny tany karakaina, dia ataonao mangina ny tabataban’ny vahiny. hoatran’ny hafanana mihamalefaka rehefa tratry ny aloky ny rahona, dia ampanginina koa ny hiran’ny mpanjakazaka.'),
  ('6ab25b72d1ed0d1ad582ea31', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 10, 'Fa hiaro an’ity tendrombohitra ity ny tanan’i Jehovah. Dia hohitsakitsahina ao amin’ny taniny ihany i Moaba, Hoatran’ny mololo hitsakitsahina ao anaty zezika.', 'fa hiaro an’ity tendrombohitra ity ny tanan’i jehovah. dia hohitsakitsahina ao amin’ny taniny ihany i moaba, hoatran’ny mololo hitsakitsahina ao anaty zezika.'),
  ('6ab25b72d1ed0d1ad582ea30', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 9, 'Amin’izany andro izany, dia hiteny izy ireo hoe: “Izy no Andriamanitsika! Manantena azy isika, Dia hamonjy antsika izy. Izy no Jehovah, Ary manantena azy isika. Andao isika hifaly sy hiravoravo satria mamonjy antsika izy.”', 'amin’izany andro izany, dia hiteny izy ireo hoe: “izy no andriamanitsika! manantena azy isika, dia hamonjy antsika izy. izy no jehovah, ary manantena azy isika. andao isika hifaly sy hiravoravo satria mamonjy antsika izy.”'),
  ('6ab25b72d1ed0d1ad582ea2e', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 7, 'Hesoriny eto amin’ity tendrombohitra ity ny lamba manarona ny vahoaka rehetra, Sy ny lamba voatenona mandrakotra ny firenena rehetra.', 'hesoriny eto amin’ity tendrombohitra ity ny lamba manarona ny vahoaka rehetra, sy ny lamba voatenona mandrakotra ny firenena rehetra.'),
  ('6ab25b72d1ed0d1ad582ea2a', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 3, 'Hanome voninahitra anao àry ny vahoaka matanjaka, Dia hatahotra anao ny tanànan’ireo firenena mpanjakazaka.', 'hanome voninahitra anao àry ny vahoaka matanjaka, dia hatahotra anao ny tanànan’ireo firenena mpanjakazaka.'),
  ('6ab25b72d1ed0d1ad582ea33', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 12, 'Dia harodany ilay tanàna voaro mafy Sy ny manda fiarovany avo be. Hazerany amin’ny tany, eo amin’ny vovoka, izany.', 'dia harodany ilay tanàna voaro mafy sy ny manda fiarovany avo be. hazerany amin’ny tany, eo amin’ny vovoka, izany.'),
  ('6ab25b72d1ed0d1ad582ea2f', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 8, 'Hofoanany tsy hisy mandrakizay ny fahafatesana, Ary hofafan’i Jehovah Tompo Fara Tampony ny ranomaso amin’ny tarehy rehetra. Hataony tsy afa-baraka intsony ny vahoakany, na aiza na aiza eran-tany, Fa i Jehovah no efa niteny an’izany.', 'hofoanany tsy hisy mandrakizay ny fahafatesana, ary hofafan’i jehovah tompo fara tampony ny ranomaso amin’ny tarehy rehetra. hataony tsy afa-baraka intsony ny vahoakany, na aiza na aiza eran-tany, fa i jehovah no efa niteny an’izany.'),
  ('6ab25b72d1ed0d1ad582ea29', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 2, 'Fa nataonao lasa korontam-bato ny tanàna, Ary lasa zavatra efa ravarava sisa ny tanàna voaro mafy. Tsy tanàna intsony ilay tilikambo fonenan’ny vahiny, Ary tsy haorina intsony koa.', 'fa nataonao lasa korontam-bato ny tanàna, ary lasa zavatra efa ravarava sisa ny tanàna voaro mafy. tsy tanàna intsony ilay tilikambo fonenan’ny vahiny, ary tsy haorina intsony koa.'),
  ('6ab25b72d1ed0d1ad582ea28', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 1, 'Ianao no Andriamanitro, Jehovah ô! Mankalaza anao aho ary midera ny anaranao. Fa nanao zava-mahagaga be dia be ianao, Dia zavatra efa nokasainao hatramin’ny taloha ela be, Satria tsy mivadika ianao sady mendri-pitokisana foana.', 'ianao no andriamanitro, jehovah ô! mankalaza anao aho ary midera ny anaranao. fa nanao zava-mahagaga be dia be ianao, dia zavatra efa nokasainao hatramin’ny taloha ela be, satria tsy mivadika ianao sady mendri-pitokisana foana.'),
  ('6ab25b72d1ed0d1ad582ea2b', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 4, 'Lasa manda fiarovana ho an’ny madinika mantsy ianao, Fiarovana mafy ho an’ny mahantra mijaly, Fialofana amin’ny oram-baratra, Ary alokaloka amin’ny hafanana. Rehefa mamely hoatran’ny oram-baratra mifafy amin’ny manda ny mpanjakazaka,', 'lasa manda fiarovana ho an’ny madinika mantsy ianao, fiarovana mafy ho an’ny mahantra mijaly, fialofana amin’ny oram-baratra, ary alokaloka amin’ny hafanana. rehefa mamely hoatran’ny oram-baratra mifafy amin’ny manda ny mpanjakazaka,'),
  ('6ab25b72d1ed0d1ad582ea32', '2026-09-22T10:41:54.336Z', '2026-09-22T10:41:54.336Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 25, 11, 'Hikapoka azy ny tanany, Toy ny ataon’ny mpilomano mikapoka rano amin’ny tanany rehefa milomano. Haetriny i Moaba fa mirehareha loatra, Ka mailaka erỳ izy hikapoka azy amin’ny tanany.', 'hikapoka azy ny tanany, toy ny ataon’ny mpilomano mikapoka rano amin’ny tanany rehefa milomano. haetriny i moaba fa mirehareha loatra, ka mailaka erỳ izy hikapoka azy amin’ny tanany.'),
  ('6ab25b73f9daa4a0564a92ac', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 16, 'Jehovah ô, nitodika tany aminao izy ireo tao anatin’ny fahoriany. Namboraka ny tao am-pony izy ireo rehefa nibitsibitsika nivavaka, tamin’izy nofaizinao.', 'jehovah ô, nitodika tany aminao izy ireo tao anatin’ny fahoriany. namboraka ny tao am-pony izy ireo rehefa nibitsibitsika nivavaka, tamin’izy nofaizinao.'),
  ('6ab25b73f9daa4a0564a92a4', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 8, 'Jehovah ô, manaraka ny lalana atoronao izahay, Ka ianao no antenainay. Tena sarobidy aminay ny anaranao ka tianay raha hotsarovana foana.', 'jehovah ô, manaraka ny lalana atoronao izahay, ka ianao no antenainay. tena sarobidy aminay ny anaranao ka tianay raha hotsarovana foana.'),
  ('6ab25b73f9daa4a0564a92b1', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 21, 'Fa mivoaka avy any amin’ny toerany i Jehovah, Mba hanao ampamoaka ny mponina ao amin’ilay tany, noho ny fahadisoana nataon’izy ireo. Dia hasehon’ilay tany ny ra nalatsak’ilay tanàna, Ary tsy hafeniny intsony ireo novonoina tao.”', 'fa mivoaka avy any amin’ny toerany i jehovah, mba hanao ampamoaka ny mponina ao amin’ilay tany, noho ny fahadisoana nataon’izy ireo. dia hasehon’ilay tany ny ra nalatsak’ilay tanàna, ary tsy hafeniny intsony ireo novonoina tao.”'),
  ('6ab25b73f9daa4a0564a929f', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 3, 'Harovanao izay miantehitra tanteraka aminao. Hampiadaninao foana izy ireo, Satria ianao no itokisany.', 'harovanao izay miantehitra tanteraka aminao. hampiadaninao foana izy ireo, satria ianao no itokisany.'),
  ('6ab25b73f9daa4a0564a92a1', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 5, 'Fa aetriny izay mipetraka eny amin’ny toerana ambony, eny amin’ny tanàna avo. Azerany koa ilay tanàna, Azerany amin’ny tany, Dia atsipiny eny amin’ny vovoka.', 'fa aetriny izay mipetraka eny amin’ny toerana ambony, eny amin’ny tanàna avo. azerany koa ilay tanàna, azerany amin’ny tany, dia atsipiny eny amin’ny vovoka.'),
  ('6ab25b73f9daa4a0564a929d', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 1, 'Amin’izany andro izany, dia hohiraina eto Joda izao hira izao: “Manana tanàna matanjaka isika. Famonjena no ataony toy ny manda sy dongon-tany fiarovana an’ilay tanàna.', 'amin’izany andro izany, dia hohiraina eto joda izao hira izao: “manana tanàna matanjaka isika. famonjena no ataony toy ny manda sy dongon-tany fiarovana an’ilay tanàna.'),
  ('6ab25b73f9daa4a0564a92a7', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 11, 'Ingainao ny tananao, Jehovah ô, nefa tsy jeren’izy ireo akory. Ho hitany fa mafana fo ho an’ny vahoakanao ianao, ka ho menatra izy ireo. Ary handevona azy ny afo natokana ho an’ny fahavalonao.', 'ingainao ny tananao, jehovah ô, nefa tsy jeren’izy ireo akory. ho hitany fa mafana fo ho an’ny vahoakanao ianao, ka ho menatra izy ireo. ary handevona azy ny afo natokana ho an’ny fahavalonao.'),
  ('6ab25b73f9daa4a0564a92a0', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 4, 'Matokia an’i Jehovah mandrakizay, Fa i Jah Jehovah no Vatolampy mandrakizay.', 'matokia an’i jehovah mandrakizay, fa i jah jehovah no vatolampy mandrakizay.'),
  ('6ab25b73f9daa4a0564a92b0', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 20, 'Mandehana miditra ao amin’ny efitranonareo anatiny, ry vahoakako, Dia hidio ny varavarana. Miafena kely vetivety, Mandra-pahalasan’ny fahatezerana.', 'mandehana miditra ao amin’ny efitranonareo anatiny, ry vahoakako, dia hidio ny varavarana. miafena kely vetivety, mandra-pahalasan’ny fahatezerana.'),
  ('6ab25b73f9daa4a0564a92a9', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 13, 'Jehovah Andriamanitray ô, misy tompo hafa ankoatra anao lasa mifehy anay. Ny anaranao ihany anefa no derainay.', 'jehovah andriamanitray ô, misy tompo hafa ankoatra anao lasa mifehy anay. ny anaranao ihany anefa no derainay.'),
  ('6ab25b73f9daa4a0564a92a8', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 12, 'Hanome anay fiadanana ianao, Jehovah ô, Satria izay rehetra ataonay, Dia noho ianao no ahavitanay an’izany.', 'hanome anay fiadanana ianao, jehovah ô, satria izay rehetra ataonay, dia noho ianao no ahavitanay an’izany.'),
  ('6ab25b73f9daa4a0564a92aa', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 14, 'Maty izy ireo ka tsy ho velona intsony. Maty tsy mahavita na inona na inona izy ireo ka tsy hitsangana intsony. Fa nitsara azy ireo ianao, Mba handringana azy ka tsy horesahina intsony ny momba azy.', 'maty izy ireo ka tsy ho velona intsony. maty tsy mahavita na inona na inona izy ireo ka tsy hitsangana intsony. fa nitsara azy ireo ianao, mba handringana azy ka tsy horesahina intsony ny momba azy.'),
  ('6ab25b73f9daa4a0564a92a3', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 7, 'Mahitsy ny lalan’ny olo-marina. Mahitsy ianao, Ka hataonao mitovy tantana ny lalan’ny olo-marina.', 'mahitsy ny lalan’ny olo-marina. mahitsy ianao, ka hataonao mitovy tantana ny lalan’ny olo-marina.'),
  ('6ab25b73f9daa4a0564a929e', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 2, 'Vohay ny vavahady mba hidiran’ilay firenena marina, Dia firenena mendri-pitokisana.', 'vohay ny vavahady mba hidiran’ilay firenena marina, dia firenena mendri-pitokisana.'),
  ('6ab25b73f9daa4a0564a92ab', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 15, 'Nataonao lasa be dia be ny mponina ao amin’ilay firenena, Jehovah ô. Nataonao lasa be dia be tokoa ny mponina ao. Nomenao voninahitra ny tenanao, Ary nitarinao be ny sisin’ilay tany manontolo.', 'nataonao lasa be dia be ny mponina ao amin’ilay firenena, jehovah ô. nataonao lasa be dia be tokoa ny mponina ao. nomenao voninahitra ny tenanao, ary nitarinao be ny sisin’ilay tany manontolo.'),
  ('6ab25b73f9daa4a0564a92a6', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 10, 'Na dia iantrana aza ny ratsy fanahy, Dia tsy hianatra fahamarinana. Ary na dia ao amin’ny tanin’ny fahitsiana aza izy, dia hanao ratsy ihany, Ka tsy hahita ny voninahitr’i Jehovah.', 'na dia iantrana aza ny ratsy fanahy, dia tsy hianatra fahamarinana. ary na dia ao amin’ny tanin’ny fahitsiana aza izy, dia hanao ratsy ihany, ka tsy hahita ny voninahitr’i jehovah.'),
  ('6ab25b73f9daa4a0564a92ae', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 18, 'Bevohoka izahay, ary nihetsi-jaza, Kanefa hoatran’ny hoe niteraka rivotra. Tsy nahavonjy an’ilay tany izahay, Ary tsy nisy zaza teraka mba hipetraka ao amin’ilay tany.', 'bevohoka izahay, ary nihetsi-jaza, kanefa hoatran’ny hoe niteraka rivotra. tsy nahavonjy an’ilay tany izahay, ary tsy nisy zaza teraka mba hipetraka ao amin’ilay tany.'),
  ('6ab25b73f9daa4a0564a92a5', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 9, 'Maniry anao amin’ny foko manontolo aho amin’ny alina, Ary mitady anao mafy aho, ao anatiko lalina ao. Rehefa mitsara ny tany mantsy ianao, Dia hianatra momba ny fahamarinana ny mponina ao amin’ilay tany.', 'maniry anao amin’ny foko manontolo aho amin’ny alina, ary mitady anao mafy aho, ao anatiko lalina ao. rehefa mitsara ny tany mantsy ianao, dia hianatra momba ny fahamarinana ny mponina ao amin’ilay tany.'),
  ('6ab25b73f9daa4a0564a92ad', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 17, 'Toy ny vehivavy bevohoka efa ho teraka, Ka mihetsi-jaza sady mitaraina fa manaintaina, Dia hoatr’izany izahay noho ny aminao, Jehovah ô!', 'toy ny vehivavy bevohoka efa ho teraka, ka mihetsi-jaza sady mitaraina fa manaintaina, dia hoatr’izany izahay noho ny aminao, jehovah ô!'),
  ('6ab25b73f9daa4a0564a92af', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 19, '“Ho velona ny olonao efa maty. Hitsangana ny fatin’ny vahoakako. Mifohaza ka mihobia, Ianareo izay mipetraka ao anaty vovoka! Fa ny andonao dia ho toy ny andon’ny maraina, Ary havelan’ny tany ho velona indray ny maty tsy mahavita na inona na inona.', '“ho velona ny olonao efa maty. hitsangana ny fatin’ny vahoakako. mifohaza ka mihobia, ianareo izay mipetraka ao anaty vovoka! fa ny andonao dia ho toy ny andon’ny maraina, ary havelan’ny tany ho velona indray ny maty tsy mahavita na inona na inona.'),
  ('6ab25b73f9daa4a0564a92a2', '2026-09-22T10:41:55.459Z', '2026-09-22T10:41:55.459Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 26, 6, 'Hanitsakitsaka an’ilay tanàna Ny tongotry ny ampijalina sy ny faladian’ny madinika.”', 'hanitsakitsaka an’ilay tanàna ny tongotry ny ampijalina sy ny faladian’ny madinika.”'),
  ('6ab25b733bbc390c36fb0b9d', '2026-09-22T10:41:55.921Z', '2026-09-22T10:41:55.921Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 3, 'Izaho, Jehovah, no miaro azy. Hanondraka azy amin’ny fotoana rehetra aho. Dia harovako andro aman’alina izy, Mba tsy hisy hanimba.', 'izaho, jehovah, no miaro azy. hanondraka azy amin’ny fotoana rehetra aho. dia harovako andro aman’alina izy, mba tsy hisy hanimba.'),
  ('6ab25b733bbc390c36fb0b9e', '2026-09-22T10:41:55.921Z', '2026-09-22T10:41:55.921Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 4, 'Tsy tezitra intsony aho. Raha misy fahavalo misakana ny lalako amin’ny tsilo sy ahidratsy, Dia hohitsakitsahiko ireny, ary hataoko indray mandoro.', 'tsy tezitra intsony aho. raha misy fahavalo misakana ny lalako amin’ny tsilo sy ahidratsy, dia hohitsakitsahiko ireny, ary hataoko indray mandoro.'),
  ('6ab25b733bbc390c36fb0b9c', '2026-09-22T10:41:55.921Z', '2026-09-22T10:41:55.921Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 2, 'Amin’izany andro izany, dia mihirà ho azy, hoe: “Tanimboaloboka mamokatra divay mandroatra!', 'amin’izany andro izany, dia mihirà ho azy, hoe: “tanimboaloboka mamokatra divay mandroatra!'),
  ('6ab25b733bbc390c36fb0b9b', '2026-09-22T10:41:55.921Z', '2026-09-22T10:41:55.921Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 1, 'Amin’izany andro izany, dia hampiasain’i Jehovah ny sabany maranitra sy lehibe ary mafy, Ka hofaiziny ny Leviatana, ilay bibilava mitsoriaka. Hofaiziny ny Leviatana, ilay bibilava miolanolana, Ary hovonoiny ilay biby ngezabe any an-dranomasina.', 'amin’izany andro izany, dia hampiasain’i jehovah ny sabany maranitra sy lehibe ary mafy, ka hofaiziny ny leviatana, ilay bibilava mitsoriaka. hofaiziny ny leviatana, ilay bibilava miolanolana, ary hovonoiny ilay biby ngezabe any an-dranomasina.'),
  ('6ab25b733bbc390c36fb0ba7', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 13, 'Ary hisy anjombona lehibe hotsofina, amin’izany andro izany. Dia ho tonga izay efa ho faty any Asyria sy izay miparitaka any Ejipta, ka hiankohoka eo anatrehan’i Jehovah eo amin’ny tendrombohitra masina any Jerosalema.', 'ary hisy anjombona lehibe hotsofina, amin’izany andro izany. dia ho tonga izay efa ho faty any asyria sy izay miparitaka any ejipta, ka hiankohoka eo anatrehan’i jehovah eo amin’ny tendrombohitra masina any jerosalema.'),
  ('6ab25b733bbc390c36fb0ba4', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 10, 'Fa hiala ao amin’ilay tanàna voaro mafy ny mponina rehetra ao, Ary ho hadino sy hilaozana toy ny tany efitra ny kijana. Any ny zanak’omby no hiraoka ahitra sy hatory, Ary hihinana sampan-kazo.', 'fa hiala ao amin’ilay tanàna voaro mafy ny mponina rehetra ao, ary ho hadino sy hilaozana toy ny tany efitra ny kijana. any ny zanak’omby no hiraoka ahitra sy hatory, ary hihinana sampan-kazo.'),
  ('6ab25b733bbc390c36fb0ba1', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 7, 'Tsy maintsy hokapohina hoatran’ny ikapohan’ilay mikapoka azy ve izy? Sa izy tsy maintsy hovonoina hoatran’ny nandripahana an’ireo novonoina teo aminy?', 'tsy maintsy hokapohina hoatran’ny ikapohan’ilay mikapoka azy ve izy? sa izy tsy maintsy hovonoina hoatran’ny nandripahana an’ireo novonoina teo aminy?'),
  ('6ab25b733bbc390c36fb0ba5', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 11, 'Rehefa maina ireo rantsany kely, Dia ho tonga hanapaka an’ireny ny vehivavy Mba hataony kitay. Fa tsy misaina ity vahoaka ity, Ka tsy hamindra fo aminy ny Mpanao azy, Ary tsy hiantra azy ny Mpamolavola azy.', 'rehefa maina ireo rantsany kely, dia ho tonga hanapaka an’ireny ny vehivavy mba hataony kitay. fa tsy misaina ity vahoaka ity, ka tsy hamindra fo aminy ny mpanao azy, ary tsy hiantra azy ny mpamolavola azy.'),
  ('6ab25b733bbc390c36fb0ba2', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 8, 'Hiady aminy ianao sady hanao kiakiaka mampahatahotra rehefa mandroaka azy. Horoahinao amin’ny rivotra mifofofofo mafy avy aminao izy, amin’ny andro isian’ny rivotra avy any atsinanana.', 'hiady aminy ianao sady hanao kiakiaka mampahatahotra rehefa mandroaka azy. horoahinao amin’ny rivotra mifofofofo mafy avy aminao izy, amin’ny andro isian’ny rivotra avy any atsinanana.'),
  ('6ab25b733bbc390c36fb0ba6', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 12, 'Amin’izany andro izany, dia hahintsan’i Jehovah ny voankazo, hatrany amin’ny rano mikoriana avy any amin’ny Renirano ka hatrany amin’ny Reniranon’i Ejipta. Dia hangonina tsirairay ianareo, ry vahoakan’Israely.', 'amin’izany andro izany, dia hahintsan’i jehovah ny voankazo, hatrany amin’ny rano mikoriana avy any amin’ny renirano ka hatrany amin’ny reniranon’i ejipta. dia hangonina tsirairay ianareo, ry vahoakan’israely.'),
  ('6ab25b733bbc390c36fb0ba0', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 6, 'Amin’ny andro ho avy, dia hisy fakany i Jakoba, Ary hamony sy hitsimoka i Israely. Dia hofenoin’izy ireo vokatra ilay tany.', 'amin’ny andro ho avy, dia hisy fakany i jakoba, ary hamony sy hitsimoka i israely. dia hofenoin’izy ireo vokatra ilay tany.'),
  ('6ab25b733bbc390c36fb0ba3', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 9, 'Hoatr’izao àry no handrakofana ny fahadisoan’i Jakoba, Ary izao no ho vokany rehefa esorina ny fahotany: Hataony toy ny vatosokay nopotipotehina Ny vato rehetra eo amin’ny alitara, Ary tsy hisy tsato-kazo masina na fandoroana emboka manitra ho tavela intsony.', 'hoatr’izao àry no handrakofana ny fahadisoan’i jakoba, ary izao no ho vokany rehefa esorina ny fahotany: hataony toy ny vatosokay nopotipotehina ny vato rehetra eo amin’ny alitara, ary tsy hisy tsato-kazo masina na fandoroana emboka manitra ho tavela intsony.'),
  ('6ab25b733bbc390c36fb0b9f', '2026-09-22T10:41:55.922Z', '2026-09-22T10:41:55.922Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 27, 5, 'Raha tsy izany, dia tokony hifikitra amin’ilay fiarovana mafy omeko izy. Tokony hitady fihavanana amiko izy, Ary hitady ahy mba hihavana izahay.”', 'raha tsy izany, dia tokony hifikitra amin’ilay fiarovana mafy omeko izy. tokony hitady fihavanana amiko izy, ary hitady ahy mba hihavana izahay.”'),
  ('6ab25b75f879c900b9a780c2', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 30, 'Hataon’i Jehovah heno ny feony matanjaka be, Ary hasehony ny sandriny ka hakapony mafy ny tanany rehefa tezitra be izy. Hisy afo mandevona rehefa manao an’izany izy, Sady hisy oram-be mivatravatra sy oram-baratra ary havandra.', 'hataon’i jehovah heno ny feony matanjaka be, ary hasehony ny sandriny ka hakapony mafy ny tanany rehefa tezitra be izy. hisy afo mandevona rehefa manao an’izany izy, sady hisy oram-be mivatravatra sy oram-baratra ary havandra.'),
  ('6ab25b75f879c900b9a780c0', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 28, 'Toy ny riaka be tafakatra hatreny amin’ny hatoka ny fanahiny, Mba hanozongozona an’ireo firenena ao anaty sivana, ka ho ringana daholo izy ireo. Ary hasiana lamboridy ny valanoranon’ny vahoaka ka ho diso lalana izy ireo.', 'toy ny riaka be tafakatra hatreny amin’ny hatoka ny fanahiny, mba hanozongozona an’ireo firenena ao anaty sivana, ka ho ringana daholo izy ireo. ary hasiana lamboridy ny valanoranon’ny vahoaka ka ho diso lalana izy ireo.'),
  ('6ab25b75f879c900b9a780bf', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 27, 'Tonga avy any lavitra ny anaran’i Jehovah. Tezitra be izy ary misy rahona matevina miaraka aminy. Feno hatezerana ny molony, Ary hoatran’ny afo mandoro ny lelany.', 'tonga avy any lavitra ny anaran’i jehovah. tezitra be izy ary misy rahona matevina miaraka aminy. feno hatezerana ny molony, ary hoatran’ny afo mandoro ny lelany.'),
  ('6ab25b75f879c900b9a780b9', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 21, 'Ary raha mivily miankavanana ianao na mivily miankavia, dia ny sofinao mihitsy no haheno teny avy ao aoriananao hoe: “Ity no lalana ka andehano.”', 'ary raha mivily miankavanana ianao na mivily miankavia, dia ny sofinao mihitsy no haheno teny avy ao aoriananao hoe: “ity no lalana ka andehano.”'),
  ('6ab25b75f879c900b9a780b0', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 12, 'Izao àry no tenin’Ilay Masin’ny Israely: “Tsy manaiky ny teniko ianareo, Fa lainga sy fitaka no itokisanareo, Sady ianteheranareo.', 'izao àry no tenin’ilay masin’ny israely: “tsy manaiky ny teniko ianareo, fa lainga sy fitaka no itokisanareo, sady ianteheranareo.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25b75f879c900b9a780ac', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 8, '“Mandehana àry, soraty eo amin’ny takela-kazo eo anatrehany izany, Ary soraty ao amin’ny boky, Mba ho azo atao vavolombelona eny foana, Amin’ny andro ho avy.', '“mandehana àry, soraty eo amin’ny takela-kazo eo anatrehany izany, ary soraty ao amin’ny boky, mba ho azo atao vavolombelona eny foana, amin’ny andro ho avy.'),
  ('6ab25b75f879c900b9a780c3', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 31, 'Fa hihorohoro i Asyria noho ny feon’i Jehovah. Hamely azy amin’ny tehina mantsy Izy.', 'fa hihorohoro i asyria noho ny feon’i jehovah. hamely azy amin’ny tehina mantsy izy.'),
  ('6ab25b75f879c900b9a780b3', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 15, 'Fa izao no tenin’i Jehovah Tompo Fara Tampony, Ilay Masin’ny Israely: “Ho voavonjy ianareo raha miverina amiko sy miezaka ho tony. Hatanjaka ianareo raha tony foana sy feno toky.” Tsy nety anefa ianareo,', 'fa izao no tenin’i jehovah tompo fara tampony, ilay masin’ny israely: “ho voavonjy ianareo raha miverina amiko sy miezaka ho tony. hatanjaka ianareo raha tony foana sy feno toky.” tsy nety anefa ianareo,'),
  ('6ab25b75f879c900b9a780aa', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 6, 'Ny fanamelohana an’ireo biby any atsimo: Mandeha mamakivaky ny tany misy fijaliana sy zava-tsarotra izy ireo, Dia tany misy liona, eny, liona mierona, Sy bibilava misy poizina, ary bibilava misidina. Eny an-damosin’ny ampondra no itondrany ny harenany, Ary eny amin’ny trafon’ny rameva no itondrany ny vatsiny. Tsy hitondra soa ho an’ny olona anefa ireny zavatra ireny.', 'ny fanamelohana an’ireo biby any atsimo: mandeha mamakivaky ny tany misy fijaliana sy zava-tsarotra izy ireo, dia tany misy liona, eny, liona mierona, sy bibilava misy poizina, ary bibilava misidina. eny an-damosin’ny ampondra no itondrany ny harenany, ary eny amin’ny trafon’ny rameva no itondrany ny vatsiny. tsy hitondra soa ho an’ny olona anefa ireny zavatra ireny.'),
  ('6ab25b75f879c900b9a780a8', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 4, 'Fa any Zoana ny andrianany, Ary tonga hatrany Hanesa ny olona nirahiny.', 'fa any zoana ny andrianany, ary tonga hatrany hanesa ny olona nirahiny.'),
  ('6ab25b75f879c900b9a780c1', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 29, 'Hanao hira kosa ianareo, hoatran’ny hira fanaonareo amin’ny alina, Rehefa miomana hanao fety. Ho falifaly ny fonareo, Ka amin’izay ianareo dia ho toy ny olona mitsoka sodina eny am-pandehanana Mankany an-tendrombohitr’i Jehovah, ho any amin’ilay Vatolampin’ny Israely.', 'hanao hira kosa ianareo, hoatran’ny hira fanaonareo amin’ny alina, rehefa miomana hanao fety. ho falifaly ny fonareo, ka amin’izay ianareo dia ho toy ny olona mitsoka sodina eny am-pandehanana mankany an-tendrombohitr’i jehovah, ho any amin’ilay vatolampin’ny israely.'),
  ('6ab25b75f879c900b9a780bd', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 25, 'Hisy rano mikoriana sy renirano eny amin’ny tendrombohitra avo rehetra sy ny havoana rehetra, amin’ilay andro handripahana olona be dia be, rehefa mianjera ny tilikambo.', 'hisy rano mikoriana sy renirano eny amin’ny tendrombohitra avo rehetra sy ny havoana rehetra, amin’ilay andro handripahana olona be dia be, rehefa mianjera ny tilikambo.'),
  ('6ab25b75f879c900b9a780ad', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 9, 'Fa vahoaka mpikomy izy ireo, ary zanaka mpamitaka, Dia zanaka tsy vonona hihaino ny lalàn’i Jehovah.', 'fa vahoaka mpikomy izy ireo, ary zanaka mpamitaka, dia zanaka tsy vonona hihaino ny lalàn’i jehovah.'),
  ('6ab25b75f879c900b9a780bb', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 23, 'Hanome ranonorana ho an’ny voa afafinao amin’ny tany Izy, ary sakafo tsara sy be dia be no ho vokatry ny tany. Hiraoka ahitra eny amin’ny kijana malalaka be ny biby fiompinao, amin’izany andro izany.', 'hanome ranonorana ho an’ny voa afafinao amin’ny tany izy, ary sakafo tsara sy be dia be no ho vokatry ny tany. hiraoka ahitra eny amin’ny kijana malalaka be ny biby fiompinao, amin’izany andro izany.'),
  ('6ab25b75f879c900b9a780b6', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 18, 'Mbola maharitra miandry foana anefa i Jehovah, satria te hiantra anareo, Ary hitsangana izy satria te hamindra fo aminareo. Andriamanitry ny rariny mantsy i Jehovah, Ka sambatra izay rehetra manantena azy.', 'mbola maharitra miandry foana anefa i jehovah, satria te hiantra anareo, ary hitsangana izy satria te hamindra fo aminareo. andriamanitry ny rariny mantsy i jehovah, ka sambatra izay rehetra manantena azy.'),
  ('6ab25b75f879c900b9a780bc', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 24, 'Ny omby sy ny ampondra izay miasa tany kosa hihinana vilona nafangaro kidiadiamborona, izay niara-nokororohina tamin’ny lapelina sy ny fitrebika.', 'ny omby sy ny ampondra izay miasa tany kosa hihinana vilona nafangaro kidiadiamborona, izay niara-nokororohina tamin’ny lapelina sy ny fitrebika.'),
  ('6ab25b75f879c900b9a780b7', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 19, 'Rehefa mipetraka ao Ziona, ao Jerosalema, ny olona, dia tsy hitomany intsony ianao. Hiantra anao tokoa Izy rehefa maheno anao miantso vonjy. Hamaly anao Izy raha vao maheno an’izany.', 'rehefa mipetraka ao ziona, ao jerosalema, ny olona, dia tsy hitomany intsony ianao. hiantra anao tokoa izy rehefa maheno anao miantso vonjy. hamaly anao izy raha vao maheno an’izany.'),
  ('6ab25b75f879c900b9a780b1', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 13, 'Ho toy ny manda mitresaka àry izany fahadisoanareo izany, Ary hoatran’ny manda avo be efa mibontsina ka mitady hianjera. Hirodana tampoka ao anatin’ny indray mipy maso ilay manda.', 'ho toy ny manda mitresaka àry izany fahadisoanareo izany, ary hoatran’ny manda avo be efa mibontsina ka mitady hianjera. hirodana tampoka ao anatin’ny indray mipy maso ilay manda.'),
  ('6ab25b75f879c900b9a780c4', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 32, 'Isaky ny mikapoka amin’ny tehiny i Jehovah Mba hanafaizana an’i Asyria, Dia hampiarahina amin’ny feon’ampongatapaka sy harpa izany. Hanambana azy ireo amin’ny tanany Izy amin’izay, ka hiady aminy.', 'isaky ny mikapoka amin’ny tehiny i jehovah mba hanafaizana an’i asyria, dia hampiarahina amin’ny feon’ampongatapaka sy harpa izany. hanambana azy ireo amin’ny tanany izy amin’izay, ka hiady aminy.'),
  ('6ab25b75f879c900b9a780b5', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 17, 'Olona iray fotsiny no mandrahona, dia hangovitra ny arivo. Olona dimy fotsiny no mandrahona, dia handositra ianareo, Ka izay sisa tavela aminareo dia ho toy ny andry tokana eny an-tampon-tendrombohitra, Sy ho toy ny tsato-kazo famantarana iray eny amin’ny havoana.', 'olona iray fotsiny no mandrahona, dia hangovitra ny arivo. olona dimy fotsiny no mandrahona, dia handositra ianareo, ka izay sisa tavela aminareo dia ho toy ny andry tokana eny an-tampon-tendrombohitra, sy ho toy ny tsato-kazo famantarana iray eny amin’ny havoana.'),
  ('6ab25b75f879c900b9a780b2', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 14, 'Hovakivakina toy ny siniben’ny mpanefy tanimanga izany, Dia ho potika tanteraka ka tsy hisy potiny ho tavela Mba hakana afo avy ao am-patana, Na hanovozana rano eny amin’ny ranom-potaka kely.”', 'hovakivakina toy ny siniben’ny mpanefy tanimanga izany, dia ho potika tanteraka ka tsy hisy potiny ho tavela mba hakana afo avy ao am-patana, na hanovozana rano eny amin’ny ranom-potaka kely.”'),
  ('6ab25b75f879c900b9a780a5', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 1, '“Hahita loza ireo zanaka mafy loha”, hoy i Jehovah, “Dia izay manatanteraka izay kasainy hatao, fa tsy izay kasaiko hatao, Sy manao fifanekena, nefa tsy notarihin’ny fanahiko, Ka vao mainka mitombo ny fahotany.', '“hahita loza ireo zanaka mafy loha”, hoy i jehovah, “dia izay manatanteraka izay kasainy hatao, fa tsy izay kasaiko hatao, sy manao fifanekena, nefa tsy notarihin’ny fanahiko, ka vao mainka mitombo ny fahotany.'),
  ('6ab25b75f879c900b9a780be', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 26, 'Ho toy ny hazavan’ny masoandro ny hazavan’ny volana fenomanana. Ary ho avo fito heny ny hazavan’ny masoandro, hoatran’ny hazavana fito andro, rehefa fonosin’i Jehovah ny ratran’ny vahoakany, ary sitraniny ny fery lalina vokatry ny kapoka nataony taminy.', 'ho toy ny hazavan’ny masoandro ny hazavan’ny volana fenomanana. ary ho avo fito heny ny hazavan’ny masoandro, hoatran’ny hazavana fito andro, rehefa fonosin’i jehovah ny ratran’ny vahoakany, ary sitraniny ny fery lalina vokatry ny kapoka nataony taminy.'),
  ('6ab25b75f879c900b9a780ba', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 22, 'Holotoinareo ny takela-bolafotsy amin’ny sary sokitrareo, sy ny takela-bolamena amin’ny sarivongana metaly ivavahanareo. Dia harianareo ireny, hoatran’ny lamba nampiasain’ny vehivavy tonga fotoana, ka hiteny ianareo hoe: “Aleo itony hariana any!”', 'holotoinareo ny takela-bolafotsy amin’ny sary sokitrareo, sy ny takela-bolamena amin’ny sarivongana metaly ivavahanareo. dia harianareo ireny, hoatran’ny lamba nampiasain’ny vehivavy tonga fotoana, ka hiteny ianareo hoe: “aleo itony hariana any!”'),
  ('6ab25b75f879c900b9a780ae', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 10, 'Hoy izy ireo amin’ny mpahita: ‘Aza mijery’, Ary amin’ny mpahita fahitana hoe: ‘Aza milaza fahitana marina aminay. Fa teny fandokafana no lazao aminay, ary zavatra mamitaka no jereo ao amin’ny fahitana.', 'hoy izy ireo amin’ny mpahita: ‘aza mijery’, ary amin’ny mpahita fahitana hoe: ‘aza milaza fahitana marina aminay. fa teny fandokafana no lazao aminay, ary zavatra mamitaka no jereo ao amin’ny fahitana.'),
  ('6ab25b75f879c900b9a780af', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 11, 'Mivilia lalana! Mialà amin’ny lalanareo. Aza miresaka aminay momba an’Ilay Masin’ny Israely intsony.’”', 'mivilia lalana! mialà amin’ny lalanareo. aza miresaka aminay momba an’ilay masin’ny israely intsony.’”'),
  ('6ab25b75f879c900b9a780a6', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 2, 'Mandeha midina any Ejipta izy ireo nefa tsy manontany ahy akory. Te hitady fiarovana amin’i Farao, Sy hialokaloka amin’i Ejipta izy ireo.', 'mandeha midina any ejipta izy ireo nefa tsy manontany ahy akory. te hitady fiarovana amin’i farao, sy hialokaloka amin’i ejipta izy ireo.'),
  ('6ab25b75f879c900b9a780a9', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 5, 'Ho menatra daholo izy ireo, Noho ny amin’ny firenena iray tsy mitondra soa ho azy, Izay sady tsy afaka manampy no tsy mitondra soa, Fa mahamenatra sy manala baraka fotsiny.”', 'ho menatra daholo izy ireo, noho ny amin’ny firenena iray tsy mitondra soa ho azy, izay sady tsy afaka manampy no tsy mitondra soa, fa mahamenatra sy manala baraka fotsiny.”'),
  ('6ab25b75f879c900b9a780a7', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 3, 'Lasa hahamenatra anareo anefa ny fiarovan’i Farao, Ary hanala baraka anareo ny mialokaloka amin’i Ejipta.', 'lasa hahamenatra anareo anefa ny fiarovan’i farao, ary hanala baraka anareo ny mialokaloka amin’i ejipta.'),
  ('6ab25b75f879c900b9a780b4', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 16, 'Fa niteny hoe: “Hitaingin-tsoavaly izahay dia handositra!” Dia handositra tokoa ianareo. “Soavaly mahery mandeha no hitaingenanay!” Dia handeha haingana be koa ny olona manenjika anareo.', 'fa niteny hoe: “hitaingin-tsoavaly izahay dia handositra!” dia handositra tokoa ianareo. “soavaly mahery mandeha no hitaingenanay!” dia handeha haingana be koa ny olona manenjika anareo.'),
  ('6ab25b75f879c900b9a780c5', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 33, 'Fa efa vonona ny Tofeta natao ho an’i Asyria. Efa nomanina ho an’ny mpanjaka koa izy io. Nataony mivangongo ao anaty lavaka lehibe sady lalina ny kitay, Ary nataony miredareda ny afo, sady be dia be ny kitay. Handrehitra azy io ny fofonain’i Jehovah, Izay hoatran’ny solifara mitosaka be.', 'fa efa vonona ny tofeta natao ho an’i asyria. efa nomanina ho an’ny mpanjaka koa izy io. nataony mivangongo ao anaty lavaka lehibe sady lalina ny kitay, ary nataony miredareda ny afo, sady be dia be ny kitay. handrehitra azy io ny fofonain’i jehovah, izay hoatran’ny solifara mitosaka be.'),
  ('6ab25b75f879c900b9a780b8', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 20, 'Fahoriana no mofo homen’i Jehovah anareo, ary fampijaliana no rano homeny anareo. Na izany aza, dia tsy hiafina intsony ilay Mpampianatra Be Voninahitra izay mampianatra anao, ka ny masonao mihitsy no hahita an’ilay Mpampianatra Be Voninahitra.', 'fahoriana no mofo homen’i jehovah anareo, ary fampijaliana no rano homeny anareo. na izany aza, dia tsy hiafina intsony ilay mpampianatra be voninahitra izay mampianatra anao, ka ny masonao mihitsy no hahita an’ilay mpampianatra be voninahitra.'),
  ('6ab25b75f879c900b9a780ab', '2026-09-22T10:41:57.779Z', '2026-09-22T10:41:57.779Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 30, 7, 'Fa tsy misy ilana azy mihitsy ny fanampian’i Ejipta. Izany no iantsoako azy hoe: “Rahaba, ilay mipetra-potsiny.”', 'fa tsy misy ilana azy mihitsy ny fanampian’i ejipta. izany no iantsoako azy hoe: “rahaba, ilay mipetra-potsiny.”'),
  ('6ab25b772443a2df0b435049', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 4, 'Hatangorona ny zavatra ataonareo babo, hoatran’ny valala mirangorango mitangorona, Ka hirohotra ho eny amin’ireny ny olona, hoatran’ny andiam-balala.', 'hatangorona ny zavatra ataonareo babo, hoatran’ny valala mirangorango mitangorona, ka hirohotra ho eny amin’ireny ny olona, hoatran’ny andiam-balala.'),
  ('6ab25b772443a2df0b43504c', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 7, 'Miantsoantso eny an-dalana ny lehilahy mahery fo eo amin’izy ireo, Ary mitomany be ny iraka mitady fihavanana.', 'miantsoantso eny an-dalana ny lehilahy mahery fo eo amin’izy ireo, ary mitomany be ny iraka mitady fihavanana.'),
  ('6ab25b772443a2df0b435046', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 1, 'Hahita loza ianao, ry ilay mpandrava tsy nisy nandrava, Dia ilay mpamadika tsy nisy namadika! Horavana ianao rehefa avy mandrava, Ary hisy hamadika rehefa avy mamadika.', 'hahita loza ianao, ry ilay mpandrava tsy nisy nandrava, dia ilay mpamadika tsy nisy namadika! horavana ianao rehefa avy mandrava, ary hisy hamadika rehefa avy mamadika.'),
  ('6ab25b772443a2df0b43504a', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 5, 'Hasandratra i Jehovah, Satria mipetraka eny amin’ny avo. Hataony manjaka ao Ziona ny rariny sy ny hitsiny.', 'hasandratra i jehovah, satria mipetraka eny amin’ny avo. hataony manjaka ao ziona ny rariny sy ny hitsiny.'),
  ('6ab25b772443a2df0b435048', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 3, 'Mandositra ny olona rehefa mandre tabataba. Miparitaka ireo firenena rehefa mitsangana ianao.', 'mandositra ny olona rehefa mandre tabataba. miparitaka ireo firenena rehefa mitsangana ianao.'),
  ('6ab25b772443a2df0b435047', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 2, 'Iantrao izahay, Jehovah ô! Ianao no antenainay. Tohano amin’ny sandrinao izahay isa-maraina, Ary vonjeo amin’ny fotoam-pahoriana.', 'iantrao izahay, jehovah ô! ianao no antenainay. tohano amin’ny sandrinao izahay isa-maraina, ary vonjeo amin’ny fotoam-pahoriana.'),
  ('6ab25b772443a2df0b43504d', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 8, 'Tsy misy olona intsony eny an-dalambe, Ary tsy misy mpandeha intsony eny an-dalana. Nivadika tamin’ny fifanekena ny fahavalo, Sady nanambany an’ireo tanàna, Ary tsy miraharaha olona.', 'tsy misy olona intsony eny an-dalambe, ary tsy misy mpandeha intsony eny an-dalana. nivadika tamin’ny fifanekena ny fahavalo, sady nanambany an’ireo tanàna, ary tsy miraharaha olona.'),
  ('6ab25b772443a2df0b43504b', '2026-09-22T10:41:59.108Z', '2026-09-22T10:41:59.108Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 6, 'Izy no mahatonga anao hilamina sy tsy hitebiteby. Betsaka ny zavatra ataony mba hamonjena anao. Omeny fahendrena sy fahalalana ianao, ary ampianariny hatahotra an’i Jehovah. Izany no harenany.', 'izy no mahatonga anao hilamina sy tsy hitebiteby. betsaka ny zavatra ataony mba hamonjena anao. omeny fahendrena sy fahalalana ianao, ary ampianariny hatahotra an’i jehovah. izany no harenany.'),
  ('6ab25b772443a2df0b435059', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 20, 'Jereo i Ziona, ilay tanàna fanaovantsika fety! Ho hitan’ny masonao i Jerosalema, izay fonenana milamina, Dia tranolay tsy hafindrafindra. Tsy hotsoahana mihitsy ny fantsika be fanenjanan-day eo aminy, Ary tsy hisy hotapahina ny tadiny.', 'jereo i ziona, ilay tanàna fanaovantsika fety! ho hitan’ny masonao i jerosalema, izay fonenana milamina, dia tranolay tsy hafindrafindra. tsy hotsoahana mihitsy ny fantsika be fanenjanan-day eo aminy, ary tsy hisy hotapahina ny tadiny.'),
  ('6ab25b772443a2df0b435052', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 13, 'Henoy izay hataoko, ry olona any lavitra! Ekeo hoe mahery aho, ry olona eto akaiky!', 'henoy izay hataoko, ry olona any lavitra! ekeo hoe mahery aho, ry olona eto akaiky!'),
  ('6ab25b772443a2df0b435058', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 19, 'Tsy hahita an’ilay firenena sahisahy ratsy intsony ianao, Izany hoe firenena mampiasa fiteny sarotra be ka tsy mety azo, Sy miakanakam-piteny ka tsy azonao ny teniny.', 'tsy hahita an’ilay firenena sahisahy ratsy intsony ianao, izany hoe firenena mampiasa fiteny sarotra be ka tsy mety azo, sy miakanakam-piteny ka tsy azonao ny teniny.'),
  ('6ab25b772443a2df0b435057', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 18, 'Hotsaroanao ao am-ponao ilay zavatra nampihorohoro anao, hoe: “Aiza ilay mpitan-tsoratra? Aiza ilay nandanja ny hetra? Ary aiza ilay nanisa ny tilikambo?”', 'hotsaroanao ao am-ponao ilay zavatra nampihorohoro anao, hoe: “aiza ilay mpitan-tsoratra? aiza ilay nandanja ny hetra? ary aiza ilay nanisa ny tilikambo?”'),
  ('6ab25b772443a2df0b435055', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 16, 'Dia izy no hipetraka eny amin’ny toerana avo. Ho eny amin’ny vatolampy sarotra aleha ny fialofany. Homena azy koa ny sakafony, Ary tsy ho ritra mihitsy ny tahirin-dranony.”', 'dia izy no hipetraka eny amin’ny toerana avo. ho eny amin’ny vatolampy sarotra aleha ny fialofany. homena azy koa ny sakafony, ary tsy ho ritra mihitsy ny tahirin-dranony.”'),
  ('6ab25b772443a2df0b435051', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 12, 'Ho lasa hoatran’ny lavenona avy amin’ny sokay nodorana ireo firenena. Hoatran’ny tsilo notapahina izy ireo ka hodorana amin’ny afo.', 'ho lasa hoatran’ny lavenona avy amin’ny sokay nodorana ireo firenena. hoatran’ny tsilo notapahina izy ireo ka hodorana amin’ny afo.'),
  ('6ab25b772443a2df0b43505c', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 23, 'Higoragora ny tady, Ka tsy mahavita mitazona ny andrin-tsambo hijoro tsara, na mahavita mamelatra ny lay. Amin’izay fotoana izay, dia hozaraina ny zavatra be dia be azo babo, Ka na ny malemy tongotra aza haka be dia be amin’izay norobaina.', 'higoragora ny tady, ka tsy mahavita mitazona ny andrin-tsambo hijoro tsara, na mahavita mamelatra ny lay. amin’izay fotoana izay, dia hozaraina ny zavatra be dia be azo babo, ka na ny malemy tongotra aza haka be dia be amin’izay norobaina.'),
  ('6ab25b772443a2df0b43505b', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 22, 'Fa i Jehovah no Mpitsara antsika, I Jehovah no Mpanao Lalàna ho antsika. I Jehovah no Mpanjakantsika, Ary izy no hamonjy antsika.', 'fa i jehovah no mpitsara antsika, i jehovah no mpanao lalàna ho antsika. i jehovah no mpanjakantsika, ary izy no hamonjy antsika.'),
  ('6ab25b772443a2df0b435050', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 11, 'Bozaka maina no miforona ao an-kibonareo, ary vodivary no aterakareo. Handevona anareo hoatran’ny afo ny eritreri-dratsinareo.', 'bozaka maina no miforona ao an-kibonareo, ary vodivary no aterakareo. handevona anareo hoatran’ny afo ny eritreri-dratsinareo.'),
  ('6ab25b772443a2df0b43505d', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 24, 'Ary tsy hisy olona hilaza hoe: “Marary aho.” Ho voavela heloka ny olona mipetraka ao amin’ilay tany.', 'ary tsy hisy olona hilaza hoe: “marary aho.” ho voavela heloka ny olona mipetraka ao amin’ilay tany.'),
  ('6ab25b772443a2df0b435054', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 15, 'Izay manao ny marina foana, Sy milaza ny marina, Sy tsy tia tombony azo amin’ny fitaka sy ny tsy rariny, Sady tsy mety mandray tsolotra mihitsy, Sy manampina ny sofiny tsy hihaino ny resaky ny olona te handatsa-dra, Ary manakimpy ny masony tsy hahita zava-dratsy,', 'izay manao ny marina foana, sy milaza ny marina, sy tsy tia tombony azo amin’ny fitaka sy ny tsy rariny, sady tsy mety mandray tsolotra mihitsy, sy manampina ny sofiny tsy hihaino ny resaky ny olona te handatsa-dra, ary manakimpy ny masony tsy hahita zava-dratsy,'),
  ('6ab25b772443a2df0b43504f', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 10, '“Hitsangana aho izao”, hoy i Jehovah, “Dia hasandratro ny tenako, Ka homeko voninahitra.', '“hitsangana aho izao”, hoy i jehovah, “dia hasandratro ny tenako, ka homeko voninahitra.'),
  ('6ab25b772443a2df0b43505a', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 21, 'Fa ao i Jehovah, Ilay Manan-kaja, No hiaro antsika hoatran’ny renirano sy ny lakandrano lehibe, Ka tsy hisy andian-tsambon’ny fahavalo handeha eny amin’ireny, Ary tsy hisy sambo lehibe handalo eny.', 'fa ao i jehovah, ilay manan-kaja, no hiaro antsika hoatran’ny renirano sy ny lakandrano lehibe, ka tsy hisy andian-tsambon’ny fahavalo handeha eny amin’ireny, ary tsy hisy sambo lehibe handalo eny.'),
  ('6ab25b772443a2df0b435056', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 17, 'Hahita mpanjaka be voninahitra ny masonao, Sady hahatazana tany eny lavitra eny.', 'hahita mpanjaka be voninahitra ny masonao, sady hahatazana tany eny lavitra eny.'),
  ('6ab25b772443a2df0b435053', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 14, 'Matahotra be ny mpanota ao Ziona, Ary lasa mangovitra ireo miala amin’Andriamanitra, ka miteny hoe: ‘Iza amintsika no mahavita mipetraka ao anaty afo mandevona? Iza amintsika koa no mahavita mipetraka ao anaty lelafo tsy mety maty?’', 'matahotra be ny mpanota ao ziona, ary lasa mangovitra ireo miala amin’andriamanitra, ka miteny hoe: ‘iza amintsika no mahavita mipetraka ao anaty afo mandevona? iza amintsika koa no mahavita mipetraka ao anaty lelafo tsy mety maty?’'),
  ('6ab25b772443a2df0b43504e', '2026-09-22T10:41:59.109Z', '2026-09-22T10:41:59.109Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 33, 9, 'Misaona sy malazo ilay tany. Menatra i Libàna fa simba. Lasa hoatran’ny tany efitra i Sarôna, Ary mihintsan-dravina i Basana sy Karmela.', 'misaona sy malazo ilay tany. menatra i libàna fa simba. lasa hoatran’ny tany efitra i sarôna, ary mihintsan-dravina i basana sy karmela.'),
  ('6ab25b772f8cdc5648209d09', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 7, 'Ho lasa farihy anirian’ny bararata ny tany ngazana, Ary ho lasa loharano ny tany karakaina. Hisy ahitra maitso sy bararata ary zozoro ny toerana ipetrahan’ny alikadia, Dia ny toerana fialany sasatra.', 'ho lasa farihy anirian’ny bararata ny tany ngazana, ary ho lasa loharano ny tany karakaina. hisy ahitra maitso sy bararata ary zozoro ny toerana ipetrahan’ny alikadia, dia ny toerana fialany sasatra.'),
  ('6ab25b772f8cdc5648209d0c', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 10, 'Hiverina any Ziona ireo navotan’i Jehovah sady hihoby. Hifaly foana izy ireo ka ho toy ny satroboninahitra eny aminy ny fifaliany. Ho falifaly sy ho ravoravo foana izy ireo, Fa tsy halahelo na hisento intsony.', 'hiverina any ziona ireo navotan’i jehovah sady hihoby. hifaly foana izy ireo ka ho toy ny satroboninahitra eny aminy ny fifaliany. ho falifaly sy ho ravoravo foana izy ireo, fa tsy halahelo na hisento intsony.'),
  ('6ab25b772f8cdc5648209d07', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 5, 'Amin’izany fotoana izany, dia hatao lasa mahita ny mason’ny jamba, Ary hatao mandre ny sofin’ny marenina.', 'amin’izany fotoana izany, dia hatao lasa mahita ny mason’ny jamba, ary hatao mandre ny sofin’ny marenina.'),
  ('6ab25b772f8cdc5648209d04', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 2, 'Hamony tokoa ny lemaka karakaina, Sady ho faly sy hihoby. Homena azy ny voninahitr’i Libàna, Sy ny hatsaran-tarehin’i Karmela sy Sarôna. Ho hitan’ny olona fa be voninahitra i Jehovah, ary henin-kaja ilay Andriamanitsika.', 'hamony tokoa ny lemaka karakaina, sady ho faly sy hihoby. homena azy ny voninahitr’i libàna, sy ny hatsaran-tarehin’i karmela sy sarôna. ho hitan’ny olona fa be voninahitra i jehovah, ary henin-kaja ilay andriamanitsika.'),
  ('6ab25b772f8cdc5648209d03', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 1, 'Hifaly ny tany efitra sy ny tany ngazana, Ary hiravoravo ny lemaka karakaina sady ho feno voninkazo.', 'hifaly ny tany efitra sy ny tany ngazana, ary hiravoravo ny lemaka karakaina sady ho feno voninkazo.'),
  ('6ab25b772f8cdc5648209d0a', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 8, 'Hisy lalambe any, Dia lalana hatao hoe Lalan’ny Fahamasinana. Tsy handeha eny ny olona tsy madio. Fa natokana ho an’izay mahazo mandeha eny ihany izy io, Ka tsy hisy olona adala handehandeha eny.', 'hisy lalambe any, dia lalana hatao hoe lalan’ny fahamasinana. tsy handeha eny ny olona tsy madio. fa natokana ho an’izay mahazo mandeha eny ihany izy io, ka tsy hisy olona adala handehandeha eny.'),
  ('6ab25b772f8cdc5648209d0b', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 9, 'Tsy hisy liona eny, Sady tsy hankeny ny bibidia masiaka. Tsy hisy ho hita eny ireny, Fa izay babo efa navotana ihany no handeha eny.', 'tsy hisy liona eny, sady tsy hankeny ny bibidia masiaka. tsy hisy ho hita eny ireny, fa izay babo efa navotana ihany no handeha eny.'),
  ('6ab25b772f8cdc5648209d06', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 4, 'Lazao amin’ireo mitebiteby hoe: “Mahereza ary aza matahotra! Ho avy hamaly ny fahavalonareo ilay Andriamanitrareo, Ho avy hanasazy Andriamanitra, Ary ho avy hamonjy anareo izy.”', 'lazao amin’ireo mitebiteby hoe: “mahereza ary aza matahotra! ho avy hamaly ny fahavalonareo ilay andriamanitrareo, ho avy hanasazy andriamanitra, ary ho avy hamonjy anareo izy.”'),
  ('6ab25b772f8cdc5648209d05', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 3, 'Hatanjaho ny tanana malemy, Sy ny lohalika mangozohozo.', 'hatanjaho ny tanana malemy, sy ny lohalika mangozohozo.'),
  ('6ab25b772f8cdc5648209d08', '2026-09-22T10:41:59.928Z', '2026-09-22T10:41:59.928Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 35, 6, 'Amin’izany fotoana izany koa, dia hitsambikina hoatran’ny serfa ny malemy tongotra, Ary hihoby ny lelan’ny moana. Fa hisy rano hiboiboika any an-tany efitra, Ary hisy rano mikoriana any amin’ny lemaka karakaina.', 'amin’izany fotoana izany koa, dia hitsambikina hoatran’ny serfa ny malemy tongotra, ary hihoby ny lelan’ny moana. fa hisy rano hiboiboika any an-tany efitra, ary hisy rano mikoriana any amin’ny lemaka karakaina.'),
  ('6ab25b7accffddbc9ff6b7bf', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 24, 'Toy ny zavamaniry vao nambolena izy ireo, Hoatran’ny voa vao nafafy, Ary mbola tsy mamaka tsara ao anaty tany ny fotony. Dia tsofin’ny rivotra izy ireo ka maina, Ary entin’ny rivotra toy ny mololo.', 'toy ny zavamaniry vao nambolena izy ireo, hoatran’ny voa vao nafafy, ary mbola tsy mamaka tsara ao anaty tany ny fotony. dia tsofin’ny rivotra izy ireo ka maina, ary entin’ny rivotra toy ny mololo.'),
  ('6ab25b7accffddbc9ff6b7b5', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 14, 'Iza no nanontaniany mba hanampy azy hisaina tsara, Ary iza no mampianatra azy ny lalan’ny rariny? Iza no mampita fahalalana aminy, Na mampiseho azy ny atao hoe tena fahiratan-tsaina?', 'iza no nanontaniany mba hanampy azy hisaina tsara, ary iza no mampianatra azy ny lalan’ny rariny? iza no mampita fahalalana aminy, na mampiseho azy ny atao hoe tena fahiratan-tsaina?'),
  ('6ab25b7accffddbc9ff6b7b3', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 12, 'Iza no mahavita mamatra ny rano rehetra amin’ny felatanany, Sy mandrefy ny lanitra amin’ny irain-jehy? Iza no mahavita mamatra ny vovoky ny tany amin’ny kapoaka, Na mandanja ny tendrombohitra amin’ny fandanjana, Sy mandanja ny havoana amin’ny mizana?', 'iza no mahavita mamatra ny rano rehetra amin’ny felatanany, sy mandrefy ny lanitra amin’ny irain-jehy? iza no mahavita mamatra ny vovoky ny tany amin’ny kapoaka, na mandanja ny tendrombohitra amin’ny fandanjana, sy mandanja ny havoana amin’ny mizana?'),
  ('6ab25b7accffddbc9ff6b7b0', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 9, 'Miakara any an-tendrombohitra avo, Ry vehivavy mitondra vaovao tsara ho an’i Ziona. Ataovy mafy ny feonao, Ry vehivavy mitondra vaovao tsara ho an’i Jerosalema. Mitenena mafy ary aza matahotra! Lazao amin’ireo tanànan’i Joda hoe: “Iny ilay Andriamanitrareo!”', 'miakara any an-tendrombohitra avo, ry vehivavy mitondra vaovao tsara ho an’i ziona. ataovy mafy ny feonao, ry vehivavy mitondra vaovao tsara ho an’i jerosalema. mitenena mafy ary aza matahotra! lazao amin’ireo tanànan’i joda hoe: “iny ilay andriamanitrareo!”'),
  ('6ab25b7accffddbc9ff6b7c5', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 30, 'Ho reraka sy ho sasatra ny ankizilahy, Ary ho tafintohina ny tovolahy ka hianjera.', 'ho reraka sy ho sasatra ny ankizilahy, ary ho tafintohina ny tovolahy ka hianjera.'),
  ('6ab25b7accffddbc9ff6b7ae', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 7, 'Maina ny ahi-maitso, Ary malazo ny voninkazo, Satria notsofin’i Jehovah tamin’ny fofonainy. Ahitra fotsiny tokoa ny olona.', 'maina ny ahi-maitso, ary malazo ny voninkazo, satria notsofin’i jehovah tamin’ny fofonainy. ahitra fotsiny tokoa ny olona.'),
  ('6ab25b7accffddbc9ff6b7c2', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 27, 'Maninona ianao, ry Jakoba no miteny an’izao, ary maninona ianao, ry Israely, no milaza hoe: ‘Tsy hitan’i Jehovah ny manjo ahy, Ary tsy mba mahazo rariny amin’Andriamanitra aho’?', 'maninona ianao, ry jakoba no miteny an’izao, ary maninona ianao, ry israely, no milaza hoe: ‘tsy hitan’i jehovah ny manjo ahy, ary tsy mba mahazo rariny amin’andriamanitra aho’?'),
  ('6ab25b7accffddbc9ff6b7ba', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 19, 'Manamboatra sampy ny mpanao asa tanana, Ary mametaka takela-bolamena eo amin’ilay izy ny mpanefy, Sady manefy rojo volafotsy.', 'manamboatra sampy ny mpanao asa tanana, ary mametaka takela-bolamena eo amin’ilay izy ny mpanefy, sady manefy rojo volafotsy.'),
  ('6ab25b7accffddbc9ff6b7ab', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 4, 'Aoka hisondrotra ny lohasaha rehetra, Ary hietry daholo kosa ny tendrombohitra sy ny havoana. Ataovy mitovy tantana ny tany misy dongodongona, Ary ataovy lasa lemaka ny tany mikitoantoana.', 'aoka hisondrotra ny lohasaha rehetra, ary hietry daholo kosa ny tendrombohitra sy ny havoana. ataovy mitovy tantana ny tany misy dongodongona, ary ataovy lasa lemaka ny tany mikitoantoana.'),
  ('6ab25b7accffddbc9ff6b7bb', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 20, 'Mifidy hazo ny olona mba hataony fanomezana, Dia hazo tsy ho lo. Mitady mpanao asa tanana mahay izy, Mba hanamboatra sary sokitra izay tsy hitongilangilana.', 'mifidy hazo ny olona mba hataony fanomezana, dia hazo tsy ho lo. mitady mpanao asa tanana mahay izy, mba hanamboatra sary sokitra izay tsy hitongilangilana.'),
  ('6ab25b7accffddbc9ff6b7b1', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 10, 'Ho avy i Jehovah Tompo Fara Tampony ka hampiseho ny heriny, Ary ny sandriny no hanjaka. Efa eny aminy ny valisoa homeny, Ary efa any aminy ny karama haloany.', 'ho avy i jehovah tompo fara tampony ka hampiseho ny heriny, ary ny sandriny no hanjaka. efa eny aminy ny valisoa homeny, ary efa any aminy ny karama haloany.'),
  ('6ab25b7accffddbc9ff6b7aa', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 3, 'Izany fa misy miantsoantso any an-tany efitra hoe: “Omano ny lalana halehan’i Jehovah! Manaova lalambe mahitsy mamakivaky ny tany karakaina, mba handehanan’ilay Andriamanitsika.', 'izany fa misy miantsoantso any an-tany efitra hoe: “omano ny lalana halehan’i jehovah! manaova lalambe mahitsy mamakivaky ny tany karakaina, mba handehanan’ilay andriamanitsika.'),
  ('6ab25b7accffddbc9ff6b7b2', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 11, 'Toy ny mpiandry ondry izy ka hokarakarainy ny andian’ondriny. Ny sandriny no hanangonany ny zanak’ondry, Dia hotrotroiny eo an-tratrany ireny. Hotarihiny sady hokenakenainy tsara ireo ondrivavy mbola mampinono.', 'toy ny mpiandry ondry izy ka hokarakarainy ny andian’ondriny. ny sandriny no hanangonany ny zanak’ondry, dia hotrotroiny eo an-tratrany ireny. hotarihiny sady hokenakenainy tsara ireo ondrivavy mbola mampinono.'),
  ('6ab25b7accffddbc9ff6b7a8', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 1, '“Ampionòny, ampionòny ny vahoakako!”, hoy ilay Andriamanitrareo.', '“ampionòny, ampionòny ny vahoakako!”, hoy ilay andriamanitrareo.'),
  ('6ab25b7accffddbc9ff6b7c6', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 31, 'Fa izay manantena an’i Jehovah kosa hahazo hery indray. Hanidina ambony izy ireo, hoatran’ny hoe manana elatry ny voromahery. Hihazakazaka izy nefa tsy ho vizana, Ary handeha nefa tsy ho reraka.”', 'fa izay manantena an’i jehovah kosa hahazo hery indray. hanidina ambony izy ireo, hoatran’ny hoe manana elatry ny voromahery. hihazakazaka izy nefa tsy ho vizana, ary handeha nefa tsy ho reraka.”'),
  ('6ab25b7accffddbc9ff6b7b8', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 17, 'Ny firenena rehetra dia toy ny tsy misy, eo anatrehany. Tsinontsinona sy tsy misy dikany ireny aminy.', 'ny firenena rehetra dia toy ny tsy misy, eo anatrehany. tsinontsinona sy tsy misy dikany ireny aminy.'),
  ('6ab25b7accffddbc9ff6b7a9', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 2, '“Manaova teny manohina ny fon’i Jerosalema. Lazao aminy fa efa vita ny asa an-terivozona nataony, Ary efa voaonitra ny fahadisoany. Efa nataon’i Jehovah nanefa ny sazy sahaza azy izy, noho ny fahotany rehetra.”', '“manaova teny manohina ny fon’i jerosalema. lazao aminy fa efa vita ny asa an-terivozona nataony, ary efa voaonitra ny fahadisoany. efa nataon’i jehovah nanefa ny sazy sahaza azy izy, noho ny fahotany rehetra.”'),
  ('6ab25b7accffddbc9ff6b7c3', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 28, 'Tsy fantatrao angaha? Sa mbola tsy henonao? Andriamanitra mandrakizay i Jehovah, ilay Mpamorona ny faran’ny tany. Tsy mba reraka na sasatra mihitsy izy. Tsy takatry ny saina ny fahalalany.', 'tsy fantatrao angaha? sa mbola tsy henonao? andriamanitra mandrakizay i jehovah, ilay mpamorona ny faran’ny tany. tsy mba reraka na sasatra mihitsy izy. tsy takatry ny saina ny fahalalany.'),
  ('6ab25b7accffddbc9ff6b7b7', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 16, 'Na ny hazo ao Libàna aza tsy ampy hatao kitay, Ary na ny bibidia ao aza tsy ampy hatao fanatitra dorana.', 'na ny hazo ao libàna aza tsy ampy hatao kitay, ary na ny bibidia ao aza tsy ampy hatao fanatitra dorana.'),
  ('6ab25b7accffddbc9ff6b7b4', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 13, 'Iza no mahavita mandrefy ny fanahin’i Jehovah? Ary iza no afaka mampianatra azy ka hanoro hevitra azy?', 'iza no mahavita mandrefy ny fanahin’i jehovah? ary iza no afaka mampianatra azy ka hanoro hevitra azy?'),
  ('6ab25b7accffddbc9ff6b7c4', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 29, 'Omeny hery ny reraka, Ary ataony matanjaka be izay kely hery.', 'omeny hery ny reraka, ary ataony matanjaka be izay kely hery.'),
  ('6ab25b7accffddbc9ff6b7bc', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 21, 'Tsy fantatrareo ve? Mbola tsy henonareo ve? Mbola tsy nolazaina taminareo hatramin’ny voalohany ve? Mbola tsy azonareo ihany ve hatramin’ny nametrahana ny fototry ny tany?', 'tsy fantatrareo ve? mbola tsy henonareo ve? mbola tsy nolazaina taminareo hatramin’ny voalohany ve? mbola tsy azonareo ihany ve hatramin’ny nametrahana ny fototry ny tany?'),
  ('6ab25b7accffddbc9ff6b7c1', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 26, '“Jereo ny lanitra ka banjino. Iza no namorona an’ireny zavatra ireny? Izy Ilay mamoaka azy ireny hoatran’ny mamoaka tafika, sady manisa azy tsirairay, Ary miantso azy rehetra amin’ny anarany avy. Matanjaka be izy ary tena mahatalanjona ny heriny, Ka tsy misy banga ireny na iray aza.', '“jereo ny lanitra ka banjino. iza no namorona an’ireny zavatra ireny? izy ilay mamoaka azy ireny hoatran’ny mamoaka tafika, sady manisa azy tsirairay, ary miantso azy rehetra amin’ny anarany avy. matanjaka be izy ary tena mahatalanjona ny heriny, ka tsy misy banga ireny na iray aza.'),
  ('6ab25b7accffddbc9ff6b7c0', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 25, '“Iza no azonareo ampitovina amiko, ka lasa hitovy aminy aho?”, hoy Ilay Masina.', '“iza no azonareo ampitovina amiko, ka lasa hitovy aminy aho?”, hoy ilay masina.'),
  ('6ab25b7accffddbc9ff6b7b6', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 15, 'Hoatran’ny rano indray mitete avy amin’ny siny ireo firenena, Ary toy ny vovoka manify eo amin’ny mizana no fiheverana azy. Manainga an’ireo nosy izy, toy ny manainga piti-bovoka.', 'hoatran’ny rano indray mitete avy amin’ny siny ireo firenena, ary toy ny vovoka manify eo amin’ny mizana no fiheverana azy. manainga an’ireo nosy izy, toy ny manainga piti-bovoka.'),
  ('6ab25b7accffddbc9ff6b7af', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 8, 'Maina ny ahi-maitso, Ary malazo ny voninkazo, Fa ny tenin’ilay Andriamanitsika kosa maharitra mandrakizay.”', 'maina ny ahi-maitso, ary malazo ny voninkazo, fa ny tenin’ilay andriamanitsika kosa maharitra mandrakizay.”'),
  ('6ab25b7accffddbc9ff6b7ac', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 5, 'Dia hiharihary ny voninahitr’i Jehovah, Ka samy hahita an’izany ny olombelona rehetra, Satria i Jehovah no efa niteny.”', 'dia hiharihary ny voninahitr’i jehovah, ka samy hahita an’izany ny olombelona rehetra, satria i jehovah no efa niteny.”'),
  ('6ab25b7accffddbc9ff6b7be', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 23, 'Ataony lasa tsinontsinona ny manam-pahefana ambony, Ary ataony tsy misy dikany ny mpitsara eto an-tany.', 'ataony lasa tsinontsinona ny manam-pahefana ambony, ary ataony tsy misy dikany ny mpitsara eto an-tany.'),
  ('6ab25b7accffddbc9ff6b7bd', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 22, 'Izy Ilay mipetraka any amin’ny avo, any ambonin’ity tany boribory ity, Ary hoatran’ny valala ny mponina eo aminy. Izy no mamelatra ny lanitra toy ny lamba manify, Sy mamelatra azy toy ny tranolay ipetrahana.', 'izy ilay mipetraka any amin’ny avo, any ambonin’ity tany boribory ity, ary hoatran’ny valala ny mponina eo aminy. izy no mamelatra ny lanitra toy ny lamba manify, sy mamelatra azy toy ny tranolay ipetrahana.'),
  ('6ab25b7accffddbc9ff6b7b9', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 18, 'Iza no azonareo ampitovina amin’Andriamanitra? Ary inona no azonareo ampitahaina aminy?', 'iza no azonareo ampitovina amin’andriamanitra? ary inona no azonareo ampitahaina aminy?'),
  ('6ab25b7accffddbc9ff6b7ad', '2026-09-22T10:42:02.392Z', '2026-09-22T10:42:02.392Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 40, 6, 'Izany misy miteny hoe: “Miantsoantsoa!” Dia misy mamaly hoe: “Hiantso hoe ahoana?” “Ahitra ihany ny olombelona rehetra, Ary hoatran’ny voninkazo eny an-tsaha daholo ny fitiavany sy ny tsy fivadihany.', 'izany misy miteny hoe: “miantsoantsoa!” dia misy mamaly hoe: “hiantso hoe ahoana?” “ahitra ihany ny olombelona rehetra, ary hoatran’ny voninkazo eny an-tsaha daholo ny fitiavany sy ny tsy fivadihany.'),
  ('6ab25b7bf19bcd2427834412', '2026-09-22T10:42:03.550Z', '2026-09-22T10:42:03.550Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 4, 'Tsy ho reraka na ho sasatra izy mandra-panaovany ny rariny eto an-tany. Ary hiandry ny lalàny foana ireo nosy.', 'tsy ho reraka na ho sasatra izy mandra-panaovany ny rariny eto an-tany. ary hiandry ny lalàny foana ireo nosy.'),
  ('6ab25b7bf19bcd242783440f', '2026-09-22T10:42:03.550Z', '2026-09-22T10:42:03.550Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 1, 'Io ny mpanompoko izay tohanako, Ilay nofidiko sady ankasitrahako! Nomeko ny fanahiko izy, Ka hampihatra ny rariny amin’ireo firenena.', 'io ny mpanompoko izay tohanako, ilay nofidiko sady ankasitrahako! nomeko ny fanahiko izy, ka hampihatra ny rariny amin’ireo firenena.'),
  ('6ab25b7bf19bcd2427834410', '2026-09-22T10:42:03.550Z', '2026-09-22T10:42:03.550Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 2, 'Tsy hiantsoantso izy na hihogahoga, Ary tsy hataony heno eny an-dalana ny feony.', 'tsy hiantsoantso izy na hihogahoga, ary tsy hataony heno eny an-dalana ny feony.'),
  ('6ab25b7bf19bcd2427834411', '2026-09-22T10:42:03.550Z', '2026-09-22T10:42:03.550Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 3, 'Tsy hotapahiny ny bararata folaka, Ary tsy hovonoiny ny lahin-jiro mitsilopilopy. Tsy mivadika izy ka hampihatra ny rariny.', 'tsy hotapahiny ny bararata folaka, ary tsy hovonoiny ny lahin-jiro mitsilopilopy. tsy mivadika izy ka hampihatra ny rariny.'),
  ('6ab25b7bf19bcd2427834413', '2026-09-22T10:42:03.550Z', '2026-09-22T10:42:03.550Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 5, 'Izao no tenin’i Jehovah, ilay tena Andriamanitra, Dia ilay Mpamorona ny lanitra, Ilay Be Voninahitra izay namelatra ny lanitra, Ilay nanao ny tany sy ny vokatra eo aminy, Ilay manome fofonaina ho an’ny mponina eny ambonin’ny tany, Sy manome aina ho an’izay mandeha eny ambonin’ny tany:', 'izao no tenin’i jehovah, ilay tena andriamanitra, dia ilay mpamorona ny lanitra, ilay be voninahitra izay namelatra ny lanitra, ilay nanao ny tany sy ny vokatra eo aminy, ilay manome fofonaina ho an’ny mponina eny ambonin’ny tany, sy manome aina ho an’izay mandeha eny ambonin’ny tany:'),
  ('6ab25b7bf19bcd242783441d', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 15, 'Handrava tendrombohitra sy havoana aho, Dia hataoko maina ny zavamaniry rehetra eny. Hovako ho nosy ny renirano, Ary hataoko ritra ny farihy anirian’ny bararata.', 'handrava tendrombohitra sy havoana aho, dia hataoko maina ny zavamaniry rehetra eny. hovako ho nosy ny renirano, ary hataoko ritra ny farihy anirian’ny bararata.'),
  ('6ab25b7bf19bcd2427834419', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 11, 'Aoka hanandra-peo ny tany efitra sy ny tanànany Ary ny tanàna kely ipetrahan’i Kedara. Aoka hihoby sy ho falifaly ny mponina eny amin’ny harambato, Sady hiantsoantso avy eny an-tampon-tendrombohitra.', 'aoka hanandra-peo ny tany efitra sy ny tanànany ary ny tanàna kely ipetrahan’i kedara. aoka hihoby sy ho falifaly ny mponina eny amin’ny harambato, sady hiantsoantso avy eny an-tampon-tendrombohitra.'),
  ('6ab25b7bf19bcd2427834424', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 22, 'Nangalarina sy norobaina ny fananan’ny vahoaka. Voafandrika ao anaty lavaka daholo izy ireo, ary afenina ao am-ponja. Nangalarina ny fananany nefa tsy nisy namonjy azy. Norobaina koa ny fananany nefa tsy nisy niteny hoe: “Avereno atỳ ireny!”', 'nangalarina sy norobaina ny fananan’ny vahoaka. voafandrika ao anaty lavaka daholo izy ireo, ary afenina ao am-ponja. nangalarina ny fananany nefa tsy nisy namonjy azy. norobaina koa ny fananany nefa tsy nisy niteny hoe: “avereno atỳ ireny!”'),
  ('6ab25b7bf19bcd2427834418', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 10, 'Mihirà hira vaovao ho an’i Jehovah! Hirao avy any amin’ny faran’ny tany ny fiderana azy, Ry olona mivelona amin’ny ranomasina sy izay rehetra ao anatiny, Ry nosy sy ny mponina eo aminy!', 'mihirà hira vaovao ho an’i jehovah! hirao avy any amin’ny faran’ny tany ny fiderana azy, ry olona mivelona amin’ny ranomasina sy izay rehetra ao anatiny, ry nosy sy ny mponina eo aminy!'),
  ('6ab25b7bf19bcd2427834416', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 8, 'Izaho no Jehovah. Izany no anarako. Tsy homeko an’iza na iza ny voninahitro, Ary tsy homeko ho an’ny sary sokitra ny fiderana ahy.', 'izaho no jehovah. izany no anarako. tsy homeko an’iza na iza ny voninahitro, ary tsy homeko ho an’ny sary sokitra ny fiderana ahy.'),
  ('6ab25b7bf19bcd242783441c', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 14, '“Efa hatry ny ela aho no nangina, Ary mbola nangina sy nifehy tena foana. Hitaraina sady hisefosefo ary ho sempotsempotra anefa aho, Toy ny vehivavy efa ho teraka.', '“efa hatry ny ela aho no nangina, ary mbola nangina sy nifehy tena foana. hitaraina sady hisefosefo ary ho sempotsempotra anefa aho, toy ny vehivavy efa ho teraka.'),
  ('6ab25b7bf19bcd2427834414', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 6, '“Izaho Jehovah no miantso anao araka ny fahamarinana. Mitazona ny tananao aho. Hiaro anao aho, ary ianao no hataoko antoka ho an’ny olona, Sy fahazavana ho an’ny firenena,', '“izaho jehovah no miantso anao araka ny fahamarinana. mitazona ny tananao aho. hiaro anao aho, ary ianao no hataoko antoka ho an’ny olona, sy fahazavana ho an’ny firenena,'),
  ('6ab25b7bf19bcd2427834423', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 21, 'Fa tia rariny i Jehovah, Ka mahafinaritra azy ny mampiseho hoe tena miavaka sy be voninahitra ny lalàna.', 'fa tia rariny i jehovah, ka mahafinaritra azy ny mampiseho hoe tena miavaka sy be voninahitra ny lalàna.'),
  ('6ab25b7bf19bcd242783441a', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 12, 'Aoka izy ireo hanome voninahitra an’i Jehovah, Sy hidera azy eny amin’ireo nosy.', 'aoka izy ireo hanome voninahitra an’i jehovah, sy hidera azy eny amin’ireo nosy.'),
  ('6ab25b7bf19bcd2427834427', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 25, 'Nanampatra ny hatezerany taminy àry Izy, Ary nisafoaka mafy sady namela azy hijalijaly tao anatin’ny ady mangotraka. Nandevona an’izay rehetra nanodidina azy izany ady izany, nefa tsy noraharahiany. Nandoro azy ilay izy, nefa tsy noheveriny ho zava-dehibe.', 'nanampatra ny hatezerany taminy àry izy, ary nisafoaka mafy sady namela azy hijalijaly tao anatin’ny ady mangotraka. nandevona an’izay rehetra nanodidina azy izany ady izany, nefa tsy noraharahiany. nandoro azy ilay izy, nefa tsy noheveriny ho zava-dehibe.'),
  ('6ab25b7bf19bcd242783441e', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 16, 'Hotarihiko amin’ny lalana tsy fantany ny jamba, Ka hoentiko ho eny amin’ny lalana tsy mahazatra azy. Hataoko mazava ny haizina eo alohan’izy ireo, Ary hataoko mitovy tantana ny tany mikitoantoana. Izany no hataoko ho azy ireo, ary tsy handao azy aho.”', 'hotarihiko amin’ny lalana tsy fantany ny jamba, ka hoentiko ho eny amin’ny lalana tsy mahazatra azy. hataoko mazava ny haizina eo alohan’izy ireo, ary hataoko mitovy tantana ny tany mikitoantoana. izany no hataoko ho azy ireo, ary tsy handao azy aho.”'),
  ('6ab25b7bf19bcd242783441b', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 13, 'Hivoaka hiady toy ny lehilahy matanjaka i Jehovah. Efa maika hanao zavatra hoatran’ny miaramila izy, Ary hiantsoantso mafy hanao hiakan’ady. Dia hasehony fa mahery noho ny fahavalony izy.', 'hivoaka hiady toy ny lehilahy matanjaka i jehovah. efa maika hanao zavatra hoatran’ny miaramila izy, ary hiantsoantso mafy hanao hiakan’ady. dia hasehony fa mahery noho ny fahavalony izy.'),
  ('6ab25b7bf19bcd2427834415', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 7, 'Mba hataonao mahita ny mason’ny jamba, Ary havoakanao avy any ambany lakaly figadrana ny voafonja, Sady havoakanao avy ao am-ponja izay mipetraka ao anaty haizina.', 'mba hataonao mahita ny mason’ny jamba, ary havoakanao avy any ambany lakaly figadrana ny voafonja, sady havoakanao avy ao am-ponja izay mipetraka ao anaty haizina.'),
  ('6ab25b7bf19bcd2427834425', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 23, 'Iza aminareo no hihaino an’izany? Iza no hihaino tsara ka handray soa any aoriana any?', 'iza aminareo no hihaino an’izany? iza no hihaino tsara ka handray soa any aoriana any?'),
  ('6ab25b7bf19bcd2427834421', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 19, 'Iza moa no jamba raha tsy ny mpanompoko ihany? Iza no tena marenina hoatran’ilay nirahiko? Iza no tena jamba hoatran’ilay nahazo valisoa, Na tena jamba toy ny mpanompon’i Jehovah?', 'iza moa no jamba raha tsy ny mpanompoko ihany? iza no tena marenina hoatran’ilay nirahiko? iza no tena jamba hoatran’ilay nahazo valisoa, na tena jamba toy ny mpanompon’i jehovah?'),
  ('6ab25b7bf19bcd2427834420', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 18, 'Mihainoa, ry marenina! Mijere tsara, ry jamba!', 'mihainoa, ry marenina! mijere tsara, ry jamba!'),
  ('6ab25b7bf19bcd242783441f', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 17, 'Hitsoaka sady ho menatra tanteraka izy ireo, Dia izay mitoky amin’ny sary sokitra, Sy miteny amin’ny sarivongana metaly hoe: “Ianareo no andriamanitray.”', 'hitsoaka sady ho menatra tanteraka izy ireo, dia izay mitoky amin’ny sary sokitra, sy miteny amin’ny sarivongana metaly hoe: “ianareo no andriamanitray.”'),
  ('6ab25b7bf19bcd2427834422', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 20, 'Mahita zavatra maro ianao, nefa tsy raharahianao. Sokafanao ny sofinao, nefa tsy mihaino ianao.', 'mahita zavatra maro ianao, nefa tsy raharahianao. sokafanao ny sofinao, nefa tsy mihaino ianao.'),
  ('6ab25b7bf19bcd2427834417', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 9, 'Jereo fa efa tanteraka ny zavatra nolazaina taloha be, Fa milaza zava-baovao kosa aho izao. Mbola tsy mipoitra ireny, dia efa teneniko anareo.”', 'jereo fa efa tanteraka ny zavatra nolazaina taloha be, fa milaza zava-baovao kosa aho izao. mbola tsy mipoitra ireny, dia efa teneniko anareo.”'),
  ('6ab25b7bf19bcd2427834426', '2026-09-22T10:42:03.551Z', '2026-09-22T10:42:03.551Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 42, 24, 'Iza no nanolotra an’i Jakoba tamin’ny mpandroba, Sy nanolotra an’i Israely tamin’ny mpangalatra? Tsy i Jehovah ve? Nanota taminy mantsy izy ireo, Sady tsy nety nanaraka an’izay natorony, Ary tsy nankatò ny lalàny.', 'iza no nanolotra an’i jakoba tamin’ny mpandroba, sy nanolotra an’i israely tamin’ny mpangalatra? tsy i jehovah ve? nanota taminy mantsy izy ireo, sady tsy nety nanaraka an’izay natorony, ary tsy nankatò ny lalàny.'),
  ('6ab25b7cfc0a3c48716e0794', '2026-09-22T10:42:04.562Z', '2026-09-22T10:42:04.562Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 1, '“Mihainoa àry, ry Jakoba mpanompoko, Dia ianao ry Israely izay nofidiko.', '“mihainoa àry, ry jakoba mpanompoko, dia ianao ry israely izay nofidiko.'),
  ('6ab25b7cfc0a3c48716e0795', '2026-09-22T10:42:04.562Z', '2026-09-22T10:42:04.562Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 2, 'Izao no tenin’i Jehovah, Ilay Mpanao anao sy Ilay namolavola anao, Ilay nanampy anao hatrany am-bohoka: ‘Aza matahotra, ry Jakoba mpanompoko, Dia ianao ry Jesorona izay nofidiko.', 'izao no tenin’i jehovah, ilay mpanao anao sy ilay namolavola anao, ilay nanampy anao hatrany am-bohoka: ‘aza matahotra, ry jakoba mpanompoko, dia ianao ry jesorona izay nofidiko.'),
  ('6ab25b7cfc0a3c48716e079c', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 9, 'Tsy misy dikany daholo izay manamboatra sary sokitra, Ary tsy hisy hilana azy ny sampy mamin’ny fony. Vavolombelona ireny, nefa tsy mahita na inona na inona sady tsy mahalala na inona na inona, Ka ho menatra izay manao azy.', 'tsy misy dikany daholo izay manamboatra sary sokitra, ary tsy hisy hilana azy ny sampy mamin’ny fony. vavolombelona ireny, nefa tsy mahita na inona na inona sady tsy mahalala na inona na inona, ka ho menatra izay manao azy.'),
  ('6ab25b7cfc0a3c48716e0797', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 4, 'Dia handrobona toy ny ahi-maitso izy ireo, Hoatran’ny hazo aravaha eny amoron’ny renirano.', 'dia handrobona toy ny ahi-maitso izy ireo, hoatran’ny hazo aravaha eny amoron’ny renirano.'),
  ('6ab25b7cfc0a3c48716e07ac', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 25, 'Ataoko tsy tanteraka ny famantarana lazain’ny mpirediredy. Izaho Ilay mahatonga ny mpisikidy hanao hoatran’ny adala. Izaho koa Ilay mahatonga ny olon-kendry ho sahiran-tsaina, Ka manova ny zavatra hainy ho hadalana.', 'ataoko tsy tanteraka ny famantarana lazain’ny mpirediredy. izaho ilay mahatonga ny mpisikidy hanao hoatran’ny adala. izaho koa ilay mahatonga ny olon-kendry ho sahiran-tsaina, ka manova ny zavatra hainy ho hadalana.'),
  ('6ab25b7cfc0a3c48716e07aa', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 23, 'Mihobia sy mifalia, ry lanitra, Fa nanao zavatra i Jehovah! Manaova horakora-pandresena, ry faritra lalina amin’ny tany! Mifalia, ry tendrombohitra, Sy ny ala ary ny hazo rehetra! Fa efa navotan’i Jehovah i Jakoba, Ary asehony amin’i Israely ny voninahiny.”', 'mihobia sy mifalia, ry lanitra, fa nanao zavatra i jehovah! manaova horakora-pandresena, ry faritra lalina amin’ny tany! mifalia, ry tendrombohitra, sy ny ala ary ny hazo rehetra! fa efa navotan’i jehovah i jakoba, ary asehony amin’i israely ny voninahiny.”'),
  ('6ab25b7cfc0a3c48716e07a9', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 22, 'Hokosehiko ny fahadisoanao, toy ny hoe hosaronana rahona, Ary hokosehiko ny fahotanao, toy ny hoe hosaronana rahona matevina. Miverena amiko fa havotako ianao.', 'hokosehiko ny fahadisoanao, toy ny hoe hosaronana rahona, ary hokosehiko ny fahotanao, toy ny hoe hosaronana rahona matevina. miverena amiko fa havotako ianao.'),
  ('6ab25b7cfc0a3c48716e0796', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 3, 'Fa handatsahako rano izay mangetaheta, Ary hasiako renirano mikoriana any amin’ny tany karakaina. Handatsahako ny fanahiko ny taranakao, Sady handrotsahako fitahiana.', 'fa handatsahako rano izay mangetaheta, ary hasiako renirano mikoriana any amin’ny tany karakaina. handatsahako ny fanahiko ny taranakao, sady handrotsahako fitahiana.'),
  ('6ab25b7cfc0a3c48716e07ae', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 27, 'Izaho Ilay miteny amin’ny rano lalina hoe: ‘Miovà ho lasa etona, Dia hataoko ritra ny reniranonao rehetra.’', 'izaho ilay miteny amin’ny rano lalina hoe: ‘miovà ho lasa etona, dia hataoko ritra ny reniranonao rehetra.’'),
  ('6ab25b7cfc0a3c48716e07ad', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 26, 'Izaho Ilay manatanteraka ny tenin’ny mpanompoko, Sady manatanteraka amin’ny an-tsipiriany an’ireo faminaniana lazain’ny olona irahiko. Izaho koa Ilay miteny momba an’i Jerosalema hoe: ‘Honenana izy’, Ary momba an’ireo tanànan’i Joda hoe: ‘Haorina indray ireny. Haveriko hoatran’ny taloha indray izay toerana efa rava tao.’', 'izaho ilay manatanteraka ny tenin’ny mpanompoko, sady manatanteraka amin’ny an-tsipiriany an’ireo faminaniana lazain’ny olona irahiko. izaho koa ilay miteny momba an’i jerosalema hoe: ‘honenana izy’, ary momba an’ireo tanànan’i joda hoe: ‘haorina indray ireny. haveriko hoatran’ny taloha indray izay toerana efa rava tao.’'),
  ('6ab25b7cfc0a3c48716e07a1', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 14, 'Misy indray mpikapa hazo sedera. Mifantina hazo izy, dia hazo oaka, Ary avelany hitombo tsara miaraka amin’ny hazo any an’ala ilay izy. Mamboly hazo lorie koa izy, ary ny ranonorana no mampaniry azy.', 'misy indray mpikapa hazo sedera. mifantina hazo izy, dia hazo oaka, ary avelany hitombo tsara miaraka amin’ny hazo any an’ala ilay izy. mamboly hazo lorie koa izy, ary ny ranonorana no mampaniry azy.'),
  ('6ab25b7cfc0a3c48716e07a0', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 13, 'Ny mpanao sokitra hazo kosa manenjana ny tady fandrefesana. Soritany amin’ny lakire mena ny endrik’ilay sarivongana. Dia mampiasa fandraka izy, ary mampiasa kômpà mba hanaovana soritra eo amin’ilay hazo. Amboariny hitovy bika amin’ny olona ilay izy, Ka ataony tsara tarehy mitovy amin’ny olombelona, Mba hapetraka ao an-trano.', 'ny mpanao sokitra hazo kosa manenjana ny tady fandrefesana. soritany amin’ny lakire mena ny endrik’ilay sarivongana. dia mampiasa fandraka izy, ary mampiasa kômpà mba hanaovana soritra eo amin’ilay hazo. amboariny hitovy bika amin’ny olona ilay izy, ka ataony tsara tarehy mitovy amin’ny olombelona, mba hapetraka ao an-trano.'),
  ('6ab25b7cfc0a3c48716e07a5', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 18, 'Tsy mahalala na inona na inona izy sady tsy misy zavatra takany. Nakombona mantsy ny masony ka tsy mahita, Ary tsy mahay manavaka izy ireo.', 'tsy mahalala na inona na inona izy sady tsy misy zavatra takany. nakombona mantsy ny masony ka tsy mahita, ary tsy mahay manavaka izy ireo.'),
  ('6ab25b7cfc0a3c48716e07a6', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 19, 'Tsy mba misy mieritreritra mihitsy izy ireo ao am-pony, Ary tsy misy mahalala na mba misaina, ka miteny hoe: “Ny antsasany nodorako, Dia nanao mofo sy nitono hena teo ambonin’ny vainafo aho mba hohaniko. Dia izaho ve dia hanao zava-maharikoriko amin’ny ambin’ilay hazo? Izaho ve dia hivavaka amin’izay vatan-kazo?”', 'tsy mba misy mieritreritra mihitsy izy ireo ao am-pony, ary tsy misy mahalala na mba misaina, ka miteny hoe: “ny antsasany nodorako, dia nanao mofo sy nitono hena teo ambonin’ny vainafo aho mba hohaniko. dia izaho ve dia hanao zava-maharikoriko amin’ny ambin’ilay hazo? izaho ve dia hivavaka amin’izay vatan-kazo?”'),
  ('6ab25b7cfc0a3c48716e07a8', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 21, '“Tsarovy izany zavatra izany, ry Jakoba ô, dia ianao ry Israely ô, Satria mpanompoko ianao. Izaho no nanao anao, ka mpanompoko ianao. Tsy hohadinoiko ianao, ry Israely ô!', '“tsarovy izany zavatra izany, ry jakoba ô, dia ianao ry israely ô, satria mpanompoko ianao. izaho no nanao anao, ka mpanompoko ianao. tsy hohadinoiko ianao, ry israely ô!'),
  ('6ab25b7cfc0a3c48716e079f', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 12, 'Mampiasa ny fitaovany ny mpanefy, rehefa manefy an’ilay vy eo ambonin’ny afon-tsaribao. Amboariny amin’ny marotoa ilay izy, Ka mampiasa ny sandriny mahery izy amin’izany. Noana anefa izy avy eo ka mihareraka. Tsy misotro rano izy ka vizana.', 'mampiasa ny fitaovany ny mpanefy, rehefa manefy an’ilay vy eo ambonin’ny afon-tsaribao. amboariny amin’ny marotoa ilay izy, ka mampiasa ny sandriny mahery izy amin’izany. noana anefa izy avy eo ka mihareraka. tsy misotro rano izy ka vizana.'),
  ('6ab25b7cfc0a3c48716e07af', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 28, 'Izaho Ilay miteny momba an’i Kyrosy hoe: ‘Izy no mpiandry ondriko, Ka hotanterahiny an-tsakany sy an-davany ny sitrapoko rehetra.’ Izaho Ilay miteny momba an’i Jerosalema hoe: ‘Haorina indray izy’, Ary momba ny tempoly hoe: ‘Hapetraka ny fototrao.’”', 'izaho ilay miteny momba an’i kyrosy hoe: ‘izy no mpiandry ondriko, ka hotanterahiny an-tsakany sy an-davany ny sitrapoko rehetra.’ izaho ilay miteny momba an’i jerosalema hoe: ‘haorina indray izy’, ary momba ny tempoly hoe: ‘hapetraka ny fototrao.’”'),
  ('6ab25b7cfc0a3c48716e079b', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 8, 'Aza matahotra, Ary aza manaiky ho resin’ny tahotra. Angaha tsy efa nilazako mialoha ianareo tsirairay? Ary angaha tsy efa noteneniko izany? Ianareo no vavolombeloko. Misy Andriamanitra hafa ankoatra ahy ve? Tsia, tsy misy Vatolampy hafa. Tsy mahafantatra aho na iray aza.’”', 'aza matahotra, ary aza manaiky ho resin’ny tahotra. angaha tsy efa nilazako mialoha ianareo tsirairay? ary angaha tsy efa noteneniko izany? ianareo no vavolombeloko. misy andriamanitra hafa ankoatra ahy ve? tsia, tsy misy vatolampy hafa. tsy mahafantatra aho na iray aza.’”'),
  ('6ab25b7cfc0a3c48716e07a7', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 20, 'Lavenona no ataony sakafo. Voafitaka ny fony ka lasa manao ratsy izy. Tsy afaka mamonjy ny ainy izy, sady tsy miteny hoe: “Tsy fitaka fotsiny ve ity eto amin’ny tanako ankavanana ity?”', 'lavenona no ataony sakafo. voafitaka ny fony ka lasa manao ratsy izy. tsy afaka mamonjy ny ainy izy, sady tsy miteny hoe: “tsy fitaka fotsiny ve ity eto amin’ny tanako ankavanana ity?”'),
  ('6ab25b7cfc0a3c48716e07a3', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 16, 'Dorany ny antsasak’ilay hazo, Dia itonoany hena hohaniny, ka voky izy. Mitanina afo eo koa izy ka miteny hoe: “Mafana erỳ aho izany mijery an’ity afo ity!”', 'dorany ny antsasak’ilay hazo, dia itonoany hena hohaniny, ka voky izy. mitanina afo eo koa izy ka miteny hoe: “mafana erỳ aho izany mijery an’ity afo ity!”'),
  ('6ab25b7cfc0a3c48716e079e', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 11, 'Ho menatra daholo ny mpiara-miasa aminy. Olombelona ihany mantsy ireo mpanao asa tanana. Asaivo mivory izy rehetra dia maka toerana. Ho raiki-tahotra izy ireo sady ho menatra daholo.', 'ho menatra daholo ny mpiara-miasa aminy. olombelona ihany mantsy ireo mpanao asa tanana. asaivo mivory izy rehetra dia maka toerana. ho raiki-tahotra izy ireo sady ho menatra daholo.'),
  ('6ab25b7cfc0a3c48716e079d', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 10, 'Iza no hanamboatra andriamanitra, Na handrendrika metaly hanaovana sarivongana tsy misy ilana azy?', 'iza no hanamboatra andriamanitra, na handrendrika metaly hanaovana sarivongana tsy misy ilana azy?'),
  ('6ab25b7cfc0a3c48716e0799', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 6, 'Izao no tenin’i Jehovah, Dia i Jehovah Tompon’ny Tafika, ilay Mpanjakan’ny Israely sy Mpanavotra azy: ‘Izaho no voalohany ary izaho no farany. Tsy misy Andriamanitra afa-tsy izaho.', 'izao no tenin’i jehovah, dia i jehovah tompon’ny tafika, ilay mpanjakan’ny israely sy mpanavotra azy: ‘izaho no voalohany ary izaho no farany. tsy misy andriamanitra afa-tsy izaho.'),
  ('6ab25b7cfc0a3c48716e07ab', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 24, 'Izao no tenin’i Jehovah, ilay Mpanavotra anao, Dia ilay namolavola anao hatrany an-kibo: “Izaho no Jehovah, ilay nanao ny zava-drehetra. Izaho irery no namelatra ny lanitra Sy namelatra ny tany. Iza no nanampy ahy tamin’izany?', 'izao no tenin’i jehovah, ilay mpanavotra anao, dia ilay namolavola anao hatrany an-kibo: “izaho no jehovah, ilay nanao ny zava-drehetra. izaho irery no namelatra ny lanitra sy namelatra ny tany. iza no nanampy ahy tamin’izany?'),
  ('6ab25b7cfc0a3c48716e079a', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 7, 'Iza no mitovy amiko? Asaivo mamaly izy ka hiteny sy hanaporofo an’izany amiko. Hatramin’ny andro namoronako ny vahoaka fahiny, Dia iza no afaka milaza an’izay hitranga tsy ho ela, Sy izay mbola hitranga amin’ny hoavy?', 'iza no mitovy amiko? asaivo mamaly izy ka hiteny sy hanaporofo an’izany amiko. hatramin’ny andro namoronako ny vahoaka fahiny, dia iza no afaka milaza an’izay hitranga tsy ho ela, sy izay mbola hitranga amin’ny hoavy?'),
  ('6ab25b7cfc0a3c48716e07a2', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 15, 'Ataon’olona kitay andrehetana afo anefa ilay izy avy eo. Akany ilay izy dia eo izy no mitanina afo. Mampirehitra afo izy dia manao mofo. Manamboatra andriamanitra koa anefa izy dia mivavaka amin’izany. Ataony sary sokitra izany dia iankohofany.', 'ataon’olona kitay andrehetana afo anefa ilay izy avy eo. akany ilay izy dia eo izy no mitanina afo. mampirehitra afo izy dia manao mofo. manamboatra andriamanitra koa anefa izy dia mivavaka amin’izany. ataony sary sokitra izany dia iankohofany.'),
  ('6ab25b7cfc0a3c48716e0798', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 5, 'Ny iray hiteny hoe: “An’i Jehovah aho.” Ny anankiray indray hanao ny anarany hoe Jakoba, Ary ny anankiray kosa hanoratra eo amin’ny tanany hoe: “An’i Jehovah.” Dia hataony hoe Israely ny anarany.’', 'ny iray hiteny hoe: “an’i jehovah aho.” ny anankiray indray hanao ny anarany hoe jakoba, ary ny anankiray kosa hanoratra eo amin’ny tanany hoe: “an’i jehovah.” dia hataony hoe israely ny anarany.’'),
  ('6ab25b7cfc0a3c48716e07a4', '2026-09-22T10:42:04.563Z', '2026-09-22T10:42:04.563Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 44, 17, 'Ny ambiny kosa anamboarany andriamanitra ka ataony sary sokitra. Iankohofany ilay izy dia ivavahany. Dia mivavaka aminy izy hoe: “Vonjeo aho fa ianao no andriamanitro.”', 'ny ambiny kosa anamboarany andriamanitra ka ataony sary sokitra. iankohofany ilay izy dia ivavahany. dia mivavaka aminy izy hoe: “vonjeo aho fa ianao no andriamanitro.”'),
  ('6ab25b7def27ba1d1fbcd878', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 17, 'Fa hovonjen’i Jehovah mandrakizay kosa ianareo ry Israely. Tsy ho menatra na ho afa-baraka ianareo mandrakizay.', 'fa hovonjen’i jehovah mandrakizay kosa ianareo ry israely. tsy ho menatra na ho afa-baraka ianareo mandrakizay.'),
  ('6ab25b7def27ba1d1fbcd875', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 14, 'Izao no tenin’i Jehovah: “Ho tonga any aminao ka ho lasanao ny tombony azon’i Ejipta, Sy ny entam-barotr’i Etiopia, ary ny Sabeanina avo ranjanana. Handeha ao aorianao izy ireo, sady mifatotra rojo vy. Ho tonga izy ireo ka hiankohoka eo anatrehanao. Hanaja anao izy ireo ka hiteny hoe: ‘Manampy anao tokoa Andriamanitra. Tsy misy ankoatra azy, ary tsy misy Andriamanitra afa-tsy izy.’”', 'izao no tenin’i jehovah: “ho tonga any aminao ka ho lasanao ny tombony azon’i ejipta, sy ny entam-barotr’i etiopia, ary ny sabeanina avo ranjanana. handeha ao aorianao izy ireo, sady mifatotra rojo vy. ho tonga izy ireo ka hiankohoka eo anatrehanao. hanaja anao izy ireo ka hiteny hoe: ‘manampy anao tokoa andriamanitra. tsy misy ankoatra azy, ary tsy misy andriamanitra afa-tsy izy.’”'),
  ('6ab25b7def27ba1d1fbcd870', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 9, 'Hahita loza izay miady amin’ny Mpanao azy! Vakim-bilany tanimanga fotsiny mantsy izy, Miaraka amin’ny vakim-bilany hafa eo amin’ny tany. Ny tanimanga ve dia hilaza amin’ny Mpanefy hoe: “Fa inona koa ity amboarinao?” Ary ny zavatra namboarinao ve dia hiteny hoe: “Tsy manan-tanana ianao”?', 'hahita loza izay miady amin’ny mpanao azy! vakim-bilany tanimanga fotsiny mantsy izy, miaraka amin’ny vakim-bilany hafa eo amin’ny tany. ny tanimanga ve dia hilaza amin’ny mpanefy hoe: “fa inona koa ity amboarinao?” ary ny zavatra namboarinao ve dia hiteny hoe: “tsy manan-tanana ianao”?'),
  ('6ab25b7def27ba1d1fbcd868', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 1, 'Izao no tenin’i Jehovah amin’ilay voahosotra notendreny, dia i Kyrosy, Ilay notantanako tamin’ny tanany ankavanana, Mba handresy firenena eo alohany, Sy hanala ny fiadiana eny amin’ny mpanjaka, Ary mba hanokatra ny varavarana kopa-droa eo anoloany, Amin’izay tsy hakatona ny vavahady:', 'izao no tenin’i jehovah amin’ilay voahosotra notendreny, dia i kyrosy, ilay notantanako tamin’ny tanany ankavanana, mba handresy firenena eo alohany, sy hanala ny fiadiana eny amin’ny mpanjaka, ary mba hanokatra ny varavarana kopa-droa eo anoloany, amin’izay tsy hakatona ny vavahady:'),
  ('6ab25b7def27ba1d1fbcd87f', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 24, 'Hilaza koa izy ireo hoe: ‘Manao ny rariny sy mahery foana i Jehovah. Ho tonga eo anatrehany sady ho menatra izay rehetra tezitra aminy.', 'hilaza koa izy ireo hoe: ‘manao ny rariny sy mahery foana i jehovah. ho tonga eo anatrehany sady ho menatra izay rehetra tezitra aminy.'),
  ('6ab25b7def27ba1d1fbcd87b', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 20, 'Mivoria ka avia! Manatòna daholo ianareo afa-nandositra avy any amin’ireo firenena. Tsy mahafantatra na inona na inona ireo mitondra sary sokitra mandehandeha, Sy mivavaka amin’andriamanitra tsy mahavonjy azy.', 'mivoria ka avia! manatòna daholo ianareo afa-nandositra avy any amin’ireo firenena. tsy mahafantatra na inona na inona ireo mitondra sary sokitra mandehandeha, sy mivavaka amin’andriamanitra tsy mahavonjy azy.'),
  ('6ab25b7def27ba1d1fbcd87e', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 23, 'Nianiana tamin’ny tenako aho, Ary marina ny teny navoakan’ny vavako, Ka tsy maintsy ho tanteraka: Handohalika eo anatrehako ny olona rehetra, Ary hianiana amiko hoe tsy hivadika.', 'nianiana tamin’ny tenako aho, ary marina ny teny navoakan’ny vavako, ka tsy maintsy ho tanteraka: handohalika eo anatrehako ny olona rehetra, ary hianiana amiko hoe tsy hivadika.'),
  ('6ab25b7def27ba1d1fbcd86c', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 5, 'Izaho no Jehovah, ary tsy misy hafa. Tsy misy Andriamanitra afa-tsy izaho. Homeko hery ianao na dia tsy fantatrao aza aho.', 'izaho no jehovah, ary tsy misy hafa. tsy misy andriamanitra afa-tsy izaho. homeko hery ianao na dia tsy fantatrao aza aho.'),
  ('6ab25b7def27ba1d1fbcd87c', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 21, 'Manaova tatitra ka resaho ny adinareo, Dia avelao izy ireo hiara-mikaon-doha. Iza no efa nilaza an’izany taloha ela be, Sy niteny an’izany efa hatry ny ela be? Tsy izaho Jehovah ve? Tsy misy Andriamanitra afa-tsy izaho. Tsy misy Andriamanitra manao ny rariny sy Mpamonjy ankoatra ahy.', 'manaova tatitra ka resaho ny adinareo, dia avelao izy ireo hiara-mikaon-doha. iza no efa nilaza an’izany taloha ela be, sy niteny an’izany efa hatry ny ela be? tsy izaho jehovah ve? tsy misy andriamanitra afa-tsy izaho. tsy misy andriamanitra manao ny rariny sy mpamonjy ankoatra ahy.'),
  ('6ab25b7def27ba1d1fbcd86a', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 3, 'Dia homeko anao ny harena voatahiry ao amin’ny haizina, Sy ny harena afenina ao amin’ny toerana miafina. Amin’izay ho fantatrao fa izaho no Jehovah, Ilay Andriamanitry ny Israely, izay miantso anao amin’ny anaranao.', 'dia homeko anao ny harena voatahiry ao amin’ny haizina, sy ny harena afenina ao amin’ny toerana miafina. amin’izay ho fantatrao fa izaho no jehovah, ilay andriamanitry ny israely, izay miantso anao amin’ny anaranao.'),
  ('6ab25b7def27ba1d1fbcd877', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 16, 'Ho menatra sy ho afa-baraka daholo izy ireo. Handeha sady ho afa-baraka daholo ny mpanamboatra sampy.', 'ho menatra sy ho afa-baraka daholo izy ireo. handeha sady ho afa-baraka daholo ny mpanamboatra sampy.'),
  ('6ab25b7def27ba1d1fbcd873', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 12, 'Nanao ny tany sy namorona ny olona eo amboniny aho. Namelatra ny lanitra tamin’ny tanako aho, Ary manome baiko ny tafiny manontolo.”', 'nanao ny tany sy namorona ny olona eo amboniny aho. namelatra ny lanitra tamin’ny tanako aho, ary manome baiko ny tafiny manontolo.”'),
  ('6ab25b7def27ba1d1fbcd87d', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 22, 'Mitadiava ahy, dia ho voavonjy ianareo rehetra any amin’ny faran’ny tany, Fa izaho no Andriamanitra, ary tsy misy hafa.', 'mitadiava ahy, dia ho voavonjy ianareo rehetra any amin’ny faran’ny tany, fa izaho no andriamanitra, ary tsy misy hafa.'),
  ('6ab25b7def27ba1d1fbcd86f', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 8, 'Mandrotsaha orana avy any ambony, ry lanitra! Aoka handrotsaka fahamarinana ny rahona. Aoka hisokatra koa ny tany ka hamokatra famonjena, Sady hampitsiry fahamarinana. Izaho Jehovah no namorona an’izany.”', 'mandrotsaha orana avy any ambony, ry lanitra! aoka handrotsaka fahamarinana ny rahona. aoka hisokatra koa ny tany ka hamokatra famonjena, sady hampitsiry fahamarinana. izaho jehovah no namorona an’izany.”'),
  ('6ab25b7def27ba1d1fbcd87a', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 19, 'Tsy tao amin’ny toerana miafina tany amin’ny tanin’ny haizina aho no niteny. Tsy niteny tamin’ny taranak’i Jakoba aho hoe: ‘Mitadiava ahy, nefa ho very maina izany ezaka ataonareo izany.’ Izaho no Jehovah, ary milaza ny marina sy miteny izay mahitsy aho.', 'tsy tao amin’ny toerana miafina tany amin’ny tanin’ny haizina aho no niteny. tsy niteny tamin’ny taranak’i jakoba aho hoe: ‘mitadiava ahy, nefa ho very maina izany ezaka ataonareo izany.’ izaho no jehovah, ary milaza ny marina sy miteny izay mahitsy aho.'),
  ('6ab25b7def27ba1d1fbcd879', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 18, 'Fa izao no tenin’i Jehovah, Ilay Mpamorona ny lanitra, Ilay tena Andriamanitra, Ilay namolavola ny tany sady Mpanao azy ka nanao azy ho mafy orina, Ary tsy hoe tsy misy antony ny namoronany azy fa nataony honenana: “Izaho no Jehovah, ary tsy misy hafa.', 'fa izao no tenin’i jehovah, ilay mpamorona ny lanitra, ilay tena andriamanitra, ilay namolavola ny tany sady mpanao azy ka nanao azy ho mafy orina, ary tsy hoe tsy misy antony ny namoronany azy fa nataony honenana: “izaho no jehovah, ary tsy misy hafa.'),
  ('6ab25b7def27ba1d1fbcd86e', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 7, 'Manao ny hazavana sy mamorona ny haizina aho, Ary mampisy fiadanana sy mahatonga loza. Izaho Jehovah no manao an’izany rehetra izany.', 'manao ny hazavana sy mamorona ny haizina aho, ary mampisy fiadanana sy mahatonga loza. izaho jehovah no manao an’izany rehetra izany.'),
  ('6ab25b7def27ba1d1fbcd880', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 25, 'Ho tsapan’ny taranak’Israely rehetra fa nety ny nanompo an’i Jehovah, Ary izy no ho reharehan’izy ireo.’”', 'ho tsapan’ny taranak’israely rehetra fa nety ny nanompo an’i jehovah, ary izy no ho reharehan’izy ireo.’”'),
  ('6ab25b7def27ba1d1fbcd871', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 10, 'Hahita loza izay milaza amin’ny rainy hoe: “Inona ity naterakao?”, Sy miteny amin’ny reniny hoe: “Fa miteraka inona koa ity ianao?”', 'hahita loza izay milaza amin’ny rainy hoe: “inona ity naterakao?”, sy miteny amin’ny reniny hoe: “fa miteraka inona koa ity ianao?”'),
  ('6ab25b7def27ba1d1fbcd874', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 13, '“Nampirisika lehilahy iray aho, satria manao ny rariny. Hataoko mahitsy ny lalany rehetra. Izy no hanorina ny tanànako, Sy hanafaka ny vahoakako any an-tsesitany, nefa tsy hoe homena vola na tsolotra izy”, hoy i Jehovah Tompon’ny tafika.', '“nampirisika lehilahy iray aho, satria manao ny rariny. hataoko mahitsy ny lalany rehetra. izy no hanorina ny tanànako, sy hanafaka ny vahoakako any an-tsesitany, nefa tsy hoe homena vola na tsolotra izy”, hoy i jehovah tompon’ny tafika.'),
  ('6ab25b7def27ba1d1fbcd86d', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 6, 'Amin’izay ho fantatry ny olona Hatrany amin’ny fiposahan’ny masoandro ka hatrany amin’ny filentehany, Fa tsy misy afa-tsy izaho. Izaho no Jehovah, ary tsy misy hafa.', 'amin’izay ho fantatry ny olona hatrany amin’ny fiposahan’ny masoandro ka hatrany amin’ny filentehany, fa tsy misy afa-tsy izaho. izaho no jehovah, ary tsy misy hafa.'),
  ('6ab25b7def27ba1d1fbcd869', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 2, '“Handeha eo alohanao aho, Ka hataoko mitovy tantana ny havoana. Hopotipotehiko ny vavahady varahina, Ary hotapahiko ny bara hidiny vy.', '“handeha eo alohanao aho, ka hataoko mitovy tantana ny havoana. hopotipotehiko ny vavahady varahina, ary hotapahiko ny bara hidiny vy.'),
  ('6ab25b7def27ba1d1fbcd876', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 15, 'Andriamanitra miafina tokoa ianao, Ry Andriamanitry ny Israely sy Mpamonjy!', 'andriamanitra miafina tokoa ianao, ry andriamanitry ny israely sy mpamonjy!'),
  ('6ab25b7def27ba1d1fbcd872', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 11, 'Izao no tenin’i Jehovah, Ilay Masin’ny Israely sy Ilay namolavola azy: “Ianao ve dia hiady hevitra amiko momba ny zavatra hitranga, Ary hibaiko ahy ny amin’izay tokony hataoko amin’ny zanako sy ny asan’ny tanako?', 'izao no tenin’i jehovah, ilay masin’ny israely sy ilay namolavola azy: “ianao ve dia hiady hevitra amiko momba ny zavatra hitranga, ary hibaiko ahy ny amin’izay tokony hataoko amin’ny zanako sy ny asan’ny tanako?'),
  ('6ab25b7def27ba1d1fbcd86b', '2026-09-22T10:42:05.393Z', '2026-09-22T10:42:05.393Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 45, 4, 'Antsoiko amin’ny anaranao ianao, Noho ny amin’i Jakoba mpanompoko sy Israely izay nofidiko. Omeko anarana be voninahitra ianao, na dia tsy nahafantatra ahy akory aza.', 'antsoiko amin’ny anaranao ianao, noho ny amin’i jakoba mpanompoko sy israely izay nofidiko. omeko anarana be voninahitra ianao, na dia tsy nahafantatra ahy akory aza.'),
  ('6ab25b80b8734cd82907f500', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 14, 'Hoatran’ny vodivary izy ireo, Ka ho kilan’ny afo. Tsy mahavonjy ny tenany tsy ho main’ny lelafo izy ireo. Tsy vainafo natao hampahafana izany, Ary tsy afo natao hamindroana.', 'hoatran’ny vodivary izy ireo, ka ho kilan’ny afo. tsy mahavonjy ny tenany tsy ho main’ny lelafo izy ireo. tsy vainafo natao hampahafana izany, ary tsy afo natao hamindroana.'),
  ('6ab25b80b8734cd82907f4fc', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 10, 'Nitoky tamin’ny faharatsianao ianao. Dia hoy ianao: “Tsy misy mahita ahy.” Ny fahendrenao sy ny fahalalanao no mahatonga anao ho diso lalana. Hoy koa ianao anakampo: “Izaho no izy, ary tsy misy hafa.”', 'nitoky tamin’ny faharatsianao ianao. dia hoy ianao: “tsy misy mahita ahy.” ny fahendrenao sy ny fahalalanao no mahatonga anao ho diso lalana. hoy koa ianao anakampo: “izaho no izy, ary tsy misy hafa.”'),
  ('6ab25b80b8734cd82907f4fa', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 8, 'Henoy izao, ry ilay tia fahafinaretana, Dia ilay mipetraka tsy manana ahiahy, sy manao anakampo hoe: “Izaho no izy, ary tsy misy hafa. Tsy ho lasa mpitondratena aho, Ary tsy mba hiaina an’izany hoe maty zanaka izany mihitsy.”', 'henoy izao, ry ilay tia fahafinaretana, dia ilay mipetraka tsy manana ahiahy, sy manao anakampo hoe: “izaho no izy, ary tsy misy hafa. tsy ho lasa mpitondratena aho, ary tsy mba hiaina an’izany hoe maty zanaka izany mihitsy.”'),
  ('6ab25b80b8734cd82907f501', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 15, 'Ho toy izany àry ireny mpilalao ody eo aminao ireny, Dia ireo niara-nisasatra taminao hatramin’ianao mbola tanora. Hirenireny izy ireny, ka samy ho any amin’izay alehany. Ary tsy hisy hamonjy ianao.', 'ho toy izany àry ireny mpilalao ody eo aminao ireny, dia ireo niara-nisasatra taminao hatramin’ianao mbola tanora. hirenireny izy ireny, ka samy ho any amin’izay alehany. ary tsy hisy hamonjy ianao.'),
  ('6ab25b80b8734cd82907f4fd', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 11, 'Ho tratran’ny loza anefa ianao, Ary tsy hisy hahasakana an’izany ny ody ampiasainao. Ho tratran’ny fahoriana ianao, ary tsy hahavita hisakana an’izany. Hisy faharavana tampoka hanjo anao, dia zavatra mbola tsy niainanao mihitsy.', 'ho tratran’ny loza anefa ianao, ary tsy hisy hahasakana an’izany ny ody ampiasainao. ho tratran’ny fahoriana ianao, ary tsy hahavita hisakana an’izany. hisy faharavana tampoka hanjo anao, dia zavatra mbola tsy niainanao mihitsy.'),
  ('6ab25b80b8734cd82907f4fe', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 12, 'Tohizo foana àry ny fampiasanao famosaviana sy ody be dia be, Dia izay efa nisasaranao hatramin’ianao mbola tanora. Sao mantsy ianao mba hahita soa amin’izany, Ary sao ianao mba hahavita hampatahotra olona.', 'tohizo foana àry ny fampiasanao famosaviana sy ody be dia be, dia izay efa nisasaranao hatramin’ianao mbola tanora. sao mantsy ianao mba hahita soa amin’izany, ary sao ianao mba hahavita hampatahotra olona.'),
  ('6ab25b80b8734cd82907f4f7', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 5, 'Mipetraha eo ianao ary mangìna, ka mijanòna ao amin’ny haizina, Ry zanakavavin’ny Kaldeanina ô! Tsy hantsoin’ny olona intsony hoe Tompovavin’ireo Fanjakana ianao.', 'mipetraha eo ianao ary mangìna, ka mijanòna ao amin’ny haizina, ry zanakavavin’ny kaldeanina ô! tsy hantsoin’ny olona intsony hoe tompovavin’ireo fanjakana ianao.'),
  ('6ab25b80b8734cd82907f4f6', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 4, '“Ilay Masin’ny Israely No Mpanavotra antsika. Jehovah Tompon’ny tafika no anarany.”', '“ilay masin’ny israely no mpanavotra antsika. jehovah tompon’ny tafika no anarany.”'),
  ('6ab25b80b8734cd82907f4f5', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 3, 'Haseho ny fitanjahanao, Ary hatao miharihary ny faritra mahamenatra amin’ny vatanao. Hamaly faty aho, ka tsy hisy hahasakana ahy.', 'haseho ny fitanjahanao, ary hatao miharihary ny faritra mahamenatra amin’ny vatanao. hamaly faty aho, ka tsy hisy hahasakana ahy.'),
  ('6ab25b80b8734cd82907f4f8', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 6, 'Tezitra tamin’ny vahoakako aho. Nataoko tsinontsinona ny lovako, Ka navelako ho resinao. Tsy niantra azy ireo mihitsy anefa ianao, Fa na ny zokiolona aza nampitondrainao zioga mavesatra be.', 'tezitra tamin’ny vahoakako aho. nataoko tsinontsinona ny lovako, ka navelako ho resinao. tsy niantra azy ireo mihitsy anefa ianao, fa na ny zokiolona aza nampitondrainao zioga mavesatra be.'),
  ('6ab25b80b8734cd82907f4fb', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 9, 'Hanjo anao tampoka ao anatin’ny indray andro anefa ireto zavatra roa ireto: Ho faty ny zanakao, ary ho lasa mpitondratena ianao. Tena hanjo anao daholo izany, Satria ianao mampiasa ody be dia be sy famosaviana mahery.', 'hanjo anao tampoka ao anatin’ny indray andro anefa ireto zavatra roa ireto: ho faty ny zanakao, ary ho lasa mpitondratena ianao. tena hanjo anao daholo izany, satria ianao mampiasa ody be dia be sy famosaviana mahery.'),
  ('6ab25b80b8734cd82907f4f9', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 7, 'Hoy ianao: “Ho Tompovavy foana aho mandrakizay.” Tsy noraisinao am-po ireny zavatra nataonao ireny, Ary tsy nosaintsaininao izay hiafarany.', 'hoy ianao: “ho tompovavy foana aho mandrakizay.” tsy noraisinao am-po ireny zavatra nataonao ireny, ary tsy nosaintsaininao izay hiafarany.'),
  ('6ab25b80b8734cd82907f4ff', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 13, 'Lasa nankaleo anao ny mpanolo-tsaina be dia be eo aminao. Asaivo mitsangana hamonjy anao ireny izao, Dia ireo mivavaka amin’ny lanitra, izay mandinika ny kintana, Ka mampahafantatra anao isaky ny tsinam-bolana Momba an’izay hitranga aminao.', 'lasa nankaleo anao ny mpanolo-tsaina be dia be eo aminao. asaivo mitsangana hamonjy anao ireny izao, dia ireo mivavaka amin’ny lanitra, izay mandinika ny kintana, ka mampahafantatra anao isaky ny tsinam-bolana momba an’izay hitranga aminao.'),
  ('6ab25b80b8734cd82907f4f4', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 2, 'Makà vato fikosoham-bary ka mitotoa koba. Esory ny voalinao. Akaro ny akanjonao dia asehoy ny fe, Ary miampità ny renirano.', 'makà vato fikosoham-bary ka mitotoa koba. esory ny voalinao. akaro ny akanjonao dia asehoy ny fe, ary miampità ny renirano.'),
  ('6ab25b80b8734cd82907f4f3', '2026-09-22T10:42:08.233Z', '2026-09-22T10:42:08.233Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 47, 1, 'Midìna ambany ka mipetraha amin’ny vovoka, Ry Babylona zanakavavy virjiny ô! Mipetraha amin’ny tany, eo amin’izay tsy misy seza fiandrianana, Ry zanakavavin’ny Kaldeanina ô! Tsy hantsoin’ny olona intsony hoe miaingitraingitra sy ampihantaina mantsy ianao.', 'midìna ambany ka mipetraha amin’ny vovoka, ry babylona zanakavavy virjiny ô! mipetraha amin’ny tany, eo amin’izay tsy misy seza fiandrianana, ry zanakavavin’ny kaldeanina ô! tsy hantsoin’ny olona intsony hoe miaingitraingitra sy ampihantaina mantsy ianao.'),
  ('6ab25b816875f5c54840c3d2', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 21, 'Tsy nangetaheta mihitsy izy ireo, tamin’izy nitarika azy ireo namakivaky tany ngazana. Nataony namoaka rano ny vatolampy mba hosotroin’izy ireo, Ary nataony nitresaka ny vatolampy mba hisy rano hiboiboika be.”', 'tsy nangetaheta mihitsy izy ireo, tamin’izy nitarika azy ireo namakivaky tany ngazana. nataony namoaka rano ny vatolampy mba hosotroin’izy ireo, ary nataony nitresaka ny vatolampy mba hisy rano hiboiboika be.”'),
  ('6ab25b816875f5c54840c3d0', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 19, 'Ho be dia be hoatran’ny fasika ny taranakao, Ary ho maro be hoatran’ny vovo-pasika. Tsy hovonoina na hofafana eo anatrehako mihitsy ny anaran’izy ireo.”', 'ho be dia be hoatran’ny fasika ny taranakao, ary ho maro be hoatran’ny vovo-pasika. tsy hovonoina na hofafana eo anatrehako mihitsy ny anaran’izy ireo.”'),
  ('6ab25b816875f5c54840c3cf', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 18, 'Raha mba mankatò ny didiko mantsy ianao, Dia ho lasa toy ny renirano ny fiadananao Ary ho lasa hoatran’ny onjan-dranomasina ny fahamarinanao!', 'raha mba mankatò ny didiko mantsy ianao, dia ho lasa toy ny renirano ny fiadananao ary ho lasa hoatran’ny onjan-dranomasina ny fahamarinanao!'),
  ('6ab25b816875f5c54840c3be', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 1, 'Henoy izao, ry taranak’i Jakoba, Dia ianareo izay miantso ny tenanareo hoe Israely, Sy ianareo nipoitra avy tamin’ny ranon’i Joda. Dia ianareo mianiana amin’ny anaran’i Jehovah, Sady miantso an’ilay Andriamanitry ny Israely, Nefa tsy manao an’izany amin’ny fo madio sady tsy manao ny tsara.', 'henoy izao, ry taranak’i jakoba, dia ianareo izay miantso ny tenanareo hoe israely, sy ianareo nipoitra avy tamin’ny ranon’i joda. dia ianareo mianiana amin’ny anaran’i jehovah, sady miantso an’ilay andriamanitry ny israely, nefa tsy manao an’izany amin’ny fo madio sady tsy manao ny tsara.'),
  ('6ab25b816875f5c54840c3bf', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 2, 'Fa mihambo ho avy amin’ilay tanàna masina ianareo, Ary mitady fanampiana any amin’ny Andriamanitry ny Israely, Ilay manana anarana hoe Jehovah Tompon’ny tafika.', 'fa mihambo ho avy amin’ilay tanàna masina ianareo, ary mitady fanampiana any amin’ny andriamanitry ny israely, ilay manana anarana hoe jehovah tompon’ny tafika.'),
  ('6ab25b816875f5c54840c3d1', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 20, 'Mivoaha avy ao Babylona! Andosiro ny Kaldeanina! Lazao sy ambarao amin’ny olona izany sady mifalia. Ataovy fantatry ny olona hatrany amin’ny faran’ny tany izany, Dia teneno hoe: “Navotan’i Jehovah i Jakoba mpanompony.', 'mivoaha avy ao babylona! andosiro ny kaldeanina! lazao sy ambarao amin’ny olona izany sady mifalia. ataovy fantatry ny olona hatrany amin’ny faran’ny tany izany, dia teneno hoe: “navotan’i jehovah i jakoba mpanompony.'),
  ('6ab25b816875f5c54840c3cc', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 15, 'Izaho no nilaza an’izany, ary izaho no niantso azy. Izaho no nitondra azy, ary hahomby izay ataony.', 'izaho no nilaza an’izany, ary izaho no niantso azy. izaho no nitondra azy, ary hahomby izay ataony.'),
  ('6ab25b816875f5c54840c3c5', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 8, 'Tena mbola tsy henonao izany sady tsy fantatrao, Ary taloha dia tsy nisokatra ny sofinao. Fantatro mantsy fa tena mpivadika ianao, Sady efa hatramin’ny vao teraka ianao no nantsoina hoe mpandika lalàna.', 'tena mbola tsy henonao izany sady tsy fantatrao, ary taloha dia tsy nisokatra ny sofinao. fantatro mantsy fa tena mpivadika ianao, sady efa hatramin’ny vao teraka ianao no nantsoina hoe mpandika lalàna.'),
  ('6ab25b816875f5c54840c3c3', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 6, 'Efa henonao sy hitanao daholo izany, Dia tsy horesahinao ve? Hilaza zava-baovao aminao aho manomboka izao, Dia tsiambaratelo nafenina ka mbola tsy fantatrao mihitsy.', 'efa henonao sy hitanao daholo izany, dia tsy horesahinao ve? hilaza zava-baovao aminao aho manomboka izao, dia tsiambaratelo nafenina ka mbola tsy fantatrao mihitsy.'),
  ('6ab25b816875f5c54840c3ce', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 17, 'Izao no tenin’i Jehovah Mpanavotra anao, Ilay Masin’ny Israely: “Izaho Jehovah no Andriamanitrao, Ilay mampianatra anao mba hahitanao soa, Ilay mitarika anao any amin’izay lalana tokony halehanao.', 'izao no tenin’i jehovah mpanavotra anao, ilay masin’ny israely: “izaho jehovah no andriamanitrao, ilay mampianatra anao mba hahitanao soa, ilay mitarika anao any amin’izay lalana tokony halehanao.'),
  ('6ab25b816875f5c54840c3c1', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 4, 'Fantatro mantsy fa mafy loha ianao. Vy ny hozatry ny hatokao ary varahina ny handrinao.', 'fantatro mantsy fa mafy loha ianao. vy ny hozatry ny hatokao ary varahina ny handrinao.'),
  ('6ab25b816875f5c54840c3d3', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 22, '“Tsy misy fiadanana ho an’ny ratsy fanahy”, hoy i Jehovah.', '“tsy misy fiadanana ho an’ny ratsy fanahy”, hoy i jehovah.'),
  ('6ab25b816875f5c54840c3ca', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 13, 'Ny tanako no nametraka ny fototry ny tany, Ary ny tanako ankavanana no namelatra ny lanitra. Rehefa antsoiko izy ireo dia mitsangana daholo.', 'ny tanako no nametraka ny fototry ny tany, ary ny tanako ankavanana no namelatra ny lanitra. rehefa antsoiko izy ireo dia mitsangana daholo.'),
  ('6ab25b816875f5c54840c3c7', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 10, 'Nodioviko ianao, nefa tsy nataoko hoatran’ny manadio volafotsy. Nosedraiko tao anatin’ny fatana fandrendrehana ianao, izany hoe tao anatin’ny fahoriana.', 'nodioviko ianao, nefa tsy nataoko hoatran’ny manadio volafotsy. nosedraiko tao anatin’ny fatana fandrendrehana ianao, izany hoe tao anatin’ny fahoriana.'),
  ('6ab25b816875f5c54840c3c6', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 9, 'Hifehy ny hatezerako anefa aho noho ny anarako, Hifehy tena aho mba hahazoako fiderana, Ka tsy horinganiko ianao.', 'hifehy ny hatezerako anefa aho noho ny anarako, hifehy tena aho mba hahazoako fiderana, ka tsy horinganiko ianao.'),
  ('6ab25b816875f5c54840c3c2', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 5, 'Efa ela aho no nilaza taminao ny zava-drehetra. Mbola tsy nitranga akory izany dia efa noteneniko anao, Sao mantsy ianao hiteny hoe: ‘Ny sampiko no nanao an’izany, Ny sary sokitra sy ny sarivongana metaly nataoko no nandidy an’izany.’', 'efa ela aho no nilaza taminao ny zava-drehetra. mbola tsy nitranga akory izany dia efa noteneniko anao, sao mantsy ianao hiteny hoe: ‘ny sampiko no nanao an’izany, ny sary sokitra sy ny sarivongana metaly nataoko no nandidy an’izany.’'),
  ('6ab25b816875f5c54840c3cd', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 16, 'Manatòna ahy, dia henoy izao: Efa hatramin’ny voalohany mihitsy aho no tsy niafinafina rehefa niteny. Efa teo aho hatramin’ny fotoana nitrangan’izany.” Dia nirahin’i Jehovah Tompo Fara Tampony izaho sy ny fanahiny.', 'manatòna ahy, dia henoy izao: efa hatramin’ny voalohany mihitsy aho no tsy niafinafina rehefa niteny. efa teo aho hatramin’ny fotoana nitrangan’izany.” dia nirahin’i jehovah tompo fara tampony izaho sy ny fanahiny.'),
  ('6ab25b816875f5c54840c3c9', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 12, 'Henoy aho, ry Jakoba sy Israely, izay nantsoiko! Tsy miova Aho, fa izaho no voalohany, ary izaho no farany.', 'henoy aho, ry jakoba sy israely, izay nantsoiko! tsy miova aho, fa izaho no voalohany, ary izaho no farany.'),
  ('6ab25b816875f5c54840c3c8', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 11, 'Hanao zavatra aho noho ny amiko. Fa nahoana no havelako hozimbazimbaina ny anarako? Tsy homeko an’iza na iza ny voninahitro.', 'hanao zavatra aho noho ny amiko. fa nahoana no havelako hozimbazimbaina ny anarako? tsy homeko an’iza na iza ny voninahitro.'),
  ('6ab25b816875f5c54840c3c0', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 3, '“Efa ela aho no nilaza taminao ny zavatra taloha. Ny vavako no niteny an’ireny, Ary nampahafantariko ireny. Nanao zavatra tampoka aho, ka tanteraka ireny.', '“efa ela aho no nilaza taminao ny zavatra taloha. ny vavako no niteny an’ireny, ary nampahafantariko ireny. nanao zavatra tampoka aho, ka tanteraka ireny.'),
  ('6ab25b816875f5c54840c3cb', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 14, 'Mivoria ianareo rehetra, ka mihainoa! Iza amin’izy ireo no nilaza an’izany zavatra izany? Tian’i Jehovah izy. Izy no hanatanteraka an’izay tian’Andriamanitra hatao amin’i Babylona, Ary ny sandriny no hamely ny Kaldeanina.', 'mivoria ianareo rehetra, ka mihainoa! iza amin’izy ireo no nilaza an’izany zavatra izany? tian’i jehovah izy. izy no hanatanteraka an’izay tian’andriamanitra hatao amin’i babylona, ary ny sandriny no hamely ny kaldeanina.'),
  ('6ab25b816875f5c54840c3c4', '2026-09-22T10:42:09.361Z', '2026-09-22T10:42:09.361Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 48, 7, 'Vao izao izany vao misy fa tsy hoe efa taloha, Dia zavatra mbola tsy henonao mihitsy talohan’ny androany, Sao ianao hiteny hoe: ‘Efa fantatro izany.’', 'vao izao izany vao misy fa tsy hoe efa taloha, dia zavatra mbola tsy henonao mihitsy talohan’ny androany, sao ianao hiteny hoe: ‘efa fantatro izany.’'),
  ('6ab25b82ac09dc2fefad399f', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 25, 'Izao anefa no tenin’i Jehovah: “Mbola halaina na dia izay efa nataon’ny lehilahy matanjaka babo aza, Ary mbola havotana izay nosamborin’ny mpitondra jadona. Hotoheriko izay manohitra anao, Ary hovonjeko ny zanakao.', 'izao anefa no tenin’i jehovah: “mbola halaina na dia izay efa nataon’ny lehilahy matanjaka babo aza, ary mbola havotana izay nosamborin’ny mpitondra jadona. hotoheriko izay manohitra anao, ary hovonjeko ny zanakao.'),
  ('6ab25b82ac09dc2fefad399c', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 22, 'Izao no tenin’i Jehovah Tompo Fara Tampony: “Hatsangako ny tanako mba ho hitan’ny firenena, Ary hatsangako ny tsato-kazo famantarana mba ho hitan’ny vahoaka. Dia hotrotroin’izy ireo ny zanakao lahy, Ary hataony antsangory ny zanakao vavy.', 'izao no tenin’i jehovah tompo fara tampony: “hatsangako ny tanako mba ho hitan’ny firenena, ary hatsangako ny tsato-kazo famantarana mba ho hitan’ny vahoaka. dia hotrotroin’izy ireo ny zanakao lahy, ary hataony antsangory ny zanakao vavy.'),
  ('6ab25b82ac09dc2fefad399b', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 21, 'Dia hiteny anakampo ianao hoe: ‘Mba iza àry no rain’ireto zaza ireto, ka nanome ahy an’ireto? Izaho ange vehivavy maty anaka sy momba e! Dia izaho koa natao sesitany sady nogadraina. Dia iza no nitaiza an’ireto? Na izaho aza nilaozan’ny olona irery tany, Dia avy aiza izany ireto?’”', 'dia hiteny anakampo ianao hoe: ‘mba iza àry no rain’ireto zaza ireto, ka nanome ahy an’ireto? izaho ange vehivavy maty anaka sy momba e! dia izaho koa natao sesitany sady nogadraina. dia iza no nitaiza an’ireto? na izaho aza nilaozan’ny olona irery tany, dia avy aiza izany ireto?’”'),
  ('6ab25b82ac09dc2fefad398c', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 6, 'Ary hoy izy: “Tsy hoe mpanompoko fotsiny ianao, Ka hampitsangana ny fokon’i Jakoba, Sy hampiverina an’izay Israelita narovana tsy ho faty. Fa nomeko ho fahazavan’ny hafa firenena koa ianao, Mba ho tonga hatrany amin’ny faran’ny tany ny famonjeko.”', 'ary hoy izy: “tsy hoe mpanompoko fotsiny ianao, ka hampitsangana ny fokon’i jakoba, sy hampiverina an’izay israelita narovana tsy ho faty. fa nomeko ho fahazavan’ny hafa firenena koa ianao, mba ho tonga hatrany amin’ny faran’ny tany ny famonjeko.”'),
  ('6ab25b82ac09dc2fefad398d', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 7, 'Izao no tenin’i Jehovah, ilay Mpanavotra ny Israely sy Ilay Masin’ny Israely, amin’ilay ankahalaina, dia ilay tsy tian’ny firenena sady mpanompon’ny mpitondra: “Hitsangana ny mpanjaka noho ny zavatra hitan’izy ireo, Ary ny andriana koa hiankohoka. Hanao an’izany izy ireo satria mendri-pitokisana i Jehovah, Ilay Masin’ny Israely nifidy anao.”', 'izao no tenin’i jehovah, ilay mpanavotra ny israely sy ilay masin’ny israely, amin’ilay ankahalaina, dia ilay tsy tian’ny firenena sady mpanompon’ny mpitondra: “hitsangana ny mpanjaka noho ny zavatra hitan’izy ireo, ary ny andriana koa hiankohoka. hanao an’izany izy ireo satria mendri-pitokisana i jehovah, ilay masin’ny israely nifidy anao.”'),
  ('6ab25b82ac09dc2fefad399e', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 24, 'Mbola azo alaina eny an-tanan’ny lehilahy matanjaka ve ny olona efa lasany? Mbola azo avotana ve izay nataon’ny mpitondra jadona babo?', 'mbola azo alaina eny an-tanan’ny lehilahy matanjaka ve ny olona efa lasany? mbola azo avotana ve izay nataon’ny mpitondra jadona babo?'),
  ('6ab25b82ac09dc2fefad399d', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 23, 'Mpanjaka no ho lasa mpitaiza anao, Ary ny andriambaviny no ho mpampinono anao. Hiankohoka amin’ny tany eo anatrehanao izy ireo, Sady hilelaka ny vovoka amin’ny tongotrao. Dia ho fantatrao fa izaho no Jehovah, Ary tsy ho afa-baraka mihitsy izay manantena ahy.”', 'mpanjaka no ho lasa mpitaiza anao, ary ny andriambaviny no ho mpampinono anao. hiankohoka amin’ny tany eo anatrehanao izy ireo, sady hilelaka ny vovoka amin’ny tongotrao. dia ho fantatrao fa izaho no jehovah, ary tsy ho afa-baraka mihitsy izay manantena ahy.”'),
  ('6ab25b82ac09dc2fefad3989', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 3, 'Hoy izy tamiko: “Mpanompoko ianao, ry Israely, Ary amin’ny alalanao no hampisehoako ny voninahitro.”', 'hoy izy tamiko: “mpanompoko ianao, ry israely, ary amin’ny alalanao no hampisehoako ny voninahitro.”'),
  ('6ab25b82ac09dc2fefad3995', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 15, 'Misy vehivavy manadino ny zanany mbola minono ve, Na tsy mangoraka an’ilay zanany naterany? Na manadino aza ireny vehivavy ireny, dia izaho indray tsy mba hanadino anao mihitsy.', 'misy vehivavy manadino ny zanany mbola minono ve, na tsy mangoraka an’ilay zanany naterany? na manadino aza ireny vehivavy ireny, dia izaho indray tsy mba hanadino anao mihitsy.'),
  ('6ab25b82ac09dc2fefad398a', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 4, 'Fa hoy kosa aho: “Very maina fotsiny ny asa mafy nataoko. Zavatra tsisy dikany no nandaniako ny heriko ka reraka fotsiny aho. I Jehovah anefa no tena hitsara ahy, Ary ny Andriamanitro no hanome ny karamako.”', 'fa hoy kosa aho: “very maina fotsiny ny asa mafy nataoko. zavatra tsisy dikany no nandaniako ny heriko ka reraka fotsiny aho. i jehovah anefa no tena hitsara ahy, ary ny andriamanitro no hanome ny karamako.”'),
  ('6ab25b82ac09dc2fefad3998', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 18, 'Mitrakà dia jereo daholo ny manodidina anao. Jereo fa mitangorona izy rehetra, Dia manatona anao. “Raha mbola velona koa aho”, hoy i Jehovah, “Dia hanaovanao hoatran’ny haingo izy rehetra, Ka hafatotrao amin’ny vatanao hoatran’ny ataon’ny vehivavy ampakarina.', 'mitrakà dia jereo daholo ny manodidina anao. jereo fa mitangorona izy rehetra, dia manatona anao. “raha mbola velona koa aho”, hoy i jehovah, “dia hanaovanao hoatran’ny haingo izy rehetra, ka hafatotrao amin’ny vatanao hoatran’ny ataon’ny vehivavy ampakarina.'),
  ('6ab25b82ac09dc2fefad398e', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 8, 'Izao no tenin’i Jehovah: “Tamin’ny fotoana fanehoana fankasitrahana aho no namaly anao, Ary tamin’ny andro famonjena aho no nanampy anao. Narovako foana ianao mba hataoko antoka ho an’ny vahoaka, Mba hamerenana an’ilay tany amin’ny laoniny, Ka ho azon’izy ireo indray ny lovany.', 'izao no tenin’i jehovah: “tamin’ny fotoana fanehoana fankasitrahana aho no namaly anao, ary tamin’ny andro famonjena aho no nanampy anao. narovako foana ianao mba hataoko antoka ho an’ny vahoaka, mba hamerenana an’ilay tany amin’ny laoniny, ka ho azon’izy ireo indray ny lovany.'),
  ('6ab25b82ac09dc2fefad3996', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 16, 'Nosoratako teo amin’ny felatanako ny anaranao. Eo anatrehako foana ny mandanao.', 'nosoratako teo amin’ny felatanako ny anaranao. eo anatrehako foana ny mandanao.'),
  ('6ab25b82ac09dc2fefad3999', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 19, 'Na dia ravarava sy tsy misy mponina intsony aza ny toerana nisy anao, ary simba ny taninao, Dia ho lasa tery loatra izany ka tsy ho antonona an’izay hipetraka ao, Ary ho lavitra be anao izay nandrapaka anao.', 'na dia ravarava sy tsy misy mponina intsony aza ny toerana nisy anao, ary simba ny taninao, dia ho lasa tery loatra izany ka tsy ho antonona an’izay hipetraka ao, ary ho lavitra be anao izay nandrapaka anao.'),
  ('6ab25b82ac09dc2fefad398b', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 5, 'I Jehovah no namolavola ahy tao an-kibo mba ho lasa mpanompony. Izy ilay niteny hoe tokony hampiverina an’i Jakoba aminy aho, Amin’izay dia ho tafangona any aminy indray i Israely. Dia hahazo voninahitra eo imason’i Jehovah aho, Ary ilay Andriamanitro no ho heriko.', 'i jehovah no namolavola ahy tao an-kibo mba ho lasa mpanompony. izy ilay niteny hoe tokony hampiverina an’i jakoba aminy aho, amin’izay dia ho tafangona any aminy indray i israely. dia hahazo voninahitra eo imason’i jehovah aho, ary ilay andriamanitro no ho heriko.'),
  ('6ab25b82ac09dc2fefad39a0', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 26, 'Hampihinaniko ny nofony ihany izay rehetra mampijaly anao, Ary hataoko mamon’ny rany ihany izy ireo, hoatran’ny hoe mamon’ny divay mamy. Dia ho fantatry ny olona rehetra fa izaho no Jehovah, Ilay Mpamonjy anao sy Mpanavotra anao, Ary izaho Ilay Maherin’i Jakoba.”', 'hampihinaniko ny nofony ihany izay rehetra mampijaly anao, ary hataoko mamon’ny rany ihany izy ireo, hoatran’ny hoe mamon’ny divay mamy. dia ho fantatry ny olona rehetra fa izaho no jehovah, ilay mpamonjy anao sy mpanavotra anao, ary izaho ilay maherin’i jakoba.”'),
  ('6ab25b82ac09dc2fefad399a', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 20, 'Ary na ireo zaza teraka taorian’ny nahafatesan’ny zanakao aza dia hiteny aminao hoe: ‘Tery loatra ity toerana ity ka tsy antonona anay. Omeo toerana malalaka eto izahay hipetrahanay.’', 'ary na ireo zaza teraka taorian’ny nahafatesan’ny zanakao aza dia hiteny aminao hoe: ‘tery loatra ity toerana ity ka tsy antonona anay. omeo toerana malalaka eto izahay hipetrahanay.’'),
  ('6ab25b82ac09dc2fefad398f', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 9, 'Dia hotenenina ny voafonja hoe: ‘Mivoaha!’, Ary izay ao anaty haizina hoe: ‘Misehoa!’ Izay hitany eny an-dalana no hohaniny, Ary eny amoron’ny lala-masaka rehetra eny izy ireo no hiraoka ahitra.', 'dia hotenenina ny voafonja hoe: ‘mivoaha!’, ary izay ao anaty haizina hoe: ‘misehoa!’ izay hitany eny an-dalana no hohaniny, ary eny amoron’ny lala-masaka rehetra eny izy ireo no hiraoka ahitra.'),
  ('6ab25b82ac09dc2fefad3987', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 1, 'Henoy aho, ry nosy! Mihainoa tsara, ry firenena any lavitra be! Mbola tsy teraka aho dia efa niantso ahy i Jehovah. Mbola tany an-kibon-dreniko aho, dia efa notononiny ny anarako.', 'henoy aho, ry nosy! mihainoa tsara, ry firenena any lavitra be! mbola tsy teraka aho dia efa niantso ahy i jehovah. mbola tany an-kibon-dreniko aho, dia efa notononiny ny anarako.'),
  ('6ab25b82ac09dc2fefad3990', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 10, 'Tsy ho noana na hangetaheta izy ireo, Ary tsy hodanihin’ny hafanana na ny masoandro. Fa hitari-dalana azy Ilay mamindra fo aminy, Ka hitarika azy ho eny amin’ny loharano.', 'tsy ho noana na hangetaheta izy ireo, ary tsy hodanihin’ny hafanana na ny masoandro. fa hitari-dalana azy ilay mamindra fo aminy, ka hitarika azy ho eny amin’ny loharano.'),
  ('6ab25b82ac09dc2fefad3997', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 17, 'Miverina haingana ny zanakao, Ary hiala aminao izay nandrodana sy nandrava anao.', 'miverina haingana ny zanakao, ary hiala aminao izay nandrodana sy nandrava anao.'),
  ('6ab25b82ac09dc2fefad3993', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 13, 'Mihobia, ry lanitra, ary mifalia, ry tany! Aoka hifalifaly ny tendrombohitra sady hihoby. Mampionona ny vahoakany mantsy i Jehovah, Sady mamindra fo amin’izay mpanompony mijaly.', 'mihobia, ry lanitra, ary mifalia, ry tany! aoka hifalifaly ny tendrombohitra sady hihoby. mampionona ny vahoakany mantsy i jehovah, sady mamindra fo amin’izay mpanompony mijaly.'),
  ('6ab25b82ac09dc2fefad3992', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 12, 'Tonga avy any lavitra be izy ireo, Ka ny sasany avy any avaratra sy avy any andrefana, Dia ny sasany avy any Sinima.”', 'tonga avy any lavitra be izy ireo, ka ny sasany avy any avaratra sy avy any andrefana, dia ny sasany avy any sinima.”'),
  ('6ab25b82ac09dc2fefad3994', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 14, 'Niteny foana anefa i Ziona hoe: “Efa nahafoy ahy i Jehovah. Efa nanadino ahy i Jehovah.”', 'niteny foana anefa i ziona hoe: “efa nahafoy ahy i jehovah. efa nanadino ahy i jehovah.”'),
  ('6ab25b82ac09dc2fefad3991', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 11, 'Hataoko lalana ny tendrombohitro rehetra, Ary hampiakariko ambony ny lalambeko rehetra.', 'hataoko lalana ny tendrombohitro rehetra, ary hampiakariko ambony ny lalambeko rehetra.'),
  ('6ab25b82ac09dc2fefad3988', '2026-09-22T10:42:10.607Z', '2026-09-22T10:42:10.607Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 49, 2, 'Nataony hoatran’ny sabatra maranitra ny vavako. Nafeniny teo ambany aloky ny tanany aho. Nataony lasa zana-tsipìka maranitra aho, Ary nafeniny tao amin’ny tranon-jana-tsipìkany.', 'nataony hoatran’ny sabatra maranitra ny vavako. nafeniny teo ambany aloky ny tanany aho. nataony lasa zana-tsipìka maranitra aho, ary nafeniny tao amin’ny tranon-jana-tsipìkany.'),
  ('6ab25b830f37a0418e30a076', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 4, 'I Jehovah Tompo Fara Tampony efa nampianatra ny lelako hahay hiteny, Mba hahafantarako an’izay tokony holazaina amin’ny olona reraka. Mamoha ahy isa-maraina izy, Ka fohaziny ny sofiko mba hihaino hoatran’ny olona ampianarina.', 'i jehovah tompo fara tampony efa nampianatra ny lelako hahay hiteny, mba hahafantarako an’izay tokony holazaina amin’ny olona reraka. mamoha ahy isa-maraina izy, ka fohaziny ny sofiko mba hihaino hoatran’ny olona ampianarina.'),
  ('6ab25b830f37a0418e30a07c', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 10, 'Iza aminareo no matahotra an’i Jehovah Sy mihaino ny tenin’ny mpanompony? Iza no nandeha tao anatin’ny haizim-be tsy nisy hazavana? Asaivo mitoky amin’ny anaran’i Jehovah sy miantehitra amin’ilay Andriamaniny izy.', 'iza aminareo no matahotra an’i jehovah sy mihaino ny tenin’ny mpanompony? iza no nandeha tao anatin’ny haizim-be tsy nisy hazavana? asaivo mitoky amin’ny anaran’i jehovah sy miantehitra amin’ilay andriamaniny izy.'),
  ('6ab25b830f37a0418e30a079', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 7, 'Hanampy ahy anefa i Jehovah Tompo Fara Tampony, Ka tsy ho menatra aho. Noho izany, dia tapa-kevitra ny ho hentitra aho, Ary fantatro fa tsy ho afa-baraka aho.', 'hanampy ahy anefa i jehovah tompo fara tampony, ka tsy ho menatra aho. noho izany, dia tapa-kevitra ny ho hentitra aho, ary fantatro fa tsy ho afa-baraka aho.'),
  ('6ab25b830f37a0418e30a073', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 1, 'Izao no tenin’i Jehovah: “Izaho angaha nanome taratasy fisaraham-panambadiana ho an’ny reninareo, tamin’izy noroahiko? Iza tamin’ireo tokony handoavako trosa no nivarotako anareo? Nanao fahadisoana ange ianareo dia izany no antony nivarotana anareo e! Ary nanota ianareo dia noroahina ny reninareo.', 'izao no tenin’i jehovah: “izaho angaha nanome taratasy fisaraham-panambadiana ho an’ny reninareo, tamin’izy noroahiko? iza tamin’ireo tokony handoavako trosa no nivarotako anareo? nanao fahadisoana ange ianareo dia izany no antony nivarotana anareo e! ary nanota ianareo dia noroahina ny reninareo.'),
  ('6ab25b830f37a0418e30a078', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 6, 'Natolotro tamin’ny olona nikapoka ahy ny lamosiko, Ary ny takolako natolotro tamin’ireo nanongotra ny volombavako. Ny tarehiko koa tsy mba nafeniko tamin’ny olona nanala baraka sy nandrora ahy.', 'natolotro tamin’ny olona nikapoka ahy ny lamosiko, ary ny takolako natolotro tamin’ireo nanongotra ny volombavako. ny tarehiko koa tsy mba nafeniko tamin’ny olona nanala baraka sy nandrora ahy.'),
  ('6ab25b830f37a0418e30a07a', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 8, 'Akaiky ahy Ilay milaza hoe marina aho. Iza no afaka miampanga ahy? Aleo izahay hifanatrika. Iza no mitory ahy any amin’ny fitsarana? Aleo izy hanatona ahy.', 'akaiky ahy ilay milaza hoe marina aho. iza no afaka miampanga ahy? aleo izahay hifanatrika. iza no mitory ahy any amin’ny fitsarana? aleo izy hanatona ahy.'),
  ('6ab25b830f37a0418e30a074', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 2, 'Nahoana àry no tsy nisy olona teto rehefa tonga aho? Ary nahoana no tsy nisy namaly rehefa niantso aho? Angaha ny tanako fohy loatra ka tsy mahavita manavotra, Sa izaho tsy manan-kery hamonjena? Teneniko mafy fotsiny ny ranomasina dia ritra, Ary ovako ho tany efitra ny renirano. Matin’ny hetaheta ny trondrony, Dia lo fa tsy misy rano.', 'nahoana àry no tsy nisy olona teto rehefa tonga aho? ary nahoana no tsy nisy namaly rehefa niantso aho? angaha ny tanako fohy loatra ka tsy mahavita manavotra, sa izaho tsy manan-kery hamonjena? teneniko mafy fotsiny ny ranomasina dia ritra, ary ovako ho tany efitra ny renirano. matin’ny hetaheta ny trondrony, dia lo fa tsy misy rano.'),
  ('6ab25b830f37a0418e30a075', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 3, 'Ampitafiako haizina ny lanitra, Ary rakofako lamba gony.”', 'ampitafiako haizina ny lanitra, ary rakofako lamba gony.”'),
  ('6ab25b830f37a0418e30a07d', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 11, '“Ianareo rehetra izay mandrehitra afo Sy mampisy pitik’afo, Mandehana amin’ny hazavan’ny afonareo Sy eo amin’ny pitik’afo alefanareo. Dia izao no sazy hampihariko aminareo: Hiampatrampatra ao anatin’ny fanaintainana faran’izay mafy ianareo.', '“ianareo rehetra izay mandrehitra afo sy mampisy pitik’afo, mandehana amin’ny hazavan’ny afonareo sy eo amin’ny pitik’afo alefanareo. dia izao no sazy hampihariko aminareo: hiampatrampatra ao anatin’ny fanaintainana faran’izay mafy ianareo.'),
  ('6ab25b830f37a0418e30a07b', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 9, 'Hanampy ahy i Jehovah Tompo Fara Tampony. Iza no hilaza fa meloka aho? Ho lasa hoatran’ny akanjo tonta izy rehetra, Ary hoatran’ny akanjo lanin’ny bibikely.', 'hanampy ahy i jehovah tompo fara tampony. iza no hilaza fa meloka aho? ho lasa hoatran’ny akanjo tonta izy rehetra, ary hoatran’ny akanjo lanin’ny bibikely.'),
  ('6ab25b830f37a0418e30a077', '2026-09-22T10:42:11.678Z', '2026-09-22T10:42:11.678Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 50, 5, 'Nanokatra ny sofiko i Jehovah Tompo Fara Tampony. Dia izaho tsy mba nikomy, Na nivily lalana.', 'nanokatra ny sofiko i jehovah tompo fara tampony. dia izaho tsy mba nikomy, na nivily lalana.'),
  ('6ab25b840be6426efe56f8e7', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 15, 'Izaho no Jehovah Andriamanitrao, Ilay mampisamboaravoara ny ranomasina sy mampidoboka ny onjany. Jehovah Tompon’ny tafika no anarako.', 'izaho no jehovah andriamanitrao, ilay mampisamboaravoara ny ranomasina sy mampidoboka ny onjany. jehovah tompon’ny tafika no anarako.'),
  ('6ab25b840be6426efe56f8e3', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 11, 'Hiverina ireo navotan’i Jehovah. Hihoby izy ireo rehefa tonga ao Ziona, Ary hifaly foana ka ho toy ny satroboninahitra eny aminy ny fifaliany. Hiravoravo sy ho faly izy ireo, Dia handositra azy ny alahelo sy ny fisentoana.', 'hiverina ireo navotan’i jehovah. hihoby izy ireo rehefa tonga ao ziona, ary hifaly foana ka ho toy ny satroboninahitra eny aminy ny fifaliany. hiravoravo sy ho faly izy ireo, dia handositra azy ny alahelo sy ny fisentoana.'),
  ('6ab25b840be6426efe56f8da', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 2, 'Jereo i Abrahama rainareo, Sy Saraha izay niteraka anareo. Fa iray ihany izy tamin’izy nantsoiko. Dia notahiko izy ka nataoko lasa be dia be.', 'jereo i abrahama rainareo, sy saraha izay niteraka anareo. fa iray ihany izy tamin’izy nantsoiko. dia notahiko izy ka nataoko lasa be dia be.'),
  ('6ab25b840be6426efe56f8d9', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 1, '“Mihainoa ahy ianareo mitady ny fahamarinana, Dia ianareo mitady an’i Jehovah! Jereo ilay vatolampy nanendahana anareo, Sy ilay lavaka nitrandrahana anareo.', '“mihainoa ahy ianareo mitady ny fahamarinana, dia ianareo mitady an’i jehovah! jereo ilay vatolampy nanendahana anareo, sy ilay lavaka nitrandrahana anareo.'),
  ('6ab25b840be6426efe56f8e5', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 13, 'Nahoana ianao no manadino an’i Jehovah, ilay Mpanao anao, Ilay namelatra ny lanitra sy nametraka ny fototry ny tany? Tontolo andro ianao natahotra foana ny fahatezeran’ilay nampijaly anao, Hoatran’ny hoe ho afaka handringana anao izy. Dia aiza izao ny hatezeran’ilay nampijaly anao?', 'nahoana ianao no manadino an’i jehovah, ilay mpanao anao, ilay namelatra ny lanitra sy nametraka ny fototry ny tany? tontolo andro ianao natahotra foana ny fahatezeran’ilay nampijaly anao, hoatran’ny hoe ho afaka handringana anao izy. dia aiza izao ny hatezeran’ilay nampijaly anao?');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25b840be6426efe56f8de', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 6, 'Mitrakà dia jereo ny lanitra, Ary jereo ny tany eny ambany! Ho potipotika ny lanitra ka hiparitaka toy ny setroka. Ny tany indray ho lasa hoatran’ny akanjo tonta, Ary ny mponina eo aminy ho faty toy ny moka. Ny famonjeko kosa haharitra mandrakizay, Ary ny fahamarinako tsy ho foana mihitsy.', 'mitrakà dia jereo ny lanitra, ary jereo ny tany eny ambany! ho potipotika ny lanitra ka hiparitaka toy ny setroka. ny tany indray ho lasa hoatran’ny akanjo tonta, ary ny mponina eo aminy ho faty toy ny moka. ny famonjeko kosa haharitra mandrakizay, ary ny fahamarinako tsy ho foana mihitsy.'),
  ('6ab25b840be6426efe56f8db', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 3, 'Fa hampionona an’i Ziona i Jehovah. Hampiononiny daholo ny toerana ravarava ao. Dia hataony ho toa an’i Edena ny tany efitra any, Ary ho toy ny zaridainan’i Jehovah ny lemaka karakaina. Hiravoravo sy hifaly ny olona ao, Ary hanao fisaorana sy hira kanto.', 'fa hampionona an’i ziona i jehovah. hampiononiny daholo ny toerana ravarava ao. dia hataony ho toa an’i edena ny tany efitra any, ary ho toy ny zaridainan’i jehovah ny lemaka karakaina. hiravoravo sy hifaly ny olona ao, ary hanao fisaorana sy hira kanto.'),
  ('6ab25b840be6426efe56f8e0', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 8, 'Fa hohanin’ny bibikely ireny, hoatran’ny fihinanany akanjo, Ary hohanin’ny bibikely mpihinan-damba, hoatran’ny fihinanany lamba volonondry. Ny fahamarinako kosa haharitra mandrakizay, Ary ny famonjeko haharitra hatrany amin’ny taranaka fara aman-dimby.”', 'fa hohanin’ny bibikely ireny, hoatran’ny fihinanany akanjo, ary hohanin’ny bibikely mpihinan-damba, hoatran’ny fihinanany lamba volonondry. ny fahamarinako kosa haharitra mandrakizay, ary ny famonjeko haharitra hatrany amin’ny taranaka fara aman-dimby.”'),
  ('6ab25b840be6426efe56f8dc', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 4, 'Henoy tsara aho, ry vahoakako! Mihainoa ahy, ry fireneko! Fa hisy lalàna havoakako, Ary ny fampiharako ny rariny no hataoko manazava ny firenena.', 'henoy tsara aho, ry vahoakako! mihainoa ahy, ry fireneko! fa hisy lalàna havoakako, ary ny fampiharako ny rariny no hataoko manazava ny firenena.'),
  ('6ab25b840be6426efe56f8e1', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 9, 'Mifohaza! Mifohaza! Mitafia hery, ry sandrin’i Jehovah! Mifohaza toy ny tamin’ny andro fahiny, toy ny tamin’ny andron’ireo taranaka taloha! Tsy ianao ve no namotipotika an’i Rahaba, Sy nanatrobaka an’ilay biby ngezabe any an-dranomasina?', 'mifohaza! mifohaza! mitafia hery, ry sandrin’i jehovah! mifohaza toy ny tamin’ny andro fahiny, toy ny tamin’ny andron’ireo taranaka taloha! tsy ianao ve no namotipotika an’i rahaba, sy nanatrobaka an’ilay biby ngezabe any an-dranomasina?'),
  ('6ab25b840be6426efe56f8e2', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 10, 'Tsy ianao ve no nanao izay haharìtra ny ranomasina, dia ny rano lalina be? Tsy ianao koa ve no nanao ny ranomasina lalina ho lalana hiampitan’ireo navotana?', 'tsy ianao ve no nanao izay haharìtra ny ranomasina, dia ny rano lalina be? tsy ianao koa ve no nanao ny ranomasina lalina ho lalana hiampitan’ireo navotana?'),
  ('6ab25b840be6426efe56f8dd', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 5, 'Efa manakaiky ny fahamarinako. Efa ho tonga ny famonjena avy amiko, Ary ny sandriko no hitsara an’ireo firenena. Izaho no hantenain’ireo nosy, Ary ny sandriko no handrandrainy.', 'efa manakaiky ny fahamarinako. efa ho tonga ny famonjena avy amiko, ary ny sandriko no hitsara an’ireo firenena. izaho no hantenain’ireo nosy, ary ny sandriko no handrandrainy.'),
  ('6ab25b840be6426efe56f8e6', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 14, 'Tsy ho ela dia hafahana ilay manjoko noho ny rojo vy mamatotra azy, Dia tsy ho faty izy ka tsy ho latsaka any an-davaka, Ary tsy ho fatin’ny mosary.', 'tsy ho ela dia hafahana ilay manjoko noho ny rojo vy mamatotra azy, dia tsy ho faty izy ka tsy ho latsaka any an-davaka, ary tsy ho fatin’ny mosary.'),
  ('6ab25b840be6426efe56f8df', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 7, 'Mihainoa ahy ianareo efa mahalala ny fahamarinana, Dia ianareo manana ny lalàko ao am-ponareo. Aza matahotra ny esoeson’ny olombelona mety maty, Ary aza mihorohoro satria hoe ambanimbaniny.', 'mihainoa ahy ianareo efa mahalala ny fahamarinana, dia ianareo manana ny lalàko ao am-ponareo. aza matahotra ny esoeson’ny olombelona mety maty, ary aza mihorohoro satria hoe ambanimbaniny.'),
  ('6ab25b840be6426efe56f8e4', '2026-09-22T10:42:12.178Z', '2026-09-22T10:42:12.178Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 12, '“Izaho Ilay mampionona anareo. Dia nahoana ianao no matahotra ny olombelona mety maty izay ho faty ihany, Sy ny zanak’olombelona izay halazo hoatran’ny ahitra?', '“izaho ilay mampionona anareo. dia nahoana ianao no matahotra ny olombelona mety maty izay ho faty ihany, sy ny zanak’olombelona izay halazo hoatran’ny ahitra?'),
  ('6ab25b840be6426efe56f8ec', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 20, 'Torana ny zanakao. Miampatrampatra eny an-joron-dalana rehetra eny izy ireo, Hoatran’ny ondridia anaty harato. Anamparan’i Jehovah ny hatezerany izy ireo, sady anarin’ilay Andriamanitrao.”', 'torana ny zanakao. miampatrampatra eny an-joron-dalana rehetra eny izy ireo, hoatran’ny ondridia anaty harato. anamparan’i jehovah ny hatezerany izy ireo, sady anarin’ilay andriamanitrao.”'),
  ('6ab25b840be6426efe56f8ed', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 21, 'Mba henoy àry izao, Ry vehivavy mijaly, izay mamo nefa tsy mamon-divay!', 'mba henoy àry izao, ry vehivavy mijaly, izay mamo nefa tsy mamon-divay!'),
  ('6ab25b840be6426efe56f8e9', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 17, 'Mifohaza! Mifohaza! Mitsangàna, ry Jerosalema ô! Nisotro tamin’ilay kaopy teny an-tanan’i Jehovah ianao, dia ilay kaopy misy ny fahatezerany. Nosotroinao ny tao anatin’ilay fisotroan-divay, Ary notaperinao tanteraka ny tao amin’ilay kaopy mampivembena.', 'mifohaza! mifohaza! mitsangàna, ry jerosalema ô! nisotro tamin’ilay kaopy teny an-tanan’i jehovah ianao, dia ilay kaopy misy ny fahatezerany. nosotroinao ny tao anatin’ilay fisotroan-divay, ary notaperinao tanteraka ny tao amin’ilay kaopy mampivembena.'),
  ('6ab25b840be6426efe56f8ee', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 22, 'Izao no tenin’i Jehovah Tomponao, ilay Andriamanitrao, izay miaro ny vahoakany: “Halaiko eny an-tananao ilay kaopy mampivembena, Dia ilay kaopy misy ny fahatezerako. Tsy hisotro amin’iny intsony ianao.', 'izao no tenin’i jehovah tomponao, ilay andriamanitrao, izay miaro ny vahoakany: “halaiko eny an-tananao ilay kaopy mampivembena, dia ilay kaopy misy ny fahatezerako. tsy hisotro amin’iny intsony ianao.'),
  ('6ab25b840be6426efe56f8eb', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 19, 'Nanjo anao ireto zavatra roa ireto: Ringana sady ravarava ianao, ary noana sady matin’ny sabatra! Dia iza no hangoraka anao? Ary iza no hampionona anao?', 'nanjo anao ireto zavatra roa ireto: ringana sady ravarava ianao, ary noana sady matin’ny sabatra! dia iza no hangoraka anao? ary iza no hampionona anao?'),
  ('6ab25b840be6426efe56f8ef', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 23, 'Hatolotro eny an-tanan’ireo mampijaly anao ilay kaopy, Dia izay niteny taminao hoe: ‘Miondreha amin’ny tany mba handehananay.’ Nataonao hoatran’ny tany àry ny lamosinao, Hoatran’ny lalana handehanan’izy ireo.”', 'hatolotro eny an-tanan’ireo mampijaly anao ilay kaopy, dia izay niteny taminao hoe: ‘miondreha amin’ny tany mba handehananay.’ nataonao hoatran’ny tany àry ny lamosinao, hoatran’ny lalana handehanan’izy ireo.”'),
  ('6ab25b840be6426efe56f8ea', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 18, 'Tsy misy eo daholo ny zanakao mba hitari-dalana anao, Ary tsy nisy nitantana anao ny zanaka notezainao rehetra.', 'tsy misy eo daholo ny zanakao mba hitari-dalana anao, ary tsy nisy nitantana anao ny zanaka notezainao rehetra.'),
  ('6ab25b840be6426efe56f8e8', '2026-09-22T10:42:12.179Z', '2026-09-22T10:42:12.179Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 51, 16, 'Hampitaiko aminao ny teny tiako holazainao, Ary hosaronako amin’ny aloky ny tanako ianao. Amin’izay dia hataoko eo amin’ny toerany ny lanitra, ary hapetrako ny fototry ny tany, Dia hiteny amin’i Ziona aho hoe: ‘Vahoakako ianao.’', 'hampitaiko aminao ny teny tiako holazainao, ary hosaronako amin’ny aloky ny tanako ianao. amin’izay dia hataoko eo amin’ny toerany ny lanitra, ary hapetrako ny fototry ny tany, dia hiteny amin’i ziona aho hoe: ‘vahoakako ianao.’'),
  ('6ab25b84f2ddf2abfda0a3dd', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 15, 'Dia hoatr’izany koa fa hataony izay hahagaga firenena be dia be. Hitampim-bava eo anatrehany ireo mpanjaka, Satria zavatra mbola tsy notantaraina tamin’izy ireo no ho hitany, Ary zavatra mbola tsy henony no hodinihiny.', 'dia hoatr’izany koa fa hataony izay hahagaga firenena be dia be. hitampim-bava eo anatrehany ireo mpanjaka, satria zavatra mbola tsy notantaraina tamin’izy ireo no ho hitany, ary zavatra mbola tsy henony no hodinihiny.'),
  ('6ab25b84f2ddf2abfda0a3d9', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 11, 'Ianareo izay mitondra ny fitaovan’i Jehovah, Mialà, mialà, mivoaha avy ao, ary aza mikasika an’izay maloto! Mivoaha avy ao aminy, ary miezaha hadio foana.', 'ianareo izay mitondra ny fitaovan’i jehovah, mialà, mialà, mivoaha avy ao, ary aza mikasika an’izay maloto! mivoaha avy ao aminy, ary miezaha hadio foana.'),
  ('6ab25b84f2ddf2abfda0a3d0', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 2, 'Ahintsano ny vovoka, ry Jerosalema ô, dia miarena ka mipetraha! Vahao ny tady mamatotra ny vozonao, ry Ziona zanakavavy nentina ho babo.', 'ahintsano ny vovoka, ry jerosalema ô, dia miarena ka mipetraha! vahao ny tady mamatotra ny vozonao, ry ziona zanakavavy nentina ho babo.'),
  ('6ab25b84f2ddf2abfda0a3d8', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 10, 'Nataon’i Jehovah hitan’ny firenena rehetra ny sandriny masina, Ary ho hitan’ny vazan-tany efatra ny zavatra nataon’ilay Andriamanitsika mba hamonjena ny vahoakany.', 'nataon’i jehovah hitan’ny firenena rehetra ny sandriny masina, ary ho hitan’ny vazan-tany efatra ny zavatra nataon’ilay andriamanitsika mba hamonjena ny vahoakany.'),
  ('6ab25b84f2ddf2abfda0a3d1', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 3, 'Fa izao no tenin’i Jehovah: “Namidy maimaim-poana ianareo, Ka tsy hisy vola haloa koa rehefa avotana ianareo.”', 'fa izao no tenin’i jehovah: “namidy maimaim-poana ianareo, ka tsy hisy vola haloa koa rehefa avotana ianareo.”'),
  ('6ab25b84f2ddf2abfda0a3db', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 13, 'Ho malina ny mpanompoko rehefa manao zavatra. Homena toerana ambony izy, Ary hasandratra ka homena voninahitra lehibe.', 'ho malina ny mpanompoko rehefa manao zavatra. homena toerana ambony izy, ary hasandratra ka homena voninahitra lehibe.'),
  ('6ab25b84f2ddf2abfda0a3d6', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 8, 'Izany fa miantsoantso mafy ny mpitilinao! Miara-mihoby izy ireo, Satria ho hitan’izy ireo tsara ny hamerenan’i Jehovah an’i Ziona amin’ny laoniny.', 'izany fa miantsoantso mafy ny mpitilinao! miara-mihoby izy ireo, satria ho hitan’izy ireo tsara ny hamerenan’i jehovah an’i ziona amin’ny laoniny.'),
  ('6ab25b84f2ddf2abfda0a3d3', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 5, '“Inona àry no tokony hataoko?” hoy i Jehovah. “Fa nalaina maimaim-poana ny vahoakako. Mihorakoraka foana ireo manjaka amin’izy ireo fa nandresy”, hoy i Jehovah. “Tsy hajain’ny olona mihitsy ny anarako, tontolo andro.', '“inona àry no tokony hataoko?” hoy i jehovah. “fa nalaina maimaim-poana ny vahoakako. mihorakoraka foana ireo manjaka amin’izy ireo fa nandresy”, hoy i jehovah. “tsy hajain’ny olona mihitsy ny anarako, tontolo andro.'),
  ('6ab25b84f2ddf2abfda0a3dc', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 14, 'Betsaka no nidanàka rehefa nahita azy. Nosimbana mihoatra noho ny endrik’olon-kafa rehetra mantsy ny endriny, Ary nosimbana mihoatra noho ny an’ny olombelona ny bikany.', 'betsaka no nidanàka rehefa nahita azy. nosimbana mihoatra noho ny endrik’olon-kafa rehetra mantsy ny endriny, ary nosimbana mihoatra noho ny an’ny olombelona ny bikany.'),
  ('6ab25b84f2ddf2abfda0a3d7', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 9, 'Mifalia, ry toerana rava ao Jerosalema, dia miaraha mihoby! Nampionona ny vahoakany mantsy i Jehovah, sady nanavotra an’i Jerosalema.', 'mifalia, ry toerana rava ao jerosalema, dia miaraha mihoby! nampionona ny vahoakany mantsy i jehovah, sady nanavotra an’i jerosalema.'),
  ('6ab25b84f2ddf2abfda0a3d4', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 6, 'Ho fantatry ny vahoakako àry ny anarako. Dia ho fantany koa amin’izany andro izany fa izaho Ilay miteny. Izaho mihitsy no miteny!”', 'ho fantatry ny vahoakako àry ny anarako. dia ho fantany koa amin’izany andro izany fa izaho ilay miteny. izaho mihitsy no miteny!”'),
  ('6ab25b84f2ddf2abfda0a3d2', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 4, 'Izao mantsy no tenin’i Jehovah Tompo Fara Tampony: “Tamin’ny voalohany, dia nidina tany Ejipta ny vahoakako mba hivahiny tany, Dia avy eo nampijalin’i Asyria tsy amin’antony.”', 'izao mantsy no tenin’i jehovah tompo fara tampony: “tamin’ny voalohany, dia nidina tany ejipta ny vahoakako mba hivahiny tany, dia avy eo nampijalin’i asyria tsy amin’antony.”'),
  ('6ab25b84f2ddf2abfda0a3da', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 12, 'Fa tsy hisahotaka ianareo rehefa miala avy ao, Sady tsy voatery handositra. Handeha eo alohanareo mantsy i Jehovah, Ary ilay Andriamanitry ny Israely no ho vodilaharana mpiaro anareo.', 'fa tsy hisahotaka ianareo rehefa miala avy ao, sady tsy voatery handositra. handeha eo alohanareo mantsy i jehovah, ary ilay andriamanitry ny israely no ho vodilaharana mpiaro anareo.'),
  ('6ab25b84f2ddf2abfda0a3d5', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 7, 'Tsara tarehy erỳ ny tongotr’ilay mitondra vaovao tsara mandeha eny an-tendrombohitra, Ilay mitory fiadanana, Ilay mitondra vaovao tsara momba ny zavatra tsara kokoa, Ilay mitory momba ny famonjena, Dia ilay miteny amin’i Ziona hoe: “Lasa Mpanjaka ny Andriamanitrao!”', 'tsara tarehy erỳ ny tongotr’ilay mitondra vaovao tsara mandeha eny an-tendrombohitra, ilay mitory fiadanana, ilay mitondra vaovao tsara momba ny zavatra tsara kokoa, ilay mitory momba ny famonjena, dia ilay miteny amin’i ziona hoe: “lasa mpanjaka ny andriamanitrao!”'),
  ('6ab25b84f2ddf2abfda0a3cf', '2026-09-22T10:42:12.725Z', '2026-09-22T10:42:12.725Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 52, 1, 'Mifohaza, mifohaza, tafio ny herinao, ry Ziona ô! Anaovy ny akanjonao tsara tarehy, ry Jerosalema tanàna masina ô! Fa tsy hiditra ao aminao intsony ny tsy mifora sy ny tsy madio.', 'mifohaza, mifohaza, tafio ny herinao, ry ziona ô! anaovy ny akanjonao tsara tarehy, ry jerosalema tanàna masina ô! fa tsy hiditra ao aminao intsony ny tsy mifora sy ny tsy madio.'),
  ('6ab25b8939f7487be73adf29', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 18, 'Araka izay ataon’ny olona ihany no hamaliany azy: Ho tezitra amin’ny fahavalony izy, ary hamaly an’ireo miady aminy. Hovaliany araka izay sahaza azy koa ireo nosy.', 'araka izay ataon’ny olona ihany no hamaliany azy: ho tezitra amin’ny fahavalony izy, ary hamaly an’ireo miady aminy. hovaliany araka izay sahaza azy koa ireo nosy.'),
  ('6ab25b8939f7487be73adf25', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 14, 'Dia mihemotra ny rariny, Ary mijanona eny lavitra eny ny hitsiny. Tafintohina eny amin’ny tany malalaky ny tanàna mantsy ny fahamarinana, Ary tsy tafiditra eny ny fahitsiana.', 'dia mihemotra ny rariny, ary mijanona eny lavitra eny ny hitsiny. tafintohina eny amin’ny tany malalaky ny tanàna mantsy ny fahamarinana, ary tsy tafiditra eny ny fahitsiana.'),
  ('6ab25b8939f7487be73adf1f', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 8, 'Tsy fantany ny lalan’ny fiadanana, Ary tsy misy rariny eny amin’ny lalany. Ataony miolakolaka ny lalana alehany, Ka tsy hahita fiadanana mihitsy izay mandeha eny.', 'tsy fantany ny lalan’ny fiadanana, ary tsy misy rariny eny amin’ny lalany. ataony miolakolaka ny lalana alehany, ka tsy hahita fiadanana mihitsy izay mandeha eny.'),
  ('6ab25b8939f7487be73adf18', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 1, 'Tsy hoe fohy loatra ny tanan’i Jehovah ka tsy mahavonjy, Na hoe donto loatra ny sofiny ka tsy maheno.', 'tsy hoe fohy loatra ny tanan’i jehovah ka tsy mahavonjy, na hoe donto loatra ny sofiny ka tsy maheno.'),
  ('6ab25b8939f7487be73adf22', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 11, 'Mierona toy ny orsa izahay rehetra, Ary mitoreo sy malahelo toy ny voromailala. Manantena rariny izahay nefa tsy misy izany, Ary manantena famonjena nefa lavitra anay izany.', 'mierona toy ny orsa izahay rehetra, ary mitoreo sy malahelo toy ny voromailala. manantena rariny izahay nefa tsy misy izany, ary manantena famonjena nefa lavitra anay izany.'),
  ('6ab25b8939f7487be73adf27', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 16, 'Hitany fa tsy nisy olona mba hanampy, Ary gaga izy fa tsy mba nisy mpanelanelana. Ny sandriny àry no nampiasainy mba hamonjy, Ary ny fahamarinany ihany no nanohana azy.', 'hitany fa tsy nisy olona mba hanampy, ary gaga izy fa tsy mba nisy mpanelanelana. ny sandriny àry no nampiasainy mba hamonjy, ary ny fahamarinany ihany no nanohana azy.'),
  ('6ab25b8939f7487be73adf2a', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 19, 'Dia hatahotra ny anaran’i Jehovah ny avy any amin’ny filentehan’ny masoandro, Ary hatahotra ny voninahiny ny avy any amin’ny fiposahan’ny masoandro. Fa ho avy toy ny renirano misasasasa izy, Ka ny fanahin’i Jehovah no mitarika azy.', 'dia hatahotra ny anaran’i jehovah ny avy any amin’ny filentehan’ny masoandro, ary hatahotra ny voninahiny ny avy any amin’ny fiposahan’ny masoandro. fa ho avy toy ny renirano misasasasa izy, ka ny fanahin’i jehovah no mitarika azy.'),
  ('6ab25b8939f7487be73adf23', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 12, 'Imbetsaka mantsy izahay no mikomy eo anatrehanao, Ary samy miampanga anay ny fahotanay. Fantatray tsara fa mikomy foana izahay, Sady manao fahadisoana imbetsaka.', 'imbetsaka mantsy izahay no mikomy eo anatrehanao, ary samy miampanga anay ny fahotanay. fantatray tsara fa mikomy foana izahay, sady manao fahadisoana imbetsaka.'),
  ('6ab25b8939f7487be73adf1d', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 6, 'Tsy ho azo atao fitafiana ny tranon-kalany, Ary tsy ho azony irakofana ny zavatra vitany. Mampidi-doza ny zavatra ataony, Ary mahery setra foana ny tanany.', 'tsy ho azo atao fitafiana ny tranon-kalany, ary tsy ho azony irakofana ny zavatra vitany. mampidi-doza ny zavatra ataony, ary mahery setra foana ny tanany.'),
  ('6ab25b8939f7487be73adf21', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 10, 'Mitsapatsapa manara-drindrina toy ny jamba izahay, Ka mitsapatsapa toy ny olona tsy manana maso. Tafintohina izahay amin’ny mitataovovonana, hoatran’ny amin’ny takariva maizimaizina ihany, Ary hoatran’ny maty izahay rehefa miaraka amin’ireo mahery.', 'mitsapatsapa manara-drindrina toy ny jamba izahay, ka mitsapatsapa toy ny olona tsy manana maso. tafintohina izahay amin’ny mitataovovonana, hoatran’ny amin’ny takariva maizimaizina ihany, ary hoatran’ny maty izahay rehefa miaraka amin’ireo mahery.'),
  ('6ab25b8939f7487be73adf20', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 9, 'Izany no mahatonga ny rariny ho lavitra anay, Sy ny fahamarinana tsy hahatratra anay. Manantena hazavana foana izahay nefa haizina no hitanay, Ary manantena andro mazava nefa mbola mandeha ao anatin’ny haizim-pito ihany.', 'izany no mahatonga ny rariny ho lavitra anay, sy ny fahamarinana tsy hahatratra anay. manantena hazavana foana izahay nefa haizina no hitanay, ary manantena andro mazava nefa mbola mandeha ao anatin’ny haizim-pito ihany.'),
  ('6ab25b8939f7487be73adf2b', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 20, '“Ho tonga any Ziona ilay Mpanavotra, Ho tonga any amin’izay tsy mandika lalàna intsony amin’ny taranak’i Jakoba”, hoy i Jehovah.', '“ho tonga any ziona ilay mpanavotra, ho tonga any amin’izay tsy mandika lalàna intsony amin’ny taranak’i jakoba”, hoy i jehovah.'),
  ('6ab25b8939f7487be73adf24', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 13, 'Mandika lalàna sy mandà an’i Jehovah izahay, Ary manome lamosina an’Andriamanitray. Mifampiresaka foana izahay hoe hampijaly sy hikomy. Mamorona lainga ao am-ponay koa izahay, ka mingonongonona teny tsy marina.', 'mandika lalàna sy mandà an’i jehovah izahay, ary manome lamosina an’andriamanitray. mifampiresaka foana izahay hoe hampijaly sy hikomy. mamorona lainga ao am-ponay koa izahay, ka mingonongonona teny tsy marina.'),
  ('6ab25b8939f7487be73adf19', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 2, 'Tsy izany, fa ny fahadisoanareo ihany no mampisaraka anareo amin’Andriamanitrareo. Ny fahotanareo ihany koa no mahatonga azy hanafina ny tarehiny tsy ho hitanareo, Ka tsy mety mihaino anareo izy.', 'tsy izany, fa ny fahadisoanareo ihany no mampisaraka anareo amin’andriamanitrareo. ny fahotanareo ihany koa no mahatonga azy hanafina ny tarehiny tsy ho hitanareo, ka tsy mety mihaino anareo izy.'),
  ('6ab25b8939f7487be73adf1a', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 3, 'Fa mihosin-dra ny felatananareo, Ary feno fahadisoana ny rantsantananareo. Mandainga ny molotrareo, ary mingonongonona zavatra tsy marina ny vavanareo.', 'fa mihosin-dra ny felatananareo, ary feno fahadisoana ny rantsantananareo. mandainga ny molotrareo, ary mingonongonona zavatra tsy marina ny vavanareo.'),
  ('6ab25b8939f7487be73adf28', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 17, 'Dia nanaovany hoatran’ny akanjo mifono vy ny fahamarinana, Ary nataony teo amin’ny lohany ny fiarovan-doha, izany hoe ny famonjena. Notafiny koa ny valifaty, Ary nanaovany hoatran’ny akanjo ny zotom-po.', 'dia nanaovany hoatran’ny akanjo mifono vy ny fahamarinana, ary nataony teo amin’ny lohany ny fiarovan-doha, izany hoe ny famonjena. notafiny koa ny valifaty, ary nanaovany hoatran’ny akanjo ny zotom-po.'),
  ('6ab25b8939f7487be73adf1e', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 7, 'Mihazakazaka hanao ratsy ny tongony, Ary maika handatsaka ran’olona tsy manan-tsiny izy ireo. Zava-dratsy no eritreretiny, Ary fandringanana sy fandravana no eny amin’ny lalany.', 'mihazakazaka hanao ratsy ny tongony, ary maika handatsaka ran’olona tsy manan-tsiny izy ireo. zava-dratsy no eritreretiny, ary fandringanana sy fandravana no eny amin’ny lalany.'),
  ('6ab25b8939f7487be73adf1c', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 5, 'Mikotrika atodina bibilava misy poizina izy ireo, Ary manenona tranon-kala. Ho faty izay mihinana ny atodiny, Ary bibilava misy poizina no foy avy ao amin’ny atody nopotipotehina.', 'mikotrika atodina bibilava misy poizina izy ireo, ary manenona tranon-kala. ho faty izay mihinana ny atodiny, ary bibilava misy poizina no foy avy ao amin’ny atody nopotipotehina.'),
  ('6ab25b8939f7487be73adf1b', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 4, 'Tsy misy olona miantsoantso mba hiaro ny fahamarinana, Ary tsy misy milaza ny marina izay mankany amin’ny fitsarana. Zavatra tsisy dikany no ianteheran’izy ireo, ary zavatra tsisy ilana azy no teneniny. Teti-dratsy no miforona ao an-kibony, ka zava-doza no aterany.', 'tsy misy olona miantsoantso mba hiaro ny fahamarinana, ary tsy misy milaza ny marina izay mankany amin’ny fitsarana. zavatra tsisy dikany no ianteheran’izy ireo, ary zavatra tsisy ilana azy no teneniny. teti-dratsy no miforona ao an-kibony, ka zava-doza no aterany.'),
  ('6ab25b8939f7487be73adf26', '2026-09-22T10:42:17.217Z', '2026-09-22T10:42:17.217Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 15, 'Foana tsy misy intsony ny fahamarinana, Ary misy mandroba izay olona mifady ny ratsy. Nahita an’izany i Jehovah ka tena tsy faly, Satria tsy nisy intsony ny rariny.', 'foana tsy misy intsony ny fahamarinana, ary misy mandroba izay olona mifady ny ratsy. nahita an’izany i jehovah ka tena tsy faly, satria tsy nisy intsony ny rariny.'),
  ('6ab25b8939f7487be73adf2c', '2026-09-22T10:42:17.218Z', '2026-09-22T10:42:17.218Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 59, 21, '“Izao no fifanekena ataoko amin’izy ireo”, hoy i Jehovah: “Ny fanahiko izay ao aminao sy ny teniko nataoko teo am-bavanao, dia tsy hesorina eo am-bavanao, na eo am-bavan’ny zanakao, na eo am-bavan’ny zafikelinao, manomboka izao ka ho mandrakizay”, hoy i Jehovah.', '“izao no fifanekena ataoko amin’izy ireo”, hoy i jehovah: “ny fanahiko izay ao aminao sy ny teniko nataoko teo am-bavanao, dia tsy hesorina eo am-bavanao, na eo am-bavan’ny zanakao, na eo am-bavan’ny zafikelinao, manomboka izao ka ho mandrakizay”, hoy i jehovah.'),
  ('6ab25b8a184eceb0c0410e93', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 5, '“Vahiny no ho avy hiandry ny andian’ondrinareo, Ary olona hafa firenena no ho mpambolinareo sy mpikarakara ny tanimboalobokareo.', '“vahiny no ho avy hiandry ny andian’ondrinareo, ary olona hafa firenena no ho mpambolinareo sy mpikarakara ny tanimboalobokareo.'),
  ('6ab25b8a184eceb0c0410e92', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 4, 'Dia hamboarin’izy ireo indray ny toerana efa rava taloha, Ary haoriny ny toerana efa tsy nisy mponina hatramin’ny ela, Haveriny amin’ny laoniny koa ny tanàna rava, Dia izay toerana tsy nisy mponina nandritra ny taranaka nifandimby.', 'dia hamboarin’izy ireo indray ny toerana efa rava taloha, ary haoriny ny toerana efa tsy nisy mponina hatramin’ny ela, haveriny amin’ny laoniny koa ny tanàna rava, dia izay toerana tsy nisy mponina nandritra ny taranaka nifandimby.'),
  ('6ab25b8a184eceb0c0410e91', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 3, 'Sy hanome izay ilain’ireo malahelo noho izay nanjo an’i Ziona, Ka hanome azy fehiloha ho solon’ny lavenona, Menaka mahafalifaly ho solon’ny alahelo, Ary akanjo fiderana ho solon’ny hakiviana. Hantsoina hoe hazoben’ny fahamarinana izy ireo, Dia hazo nambolen’i Jehovah mba hanomezam-boninahitra azy.', 'sy hanome izay ilain’ireo malahelo noho izay nanjo an’i ziona, ka hanome azy fehiloha ho solon’ny lavenona, menaka mahafalifaly ho solon’ny alahelo, ary akanjo fiderana ho solon’ny hakiviana. hantsoina hoe hazoben’ny fahamarinana izy ireo, dia hazo nambolen’i jehovah mba hanomezam-boninahitra azy.'),
  ('6ab25b8a184eceb0c0410e96', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 8, 'Fa izaho Jehovah dia tia rariny, Sady mankahala ny fandrobana sy ny tsy fahamarinana. Mendri-pitokisana aho ka homeko foana ny karaman’izy ireo, Ary hanao fifanekena mandrakizay aminy aho.', 'fa izaho jehovah dia tia rariny, sady mankahala ny fandrobana sy ny tsy fahamarinana. mendri-pitokisana aho ka homeko foana ny karaman’izy ireo, ary hanao fifanekena mandrakizay aminy aho.'),
  ('6ab25b8a184eceb0c0410e90', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 2, 'Nirahiny koa aho hitory ny taona fanehoan’i Jehovah fankasitrahana, Sy ny andro famalian’ilay Andriamanitsika, Mba hampionona an’izay malahelo rehetra,', 'nirahiny koa aho hitory ny taona fanehoan’i jehovah fankasitrahana, sy ny andro famalian’ilay andriamanitsika, mba hampionona an’izay malahelo rehetra,'),
  ('6ab25b8a184eceb0c0410e98', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 10, 'Ho faly be aho noho ny amin’i Jehovah, Ary hiravoravo aho noho ny amin’ilay Andriamanitro. Efa nampanaoviny ahy toy ny akanjo mantsy ny famonjena, Ary efa nampitafiany ahy toy ny akanjo lava ny fahamarinana, Ka hoatran’ny mpampakatra manao fehiloha mitovy amin’ny an’ny mpisorona aho, Ary hoatran’ny ampakarina manao firavaka.', 'ho faly be aho noho ny amin’i jehovah, ary hiravoravo aho noho ny amin’ilay andriamanitro. efa nampanaoviny ahy toy ny akanjo mantsy ny famonjena, ary efa nampitafiany ahy toy ny akanjo lava ny fahamarinana, ka hoatran’ny mpampakatra manao fehiloha mitovy amin’ny an’ny mpisorona aho, ary hoatran’ny ampakarina manao firavaka.'),
  ('6ab25b8a184eceb0c0410e97', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 9, 'Ho fantatr’ireo firenena ny zanak’izy ireo, Ary ho fantatry ny vahoaka ny taranany. Izay rehetra mahita azy dia hahafantatra hoe Izy ireo no taranaka notahin’i Jehovah.”', 'ho fantatr’ireo firenena ny zanak’izy ireo, ary ho fantatry ny vahoaka ny taranany. izay rehetra mahita azy dia hahafantatra hoe izy ireo no taranaka notahin’i jehovah.”'),
  ('6ab25b8a184eceb0c0410e8f', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 1, 'Ny fanahin’i Jehovah Tompo Fara Tampony no ato amiko, Satria nanosotra ahy hilaza vaovao tsara amin’ny mpandefitra i Jehovah. Nirahiny hanisy fehy lamba ny ratran’ny torotoro fo aho, Sy hanambara hoe ho afaka ny babo, Ary hampahiratina ny mason’ny voafonja mba tena hahita tsara.', 'ny fanahin’i jehovah tompo fara tampony no ato amiko, satria nanosotra ahy hilaza vaovao tsara amin’ny mpandefitra i jehovah. nirahiny hanisy fehy lamba ny ratran’ny torotoro fo aho, sy hanambara hoe ho afaka ny babo, ary hampahiratina ny mason’ny voafonja mba tena hahita tsara.'),
  ('6ab25b8a184eceb0c0410e99', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 11, 'Mampitsiry voa ny tany, Ary mampitsimoka an’izay nafafy teo aminy ny tanimboly. Dia hoatr’izany koa no ataon’i Jehovah Tompo Fara Tampony, Satria hataony mitsiry eo anatrehan’ny firenena rehetra ny fahamarinana sy fiderana.', 'mampitsiry voa ny tany, ary mampitsimoka an’izay nafafy teo aminy ny tanimboly. dia hoatr’izany koa no ataon’i jehovah tompo fara tampony, satria hataony mitsiry eo anatrehan’ny firenena rehetra ny fahamarinana sy fiderana.'),
  ('6ab25b8a184eceb0c0410e94', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 6, 'Fa ianareo indray, hantsoina hoe mpisoron’i Jehovah. Ary hiantso anareo hoe mpanompon’ilay Andriamanitsika izy ireo. Hihinana ny fananan’ny firenena ianareo, Ary hirehareha amin’ny voninahitr’izy ireo.', 'fa ianareo indray, hantsoina hoe mpisoron’i jehovah. ary hiantso anareo hoe mpanompon’ilay andriamanitsika izy ireo. hihinana ny fananan’ny firenena ianareo, ary hirehareha amin’ny voninahitr’izy ireo.'),
  ('6ab25b8a184eceb0c0410e95', '2026-09-22T10:42:18.737Z', '2026-09-22T10:42:18.737Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 61, 7, 'Hahazo anjara avo roa heny ny vahoakako ho solon’ny henatra, Ary tsy ho afa-baraka intsony izy fa hihoby noho ny anjarany. Hahazo anjara avo roa heny tokoa izy ireo ao amin’ny taniny, Dia hifaly mandrakizay.', 'hahazo anjara avo roa heny ny vahoakako ho solon’ny henatra, ary tsy ho afa-baraka intsony izy fa hihoby noho ny anjarany. hahazo anjara avo roa heny tokoa izy ireo ao amin’ny taniny, dia hifaly mandrakizay.'),
  ('6ab25b8bc12a04e832b9fbcf', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 11, 'Izao no nolazain’i Jehovah hatrany amin’ny faran’ny tany: “Teneno i Ziona zanakavavy hoe: ‘Efa kely sisa dia hovonjena ianao. Efa eny aminy ny valisoa homeny, Ary efa any aminy ny karama haloany.’”', 'izao no nolazain’i jehovah hatrany amin’ny faran’ny tany: “teneno i ziona zanakavavy hoe: ‘efa kely sisa dia hovonjena ianao. efa eny aminy ny valisoa homeny, ary efa any aminy ny karama haloany.’”'),
  ('6ab25b8bc12a04e832b9fbce', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 10, 'Mivoaha amin’ny vavahady, mivoaha! Karakarao izay lalana halehan’ny olona! Manamboara lalambe, manamboara! Esory izay vato eny. Manangàna tsato-kazo famantarana ho an’ireo firenena.', 'mivoaha amin’ny vavahady, mivoaha! karakarao izay lalana halehan’ny olona! manamboara lalambe, manamboara! esory izay vato eny. manangàna tsato-kazo famantarana ho an’ireo firenena.'),
  ('6ab25b8bc12a04e832b9fbcc', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 8, 'Efa nanangana ny tanany ankavanana sy ny sandriny mahery i Jehovah, ka nianiana hoe: “Tsy homeko ho sakafon’ny fahavalonao intsony ny varimbazahanao, Ary tsy hosotroin’ny hafa firenena intsony ny divainao vaovao, izay efa nisasaranao.', 'efa nanangana ny tanany ankavanana sy ny sandriny mahery i jehovah, ka nianiana hoe: “tsy homeko ho sakafon’ny fahavalonao intsony ny varimbazahanao, ary tsy hosotroin’ny hafa firenena intsony ny divainao vaovao, izay efa nisasaranao.'),
  ('6ab25b8bc12a04e832b9fbca', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 6, 'Efa nanendry mpitily ho eny ambonin’ny mandanao aho, ry Jerosalema ô! Tsy tokony hangina mihitsy izy ireo, na andro na alina. “Ianareo izay miresaka momba an’i Jehovah, Aza mitsahatra mihitsy,', 'efa nanendry mpitily ho eny ambonin’ny mandanao aho, ry jerosalema ô! tsy tokony hangina mihitsy izy ireo, na andro na alina. “ianareo izay miresaka momba an’i jehovah, aza mitsahatra mihitsy,'),
  ('6ab25b8bc12a04e832b9fbcd', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 9, 'Fa izay mijinja azy ihany no hihinana azy, ka hidera an’i Jehovah. Dia izay mioty azy ihany no hisotro azy ao amin’ny tokotaniko masina.”', 'fa izay mijinja azy ihany no hihinana azy, ka hidera an’i jehovah. dia izay mioty azy ihany no hisotro azy ao amin’ny tokotaniko masina.”'),
  ('6ab25b8bc12a04e832b9fbd0', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 12, 'Dia hantsoina hoe vahoaka masina navotan’i Jehovah izy ireo. Ary ianao koa hantsoina hoe Ilay Notadiavina, Tanàna Tsy Nilaozana.', 'dia hantsoina hoe vahoaka masina navotan’i jehovah izy ireo. ary ianao koa hantsoina hoe ilay notadiavina, tanàna tsy nilaozana.'),
  ('6ab25b8bc12a04e832b9fbc7', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 3, 'Ho lasa satroboninahitra tsara tarehy eo an-tanan’i Jehovah ianao, Ho fehilohan’ny mpanjaka, eo am-pelatanan’ilay Andriamanitrao.', 'ho lasa satroboninahitra tsara tarehy eo an-tanan’i jehovah ianao, ho fehilohan’ny mpanjaka, eo am-pelatanan’ilay andriamanitrao.'),
  ('6ab25b8bc12a04e832b9fbc9', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 5, 'Fa hoatran’ny tovolahy manambady virjiny, Dia hanambady anao koa ny zanakao. Faly be amin’ny ampakarina ny mpampakatra, Dia hoatr’izany koa fa ho faly be aminao ilay Andriamanitrao.', 'fa hoatran’ny tovolahy manambady virjiny, dia hanambady anao koa ny zanakao. faly be amin’ny ampakarina ny mpampakatra, dia hoatr’izany koa fa ho faly be aminao ilay andriamanitrao.'),
  ('6ab25b8bc12a04e832b9fbc5', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 1, 'Tsy hangina aho noho ny amin’i Ziona, Ary tsy hipetra-potsiny aho noho ny amin’i Jerosalema, Raha tsy efa mamirapiratra hoatran’ny hazavana ny fahamarinany, Ary raha tsy efa mirehitra hoatran’ny fanilo ny famonjena azy.', 'tsy hangina aho noho ny amin’i ziona, ary tsy hipetra-potsiny aho noho ny amin’i jerosalema, raha tsy efa mamirapiratra hoatran’ny hazavana ny fahamarinany, ary raha tsy efa mirehitra hoatran’ny fanilo ny famonjena azy.'),
  ('6ab25b8bc12a04e832b9fbc8', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 4, 'Tsy hantsoina intsony hoe vehivavy nilaozam-bady ianao, Ary ny taninao tsy hatao intsony hoe tany tsy misy mponina. Fa ianao kosa hantsoina hoe Sitrako Izy, Ary ny taninao hoe Ilay Manambady. Fa hankasitraka anao i Jehovah, Ary ny taninao ho lasa hoatran’ny hoe manambady.', 'tsy hantsoina intsony hoe vehivavy nilaozam-bady ianao, ary ny taninao tsy hatao intsony hoe tany tsy misy mponina. fa ianao kosa hantsoina hoe sitrako izy, ary ny taninao hoe ilay manambady. fa hankasitraka anao i jehovah, ary ny taninao ho lasa hoatran’ny hoe manambady.'),
  ('6ab25b8bc12a04e832b9fbc6', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 2, '“Hahita ny fahamarinanao ny firenena, ry vehivavy, Ary hahita ny voninahitrao ny mpanjaka rehetra. Dia homena anarana vaovao ianao, Ka i Jehovah mihitsy no hanome an’izany.', '“hahita ny fahamarinanao ny firenena, ry vehivavy, ary hahita ny voninahitrao ny mpanjaka rehetra. dia homena anarana vaovao ianao, ka i jehovah mihitsy no hanome an’izany.'),
  ('6ab25b8bc12a04e832b9fbcb', '2026-09-22T10:42:19.249Z', '2026-09-22T10:42:19.249Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 62, 7, 'Dia aza avela hitsahatra mihitsy koa izy, raha tsy efa voaoriny mafy i Jerosalema, Ary raha tsy efa ataony midera azy io ny olona eran-tany.”', 'dia aza avela hitsahatra mihitsy koa izy, raha tsy efa voaoriny mafy i jerosalema, ary raha tsy efa ataony midera azy io ny olona eran-tany.”'),
  ('6ab25b8c78d66a2c510a3da4', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 14, 'Hoatran’ny biby fiompy midina eny amin’ny tany lemaka mba hiala sasatra, Dia hoatr’izany koa fa nataon’ny fanahin’i Jehovah niala sasatra izy ireo.” Izany no fomba nitarihanao ny vahoakanao, Mba ho lasa be voninahitra ny anaranao.', 'hoatran’ny biby fiompy midina eny amin’ny tany lemaka mba hiala sasatra, dia hoatr’izany koa fa nataon’ny fanahin’i jehovah niala sasatra izy ireo.” izany no fomba nitarihanao ny vahoakanao, mba ho lasa be voninahitra ny anaranao.'),
  ('6ab25b8c78d66a2c510a3da1', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 11, 'Dia nahatsiaro ny andro fahiny izy ireo, Dia ny andron’i Mosesy mpanompony, ka niteny hoe: “Fa aiza Ilay nitondra azy ireo niakatra avy tany an-dranomasina, niaraka tamin’ny mpiandry ny andian’ondriny? Aiza Ilay nametraka ny fanahiny masina tao aminy?', 'dia nahatsiaro ny andro fahiny izy ireo, dia ny andron’i mosesy mpanompony, ka niteny hoe: “fa aiza ilay nitondra azy ireo niakatra avy tany an-dranomasina, niaraka tamin’ny mpiandry ny andian’ondriny? aiza ilay nametraka ny fanahiny masina tao aminy?'),
  ('6ab25b8c78d66a2c510a3d98', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 2, 'Nahoana no mena ny fitafianao, Ary nahoana ny akanjonao no hoatran’ny an’ny mpanitsakitsaka voaloboka ao anaty lavaka famiazam-boaloboka?', 'nahoana no mena ny fitafianao, ary nahoana ny akanjonao no hoatran’ny an’ny mpanitsakitsaka voaloboka ao anaty lavaka famiazam-boaloboka?'),
  ('6ab25b8c78d66a2c510a3d9b', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 5, 'Nijery aho fa tsy mba nisy nanampy. Gaga be aho fa tsy nisy nanome tanana ahy. Ny sandriko àry no nampiasaiko hamonjena, Ary ny hatezerako no nanampy ahy.', 'nijery aho fa tsy mba nisy nanampy. gaga be aho fa tsy nisy nanome tanana ahy. ny sandriko àry no nampiasaiko hamonjena, ary ny hatezerako no nanampy ahy.'),
  ('6ab25b8c78d66a2c510a3da7', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 17, 'Jehovah ô, fa maninona izahay no avelanao hirenireny hiala amin’ny lalanao? Maninona no avelanao ho lasa mafy fo izahay, ka lasa tsy matahotra anao? Miverena noho ny amin’ny mpanomponao, Dia ilay vahoaka lovanao.', 'jehovah ô, fa maninona izahay no avelanao hirenireny hiala amin’ny lalanao? maninona no avelanao ho lasa mafy fo izahay, ka lasa tsy matahotra anao? miverena noho ny amin’ny mpanomponao, dia ilay vahoaka lovanao.'),
  ('6ab25b8c78d66a2c510a3da2', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 12, 'Aiza Ilay nanohana ny tanana ankavanan’i Mosesy tamin’ny sandriny be voninahitra, Dia Ilay nanasaraka ny rano teo alohan’izy ireo, Mba hampahalaza ny anarany mandrakizay?', 'aiza ilay nanohana ny tanana ankavanan’i mosesy tamin’ny sandriny be voninahitra, dia ilay nanasaraka ny rano teo alohan’izy ireo, mba hampahalaza ny anarany mandrakizay?'),
  ('6ab25b8c78d66a2c510a3da6', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 16, 'Fa ianao no Rainay. Na tsy fantatr’i Abrahama aza izahay, Ary na tsy fantatr’i Israely aza, Dia ianao no Rainay, Jehovah ô! Ianao no Mpanavotra anay hatrizay hatrizay, ary izany no anaranao.', 'fa ianao no rainay. na tsy fantatr’i abrahama aza izahay, ary na tsy fantatr’i israely aza, dia ianao no rainay, jehovah ô! ianao no mpanavotra anay hatrizay hatrizay, ary izany no anaranao.'),
  ('6ab25b8c78d66a2c510a3da0', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 10, 'Nikomy anefa izy ireo, ka nanao izay nampalahelo ny fanahiny masina. Lasa fahavalon’izy ireo àry izy, Ka niady taminy.', 'nikomy anefa izy ireo, ka nanao izay nampalahelo ny fanahiny masina. lasa fahavalon’izy ireo àry izy, ka niady taminy.'),
  ('6ab25b8c78d66a2c510a3d9d', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 7, 'Horesahiko ny zavatra ataon’i Jehovah mampiseho hoe be fitiavana sy tsy mivadika izy, Ny zavatra ataon’i Jehovah izay mendri-piderana, Noho izay rehetra ataon’i Jehovah ho antsika, Dia ny zavatra tsara be dia be nataony ho an’ny taranak’Israely. Mamindra fo mantsy izy sady tena be fitiavana sy tsy mivadika.', 'horesahiko ny zavatra ataon’i jehovah mampiseho hoe be fitiavana sy tsy mivadika izy, ny zavatra ataon’i jehovah izay mendri-piderana, noho izay rehetra ataon’i jehovah ho antsika, dia ny zavatra tsara be dia be nataony ho an’ny taranak’israely. mamindra fo mantsy izy sady tena be fitiavana sy tsy mivadika.'),
  ('6ab25b8c78d66a2c510a3d9c', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 6, 'Nohitsakitsahiko ireo firenena sady tezitra ihany aho, Ka nataoko mamon’ny hatezerako ireny. Dia nataoko nandriaka tamin’ny tany ny rany.”', 'nohitsakitsahiko ireo firenena sady tezitra ihany aho, ka nataoko mamon’ny hatezerako ireny. dia nataoko nandriaka tamin’ny tany ny rany.”'),
  ('6ab25b8c78d66a2c510a3da5', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 15, 'Mijere avy any an-danitra, Dia mitazàna avy eny amin’ny fonenanao avo, izay sady masina no be voninahitra. Aiza ilay hoe be zotom-po sy mahery ianao, Sady hoe te hangoraka mafy sy mamindra fo? Tsy manao an’izany aminay intsony ianao.', 'mijere avy any an-danitra, dia mitazàna avy eny amin’ny fonenanao avo, izay sady masina no be voninahitra. aiza ilay hoe be zotom-po sy mahery ianao, sady hoe te hangoraka mafy sy mamindra fo? tsy manao an’izany aminay intsony ianao.'),
  ('6ab25b8c78d66a2c510a3d9e', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 8, 'Fa hoy izy: “Vahoakako tokoa ireo, sady zanaka tsy hivadika.” Lasa Mpamonjy an’ireo àry izy.', 'fa hoy izy: “vahoakako tokoa ireo, sady zanaka tsy hivadika.” lasa mpamonjy an’ireo àry izy.'),
  ('6ab25b8c78d66a2c510a3d99', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 3, '“Izaho irery no nanitsakitsaka ny voaloboka tao anaty lavaka famiazana azy, Fa tsy nisy niaraka tamiko ny olona avy any amin’ireo firenena. Dia nohitsakitsahiko ireny sady tezitra ihany aho, Ary nohosihoseko ireny sady nisafoaka ihany aho. Dia nipitipitika teo amin’ny akanjoko ny rany, Ka nolotoiko ny akanjoko rehetra.', '“izaho irery no nanitsakitsaka ny voaloboka tao anaty lavaka famiazana azy, fa tsy nisy niaraka tamiko ny olona avy any amin’ireo firenena. dia nohitsakitsahiko ireny sady tezitra ihany aho, ary nohosihoseko ireny sady nisafoaka ihany aho. dia nipitipitika teo amin’ny akanjoko ny rany, ka nolotoiko ny akanjoko rehetra.'),
  ('6ab25b8c78d66a2c510a3da9', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 19, 'Lasa hoatran’ny olona tsy mba nofehezinao mihitsy izahay nandritra ny fotoana ela be, Sady toy ny hoe tsy mba nantsoina tamin’ny anaranao mihitsy.', 'lasa hoatran’ny olona tsy mba nofehezinao mihitsy izahay nandritra ny fotoana ela be, sady toy ny hoe tsy mba nantsoina tamin’ny anaranao mihitsy.'),
  ('6ab25b8c78d66a2c510a3d97', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 1, 'Iza iny tamy avy any Edoma iny, Iny avy any Bozra iny, sady manao akanjo marevaka? Manao fitafiana tsara be koa izy, Sady hita amin’ny fandehany hoe tena mahery sy manana fahefana. “Tsy iza fa izaho, Ilay milaza ny marina, Ilay manan-kery lehibe hamonjena.”', 'iza iny tamy avy any edoma iny, iny avy any bozra iny, sady manao akanjo marevaka? manao fitafiana tsara be koa izy, sady hita amin’ny fandehany hoe tena mahery sy manana fahefana. “tsy iza fa izaho, ilay milaza ny marina, ilay manan-kery lehibe hamonjena.”'),
  ('6ab25b8c78d66a2c510a3da3', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 13, 'Aiza Ilay nampandeha azy ireo namakivaky ny rano manonja be, Mba tsy ho tafintohina izy ireo rehefa mandeha, Hoatran’ny soavaly mikarenjy eny an-tanety?', 'aiza ilay nampandeha azy ireo namakivaky ny rano manonja be, mba tsy ho tafintohina izy ireo rehefa mandeha, hoatran’ny soavaly mikarenjy eny an-tanety?'),
  ('6ab25b8c78d66a2c510a3d9a', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 4, 'Fa efa ato am-poko ny andro hanaovako valifaty, Ary efa tonga ny taona hanavotako ny vahoakako.', 'fa efa ato am-poko ny andro hanaovako valifaty, ary efa tonga ny taona hanavotako ny vahoakako.'),
  ('6ab25b8c78d66a2c510a3da8', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 18, 'Fotoana fohy ihany ny vahoakanao masina no nanana an’ilay tany nomenao, Dia nohitsakitsahin’ny fahavalonay ny toeranao masina.', 'fotoana fohy ihany ny vahoakanao masina no nanana an’ilay tany nomenao, dia nohitsakitsahin’ny fahavalonay ny toeranao masina.'),
  ('6ab25b8c78d66a2c510a3d9f', '2026-09-22T10:42:20.003Z', '2026-09-22T10:42:20.003Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 63, 9, 'Nalahelo be izy tamin’ny fotoana rehetra nijalian’izy ireo, Ka ilay iraka manokana nalefany no namonjy azy ireo. Be fitiavana sy mangoraka izy ka nanavotra azy ireo. Dia nibata sy nitondra azy foana izy nandritra an’ireny taona lasa rehetra ireny.', 'nalahelo be izy tamin’ny fotoana rehetra nijalian’izy ireo, ka ilay iraka manokana nalefany no namonjy azy ireo. be fitiavana sy mangoraka izy ka nanavotra azy ireo. dia nibata sy nitondra azy foana izy nandritra an’ireny taona lasa rehetra ireny.'),
  ('6ab25b8ce85bae8bcd7909b4', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 10, 'Lasa tany efitra ireo tanànanao masina. Lasa tany efitra koa i Ziona, Ary lasa ngazana i Jerosalema.', 'lasa tany efitra ireo tanànanao masina. lasa tany efitra koa i ziona, ary lasa ngazana i jerosalema.'),
  ('6ab25b8ce85bae8bcd7909ae', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 4, 'Efa hatramin’ny taloha no tsy nisy naheno na nandre, Na nahita Andriamanitra ankoatra anao, Dia ilay Andriamanitra manao zavatra ho an’izay manantena azy foana.', 'efa hatramin’ny taloha no tsy nisy naheno na nandre, na nahita andriamanitra ankoatra anao, dia ilay andriamanitra manao zavatra ho an’izay manantena azy foana.'),
  ('6ab25b8ce85bae8bcd7909ad', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 3, 'Rehefa nanao zavatra mahatalanjona ianao, zavatra tsy sahinay nantenaina akory, Dia nidina ianao, ary nihovotrovotra teo anatrehanao ny tendrombohitra.', 'rehefa nanao zavatra mahatalanjona ianao, zavatra tsy sahinay nantenaina akory, dia nidina ianao, ary nihovotrovotra teo anatrehanao ny tendrombohitra.'),
  ('6ab25b8ce85bae8bcd7909b6', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 12, 'Dia mbola tsy hanao zavatra ihany ve ianao, Jehovah ô? Mbola hangina ihany ve ianao ka hamela anay hijaly be hoatr’izao?', 'dia mbola tsy hanao zavatra ihany ve ianao, jehovah ô? mbola hangina ihany ve ianao ka hamela anay hijaly be hoatr’izao?'),
  ('6ab25b8ce85bae8bcd7909ac', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 2, 'Hoatran’ny afo mandoro kirihitra, Sy hoatran’ny afo mampangotraka rano, Dia ho fantatry ny fahavalonao ny anaranao, Ka hangovitra eo anatrehanao ny firenena.', 'hoatran’ny afo mandoro kirihitra, sy hoatran’ny afo mampangotraka rano, dia ho fantatry ny fahavalonao ny anaranao, ka hangovitra eo anatrehanao ny firenena.'),
  ('6ab25b8ce85bae8bcd7909b0', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 6, 'Lasa hoatran’ny olona maloto daholo izahay, Ary toy ny akanjo voaloton’ny fadimbolana ny tsara rehetra vitanay. Halazo hoatran’ny ravinkazo izahay rehetra, Ary hipaoka anay toy ny rivotra ny fahadisoanay.', 'lasa hoatran’ny olona maloto daholo izahay, ary toy ny akanjo voaloton’ny fadimbolana ny tsara rehetra vitanay. halazo hoatran’ny ravinkazo izahay rehetra, ary hipaoka anay toy ny rivotra ny fahadisoanay.'),
  ('6ab25b8ce85bae8bcd7909b1', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 7, 'Tsy mba misy olona miantso ny anaranao, Sady tsy mba misy miezaka ny hifikitra aminao. Fa afeninao tsy ho hitanay ny tarehinao, Ary ataonao lasa reraka izahay noho ny fahadisoanay.', 'tsy mba misy olona miantso ny anaranao, sady tsy mba misy miezaka ny hifikitra aminao. fa afeninao tsy ho hitanay ny tarehinao, ary ataonao lasa reraka izahay noho ny fahadisoanay.'),
  ('6ab25b8ce85bae8bcd7909b2', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 8, 'Ianao anefa izao no Rainay, Jehovah ô! Tanimanga izahay, ary ianao no Mpanefy anay. Asan’ny tananao daholo izahay.', 'ianao anefa izao no rainay, jehovah ô! tanimanga izahay, ary ianao no mpanefy anay. asan’ny tananao daholo izahay.'),
  ('6ab25b8ce85bae8bcd7909af', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 5, 'Tsenainao izay faly manao ny tsara, Dia izay mahatsiaro anao ka manaraka ny lalanao. Tezitra ianao rehefa nanota foana izahay. Nanota nandritra ny fotoana ela be mantsy izahay. Dia ho voavonjy ve izahay izao?', 'tsenainao izay faly manao ny tsara, dia izay mahatsiaro anao ka manaraka ny lalanao. tezitra ianao rehefa nanota foana izahay. nanota nandritra ny fotoana ela be mantsy izahay. dia ho voavonjy ve izahay izao?'),
  ('6ab25b8ce85bae8bcd7909ab', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 1, 'Raha mba norovitinao mantsy ny lanitra ka nidina ianao, Dia hihovotrovotra eo anatrehanao ny tendrombohitra,', 'raha mba norovitinao mantsy ny lanitra ka nidina ianao, dia hihovotrovotra eo anatrehanao ny tendrombohitra,'),
  ('6ab25b8ce85bae8bcd7909b5', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 11, 'Masina sady be voninahitra ilay tranonay, Dia tao ny razambenay no nidera anao. Kilan’ny afo anefa ilay izy, Ary ravarava ny zava-drehetra tianay.', 'masina sady be voninahitra ilay tranonay, dia tao ny razambenay no nidera anao. kilan’ny afo anefa ilay izy, ary ravarava ny zava-drehetra tianay.'),
  ('6ab25b8ce85bae8bcd7909b3', '2026-09-22T10:42:20.505Z', '2026-09-22T10:42:20.505Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 64, 9, 'Aza tezitra be loatra, Jehovah ô, Ary aza tsaroana mandrakizay ny fahadisoanay. Mba jereo izahay fa vahoakanao daholo ange izahay e!', 'aza tezitra be loatra, jehovah ô, ary aza tsaroana mandrakizay ny fahadisoanay. mba jereo izahay fa vahoakanao daholo ange izahay e!'),
  ('6ab25b8d13be424f14e2d5f6', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 15, 'Anarana sisa no mba ho tavela aminareo, dia anarana hampiasain’ny olom-boafidiko hanozonana. Ary hamono anareo tsirairay i Jehovah Tompo Fara Tampony, Fa ny mpanompony kosa hantsoiny amin’ny anarana hafa.', 'anarana sisa no mba ho tavela aminareo, dia anarana hampiasain’ny olom-boafidiko hanozonana. ary hamono anareo tsirairay i jehovah tompo fara tampony, fa ny mpanompony kosa hantsoiny amin’ny anarana hafa.'),
  ('6ab25b8d13be424f14e2d5ed', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 6, 'Efa voasoratra eo anatrehako izany. Tsy hipetra-potsiny aho, Fa hamaly azy ireo. Hovaliako izy ireo ka hosaziko noho izay rehetra nataony,', 'efa voasoratra eo anatrehako izany. tsy hipetra-potsiny aho, fa hamaly azy ireo. hovaliako izy ireo ka hosaziko noho izay rehetra nataony,'),
  ('6ab25b8d13be424f14e2d5e9', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 2, 'Mamelatra ny tanako tontolo andro amin’ny vahoaka mafy loha aho, Dia amin’izay mandeha amin’ny lalan-dratsy, Sady manao izay saim-pantany fotsiny.', 'mamelatra ny tanako tontolo andro amin’ny vahoaka mafy loha aho, dia amin’izay mandeha amin’ny lalan-dratsy, sady manao izay saim-pantany fotsiny.'),
  ('6ab25b8d13be424f14e2d5fa', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 19, 'Hifaly noho ny amin’i Jerosalema aho, ary hiravoravo noho ny amin’ny vahoakako. Dia tsy ho heno ao aminy intsony ny feon’olona mitomany na mitaraindraina.”', 'hifaly noho ny amin’i jerosalema aho, ary hiravoravo noho ny amin’ny vahoakako. dia tsy ho heno ao aminy intsony ny feon’olona mitomany na mitaraindraina.”'),
  ('6ab25b8d13be424f14e2d5eb', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 4, 'Mipetrapetraka eny amin’ny fasana izy ireo, Ary mijanona mandritra ny alina ao amin’ny toerana miafina, Sady mihinana henan-kisoa Sy ron-javatra maloto eo am-biliany.', 'mipetrapetraka eny amin’ny fasana izy ireo, ary mijanona mandritra ny alina ao amin’ny toerana miafina, sady mihinana henan-kisoa sy ron-javatra maloto eo am-biliany.'),
  ('6ab25b8d13be424f14e2d5f5', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 14, 'Ny mpanompoko hihoby satria falifaly ny fony, Fa ianareo kosa hitaraindraina satria malahelo ny fonareo, Ary hidradradradra satria kivy.', 'ny mpanompoko hihoby satria falifaly ny fony, fa ianareo kosa hitaraindraina satria malahelo ny fonareo, ary hidradradradra satria kivy.'),
  ('6ab25b8d13be424f14e2d5f2', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 11, 'Anisan’izay mahafoy an’i Jehovah anefa ianareo, Dia izay manadino ny tendrombohitro masina, Sy manomana latabatra ho an’ny andriamanitry ny Vintana, Ary mameno kaopy amin’ny divay misy fangarony ho an’ny andriamanitry ny Lahatra.', 'anisan’izay mahafoy an’i jehovah anefa ianareo, dia izay manadino ny tendrombohitro masina, sy manomana latabatra ho an’ny andriamanitry ny vintana, ary mameno kaopy amin’ny divay misy fangarony ho an’ny andriamanitry ny lahatra.'),
  ('6ab25b8d13be424f14e2d5f1', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 10, 'Ho lasa kijana ho an’ny ondry i Sarôna, Ary ny Lohasahan’i Akora ho toerana fialan-tsasatra ho an’ny omby. Izany no hataoko ho an’ilay vahoakako mitady ahy.', 'ho lasa kijana ho an’ny ondry i sarôna, ary ny lohasahan’i akora ho toerana fialan-tsasatra ho an’ny omby. izany no hataoko ho an’ilay vahoakako mitady ahy.'),
  ('6ab25b8d13be424f14e2d5fb', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 20, '“Tsy hisy ao amin’io toerana io intsony izany hoe zaza velona andro vitsivitsy fotsiny izany, Na hoe olona antitra tsy mahatapitra ny androm-piainany. Fa mbola heverina ho ankizilahy ihany izay maty, na dia zato taona aza, Ary ny mpanota kosa hozonina, na dia efa zato taona aza.', '“tsy hisy ao amin’io toerana io intsony izany hoe zaza velona andro vitsivitsy fotsiny izany, na hoe olona antitra tsy mahatapitra ny androm-piainany. fa mbola heverina ho ankizilahy ihany izay maty, na dia zato taona aza, ary ny mpanota kosa hozonina, na dia efa zato taona aza.'),
  ('6ab25b8d13be424f14e2d5ee', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 7, 'Noho ny fahadisoany sy ny fahadisoan’ny razambeny”, hoy i Jehovah. “Nandoro fanatitra mba hidona-tsetroka teny an-tendrombohitra izy ireo, Sady nanala baraka ahy teny amin’ny havoana, Ka hafatrako daholo aloha ny karamany.”', 'noho ny fahadisoany sy ny fahadisoan’ny razambeny”, hoy i jehovah. “nandoro fanatitra mba hidona-tsetroka teny an-tendrombohitra izy ireo, sady nanala baraka ahy teny amin’ny havoana, ka hafatrako daholo aloha ny karamany.”'),
  ('6ab25b8d13be424f14e2d5f3', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 12, 'Dia hatolotro ho fatin’ny sabatra ianareo, Ary hiankohoka mba hovonoina daholo. Niantso mantsy aho, fa tsy namaly ianareo. Niteny aho, fa tsy nihaino ianareo. Nanao izay ratsy teo imasoko foana koa ianareo, Ary ny zavatra tsy tiako no nofidinareo.”', 'dia hatolotro ho fatin’ny sabatra ianareo, ary hiankohoka mba hovonoina daholo. niantso mantsy aho, fa tsy namaly ianareo. niteny aho, fa tsy nihaino ianareo. nanao izay ratsy teo imasoko foana koa ianareo, ary ny zavatra tsy tiako no nofidinareo.”'),
  ('6ab25b8d13be424f14e2d5ea', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 3, 'Vahoaka manao izay hampahatezitra ahy foana izy ireo, Sady manao sorona eny an-jaridaina sy mandoro fanatitra mba hidona-tsetroka eny ambonin’ny biriky.', 'vahoaka manao izay hampahatezitra ahy foana izy ireo, sady manao sorona eny an-jaridaina sy mandoro fanatitra mba hidona-tsetroka eny ambonin’ny biriky.'),
  ('6ab25b8d13be424f14e2d5f4', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 13, 'Izao àry no tenin’i Jehovah Tompo Fara Tampony: “Ny mpanompoko hihinana, fa ianareo kosa ho noana. Ny mpanompoko hisotro, fa ianareo kosa hangetaheta. Ny mpanompoko hifaly, fa ianareo kosa ho afa-baraka.', 'izao àry no tenin’i jehovah tompo fara tampony: “ny mpanompoko hihinana, fa ianareo kosa ho noana. ny mpanompoko hisotro, fa ianareo kosa hangetaheta. ny mpanompoko hifaly, fa ianareo kosa ho afa-baraka.'),
  ('6ab25b8d13be424f14e2d600', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 25, 'Hiara-miraoka ahitra ny amboadia sy ny zanak’ondry. Dia hihinana mololo hoatran’ny omby ny liona, Ary vovoka no ho sakafon’ny bibilava. Dia tsy handratra an’iza na iza, na hanimba na inona na inona eran’ny tendrombohitro masina ireny”, hoy i Jehovah.', 'hiara-miraoka ahitra ny amboadia sy ny zanak’ondry. dia hihinana mololo hoatran’ny omby ny liona, ary vovoka no ho sakafon’ny bibilava. dia tsy handratra an’iza na iza, na hanimba na inona na inona eran’ny tendrombohitro masina ireny”, hoy i jehovah.'),
  ('6ab25b8d13be424f14e2d5f7', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 16, 'Izay mangataka fitahiana ho an’ny tenany eny ambonin’ny tany àry, Dia hotahin’ilay Andriamanitry ny fahamarinana. Ary izay mianiana eny ambonin’ny tany, Dia hianiana amin’ny anaran’ilay Andriamanitry ny fahamarinana. Hohadinoina mantsy ny fahoriana taloha, Ka hafenina tsy ho hitan’ny masoko.', 'izay mangataka fitahiana ho an’ny tenany eny ambonin’ny tany àry, dia hotahin’ilay andriamanitry ny fahamarinana. ary izay mianiana eny ambonin’ny tany, dia hianiana amin’ny anaran’ilay andriamanitry ny fahamarinana. hohadinoina mantsy ny fahoriana taloha, ka hafenina tsy ho hitan’ny masoko.'),
  ('6ab25b8d13be424f14e2d5ff', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 24, 'Na mbola tsy miantso aza izy ireo, dia efa hamaly aho, Ary raha mbola tsy tapitra ny teniny, dia efa henoko daholo.', 'na mbola tsy miantso aza izy ireo, dia efa hamaly aho, ary raha mbola tsy tapitra ny teniny, dia efa henoko daholo.'),
  ('6ab25b8d13be424f14e2d5f0', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 9, 'Hamoaka taranaka avy amin’i Jakoba aho, Ary hamoaka olona iray avy amin’i Joda mba handova ny tendrombohitro. Ho lasan’ny olom-boafidiko ilay tany, Dia hipetraka ao ny mpanompoko.', 'hamoaka taranaka avy amin’i jakoba aho, ary hamoaka olona iray avy amin’i joda mba handova ny tendrombohitro. ho lasan’ny olom-boafidiko ilay tany, dia hipetraka ao ny mpanompoko.'),
  ('6ab25b8d13be424f14e2d5ef', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 8, 'Izao no tenin’i Jehovah: “Hoatran’ny rehefa misy voaloboka iray tangozany azo anaovana divay vaovao, Ka misy miteny hoe: ‘Aza simbana io fa misy zavatra tsara ihany’, Dia hoatr’izany koa no hataoko amin’ny mpanompoko. Tsy haringako izy rehetra.', 'izao no tenin’i jehovah: “hoatran’ny rehefa misy voaloboka iray tangozany azo anaovana divay vaovao, ka misy miteny hoe: ‘aza simbana io fa misy zavatra tsara ihany’, dia hoatr’izany koa no hataoko amin’ny mpanompoko. tsy haringako izy rehetra.'),
  ('6ab25b8d13be424f14e2d5e8', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 1, '“Navelako hahafantatra ahy izay tsy nanontany momba ahy, Ary navelako hahita ahy izay tsy nitady ahy. Hoy aho amin’ny firenena izay tsy niantso ny anarako: ‘Intỳ aho! Intỳ aho!’', '“navelako hahafantatra ahy izay tsy nanontany momba ahy, ary navelako hahita ahy izay tsy nitady ahy. hoy aho amin’ny firenena izay tsy niantso ny anarako: ‘intỳ aho! intỳ aho!’'),
  ('6ab25b8d13be424f14e2d5fe', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 23, 'Tsy ho very maina fotsiny ny asa mafy ataony, Ary rehefa miteraka izy dia tsy hisy loza hanjo ny zanany. Fa vahoaka tahin’i Jehovah izy ireo, Ary hoatr’izany koa ny taranany.', 'tsy ho very maina fotsiny ny asa mafy ataony, ary rehefa miteraka izy dia tsy hisy loza hanjo ny zanany. fa vahoaka tahin’i jehovah izy ireo, ary hoatr’izany koa ny taranany.'),
  ('6ab25b8d13be424f14e2d5fd', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 22, 'Tsy hanao trano hipetrahan’olon-kafa izy, Na hamboly zavatra hohanin’olon-kafa. Fa hitovy amin’ny halavan’ny androm-piainan’ny hazo ny androm-piainan’ny vahoakako, Ary hanaram-po amin’ny asan’ny tanany ny olom-boafidiko.', 'tsy hanao trano hipetrahan’olon-kafa izy, na hamboly zavatra hohanin’olon-kafa. fa hitovy amin’ny halavan’ny androm-piainan’ny hazo ny androm-piainan’ny vahoakako, ary hanaram-po amin’ny asan’ny tanany ny olom-boafidiko.'),
  ('6ab25b8d13be424f14e2d5f9', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 18, 'Miravoravoa sy mifalia mandrakizay àry noho ny amin’izay hoforoniko. Fa hoforoniko mba hahafaly ny olona i Jerosalema, Ary hoforoniko mba haharavoravo ny olona ny vahoakany.', 'miravoravoa sy mifalia mandrakizay àry noho ny amin’izay hoforoniko. fa hoforoniko mba hahafaly ny olona i jerosalema, ary hoforoniko mba haharavoravo ny olona ny vahoakany.'),
  ('6ab25b8d13be424f14e2d5f8', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 17, 'Fa hamorona lanitra vaovao sy tany vaovao aho. Dia tsy hotsaroana intsony ny zavatra taloha, Sady tsy handreraka fo.', 'fa hamorona lanitra vaovao sy tany vaovao aho. dia tsy hotsaroana intsony ny zavatra taloha, sady tsy handreraka fo.'),
  ('6ab25b8d13be424f14e2d5fc', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 21, 'Hanao trano ny olona ka hipetraka ao, Ary hamboly voaloboka ka hihinana ny vokatra amin’izany.', 'hanao trano ny olona ka hipetraka ao, ary hamboly voaloboka ka hihinana ny vokatra amin’izany.'),
  ('6ab25b8d13be424f14e2d5ec', '2026-09-22T10:42:21.045Z', '2026-09-22T10:42:21.045Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Isaia', 23, 65, 5, 'Hoy izy ireo: ‘Mijanòna eny, fa aza manatona ahy! Fa masina noho ianao aho.’ Setroka eo am-bavoroko anefa ireny, sady afo mirehitra tontolo andro.', 'hoy izy ireo: ‘mijanòna eny, fa aza manatona ahy! fa masina noho ianao aho.’ setroka eo am-bavoroko anefa ireny, sady afo mirehitra tontolo andro.'),
  ('6ab25b8e9636ae61915774ca', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 13, 'Niteny tamiko fanindroany i Jehovah hoe: “Inona no hitanao?” Dia hoy aho: “Mahita vilany mangotraka aho. Mitodika mianavaratra ny vodin’ilay vilany, ka mitongilana mianatsimo ny vavany.”', 'niteny tamiko fanindroany i jehovah hoe: “inona no hitanao?” dia hoy aho: “mahita vilany mangotraka aho. mitodika mianavaratra ny vodin’ilay vilany, ka mitongilana mianatsimo ny vavany.”'),
  ('6ab25b8e9636ae61915774c5', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 8, 'Aza matahotra azy, Fa ‘ho eo foana aho mba hamonjy anao’, hoy i Jehovah.”', 'aza matahotra azy, fa ‘ho eo foana aho mba hamonjy anao’, hoy i jehovah.”'),
  ('6ab25b8e9636ae61915774ce', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 17, '“Fa ianao kosa miomàna hanao zavatra, Ary mitsangàna ka teneno amin’izy ireo izay rehetra asaiko lazainao. Aza matahotra be azy ireo, Sao ianao indray no hataoko matahotra be eo anatrehany.', '“fa ianao kosa miomàna hanao zavatra, ary mitsangàna ka teneno amin’izy ireo izay rehetra asaiko lazainao. aza matahotra be azy ireo, sao ianao indray no hataoko matahotra be eo anatrehany.'),
  ('6ab25b8e9636ae61915774cb', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 14, 'Dia hoy i Jehovah tamiko: “Avy any avaratra no hiavian’ny loza Hamely ny mponina rehetra ao amin’ilay tany.', 'dia hoy i jehovah tamiko: “avy any avaratra no hiavian’ny loza hamely ny mponina rehetra ao amin’ilay tany.'),
  ('6ab25b8e9636ae61915774c0', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 3, 'Nampitaina taminy koa izany tamin’ny andron’i Joiakima zanak’i Josia, mpanjakan’ny Joda, mandra-pahatapitry ny taona faha-11 nanjakan’i Zedekia zanak’i Josia, mpanjakan’ny Joda, mandra-panao sesitany ny mponin’i Jerosalema tamin’ny volana fahadimy.', 'nampitaina taminy koa izany tamin’ny andron’i joiakima zanak’i josia, mpanjakan’ny joda, mandra-pahatapitry ny taona faha-11 nanjakan’i zedekia zanak’i josia, mpanjakan’ny joda, mandra-panao sesitany ny mponin’i jerosalema tamin’ny volana fahadimy.'),
  ('6ab25b8e9636ae61915774d0', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 19, 'Tsy maintsy hiady aminao izy ireo, Nefa tsy haharesy anao, Satria ‘ho eo foana aho mba hamonjy anao’, hoy i Jehovah.”', 'tsy maintsy hiady aminao izy ireo, nefa tsy haharesy anao, satria ‘ho eo foana aho mba hamonjy anao’, hoy i jehovah.”'),
  ('6ab25b8e9636ae61915774c4', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 7, 'Fa hoy i Jehovah tamiko: “Aza miteny hoe: ‘Mbola zaza aho.’ Fa tsy maintsy mandeha any amin’izay rehetra anirahako anao ianao, Ary hiteny an’izay rehetra asaiko lazainao.', 'fa hoy i jehovah tamiko: “aza miteny hoe: ‘mbola zaza aho.’ fa tsy maintsy mandeha any amin’izay rehetra anirahako anao ianao, ary hiteny an’izay rehetra asaiko lazainao.'),
  ('6ab25b8e9636ae61915774be', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 1, 'Voasoratra ato ny tenin’i Jeremia zanak’i Hilkia, anisan’ny mpisorona tao Anatota, tany amin’ny tanin’i Benjamina.', 'voasoratra ato ny tenin’i jeremia zanak’i hilkia, anisan’ny mpisorona tao anatota, tany amin’ny tanin’i benjamina.'),
  ('6ab25b8e9636ae61915774c9', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 12, 'Ary hoy i Jehovah tamiko: “Marina izany! Mifoha tsara mihitsy aho mba hanatanteraka ny teniko.”', 'ary hoy i jehovah tamiko: “marina izany! mifoha tsara mihitsy aho mba hanatanteraka ny teniko.”'),
  ('6ab25b8e9636ae61915774c3', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 6, 'Hoy anefa aho: “Indrisy, ry Jehovah Tompo Fara Tampony ô! Tsy mahay mandaha-teny aho fa mbola zaza.”', 'hoy anefa aho: “indrisy, ry jehovah tompo fara tampony ô! tsy mahay mandaha-teny aho fa mbola zaza.”'),
  ('6ab25b8e9636ae61915774cc', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 15, 'Fa ‘hiantso ny foko rehetra ao amin’ireo fanjakana any avaratra aho’, hoy i Jehovah. ‘Dia ho avy izy ireo, ka samy hametraka ny seza fiandrianany Eo amin’ny fidirana amin’ny vavahadin’i Jerosalema. Hamely ny mandany rehetra manodidina Sy ny tanàna rehetra any Joda izy ireo.', 'fa ‘hiantso ny foko rehetra ao amin’ireo fanjakana any avaratra aho’, hoy i jehovah. ‘dia ho avy izy ireo, ka samy hametraka ny seza fiandrianany eo amin’ny fidirana amin’ny vavahadin’i jerosalema. hamely ny mandany rehetra manodidina sy ny tanàna rehetra any joda izy ireo.'),
  ('6ab25b8e9636ae61915774c7', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 10, 'Ary omeko fahefana amin’ireo firenena sy fanjakana ianao androany, mba hanongotra sy handrodana, handringana sy handrava, ary hanorina sy hamboly.”', 'ary omeko fahefana amin’ireo firenena sy fanjakana ianao androany, mba hanongotra sy handrodana, handringana sy handrava, ary hanorina sy hamboly.”'),
  ('6ab25b8e9636ae61915774c1', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 4, 'Niteny tamiko i Jehovah hoe:', 'niteny tamiko i jehovah hoe:'),
  ('6ab25b8e9636ae61915774cd', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 16, 'Hamoaka didy hanamelohana ny vahoakako aho noho ny ratsy rehetra ataony. Niala tamiko mantsy izy ireo, Ary mandoro fanatitra mba hidona-tsetroka ho an’ny andriamani-kafa. Miankohoka amin’ny asan’ny tanany koa izy ireo.’', 'hamoaka didy hanamelohana ny vahoakako aho noho ny ratsy rehetra ataony. niala tamiko mantsy izy ireo, ary mandoro fanatitra mba hidona-tsetroka ho an’ny andriamani-kafa. miankohoka amin’ny asan’ny tanany koa izy ireo.’'),
  ('6ab25b8e9636ae61915774cf', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 18, 'Fa ataoko toy ny tanàna voaro mafy ianao androany, Ary ataoko toy ny andry vy sy manda varahina mba ho vitanao ny hiatrika an’ilay tany manontolo, Dia ireo mpanjakan’ny Joda, sy ny andrianany, Sy ny mpisorony, ary ny vahoakany.', 'fa ataoko toy ny tanàna voaro mafy ianao androany, ary ataoko toy ny andry vy sy manda varahina mba ho vitanao ny hiatrika an’ilay tany manontolo, dia ireo mpanjakan’ny joda, sy ny andrianany, sy ny mpisorony, ary ny vahoakany.'),
  ('6ab25b8e9636ae61915774c8', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 11, 'Niteny tamiko indray i Jehovah hoe: “Inona no hitanao, ry Jeremia?” Dia hoy aho: “Mahita sampana hazo amandie aho.”', 'niteny tamiko indray i jehovah hoe: “inona no hitanao, ry jeremia?” dia hoy aho: “mahita sampana hazo amandie aho.”'),
  ('6ab25b8e9636ae61915774c2', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 5, '“Efa fantatro ianao talohan’ny namoronako anao tao an-kibo, Ary efa nohamasiniko ianao talohan’ny nahaterahanao. Notendreko ho mpaminany ho an’ireo firenena ianao.”', '“efa fantatro ianao talohan’ny namoronako anao tao an-kibo, ary efa nohamasiniko ianao talohan’ny nahaterahanao. notendreko ho mpaminany ho an’ireo firenena ianao.”'),
  ('6ab25b8e9636ae61915774bf', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 2, 'Nampita ny teniny tamin’i Jeremia i Jehovah tamin’ny andron’i Josia zanak’i Amona, mpanjakan’ny Joda, tamin’ny taona faha-13 nanjakany.', 'nampita ny teniny tamin’i jeremia i jehovah tamin’ny andron’i josia zanak’i amona, mpanjakan’ny joda, tamin’ny taona faha-13 nanjakany.'),
  ('6ab25b8e9636ae61915774c6', '2026-09-22T10:42:22.316Z', '2026-09-22T10:42:22.316Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 1, 9, 'Natsotran’i Jehovah ny tanany avy eo, dia nokasihiny ny vavako. Ary hoy i Jehovah: “Efa nataoko ao am-bavanao ny teniko.', 'natsotran’i jehovah ny tanany avy eo, dia nokasihiny ny vavako. ary hoy i jehovah: “efa nataoko ao am-bavanao ny teniko.'),
  ('6ab25b90f5875dabdb7b3900', '2026-09-22T10:42:24.924Z', '2026-09-22T10:42:24.924Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 6, 'Noho izany, dia manafika azy ireo ny liona any an’ala, Mandringana azy ireo ny amboadia any amin’ny lemaka karakaina, Ary mamitsaka eny an-tanànany ny leopara. Rotidrotehina izay rehetra mivoaka avy ao. Be dia be mantsy ny lalàna nodikain’izy ireo Ary imbetsaka izy ireo no nivadika.', 'noho izany, dia manafika azy ireo ny liona any an’ala, mandringana azy ireo ny amboadia any amin’ny lemaka karakaina, ary mamitsaka eny an-tanànany ny leopara. rotidrotehina izay rehetra mivoaka avy ao. be dia be mantsy ny lalàna nodikain’izy ireo ary imbetsaka izy ireo no nivadika.'),
  ('6ab25b90f5875dabdb7b38fe', '2026-09-22T10:42:24.924Z', '2026-09-22T10:42:24.924Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 4, 'Nieritreritra anefa aho hoe: “Tena olona ambany ireto! Manao hadalana izy ireo, satria tsy fantany ny lalan’i Jehovah Sy izay takin’ny Andriamaniny.', 'nieritreritra anefa aho hoe: “tena olona ambany ireto! manao hadalana izy ireo, satria tsy fantany ny lalan’i jehovah sy izay takin’ny andriamaniny.'),
  ('6ab25b90f5875dabdb7b38fd', '2026-09-22T10:42:24.924Z', '2026-09-22T10:42:24.924Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 3, 'Jehovah ô, tsy ny olona tsy mivadika ve no tadiavinao? Nokapohinao ny vahoakanao, nefa tsy nihontsina. Saika tapitra naripakao izy ireo, nefa tsy nety nandray anatra. Nataon’izy ireo mafy noho ny vatolampy ny lohany, Ary tsy nety niverina taminao izy ireo.', 'jehovah ô, tsy ny olona tsy mivadika ve no tadiavinao? nokapohinao ny vahoakanao, nefa tsy nihontsina. saika tapitra naripakao izy ireo, nefa tsy nety nandray anatra. nataon’izy ireo mafy noho ny vatolampy ny lohany, ary tsy nety niverina taminao izy ireo.'),
  ('6ab25b90f5875dabdb7b38ff', '2026-09-22T10:42:24.924Z', '2026-09-22T10:42:24.924Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 5, 'Handeha hiresaka amin’ireo olona ambony aho, Fa izy ireo izao no mahalala ny lalan’i Jehovah Sy izay takin’ny Andriamaniny. Efa nanapatapaka ny zioga koa anefa izy rehetra, Ary efa nanapaka an’izay namatotra azy.”', 'handeha hiresaka amin’ireo olona ambony aho, fa izy ireo izao no mahalala ny lalan’i jehovah sy izay takin’ny andriamaniny. efa nanapatapaka ny zioga koa anefa izy rehetra, ary efa nanapaka an’izay namatotra azy.”'),
  ('6ab25b90f5875dabdb7b38fb', '2026-09-22T10:42:24.924Z', '2026-09-22T10:42:24.924Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 1, 'Mandehana mivezivezy eny amin’ireo lalana ao Jerosalema. Dia jereo tsara daholo ny toerana rehetra sady diniho. Mankanesa eny amin’ny tany malalaka be olona dia tadiavo Raha mahita olona iray manao ny rariny Sy miezaka ny tsy hivadika ianareo. Raha izany mantsy, dia havelako ny helok’ilay tanàna.', 'mandehana mivezivezy eny amin’ireo lalana ao jerosalema. dia jereo tsara daholo ny toerana rehetra sady diniho. mankanesa eny amin’ny tany malalaka be olona dia tadiavo raha mahita olona iray manao ny rariny sy miezaka ny tsy hivadika ianareo. raha izany mantsy, dia havelako ny helok’ilay tanàna.'),
  ('6ab25b90f5875dabdb7b38fc', '2026-09-22T10:42:24.924Z', '2026-09-22T10:42:24.924Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 2, 'Na misy mianiana aza hoe: “Raha mbola velona koa i Jehovah!”, Dia mbola lainga ihany ny fianianana ataon’izy ireny.', 'na misy mianiana aza hoe: “raha mbola velona koa i jehovah!”, dia mbola lainga ihany ny fianianana ataon’izy ireny.'),
  ('6ab25b90f5875dabdb7b3902', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 8, 'Hoatran’ny soavaly maimay mitady vavy izy ireo, Ka samy mitady vehivavy efa vadin’olona.', 'hoatran’ny soavaly maimay mitady vavy izy ireo, ka samy mitady vehivavy efa vadin’olona.'),
  ('6ab25b90f5875dabdb7b3916', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 28, 'Nihanatavy sy mandimandina izy ireo. Tafahoatra loatra ny ratsy vitany. Tsy mba miady ho an’ny kamboty izy ireo eny amin’ny fitsarana, Satria te hahazo tombony. Ary tsy omeny rariny ny mahantra.’”', 'nihanatavy sy mandimandina izy ireo. tafahoatra loatra ny ratsy vitany. tsy mba miady ho an’ny kamboty izy ireo eny amin’ny fitsarana, satria te hahazo tombony. ary tsy omeny rariny ny mahantra.’”'),
  ('6ab25b90f5875dabdb7b3910', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 22, '‘Tsy mba matahotra ahy ve ianareo’, hoy i Jehovah. ‘Tsy tokony hangovitra eo anatrehako ve ianareo? Izaho ange no nanao ny fasika ho fetran’ny ranomasina e, Mba ho lalàna mandrakizay tsy azony dikaina! Na misamboaravoara aza ny onjany, dia tsy hivoaka ho mpandresy. Ary na midoboka mafy aza ireny, dia mbola tsy ho afaka ny hihoatra an’ilay fetra ihany.', '‘tsy mba matahotra ahy ve ianareo’, hoy i jehovah. ‘tsy tokony hangovitra eo anatrehako ve ianareo? izaho ange no nanao ny fasika ho fetran’ny ranomasina e, mba ho lalàna mandrakizay tsy azony dikaina! na misamboaravoara aza ny onjany, dia tsy hivoaka ho mpandresy. ary na midoboka mafy aza ireny, dia mbola tsy ho afaka ny hihoatra an’ilay fetra ihany.'),
  ('6ab25b90f5875dabdb7b3911', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 23, 'Mafy loha sy mpikomy anefa ity vahoaka ity. Nivily lalana izy ireo ary nandeha tamin’izay lalana tiany.', 'mafy loha sy mpikomy anefa ity vahoaka ity. nivily lalana izy ireo ary nandeha tamin’izay lalana tiany.'),
  ('6ab25b90f5875dabdb7b3909', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 15, '“Koa hisy firenena avy any lavitra hoentiko hamely anareo, ry taranak’Israely”, hoy i Jehovah. “Firenena efa nisy hatry ny ela izany, Firenena efa taloha be. Tsy hainao ny fiteniny Ary tsy azonao izay lazainy.', '“koa hisy firenena avy any lavitra hoentiko hamely anareo, ry taranak’israely”, hoy i jehovah. “firenena efa nisy hatry ny ela izany, firenena efa taloha be. tsy hainao ny fiteniny ary tsy azonao izay lazainy.'),
  ('6ab25b90f5875dabdb7b3903', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 9, '“Koa tsy tokony hataoko ampamoaka ve izy ireo noho izany?”, hoy i Jehovah. “Ary tsy tokony hamaly ny nataon’ny firenena toy izany ve aho?”', '“koa tsy tokony hataoko ampamoaka ve izy ireo noho izany?”, hoy i jehovah. “ary tsy tokony hamaly ny nataon’ny firenena toy izany ve aho?”'),
  ('6ab25b90f5875dabdb7b3918', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 30, 'Zavatra mampihoron-koditra sy mahatsiravina no mitranga ao amin’ilay tany:', 'zavatra mampihoron-koditra sy mahatsiravina no mitranga ao amin’ilay tany:'),
  ('6ab25b90f5875dabdb7b3906', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 12, '“Nanda an’i Jehovah izy ireo, ary izao foana no lazainy: ‘Tsy hanao na inona na inona Izy. Tsy hisy loza hanjo anay. Tsy hahita ady izahay na ho tratran’ny mosary.’', '“nanda an’i jehovah izy ireo, ary izao foana no lazainy: ‘tsy hanao na inona na inona izy. tsy hisy loza hanjo anay. tsy hahita ady izahay na ho tratran’ny mosary.’'),
  ('6ab25b90f5875dabdb7b3917', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 29, '“Koa tsy tokony hataoko ampamoaka ve izy ireo noho izany?”, hoy i Jehovah. “Ary tsy tokony hamaly ny nataon’ny firenena toy izany ve aho?', '“koa tsy tokony hataoko ampamoaka ve izy ireo noho izany?”, hoy i jehovah. “ary tsy tokony hamaly ny nataon’ny firenena toy izany ve aho?'),
  ('6ab25b90f5875dabdb7b3913', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 25, 'Ny fahadisoanareo ihany no nahatonga anareo tsy hahazo an’izany rehetra izany, Ary ny fahotanareo ihany no tsy nahazoanareo zavatra tsara.', 'ny fahadisoanareo ihany no nahatonga anareo tsy hahazo an’izany rehetra izany, ary ny fahotanareo ihany no tsy nahazoanareo zavatra tsara.'),
  ('6ab25b90f5875dabdb7b390e', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 20, 'Lazao amin’ny taranak’i Jakoba Ary ambarao ao Joda hoe:', 'lazao amin’ny taranak’i jakoba ary ambarao ao joda hoe:'),
  ('6ab25b90f5875dabdb7b390d', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 19, 'Rehefa manontany izy ireo hoe: ‘Fa maninona i Jehovah Andriamanitsika no nanao an’izany rehetra izany tamintsika?’ Dia izao no havalinao azy: ‘Niala tamiko ianareo ary nanompo andriamani-kafa tao amin’ny taninareo. Koa hanompo firenena hafa any an-tanin’olona ianareo.’”', 'rehefa manontany izy ireo hoe: ‘fa maninona i jehovah andriamanitsika no nanao an’izany rehetra izany tamintsika?’ dia izao no havalinao azy: ‘niala tamiko ianareo ary nanompo andriamani-kafa tao amin’ny taninareo. koa hanompo firenena hafa any an-tanin’olona ianareo.’”'),
  ('6ab25b90f5875dabdb7b390b', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 17, 'Haripany ny vokatrao sy ny mofonao. Haripany ny zanakao lahy sy ny zanakao vavy. Haripany ny omby aman’ondrinao. Haripany ny voalobokao sy ny aviavinao. Dia horavany amin’ny sabatra ny tanàna voaro mafy itokisanao.”', 'haripany ny vokatrao sy ny mofonao. haripany ny zanakao lahy sy ny zanakao vavy. haripany ny omby aman’ondrinao. haripany ny voalobokao sy ny aviavinao. dia horavany amin’ny sabatra ny tanàna voaro mafy itokisanao.”'),
  ('6ab25b90f5875dabdb7b3908', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 14, 'Izao àry no lazain’i Jehovah Andriamanitry ny tafika: “Satria niteny an’izany izy ireo, Dia hataoko toy ny afo ao am-bavanao ny teniko, Ary ity vahoaka ity kosa ho toy ny kitay, Ka holevonin’ilay afo.”', 'izao àry no lazain’i jehovah andriamanitry ny tafika: “satria niteny an’izany izy ireo, dia hataoko toy ny afo ao am-bavanao ny teniko, ary ity vahoaka ity kosa ho toy ny kitay, ka holevonin’ilay afo.”'),
  ('6ab25b90f5875dabdb7b3907', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 13, 'Zava-poana toy ny rivotra no lazain’ny mpaminany, Ary tsy ao aminy ny teniko. Ho zava-poana hoatran’ny teniny ihany izy ireo!”', 'zava-poana toy ny rivotra no lazain’ny mpaminany, ary tsy ao aminy ny teniko. ho zava-poana hoatran’ny teniny ihany izy ireo!”'),
  ('6ab25b90f5875dabdb7b3905', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 11, 'Tena namadika ahy mantsy Ny taranak’Israely sy ny taranak’i Joda”, hoy i Jehovah.', 'tena namadika ahy mantsy ny taranak’israely sy ny taranak’i joda”, hoy i jehovah.'),
  ('6ab25b90f5875dabdb7b3901', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 7, 'Koa ahoana moa no hamelako an’izany helokao izany? Niala tamiko ireo zanakao, Ka mianiana amin’ny anaran’izay tsy Andriamanitra. Nomeko azy daholo izay nilainy, Nefa mbola manitsakitsa-bady ihany izy ireo, Sady mirohotra mankao an-tranon’ny mpivaro-tena.', 'koa ahoana moa no hamelako an’izany helokao izany? niala tamiko ireo zanakao, ka mianiana amin’ny anaran’izay tsy andriamanitra. nomeko azy daholo izay nilainy, nefa mbola manitsakitsa-bady ihany izy ireo, sady mirohotra mankao an-tranon’ny mpivaro-tena.'),
  ('6ab25b90f5875dabdb7b3915', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 27, 'Toy ny tranom-borona feno vorona, Dia feno fitaka koa ny tranony. Izany no mahatonga azy ireo hanana fahefana sy harena.', 'toy ny tranom-borona feno vorona, dia feno fitaka koa ny tranony. izany no mahatonga azy ireo hanana fahefana sy harena.'),
  ('6ab25b90f5875dabdb7b390f', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 21, '“Henoy izao, ry vahoaka adala sy tsisy saina: Mana-maso izy ireo nefa tsy mahita, Ary manan-tsofina nefa tsy maheno.', '“henoy izao, ry vahoaka adala sy tsisy saina: mana-maso izy ireo nefa tsy mahita, ary manan-tsofina nefa tsy maheno.'),
  ('6ab25b90f5875dabdb7b3919', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 31, 'Maminany lainga ny mpaminany, Ary manampatra fahefana ny mpisorona. Dia tian’ny vahoakako erỳ izany! Koa ahoana no hataonareo rehefa tonga ny farany?”', 'maminany lainga ny mpaminany, ary manampatra fahefana ny mpisorona. dia tian’ny vahoakako erỳ izany! koa ahoana no hataonareo rehefa tonga ny farany?”'),
  ('6ab25b90f5875dabdb7b3912', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 24, 'Tsy mba miteny anakampo izy ireo hoe: “Andao amin’izay isika hatahotra an’i Jehovah Andriamanitsika, Ilay manome antsika orana amin’ny fotoanany, Dia ny oram-pararano sy ny oran-dohataona, Ilay manome antoka antsika fa ho tonga amin’ny fotoana voatondro ireo herinandro fijinjana.”', 'tsy mba miteny anakampo izy ireo hoe: “andao amin’izay isika hatahotra an’i jehovah andriamanitsika, ilay manome antsika orana amin’ny fotoanany, dia ny oram-pararano sy ny oran-dohataona, ilay manome antoka antsika fa ho tonga amin’ny fotoana voatondro ireo herinandro fijinjana.”'),
  ('6ab25b90f5875dabdb7b3904', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 10, '“Miakara ka simbao ireo tanimboalobony mikitohatohatra, Nefa aza potehina tanteraka. Esory ny sampany vao mitsiry, Satria tsy an’i Jehovah ireny.', '“miakara ka simbao ireo tanimboalobony mikitohatohatra, nefa aza potehina tanteraka. esory ny sampany vao mitsiry, satria tsy an’i jehovah ireny.'),
  ('6ab25b90f5875dabdb7b390c', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 18, '“Tsy horinganiko tanteraka anefa ianareo”, hoy i Jehovah, “na dia amin’izany andro izany aza.', '“tsy horinganiko tanteraka anefa ianareo”, hoy i jehovah, “na dia amin’izany andro izany aza.'),
  ('6ab25b90f5875dabdb7b390a', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 16, 'Toy ny fasana misokatra ny tranon-jana-tsipìkany; Miaramila izy rehetra.', 'toy ny fasana misokatra ny tranon-jana-tsipìkany; miaramila izy rehetra.'),
  ('6ab25b90f5875dabdb7b3914', '2026-09-22T10:42:24.925Z', '2026-09-22T10:42:24.925Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 5, 26, 'Fa misy ratsy fanahy amin’ny vahoakako. Mitilitily tsy misy farany hoatran’ny mpamandri-borona mamitsaka ao amin’ny miafina izy ireo. Mamelatra fandrika mahafaty izy ireo, Ary olona no azony.', 'fa misy ratsy fanahy amin’ny vahoakako. mitilitily tsy misy farany hoatran’ny mpamandri-borona mamitsaka ao amin’ny miafina izy ireo. mamelatra fandrika mahafaty izy ireo, ary olona no azony.'),
  ('6ab25b92500c32ae14ecb401', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 29, 'May ny tafoforana. Misy firaka avy ao anaty afo. Very maina fotsiny ny nandrendrehana ny metaly na dia atao mahamay be foana aza ny afo, Satria tsy niavaka akory ny loto.', 'may ny tafoforana. misy firaka avy ao anaty afo. very maina fotsiny ny nandrendrehana ny metaly na dia atao mahamay be foana aza ny afo, satria tsy niavaka akory ny loto.'),
  ('6ab25b92500c32ae14ecb3fe', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 26, 'Ry zanakavavin’ny fireneko! Mitafia lamba gony ary aoka ianao hihosin-davenona. Aoka ianao hisaona toy ny misaona zanaka lahitokana ka hidradradradra mafy, Satria hanafika antsika tampoka ny mpandrava.', 'ry zanakavavin’ny fireneko! mitafia lamba gony ary aoka ianao hihosin-davenona. aoka ianao hisaona toy ny misaona zanaka lahitokana ka hidradradradra mafy, satria hanafika antsika tampoka ny mpandrava.'),
  ('6ab25b92500c32ae14ecb3fc', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 24, 'Efa renay ny momba azy, Ka miraviravy tanana izahay. Mijaly izahay, Ary mitebiteby be hoatran’ny vehivavy efa ho teraka.', 'efa renay ny momba azy, ka miraviravy tanana izahay. mijaly izahay, ary mitebiteby be hoatran’ny vehivavy efa ho teraka.'),
  ('6ab25b92500c32ae14ecb3f7', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 19, 'Henoy, ry tany ô! Hahatonga loza amin’ity vahoaka ity aho, Ho valin’ny teti-dratsy nataony. Tsy nihaino ny teniko mantsy izy ireo, Sady tsy niraharaha ny lalàko.”', 'henoy, ry tany ô! hahatonga loza amin’ity vahoaka ity aho, ho valin’ny teti-dratsy nataony. tsy nihaino ny teniko mantsy izy ireo, sady tsy niraharaha ny lalàko.”'),
  ('6ab25b92500c32ae14ecb3f1', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 13, '“Samy maka tombony azo amin’ny tsy marina ny olona, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra. Ary samy mamitaka na ny mpaminany na ny mpisorona.', '“samy maka tombony azo amin’ny tsy marina ny olona, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra. ary samy mamitaka na ny mpaminany na ny mpisorona.'),
  ('6ab25b92500c32ae14ecb400', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 28, 'Olona faran’izay mafy loha izy rehetra, Ary mandehandeha manendrikendrika. Toy ny varahina sy vy izy ireo, Sady mpanao ratsy daholo.', 'olona faran’izay mafy loha izy rehetra, ary mandehandeha manendrikendrika. toy ny varahina sy vy izy ireo, sady mpanao ratsy daholo.'),
  ('6ab25b92500c32ae14ecb3f2', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 14, 'Miezaka manasitrana ny ratran’ny vahoakako izy ireo nefa ataony zara fa vita izany, ka hoy izy ireo: ‘Fiadanana! Fiadanana!’ Nefa tsy misy fiadanana akory.', 'miezaka manasitrana ny ratran’ny vahoakako izy ireo nefa ataony zara fa vita izany, ka hoy izy ireo: ‘fiadanana! fiadanana!’ nefa tsy misy fiadanana akory.'),
  ('6ab25b92500c32ae14ecb3f0', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 12, 'Ho lasan’olon-kafa ny tranon’izy ireo Sy ny sahany ary ny vadiny. Fa hanatsotra ny tanako hamely ny mponin’ilay tany aho”, hoy i Jehovah.', 'ho lasan’olon-kafa ny tranon’izy ireo sy ny sahany ary ny vadiny. fa hanatsotra ny tanako hamely ny mponin’ilay tany aho”, hoy i jehovah.'),
  ('6ab25b92500c32ae14ecb3e8', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 4, '“Miomàna hiady amin’i Jerosalema! Mitsangàna, andao izy hotafihina amin’ny mitataovovonana!” “Idiran-doza isika fa efa mihariva ny andro, Efa mihalava ny aloka satria efa hariva!”', '“miomàna hiady amin’i jerosalema! mitsangàna, andao izy hotafihina amin’ny mitataovovonana!” “idiran-doza isika fa efa mihariva ny andro, efa mihalava ny aloka satria efa hariva!”'),
  ('6ab25b92500c32ae14ecb3f5', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 17, '“Dia nanendry mpitily aho hilaza aminareo hoe: ‘Henoy ny feon’ny anjombona!’” Hoy anefa ianareo: “Tsy hihaino izahay.”', '“dia nanendry mpitily aho hilaza aminareo hoe: ‘henoy ny feon’ny anjombona!’” hoy anefa ianareo: “tsy hihaino izahay.”'),
  ('6ab25b92500c32ae14ecb3ef', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 11, 'Koa miredareda ato anatiko ny fahatezeran’i Jehovah, Ka reraka mitana an’izany aho.” “Anamparo ny hatezeranao ny ankizy eny an-dalana, Sy ny andiana tovolahy mitangorongorona. Samy ho lasa babo daholo na ny lehilahy na ny vadiny, Na ny lehilahy efa be taona na ny efa antitra be.', 'koa miredareda ato anatiko ny fahatezeran’i jehovah, ka reraka mitana an’izany aho.” “anamparo ny hatezeranao ny ankizy eny an-dalana, sy ny andiana tovolahy mitangorongorona. samy ho lasa babo daholo na ny lehilahy na ny vadiny, na ny lehilahy efa be taona na ny efa antitra be.'),
  ('6ab25b92500c32ae14ecb3eb', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 7, 'Toy ny itehirizan’ny lavaka fanangonan-drano ny rano ho mangatsiatsiaka, No itehirizany ny ratsy fanaony ho mangatsiatsiaka. Herisetra sy fandravana no heno ao aminy. Aretina sy loza foana no eo anatrehako.', 'toy ny itehirizan’ny lavaka fanangonan-drano ny rano ho mangatsiatsiaka, no itehirizany ny ratsy fanaony ho mangatsiatsiaka. herisetra sy fandravana no heno ao aminy. aretina sy loza foana no eo anatrehako.'),
  ('6ab25b92500c32ae14ecb3f3', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 15, 'Mba menatra ve izy ireo noho ny zavatra maharikoriko ataony? Tsy menatra mihitsy izy ireo. Tsy hainy akory na dia ny atao hoe henatra aza! Koa ho lavo miaraka amin’izay lavo izy ireo. Ho tafintohina izy ireo rehefa manasazy azy ireo aho”, hoy i Jehovah.', 'mba menatra ve izy ireo noho ny zavatra maharikoriko ataony? tsy menatra mihitsy izy ireo. tsy hainy akory na dia ny atao hoe henatra aza! koa ho lavo miaraka amin’izay lavo izy ireo. ho tafintohina izy ireo rehefa manasazy azy ireo aho”, hoy i jehovah.'),
  ('6ab25b92500c32ae14ecb402', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 30, 'Hantsoin’ny olona hoe volafotsy fanary izy ireo, Satria efa narian’i Jehovah.”', 'hantsoin’ny olona hoe volafotsy fanary izy ireo, satria efa narian’i jehovah.”'),
  ('6ab25b92500c32ae14ecb3fa', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 22, 'Izao no tenin’i Jehovah: “Hisy vahoaka ho tonga avy any amin’ilay tany any avaratra, Ary hisy firenena lehibe hofohazina avy any amin’ny faritra lavitra indrindra amin’ny tany.', 'izao no tenin’i jehovah: “hisy vahoaka ho tonga avy any amin’ilay tany any avaratra, ary hisy firenena lehibe hofohazina avy any amin’ny faritra lavitra indrindra amin’ny tany.'),
  ('6ab25b92500c32ae14ecb3f8', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 20, '“Ataoko inona koa izay emboka manitra hafaranao avy any Sheba Sy izay fantàkamanitra avy any an-tany lavitra? Tsy azo ekena ny fanatitra dorana manontolo atolotrareo, Ary tsy ankasitrahako ny sorona ataonareo.”', '“ataoko inona koa izay emboka manitra hafaranao avy any sheba sy izay fantàkamanitra avy any an-tany lavitra? tsy azo ekena ny fanatitra dorana manontolo atolotrareo, ary tsy ankasitrahako ny sorona ataonareo.”'),
  ('6ab25b92500c32ae14ecb3ee', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 10, '“Iza no hitenenako sy hampitandremako? Iza no hihaino ahy? Tsentsina ny sofin’izy ireo, ka tsy afaka mandre. Ataon’izy ireo tsinontsinona ny tenin’i Jehovah, Sady tsy mahafinaritra azy.', '“iza no hitenenako sy hampitandremako? iza no hihaino ahy? tsentsina ny sofin’izy ireo, ka tsy afaka mandre. ataon’izy ireo tsinontsinona ny tenin’i jehovah, sady tsy mahafinaritra azy.'),
  ('6ab25b92500c32ae14ecb3e9', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 5, '“Mitsangàna, andao izy hotafihina mandritra ny alina, Dia horavantsika ireo tilikambony voaro mafy.”', '“mitsangàna, andao izy hotafihina mandritra ny alina, dia horavantsika ireo tilikambony voaro mafy.”'),
  ('6ab25b92500c32ae14ecb3ed', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 9, 'Izao no tenin’i Jehovah Tompon’ny tafika: “Hotsimponina tsara toy ny voaloboka navelan’ny mpioty izay sisa amin’ny Israely. Avereno eo amin’ny voaloboka indray ny tananao, toy ny ataon’ny mpioty.”', 'izao no tenin’i jehovah tompon’ny tafika: “hotsimponina tsara toy ny voaloboka navelan’ny mpioty izay sisa amin’ny israely. avereno eo amin’ny voaloboka indray ny tananao, toy ny ataon’ny mpioty.”'),
  ('6ab25b92500c32ae14ecb3f9', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 21, 'Koa izao no tenin’i Jehovah: “Hasiako vato mahatafintohina eo anoloan’ity vahoaka ity, Ka ho tafintohina izy ireo, Dia ny ray sy ny zanany, Ary ny mpiara-monina sy ny namany. Ho faty daholo izy ireo.”', 'koa izao no tenin’i jehovah: “hasiako vato mahatafintohina eo anoloan’ity vahoaka ity, ka ho tafintohina izy ireo, dia ny ray sy ny zanany, ary ny mpiara-monina sy ny namany. ho faty daholo izy ireo.”'),
  ('6ab25b92500c32ae14ecb3e7', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 3, 'Ho avy ireo mpiandry ondry sy ny andian’ondriny. Hanangana ny tranolainy manodidina azy izy ireo, Ary samy hitondra ny ondriny hiraoka ahitra.', 'ho avy ireo mpiandry ondry sy ny andian’ondriny. hanangana ny tranolainy manodidina azy izy ireo, ary samy hitondra ny ondriny hiraoka ahitra.'),
  ('6ab25b92500c32ae14ecb3f4', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 16, 'Izao no tenin’i Jehovah: “Mitsangàna eny amin’ny sampanan-dalana ka mandiniha. Anontanio hoe aiza ireo lalana fahiny Ary aiza ny lalana tsara, ka izay no andehano Dia hiadana ianareo.” Hoy anefa ianareo: “Tsy handeha amin’izany izahay.”', 'izao no tenin’i jehovah: “mitsangàna eny amin’ny sampanan-dalana ka mandiniha. anontanio hoe aiza ireo lalana fahiny ary aiza ny lalana tsara, ka izay no andehano dia hiadana ianareo.” hoy anefa ianareo: “tsy handeha amin’izany izahay.”'),
  ('6ab25b92500c32ae14ecb3f6', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 18, '“Koa mihainoa, ry firenena ô! Ry vahoaka ô, fantaro Izay hanjo azy ireo!', '“koa mihainoa, ry firenena ô! ry vahoaka ô, fantaro izay hanjo azy ireo!'),
  ('6ab25b92500c32ae14ecb3ea', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 6, 'Fa izao no tenin’i Jehovah Tompon’ny tafika: “Mikapà hazo, dia manangàna dongon-tany hanaovana fahirano an’i Jerosalema. Tanàna tsy maintsy atao ampamoaka izy. Tsy misy afa-tsy fampahoriana ao aminy.', 'fa izao no tenin’i jehovah tompon’ny tafika: “mikapà hazo, dia manangàna dongon-tany hanaovana fahirano an’i jerosalema. tanàna tsy maintsy atao ampamoaka izy. tsy misy afa-tsy fampahoriana ao aminy.'),
  ('6ab25b92500c32ae14ecb3fd', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 25, 'Aza mivoaka ho any an-tsaha, Na mandeha eny an-dalana Fa manana sabatra ny fahavalo, Ka manjaka hatraiza hatraiza ny horohoro.', 'aza mivoaka ho any an-tsaha, na mandeha eny an-dalana fa manana sabatra ny fahavalo, ka manjaka hatraiza hatraiza ny horohoro.'),
  ('6ab25b92500c32ae14ecb3fb', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 23, 'Hitazona tsipìka sy lefom-pohy izy ireo. Masiaka be izy ireo ka tsy hiantra. Midoboka toy ny ranomasina ny feony, Ary mitaingin-tsoavaly izy ireo. Milahatra toy ny lehilahy mpiady izy mba hanafika anao, ry Ziona zanakavavy ô!”', 'hitazona tsipìka sy lefom-pohy izy ireo. masiaka be izy ireo ka tsy hiantra. midoboka toy ny ranomasina ny feony, ary mitaingin-tsoavaly izy ireo. milahatra toy ny lehilahy mpiady izy mba hanafika anao, ry ziona zanakavavy ô!”'),
  ('6ab25b92500c32ae14ecb3ec', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 8, 'Mba maneke hahitsy, ry Jerosalema ô, raha tsy izany dia ho tofoka aminao aho ka hiala aminao. Hataoko lasa tany tsy misy mponina ianao.”', 'mba maneke hahitsy, ry jerosalema ô, raha tsy izany dia ho tofoka aminao aho ka hiala aminao. hataoko lasa tany tsy misy mponina ianao.”'),
  ('6ab25b92500c32ae14ecb3e5', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 1, 'Ry taranak’i Benjamina ô, mitadiava fialofana lavitra an’i Jerosalema. Tsofy ao Tekoa ny anjombona. Mandreheta afo famantarana ao Beti-hakerema! Fa efa mananontanona avy any avaratra ny loza, dia fandravana be.', 'ry taranak’i benjamina ô, mitadiava fialofana lavitra an’i jerosalema. tsofy ao tekoa ny anjombona. mandreheta afo famantarana ao beti-hakerema! fa efa mananontanona avy any avaratra ny loza, dia fandravana be.'),
  ('6ab25b92500c32ae14ecb3ff', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 27, '“Notendreko ho mpisedra metaly eo amin’ny vahoakako ianao, Ka hanadihady tsara. Handinika sy hamotopototra an’izay ataon’izy ireo ianao.', '“notendreko ho mpisedra metaly eo amin’ny vahoakako ianao, ka hanadihady tsara. handinika sy hamotopototra an’izay ataon’izy ireo ianao.'),
  ('6ab25b92500c32ae14ecb3e6', '2026-09-22T10:42:26.581Z', '2026-09-22T10:42:26.581Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 6, 2, 'Hoatran’ny vehivavy tsara tarehy sy nampihantaina i Ziona zanakavavy.', 'hoatran’ny vehivavy tsara tarehy sy nampihantaina i ziona zanakavavy.'),
  ('6ab25b935d5e131925aa2b0d', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 34, 'Dia hataoko tsy misy feon’olona mifaly sy miravoravo, na feona mpampakatra sy ampakarina, intsony ao amin’ireo tanànan’i Joda sy eny amin’ny lalan’i Jerosalema. Fa ho rava tanteraka ilay tany.’”', 'dia hataoko tsy misy feon’olona mifaly sy miravoravo, na feona mpampakatra sy ampakarina, intsony ao amin’ireo tanànan’i joda sy eny amin’ny lalan’i jerosalema. fa ho rava tanteraka ilay tany.’”'),
  ('6ab25b935d5e131925aa2af9', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 14, 'Koa hataoko hoatran’i Silo ilay trano mitondra ny anarako, na dia itokisanareo aza. Ary hataoko toy izany koa ity toerana nomeko anareo sy ny razambenareo ity.', 'koa hataoko hoatran’i silo ilay trano mitondra ny anarako, na dia itokisanareo aza. ary hataoko toy izany koa ity toerana nomeko anareo sy ny razambenareo ity.'),
  ('6ab25b935d5e131925aa2af1', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 6, 'Aza ampijalina ny hafa firenena monina eo aminareo sy ny kamboty ary ny mpitondratena, ary aza mandatsaka ran’olona tsy manan-tsiny eto amin’ity toerana ity. Aza manompo andriamani-kafa ka hahatonga loza aminareo.', 'aza ampijalina ny hafa firenena monina eo aminareo sy ny kamboty ary ny mpitondratena, ary aza mandatsaka ran’olona tsy manan-tsiny eto amin’ity toerana ity. aza manompo andriamani-kafa ka hahatonga loza aminareo.'),
  ('6ab25b935d5e131925aa2aec', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 1, 'Niteny tamin’i Jeremia i Jehovah hoe:', 'niteny tamin’i jeremia i jehovah hoe:'),
  ('6ab25b935d5e131925aa2b05', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 26, 'Tsy nety nihaino ahy anefa ity vahoaka ity na nanongilan-tsofina. Mafy loha izy ireo ka nanao zavatra ratsy kokoa noho ny nataon’ny razambeny!', 'tsy nety nihaino ahy anefa ity vahoaka ity na nanongilan-tsofina. mafy loha izy ireo ka nanao zavatra ratsy kokoa noho ny nataon’ny razambeny!'),
  ('6ab25b935d5e131925aa2b02', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 23, 'Izao kosa no didy nomeko azy ireo: “Ankatoavy ny teniko, dia ho Andriamanitrareo aho, ary ianareo ho vahoakako. Mandehana amin’ny lalana rehetra asaiko alehanareo, dia hahita soa ianareo.”’', 'izao kosa no didy nomeko azy ireo: “ankatoavy ny teniko, dia ho andriamanitrareo aho, ary ianareo ho vahoakako. mandehana amin’ny lalana rehetra asaiko alehanareo, dia hahita soa ianareo.”’'),
  ('6ab25b935d5e131925aa2aff', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 20, 'Koa izao no lazain’i Jehovah Tompo Fara Tampony: ‘Hanampatra ny hatezerako sy hisafoaka amin’ity toerana ity aho, sy amin’ny olona sy ny biby sy ny hazo eny an-tsaha ary amin’ny vokatry ny tany. Hirehitra tokoa ny fahatezerako ka tsy hovonoina.’', 'koa izao no lazain’i jehovah tompo fara tampony: ‘hanampatra ny hatezerako sy hisafoaka amin’ity toerana ity aho, sy amin’ny olona sy ny biby sy ny hazo eny an-tsaha ary amin’ny vokatry ny tany. hirehitra tokoa ny fahatezerako ka tsy hovonoina.’'),
  ('6ab25b935d5e131925aa2afa', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 15, 'Horoahiko tsy ho eo anatrehako ianareo, hoatran’ny nandroahako ny rahalahinareo rehetra, dia ny taranak’i Efraima manontolo.’', 'horoahiko tsy ho eo anatrehako ianareo, hoatran’ny nandroahako ny rahalahinareo rehetra, dia ny taranak’i efraima manontolo.’'),
  ('6ab25b935d5e131925aa2aed', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 2, '“Mijoroa eo amin’ny vavahadin’ny tranon’i Jehovah, ka torio eo izao hafatra izao: ‘Henoy ny tenin’i Jehovah, ry vahoakan’ny Joda rehetra, izay miditra amin’ireto vavahady ireto mba hiankohoka eo anatrehan’i Jehovah.', '“mijoroa eo amin’ny vavahadin’ny tranon’i jehovah, ka torio eo izao hafatra izao: ‘henoy ny tenin’i jehovah, ry vahoakan’ny joda rehetra, izay miditra amin’ireto vavahady ireto mba hiankohoka eo anatrehan’i jehovah.'),
  ('6ab25b935d5e131925aa2b04', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 25, 'hatramin’ny andro nivoahan’ny razambenareo avy tany Ejipta ka hatramin’izao. Koa nirahiko tany aminareo foana ny mpaminany mpanompoko rehetra isan’andro, ary imbetsaka aho no naniraka azy ireny tany aminareo.', 'hatramin’ny andro nivoahan’ny razambenareo avy tany ejipta ka hatramin’izao. koa nirahiko tany aminareo foana ny mpaminany mpanompoko rehetra isan’andro, ary imbetsaka aho no naniraka azy ireny tany aminareo.'),
  ('6ab25b935d5e131925aa2af4', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 9, 'Mangalatra ianareo, mamono olona, manitsakitsa-bady, mianiana lainga, manao sorona ho an’i Bala, ary manompo andriamanitra tsy fantatrareo.', 'mangalatra ianareo, mamono olona, manitsakitsa-bady, mianiana lainga, manao sorona ho an’i bala, ary manompo andriamanitra tsy fantatrareo.'),
  ('6ab25b935d5e131925aa2b06', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 27, '“Holazainao amin’izy ireo daholo ny teniko, nefa tsy hihaino anao ry zareo. Hiantso azy ireo ianao, nefa tsy hamaly anao ry zareo.', '“holazainao amin’izy ireo daholo ny teniko, nefa tsy hihaino anao ry zareo. hiantso azy ireo ianao, nefa tsy hamaly anao ry zareo.'),
  ('6ab25b935d5e131925aa2b01', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 22, 'Fa tsy niresaka tamin’ny razambenareo momba ny fanatitra dorana manontolo sy ny sorona aho, na nanome didy azy ireo momba an’izany, tamin’ny andro nitondrako azy ireo nivoaka avy tany Ejipta.', 'fa tsy niresaka tamin’ny razambenareo momba ny fanatitra dorana manontolo sy ny sorona aho, na nanome didy azy ireo momba an’izany, tamin’ny andro nitondrako azy ireo nivoaka avy tany ejipta.'),
  ('6ab25b935d5e131925aa2afc', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 17, 'Tsy hitanao angaha izay ataon’izy ireo ao amin’ny tanànan’i Joda sy eny amin’ny lalan’i Jerosalema?', 'tsy hitanao angaha izay ataon’izy ireo ao amin’ny tanànan’i joda sy eny amin’ny lalan’i jerosalema?'),
  ('6ab25b935d5e131925aa2af5', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 10, 'Dia mbola tonga mitsangana eto anatrehako ato amin’ity trano mitondra ny anarako ity ihany ve ianareo, sady milaza hoe: ‘Ho voavonjy isika’, nefa izany zava-maharikoriko rehetra izany no ataonareo?', 'dia mbola tonga mitsangana eto anatrehako ato amin’ity trano mitondra ny anarako ity ihany ve ianareo, sady milaza hoe: ‘ho voavonjy isika’, nefa izany zava-maharikoriko rehetra izany no ataonareo?'),
  ('6ab25b935d5e131925aa2aee', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 3, 'Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Ahitsio ny lalanareo sy ny ataonareo, dia havelako hipetraka eto amin’ity toerana ity foana ianareo.', 'izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: “ahitsio ny lalanareo sy ny ataonareo, dia havelako hipetraka eto amin’ity toerana ity foana ianareo.'),
  ('6ab25b935d5e131925aa2af0', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 5, 'Ahitsio tanteraka ny lalanareo sy ny ataonareo, ary tsarao araka ny rariny ny olona sy izay miady aminy.', 'ahitsio tanteraka ny lalanareo sy ny ataonareo, ary tsarao araka ny rariny ny olona sy izay miady aminy.'),
  ('6ab25b935d5e131925aa2b08', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 29, '“Hetezo ny volonao lava ka ario. Manaova hira fisaonana eny amin’ny havoana mangadihady. Sady nolavin’i Jehovah mantsy ilay taranaka mampahatezitra mafy azy no efa hafoiny.', '“hetezo ny volonao lava ka ario. manaova hira fisaonana eny amin’ny havoana mangadihady. sady nolavin’i jehovah mantsy ilay taranaka mampahatezitra mafy azy no efa hafoiny.'),
  ('6ab25b935d5e131925aa2af6', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 11, 'Heverinareo fa lava-bato fiafenan’ny jiolahy angaha ity trano mitondra ny anarako ity? Hitako ange ny ataonareo e!”, hoy i Jehovah.', 'heverinareo fa lava-bato fiafenan’ny jiolahy angaha ity trano mitondra ny anarako ity? hitako ange ny ataonareo e!”, hoy i jehovah.'),
  ('6ab25b935d5e131925aa2b0b', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 32, '“‘Koa ho avy ny andro’, hoy i Jehovah, ‘izay tsy hiantsoana azy io intsony hoe Tofeta na Lohasahan’ny Taranak’i Hinoma, fa hoe Lohasaha Famonoana. Handevina ao Tofeta izy ireo, mandra-paha tsy hisy toerana azo andevenana intsony ao.', '“‘koa ho avy ny andro’, hoy i jehovah, ‘izay tsy hiantsoana azy io intsony hoe tofeta na lohasahan’ny taranak’i hinoma, fa hoe lohasaha famonoana. handevina ao tofeta izy ireo, mandra-paha tsy hisy toerana azo andevenana intsony ao.'),
  ('6ab25b935d5e131925aa2b09', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 30, '‘Fa nanao izay ratsy teo imasoko ny vahoakan’ny Joda’, hoy i Jehovah. ‘Nataony tao amin’ilay trano mitondra ny anarako ireo sampiny maharikoriko, mba handotoana ny tranoko.', '‘fa nanao izay ratsy teo imasoko ny vahoakan’ny joda’, hoy i jehovah. ‘nataony tao amin’ilay trano mitondra ny anarako ireo sampiny maharikoriko, mba handotoana ny tranoko.'),
  ('6ab25b935d5e131925aa2b00', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 21, '“Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Mandehana àry ampio fanatitra dorana manontolo ny sorona hafa ataonareo, dia hano ho anareo ny hena!', '“izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘mandehana àry ampio fanatitra dorana manontolo ny sorona hafa ataonareo, dia hano ho anareo ny hena!'),
  ('6ab25b935d5e131925aa2afd', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 18, 'Maka kitay ny ankizy ary mandrehitra afo ny rainy, dia ny vehivavy mamolavola koba mba hanaovana mofo atao fanatitra ho an’ny Mpanjakavavin’ny Lanitra. Mandraraka fanatitra zava-pisotro ho an’ny andriamani-kafa koa izy ireo, mba hampahatezitra ahy.', 'maka kitay ny ankizy ary mandrehitra afo ny rainy, dia ny vehivavy mamolavola koba mba hanaovana mofo atao fanatitra ho an’ny mpanjakavavin’ny lanitra. mandraraka fanatitra zava-pisotro ho an’ny andriamani-kafa koa izy ireo, mba hampahatezitra ahy.'),
  ('6ab25b935d5e131925aa2b07', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 28, 'Koa lazao aminy hoe: ‘Ity ilay firenena tsy nankatò ny tenin’i Jehovah Andriamaniny, sady tsy nety nandray anatra. Tsy misy olona tsy mivadika intsony eo amin’izy ireo, ary na ny tsy fivadihana aza tsy asiany resaka akory.’', 'koa lazao aminy hoe: ‘ity ilay firenena tsy nankatò ny tenin’i jehovah andriamaniny, sady tsy nety nandray anatra. tsy misy olona tsy mivadika intsony eo amin’izy ireo, ary na ny tsy fivadihana aza tsy asiany resaka akory.’'),
  ('6ab25b935d5e131925aa2afb', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 16, '“Fa ianao kosa, aza mivavaka ho an’ity vahoaka ity. Aza mitaraina na mivavaka na miangavy amiko ho azy, fa tsy hihaino anao aho.', '“fa ianao kosa, aza mivavaka ho an’ity vahoaka ity. aza mitaraina na mivavaka na miangavy amiko ho azy, fa tsy hihaino anao aho.'),
  ('6ab25b935d5e131925aa2af7', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 12, '“‘Mandehana any Silo, any amin’ilay toerana nametrahako ny anarako tamin’ny voalohany, dia jereo ny nataoko taminy noho ny zava-dratsy nataon’ny Israely vahoakako.', '“‘mandehana any silo, any amin’ilay toerana nametrahako ny anarako tamin’ny voalohany, dia jereo ny nataoko taminy noho ny zava-dratsy nataon’ny israely vahoakako.'),
  ('6ab25b935d5e131925aa2afe', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 19, '‘Izaho ve anefa no tian-dry zareo ho voa amin’izany?’, hoy i Jehovah. ‘Tsy izy ireo ihany ve no ho voa amin’izany, dia ho afa-baraka?’', '‘izaho ve anefa no tian-dry zareo ho voa amin’izany?’, hoy i jehovah. ‘tsy izy ireo ihany ve no ho voa amin’izany, dia ho afa-baraka?’'),
  ('6ab25b935d5e131925aa2b03', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 24, 'Tsy nihaino anefa izy ireo na nanongilan-tsofina, fa nandeha araka izay saim-pantany sady nikiry nanaraka ny fo ratsiny. Nihemotra àry izy ireo fa tsy nandroso,', 'tsy nihaino anefa izy ireo na nanongilan-tsofina, fa nandeha araka izay saim-pantany sady nikiry nanaraka ny fo ratsiny. nihemotra àry izy ireo fa tsy nandroso,'),
  ('6ab25b935d5e131925aa2b0a', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 31, 'Nanorina an’ireo toerana avo ao Tofeta, ao amin’ny Lohasahan’ny Taranak’i Hinoma, izy ireo, mba handoroany ny zanany lahy sy ny zanany vavy ao anaty afo. Tsy nandidy azy hanao an’izany anefa aho, ary tsy tao an-tsaiko akory aza izany.’', 'nanorina an’ireo toerana avo ao tofeta, ao amin’ny lohasahan’ny taranak’i hinoma, izy ireo, mba handoroany ny zanany lahy sy ny zanany vavy ao anaty afo. tsy nandidy azy hanao an’izany anefa aho, ary tsy tao an-tsaiko akory aza izany.’'),
  ('6ab25b935d5e131925aa2b0c', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 33, 'Ho lasa sakafon’ny voro-manidina sy ny bibidia ny fatin’ity vahoaka ity. Ary tsy hisy hampatahotra an’ireny biby ireny ka hampandositra azy.', 'ho lasa sakafon’ny voro-manidina sy ny bibidia ny fatin’ity vahoaka ity. ary tsy hisy hampatahotra an’ireny biby ireny ka hampandositra azy.'),
  ('6ab25b935d5e131925aa2af8', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 13, 'Mbola nanao an’izany rehetra izany ihany anefa ianareo’, hoy i Jehovah, ‘ary na dia efa niteny anareo imbetsaka aza aho, dia tsy nihaino ianareo. Niantso anareo foana aho, fa tsy namaly ianareo.', 'mbola nanao an’izany rehetra izany ihany anefa ianareo’, hoy i jehovah, ‘ary na dia efa niteny anareo imbetsaka aza aho, dia tsy nihaino ianareo. niantso anareo foana aho, fa tsy namaly ianareo.'),
  ('6ab25b935d5e131925aa2aef', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 4, 'Aza matoky ny teny mamitaka, ka milaza hoe: ‘Tempolin’i Jehovah ity, tempolin’i Jehovah, tempolin’i Jehovah!’', 'aza matoky ny teny mamitaka, ka milaza hoe: ‘tempolin’i jehovah ity, tempolin’i jehovah, tempolin’i jehovah!’'),
  ('6ab25b935d5e131925aa2af3', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 8, '“Teny mamitaka anefa no atokisanareo, ka tsy hahasoa anareo mihitsy izany.', '“teny mamitaka anefa no atokisanareo, ka tsy hahasoa anareo mihitsy izany.'),
  ('6ab25b935d5e131925aa2af2', '2026-09-22T10:42:27.765Z', '2026-09-22T10:42:27.765Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 7, 7, 'Raha mankatò an’izany ianareo, dia havelako hipetraka mandrakizay eto amin’ity toerana ity, izany hoe eo amin’ilay tany nomeko ho an’ny razambenareo.”’”', 'raha mankatò an’izany ianareo, dia havelako hipetraka mandrakizay eto amin’ity toerana ity, izany hoe eo amin’ilay tany nomeko ho an’ny razambenareo.”’”'),
  ('6ab25b95999e2c8d99a62672', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 1, '“Amin’izany andro izany”, hoy i Jehovah, “dia hofongarina avy ao am-pasana ny taolan’ireo mpanjakan’ny Joda sy ireo andrianany sy ireo mpisorony sy ireo mpaminaniny, ary ny taolan’ny mponin’i Jerosalema.', '“amin’izany andro izany”, hoy i jehovah, “dia hofongarina avy ao am-pasana ny taolan’ireo mpanjakan’ny joda sy ireo andrianany sy ireo mpisorony sy ireo mpaminaniny, ary ny taolan’ny mponin’i jerosalema.'),
  ('6ab25b95999e2c8d99a62673', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 2, 'Dia halaina ireny ka haparitaka eo anatrehan’ny masoandro sy ny volana ary izay rehetra eny amin’ny lanitra, izay samy tian’izy ireo sy notompoiny sy nivavahany sy nakany hevitra ary niankohofany. Tsy hangonina na halevina ireny taolana ireny, fa ho zezika eny ambonin’ny tany.”', 'dia halaina ireny ka haparitaka eo anatrehan’ny masoandro sy ny volana ary izay rehetra eny amin’ny lanitra, izay samy tian’izy ireo sy notompoiny sy nivavahany sy nakany hevitra ary niankohofany. tsy hangonina na halevina ireny taolana ireny, fa ho zezika eny ambonin’ny tany.”'),
  ('6ab25b95999e2c8d99a62674', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 3, '“Ary aleon’ireo sisa tavela amin’ity firenena ratsy fanahy ity ho faty, toy izay ho velona any amin’ny toerana rehetra hanaparitahako azy”, hoy i Jehovah Tompon’ny tafika.', '“ary aleon’ireo sisa tavela amin’ity firenena ratsy fanahy ity ho faty, toy izay ho velona any amin’ny toerana rehetra hanaparitahako azy”, hoy i jehovah tompon’ny tafika.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25b95999e2c8d99a62675', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 4, '“Lazao amin’izy ireo hoe: ‘Izao no tenin’i Jehovah: “Ho lavo ve izy ireo, dia tsy ho tafarina intsony? Raha miverina ny iray, dia tsy hiverina koa ve ny hafa?', '“lazao amin’izy ireo hoe: ‘izao no tenin’i jehovah: “ho lavo ve izy ireo, dia tsy ho tafarina intsony? raha miverina ny iray, dia tsy hiverina koa ve ny hafa?'),
  ('6ab25b95999e2c8d99a62676', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 5, 'Nahoana ity vahoakan’i Jerosalema ity no mbola mivadika amiko foana? Tsy mitsahatra mamitaka izy ireo, Ary tsy mety miverina amiko.', 'nahoana ity vahoakan’i jerosalema ity no mbola mivadika amiko foana? tsy mitsahatra mamitaka izy ireo, ary tsy mety miverina amiko.'),
  ('6ab25b95999e2c8d99a62677', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 6, 'Nihaino sy nanongilan-tsofina aho, nefa tsy marina ny zavatra noresahin’izy ireo. Tsy mba nisy nibebaka tamin’ny faharatsiany, na niteny hoe: ‘Fa inona ity nataoko?’ Samy miverina manao ny fanaon’ny besinimaro izy ireo, toy ny soavaly miriotra ho any an’ady.', 'nihaino sy nanongilan-tsofina aho, nefa tsy marina ny zavatra noresahin’izy ireo. tsy mba nisy nibebaka tamin’ny faharatsiany, na niteny hoe: ‘fa inona ity nataoko?’ samy miverina manao ny fanaon’ny besinimaro izy ireo, toy ny soavaly miriotra ho any an’ady.'),
  ('6ab25b95999e2c8d99a62678', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 7, 'Na ny vanobe eny amin’ny lanitra aza mahalala tsara ny fotoana andehanany. Ary samy manaja tsara ny fotoana fiverenany ny domohina sy ny sidintsidina ary ny fitatrala. Fa ny vahoakako kosa tsy mba mahalala ny fotoana hitsaran’i Jehovah azy.”’', 'na ny vanobe eny amin’ny lanitra aza mahalala tsara ny fotoana andehanany. ary samy manaja tsara ny fotoana fiverenany ny domohina sy ny sidintsidina ary ny fitatrala. fa ny vahoakako kosa tsy mba mahalala ny fotoana hitsaran’i jehovah azy.”’'),
  ('6ab25b95999e2c8d99a62679', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 8, '‘Ahoana no ahasahianareo milaza hoe: “Hendry izahay sady anananay ny lalàn’i Jehovah”? Nampiasain’ny mpanora-dalàna hanoratana lainga fotsiny mantsy ny peniny mandainga.', '‘ahoana no ahasahianareo milaza hoe: “hendry izahay sady anananay ny lalàn’i jehovah”? nampiasain’ny mpanora-dalàna hanoratana lainga fotsiny mantsy ny peniny mandainga.'),
  ('6ab25b95999e2c8d99a6267a', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 9, 'Menatra ny hendry. Mihorohoro izy ireo, ary ho voafandrika. Tsy noraharahiany ny tenin’i Jehovah, Ka inona intsony no fahendrena ananany?', 'menatra ny hendry. mihorohoro izy ireo, ary ho voafandrika. tsy noraharahiany ny tenin’i jehovah, ka inona intsony no fahendrena ananany?'),
  ('6ab25b95999e2c8d99a6267b', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 10, 'Koa homeko ho an’olon-kafa ny vadiny, Ary ny sahany ho lasan’olona, Satria samy maka tombony azo amin’ny tsy marina izy ireo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra. Ary samy mamitaka na ny mpaminany na ny mpisorona.', 'koa homeko ho an’olon-kafa ny vadiny, ary ny sahany ho lasan’olona, satria samy maka tombony azo amin’ny tsy marina izy ireo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra. ary samy mamitaka na ny mpaminany na ny mpisorona.'),
  ('6ab25b95999e2c8d99a6267c', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 11, 'Miezaka manasitrana ny ratran’ny zanakavavin’ny fireneko izy ireo nefa ataony zara fa vita izany, ka hoy izy ireo: “Fiadanana! Fiadanana!” Nefa tsy misy fiadanana akory.', 'miezaka manasitrana ny ratran’ny zanakavavin’ny fireneko izy ireo nefa ataony zara fa vita izany, ka hoy izy ireo: “fiadanana! fiadanana!” nefa tsy misy fiadanana akory.'),
  ('6ab25b95999e2c8d99a6267d', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 12, 'Mba menatra ve izy ireo noho ny zavatra maharikoriko ataony? Tsy menatra mihitsy izy ireo. Tsy hainy akory na dia ny atao hoe henatra aza! Koa ho lavo miaraka amin’izay lavo izy ireo. Ho tafintohina izy ireo rehefa manasazy azy ireo aho’, hoy i Jehovah.', 'mba menatra ve izy ireo noho ny zavatra maharikoriko ataony? tsy menatra mihitsy izy ireo. tsy hainy akory na dia ny atao hoe henatra aza! koa ho lavo miaraka amin’izay lavo izy ireo. ho tafintohina izy ireo rehefa manasazy azy ireo aho’, hoy i jehovah.'),
  ('6ab25b95999e2c8d99a6267e', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 13, '‘Rehefa angoniko izy ireo, dia horinganiko’, hoy i Jehovah. ‘Tsy hisy voa ho tavela eo amin’ny voaloboka, tsy hisy voa koa ny aviavy, ary halazo ny ravina. Ary izay nomeko azy dia hafoiny.’”', '‘rehefa angoniko izy ireo, dia horinganiko’, hoy i jehovah. ‘tsy hisy voa ho tavela eo amin’ny voaloboka, tsy hisy voa koa ny aviavy, ary halazo ny ravina. ary izay nomeko azy dia hafoiny.’”'),
  ('6ab25b95999e2c8d99a6267f', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 14, '“Nahoana isika no mipetra-potsiny eto? Andao hifamory ka hiditra ao amin’ireo tanàna voaro mafy ary ho faty ao. Fa handringana antsika i Jehovah Andriamanitsika, Ka omeny rano misy poizina isika hosotrointsika, Satria nanota tamin’i Jehovah isika.', '“nahoana isika no mipetra-potsiny eto? andao hifamory ka hiditra ao amin’ireo tanàna voaro mafy ary ho faty ao. fa handringana antsika i jehovah andriamanitsika, ka omeny rano misy poizina isika hosotrointsika, satria nanota tamin’i jehovah isika.'),
  ('6ab25b95999e2c8d99a62680', '2026-09-22T10:42:29.033Z', '2026-09-22T10:42:29.033Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 15, 'Nanantena fiadanana isika, kanjo tsy nisy zavatra tsara nitranga. Nanantena fotoam-panasitranana isika, kanjo horohoro no niseho!', 'nanantena fiadanana isika, kanjo tsy nisy zavatra tsara nitranga. nanantena fotoam-panasitranana isika, kanjo horohoro no niseho!'),
  ('6ab25b95999e2c8d99a62686', '2026-09-22T10:42:29.034Z', '2026-09-22T10:42:29.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 21, 'Torotoro fo aho noho ny ratran’ny zanakavavin’ny fireneko. Kivy be aho, Sady matahotra be mihitsy!', 'torotoro fo aho noho ny ratran’ny zanakavavin’ny fireneko. kivy be aho, sady matahotra be mihitsy!'),
  ('6ab25b95999e2c8d99a62681', '2026-09-22T10:42:29.034Z', '2026-09-22T10:42:29.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 16, 'Heno avy any Dana ny fiefonefon’ny soavalin’ny fahavalo. Mihovotrovotra ilay tany manontolo Rehefa maheno ny feon’ireo soavalilahy mikiakiaka. Tonga ny fahavalo ka mandripaka an’ilay tany sy izay rehetra ao aminy, Dia ny tanàna sy ny mponina ao.”', 'heno avy any dana ny fiefonefon’ny soavalin’ny fahavalo. mihovotrovotra ilay tany manontolo rehefa maheno ny feon’ireo soavalilahy mikiakiaka. tonga ny fahavalo ka mandripaka an’ilay tany sy izay rehetra ao aminy, dia ny tanàna sy ny mponina ao.”'),
  ('6ab25b95999e2c8d99a62684', '2026-09-22T10:42:29.034Z', '2026-09-22T10:42:29.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 19, 'Izany fa miantso vonjy avy any an-tany lavitra Ny zanakavavin’ny fireneko, ka milaza hoe: “Tsy ao Ziona ve i Jehovah? Sa tsy ao ny mpanjakany?” “Fa maninona izy ireo no nampahatezitra ahy tamin’ireo sary sokitra Sy andriamani-kafa tsy misy dikany?”', 'izany fa miantso vonjy avy any an-tany lavitra ny zanakavavin’ny fireneko, ka milaza hoe: “tsy ao ziona ve i jehovah? sa tsy ao ny mpanjakany?” “fa maninona izy ireo no nampahatezitra ahy tamin’ireo sary sokitra sy andriamani-kafa tsy misy dikany?”'),
  ('6ab25b95999e2c8d99a62682', '2026-09-22T10:42:29.034Z', '2026-09-22T10:42:29.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 17, '“Handefasako bibilava eo aminareo, Dia bibilava misy poizina sy tsy mety baikoina. Tena hanaikitra anareo ireny”, hoy i Jehovah.', '“handefasako bibilava eo aminareo, dia bibilava misy poizina sy tsy mety baikoina. tena hanaikitra anareo ireny”, hoy i jehovah.'),
  ('6ab25b95999e2c8d99a62687', '2026-09-22T10:42:29.034Z', '2026-09-22T10:42:29.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 22, 'Tsy misy balsama angaha any Gileada? Ary tsy misy dokotera angaha any? Koa nahoana no mbola tsy sitrana ihany ny zanakavavin’ny fireneko?', 'tsy misy balsama angaha any gileada? ary tsy misy dokotera angaha any? koa nahoana no mbola tsy sitrana ihany ny zanakavavin’ny fireneko?'),
  ('6ab25b95999e2c8d99a62685', '2026-09-22T10:42:29.034Z', '2026-09-22T10:42:29.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 20, '“Efa lasa ny fijinjana ary efa nifarana ny fahavaratra, Nefa mbola tsy voavonjy ihany isika!”', '“efa lasa ny fijinjana ary efa nifarana ny fahavaratra, nefa mbola tsy voavonjy ihany isika!”'),
  ('6ab25b95999e2c8d99a62683', '2026-09-22T10:42:29.034Z', '2026-09-22T10:42:29.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 8, 18, 'Tsy mety sitrana mihitsy ny alaheloko. Marary ny foko.', 'tsy mety sitrana mihitsy ny alaheloko. marary ny foko.'),
  ('6ab25b95bacd87b1d5a5eb32', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 21, 'Fa nitsofoka avy eo am-baravarankelintsika ny fahafatesana, Ary niditra nankao amin’ireo tilikambo voaro mafy, Mba haka ny ankizy eny an-dalana Sy ny tovolahy eny amin’ny tany malalaka.’', 'fa nitsofoka avy eo am-baravarankelintsika ny fahafatesana, ary niditra nankao amin’ireo tilikambo voaro mafy, mba haka ny ankizy eny an-dalana sy ny tovolahy eny amin’ny tany malalaka.’'),
  ('6ab25b95bacd87b1d5a5eb2e', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 17, 'Izao no lazain’i Jehovah Tompon’ny tafika: ‘Aoka ianareo hisaina tsara. Antsoy ireo vehivavy mpanao hira fisaonana, Ary ampanantsoy koa ireo vehivavy efa za-draharaha,', 'izao no lazain’i jehovah tompon’ny tafika: ‘aoka ianareo hisaina tsara. antsoy ireo vehivavy mpanao hira fisaonana, ary ampanantsoy koa ireo vehivavy efa za-draharaha,'),
  ('6ab25b95bacd87b1d5a5eb2d', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 16, 'Haparitako any amin’ireo firenena tsy fantany sy tsy fantatry ny razambeny izy ireo, ary handefasako sabatra hamely azy, mandra-paharipany tanteraka.’', 'haparitako any amin’ireo firenena tsy fantany sy tsy fantatry ny razambeny izy ireo, ary handefasako sabatra hamely azy, mandra-paharipany tanteraka.’'),
  ('6ab25b95bacd87b1d5a5eb27', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 10, 'Hitomany sy hitaraina noho ny amin’ny tendrombohitra aho, Ary hanao hira fisaonana noho ny amin’ny kijana any an-tany efitra. Fa may ireny ka tsy misy olona mandalo intsony eny, Sady tsy misy feona biby fiompy heno intsony. Nandositra ny voro-manidina sy ny bibidia, ka efa lasa daholo.', 'hitomany sy hitaraina noho ny amin’ny tendrombohitra aho, ary hanao hira fisaonana noho ny amin’ny kijana any an-tany efitra. fa may ireny ka tsy misy olona mandalo intsony eny, sady tsy misy feona biby fiompy heno intsony. nandositra ny voro-manidina sy ny bibidia, ka efa lasa daholo.'),
  ('6ab25b95bacd87b1d5a5eb36', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 25, '“Ho avy ny andro”, hoy i Jehovah, “izay hanaovako ampamoaka an’izay rehetra voafora nefa tsy voafora akory raha ny marina,', '“ho avy ny andro”, hoy i jehovah, “izay hanaovako ampamoaka an’izay rehetra voafora nefa tsy voafora akory raha ny marina,'),
  ('6ab25b95bacd87b1d5a5eb26', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 9, '“Koa tsy tokony hataoko ampamoaka ve izy ireo noho izany?”, hoy i Jehovah. “Ary tsy tokony hamaly ny nataon’ny firenena toy izany ve aho?', '“koa tsy tokony hataoko ampamoaka ve izy ireo noho izany?”, hoy i jehovah. “ary tsy tokony hamaly ny nataon’ny firenena toy izany ve aho?'),
  ('6ab25b95bacd87b1d5a5eb1f', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 2, 'Raha mba manana toeram-pilasian’ny mpanao dia lavitra mantsy aho any an-tany efitra, Dia handao ny fireneko aho ka handeha lavitra azy. Mpanitsakitsa-bady mantsy izy rehetra Sady mpivadika daholo.', 'raha mba manana toeram-pilasian’ny mpanao dia lavitra mantsy aho any an-tany efitra, dia handao ny fireneko aho ka handeha lavitra azy. mpanitsakitsa-bady mantsy izy rehetra sady mpivadika daholo.'),
  ('6ab25b95bacd87b1d5a5eb31', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 20, 'Mihainoa ny tenin’i Jehovah ianareo vehivavy. Aoka ianareo hanongilan-tsofina amin’ny teny aloaky ny vavany. Ampianaro an’ity hira fisaonana ity ny zanakareo vavy, Ary samia mampianatra azy io amin’ny namany avy.', 'mihainoa ny tenin’i jehovah ianareo vehivavy. aoka ianareo hanongilan-tsofina amin’ny teny aloaky ny vavany. ampianaro an’ity hira fisaonana ity ny zanakareo vavy, ary samia mampianatra azy io amin’ny namany avy.'),
  ('6ab25b95bacd87b1d5a5eb2b', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 14, 'Fa nikiry nanao izay tian’ny fony fotsiny izy ireo sady nanompo an’ireo sarin’i Bala, hoatran’izay nampianarin’ny razambeny azy.', 'fa nikiry nanao izay tian’ny fony fotsiny izy ireo sady nanompo an’ireo sarin’i bala, hoatran’izay nampianarin’ny razambeny azy.'),
  ('6ab25b95bacd87b1d5a5eb29', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 12, 'Iza no mba hendry ka mahazo ny hevitr’izany? Ary iza no niresahan’i Jehovah ka ho afaka hilaza an’izany? Fa nahoana no rava ilay tany? Ary nahoana izy io no may hoatran’ny tany efitra Ka tsy misy olona mandalo eo intsony?”', 'iza no mba hendry ka mahazo ny hevitr’izany? ary iza no niresahan’i jehovah ka ho afaka hilaza an’izany? fa nahoana no rava ilay tany? ary nahoana izy io no may hoatran’ny tany efitra ka tsy misy olona mandalo eo intsony?”'),
  ('6ab25b95bacd87b1d5a5eb2c', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 15, 'Izao àry no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Hampihinaniko zavamaniry mangidy be ity vahoaka ity, ary hampisotroiko rano misy poizina.', 'izao àry no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘hampihinaniko zavamaniry mangidy be ity vahoaka ity, ary hampisotroiko rano misy poizina.'),
  ('6ab25b95bacd87b1d5a5eb23', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 6, 'Mipetraka eo afovoan’ny fitaka ianao. Namitaka izy ireo ka nanda tsy hahalala ahy”, hoy i Jehovah.', 'mipetraka eo afovoan’ny fitaka ianao. namitaka izy ireo ka nanda tsy hahalala ahy”, hoy i jehovah.'),
  ('6ab25b95bacd87b1d5a5eb1e', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 1, 'Raha mba rano mantsy ny lohako, Ary loharanon-dranomaso ny masoko, Dia hitomany andro aman’alina aho Noho ireo mpiray firenena amiko novonoina.', 'raha mba rano mantsy ny lohako, ary loharanon-dranomaso ny masoko, dia hitomany andro aman’alina aho noho ireo mpiray firenena amiko novonoina.'),
  ('6ab25b95bacd87b1d5a5eb34', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 23, 'Izao no tenin’i Jehovah: “Aoka ny hendry tsy hirehareha amin’ny fahendreny, Ary ny mahery tsy hirehareha amin’ny heriny, Ary ny manankarena tsy hirehareha amin’ny harenany.”', 'izao no tenin’i jehovah: “aoka ny hendry tsy hirehareha amin’ny fahendreny, ary ny mahery tsy hirehareha amin’ny heriny, ary ny manankarena tsy hirehareha amin’ny harenany.”'),
  ('6ab25b95bacd87b1d5a5eb25', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 8, 'Zana-tsipìka mahafaty ny lelan’izy ireo satria milaza fitaka. Fihavanana no resahin’ny olona amin’ny namany, Nefa ao anatiny ao izy efa toy ny olona mamitsaka hanafika.”', 'zana-tsipìka mahafaty ny lelan’izy ireo satria milaza fitaka. fihavanana no resahin’ny olona amin’ny namany, nefa ao anatiny ao izy efa toy ny olona mamitsaka hanafika.”'),
  ('6ab25b95bacd87b1d5a5eb2f', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 18, 'Mba ho avy haingana izy ireo, ka hidradradradra ho antsika. Dia hirotsaka ny ranomasontsika, Ary hisy ranomaso hikoriana avy amin’ny hodi-masontsika.', 'mba ho avy haingana izy ireo, ka hidradradradra ho antsika. dia hirotsaka ny ranomasontsika, ary hisy ranomaso hikoriana avy amin’ny hodi-masontsika.'),
  ('6ab25b95bacd87b1d5a5eb22', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 5, 'Samy mamitaka ny namany avy izy ireo, Ary tsy misy milaza ny marina. Efa nampianariny handainga ny lelany. Mandrera-tena manao zava-dratsy izy ireo.', 'samy mamitaka ny namany avy izy ireo, ary tsy misy milaza ny marina. efa nampianariny handainga ny lelany. mandrera-tena manao zava-dratsy izy ireo.'),
  ('6ab25b95bacd87b1d5a5eb20', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 3, 'Vonona ny handainga ny lelan’izy ireo, hoatran’ny tsipìka efa voaomana hitifirana. Lainga no manjaka ao amin’ilay tany. Tsy misy olona tsy mivadika ao. “Miharatsy foana izy ireo, Ary tsy raharahiany aho”, hoy i Jehovah.', 'vonona ny handainga ny lelan’izy ireo, hoatran’ny tsipìka efa voaomana hitifirana. lainga no manjaka ao amin’ilay tany. tsy misy olona tsy mivadika ao. “miharatsy foana izy ireo, ary tsy raharahiany aho”, hoy i jehovah.'),
  ('6ab25b95bacd87b1d5a5eb37', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 26, 'dia i Ejipta, Joda, Edoma, ny Amonita, Moaba, ary izay rehetra monina any an-tany efitra sady nokakasana ny fihirifany. Fa tsy voafora ny firenena rehetra, ary tsy voafora fo ny taranak’Israely manontolo.”', 'dia i ejipta, joda, edoma, ny amonita, moaba, ary izay rehetra monina any an-tany efitra sady nokakasana ny fihirifany. fa tsy voafora ny firenena rehetra, ary tsy voafora fo ny taranak’israely manontolo.”'),
  ('6ab25b95bacd87b1d5a5eb21', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 4, '“Mitandrema amin’ny namanareo ianareo rehetra, Ary aza atokisana na dia ny rahalahinareo aza. Fa mpamadika ny rahalahy rehetra, Ary mpanendrikendrika ny namana rehetra.', '“mitandrema amin’ny namanareo ianareo rehetra, ary aza atokisana na dia ny rahalahinareo aza. fa mpamadika ny rahalahy rehetra, ary mpanendrikendrika ny namana rehetra.'),
  ('6ab25b95bacd87b1d5a5eb33', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 22, 'Teneno hoe: ‘Izao no lazain’i Jehovah: “Hiampatrampatra ny fatin’ny olona, ka ho toy ny zezika eny an-tsaha, Sy ho toy ny varimbazaha vao avy nojinjaina Nefa tsy misy manangona.”’”', 'teneno hoe: ‘izao no lazain’i jehovah: “hiampatrampatra ny fatin’ny olona, ka ho toy ny zezika eny an-tsaha, sy ho toy ny varimbazaha vao avy nojinjaina nefa tsy misy manangona.”’”'),
  ('6ab25b95bacd87b1d5a5eb30', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 19, 'Fa heno avy ao Ziona ny feon’ireo midradradradra hoe: “Dia rava tokoa moa ny tanànantsika! Afa-baraka tanteraka isika! Fa niala tao amin’ilay tany isika, dia narodan’izy ireo ny tranontsika.”', 'fa heno avy ao ziona ny feon’ireo midradradradra hoe: “dia rava tokoa moa ny tanànantsika! afa-baraka tanteraka isika! fa niala tao amin’ilay tany isika, dia narodan’izy ireo ny tranontsika.”'),
  ('6ab25b95bacd87b1d5a5eb2a', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 13, 'Dia hoy i Jehovah: “Satria tsy niraharaha ny lalàna nomeko azy izy ireo, sady tsy nanaraka an’izany. Tsy nankatò ny teniko koa izy ireo.', 'dia hoy i jehovah: “satria tsy niraharaha ny lalàna nomeko azy izy ireo, sady tsy nanaraka an’izany. tsy nankatò ny teniko koa izy ireo.'),
  ('6ab25b95bacd87b1d5a5eb35', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 24, '“Izay mirehareha kosa, dia aoka hirehareha amin’izao zavatra izao: Mahafantatra tsara sy mahalala ahy izy; Fantany hoe izaho no Jehovah, Ilay maneho fitiavana sy tsy fivadihana, ary manao ny rariny sy ny hitsiny eny ambonin’ny tany, Satria tena mahafinaritra ahy ireo toetra ireo”, hoy i Jehovah.', '“izay mirehareha kosa, dia aoka hirehareha amin’izao zavatra izao: mahafantatra tsara sy mahalala ahy izy; fantany hoe izaho no jehovah, ilay maneho fitiavana sy tsy fivadihana, ary manao ny rariny sy ny hitsiny eny ambonin’ny tany, satria tena mahafinaritra ahy ireo toetra ireo”, hoy i jehovah.'),
  ('6ab25b95bacd87b1d5a5eb28', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 11, 'Hataoko lasa vato mivangongo sy fonenan’ny alikadia i Jerosalema, Ary hataoko lasa aolo tsy misy mponina ireo tanànan’i Joda.', 'hataoko lasa vato mivangongo sy fonenan’ny alikadia i jerosalema, ary hataoko lasa aolo tsy misy mponina ireo tanànan’i joda.'),
  ('6ab25b95bacd87b1d5a5eb24', '2026-09-22T10:42:29.561Z', '2026-09-22T10:42:29.561Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 9, 7, 'Koa izao no lazain’i Jehovah Tompon’ny tafika: “Hataoko mitsonika izy ireo ka hosedraiko, Satria inona moa no mbola azoko atao amin’ny zanakavavin’ny fireneko?', 'koa izao no lazain’i jehovah tompon’ny tafika: “hataoko mitsonika izy ireo ka hosedraiko, satria inona moa no mbola azoko atao amin’ny zanakavavin’ny fireneko?'),
  ('6ab25b964278fcf14fa697e3', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 2, 'Izao no lazain’i Jehovah: “Aza mianatra ny fomban’ireo firenena, Ary aza matahotra be an’ireo famantarana eny amin’ny lanitra Satria hoe matahotra be azy ireny ireo firenena.', 'izao no lazain’i jehovah: “aza mianatra ny fomban’ireo firenena, ary aza matahotra be an’ireo famantarana eny amin’ny lanitra satria hoe matahotra be azy ireny ireo firenena.'),
  ('6ab25b964278fcf14fa697f8', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 23, 'Jehovah ô, fantatro tsara fa tsy an’ny olombelona ny lalan-kalehany. Tsy natao hitondra samirery ny fiainany koa ny olona.', 'jehovah ô, fantatro tsara fa tsy an’ny olombelona ny lalan-kalehany. tsy natao hitondra samirery ny fiainany koa ny olona.'),
  ('6ab25b964278fcf14fa697f6', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 21, 'Tsy misaina ireo mpiandry ondry, Sady tsy manontany an’i Jehovah. Tsy malina àry izy ireo rehefa manao zavatra, Ka miparitaka daholo ny andian’ondriny.”', 'tsy misaina ireo mpiandry ondry, sady tsy manontany an’i jehovah. tsy malina àry izy ireo rehefa manao zavatra, ka miparitaka daholo ny andian’ondriny.”'),
  ('6ab25b964278fcf14fa697e8', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 7, 'Iza no tsy hatahotra anao, ry Mpanjakan’ireo firenena ô? Fa mendrika an’izany ianao. Fa tsy misy toa anao mihitsy Eo amin’ny olon-kendry rehetra eo amin’ireo firenena sy eo amin’ny fanjakany rehetra.', 'iza no tsy hatahotra anao, ry mpanjakan’ireo firenena ô? fa mendrika an’izany ianao. fa tsy misy toa anao mihitsy eo amin’ny olon-kendry rehetra eo amin’ireo firenena sy eo amin’ny fanjakany rehetra.'),
  ('6ab25b964278fcf14fa697e6', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 5, 'Hoatran’ny sariolona fampitahoram-borona eny amin’ny sahan-kôkômbra ireny, ka tsy afa-miteny. Tsy maintsy bataina ireny satria tsy afa-mamindra. Aza matahotra azy, fa sady tsy afaka manisy ratsy ireny No tsy afaka manisy soa.”', 'hoatran’ny sariolona fampitahoram-borona eny amin’ny sahan-kôkômbra ireny, ka tsy afa-miteny. tsy maintsy bataina ireny satria tsy afa-mamindra. aza matahotra azy, fa sady tsy afaka manisy ratsy ireny no tsy afaka manisy soa.”'),
  ('6ab25b964278fcf14fa697f0', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 15, 'Sandoka fotsiny ireny sady ihomehezan’ny olona. Ho fongana ireny rehefa tonga ny andro hanasaziana azy.', 'sandoka fotsiny ireny sady ihomehezan’ny olona. ho fongana ireny rehefa tonga ny andro hanasaziana azy.'),
  ('6ab25b964278fcf14fa697e9', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 8, 'Sady adala no tsy misaina daholo izy ireo. Fitaka tanteraka ny zavatra ampianarin’ny hazo.', 'sady adala no tsy misaina daholo izy ireo. fitaka tanteraka ny zavatra ampianarin’ny hazo.'),
  ('6ab25b964278fcf14fa697ed', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 12, 'Izy Ilay nanao ny tany tamin’ny heriny, Dia Ilay nanao izay hahamafy orina ny tany lonaka tamin’ny fahendreny, Sy namelatra ny lanitra tamin’ny fahiratan-tsainy.', 'izy ilay nanao ny tany tamin’ny heriny, dia ilay nanao izay hahamafy orina ny tany lonaka tamin’ny fahendreny, sy namelatra ny lanitra tamin’ny fahiratan-tsainy.'),
  ('6ab25b964278fcf14fa697ec', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 11, '* Izao no holazainareo amin’izy ireo: “Ho fongana tsy ho eto an-tany sy etỳ ambanin’ny lanitra Ireo andriamanitra tsy nanao ny lanitra sy ny tany.”', '* izao no holazainareo amin’izy ireo: “ho fongana tsy ho eto an-tany sy etỳ ambanin’ny lanitra ireo andriamanitra tsy nanao ny lanitra sy ny tany.”'),
  ('6ab25b964278fcf14fa697f1', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 16, 'Tsy mba toy ireny kosa ilay Anjaran’i Jakoba, Fa izy Ilay nanao ny zava-drehetra, Ary ny Israely no tehin’ny lovany. Jehovah Tompon’ny tafika no anarany.', 'tsy mba toy ireny kosa ilay anjaran’i jakoba, fa izy ilay nanao ny zava-drehetra, ary ny israely no tehin’ny lovany. jehovah tompon’ny tafika no anarany.'),
  ('6ab25b964278fcf14fa697ea', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 9, 'Nohafarana avy any Tarsisy ny volafotsy nofisahina, ary avy any Ofaza ny volamena. Namboarin’ny mpanao asa tanana sy ny mpanefy ireny. Kofehy manga sy volonondry volomparasy no nanaovana ny fitafiany. Asa tanan’olona mahay izy rehetra.', 'nohafarana avy any tarsisy ny volafotsy nofisahina, ary avy any ofaza ny volamena. namboarin’ny mpanao asa tanana sy ny mpanefy ireny. kofehy manga sy volonondry volomparasy no nanaovana ny fitafiany. asa tanan’olona mahay izy rehetra.'),
  ('6ab25b964278fcf14fa697e4', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 3, 'Fa fitaka ny fanaon’ireo firenena. Hazo nokapaina tany an’ala fotsiny ilay izy, Dia namboarin’ny mpanao asa tanana tamin’ny fitaovany.', 'fa fitaka ny fanaon’ireo firenena. hazo nokapaina tany an’ala fotsiny ilay izy, dia namboarin’ny mpanao asa tanana tamin’ny fitaovany.'),
  ('6ab25b964278fcf14fa697f7', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 22, 'Henoy! Izany misy filazana! Migodongodona mafy avy any amin’ilay tany any avaratra ny fahavalo, Mba hahatonga an’ireo tanànan’i Joda ho aolo sy ho lasa fonenan’ny alikadia.', 'henoy! izany misy filazana! migodongodona mafy avy any amin’ilay tany any avaratra ny fahavalo, mba hahatonga an’ireo tanànan’i joda ho aolo sy ho lasa fonenan’ny alikadia.'),
  ('6ab25b964278fcf14fa697f5', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 20, 'Rava ny tranolaiko ary nisy nanapaka daholo ny tady fanenjanana azy. Nandao ahy ireo zanako ka tsy eo intsony. Tsy misy tavela mba hanenjana ny tranolaiko na hanangana azy.', 'rava ny tranolaiko ary nisy nanapaka daholo ny tady fanenjanana azy. nandao ahy ireo zanako ka tsy eo intsony. tsy misy tavela mba hanenjana ny tranolaiko na hanangana azy.'),
  ('6ab25b964278fcf14fa697f4', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 19, 'Idiran-doza aho fa maratra! Tsy mety sitrana mihitsy ny ratrako. Dia hoy aho: “Efa izao no aretiko, ka dia hozakaiko.', 'idiran-doza aho fa maratra! tsy mety sitrana mihitsy ny ratrako. dia hoy aho: “efa izao no aretiko, ka dia hozakaiko.'),
  ('6ab25b964278fcf14fa697f3', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 18, 'Fa izao no lazain’i Jehovah: “Hatsipiko ho any ivelan’ny taniny ny mponina, amin’ity indray mandeha ity, Ary hataoko mahita faisana.”', 'fa izao no lazain’i jehovah: “hatsipiko ho any ivelan’ny taniny ny mponina, amin’ity indray mandeha ity, ary hataoko mahita faisana.”'),
  ('6ab25b964278fcf14fa697eb', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 10, 'I Jehovah kosa no tena Andriamanitra. Izy no Andriamanitra velona sy Mpanjaka mandrakizay. Hihovotrovotra ny tany noho ny fahatezerany, Ary tsy hisy firenena hahatanty ny fanamelohany.', 'i jehovah kosa no tena andriamanitra. izy no andriamanitra velona sy mpanjaka mandrakizay. hihovotrovotra ny tany noho ny fahatezerany, ary tsy hisy firenena hahatanty ny fanamelohany.'),
  ('6ab25b964278fcf14fa697ee', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 13, 'Rehefa ataony heno ny feony, Dia misamboaravoara ny rano eny amin’ny lanitra, Ary mampiakatra rahona avy any amin’ny faran’ny tany izy. Manao tselatra ho an’ny orana izy, Ary avoakany avy ao amin’ny trano fitehirizany azy ny rivotra.', 'rehefa ataony heno ny feony, dia misamboaravoara ny rano eny amin’ny lanitra, ary mampiakatra rahona avy any amin’ny faran’ny tany izy. manao tselatra ho an’ny orana izy, ary avoakany avy ao amin’ny trano fitehirizany azy ny rivotra.'),
  ('6ab25b964278fcf14fa697e5', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 4, 'Ravahany volafotsy sy volamena ilay izy, Ary nakambany tamin’ny marotoa sy fantsika mba tsy hianjera.', 'ravahany volafotsy sy volamena ilay izy, ary nakambany tamin’ny marotoa sy fantsika mba tsy hianjera.'),
  ('6ab25b964278fcf14fa697e2', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 1, 'Henoy ny teny fanamelohan’i Jehovah anareo, ry taranak’Israely!', 'henoy ny teny fanamelohan’i jehovah anareo, ry taranak’israely!'),
  ('6ab25b964278fcf14fa697f9', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 24, 'Ahitsio araka izay hitanao hoe rariny aho, Jehovah ô, Fa aza atao amim-pahatezerana, sao lasa ataonao tsinontsinona aho.', 'ahitsio araka izay hitanao hoe rariny aho, jehovah ô, fa aza atao amim-pahatezerana, sao lasa ataonao tsinontsinona aho.'),
  ('6ab25b964278fcf14fa697f2', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 17, 'Angony ny entanao eo amin’ny tany, Ry vehivavy natao fahirano!', 'angony ny entanao eo amin’ny tany, ry vehivavy natao fahirano!'),
  ('6ab25b964278fcf14fa697fa', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 25, 'Anamparo ny hatezeranao ireo firenena tsy miraharaha anao Sy ireo foko tsy miantso ny anaranao. Fa naripak’izy ireo i Jakoba. Naripak’izy ireo izy ka saika fongana tanteraka, Ary noravany ny taniny.', 'anamparo ny hatezeranao ireo firenena tsy miraharaha anao sy ireo foko tsy miantso ny anaranao. fa naripak’izy ireo i jakoba. naripak’izy ireo izy ka saika fongana tanteraka, ary noravany ny taniny.'),
  ('6ab25b964278fcf14fa697ef', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 14, 'Tsy misaina ny olona rehetra sady manaonao foana. Ho menatra ny mpanefy rehetra fa nanao sary sokitra. Fitaka fotsiny mantsy ny sarivongana metaly nataony, Sady tsy mananaina.', 'tsy misaina ny olona rehetra sady manaonao foana. ho menatra ny mpanefy rehetra fa nanao sary sokitra. fitaka fotsiny mantsy ny sarivongana metaly nataony, sady tsy mananaina.'),
  ('6ab25b964278fcf14fa697e7', '2026-09-22T10:42:30.137Z', '2026-09-22T10:42:30.137Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 10, 6, 'Tsy misy hoatr’anao, Jehovah ô! Tena miavaka ianao, ary be voninahitra sy mahery ny anaranao.', 'tsy misy hoatr’anao, jehovah ô! tena miavaka ianao, ary be voninahitra sy mahery ny anaranao.'),
  ('6ab25b96bb68170cdcee8bc3', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 22, 'Izao no tenin’i Jehovah Tompon’ny tafika: “Hataoko ampamoaka izy ireo. Ho fatin’ny sabatra ny tovolahy, ary ho faty mosary ny zanany lahy sy ny zanany vavy.', 'izao no tenin’i jehovah tompon’ny tafika: “hataoko ampamoaka izy ireo. ho fatin’ny sabatra ny tovolahy, ary ho faty mosary ny zanany lahy sy ny zanany vavy.'),
  ('6ab25b96bb68170cdcee8bbf', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 18, 'Nampahafantarin’i Jehovah aho ka nahalala. Nataonao hitako, tamin’izany fotoana izany, izay nataon’izy ireo.', 'nampahafantarin’i jehovah aho ka nahalala. nataonao hitako, tamin’izany fotoana izany, izay nataon’izy ireo.'),
  ('6ab25b96bb68170cdcee8bb3', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 6, 'Niteny tamiko i Jehovah avy eo hoe: “Ambarao ao amin’ireo tanànan’i Joda sy eny amin’ny lalan’i Jerosalema ireto teny rehetra ireto: ‘Henoy ny teny ato amin’ity fifanekena ity, dia araho.', 'niteny tamiko i jehovah avy eo hoe: “ambarao ao amin’ireo tanànan’i joda sy eny amin’ny lalan’i jerosalema ireto teny rehetra ireto: ‘henoy ny teny ato amin’ity fifanekena ity, dia araho.'),
  ('6ab25b96bb68170cdcee8bbb', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 14, '“Fa ianao kosa, aza mivavaka ho an’ity vahoaka ity. Aza mitaraina na mivavaka ho azy, fa tsy hihaino aho rehefa miantso ahy izy ireo noho ny loza manjo azy.', '“fa ianao kosa, aza mivavaka ho an’ity vahoaka ity. aza mitaraina na mivavaka ho azy, fa tsy hihaino aho rehefa miantso ahy izy ireo noho ny loza manjo azy.'),
  ('6ab25b96bb68170cdcee8bb0', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 3, 'ka lazao aminy hoe: ‘Izao no tenin’i Jehovah Andriamanitry ny Israely: “Voaozona izay tsy mankatò ny teny ato amin’ity fifanekena ity,', 'ka lazao aminy hoe: ‘izao no tenin’i jehovah andriamanitry ny israely: “voaozona izay tsy mankatò ny teny ato amin’ity fifanekena ity,'),
  ('6ab25b96bb68170cdcee8bb1', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 4, 'izay nasaiko narahin’ny razambenareo tamin’ny andro nitondrako azy nivoaka avy tany Ejipta, avy tao amin’ny fatana fandrendrehana vy. Hoy mantsy aho tamin’izay: ‘Ankatoavy ny teniko, ary ataovy izay rehetra andidiako anareo. Dia ho vahoakako ianareo, ary izaho ho Andriamanitrareo,', 'izay nasaiko narahin’ny razambenareo tamin’ny andro nitondrako azy nivoaka avy tany ejipta, avy tao amin’ny fatana fandrendrehana vy. hoy mantsy aho tamin’izay: ‘ankatoavy ny teniko, ary ataovy izay rehetra andidiako anareo. dia ho vahoakako ianareo, ary izaho ho andriamanitrareo,'),
  ('6ab25b96bb68170cdcee8bb7', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 10, 'Naverin’izy ireo indray ny fahadisoan’ny razambeny taloha, izay tsy nety nankatò ny teniko. Nanaraka andriamani-kafa sy nanompo azy ireny koa izy ireo. Nivadika tamin’ny fifanekena nataoko tamin’ny razambeny ny taranak’Israely sy ny taranak’i Joda.', 'naverin’izy ireo indray ny fahadisoan’ny razambeny taloha, izay tsy nety nankatò ny teniko. nanaraka andriamani-kafa sy nanompo azy ireny koa izy ireo. nivadika tamin’ny fifanekena nataoko tamin’ny razambeny ny taranak’israely sy ny taranak’i joda.'),
  ('6ab25b96bb68170cdcee8baf', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 2, '“Samia mihaino ny teny ato amin’ity fifanekena ity! “Resaho amin’ny fokon’i Joda sy ny mponin’i Jerosalema izany,', '“samia mihaino ny teny ato amin’ity fifanekena ity! “resaho amin’ny fokon’i joda sy ny mponin’i jerosalema izany,'),
  ('6ab25b96bb68170cdcee8bc4', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 23, 'Tsy hisy hiangana izy ireo, satria hahatonga loza amin’ny mponin’i Anatota aho, amin’ny taona hanaovako ampamoaka azy.”', 'tsy hisy hiangana izy ireo, satria hahatonga loza amin’ny mponin’i anatota aho, amin’ny taona hanaovako ampamoaka azy.”'),
  ('6ab25b96bb68170cdcee8bb5', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 8, 'Tsy nihaino anefa izy ireo na nanongilan-tsofina, fa mbola samy nikiry nanaraka ny fo ratsiny ihany. Koa notanterahiko tamin’izy ireo ny teny rehetra ato amin’ity fifanekena ity, izay nasaiko narahiny nefa tsy narahiny.’”', 'tsy nihaino anefa izy ireo na nanongilan-tsofina, fa mbola samy nikiry nanaraka ny fo ratsiny ihany. koa notanterahiko tamin’izy ireo ny teny rehetra ato amin’ity fifanekena ity, izay nasaiko narahiny nefa tsy narahiny.’”'),
  ('6ab25b96bb68170cdcee8bb6', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 9, 'Hoy koa i Jehovah tamiko: “Mitetika ny hikomy ny fokon’i Joda sy ny mponin’i Jerosalema.', 'hoy koa i jehovah tamiko: “mitetika ny hikomy ny fokon’i joda sy ny mponin’i jerosalema.'),
  ('6ab25b96bb68170cdcee8bba', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 13, 'Fa lasa maro toy ny tanànanareo ny andriamanitrareo, ry Joda ô! Ary be dia be hoatran’ireo lalana ao Jerosalema ny alitara naorinareo ho an’ilay zavatra mahamenatra, dia alitara anaovana sorona ho an’i Bala.’', 'fa lasa maro toy ny tanànanareo ny andriamanitrareo, ry joda ô! ary be dia be hoatran’ireo lalana ao jerosalema ny alitara naorinareo ho an’ilay zavatra mahamenatra, dia alitara anaovana sorona ho an’i bala.’'),
  ('6ab25b96bb68170cdcee8bb4', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 7, 'Fa efa nanariko mafy ny razambenareo tamin’ny andro nitondrako azy avy tany Ejipta ka hatramin’izao. Nananatra azy imbetsaka aho hoe: “Ankatoavy ny teniko.”', 'fa efa nanariko mafy ny razambenareo tamin’ny andro nitondrako azy avy tany ejipta ka hatramin’izao. nananatra azy imbetsaka aho hoe: “ankatoavy ny teniko.”'),
  ('6ab25b96bb68170cdcee8bae', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 1, 'Niteny tamin’i Jeremia i Jehovah hoe:', 'niteny tamin’i jeremia i jehovah hoe:'),
  ('6ab25b96bb68170cdcee8bc2', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 21, 'Nomelohin’i Jehovah àry ny mponin’i Anatota, izay mitady hamono anao ka miteny hoe: “Aza maminany amin’ny anaran’i Jehovah ianao, raha tsy izany dia hovonoinay.”', 'nomelohin’i jehovah àry ny mponin’i anatota, izay mitady hamono anao ka miteny hoe: “aza maminany amin’ny anaran’i jehovah ianao, raha tsy izany dia hovonoinay.”'),
  ('6ab25b96bb68170cdcee8bc1', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 20, 'Mitsara araka ny rariny anefa i Jehovah Tompon’ny tafika. Mandinika ny eritreritra lalina indrindra sy ny fo izy. Avelao aho hahita ny hamalianao azy ireny, Satria ianao no nanankinako ny ady nataoko teny amin’ny fitsarana!', 'mitsara araka ny rariny anefa i jehovah tompon’ny tafika. mandinika ny eritreritra lalina indrindra sy ny fo izy. avelao aho hahita ny hamalianao azy ireny, satria ianao no nanankinako ny ady nataoko teny amin’ny fitsarana!'),
  ('6ab25b96bb68170cdcee8bc0', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 19, 'Hoatran’ny zanak’ondry malemy paika nentina hovonoina aho. Tsy fantatro hoe nanao tetika hamelezana ahy izy ireo. Niteny izy ireo hoe: “Andao hopotehintsika ilay hazo sy ny voany, Ary hofongorantsika tsy ho eo amin’ny tanin’ny velona izy, Mba tsy hotsaroana intsony ny anarany.”', 'hoatran’ny zanak’ondry malemy paika nentina hovonoina aho. tsy fantatro hoe nanao tetika hamelezana ahy izy ireo. niteny izy ireo hoe: “andao hopotehintsika ilay hazo sy ny voany, ary hofongorantsika tsy ho eo amin’ny tanin’ny velona izy, mba tsy hotsaroana intsony ny anarany.”'),
  ('6ab25b96bb68170cdcee8bbc', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 15, 'Mbola manan-jo ho ao an-tranoko ve ny vahoakako tena tiako, Nefa ny ankamaroan’izy ireo aza manatanteraka ny teti-dratsiny? Hahasakana ny loza tsy hihatra aminao ve ny hena masina atolotr’izy ireo? Ho faly ve ianao amin’izay fotoana izay?', 'mbola manan-jo ho ao an-tranoko ve ny vahoakako tena tiako, nefa ny ankamaroan’izy ireo aza manatanteraka ny teti-dratsiny? hahasakana ny loza tsy hihatra aminao ve ny hena masina atolotr’izy ireo? ho faly ve ianao amin’izay fotoana izay?'),
  ('6ab25b96bb68170cdcee8bb2', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 5, 'mba hanatanterahako ny fianianana nataoko tamin’ny razambenareo, dia ny hanome azy ireo an’ilay tany tondra-dronono sy tantely, hoatran’ny amin’izao androany izao.’”’” Dia namaly aho hoe: “Amena, Jehovah ô!”', 'mba hanatanterahako ny fianianana nataoko tamin’ny razambenareo, dia ny hanome azy ireo an’ilay tany tondra-dronono sy tantely, hoatran’ny amin’izao androany izao.’”’” dia namaly aho hoe: “amena, jehovah ô!”'),
  ('6ab25b96bb68170cdcee8bb8', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 11, 'Koa izao no lazain’i Jehovah: ‘Hahatonga loza aminy aho, ka tsy ho afa-mandositra an’izany izy ireo. Ary hiantso vonjy amiko izy ireo, fa tsy hihaino azy aho.', 'koa izao no lazain’i jehovah: ‘hahatonga loza aminy aho, ka tsy ho afa-mandositra an’izany izy ireo. ary hiantso vonjy amiko izy ireo, fa tsy hihaino azy aho.'),
  ('6ab25b96bb68170cdcee8bbe', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 17, '“Nanambara loza hamelezana anao i Jehovah Tompon’ny tafika, Ilay namboly anao, noho ny zava-dratsy nataon’ny taranak’Israely sy ny taranak’i Joda. Nampahatezitra ahy izy ireo satria nanao sorona ho an’i Bala.”', '“nanambara loza hamelezana anao i jehovah tompon’ny tafika, ilay namboly anao, noho ny zava-dratsy nataon’ny taranak’israely sy ny taranak’i joda. nampahatezitra ahy izy ireo satria nanao sorona ho an’i bala.”'),
  ('6ab25b96bb68170cdcee8bbd', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 16, 'Taloha ianao nantsoin’i Jehovah hoe oliva midoroboka, Tsara tarehy sady nisy voany tena tsara. Tao anatin’ny tabataba be anefa no nandrehetany afo handoroana azy. Ary notapahina ny rantsany.', 'taloha ianao nantsoin’i jehovah hoe oliva midoroboka, tsara tarehy sady nisy voany tena tsara. tao anatin’ny tabataba be anefa no nandrehetany afo handoroana azy. ary notapahina ny rantsany.'),
  ('6ab25b96bb68170cdcee8bb9', '2026-09-22T10:42:30.739Z', '2026-09-22T10:42:30.739Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 11, 12, 'Dia handeha ho any amin’ireo andriamanitra, izay nanaovany sorona, ny mponina ao an-tanànan’i Joda sy Jerosalema, ka hiantso vonjy aminy. Tsy hahavonjy azy ireo mihitsy anefa ireny amin’ny fotoana hiavian’ny loza.', 'dia handeha ho any amin’ireo andriamanitra, izay nanaovany sorona, ny mponina ao an-tanànan’i joda sy jerosalema, ka hiantso vonjy aminy. tsy hahavonjy azy ireo mihitsy anefa ireny amin’ny fotoana hiavian’ny loza.'),
  ('6ab25b97054bd4f8a5a602db', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 16, '“Ary ho tsara toerana eo amin’ny vahoakako izy ireo, raha tena mianatra ny fanaon’ny vahoakako sy mianiana amin’ny anarako hoe: ‘Raha mbola velona koa i Jehovah!’, toy ny nampianaran’izy ireo ny vahoakako hianiana tamin’ny anaran’i Bala.', '“ary ho tsara toerana eo amin’ny vahoakako izy ireo, raha tena mianatra ny fanaon’ny vahoakako sy mianiana amin’ny anarako hoe: ‘raha mbola velona koa i jehovah!’, toy ny nampianaran’izy ireo ny vahoakako hianiana tamin’ny anaran’i bala.'),
  ('6ab25b97054bd4f8a5a602ce', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 3, 'Fa ianao kosa, Jehovah ô, mahalala tsara ahy sady mahita ahy. Nodinihinao ny foko ka hitanao fa mifikitra aminao. Avaho toy ny ondry hovonoina izy ireny, Ary atokàny ho amin’ny andro famonoana.', 'fa ianao kosa, jehovah ô, mahalala tsara ahy sady mahita ahy. nodinihinao ny foko ka hitanao fa mifikitra aminao. avaho toy ny ondry hovonoina izy ireny, ary atokàny ho amin’ny andro famonoana.'),
  ('6ab25b97054bd4f8a5a602d1', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 6, 'Na ny rahalahinao sy ny ankohonan-drainao aza Mamitaka anao. Miantsoantso mafy hamely anao izy ireo. Aza matoky azy, Na dia zavatra tsara aza no lazainy aminao.', 'na ny rahalahinao sy ny ankohonan-drainao aza mamitaka anao. miantsoantso mafy hamely anao izy ireo. aza matoky azy, na dia zavatra tsara aza no lazainy aminao.'),
  ('6ab25b97054bd4f8a5a602da', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 15, 'Rehefa avy manongotra azy ireo aho, dia hamindra fo aminy ka hamerina ny tsirairay ho ao amin’ny lovany sy ny taniny.”', 'rehefa avy manongotra azy ireo aho, dia hamindra fo aminy ka hamerina ny tsirairay ho ao amin’ny lovany sy ny taniny.”'),
  ('6ab25b97054bd4f8a5a602d7', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 12, 'Tonga avy any amin’ny lala-masaka rehetra any an-tany efitra ireo mpandrava, Satria mandripaka olona hatrany amin’ny faran’ilay tany ka hatrany amin’ny faran’ilay tany ny sabatr’i Jehovah. Tsy misy fiadanana na ho an’iza na ho an’iza.', 'tonga avy any amin’ny lala-masaka rehetra any an-tany efitra ireo mpandrava, satria mandripaka olona hatrany amin’ny faran’ilay tany ka hatrany amin’ny faran’ilay tany ny sabatr’i jehovah. tsy misy fiadanana na ho an’iza na ho an’iza.'),
  ('6ab25b97054bd4f8a5a602cd', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 2, 'Nambolenao izy ireny ka miorim-paka. Mitombo izy ireny ary mamoa. Tsy afaka am-bavany ianao, nefa lavitry ny fony.', 'nambolenao izy ireny ka miorim-paka. mitombo izy ireny ary mamoa. tsy afaka am-bavany ianao, nefa lavitry ny fony.'),
  ('6ab25b97054bd4f8a5a602d6', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 11, 'Lasa tany ngazana ilay izy, Ary lasa karakaina Sy tsy misy mponina eo anatrehako. Lasa ravarava ilay tany manontolo, Nefa tsy misy olona mandray am-po an’izany.', 'lasa tany ngazana ilay izy, ary lasa karakaina sy tsy misy mponina eo anatrehako. lasa ravarava ilay tany manontolo, nefa tsy misy olona mandray am-po an’izany.'),
  ('6ab25b97054bd4f8a5a602d2', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 7, '“Nilaozako ny tranoko, ary nafoiko ny lovako. Nataoko resin’ny fahavalony ilay malalan’ny foko.', '“nilaozako ny tranoko, ary nafoiko ny lovako. nataoko resin’ny fahavalony ilay malalan’ny foko.'),
  ('6ab25b97054bd4f8a5a602d8', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 13, 'Varimbazaha no nafafin’izy ireo nefa tsilo no nojinjainy. Reraka be izy ireo nefa niasa maina fotsiny. Ho menatra izy ireo noho ny vokatra azony, Satria tezitra be i Jehovah.”', 'varimbazaha no nafafin’izy ireo nefa tsilo no nojinjainy. reraka be izy ireo nefa niasa maina fotsiny. ho menatra izy ireo noho ny vokatra azony, satria tezitra be i jehovah.”'),
  ('6ab25b97054bd4f8a5a602d4', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 9, 'Amiko dia toy ny vorona mpihaza maro loko ny lovako. Manodidina sy manafika azy ny vorona hafa mpihaza. Avia daholo ianareo biby eny an-tsaha, Avia mihinàna!', 'amiko dia toy ny vorona mpihaza maro loko ny lovako. manodidina sy manafika azy ny vorona hafa mpihaza. avia daholo ianareo biby eny an-tsaha, avia mihinàna!'),
  ('6ab25b97054bd4f8a5a602cf', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 4, 'Mandra-pahoviana ity tany ity no ho karakaina, Ary mandra-pahoviana ny zavamaniry eny an-tsaha no ho maina? Ripaka ny biby sy ny vorona Noho ny faharatsian’ny mponina ao. Hoy mantsy izy ireo: “Tsy hahita an’izay hitranga amintsika izy.”', 'mandra-pahoviana ity tany ity no ho karakaina, ary mandra-pahoviana ny zavamaniry eny an-tsaha no ho maina? ripaka ny biby sy ny vorona noho ny faharatsian’ny mponina ao. hoy mantsy izy ireo: “tsy hahita an’izay hitranga amintsika izy.”'),
  ('6ab25b97054bd4f8a5a602d9', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 14, 'Izao no lazain’i Jehovah mba hanamelohana ny ratsy fanahy rehetra manodidina ahy, izay mikitikitika an’ilay lova nomeko ho an’ny Israely vahoakako: “Hongotako tsy ho eo amin’ny taniny izy ireo, ary hongotako tsy ho eo amin’izy ireo ny taranak’i Joda.', 'izao no lazain’i jehovah mba hanamelohana ny ratsy fanahy rehetra manodidina ahy, izay mikitikitika an’ilay lova nomeko ho an’ny israely vahoakako: “hongotako tsy ho eo amin’ny taniny izy ireo, ary hongotako tsy ho eo amin’izy ireo ny taranak’i joda.'),
  ('6ab25b97054bd4f8a5a602d3', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 8, 'Amiko dia nanjary toy ny liona any an’ala ny lovako. Nierona tamiko izy Ka lasa halako.', 'amiko dia nanjary toy ny liona any an’ala ny lovako. nierona tamiko izy ka lasa halako.'),
  ('6ab25b97054bd4f8a5a602dc', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 17, 'Fa hongotako kosa izany firenena izany raha tsy mety mankatò. Hongotako sy horavako izy”, hoy i Jehovah.', 'fa hongotako kosa izany firenena izany raha tsy mety mankatò. hongotako sy horavako izy”, hoy i jehovah.'),
  ('6ab25b97054bd4f8a5a602d0', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 5, 'Olona aza no niara-nihazakazaka taminao, dia efa nandreraka anao. Koa ahoana moa no hahafahanao hifaninana amin’ny soavaly? Na dia milamina aza ianao ao amin’ny tany tsy misy ady, Dia hanao ahoana ianao rehefa ao amin’ny kirihitrala matevina eny amoron’i Jordana?', 'olona aza no niara-nihazakazaka taminao, dia efa nandreraka anao. koa ahoana moa no hahafahanao hifaninana amin’ny soavaly? na dia milamina aza ianao ao amin’ny tany tsy misy ady, dia hanao ahoana ianao rehefa ao amin’ny kirihitrala matevina eny amoron’i jordana?'),
  ('6ab25b97054bd4f8a5a602cc', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 1, 'Manao ny rariny ianao, Jehovah ô, rehefa mitaraina aminao aho Sy rehefa miresaka aminao momba ny fanaovana ny rariny. Nahoana anefa no mahomby ny ratsy fanahy, Ary nahoana ny mpivadika no tsy mba manana ahiahy?', 'manao ny rariny ianao, jehovah ô, rehefa mitaraina aminao aho sy rehefa miresaka aminao momba ny fanaovana ny rariny. nahoana anefa no mahomby ny ratsy fanahy, ary nahoana ny mpivadika no tsy mba manana ahiahy?'),
  ('6ab25b97054bd4f8a5a602d5', '2026-09-22T10:42:31.635Z', '2026-09-22T10:42:31.635Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 12, 10, 'Maro ireo mpiandry ondry nanimba ny tanimboaloboko. Nohitsakitsahin’izy ireo ilay anjara taniko. Novany ho tany efitra sy tsy misy mponina ilay anjara taniko nahafinaritra ahy.', 'maro ireo mpiandry ondry nanimba ny tanimboaloboko. nohitsakitsahin’izy ireo ilay anjara taniko. novany ho tany efitra sy tsy misy mponina ilay anjara taniko nahafinaritra ahy.'),
  ('6ab25b98603fec3ed368af50', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 23, 'Mahavita manova ny volon-kodiny ve ny Kosita, ary ny leopara ve mahavita manova ny pentimpentina aminy? Raha izany, dia mahavita manao ny tsara ianareo, Izay nampiofanina hanao ratsy.', 'mahavita manova ny volon-kodiny ve ny kosita, ary ny leopara ve mahavita manova ny pentimpentina aminy? raha izany, dia mahavita manao ny tsara ianareo, izay nampiofanina hanao ratsy.'),
  ('6ab25b98603fec3ed368af3a', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 1, 'Izao no nolazain’i Jehovah tamiko: “Mandehana mividy fehikibo vita amin’ny lamba rongony, dia afatory eo amin’ny andilanao. Aza atao lenan’ny rano anefa ilay izy.”', 'izao no nolazain’i jehovah tamiko: “mandehana mividy fehikibo vita amin’ny lamba rongony, dia afatory eo amin’ny andilanao. aza atao lenan’ny rano anefa ilay izy.”'),
  ('6ab25b98603fec3ed368af40', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 7, 'Nankany amoron’i Eofrata àry aho ka nandavaka teo amin’ilay toerana nanafenako an’ilay fehikibo, dia nalaiko ilay izy. Ary hitako fa efa simba ilay fehikibo, sady tsy nisy nilana azy intsony!', 'nankany amoron’i eofrata àry aho ka nandavaka teo amin’ilay toerana nanafenako an’ilay fehikibo, dia nalaiko ilay izy. ary hitako fa efa simba ilay fehikibo, sady tsy nisy nilana azy intsony!'),
  ('6ab25b98603fec3ed368af51', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 24, 'Koa haparitako toy ny mololo entin’ny rivotra avy any an-tany efitra izy ireo.', 'koa haparitako toy ny mololo entin’ny rivotra avy any an-tany efitra izy ireo.'),
  ('6ab25b98603fec3ed368af4f', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 22, 'Ary hiteny ianao ao am-ponao ao hoe: ‘Fa maninona àry aho no tratran’izao?’ Satria lehibe ny fahadisoanao dia nesorina ny morontongotr’akanjonao, Ary noratraratraina ny voditongotrao.', 'ary hiteny ianao ao am-ponao ao hoe: ‘fa maninona àry aho no tratran’izao?’ satria lehibe ny fahadisoanao dia nesorina ny morontongotr’akanjonao, ary noratraratraina ny voditongotrao.'),
  ('6ab25b98603fec3ed368af47', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 14, 'Ary hataoko mifamotika izy ireo, na ny ray na ny zanany”, hoy i Jehovah. “Tsy hangoraka aho na halahelo na hamindra fo amin’izy ireo. Tsy hisy hahasakana ahy tsy handringana azy.”’', 'ary hataoko mifamotika izy ireo, na ny ray na ny zanany”, hoy i jehovah. “tsy hangoraka aho na halahelo na hamindra fo amin’izy ireo. tsy hisy hahasakana ahy tsy handringana azy.”’'),
  ('6ab25b98603fec3ed368af3c', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 3, 'Ary niteny tamiko fanindroany i Jehovah hoe:', 'ary niteny tamiko fanindroany i jehovah hoe:'),
  ('6ab25b98603fec3ed368af4d', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 20, 'Tazano ireo olona tonga avy any avaratra, ka jereo. Aiza ilay andian’ondry nomena anao, dia ireo ondry tsara tarehy?', 'tazano ireo olona tonga avy any avaratra, ka jereo. aiza ilay andian’ondry nomena anao, dia ireo ondry tsara tarehy?'),
  ('6ab25b98603fec3ed368af49', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 16, 'Omeo voninahitra i Jehovah Andriamanitrareo, Dieny mbola tsy mahatonga haizina izy Ary dieny mbola tsy tafintohina eny an-tendrombohitra ny tongotrareo rehefa maizimaizina ny andro. Hanantena hazavana ianareo, Kanjo hataony misy haizim-be, Ary hovany ho haizim-pito aza izany.', 'omeo voninahitra i jehovah andriamanitrareo, dieny mbola tsy mahatonga haizina izy ary dieny mbola tsy tafintohina eny an-tendrombohitra ny tongotrareo rehefa maizimaizina ny andro. hanantena hazavana ianareo, kanjo hataony misy haizim-be, ary hovany ho haizim-pito aza izany.'),
  ('6ab25b98603fec3ed368af3e', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 5, 'Dia lasa aho ka nafeniko teo amoron’i Eofrata ilay izy, araka izay nasain’i Jehovah nataoko.', 'dia lasa aho ka nafeniko teo amoron’i eofrata ilay izy, araka izay nasain’i jehovah nataoko.'),
  ('6ab25b98603fec3ed368af3d', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 4, '“Alaivo ilay fehikibo eny aminao, ilay novidinao, ary mitsangàna ka mandehana any amin’ny Reniranon’i Eofrata. Ary afeno any ilay izy, ao an-tsefatsefaky ny harambato.”', '“alaivo ilay fehikibo eny aminao, ilay novidinao, ary mitsangàna ka mandehana any amin’ny reniranon’i eofrata. ary afeno any ilay izy, ao an-tsefatsefaky ny harambato.”'),
  ('6ab25b98603fec3ed368af53', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 26, 'Dia hingaiko hatreny amin’ny tarehinao ny morontongotr’akanjonao, Ka ho hitan’ny olona ny faritra mahamenatra anao,', 'dia hingaiko hatreny amin’ny tarehinao ny morontongotr’akanjonao, ka ho hitan’ny olona ny faritra mahamenatra anao,'),
  ('6ab25b98603fec3ed368af48', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 15, 'Mihainoa ka aoka ianareo hanongilan-tsofina. Aza manambony tena, fa i Jehovah no miteny.', 'mihainoa ka aoka ianareo hanongilan-tsofina. aza manambony tena, fa i jehovah no miteny.'),
  ('6ab25b98603fec3ed368af4a', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 17, 'Raha tsy mety mihaino ianareo, Dia hitomany mangingina aho noho ny fireharehanareo. Hijoy ny ranomasoko, ary handrotsaka ranomaso ny masoko, Satria lasa babo ny andian’ondrin’i Jehovah.', 'raha tsy mety mihaino ianareo, dia hitomany mangingina aho noho ny fireharehanareo. hijoy ny ranomasoko, ary handrotsaka ranomaso ny masoko, satria lasa babo ny andian’ondrin’i jehovah.'),
  ('6ab25b98603fec3ed368af46', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 13, 'Koa izao avaly azy ireo: ‘Izao no lazain’i Jehovah: “Hataoko mamo ny mponina rehetra eto amin’ity tany ity, anisan’izany ireo mpanjaka mipetraka eo amin’ny seza fiandrianan’i Davida, ireo mpisorona sy mpaminany, ary ny mponina rehetra ao Jerosalema.', 'koa izao avaly azy ireo: ‘izao no lazain’i jehovah: “hataoko mamo ny mponina rehetra eto amin’ity tany ity, anisan’izany ireo mpanjaka mipetraka eo amin’ny seza fiandrianan’i davida, ireo mpisorona sy mpaminany, ary ny mponina rehetra ao jerosalema.'),
  ('6ab25b98603fec3ed368af44', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 11, '‘Fa toy ny fehikibo mifatotra amin’ny andilan’ny olona, dia nataoko nifamatotra tamiko koa ny taranak’Israely manontolo sy ny taranak’i Joda manontolo’, hoy i Jehovah. ‘Amin’izay izy ireo dia ho vahoakako sy ho voninahitro sy ho fiderana ahy ary ho ravaka ho ahy. Tsy nankatò anefa izy ireo.’', '‘fa toy ny fehikibo mifatotra amin’ny andilan’ny olona, dia nataoko nifamatotra tamiko koa ny taranak’israely manontolo sy ny taranak’i joda manontolo’, hoy i jehovah. ‘amin’izay izy ireo dia ho vahoakako sy ho voninahitro sy ho fiderana ahy ary ho ravaka ho ahy. tsy nankatò anefa izy ireo.’'),
  ('6ab25b98603fec3ed368af4e', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 21, 'Inona no holazainao rehefa manasazy anao Ny olona noraisinao ho namana akaiky hatramin’izay? Tsy hanaintaina mafy hoatran’ny vehivavy efa ho teraka ve ianao?', 'inona no holazainao rehefa manasazy anao ny olona noraisinao ho namana akaiky hatramin’izay? tsy hanaintaina mafy hoatran’ny vehivavy efa ho teraka ve ianao?'),
  ('6ab25b98603fec3ed368af54', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 27, 'Ny fanitsakitsahanao ny vadinao, ny filanao lehilahy, Ary ny zavatra vetaveta ataonao rehefa mivaro-tena. Hitako ny zava-maharikoriko ataonao Eny amin’ny havoana sy eny an-tsaha. Hahita loza ianao, ry Jerosalema ô! Mandra-pahoviana ianao no tsy hadio?”', 'ny fanitsakitsahanao ny vadinao, ny filanao lehilahy, ary ny zavatra vetaveta ataonao rehefa mivaro-tena. hitako ny zava-maharikoriko ataonao eny amin’ny havoana sy eny an-tsaha. hahita loza ianao, ry jerosalema ô! mandra-pahoviana ianao no tsy hadio?”'),
  ('6ab25b98603fec3ed368af4c', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 19, 'Nakatona ireo tanàna any atsimo ka tsy misy mamoha. Natao sesitany ny fokon’i Joda manontolo. Natao sesitany daholo izy ireo.', 'nakatona ireo tanàna any atsimo ka tsy misy mamoha. natao sesitany ny fokon’i joda manontolo. natao sesitany daholo izy ireo.'),
  ('6ab25b98603fec3ed368af41', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 8, 'Dia niteny tamiko i Jehovah hoe:', 'dia niteny tamiko i jehovah hoe:'),
  ('6ab25b98603fec3ed368af3b', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 2, 'Dia novidiko ilay fehikibo, araka ny tenin’i Jehovah, ka nafatotro teo amin’ny andilako.', 'dia novidiko ilay fehikibo, araka ny tenin’i jehovah, ka nafatotro teo amin’ny andilako.'),
  ('6ab25b98603fec3ed368af52', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 25, 'Izany no anjaranao, dia ilay anjara norefesiko ho anao”, hoy i Jehovah, “Satria nanadino ahy ianao ary lainga no atokisanao.', 'izany no anjaranao, dia ilay anjara norefesiko ho anao”, hoy i jehovah, “satria nanadino ahy ianao ary lainga no atokisanao.'),
  ('6ab25b98603fec3ed368af45', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 12, '“Ampitao aminy koa izao hafatra izao: ‘Izao no lazain’i Jehovah Andriamanitry ny Israely: “Tokony hofenoina divay ny siny lehibe rehetra.”’ Dia hamaly anao izy ireo hoe: ‘Fa angaha moa tsy efa fantatray hoe tokony hofenoina divay ny siny lehibe rehetra?’', '“ampitao aminy koa izao hafatra izao: ‘izao no lazain’i jehovah andriamanitry ny israely: “tokony hofenoina divay ny siny lehibe rehetra.”’ dia hamaly anao izy ireo hoe: ‘fa angaha moa tsy efa fantatray hoe tokony hofenoina divay ny siny lehibe rehetra?’'),
  ('6ab25b98603fec3ed368af42', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 9, '“Izao no lazain’i Jehovah: ‘Hosimbako toy izany koa ny fireharehan’i Joda sy ny haben’ny fireharehan’i Jerosalema.', '“izao no lazain’i jehovah: ‘hosimbako toy izany koa ny fireharehan’i joda sy ny haben’ny fireharehan’i jerosalema.'),
  ('6ab25b98603fec3ed368af3f', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 6, 'Niteny tamiko anefa i Jehovah rehefa afaka andro maro hoe: “Mitsangàna ka mandehana any amin’ny Reniranon’i Eofrata, ary alaivo ilay fehikibo nasaiko nafeninao any.”', 'niteny tamiko anefa i jehovah rehefa afaka andro maro hoe: “mitsangàna ka mandehana any amin’ny reniranon’i eofrata, ary alaivo ilay fehikibo nasaiko nafeninao any.”'),
  ('6ab25b98603fec3ed368af43', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 10, 'Ho lasa hoatran’io fehikibo tsy misy ilana azy io koa ity vahoaka ratsy toetra ity, izay tsy mety mankatò ny teniko, sy mikiry manao izay tian’ny fony, ary manaraka andriamani-kafa ka manompo azy ireny sy miankohoka aminy.’', 'ho lasa hoatran’io fehikibo tsy misy ilana azy io koa ity vahoaka ratsy toetra ity, izay tsy mety mankatò ny teniko, sy mikiry manao izay tian’ny fony, ary manaraka andriamani-kafa ka manompo azy ireny sy miankohoka aminy.’'),
  ('6ab25b98603fec3ed368af4b', '2026-09-22T10:42:32.807Z', '2026-09-22T10:42:32.807Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 13, 18, 'Lazao amin’ny mpanjaka sy ny renin’ny mpanjaka hoe: ‘Mipetraha ambany, Satria ho latsaka avy eny an-dohanareo ny satroboninahitrareo tsara tarehy.’', 'lazao amin’ny mpanjaka sy ny renin’ny mpanjaka hoe: ‘mipetraha ambany, satria ho latsaka avy eny an-dohanareo ny satroboninahitrareo tsara tarehy.’'),
  ('6ab25b99d3ce9ad270097720', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 8, 'Ry fanantenan’ny Israely ô! Ry Mpamonjy azy amin’ny fotoam-pahoriana, Nahoana no dia toy ny vahiny eto amin’ity tany ity ianao, Ary toy ny mpanao dia lavitra mijanona eto indray alina monja?', 'ry fanantenan’ny israely ô! ry mpamonjy azy amin’ny fotoam-pahoriana, nahoana no dia toy ny vahiny eto amin’ity tany ity ianao, ary toy ny mpanao dia lavitra mijanona eto indray alina monja?'),
  ('6ab25b99d3ce9ad27009771c', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 4, 'Kivy ny mpamboly ka saronany ny lohany, Fa mitresatresaka ny tany Satria tsy misy orana milatsaka eo aminy.', 'kivy ny mpamboly ka saronany ny lohany, fa mitresatresaka ny tany satria tsy misy orana milatsaka eo aminy.'),
  ('6ab25b99d3ce9ad270097723', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 11, 'Dia hoy i Jehovah tamiko: “Aza mangataka zavatra tsara ho an’ity vahoaka ity, rehefa mivavaka amiko.', 'dia hoy i jehovah tamiko: “aza mangataka zavatra tsara ho an’ity vahoaka ity, rehefa mivavaka amiko.'),
  ('6ab25b99d3ce9ad270097725', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 13, 'Dia hoy aho: “Indrisy, Jehovah Tompo Fara Tampony ô! Izao no lazain’ny mpaminany amin’izy ireo: ‘Tsy hahita ady ianareo, ary tsy ho tratran’ny mosary, fa hataoko izay tena hiadananareo eto amin’ity toerana ity.’”', 'dia hoy aho: “indrisy, jehovah tompo fara tampony ô! izao no lazain’ny mpaminany amin’izy ireo: ‘tsy hahita ady ianareo, ary tsy ho tratran’ny mosary, fa hataoko izay tena hiadananareo eto amin’ity toerana ity.’”'),
  ('6ab25b99d3ce9ad27009771f', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 7, 'Na dia miampanga anay aza ny fahadisoanay, Dia mba manaova zavatra noho ny anaranao, Jehovah ô! Fa efa imbetsaka izahay no nivadika taminao, Ary taminao izahay no nanota.', 'na dia miampanga anay aza ny fahadisoanay, dia mba manaova zavatra noho ny anaranao, jehovah ô! fa efa imbetsaka izahay no nivadika taminao, ary taminao izahay no nanota.'),
  ('6ab25b99d3ce9ad27009771d', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 5, 'Na ny serfavavy eny an-tsaha aza mandao ny zanany vao teraka, Satria tsy misy ahi-maitso.', 'na ny serfavavy eny an-tsaha aza mandao ny zanany vao teraka, satria tsy misy ahi-maitso.'),
  ('6ab25b99d3ce9ad27009771e', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 6, 'Mijanona eny amin’ny havoana mangadihady ny ampondradia. Misefosefo toy ny alikadia izy. Reraka ny masony satria tsy misy zavamaniry.', 'mijanona eny amin’ny havoana mangadihady ny ampondradia. misefosefo toy ny alikadia izy. reraka ny masony satria tsy misy zavamaniry.'),
  ('6ab25b99d3ce9ad270097719', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 1, 'Izao no tenin’i Jehovah tamin’i Jeremia, momba ny hain-tany:', 'izao no tenin’i jehovah tamin’i jeremia, momba ny hain-tany:'),
  ('6ab25b99d3ce9ad270097728', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 16, 'Ary hatsipy eny amin’ny lalan’i Jerosalema ny fatin’ny olona izay nilazany ny faminaniany, satria ho fatin’ny mosary sy ny sabatra izy ireny. Tsy hisy handevina ny fatin’izy ireny sy ny fatin’ny vadiny sy ny zanany lahy ary ny zanany vavy. Fa hataoko mihatra aminy ny loza sahaza azy.’', 'ary hatsipy eny amin’ny lalan’i jerosalema ny fatin’ny olona izay nilazany ny faminaniany, satria ho fatin’ny mosary sy ny sabatra izy ireny. tsy hisy handevina ny fatin’izy ireny sy ny fatin’ny vadiny sy ny zanany lahy ary ny zanany vavy. fa hataoko mihatra aminy ny loza sahaza azy.’'),
  ('6ab25b99d3ce9ad270097721', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 9, 'Nahoana ianao no hoatran’ny olona very hevitra, Sy hoatran’ny lehilahy matanjaka tsy afaka mamonjy? Fa ianao no eo aminay, Jehovah ô, Ary mitondra ny anaranao izahay. Aza dia afoy re izahay e!', 'nahoana ianao no hoatran’ny olona very hevitra, sy hoatran’ny lehilahy matanjaka tsy afaka mamonjy? fa ianao no eo aminay, jehovah ô, ary mitondra ny anaranao izahay. aza dia afoy re izahay e!'),
  ('6ab25b99d3ce9ad27009771a', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 2, 'Misaona i Joda, ary mihasimba ireo vavahadiny. Manjombona izy ireo sady midaboka amin’ny tany. Miakatra avy ao Jerosalema ny fitarainana.', 'misaona i joda, ary mihasimba ireo vavahadiny. manjombona izy ireo sady midaboka amin’ny tany. miakatra avy ao jerosalema ny fitarainana.'),
  ('6ab25b99d3ce9ad270097726', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 14, 'Dia niteny tamiko i Jehovah hoe: “Maminany lainga amin’ny anarako ireo mpaminany ireo. Tsy naniraka azy ireo aho na nanome didy azy na niresaka taminy. Tsy marina ny fahitana azony, tsy misy dikany ny sikidy ataony, ary fitaka foromporonin’ny sainy ny faminaniana resahiny aminareo.', 'dia niteny tamiko i jehovah hoe: “maminany lainga amin’ny anarako ireo mpaminany ireo. tsy naniraka azy ireo aho na nanome didy azy na niresaka taminy. tsy marina ny fahitana azony, tsy misy dikany ny sikidy ataony, ary fitaka foromporonin’ny sainy ny faminaniana resahiny aminareo.'),
  ('6ab25b99d3ce9ad270097724', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 12, 'Tsy mihaino ny fitarainany aho na dia mifady hanina aza izy. Ary na manolotra fanatitra dorana manontolo sy fanatitra varimbazaha aza izy, dia tsy mankasitraka an’izany aho. Fa horinganiko amin’ny sabatra sy ny mosary ary ny areti-mandringana izy ireo.”', 'tsy mihaino ny fitarainany aho na dia mifady hanina aza izy. ary na manolotra fanatitra dorana manontolo sy fanatitra varimbazaha aza izy, dia tsy mankasitraka an’izany aho. fa horinganiko amin’ny sabatra sy ny mosary ary ny areti-mandringana izy ireo.”'),
  ('6ab25b99d3ce9ad270097729', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 17, '“Lazao amin’izy ireo izao teny izao: ‘Aoka hirotsaka andro aman’alina ny ranomasoko ka tsy hijanona mihitsy, Fa voa mafy ny virjiny zanakavavin’ny fireneko noho ny vono nahazo azy, Ary tena maratra be izy.', '“lazao amin’izy ireo izao teny izao: ‘aoka hirotsaka andro aman’alina ny ranomasoko ka tsy hijanona mihitsy, fa voa mafy ny virjiny zanakavavin’ny fireneko noho ny vono nahazo azy, ary tena maratra be izy.'),
  ('6ab25b99d3ce9ad270097727', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 15, 'Maminany amin’ny anarako ireo mpaminany ireo, nefa tsy nirahiko. Milaza izy ireo fa tsy hisy sabatra na mosary hamely an’ity tany ity. Koa izao no lazain’i Jehovah momba azy ireo: ‘Ho fatin’ny sabatra sy ny mosary ireo mpaminany ireo.', 'maminany amin’ny anarako ireo mpaminany ireo, nefa tsy nirahiko. milaza izy ireo fa tsy hisy sabatra na mosary hamely an’ity tany ity. koa izao no lazain’i jehovah momba azy ireo: ‘ho fatin’ny sabatra sy ny mosary ireo mpaminany ireo.'),
  ('6ab25b99d3ce9ad270097722', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 10, 'Izao no lazain’i Jehovah momba an’ity vahoaka ity: “Tia mirenireny izy ireo ka tsy voafehiny ny tongony. Tsy ankasitrahan’i Jehovah àry izy ireo. Koa hotsaroany ny fahadisoan’izy ireo, ary hataony ampamoaka izy noho ny fahotany.”', 'izao no lazain’i jehovah momba an’ity vahoaka ity: “tia mirenireny izy ireo ka tsy voafehiny ny tongony. tsy ankasitrahan’i jehovah àry izy ireo. koa hotsaroany ny fahadisoan’izy ireo, ary hataony ampamoaka izy noho ny fahotany.”'),
  ('6ab25b99d3ce9ad27009771b', '2026-09-22T10:42:33.250Z', '2026-09-22T10:42:33.250Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 3, 'Irahin’ny tompony hantsaka rano ny mpanompony. Dia mankany amin’ny lavadrano izy ireny nefa tsy mahita rano, Ka miverim-potsiny miaraka amin’ny sininy. Menatra sy diso fanantenana izy ireny, Ka saronany ny lohany.', 'irahin’ny tompony hantsaka rano ny mpanompony. dia mankany amin’ny lavadrano izy ireny nefa tsy mahita rano, ka miverim-potsiny miaraka amin’ny sininy. menatra sy diso fanantenana izy ireny, ka saronany ny lohany.'),
  ('6ab25b99d3ce9ad27009772d', '2026-09-22T10:42:33.251Z', '2026-09-22T10:42:33.251Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 21, 'Aza ailikilika izahay noho ny anaranao. Aza hamavoina ny seza fiandriananao be voninahitra. Mba tsarovy re ny fifanekena nataonao taminay e, ary aza mivadika amin’izany!', 'aza ailikilika izahay noho ny anaranao. aza hamavoina ny seza fiandriananao be voninahitra. mba tsarovy re ny fifanekena nataonao taminay e, ary aza mivadika amin’izany!'),
  ('6ab25b99d3ce9ad27009772a', '2026-09-22T10:42:33.251Z', '2026-09-22T10:42:33.251Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 18, 'Rehefa mivoaka mankeny an-tsaha aho, Dia ireo matin’ny sabatra no hitako! Ary rehefa miditra ao an-tanàna aho, Dia ireo marary vokatry ny mosary no hitako! Fa samy mirenireny any amin’ny tany tsy fantany ny mpaminany sy ny mpisorona.’”', 'rehefa mivoaka mankeny an-tsaha aho, dia ireo matin’ny sabatra no hitako! ary rehefa miditra ao an-tanàna aho, dia ireo marary vokatry ny mosary no hitako! fa samy mirenireny any amin’ny tany tsy fantany ny mpaminany sy ny mpisorona.’”'),
  ('6ab25b99d3ce9ad27009772e', '2026-09-22T10:42:33.251Z', '2026-09-22T10:42:33.251Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 22, 'Misy mahavita mandatsaka orana ve ireo sampy tsy misy dikany tompoin’ireo firenena, Na mahavita mandrotsaka oram-be ve raha ny lanitra fotsiny? Tsy Ianao irery ihany ve no mahavita an’izany, ry Jehovah Andriamanitray ô? Koa ianao no antenainay, Satria ianao ihany no manao an’izany rehetra izany.', 'misy mahavita mandatsaka orana ve ireo sampy tsy misy dikany tompoin’ireo firenena, na mahavita mandrotsaka oram-be ve raha ny lanitra fotsiny? tsy ianao irery ihany ve no mahavita an’izany, ry jehovah andriamanitray ô? koa ianao no antenainay, satria ianao ihany no manao an’izany rehetra izany.'),
  ('6ab25b99d3ce9ad27009772b', '2026-09-22T10:42:33.251Z', '2026-09-22T10:42:33.251Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 19, 'Efa nolavinao tanteraka ve i Joda? Efa nankahalainao ve i Ziona? Nahoana no nokapohinao izahay ka tsy mety sitrana intsony? Nanantena fiadanana izahay, kanjo tsy nisy zavatra tsara nitranga. Nanantena fotoam-panasitranana izahay, kanjo horohoro no niseho!', 'efa nolavinao tanteraka ve i joda? efa nankahalainao ve i ziona? nahoana no nokapohinao izahay ka tsy mety sitrana intsony? nanantena fiadanana izahay, kanjo tsy nisy zavatra tsara nitranga. nanantena fotoam-panasitranana izahay, kanjo horohoro no niseho!'),
  ('6ab25b99d3ce9ad27009772c', '2026-09-22T10:42:33.251Z', '2026-09-22T10:42:33.251Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 14, 20, 'Jehovah ô, miaiky ny ratsy vitanay Sy ny fahadisoana nataon’ny razambenay izahay. Fa nanota taminao izahay.', 'jehovah ô, miaiky ny ratsy vitanay sy ny fahadisoana nataon’ny razambenay izahay. fa nanota taminao izahay.'),
  ('6ab25b99adc09186b5e37c10', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 15, 'Fantatrao ny manjo ahy, Jehovah ô! Mba tsarovy aho, ka tsinjovy. Valio ny mpanenjika ahy noho izay nataony tamiko. Aza avela ho fatiny aho noho ianao tsy mora tezitra. Fantaro fa noho ny aminao no mahatonga ahy hisy handatsa hoatr’izao.', 'fantatrao ny manjo ahy, jehovah ô! mba tsarovy aho, ka tsinjovy. valio ny mpanenjika ahy noho izay nataony tamiko. aza avela ho fatiny aho noho ianao tsy mora tezitra. fantaro fa noho ny aminao no mahatonga ahy hisy handatsa hoatr’izao.'),
  ('6ab25b99adc09186b5e37c02', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 1, 'Dia hoy i Jehovah tamiko: “Na nijoro teto anatrehako aza i Mosesy sy Samoela, dia tsy ho namindra fo tamin’ity vahoaka ity aho. Roahy hiala eto anatrehako izy ireo. Asaivo mandeha ry zareo.', 'dia hoy i jehovah tamiko: “na nijoro teto anatrehako aza i mosesy sy samoela, dia tsy ho namindra fo tamin’ity vahoaka ity aho. roahy hiala eto anatrehako izy ireo. asaivo mandeha ry zareo.'),
  ('6ab25b99adc09186b5e37c03', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 2, 'Ary raha manontany anao izy ireo hoe: ‘Handeha ho aiza izahay?’, dia izao avaly azy: ‘Izao no lazain’i Jehovah: “Ho tratran’ny loza mahafaty izay natao ho tratran’ny loza mahafaty! Ho fatin’ny sabatra izay natao ho fatin’ny sabatra! Ho fatin’ny mosary izay natao ho fatin’ny mosary! Ary ho lasa babo izay natao ho lasa babo!”’', 'ary raha manontany anao izy ireo hoe: ‘handeha ho aiza izahay?’, dia izao avaly azy: ‘izao no lazain’i jehovah: “ho tratran’ny loza mahafaty izay natao ho tratran’ny loza mahafaty! ho fatin’ny sabatra izay natao ho fatin’ny sabatra! ho fatin’ny mosary izay natao ho fatin’ny mosary! ary ho lasa babo izay natao ho lasa babo!”’'),
  ('6ab25b99adc09186b5e37c13', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 18, 'Nahoana no manaintaina foana aho, ary tsy misy fanafany ny ratrako? Tsy mety sitrana ilay izy. Ho lasa toy ny tahirin-drano mamitaka ve ianao, Ka tsy ho azo itokisana?', 'nahoana no manaintaina foana aho, ary tsy misy fanafany ny ratrako? tsy mety sitrana ilay izy. ho lasa toy ny tahirin-drano mamitaka ve ianao, ka tsy ho azo itokisana?'),
  ('6ab25b99adc09186b5e37c12', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 17, 'Tsy miara-mipetraka amin’ireo tia mifety aho, ary tsy mba mifalifaly. Mipetraka irery aho satria mitarika ahy ny tananao, Fa nataonao lasa tezitra be aho.', 'tsy miara-mipetraka amin’ireo tia mifety aho, ary tsy mba mifalifaly. mipetraka irery aho satria mitarika ahy ny tananao, fa nataonao lasa tezitra be aho.'),
  ('6ab25b99adc09186b5e37c0e', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 13, 'Homeko ho an’ny mpandroba ny fanananao sy ny harenanao. Homeko maimaim-poana izany noho ny fahotana rehetra nataonao nanerana ny taninao.', 'homeko ho an’ny mpandroba ny fanananao sy ny harenanao. homeko maimaim-poana izany noho ny fahotana rehetra nataonao nanerana ny taninao.'),
  ('6ab25b99adc09186b5e37c0c', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 11, 'Dia hoy i Jehovah: “Tena hanampy anao aho. Hifampiraharaha amin’ny fahavalo tokoa aho mba ho voaro ianao, Amin’ny fotoanan’ny loza sy amin’ny fotoana mahory.', 'dia hoy i jehovah: “tena hanampy anao aho. hifampiraharaha amin’ny fahavalo tokoa aho mba ho voaro ianao, amin’ny fotoanan’ny loza sy amin’ny fotoana mahory.'),
  ('6ab25b99adc09186b5e37c0a', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 9, 'Mihareraka ny vehivavy niteraka fito, Ary sempotsempotra be. Milentika ny masoandrony na dia mbola antoandro aza ny andro, Ka mahatonga henatra sy fahafaham-baraka.’ ‘Ary ny sisa amin’izy ireo Hatolotro ho fatin’ny sabatry ny fahavalony’, hoy i Jehovah.”', 'mihareraka ny vehivavy niteraka fito, ary sempotsempotra be. milentika ny masoandrony na dia mbola antoandro aza ny andro, ka mahatonga henatra sy fahafaham-baraka.’ ‘ary ny sisa amin’izy ireo hatolotro ho fatin’ny sabatry ny fahavalony’, hoy i jehovah.”'),
  ('6ab25b99adc09186b5e37c0d', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 12, 'Misy mahapotipotika vy ve, Dia ny vy avy any avaratra? Ary misy mahapotipotika varahina ve?', 'misy mahapotipotika vy ve, dia ny vy avy any avaratra? ary misy mahapotipotika varahina ve?'),
  ('6ab25b99adc09186b5e37c0b', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 10, 'Idiran-doza aho, ry Neny, fa niteraka ahy ianao. Mila vaniny amiko sy mila ady amiko daholo ny olona rehetra eto amin’ity tany ity. Tsy mba nampisambo-bola aho na nindram-bola, Nefa manozona ahy izy rehetra.', 'idiran-doza aho, ry neny, fa niteraka ahy ianao. mila vaniny amiko sy mila ady amiko daholo ny olona rehetra eto amin’ity tany ity. tsy mba nampisambo-bola aho na nindram-bola, nefa manozona ahy izy rehetra.'),
  ('6ab25b99adc09186b5e37c09', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 8, 'Ho lasa maro noho ny fasika eny an-dranomasina ny maty vady. Hitondra mpandrava hanafika azy ireo aho amin’ny mitataovovonana, ka hotafihiny ny reny sy ny tovolahy. Hataoko mivadi-po sy mivarahontsana tampoka izy ireo.', 'ho lasa maro noho ny fasika eny an-dranomasina ny maty vady. hitondra mpandrava hanafika azy ireo aho amin’ny mitataovovonana, ka hotafihiny ny reny sy ny tovolahy. hataoko mivadi-po sy mivarahontsana tampoka izy ireo.'),
  ('6ab25b99adc09186b5e37c07', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 6, '‘Nahafoy ahy ianao’, hoy i Jehovah. ‘Tsy mitsahatra manome lamosina ahy ianao. Koa hanatsotra ny tanako hamely anao aho, ka handringana anao. Efa reraky ny miantra anao aho.', '‘nahafoy ahy ianao’, hoy i jehovah. ‘tsy mitsahatra manome lamosina ahy ianao. koa hanatsotra ny tanako hamely anao aho, ka handringana anao. efa reraky ny miantra anao aho.'),
  ('6ab25b99adc09186b5e37c05', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 4, 'Hataoko mihorohoro ny fanjakana rehetra eto an-tany mahita an’izay hanjo azy, noho izay nataon’i Manase zanak’i Hezekia, mpanjakan’ny Joda, tao Jerosalema.', 'hataoko mihorohoro ny fanjakana rehetra eto an-tany mahita an’izay hanjo azy, noho izay nataon’i manase zanak’i hezekia, mpanjakan’ny joda, tao jerosalema.'),
  ('6ab25b99adc09186b5e37c11', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 16, 'Hitako ny teninao ka nohaniko. Ary naharavoravo ahy ny teninao sady nahafaly ny foko. Fa mitondra ny anaranao aho, ry Jehovah Andriamanitry ny tafika ô!', 'hitako ny teninao ka nohaniko. ary naharavoravo ahy ny teninao sady nahafaly ny foko. fa mitondra ny anaranao aho, ry jehovah andriamanitry ny tafika ô!'),
  ('6ab25b99adc09186b5e37c04', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 3, '“‘Handefa loza efatra aho hamelezana azy ireo’, hoy i Jehovah: ‘Sabatra hamono azy, alika hitaritarika azy, ary voro-manidina sy bibidia handrapaka sy hamotika azy.', '“‘handefa loza efatra aho hamelezana azy ireo’, hoy i jehovah: ‘sabatra hamono azy, alika hitaritarika azy, ary voro-manidina sy bibidia handrapaka sy hamotika azy.'),
  ('6ab25b99adc09186b5e37c16', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 21, '“Hamonjy anao eo an-tanan’ny ratsy fanahy aho, Ary hanavotra anao eo am-pelatanan’ny olona tsy mifaditrovana.”', '“hamonjy anao eo an-tanan’ny ratsy fanahy aho, ary hanavotra anao eo am-pelatanan’ny olona tsy mifaditrovana.”'),
  ('6ab25b99adc09186b5e37c0f', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 14, 'Homeko ny fahavalonao ireny, Mba hoentiny any amin’ny tany tsy fantatrao. Fa nandrehitra afo ny fahatezerako, Ka mandoro anareo izany!”', 'homeko ny fahavalonao ireny, mba hoentiny any amin’ny tany tsy fantatrao. fa nandrehitra afo ny fahatezerako, ka mandoro anareo izany!”'),
  ('6ab25b99adc09186b5e37c15', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 20, '“Ataoko toy ny manda varahina voaro mafy ianao ho an’ity vahoaka ity. Tsy maintsy hiady aminao izy ireo, Nefa tsy haharesy anao, Satria ho eo foana aho, mba hamonjy sy hanafaka anao”, hoy i Jehovah.', '“ataoko toy ny manda varahina voaro mafy ianao ho an’ity vahoaka ity. tsy maintsy hiady aminao izy ireo, nefa tsy haharesy anao, satria ho eo foana aho, mba hamonjy sy hanafaka anao”, hoy i jehovah.'),
  ('6ab25b99adc09186b5e37c06', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 5, 'Iza no mba hiantra anao, ry Jerosalema ô? Iza no mba hangoraka anao, Ary iza no mba hijanona hanontany hoe manahoana ianao?’', 'iza no mba hiantra anao, ry jerosalema ô? iza no mba hangoraka anao, ary iza no mba hijanona hanontany hoe manahoana ianao?’'),
  ('6ab25b99adc09186b5e37c14', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 19, 'Koa izao no lazain’i Jehovah: “Raha miverina amiko ianao, dia horaisiko indray, Ka hitsangana eto anatrehako. Raha manavaka an’izay sarobidy amin’izay tsy misy dikany ianao, Dia ho lasa mpitondra teniko. Tsy maintsy hiverina aminao ny vahoaka, Fa ianao kosa tsy hiverina aminy.”', 'koa izao no lazain’i jehovah: “raha miverina amiko ianao, dia horaisiko indray, ka hitsangana eto anatrehako. raha manavaka an’izay sarobidy amin’izay tsy misy dikany ianao, dia ho lasa mpitondra teniko. tsy maintsy hiverina aminao ny vahoaka, fa ianao kosa tsy hiverina aminy.”'),
  ('6ab25b99adc09186b5e37c08', '2026-09-22T10:42:33.814Z', '2026-09-22T10:42:33.814Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 15, 7, 'Ary hokororohiko amin’ny fikororohana izy ireo, eo amin’ireo vavahady ao amin’ilay tany. Haripako ny zanany. Haringako ny vahoakako, Satria tsy mety miala amin’ny fanaony.', 'ary hokororohiko amin’ny fikororohana izy ireo, eo amin’ireo vavahady ao amin’ilay tany. haripako ny zanany. haringako ny vahoakako, satria tsy mety miala amin’ny fanaony.'),
  ('6ab25b9a23d0816c7d466e23', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 17, 'Fa hitan’ny masoko daholo izay ataon’izy ireo. Tsy misy miafina eo anatrehako izy ireo, Ary miharihary eo imasoko ny fahadisoany.', 'fa hitan’ny masoko daholo izay ataon’izy ireo. tsy misy miafina eo anatrehako izy ireo, ary miharihary eo imasoko ny fahadisoany.'),
  ('6ab25b9a23d0816c7d466e1c', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 10, '“Rehefa lazainao amin’ity vahoaka ity izany rehetra izany, dia hanontany anao izy hoe: ‘Fa maninona i Jehovah no nilaza fa hamely anay amin’izany loza amin’antambo rehetra izany? Fa inona no fahadisoana sy fahotana vitanay tamin’i Jehovah Andriamanitray?’', '“rehefa lazainao amin’ity vahoaka ity izany rehetra izany, dia hanontany anao izy hoe: ‘fa maninona i jehovah no nilaza fa hamely anay amin’izany loza amin’antambo rehetra izany? fa inona no fahadisoana sy fahotana vitanay tamin’i jehovah andriamanitray?’'),
  ('6ab25b9a23d0816c7d466e1a', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 8, 'Ary aza miditra ao amin’ny trano misy fanasana, Mba hiara-mipetraka hihinana sy hisotro amin’izy ireo.’', 'ary aza miditra ao amin’ny trano misy fanasana, mba hiara-mipetraka hihinana sy hisotro amin’izy ireo.’'),
  ('6ab25b9a23d0816c7d466e16', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 4, '‘Ho fatin’ny aretina mahafaty izy ireny, nefa tsy hisy hisaona na handevina azy. Ho lasa zezika eny ambonin’ny tany izy ireny. Ho fatin’ny sabatra sy ny mosary izy ireny, ary ho sakafon’ny voro-manidina sy ny bibidia ny fatiny.’', '‘ho fatin’ny aretina mahafaty izy ireny, nefa tsy hisy hisaona na handevina azy. ho lasa zezika eny ambonin’ny tany izy ireny. ho fatin’ny sabatra sy ny mosary izy ireny, ary ho sakafon’ny voro-manidina sy ny bibidia ny fatiny.’'),
  ('6ab25b9a23d0816c7d466e20', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 14, '“‘Ho avy anefa ny andro’, hoy i Jehovah, ‘izay tsy hilazana intsony hoe: “Raha mbola velona koa i Jehovah, ilay namoaka ny vahoakan’Israely avy tany Ejipta!”', '“‘ho avy anefa ny andro’, hoy i jehovah, ‘izay tsy hilazana intsony hoe: “raha mbola velona koa i jehovah, ilay namoaka ny vahoakan’israely avy tany ejipta!”'),
  ('6ab25b9a23d0816c7d466e17', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 5, 'Fa izao no lazain’i Jehovah: ‘Aza miditra ao amin’ny trano misy sakafo be, izay aroso rehefa misy fahoriana, Ary aza mankany mba hidradradradra na hitsapa alahelo.’ ‘Efa nesoriko tsy ho amin’ity vahoaka ity mantsy ny fiadanako’, hoy i Jehovah, ‘Ary tsy ho tsara fanahy aminy aho sady tsy hamindra fo aminy.', 'fa izao no lazain’i jehovah: ‘aza miditra ao amin’ny trano misy sakafo be, izay aroso rehefa misy fahoriana, ary aza mankany mba hidradradradra na hitsapa alahelo.’ ‘efa nesoriko tsy ho amin’ity vahoaka ity mantsy ny fiadanako’, hoy i jehovah, ‘ary tsy ho tsara fanahy aminy aho sady tsy hamindra fo aminy.'),
  ('6ab25b9a23d0816c7d466e14', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 2, '“Aza manambady na manana zanakalahy sy zanakavavy eto amin’ity toerana ity.', '“aza manambady na manana zanakalahy sy zanakavavy eto amin’ity toerana ity.'),
  ('6ab25b9a23d0816c7d466e27', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 21, '“Koa hataoko fantany Ny heriko sy ny tanjako amin’ity indray mandeha ity. Hasehoko azy ireo izany, Ka tsy maintsy ho fantany fa Jehovah no anarako.”', '“koa hataoko fantany ny heriko sy ny tanjako amin’ity indray mandeha ity. hasehoko azy ireo izany, ka tsy maintsy ho fantany fa jehovah no anarako.”'),
  ('6ab25b9a23d0816c7d466e26', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 20, 'Mahavita manao andriamanitra hivavahany ve ny olombelona? Tsy tena andriamanitra no vitany.', 'mahavita manao andriamanitra hivavahany ve ny olombelona? tsy tena andriamanitra no vitany.'),
  ('6ab25b9a23d0816c7d466e1f', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 13, 'Koa hatsipiko hiala eto amin’ity tany ity ianareo, ka halefako any amin’ny tany tsy fantatrareo na ny razambenareo. Any ianareo no hanompo andriamani-kafa andro aman’alina, satria tsy hamindra fo aminareo aho.”’', 'koa hatsipiko hiala eto amin’ity tany ity ianareo, ka halefako any amin’ny tany tsy fantatrareo na ny razambenareo. any ianareo no hanompo andriamani-kafa andro aman’alina, satria tsy hamindra fo aminareo aho.”’'),
  ('6ab25b9a23d0816c7d466e22', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 16, '‘Haniraka mpanjono maro aho’, hoy i Jehovah, ‘Mba hanjono azy ireo. Haniraka mpihaza be dia be aho avy eo, Mba hihaza azy eny amin’ny tendrombohitra sy havoana rehetra Ary eny an-tsefatsefaky ny harambato.', '‘haniraka mpanjono maro aho’, hoy i jehovah, ‘mba hanjono azy ireo. haniraka mpihaza be dia be aho avy eo, mba hihaza azy eny amin’ny tendrombohitra sy havoana rehetra ary eny an-tsefatsefaky ny harambato.'),
  ('6ab25b9a23d0816c7d466e15', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 3, 'Izao mantsy no lazain’i Jehovah momba an’ireo zanakalahy sy zanakavavy teraka eto, sy momba ny ray sy ny reny niteraka azy teto amin’ity tany ity:', 'izao mantsy no lazain’i jehovah momba an’ireo zanakalahy sy zanakavavy teraka eto, sy momba ny ray sy ny reny niteraka azy teto amin’ity tany ity:'),
  ('6ab25b9a23d0816c7d466e24', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 18, 'Voalohany aloha, dia hosaziko araka izay sahaza azy izy ireo noho ny fahadisoany sy ny fahotany. Fa nolotoiny tamin’ny fatin’ireo sampiny maharikoriko ny taniko, Ary nofenoiny zava-maharikoriko ny lovako.’”', 'voalohany aloha, dia hosaziko araka izay sahaza azy izy ireo noho ny fahadisoany sy ny fahotany. fa nolotoiny tamin’ny fatin’ireo sampiny maharikoriko ny taniko, ary nofenoiny zava-maharikoriko ny lovako.’”'),
  ('6ab25b9a23d0816c7d466e21', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 15, 'Fa izao kosa no holazaina: “Raha mbola velona koa i Jehovah, ilay namoaka ny vahoakan’Israely avy tany amin’ilay tany any avaratra, sy avy tany amin’ny toerana rehetra nanaparitahany azy!” Hampodiko ao amin’ny taniny izy ireo, dia ilay tany nomeko ny razambeny.’', 'fa izao kosa no holazaina: “raha mbola velona koa i jehovah, ilay namoaka ny vahoakan’israely avy tany amin’ilay tany any avaratra, sy avy tany amin’ny toerana rehetra nanaparitahany azy!” hampodiko ao amin’ny taniny izy ireo, dia ilay tany nomeko ny razambeny.’'),
  ('6ab25b9a23d0816c7d466e18', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 6, '‘Ho faty eto amin’ity tany ity izy ireo, na ny lehibe na ny madinika. Tsy halevina izy ireo, Ary tsy hisy olona hisaona azy Na handidididy vatana na hanasola ny lohany noho ny aminy.', '‘ho faty eto amin’ity tany ity izy ireo, na ny lehibe na ny madinika. tsy halevina izy ireo, ary tsy hisy olona hisaona azy na handidididy vatana na hanasola ny lohany noho ny aminy.'),
  ('6ab25b9a23d0816c7d466e1d', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 11, 'Koa izao avaly azy ireo: ‘“Satria niala tamiko ny razambenareo”, hoy i Jehovah, “dia nanaraka andriamani-kafa sy nanompo azy ireny sady niankohoka taminy. Fa izaho kosa nafoiny ary ny lalàko tsy narahiny.', 'koa izao avaly azy ireo: ‘“satria niala tamiko ny razambenareo”, hoy i jehovah, “dia nanaraka andriamani-kafa sy nanompo azy ireny sady niankohoka taminy. fa izaho kosa nafoiny ary ny lalàko tsy narahiny.'),
  ('6ab25b9a23d0816c7d466e25', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 19, 'Jehovah ô, ianao no heriko sy manda fiarovana ho ahy Ary toerana fandosirako amin’ny andro fahoriana. Hankany aminao ny firenena avy any amin’ny faran’ny tany, Ka hilaza hoe: “Lainga tanteraka no nolovan’ny razambenay, Dia zava-poana tsy misy ilana azy sady tsy mahasoa.”', 'jehovah ô, ianao no heriko sy manda fiarovana ho ahy ary toerana fandosirako amin’ny andro fahoriana. hankany aminao ny firenena avy any amin’ny faran’ny tany, ka hilaza hoe: “lainga tanteraka no nolovan’ny razambenay, dia zava-poana tsy misy ilana azy sady tsy mahasoa.”'),
  ('6ab25b9a23d0816c7d466e1e', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 12, 'Ary ratsy lavitra noho ny nataon’ny razambenareo ny ataonareo. Samy mikiry manaraka ny fo ratsinareo ianareo fa tsy mankatò ahy.', 'ary ratsy lavitra noho ny nataon’ny razambenareo ny ataonareo. samy mikiry manaraka ny fo ratsinareo ianareo fa tsy mankatò ahy.'),
  ('6ab25b9a23d0816c7d466e13', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 1, 'Niteny tamiko indray i Jehovah hoe:', 'niteny tamiko indray i jehovah hoe:'),
  ('6ab25b9a23d0816c7d466e1b', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 9, '“Fa izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Hataoko tsy misy feon’olona mifaly sy miravoravo, na feona mpampakatra sy ampakarina intsony eto amin’ity toerana ity, amin’ny andronareo. Ny masonareo mihitsy no hahita an’izany.’', '“fa izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘hataoko tsy misy feon’olona mifaly sy miravoravo, na feona mpampakatra sy ampakarina intsony eto amin’ity toerana ity, amin’ny andronareo. ny masonareo mihitsy no hahita an’izany.’'),
  ('6ab25b9a23d0816c7d466e19', '2026-09-22T10:42:34.326Z', '2026-09-22T10:42:34.326Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 16, 7, 'Tsy hisy hanome sakafo ho an’ireo misaona, Mba hampiononana azy noho izy nidonam-pahoriana. Tsy hisy hanome azy ireo ny kaopin’ny fampiononana Mba hisotroany, noho ny nahafatesan’ny rainy na ny reniny.', 'tsy hisy hanome sakafo ho an’ireo misaona, mba hampiononana azy noho izy nidonam-pahoriana. tsy hisy hanome azy ireo ny kaopin’ny fampiononana mba hisotroany, noho ny nahafatesan’ny rainy na ny reniny.'),
  ('6ab25b9a74116d08a0db50e3', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 20, 'Lazao amin’izy ireo hoe: ‘Henoy ny tenin’i Jehovah, ry mpanjakan’ny Joda, sy ianareo rehetra vahoakan’i Joda sy mponin’i Jerosalema, izay miditra eo amin’ireto vavahady ireto.', 'lazao amin’izy ireo hoe: ‘henoy ny tenin’i jehovah, ry mpanjakan’ny joda, sy ianareo rehetra vahoakan’i joda sy mponin’i jerosalema, izay miditra eo amin’ireto vavahady ireto.'),
  ('6ab25b9a74116d08a0db50e6', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 23, 'Tsy nihaino anefa izy ireo na nanongilan-tsofina, fa mafy loha tsy nety nankatò na nandray anatra.”’', 'tsy nihaino anefa izy ireo na nanongilan-tsofina, fa mafy loha tsy nety nankatò na nandray anatra.”’'),
  ('6ab25b9a74116d08a0db50e0', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 17, 'Aza manao izay hampihorohoro ahy. Ianao no fialofako amin’ny andro iavian’ny loza.', 'aza manao izay hampihorohoro ahy. ianao no fialofako amin’ny andro iavian’ny loza.'),
  ('6ab25b9a74116d08a0db50df', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 16, 'Izaho kosa anefa tsy nitsoaka tsy ho mpiandry ondry fa mbola nanaraka anao. Tsy naniry ny hahatongavan’ny andro iavian’ny loza koa aho. Fantatrao tsara ny teny rehetra naloaky ny vavako. Teo anatrehanao no nitranga izany rehetra izany.', 'izaho kosa anefa tsy nitsoaka tsy ho mpiandry ondry fa mbola nanaraka anao. tsy naniry ny hahatongavan’ny andro iavian’ny loza koa aho. fantatrao tsara ny teny rehetra naloaky ny vavako. teo anatrehanao no nitranga izany rehetra izany.'),
  ('6ab25b9a74116d08a0db50dd', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 14, 'Sitrano aho, Jehovah ô, dia ho sitrana. Vonjeo aho, dia ho voavonjy, Fa ianao no deraiko.', 'sitrano aho, jehovah ô, dia ho sitrana. vonjeo aho, dia ho voavonjy, fa ianao no deraiko.'),
  ('6ab25b9a74116d08a0db50d2', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 3, 'Ary teny an-tendrombohitra any ambanivohitra. Homeko ho an’ny mpandroba ny fanananao sy ny harenanao rehetra. Homeko azy ny toerana avo naorinao, noho ny fahotana nataonao nanerana ny taninao.', 'ary teny an-tendrombohitra any ambanivohitra. homeko ho an’ny mpandroba ny fanananao sy ny harenanao rehetra. homeko azy ny toerana avo naorinao, noho ny fahotana nataonao nanerana ny taninao.'),
  ('6ab25b9a74116d08a0db50de', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 15, 'Misy milaza amiko hoe: “Aiza koa izay tenin’i Jehovah eo? Aoka ho tanteraka amin’izay izany!”', 'misy milaza amiko hoe: “aiza koa izay tenin’i jehovah eo? aoka ho tanteraka amin’izay izany!”'),
  ('6ab25b9a74116d08a0db50e9', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 26, 'Ary ho avy ny olona avy any amin’ireo tanànan’i Joda, avy any amin’ny manodidina an’i Jerosalema, ny tanin’i Benjamina, ny faritra iva, ny faritra be tendrombohitra, ary ny avy any Negeba. Hitondra fanatitra ao an-tranon’i Jehovah izy ireo, dia fanatitra dorana manontolo, sorona, fanatitra varimbazaha, ditin-kazo manitra, ary sorona fisaorana.', 'ary ho avy ny olona avy any amin’ireo tanànan’i joda, avy any amin’ny manodidina an’i jerosalema, ny tanin’i benjamina, ny faritra iva, ny faritra be tendrombohitra, ary ny avy any negeba. hitondra fanatitra ao an-tranon’i jehovah izy ireo, dia fanatitra dorana manontolo, sorona, fanatitra varimbazaha, ditin-kazo manitra, ary sorona fisaorana.'),
  ('6ab25b9a74116d08a0db50da', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 11, 'Izay manao ny tsy marina mba hahazoana harena, Dia toy ny tsipoy manangona atody tsy azy. Handao azy izany harenany izany raha vao misasaka ny androm-piainany, Ary ho hita amin’ny farany fa tsy misy saina izy.”', 'izay manao ny tsy marina mba hahazoana harena, dia toy ny tsipoy manangona atody tsy azy. handao azy izany harenany izany raha vao misasaka ny androm-piainany, ary ho hita amin’ny farany fa tsy misy saina izy.”'),
  ('6ab25b9a74116d08a0db50d0', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 1, '“Voasoratra tamin’ny penina vy ny fahotan’ny Joda, Sady vita sokitra tamin’ny tendrona diamondra, eo amin’ny fon’izy ireo Sy eo amin’ny tandroky ny alitarany.', '“voasoratra tamin’ny penina vy ny fahotan’ny joda, sady vita sokitra tamin’ny tendrona diamondra, eo amin’ny fon’izy ireo sy eo amin’ny tandroky ny alitarany.'),
  ('6ab25b9a74116d08a0db50e5', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 22, 'Aza mitondra entana avy ao an-tranonareo rehefa Sabata ny andro, ary aza manao asa na inona na inona. Fa hamasino ny andro sabata, araka ny didy nomeko ny razambenareo.', 'aza mitondra entana avy ao an-tranonareo rehefa sabata ny andro, ary aza manao asa na inona na inona. fa hamasino ny andro sabata, araka ny didy nomeko ny razambenareo.'),
  ('6ab25b9a74116d08a0db50e7', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 24, '“‘“Raha mankatò ahy an-tsakany sy an-davany anefa ianareo”, hoy i Jehovah, “ka tsy mampiditra entana eo amin’ireo vavahadin’ity tanàna ity rehefa Sabata ny andro, sady manamasina ny andro sabata ka tsy manao asa na inona na inona,', '“‘“raha mankatò ahy an-tsakany sy an-davany anefa ianareo”, hoy i jehovah, “ka tsy mampiditra entana eo amin’ireo vavahadin’ity tanàna ity rehefa sabata ny andro, sady manamasina ny andro sabata ka tsy manao asa na inona na inona,'),
  ('6ab25b9a74116d08a0db50db', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 12, 'Seza fiandrianana be voninahitra, izay efa nasandratra hatrany am-boalohany, No toerana masina ho antsika.', 'seza fiandrianana be voninahitra, izay efa nasandratra hatrany am-boalohany, no toerana masina ho antsika.'),
  ('6ab25b9a74116d08a0db50ea', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 27, '“‘“Fa raha tsy mankatò ahy kosa ianareo ka tsy manamasina ny andro sabata, fa mitondra entana sy mampiditra an’izany eo amin’ireo vavahadin’i Jerosalema na Sabata aza ny andro, dia hodorako ireo vavahadiny. Dia ho levon’ny afo ireo tilikambo voaro mafy ao Jerosalema, ary tsy hovonoina izany afo izany.”’”', '“‘“fa raha tsy mankatò ahy kosa ianareo ka tsy manamasina ny andro sabata, fa mitondra entana sy mampiditra an’izany eo amin’ireo vavahadin’i jerosalema na sabata aza ny andro, dia hodorako ireo vavahadiny. dia ho levon’ny afo ireo tilikambo voaro mafy ao jerosalema, ary tsy hovonoina izany afo izany.”’”'),
  ('6ab25b9a74116d08a0db50d9', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 10, 'Izaho Jehovah no mandinika ny fo Sy mamantatra ny eritreritra lalina indrindra, Mba hamaliako ny tsirairay araka izay ataony, Sy araka ny vokatry ny asany.', 'izaho jehovah no mandinika ny fo sy mamantatra ny eritreritra lalina indrindra, mba hamaliako ny tsirairay araka izay ataony, sy araka ny vokatry ny asany.'),
  ('6ab25b9a74116d08a0db50d8', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 9, 'Mamitaka mihoatra noho ny zava-drehetra ny fo, sady sarotra fehezina. Iza no mahalala ny momba azy?', 'mamitaka mihoatra noho ny zava-drehetra ny fo, sady sarotra fehezina. iza no mahalala ny momba azy?'),
  ('6ab25b9a74116d08a0db50d4', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 5, 'Izao no lazain’i Jehovah: “Voaozona izay olona matoky olona Sy miantehitra amin’ny herin’olombelona, Ka miala amin’i Jehovah ny fony.', 'izao no lazain’i jehovah: “voaozona izay olona matoky olona sy miantehitra amin’ny herin’olombelona, ka miala amin’i jehovah ny fony.'),
  ('6ab25b9a74116d08a0db50e4', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 21, 'Izao no lazain’i Jehovah: “Mitandrema mba tsy hitondra entana amin’ny andro sabata, na hampiditra an’izany eo amin’ireo vavahadin’i Jerosalema.', 'izao no lazain’i jehovah: “mitandrema mba tsy hitondra entana amin’ny andro sabata, na hampiditra an’izany eo amin’ireo vavahadin’i jerosalema.'),
  ('6ab25b9a74116d08a0db50d6', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 7, 'Hotahina izay olona matoky an’i Jehovah Sy miantehitra amin’i Jehovah.', 'hotahina izay olona matoky an’i jehovah sy miantehitra amin’i jehovah.'),
  ('6ab25b9a74116d08a0db50d3', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 4, 'Hafoinao an-tsitrapo ny lova nomeko anao. Ary hasaiko manompo ny fahavalonao any amin’ny tany tsy fantatrao ianao, Satria narehitrao toy ny afo ny fahatezerako. Dia hirehitra mandrakizay izany.”', 'hafoinao an-tsitrapo ny lova nomeko anao. ary hasaiko manompo ny fahavalonao any amin’ny tany tsy fantatrao ianao, satria narehitrao toy ny afo ny fahatezerako. dia hirehitra mandrakizay izany.”'),
  ('6ab25b9a74116d08a0db50e2', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 19, 'Izao no nolazain’i Jehovah tamiko: “Mandehana mijoro eo amin’ny vavahadin’ny zana-bahoaka, izay fandalovan’ireo mpanjakan’ny Joda rehefa miditra sy mivoaka, ary eo amin’ny vavahady rehetra ao Jerosalema.', 'izao no nolazain’i jehovah tamiko: “mandehana mijoro eo amin’ny vavahadin’ny zana-bahoaka, izay fandalovan’ireo mpanjakan’ny joda rehefa miditra sy mivoaka, ary eo amin’ny vavahady rehetra ao jerosalema.'),
  ('6ab25b9a74116d08a0db50d7', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 8, 'Ho toy ny hazo nambolena eo amoron-drano izy, Dia hazo mampisandrahaka ny fakany hatrany amin’ny renirano. Tsy ho tsapany akory ny hafanana, Fa handrobona foana ny raviny. Ary na dia amin’ny taona isian’ny hain-tany aza, dia tsy hanahy izy Fa mbola hamokatra foana.', 'ho toy ny hazo nambolena eo amoron-drano izy, dia hazo mampisandrahaka ny fakany hatrany amin’ny renirano. tsy ho tsapany akory ny hafanana, fa handrobona foana ny raviny. ary na dia amin’ny taona isian’ny hain-tany aza, dia tsy hanahy izy fa mbola hamokatra foana.'),
  ('6ab25b9a74116d08a0db50e8', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 25, 'dia hiditra eo amin’ireo vavahadin’ity tanàna ity koa ireo mpanjaka sy andriana mipetraka eo amin’ny seza fiandrianan’i Davida. Hitaingina kalesy sy soavaly izy ireo sy ny andrianany ary ny fokon’i Joda sy ny mponin’i Jerosalema, amin’izay fotoana izay. Dia honenana mandrakizay ity tanàna ity.', 'dia hiditra eo amin’ireo vavahadin’ity tanàna ity koa ireo mpanjaka sy andriana mipetraka eo amin’ny seza fiandrianan’i davida. hitaingina kalesy sy soavaly izy ireo sy ny andrianany ary ny fokon’i joda sy ny mponin’i jerosalema, amin’izay fotoana izay. dia honenana mandrakizay ity tanàna ity.'),
  ('6ab25b9a74116d08a0db50e1', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 18, 'Aoka ho menatra ireo mpanenjika ahy, Fa izaho kosa aoka tsy ho menatra. Aoka hihorohoro izy ireo, Fa izaho kosa aoka tsy hihorohoro. Ataovy tonga aminy ny andro iavian’ny loza, Ka torotoroy izy ireo ary aringano tanteraka.', 'aoka ho menatra ireo mpanenjika ahy, fa izaho kosa aoka tsy ho menatra. aoka hihorohoro izy ireo, fa izaho kosa aoka tsy hihorohoro. ataovy tonga aminy ny andro iavian’ny loza, ka torotoroy izy ireo ary aringano tanteraka.'),
  ('6ab25b9a74116d08a0db50dc', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 13, 'Ry Jehovah, fanantenan’ny Israely ô! Ho menatra izay rehetra mahafoy anao. Hosoratana eo amin’ny vovoka ny anaran’ireo mivadi-pinoana sy miala aminao, Noho izy ireo miala amin’i Jehovah, ilay loharanon’ny rano velona.', 'ry jehovah, fanantenan’ny israely ô! ho menatra izay rehetra mahafoy anao. hosoratana eo amin’ny vovoka ny anaran’ireo mivadi-pinoana sy miala aminao, noho izy ireo miala amin’i jehovah, ilay loharanon’ny rano velona.'),
  ('6ab25b9a74116d08a0db50d5', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 6, 'Ho toy ny hazo tokana any amin’ny tany karakaina izy. Tsy mba hahita zava-tsoa izy, Fa hipetraka any amin’ny faritra ngazana any an-tany efitra, Any amin’ny tanin-tsira tsy azo ipetrahana.', 'ho toy ny hazo tokana any amin’ny tany karakaina izy. tsy mba hahita zava-tsoa izy, fa hipetraka any amin’ny faritra ngazana any an-tany efitra, any amin’ny tanin-tsira tsy azo ipetrahana.'),
  ('6ab25b9a74116d08a0db50d1', '2026-09-22T10:42:34.983Z', '2026-09-22T10:42:34.983Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 17, 2, 'Na ny taranany aza mahatadidy ny alitara sy ny tsato-kazo masina nataon’izy ireo Teny akaikin’ny hazo midoroboka, teny amin’ny havoana,', 'na ny taranany aza mahatadidy ny alitara sy ny tsato-kazo masina nataon’izy ireo teny akaikin’ny hazo midoroboka, teny amin’ny havoana,'),
  ('6ab25b9bfd7109a4c2dc6537', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 1, 'Niteny tamin’i Jeremia i Jehovah hoe:', 'niteny tamin’i jeremia i jehovah hoe:'),
  ('6ab25b9bfd7109a4c2dc6548', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 18, 'Dia hoy izy ireo: “Andao isika hanao tetika hamelezana an’i Jeremia, satria mbola ho eo foana ny lalàna avy amin’ny mpisorontsika, ny torohevitra avy amin’ny olon-kendry, ary ny teny avy amin’ny mpaminany. Andao isika hiampanga azy, ary aza miraharaha an’izay lazainy.”', 'dia hoy izy ireo: “andao isika hanao tetika hamelezana an’i jeremia, satria mbola ho eo foana ny lalàna avy amin’ny mpisorontsika, ny torohevitra avy amin’ny olon-kendry, ary ny teny avy amin’ny mpaminany. andao isika hiampanga azy, ary aza miraharaha an’izay lazainy.”'),
  ('6ab25b9bfd7109a4c2dc6549', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 19, 'Henoy aho, Jehovah ô, Ary henoy ny tenin’ireo mpanohitra ahy.', 'henoy aho, jehovah ô, ary henoy ny tenin’ireo mpanohitra ahy.'),
  ('6ab25b9bfd7109a4c2dc6545', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 15, 'Nanadino ahy anefa ny vahoakako. Manao sorona ho an’ny zavatra tsy misy dikany mantsy izy ireo, Ary manao izay hahatafintohina ny olona eny amin’ny lalany, dia ny lalana fahiny, Mba handehanan’izy ireny eny amin’ny lalan-kely mikitoantoana sy tsy mitovy tantana.', 'nanadino ahy anefa ny vahoakako. manao sorona ho an’ny zavatra tsy misy dikany mantsy izy ireo, ary manao izay hahatafintohina ny olona eny amin’ny lalany, dia ny lalana fahiny, mba handehanan’izy ireny eny amin’ny lalan-kely mikitoantoana sy tsy mitovy tantana.'),
  ('6ab25b9bfd7109a4c2dc6540', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 10, 'nefa manao ratsy eo imasoko izy ka tsy mankatò ny teniko, dia hiova hevitra aho ka tsy hataoko aminy indray ilay zavatra tsara nokasaiko hatao aminy.’', 'nefa manao ratsy eo imasoko izy ka tsy mankatò ny teniko, dia hiova hevitra aho ka tsy hataoko aminy indray ilay zavatra tsara nokasaiko hatao aminy.’'),
  ('6ab25b9bfd7109a4c2dc653c', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 6, '“‘Tsy afaka manao aminareo hoatran’ny nataon’io mpanefy tanimanga io koa ve aho, ry taranak’Israely?’, hoy i Jehovah. ‘Toy ny tanimanga eny an-tanan’ny mpanefy tanimanga ianareo eto an-tanako, ry taranak’Israely ô!', '“‘tsy afaka manao aminareo hoatran’ny nataon’io mpanefy tanimanga io koa ve aho, ry taranak’israely?’, hoy i jehovah. ‘toy ny tanimanga eny an-tanan’ny mpanefy tanimanga ianareo eto an-tanako, ry taranak’israely ô!'),
  ('6ab25b9bfd7109a4c2dc6538', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 2, '“Mitsangàna dia midìna any an-tranon’ny mpanefy tanimanga, fa any aho no hilaza aminao ny teniko.”', '“mitsangàna dia midìna any an-tranon’ny mpanefy tanimanga, fa any aho no hilaza aminao ny teniko.”'),
  ('6ab25b9bfd7109a4c2dc654c', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 22, 'Aoka hisy fidradradradrana ho re avy ao an-tranon’izy ireo, Rehefa asainao manafika azy tampoka ny mpandroba. Nihady lavaka mantsy izy ireo mba hisamborana ahy, Ary nanisy fandrika hamandrihana ny tongotro.', 'aoka hisy fidradradradrana ho re avy ao an-tranon’izy ireo, rehefa asainao manafika azy tampoka ny mpandroba. nihady lavaka mantsy izy ireo mba hisamborana ahy, ary nanisy fandrika hamandrihana ny tongotro.'),
  ('6ab25b9bfd7109a4c2dc653a', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 4, 'Simban’ny tanan’ilay mpanefy tanimanga anefa ilay vilany nataony. Novany ho zavatra hafa àry ilay izy, araka izay tiany.', 'simban’ny tanan’ilay mpanefy tanimanga anefa ilay vilany nataony. novany ho zavatra hafa àry ilay izy, araka izay tiany.'),
  ('6ab25b9bfd7109a4c2dc6546', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 16, 'Koa hanjary hihorohoro ny olona mahita ny tanin’izy ireo, Ary hisioka haneso azy io mandrakizay. Ho tsiravina izay mpandalo rehetra mahita azy, ka hihivingivin-doha.', 'koa hanjary hihorohoro ny olona mahita ny tanin’izy ireo, ary hisioka haneso azy io mandrakizay. ho tsiravina izay mpandalo rehetra mahita azy, ka hihivingivin-doha.'),
  ('6ab25b9bfd7109a4c2dc654d', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 23, 'Fa ianao kosa Jehovah ô, Mahafantatra tsara ny tetika rehetra ataon’izy ireo mba hamonoana ahy ho faty. Aza manarona ny fahadisoany, Ary aza kosehina tsy ho eo anatrehanao ny fahotany. Aoka izy ireo ho tafintohina eo anatrehanao, Rehefa mamely azy ireo ianao, noho ny fahatezeranao.', 'fa ianao kosa jehovah ô, mahafantatra tsara ny tetika rehetra ataon’izy ireo mba hamonoana ahy ho faty. aza manarona ny fahadisoany, ary aza kosehina tsy ho eo anatrehanao ny fahotany. aoka izy ireo ho tafintohina eo anatrehanao, rehefa mamely azy ireo ianao, noho ny fahatezeranao.'),
  ('6ab25b9bfd7109a4c2dc654b', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 21, 'Koa ataovy matin’ny mosary ny zanany, Ary atolory ho fatin’ny sabatra izy ireo. Enga anie ny vadiny ho maty zanaka, ary ho lasa mpitondratena! Enga anie ho fatin’ny aretina ny lehilahy eo aminy, Ary ny tovolahy ho fatin’ny sabatra any an’ady!', 'koa ataovy matin’ny mosary ny zanany, ary atolory ho fatin’ny sabatra izy ireo. enga anie ny vadiny ho maty zanaka, ary ho lasa mpitondratena! enga anie ho fatin’ny aretina ny lehilahy eo aminy, ary ny tovolahy ho fatin’ny sabatra any an’ady!'),
  ('6ab25b9bfd7109a4c2dc6544', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 14, 'Tsy misy lanezy intsony ve eny amin’ny vatolampy, eny amin’ny tehezan’i Libàna? Ho ritra ve ny rano mangatsiatsiaka mikoriana avy lavitra?', 'tsy misy lanezy intsony ve eny amin’ny vatolampy, eny amin’ny tehezan’i libàna? ho ritra ve ny rano mangatsiatsiaka mikoriana avy lavitra?'),
  ('6ab25b9bfd7109a4c2dc6543', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 13, 'Koa izao no lazain’i Jehovah: “Mba anontanio, azafady, ny olona any amin’ireo firenena. Iza no efa nandre zavatra hoatr’izany? Nanao zavatra faran’izay mahatsiravina ny Israely virjiny.', 'koa izao no lazain’i jehovah: “mba anontanio, azafady, ny olona any amin’ireo firenena. iza no efa nandre zavatra hoatr’izany? nanao zavatra faran’izay mahatsiravina ny israely virjiny.'),
  ('6ab25b9bfd7109a4c2dc653f', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 9, 'Fa isaky ny milaza kosa aho hoe hanorina sy hamboly firenena na fanjakana iray,', 'fa isaky ny milaza kosa aho hoe hanorina sy hamboly firenena na fanjakana iray,'),
  ('6ab25b9bfd7109a4c2dc6539', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 3, 'Dia nidina tany an-tranon’ny mpanefy tanimanga aho, ka nahita azy niasa teo amin’ilay milina mihodinkodina fampiasany.', 'dia nidina tany an-tranon’ny mpanefy tanimanga aho, ka nahita azy niasa teo amin’ilay milina mihodinkodina fampiasany.'),
  ('6ab25b9bfd7109a4c2dc654a', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 20, 'Dia ratsy ve no havaly ny soa? Fa nihady lavaka hamonoana ahy izy ireo. Tsarovy ny nitsanganako teo anatrehanao mba hilaza zavatra tsara momba azy ireo, Amin’izay dia tsy ho tezitra aminy intsony ianao.', 'dia ratsy ve no havaly ny soa? fa nihady lavaka hamonoana ahy izy ireo. tsarovy ny nitsanganako teo anatrehanao mba hilaza zavatra tsara momba azy ireo, amin’izay dia tsy ho tezitra aminy intsony ianao.'),
  ('6ab25b9bfd7109a4c2dc6541', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 11, '“Mba lazao amin’ny fokon’i Joda sy ny mponin’i Jerosalema àry hoe: ‘Izao no tenin’i Jehovah: “Efa manomana loza ho anareo aho ary efa mieritreritra ny fomba hamelezana anareo. Koa mialà re amin’ny lalan-dratsinareo e, ary ahitsio ny lalanareo sy ny fanaonareo.”’”', '“mba lazao amin’ny fokon’i joda sy ny mponin’i jerosalema àry hoe: ‘izao no tenin’i jehovah: “efa manomana loza ho anareo aho ary efa mieritreritra ny fomba hamelezana anareo. koa mialà re amin’ny lalan-dratsinareo e, ary ahitsio ny lalanareo sy ny fanaonareo.”’”'),
  ('6ab25b9bfd7109a4c2dc653d', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 7, 'Isaky ny milaza aho hoe hanongotra sy handrodana ary handrava firenena na fanjakana iray,', 'isaky ny milaza aho hoe hanongotra sy handrodana ary handrava firenena na fanjakana iray,'),
  ('6ab25b9bfd7109a4c2dc653b', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 5, 'Dia niteny tamiko indray i Jehovah hoe:', 'dia niteny tamiko indray i jehovah hoe:'),
  ('6ab25b9bfd7109a4c2dc653e', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 8, 'nefa miala amin’ilay faharatsiana nanamelohako azy ilay firenena, dia hiova hevitra aho ka tsy hampihariko aminy indray ilay loza nokasaiko hamelezana azy.', 'nefa miala amin’ilay faharatsiana nanamelohako azy ilay firenena, dia hiova hevitra aho ka tsy hampihariko aminy indray ilay loza nokasaiko hamelezana azy.'),
  ('6ab25b9bfd7109a4c2dc6547', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 17, 'Haparitako eo anoloan’ny fahavalony izy ireo, toy ny ataon’ny rivotra avy any atsinanana. Hanome lamosina azy ireo aho fa tsy hanatrika azy, amin’ny andro hahitany loza.”', 'haparitako eo anoloan’ny fahavalony izy ireo, toy ny ataon’ny rivotra avy any atsinanana. hanome lamosina azy ireo aho fa tsy hanatrika azy, amin’ny andro hahitany loza.”');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25b9bfd7109a4c2dc6542', '2026-09-22T10:42:35.499Z', '2026-09-22T10:42:35.499Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 18, 12, 'Hoy anefa izy ireo: “Aza manantena an’izany! Fa izay efa noeritreretinay ihany no hataonay, ary samy hikiry hanao izay tianay izahay.”', 'hoy anefa izy ireo: “aza manantena an’izany! fa izay efa noeritreretinay ihany no hataonay, ary samy hikiry hanao izay tianay izahay.”'),
  ('6ab25b9c8f54eb1f44c81823', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 7, 'Hataoko tsy tanteraka eto amin’ity toerana ity ny tetika nataon’i Joda sy Jerosalema, ary hataoko matin’ny sabatry ny fahavalony sy maty eo am-pelatanan’ ireo mitady hamono azy izy ireo. Dia homeko ho sakafon’ny voro-manidina sy ny bibidia ny fatiny.', 'hataoko tsy tanteraka eto amin’ity toerana ity ny tetika nataon’i joda sy jerosalema, ary hataoko matin’ny sabatry ny fahavalony sy maty eo am-pelatanan’ ireo mitady hamono azy izy ireo. dia homeko ho sakafon’ny voro-manidina sy ny bibidia ny fatiny.'),
  ('6ab25b9c8f54eb1f44c81821', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 5, 'Nanorina an’ireo toerana avo ho an’i Bala koa izy ireo mba handoroany ny zanany ao anaty afo, ho fanatitra dorana manontolo ho an’i Bala. Tsy nandidy azy hanao an’izany anefa aho na niresaka an’izany taminy, ary tsy tao an-tsaiko akory aza izany.”’', 'nanorina an’ireo toerana avo ho an’i bala koa izy ireo mba handoroany ny zanany ao anaty afo, ho fanatitra dorana manontolo ho an’i bala. tsy nandidy azy hanao an’izany anefa aho na niresaka an’izany taminy, ary tsy tao an-tsaiko akory aza izany.”’'),
  ('6ab25b9c8f54eb1f44c81826', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 10, '“Dia poteho eo anatrehan’ireo olona miaraka aminao ilay jaogy kely.', '“dia poteho eo anatrehan’ireo olona miaraka aminao ilay jaogy kely.'),
  ('6ab25b9c8f54eb1f44c8181f', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 3, 'Izao no holazainao: ‘Henoy ny tenin’i Jehovah, ry mpanjakan’ny Joda sy mponin’i Jerosalema. Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “‘“Hahatonga loza amin’ity toerana ity aho, ka hangorintsina ny sofin’izay mandre an’izany.', 'izao no holazainao: ‘henoy ny tenin’i jehovah, ry mpanjakan’ny joda sy mponin’i jerosalema. izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: “‘“hahatonga loza amin’ity toerana ity aho, ka hangorintsina ny sofin’izay mandre an’izany.'),
  ('6ab25b9c8f54eb1f44c8181d', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 1, 'Izao no nolazain’i Jehovah: “Mandehana mividy jaogy kely any amin’ny mpanefy tanimanga, ary miantsoa anti-panahy eo amin’ny vahoaka sy anti-panahy mpisorona.', 'izao no nolazain’i jehovah: “mandehana mividy jaogy kely any amin’ny mpanefy tanimanga, ary miantsoa anti-panahy eo amin’ny vahoaka sy anti-panahy mpisorona.'),
  ('6ab25b9c8f54eb1f44c8181e', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 2, 'Dia mivoaha eny amin’ny Lohasahan’ny Taranak’i Hinoma, eo amin’ny fidirana amin’ny Vavahadin’ny Vakim-bilany Tanimanga, ka ambarao eny izay teny holazaiko aminao.', 'dia mivoaha eny amin’ny lohasahan’ny taranak’i hinoma, eo amin’ny fidirana amin’ny vavahadin’ny vakim-bilany tanimanga, ka ambarao eny izay teny holazaiko aminao.'),
  ('6ab25b9c8f54eb1f44c81824', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 8, 'Ary hataoko mihorohoro ny olona mahita an’izay hanjo an’ity tanàna ity ary hisioka haneso azy. Ho tsiravina izay mpandalo rehetra mahita azy, ka hisioka noho ny loza rehetra nanjo azy.', 'ary hataoko mihorohoro ny olona mahita an’izay hanjo an’ity tanàna ity ary hisioka haneso azy. ho tsiravina izay mpandalo rehetra mahita azy, ka hisioka noho ny loza rehetra nanjo azy.'),
  ('6ab25b9c8f54eb1f44c81828', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 12, '“‘Izany no hataoko amin’ity toerana ity sy ny mponina ao’, hoy i Jehovah. ‘Hataoko hoatran’i Tofeta ity tanàna ity.', '“‘izany no hataoko amin’ity toerana ity sy ny mponina ao’, hoy i jehovah. ‘hataoko hoatran’i tofeta ity tanàna ity.'),
  ('6ab25b9c8f54eb1f44c81827', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 11, 'Ary lazao amin’izy ireo hoe: ‘Izao no tenin’i Jehovah Tompon’ny tafika: “Hopotehiko hoatr’izao ity vahoaka ity sy ity tanàna ity, hoatran’ny ataon’ny olona iray manapotika vilany tanimanga mba tsy ho azo amboarina intsony. Dia haleviny ao Tofeta izay maty, mandra-paha tsy hisy toerana handevenana azy ireo intsony ao.”’', 'ary lazao amin’izy ireo hoe: ‘izao no tenin’i jehovah tompon’ny tafika: “hopotehiko hoatr’izao ity vahoaka ity sy ity tanàna ity, hoatran’ny ataon’ny olona iray manapotika vilany tanimanga mba tsy ho azo amboarina intsony. dia haleviny ao tofeta izay maty, mandra-paha tsy hisy toerana handevenana azy ireo intsony ao.”’'),
  ('6ab25b9c8f54eb1f44c8182a', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 14, 'Rehefa tafaverina avy tany Tofeta, izay nanirahan’i Jehovah azy mba haminany, i Jeremia, dia nitsangana teo an-tokotanin’ny tranon’i Jehovah. Dia hoy izy tamin’ny vahoaka rehetra:', 'rehefa tafaverina avy tany tofeta, izay nanirahan’i jehovah azy mba haminany, i jeremia, dia nitsangana teo an-tokotanin’ny tranon’i jehovah. dia hoy izy tamin’ny vahoaka rehetra:'),
  ('6ab25b9c8f54eb1f44c81829', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 13, 'Dia hanjary haloto hoatran’ny eto Tofeta ireo trano ao Jerosalema sy ny tranon’ireo mpanjakan’ny Joda. Haloto izay trano rehetra nanolorana fanatitra teny an-tampony, izany hoe nanaovana sorona ho an’izay rehetra eny amin’ny lanitra, sady nandrarahana fanatitra zava-pisotro ho an’ny andriamani-kafa.’”', 'dia hanjary haloto hoatran’ny eto tofeta ireo trano ao jerosalema sy ny tranon’ireo mpanjakan’ny joda. haloto izay trano rehetra nanolorana fanatitra teny an-tampony, izany hoe nanaovana sorona ho an’izay rehetra eny amin’ny lanitra, sady nandrarahana fanatitra zava-pisotro ho an’ny andriamani-kafa.’”'),
  ('6ab25b9c8f54eb1f44c81820', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 4, 'Niala tamiko mantsy izy ireo, ary nataony izay tsy hahafantarana intsony an’ity toerana ity. Eto izy ireo no manao sorona ho an’ny andriamani-kafa, dia andriamanitra tsy fantatr’izy ireo sy ny razambeny sady tsy fantatry ny mpanjakan’ny Joda. Ary nataony feno ran’olona tsy manan-tsiny ity toerana ity.', 'niala tamiko mantsy izy ireo, ary nataony izay tsy hahafantarana intsony an’ity toerana ity. eto izy ireo no manao sorona ho an’ny andriamani-kafa, dia andriamanitra tsy fantatr’izy ireo sy ny razambeny sady tsy fantatry ny mpanjakan’ny joda. ary nataony feno ran’olona tsy manan-tsiny ity toerana ity.'),
  ('6ab25b9c8f54eb1f44c81825', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 9, 'Hampihinaniko ny nofon’ny zanany lahy sy ny zanany vavy izy ireo, ary samy hihinana ny nofon’ny namany avy. Hanao fahirano azy ireo mantsy ny fahavalony sy ireo mitady hamono azy, ka ho very hevitra izy ireo.”’', 'hampihinaniko ny nofon’ny zanany lahy sy ny zanany vavy izy ireo, ary samy hihinana ny nofon’ny namany avy. hanao fahirano azy ireo mantsy ny fahavalony sy ireo mitady hamono azy, ka ho very hevitra izy ireo.”’'),
  ('6ab25b9c8f54eb1f44c8182b', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 15, '“Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Hataoko tonga amin’ity tanàna ity sy ny tanàna keliny rehetra ny loza rehetra nolazaiko hamelezana azy, satria mafy loha tsy nety nankatò ny teniko izy ireo.’”', '“izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘hataoko tonga amin’ity tanàna ity sy ny tanàna keliny rehetra ny loza rehetra nolazaiko hamelezana azy, satria mafy loha tsy nety nankatò ny teniko izy ireo.’”'),
  ('6ab25b9c8f54eb1f44c81822', '2026-09-22T10:42:36.136Z', '2026-09-22T10:42:36.136Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 19, 6, '“‘“Koa ho avy ny andro”, hoy i Jehovah, “izay tsy hiantsoana an’ity toerana ity intsony hoe Tofeta na Lohasahan’ny Taranak’i Hinoma, fa hoe Lohasaha Famonoana.', '“‘“koa ho avy ny andro”, hoy i jehovah, “izay tsy hiantsoana an’ity toerana ity intsony hoe tofeta na lohasahan’ny taranak’i hinoma, fa hoe lohasaha famonoana.'),
  ('6ab25b9dd55449e4c49fdc6d', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 9, 'Dia niteny aho hoe: “Tsy hiresaka momba azy intsony aho, Na hiteny amin’ny anarany.” Lasa toy ny afo mirehitra ato am-poko sy voahidy ato amin’ny taolako anefa ny teniny, Ka reraky ny mitazona an’ilay izy aho. Tsy vitako intsony ny miaritra an’izany.', 'dia niteny aho hoe: “tsy hiresaka momba azy intsony aho, na hiteny amin’ny anarany.” lasa toy ny afo mirehitra ato am-poko sy voahidy ato amin’ny taolako anefa ny teniny, ka reraky ny mitazona an’ilay izy aho. tsy vitako intsony ny miaritra an’izany.'),
  ('6ab25b9dd55449e4c49fdc65', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 1, 'Nihaino an’i Jeremia i Pasora mpisorona, zanak’i Imera, rehefa nilaza an’izany faminaniana izany izy. Lehiben’ny mpiadidy tao an-tranon’i Jehovah i Pasora.', 'nihaino an’i jeremia i pasora mpisorona, zanak’i imera, rehefa nilaza an’izany faminaniana izany izy. lehiben’ny mpiadidy tao an-tranon’i jehovah i pasora.'),
  ('6ab25b9dd55449e4c49fdc74', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 16, 'Enga anie izany olona izany ho lasa hoatran’ireo tanàna noravan’i Jehovah nefa tsy nanenenany! Handre antsoantso anie izy amin’ny maraina ary haheno fanairana amin’ny mitataovovonana.', 'enga anie izany olona izany ho lasa hoatran’ireo tanàna noravan’i jehovah nefa tsy nanenenany! handre antsoantso anie izy amin’ny maraina ary haheno fanairana amin’ny mitataovovonana.'),
  ('6ab25b9dd55449e4c49fdc6c', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 8, 'Fa isaky ny miteny aho, dia tsy maintsy mitaraina sy miantsoantso hoe: “Herisetra sy fandravana!” Atao tsinontsinona sy esoesoina aho tontolo andro, noho ny tenin’i Jehovah.', 'fa isaky ny miteny aho, dia tsy maintsy mitaraina sy miantsoantso hoe: “herisetra sy fandravana!” atao tsinontsinona sy esoesoina aho tontolo andro, noho ny tenin’i jehovah.'),
  ('6ab25b9dd55449e4c49fdc73', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 15, 'Ho voaozona anie ilay olona nilaza vaovao tsara tamin’i Dada hoe: “Tera-dahy ianao!” Faly be i Dada tamin’izay.', 'ho voaozona anie ilay olona nilaza vaovao tsara tamin’i dada hoe: “tera-dahy ianao!” faly be i dada tamin’izay.'),
  ('6ab25b9dd55449e4c49fdc6e', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 10, 'Fa naheno fanaratsiana aely etsy sy eroa aho. Nanjaka hatraiza hatraiza ny horohoro. Hoy izy ireo: “Ampangao izy! Andao isika hiampanga azy!” Miandry izay hahasolafaka ahy ny olona rehetra mirary soa ho ahy, ka miteny hoe: “Angamba izy hanao hadalana, Dia ho afaka handresy sy hamaly faty azy isika.”', 'fa naheno fanaratsiana aely etsy sy eroa aho. nanjaka hatraiza hatraiza ny horohoro. hoy izy ireo: “ampangao izy! andao isika hiampanga azy!” miandry izay hahasolafaka ahy ny olona rehetra mirary soa ho ahy, ka miteny hoe: “angamba izy hanao hadalana, dia ho afaka handresy sy hamaly faty azy isika.”'),
  ('6ab25b9dd55449e4c49fdc6b', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 7, 'Nofitahinao aho, Jehovah ô, ka voafitaka. Nampiasa ny herinao tamiko ianao, ka nandresy. Ataon’ny olona fihomehezana aho tontolo andro. Esoin’izy rehetra aho.', 'nofitahinao aho, jehovah ô, ka voafitaka. nampiasa ny herinao tamiko ianao, ka nandresy. ataon’ny olona fihomehezana aho tontolo andro. esoin’izy rehetra aho.'),
  ('6ab25b9dd55449e4c49fdc67', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 3, 'Nasain’i Pasora nesorina teo amin’ilay gadra hazo anefa i Jeremia ny ampitson’iny. Dia hoy i Jeremia taminy: “Tsy Pasora intsony no iantsoan’i Jehovah anao, fa hoe Horohoro Hatraiza Hatraiza.', 'nasain’i pasora nesorina teo amin’ilay gadra hazo anefa i jeremia ny ampitson’iny. dia hoy i jeremia taminy: “tsy pasora intsony no iantsoan’i jehovah anao, fa hoe horohoro hatraiza hatraiza.'),
  ('6ab25b9dd55449e4c49fdc69', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 5, 'Homeko an’ireo fahavalony ny harena rehetra ato amin’ity tanàna ity, sy ny fananana sy ny zava-tsarobidy rehetra ato, ary ny harena rehetran’ireo mpanjakan’ny Joda. Dia horobain’ny fahavalony sy halainy ireny, ary hoentiny any Babylona.', 'homeko an’ireo fahavalony ny harena rehetra ato amin’ity tanàna ity, sy ny fananana sy ny zava-tsarobidy rehetra ato, ary ny harena rehetran’ireo mpanjakan’ny joda. dia horobain’ny fahavalony sy halainy ireny, ary hoentiny any babylona.'),
  ('6ab25b9dd55449e4c49fdc71', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 13, 'Mihirà ho an’i Jehovah! Miderà an’i Jehovah! Fa mamonjy ny mahantra avy eo an-tanan’ny mpanao ratsy izy.', 'mihirà ho an’i jehovah! miderà an’i jehovah! fa mamonjy ny mahantra avy eo an-tanan’ny mpanao ratsy izy.'),
  ('6ab25b9dd55449e4c49fdc76', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 18, 'Fa maninona re aho no tsy maintsy nivoaka avy tao an-kibo e, Mba hahita fijaliana sy alahelo, Ka hifarana amin-kenatra ny androm-piainako?', 'fa maninona re aho no tsy maintsy nivoaka avy tao an-kibo e, mba hahita fijaliana sy alahelo, ka hifarana amin-kenatra ny androm-piainako?'),
  ('6ab25b9dd55449e4c49fdc70', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 12, 'Ianao kosa anefa, Jehovah Tompon’ny tafika ô, no mandinika ny olo-marina! Hitanao ny eritreritra lalina indrindra sy ny fo. Avelao aho hahita ny hamalianao azy ireny, Satria ianao no nanankinako ny ady nataoko teny amin’ny fitsarana!', 'ianao kosa anefa, jehovah tompon’ny tafika ô, no mandinika ny olo-marina! hitanao ny eritreritra lalina indrindra sy ny fo. avelao aho hahita ny hamalianao azy ireny, satria ianao no nanankinako ny ady nataoko teny amin’ny fitsarana!'),
  ('6ab25b9dd55449e4c49fdc6a', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 6, 'Ary ianao kosa, ry Pasora, ho lasa babo ianao sy izay rehetra mipetraka ao an-tranonao. Ho lasa any Babylona ianao ka ho faty any, ary halevina any miaraka amin’ny namanao rehetra, noho ianao naminany lainga tamin’izy ireo.’”', 'ary ianao kosa, ry pasora, ho lasa babo ianao sy izay rehetra mipetraka ao an-tranonao. ho lasa any babylona ianao ka ho faty any, ary halevina any miaraka amin’ny namanao rehetra, noho ianao naminany lainga tamin’izy ireo.’”'),
  ('6ab25b9dd55449e4c49fdc68', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 4, 'Fa izao no lazain’i Jehovah: ‘Hataoko mihorohoro ianao sy ny namanao rehetra, rehefa mahita an’izay hanjo anao. Hovonoin’ny fahavalony amin’ny sabatra izy ireo, ary hahita an’izany ny masonao. Hataoko resin’ny mpanjakan’i Babylona koa ny Joda rehetra, ka hataony sesitany any Babylona ary hovonoiny amin’ny sabatra.', 'fa izao no lazain’i jehovah: ‘hataoko mihorohoro ianao sy ny namanao rehetra, rehefa mahita an’izay hanjo anao. hovonoin’ny fahavalony amin’ny sabatra izy ireo, ary hahita an’izany ny masonao. hataoko resin’ny mpanjakan’i babylona koa ny joda rehetra, ka hataony sesitany any babylona ary hovonoiny amin’ny sabatra.'),
  ('6ab25b9dd55449e4c49fdc75', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 17, 'Fa maninona aho no tsy novonoiny tany an-kibo, Mba ho lasa fasako i Neny Ka ho bevohoka ahy eny foana?', 'fa maninona aho no tsy novonoiny tany an-kibo, mba ho lasa fasako i neny ka ho bevohoka ahy eny foana?'),
  ('6ab25b9dd55449e4c49fdc72', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 14, 'Ho voaozona anie ny andro nahaterahako! Tsy hotahina anie ny andro niterahan’i Neny ahy!', 'ho voaozona anie ny andro nahaterahako! tsy hotahina anie ny andro niterahan’i neny ahy!'),
  ('6ab25b9dd55449e4c49fdc6f', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 11, 'Teo akaikiko teo toy ny miaramila mampahatahotra anefa i Jehovah, Ka ho tafintohina sy tsy haharesy ireo mpanenjika ahy. Ho menatra be izy ireo satria tsy hahavoa. Ho afa-baraka mandrakizay izy ireo, ary tsy hohadinoina mihitsy izany.', 'teo akaikiko teo toy ny miaramila mampahatahotra anefa i jehovah, ka ho tafintohina sy tsy haharesy ireo mpanenjika ahy. ho menatra be izy ireo satria tsy hahavoa. ho afa-baraka mandrakizay izy ireo, ary tsy hohadinoina mihitsy izany.'),
  ('6ab25b9dd55449e4c49fdc66', '2026-09-22T10:42:37.034Z', '2026-09-22T10:42:37.034Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 20, 2, 'Dia nikapoka an’i Jeremia mpaminany izy ary nanagadra azy tamin’ny gadra hazo, teo amin’ny Vavahadin’i Benjamina, dia ilay vavahady ambony mankao amin’ny tranon’i Jehovah.', 'dia nikapoka an’i jeremia mpaminany izy ary nanagadra azy tamin’ny gadra hazo, teo amin’ny vavahadin’i benjamina, dia ilay vavahady ambony mankao amin’ny tranon’i jehovah.'),
  ('6ab25b9d294860eb4164155c', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 8, '“Ary lazao amin’ity vahoaka ity hoe: ‘Izao no tenin’i Jehovah: “Ataoko eo anoloanareo ny lalan’ny fiainana sy ny lalan’ny fahafatesana.', '“ary lazao amin’ity vahoaka ity hoe: ‘izao no tenin’i jehovah: “ataoko eo anoloanareo ny lalan’ny fiainana sy ny lalan’ny fahafatesana.'),
  ('6ab25b9d294860eb41641561', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 13, '‘Hiady aminao aho, ry ilay mipetraka eo amin’ny lohasaha, Ry ilay vatolampy eny amin’ny tany lemaka’, hoy i Jehovah. ‘Ary ianareo izay milaza hoe: “Iza no hidina hiady aminay? Iza no hanafika ny fonenanay?”,', '‘hiady aminao aho, ry ilay mipetraka eo amin’ny lohasaha, ry ilay vatolampy eny amin’ny tany lemaka’, hoy i jehovah. ‘ary ianareo izay milaza hoe: “iza no hidina hiady aminay? iza no hanafika ny fonenanay?”,'),
  ('6ab25b9d294860eb4164155a', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 6, 'Hamely an’izay monina eto amin’ity tanàna ity aho, na olona izany na biby. Ho fatin’ny areti-mandringana tena mahery izy ireo.”’', 'hamely an’izay monina eto amin’ity tanàna ity aho, na olona izany na biby. ho fatin’ny areti-mandringana tena mahery izy ireo.”’'),
  ('6ab25b9d294860eb41641558', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 4, '‘Izao no tenin’i Jehovah Andriamanitry ny Israely: “Ataoko mifotitra aminareo ny fitaovam-piadiana eny an-tananareo, dia izay ampiasainareo mba hiadiana amin’ny mpanjakan’i Babylona sy ny Kaldeanina manao fahirano anareo any ivelan’ny manda. Hangoniko eo afovoan’ity tanàna ity izy ireny.', '‘izao no tenin’i jehovah andriamanitry ny israely: “ataoko mifotitra aminareo ny fitaovam-piadiana eny an-tananareo, dia izay ampiasainareo mba hiadiana amin’ny mpanjakan’i babylona sy ny kaldeanina manao fahirano anareo any ivelan’ny manda. hangoniko eo afovoan’ity tanàna ity izy ireny.'),
  ('6ab25b9d294860eb41641555', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 1, 'Nahazo hafatra avy tamin’i Jehovah i Jeremia, rehefa nirahin’i Zedekia Mpanjaka ho any aminy i Pasora zanak’i Malkia sy Zefania mpisorona zanak’i Mahaseia, mba hilaza hoe:', 'nahazo hafatra avy tamin’i jehovah i jeremia, rehefa nirahin’i zedekia mpanjaka ho any aminy i pasora zanak’i malkia sy zefania mpisorona zanak’i mahaseia, mba hilaza hoe:'),
  ('6ab25b9d294860eb4164155e', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 10, '“‘“Fa manohitra an’ity tanàna ity aho ka loza no hahazo azy fa tsy zava-tsoa”, hoy i Jehovah. “Hataoko resin’ny mpanjakan’i Babylona ity tanàna ity, dia hodorany.”', '“‘“fa manohitra an’ity tanàna ity aho ka loza no hahazo azy fa tsy zava-tsoa”, hoy i jehovah. “hataoko resin’ny mpanjakan’i babylona ity tanàna ity, dia hodorany.”'),
  ('6ab25b9d294860eb41641557', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 3, 'Hoy i Jeremia tamin’izy roa lahy: “Lazao amin’i Zedekia hoe:', 'hoy i jeremia tamin’izy roa lahy: “lazao amin’i zedekia hoe:'),
  ('6ab25b9d294860eb41641556', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 2, '“Mba anontanio i Jehovah hoe inona no hitranga amintsika, fa miady amintsika i Nebokadnezara mpanjakan’i Babylona. Angamba hanao zavatra iray mahatalanjona ho antsika indray i Jehovah hoatran’ny efa nataony, mba hialan’i Nebokadnezara eto amintsika.”', '“mba anontanio i jehovah hoe inona no hitranga amintsika, fa miady amintsika i nebokadnezara mpanjakan’i babylona. angamba hanao zavatra iray mahatalanjona ho antsika indray i jehovah hoatran’ny efa nataony, mba hialan’i nebokadnezara eto amintsika.”'),
  ('6ab25b9d294860eb41641560', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 12, 'Ry taranak’i Davida ô, izao no lazain’i Jehovah: “Manaova foana ny rariny isa-maraina, Ary vonjeo eo an-tanan’ilay nanambaka azy izay nambakaina, Sao hirehitra toy ny afo ny fahatezerako Ka hiredareda nefa tsy hisy hamono, Noho ny ratsy nataonareo.”’', 'ry taranak’i davida ô, izao no lazain’i jehovah: “manaova foana ny rariny isa-maraina, ary vonjeo eo an-tanan’ilay nanambaka azy izay nambakaina, sao hirehitra toy ny afo ny fahatezerako ka hiredareda nefa tsy hisy hamono, noho ny ratsy nataonareo.”’'),
  ('6ab25b9d294860eb41641559', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 5, 'Dia izaho mihitsy no hiady aminareo ka hanatsotra ny tanako sy hampiasa ny sandriko mahery, sady ho tezitra sy ho vinitra ary hisafoaka aminareo.', 'dia izaho mihitsy no hiady aminareo ka hanatsotra ny tanako sy hampiasa ny sandriko mahery, sady ho tezitra sy ho vinitra ary hisafoaka aminareo.'),
  ('6ab25b9d294860eb41641562', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 14, 'Hataoko ampamoaka ianareo Noho izay nataonareo’, hoy i Jehovah. ‘Ary hodorako ny alany, Ka ho levon’ny afo ny zava-drehetra manodidina azy.’”', 'hataoko ampamoaka ianareo noho izay nataonareo’, hoy i jehovah. ‘ary hodorako ny alany, ka ho levon’ny afo ny zava-drehetra manodidina azy.’”'),
  ('6ab25b9d294860eb4164155b', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 7, '“‘“Aorian’izany”, hoy i Jehovah, “dia izao no hataoko amin’i Zedekia mpanjakan’ny Joda sy ny mpanompony ary ny vahoaka ato amin’ity tanàna ity, dia ireo tsy matin’ny areti-mandringana sy ny sabatra ary ny mosary: Hataoko resin’i Nebokadnezara mpanjakan’i Babylona izy ireo, ary hataoko resin’ny fahavalony sy ireo mitady hamono azy. Hamely azy ireo amin’ny sabatra i Nebokadnezara. Tsy hiantra izy na hangoraka na hamindra fo.”’', '“‘“aorian’izany”, hoy i jehovah, “dia izao no hataoko amin’i zedekia mpanjakan’ny joda sy ny mpanompony ary ny vahoaka ato amin’ity tanàna ity, dia ireo tsy matin’ny areti-mandringana sy ny sabatra ary ny mosary: hataoko resin’i nebokadnezara mpanjakan’i babylona izy ireo, ary hataoko resin’ny fahavalony sy ireo mitady hamono azy. hamely azy ireo amin’ny sabatra i nebokadnezara. tsy hiantra izy na hangoraka na hamindra fo.”’'),
  ('6ab25b9d294860eb4164155f', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 11, '“‘Henoy ny tenin’i Jehovah, ry ankohonan’ny mpanjakan’ny Joda.', '“‘henoy ny tenin’i jehovah, ry ankohonan’ny mpanjakan’ny joda.'),
  ('6ab25b9d294860eb4164155d', '2026-09-22T10:42:37.497Z', '2026-09-22T10:42:37.497Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 21, 9, 'Ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana izay mijanona ato amin’ity tanàna ity. Fa izay mivoaka kosa ka mitolo-batana any amin’ny Kaldeanina, izay manao fahirano anareo, dia tsy ho faty fa ny ainy no ho babony.”’', 'ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana izay mijanona ato amin’ity tanàna ity. fa izay mivoaka kosa ka mitolo-batana any amin’ny kaldeanina, izay manao fahirano anareo, dia tsy ho faty fa ny ainy no ho babony.”’'),
  ('6ab25b9e4208f8402839616b', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 22, 'Hopaohin’ny rivotra ireo mpiandry ondry rehetra ao aminao, Ary ho lasa babo ireo lehilahy niaraka taminao. Dia ho menatra sy ho afa-baraka ianao, noho ny loza rehetra hanjo anao.', 'hopaohin’ny rivotra ireo mpiandry ondry rehetra ao aminao, ary ho lasa babo ireo lehilahy niaraka taminao. dia ho menatra sy ho afa-baraka ianao, noho ny loza rehetra hanjo anao.'),
  ('6ab25b9e4208f8402839615c', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 7, 'Dia hanendry mpandrava hanafika anao aho. Samy hitondra ny fitaovam-piadiany izy ireny. Hokapainy ny hazo sedera tsara indrindra eo aminao, Dia hazerany ao anaty afo.', 'dia hanendry mpandrava hanafika anao aho. samy hitondra ny fitaovam-piadiany izy ireny. hokapainy ny hazo sedera tsara indrindra eo aminao, dia hazerany ao anaty afo.'),
  ('6ab25b9e4208f84028396166', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 17, '‘Ny masonao sy ny fonao kosa tsy mieritreritra afa-tsy ny haka tombony azo amin’ny tsy marina, Sy handatsaka ran’olona tsy manan-tsiny, Ary hanambaka sy haka an-keriny.’', '‘ny masonao sy ny fonao kosa tsy mieritreritra afa-tsy ny haka tombony azo amin’ny tsy marina, sy handatsaka ran’olona tsy manan-tsiny, ary hanambaka sy haka an-keriny.’'),
  ('6ab25b9e4208f84028396165', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 16, 'Niaro ny zon’ny olona mijaly sy ny mahantra izy, Ka nahita soa. ‘Tsy izany ve no atao hoe mahalala ahy?’, hoy i Jehovah.', 'niaro ny zon’ny olona mijaly sy ny mahantra izy, ka nahita soa. ‘tsy izany ve no atao hoe mahalala ahy?’, hoy i jehovah.'),
  ('6ab25b9e4208f8402839616c', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 23, 'Ry ilay mipetraka any Libàna, Izay manao akany eny amin’ny sedera, Hitaraindraina ianao rehefa manaintaina mafy, Manaintaina hoatran’ny vehivavy efa ho teraka!”', 'ry ilay mipetraka any libàna, izay manao akany eny amin’ny sedera, hitaraindraina ianao rehefa manaintaina mafy, manaintaina hoatran’ny vehivavy efa ho teraka!”'),
  ('6ab25b9e4208f8402839615f', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 10, 'Aza mitomany an’ilay efa maty, Ary aza malahelo azy. Aoka kosa ianareo hitomany be an’ilay handeha, Satria tsy hiverina intsony izy ka tsy hahita an’ilay tany nahaterahany.', 'aza mitomany an’ilay efa maty, ary aza malahelo azy. aoka kosa ianareo hitomany be an’ilay handeha, satria tsy hiverina intsony izy ka tsy hahita an’ilay tany nahaterahany.'),
  ('6ab25b9e4208f84028396156', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 1, 'Izao no lazain’i Jehovah: “Midìna any an-tranon’ny mpanjakan’ny Joda, ka lazao any ity hafatra ity.', 'izao no lazain’i jehovah: “midìna any an-tranon’ny mpanjakan’ny joda, ka lazao any ity hafatra ity.'),
  ('6ab25b9e4208f84028396170', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 27, 'Tsy ho tafaverina intsony ao amin’ilay tany iriny hiverenana izy ireo.', 'tsy ho tafaverina intsony ao amin’ilay tany iriny hiverenana izy ireo.'),
  ('6ab25b9e4208f84028396159', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 4, 'Fa raha tena mankatò an’izany teny izany ianareo, dia hiditra amin’ny vavahadin’ity trano ity ireo mpanjaka mipetraka eo amin’ny seza fiandrianan’i Davida. Ary hitaingina kalesy sy soavaly izy ireo sy ny mpanompony ary ny vahoakany, amin’izany fotoana izany.”’', 'fa raha tena mankatò an’izany teny izany ianareo, dia hiditra amin’ny vavahadin’ity trano ity ireo mpanjaka mipetraka eo amin’ny seza fiandrianan’i davida. ary hitaingina kalesy sy soavaly izy ireo sy ny mpanompony ary ny vahoakany, amin’izany fotoana izany.”’'),
  ('6ab25b9e4208f84028396158', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 3, 'Izao no lazain’i Jehovah: “Manaova ny rariny sy ny hitsiny. Vonjeo eo an-tanan’ilay manambaka azy izay ambakaina. Aza mampijaly an’ireo hafa firenena monina eo aminareo, ary aza mampahory ny kamboty ray na ny mpitondratena. Aza mandatsaka ran’olona tsy manan-tsiny eto amin’ity toerana ity.', 'izao no lazain’i jehovah: “manaova ny rariny sy ny hitsiny. vonjeo eo an-tanan’ilay manambaka azy izay ambakaina. aza mampijaly an’ireo hafa firenena monina eo aminareo, ary aza mampahory ny kamboty ray na ny mpitondratena. aza mandatsaka ran’olona tsy manan-tsiny eto amin’ity toerana ity.'),
  ('6ab25b9e4208f84028396161', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 12, 'Fa ho faty any amin’ny toerana anaovana sesitany azy izy, ka tsy ho hitany intsony ity tany ity.’', 'fa ho faty any amin’ny toerana anaovana sesitany azy izy, ka tsy ho hitany intsony ity tany ity.’'),
  ('6ab25b9e4208f84028396168', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 19, 'Halevina toy ny fandevina ampondra izy, Ka hotaritaritina sy hariana Any ivelan’ny vavahadin’i Jerosalema.’', 'halevina toy ny fandevina ampondra izy, ka hotaritaritina sy hariana any ivelan’ny vavahadin’i jerosalema.’'),
  ('6ab25b9e4208f8402839616f', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 26, 'Ary hatsipiko any an-tany hafa tsy nahaterahanareo ianao sy ny reninao niteraka anao, ka any ianareo no ho faty.', 'ary hatsipiko any an-tany hafa tsy nahaterahanareo ianao sy ny reninao niteraka anao, ka any ianareo no ho faty.'),
  ('6ab25b9e4208f8402839615a', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 5, '“‘Raha tsy mankatò an’izany teny izany kosa ianareo, dia mianiana amin’ny tenako aho’, hoy i Jehovah, ‘fa ho rava ity trano ity.’', '“‘raha tsy mankatò an’izany teny izany kosa ianareo, dia mianiana amin’ny tenako aho’, hoy i jehovah, ‘fa ho rava ity trano ity.’'),
  ('6ab25b9e4208f8402839616e', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 25, 'Dia hatolotro eo an-tanan’ireo mitady hamono anao sy ireo atahoranao ianao, dia i Nebokadnezara mpanjakan’i Babylona sy ny Kaldeanina.', 'dia hatolotro eo an-tanan’ireo mitady hamono anao sy ireo atahoranao ianao, dia i nebokadnezara mpanjakan’i babylona sy ny kaldeanina.'),
  ('6ab25b9e4208f84028396171', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 28, 'Vilany natao tsinontsinona sy novakina ve ity lehilahy atao hoe Konia ity, Izany hoe fitaovana tsy misy mpitia? Nahoana izy sy ny taranany no natsipy Sy nariana any amin’ny tany tsy fantany?’', 'vilany natao tsinontsinona sy novakina ve ity lehilahy atao hoe konia ity, izany hoe fitaovana tsy misy mpitia? nahoana izy sy ny taranany no natsipy sy nariana any amin’ny tany tsy fantany?’'),
  ('6ab25b9e4208f84028396172', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 29, 'Ry tany ô! Ry tany ô! Ry tany ô! Henoy ny tenin’i Jehovah.', 'ry tany ô! ry tany ô! ry tany ô! henoy ny tenin’i jehovah.'),
  ('6ab25b9e4208f84028396164', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 15, 'Mbola hanjaka foana ve ianao satria hoe nampiasa hazo sedera betsaka kokoa noho ny hafa? Nihinana sy nisotro koa ny rainao, Nefa nanao ny rariny sy ny hitsiny izy, Ka nahita soa.', 'mbola hanjaka foana ve ianao satria hoe nampiasa hazo sedera betsaka kokoa noho ny hafa? nihinana sy nisotro koa ny rainao, nefa nanao ny rariny sy ny hitsiny izy, ka nahita soa.'),
  ('6ab25b9e4208f8402839615d', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 8, '“‘Firenena maro no handalo eo akaikin’ity tanàna ity ka hifanontany hoe: “Fa naninona àry no dia nataon’i Jehovah hoatr’izao ity tanàna lehibe ity?”', '“‘firenena maro no handalo eo akaikin’ity tanàna ity ka hifanontany hoe: “fa naninona àry no dia nataon’i jehovah hoatr’izao ity tanàna lehibe ity?”'),
  ('6ab25b9e4208f8402839615b', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 6, '“Fa izao no lazain’i Jehovah momba ny tranon’ny mpanjakan’ny Joda: ‘Hoatran’i Gileada ianao amiko Sady hoatran’ny tampon’i Libàna. Hataoko lasa tany efitra anefa ianao, Ary tsy hisy hipetraka ireo tanànanao.', '“fa izao no lazain’i jehovah momba ny tranon’ny mpanjakan’ny joda: ‘hoatran’i gileada ianao amiko sady hoatran’ny tampon’i libàna. hataoko lasa tany efitra anefa ianao, ary tsy hisy hipetraka ireo tanànanao.'),
  ('6ab25b9e4208f84028396157', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 2, 'Lazao hoe: ‘Henoy ny tenin’i Jehovah, ry mpanjakan’ny Joda mipetraka eo amin’ny seza fiandrianan’i Davida, dia ianao sy ny mpanomponao ary ny vahoakanao, izay miditra amin’ ireto vavahady ireto.', 'lazao hoe: ‘henoy ny tenin’i jehovah, ry mpanjakan’ny joda mipetraka eo amin’ny seza fiandrianan’i davida, dia ianao sy ny mpanomponao ary ny vahoakanao, izay miditra amin’ ireto vavahady ireto.'),
  ('6ab25b9e4208f84028396162', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 13, 'Hahita loza izay manorina trano nefa manao ny tsy marina, Ary manao efitra ambony nefa manao ny tsy rariny. Mampiasa olona izy nefa miasa maina fotsiny izy ireny, Fa tsy omeny karama.', 'hahita loza izay manorina trano nefa manao ny tsy marina, ary manao efitra ambony nefa manao ny tsy rariny. mampiasa olona izy nefa miasa maina fotsiny izy ireny, fa tsy omeny karama.'),
  ('6ab25b9e4208f84028396163', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 14, 'Hahita loza izay milaza hoe: ‘Hanao trano lehibe ho an’ny tenako aho, Dia trano misy efitra ambony rihana malalaka be. Hasiako varavarankely ilay izy, Ary hopetahako takela-kazo sedera, dia holokoako mena volon-daoranjy.’', 'hahita loza izay milaza hoe: ‘hanao trano lehibe ho an’ny tenako aho, dia trano misy efitra ambony rihana malalaka be. hasiako varavarankely ilay izy, ary hopetahako takela-kazo sedera, dia holokoako mena volon-daoranjy.’'),
  ('6ab25b9e4208f84028396173', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 30, 'Izao no lazain’i Jehovah: ‘Soraty ho toy ny hoe tsy manan-janaka io lehilahy io, Dia lehilahy tsy hahomby mihitsy mandritra ny androm-piainany. Fa tsy hisy amin’ny taranany hahavita Hipetraka eo amin’ny seza fiandrianan’i Davida sy hanjaka ao Joda indray.’”', 'izao no lazain’i jehovah: ‘soraty ho toy ny hoe tsy manan-janaka io lehilahy io, dia lehilahy tsy hahomby mihitsy mandritra ny androm-piainany. fa tsy hisy amin’ny taranany hahavita hipetraka eo amin’ny seza fiandrianan’i davida sy hanjaka ao joda indray.’”'),
  ('6ab25b9e4208f8402839615e', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 9, 'Dia hisy hamaly hoe: “Satria nivadika tamin’ny fifanekena nifanaovany tamin’i Jehovah Andriamaniny izy ireo, ka niankohoka tamin’ny andriamani-kafa sy nanompo an’ireny.”’', 'dia hisy hamaly hoe: “satria nivadika tamin’ny fifanekena nifanaovany tamin’i jehovah andriamaniny izy ireo, ka niankohoka tamin’ny andriamani-kafa sy nanompo an’ireny.”’'),
  ('6ab25b9e4208f8402839616d', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 24, '“‘Raha mbola velona koa aho’, hoy i Jehovah, ‘dia hotsoahako hiala eo an-tanako ianao, ry Konia zanak’i Joiakima, mpanjakan’ny Joda, na dia toy ny peratra fanombohan-kase eto amin’ny tanako ankavanana aza!', '“‘raha mbola velona koa aho’, hoy i jehovah, ‘dia hotsoahako hiala eo an-tanako ianao, ry konia zanak’i joiakima, mpanjakan’ny joda, na dia toy ny peratra fanombohan-kase eto amin’ny tanako ankavanana aza!'),
  ('6ab25b9e4208f8402839616a', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 21, 'Niteny anao aho tamin’ianao mbola niadana, Saingy hoy ianao: ‘Tsy hankatò aho.’ Efa izany no fanaonao hatramin’ianao mbola kely. Tsy nankatò ny teniko mantsy ianao.', 'niteny anao aho tamin’ianao mbola niadana, saingy hoy ianao: ‘tsy hankatò aho.’ efa izany no fanaonao hatramin’ianao mbola kely. tsy nankatò ny teniko mantsy ianao.'),
  ('6ab25b9e4208f84028396169', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 20, 'Miakara any Libàna ka miantsoantsoa, Ary ataovy heno any Basana ny feonao. Miantsoantsoa any Abarima, Satria ripaka daholo ireo lehilahy niaraka taminao.', 'miakara any libàna ka miantsoantsoa, ary ataovy heno any basana ny feonao. miantsoantsoa any abarima, satria ripaka daholo ireo lehilahy niaraka taminao.'),
  ('6ab25b9e4208f84028396160', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 11, '“Fa izao no lazain’i Jehovah momba an’i Saloma zanak’i Josia, dia ilay mpanjakan’ny Joda nandimby an’i Josia rainy sy niala teto amin’ity toerana ity: ‘Tsy hiverina atỳ intsony izy.', '“fa izao no lazain’i jehovah momba an’i saloma zanak’i josia, dia ilay mpanjakan’ny joda nandimby an’i josia rainy sy niala teto amin’ity toerana ity: ‘tsy hiverina atỳ intsony izy.'),
  ('6ab25b9e4208f84028396167', '2026-09-22T10:42:38.064Z', '2026-09-22T10:42:38.064Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 22, 18, '“Koa izao no lazain’i Jehovah momba an’i Joiakima zanak’i Josia, mpanjakan’ny Joda: ‘Tsy hisy hisaona azy, ka hiteny hoe: “Indrisy, ry rahalahiko! Indrisy, ry anabaviko!” Tsy hisy hisaona azy, ka hiteny hoe: “Indrisy, ry tompoko! Indrisy, ry ilay hajaina!”', '“koa izao no lazain’i jehovah momba an’i joiakima zanak’i josia, mpanjakan’ny joda: ‘tsy hisy hisaona azy, ka hiteny hoe: “indrisy, ry rahalahiko! indrisy, ry anabaviko!” tsy hisy hisaona azy, ka hiteny hoe: “indrisy, ry tompoko! indrisy, ry ilay hajaina!”'),
  ('6ab25b9eff4387290cf6b576', '2026-09-22T10:42:38.744Z', '2026-09-22T10:42:38.744Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 5, '“Henoy izao!”, hoy i Jehovah. “Ho avy ny andro hampipoirako tsimoka marina ho an’i Davida. Hisy mpanjaka hitondra eo amin’ilay tany. Ho lalin-tsaina izy ary hanao ny rariny sy ny hitsiny.', '“henoy izao!”, hoy i jehovah. “ho avy ny andro hampipoirako tsimoka marina ho an’i davida. hisy mpanjaka hitondra eo amin’ilay tany. ho lalin-tsaina izy ary hanao ny rariny sy ny hitsiny.'),
  ('6ab25b9eff4387290cf6b573', '2026-09-22T10:42:38.744Z', '2026-09-22T10:42:38.744Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 2, 'Izao àry no lazain’i Jehovah Andriamanitry ny Israely mba hanamelohana an’ireo mpiandry izay miandry ny vahoakany: “Aparitakareo ny ondriko. Aelinareo izy ireo, fa tsy karakarainareo.” “Koa tsy hananako antra ianareo noho ny ratsy nataonareo”, hoy i Jehovah.', 'izao àry no lazain’i jehovah andriamanitry ny israely mba hanamelohana an’ireo mpiandry izay miandry ny vahoakany: “aparitakareo ny ondriko. aelinareo izy ireo, fa tsy karakarainareo.” “koa tsy hananako antra ianareo noho ny ratsy nataonareo”, hoy i jehovah.'),
  ('6ab25b9eff4387290cf6b572', '2026-09-22T10:42:38.744Z', '2026-09-22T10:42:38.744Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 1, '“Hahita loza ireo mpiandry ondry mandripaka sy manaparitaka ny ondry ao an-kijanako!”, hoy i Jehovah.', '“hahita loza ireo mpiandry ondry mandripaka sy manaparitaka ny ondry ao an-kijanako!”, hoy i jehovah.'),
  ('6ab25b9eff4387290cf6b575', '2026-09-22T10:42:38.744Z', '2026-09-22T10:42:38.744Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 4, 'Ary hanendry mpiandry izay tena hiandry azy ireo aho. Tsy hatahotra intsony izy ireo na hihorohoro, ary tsy hisy ho very na iray aza”, hoy i Jehovah.', 'ary hanendry mpiandry izay tena hiandry azy ireo aho. tsy hatahotra intsony izy ireo na hihorohoro, ary tsy hisy ho very na iray aza”, hoy i jehovah.'),
  ('6ab25b9eff4387290cf6b574', '2026-09-22T10:42:38.744Z', '2026-09-22T10:42:38.744Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 3, '“Dia hangoniko avy any amin’ny tany rehetra nanaparitahako azy ny ondriko sisa, ka haveriko ao amin’ny kijanany. Ho maro anaka sy hihabetsaka izy ireo.', '“dia hangoniko avy any amin’ny tany rehetra nanaparitahako azy ny ondriko sisa, ka haveriko ao amin’ny kijanany. ho maro anaka sy hihabetsaka izy ireo.'),
  ('6ab25b9eff4387290cf6b597', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 38, 'Ary raha mbola milaza ianareo hoe: “Ny enta-mavesatr’i Jehovah!”, dia izao kosa no lazain’i Jehovah: “Koa satria nilaza ianareo hoe: ‘Izany teny izany ilay enta-mavesatr’i Jehovah’, nefa izaho efa niteny taminareo hoe: ‘Tsy tokony hilaza intsony ianareo hoe: “Enta-mavesatr’i Jehovah!”’,', 'ary raha mbola milaza ianareo hoe: “ny enta-mavesatr’i jehovah!”, dia izao kosa no lazain’i jehovah: “koa satria nilaza ianareo hoe: ‘izany teny izany ilay enta-mavesatr’i jehovah’, nefa izaho efa niteny taminareo hoe: ‘tsy tokony hilaza intsony ianareo hoe: “enta-mavesatr’i jehovah!”’,'),
  ('6ab25b9eff4387290cf6b595', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 36, 'Tsy tokony hilaza intsony anefa ianareo hoe enta-mavesatr’i Jehovah, satria ny tenin’ny tsirairay ihany no enta-mavesatra. Novanareo ny tenin’ilay Andriamanitra velona, dia i Jehovah Tompon’ny tafika sady Andriamanitsika.', 'tsy tokony hilaza intsony anefa ianareo hoe enta-mavesatr’i jehovah, satria ny tenin’ny tsirairay ihany no enta-mavesatra. novanareo ny tenin’ilay andriamanitra velona, dia i jehovah tompon’ny tafika sady andriamanitsika.'),
  ('6ab25b9eff4387290cf6b589', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 24, '“Misy olona afaka miafina ao amin’ny takona ve ka tsy ho hitako?”, hoy i Jehovah. “Tsy manerana ny lanitra sy ny tany ve aho?”, hoy i Jehovah.', '“misy olona afaka miafina ao amin’ny takona ve ka tsy ho hitako?”, hoy i jehovah. “tsy manerana ny lanitra sy ny tany ve aho?”, hoy i jehovah.'),
  ('6ab25b9eff4387290cf6b581', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 16, 'Izao no lazain’i Jehovah Tompon’ny tafika: “Aza mihaino ny tenin’ireo mpaminany milaza faminaniana aminareo. Mamitaka anareo fotsiny izy ireo. Fahitana avy ao am-pony no lazainy, Fa tsy avy amin’ny vavan’i Jehovah.', 'izao no lazain’i jehovah tompon’ny tafika: “aza mihaino ny tenin’ireo mpaminany milaza faminaniana aminareo. mamitaka anareo fotsiny izy ireo. fahitana avy ao am-pony no lazainy, fa tsy avy amin’ny vavan’i jehovah.'),
  ('6ab25b9eff4387290cf6b57b', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 10, 'Feno mpanitsakitsa-bady mantsy ilay tany. Misaona koa ilay tany satria voaozona, Ary maina ny kijana any an-tany efitra. Ratsy ny ataon’izy ireo, ary manampatra fahefana izy ireo.', 'feno mpanitsakitsa-bady mantsy ilay tany. misaona koa ilay tany satria voaozona, ary maina ny kijana any an-tany efitra. ratsy ny ataon’izy ireo, ary manampatra fahefana izy ireo.'),
  ('6ab25b9eff4387290cf6b57d', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 12, '“Koa halama sy ho maizina ny lalana izoran’izy ireo. Hisy hanosika izy ireo, ka ho lavo. Fa hahatonga loza aminy aho, Amin’ny taona hanasaziana azy”, hoy i Jehovah.', '“koa halama sy ho maizina ny lalana izoran’izy ireo. hisy hanosika izy ireo, ka ho lavo. fa hahatonga loza aminy aho, amin’ny taona hanasaziana azy”, hoy i jehovah.'),
  ('6ab25b9eff4387290cf6b596', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 37, '“Izao no holazainao amin’ilay mpaminany: ‘Inona no navalin’i Jehovah anao? Inona no nolazain’i Jehovah?', '“izao no holazainao amin’ilay mpaminany: ‘inona no navalin’i jehovah anao? inona no nolazain’i jehovah?'),
  ('6ab25b9eff4387290cf6b58d', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 28, 'Avelao hitantara ny nofiny izay mpaminany manonofy. Fa izay nanankinana ny teniko kosa, dia tokony ho ny teniko ihany no holazainy.” “Inona moa izay mololo raha oharina amin’ny voam-bary?”, hoy i Jehovah.', 'avelao hitantara ny nofiny izay mpaminany manonofy. fa izay nanankinana ny teniko kosa, dia tokony ho ny teniko ihany no holazainy.” “inona moa izay mololo raha oharina amin’ny voam-bary?”, hoy i jehovah.'),
  ('6ab25b9eff4387290cf6b58b', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 26, 'Mandra-pahoviana no mbola ho ao am-pon’ireo mpaminany ireo foana ny hoe haminany lainga? Mpaminany milaza fitaka izy ireo, ka izay ao am-pony fotsiny no lazainy.', 'mandra-pahoviana no mbola ho ao am-pon’ireo mpaminany ireo foana ny hoe haminany lainga? mpaminany milaza fitaka izy ireo, ka izay ao am-pony fotsiny no lazainy.'),
  ('6ab25b9eff4387290cf6b58a', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 25, '“Efa reko izay nolazain’ireo mpaminany maminany lainga amin’ny anarako hoe: ‘Nanonofy aho! Nanonofy aho!’', '“efa reko izay nolazain’ireo mpaminany maminany lainga amin’ny anarako hoe: ‘nanonofy aho! nanonofy aho!’'),
  ('6ab25b9eff4387290cf6b587', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 22, 'Raha nijoro teo amin’ireo olona akaiky ahy anefa izy ireo, Dia ho nataony izay handrenesan’ny vahoakako ny teniko, Ary ho nasainy niala tamin’ny lalan-dratsiny sy tamin’ny ratsy fanaony izy ireny.”', 'raha nijoro teo amin’ireo olona akaiky ahy anefa izy ireo, dia ho nataony izay handrenesan’ny vahoakako ny teniko, ary ho nasainy niala tamin’ny lalan-dratsiny sy tamin’ny ratsy fanaony izy ireny.”'),
  ('6ab25b9eff4387290cf6b590', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 31, 'Hoy koa i Jehovah: “Hosaziko ireo mpaminany mampiasa ny lelany hilazana hoe: ‘Izao no lazainy!’”', 'hoy koa i jehovah: “hosaziko ireo mpaminany mampiasa ny lelany hilazana hoe: ‘izao no lazainy!’”'),
  ('6ab25b9eff4387290cf6b58c', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 27, 'Mifampitantara ny nofiny izy ireo satria tiany hanadino ny anarako ny vahoakako, hoatran’ny razambeny izay nanadino ny anarako noho izy ireny nanompo an’i Bala.', 'mifampitantara ny nofiny izy ireo satria tiany hanadino ny anarako ny vahoakako, hoatran’ny razambeny izay nanadino ny anarako noho izy ireny nanompo an’i bala.'),
  ('6ab25b9eff4387290cf6b586', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 21, 'Tsy naniraka an’ireo mpaminany ireo aho, nefa nihazakazaka nanao an’izany izy ireo. Tsy niteny taminy aho nefa naminany izy ireo.', 'tsy naniraka an’ireo mpaminany ireo aho, nefa nihazakazaka nanao an’izany izy ireo. tsy niteny taminy aho nefa naminany izy ireo.'),
  ('6ab25b9eff4387290cf6b57c', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 11, '“Samy maloto na ny mpaminany na ny mpisorona. Na dia ao an-tranoko aza, dia ahitako ny faharatsian’izy ireo”, hoy i Jehovah.', '“samy maloto na ny mpaminany na ny mpisorona. na dia ao an-tranoko aza, dia ahitako ny faharatsian’izy ireo”, hoy i jehovah.'),
  ('6ab25b9eff4387290cf6b579', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 8, 'Fa izao kosa no holazaina: ‘Raha mbola velona koa i Jehovah, ilay namoaka sy nampody ny taranaky ny vahoakan’Israely avy tany amin’ilay tany any avaratra, sy avy tany amin’ny toerana rehetra nanaparitahako azy.’ Dia hipetraka ao amin’ny taniny izy ireo.”', 'fa izao kosa no holazaina: ‘raha mbola velona koa i jehovah, ilay namoaka sy nampody ny taranaky ny vahoakan’israely avy tany amin’ilay tany any avaratra, sy avy tany amin’ny toerana rehetra nanaparitahako azy.’ dia hipetraka ao amin’ny taniny izy ireo.”'),
  ('6ab25b9eff4387290cf6b598', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 39, 'dia hingaiko sy hariako tsy ho eo anatrehako ianareo sy ilay tanàna nomeko anareo sy ny razambenareo.', 'dia hingaiko sy hariako tsy ho eo anatrehako ianareo sy ilay tanàna nomeko anareo sy ny razambenareo.'),
  ('6ab25b9eff4387290cf6b593', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 34, 'Ary raha misy mpaminany na mpisorona na olona milaza hoe: ‘Izao no enta-mavesatr’i Jehovah!’, dia tsy hananako antra izany olona izany sy ny ankohonany.', 'ary raha misy mpaminany na mpisorona na olona milaza hoe: ‘izao no enta-mavesatr’i jehovah!’, dia tsy hananako antra izany olona izany sy ny ankohonany.'),
  ('6ab25b9eff4387290cf6b58f', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 30, '“Koa hosaziko”, hoy i Jehovah, “ireo mpaminany mifangalatra ny teniko.”', '“koa hosaziko”, hoy i jehovah, “ireo mpaminany mifangalatra ny teniko.”'),
  ('6ab25b9eff4387290cf6b594', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 35, 'Samy miteny amin’ny namanareo sy ny rahalahinareo avy ianareo hoe: ‘Inona no navalin’i Jehovah? Ary inona no nolazain’i Jehovah?’', 'samy miteny amin’ny namanareo sy ny rahalahinareo avy ianareo hoe: ‘inona no navalin’i jehovah? ary inona no nolazain’i jehovah?’'),
  ('6ab25b9eff4387290cf6b584', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 19, 'Hifofofofo toy ny tafio-drivotra ny fahatezeran’i Jehovah. Ho toy ny rivo-mahery hihodinkodina eo amin’ny lohan’ny ratsy fanahy izany.', 'hifofofofo toy ny tafio-drivotra ny fahatezeran’i jehovah. ho toy ny rivo-mahery hihodinkodina eo amin’ny lohan’ny ratsy fanahy izany.'),
  ('6ab25b9eff4387290cf6b578', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 7, '“Ho avy anefa ny andro”, hoy i Jehovah, “izay tsy hilazana intsony hoe: ‘Raha mbola velona koa i Jehovah, ilay namoaka ny vahoakan’Israely avy tany Ejipta!’', '“ho avy anefa ny andro”, hoy i jehovah, “izay tsy hilazana intsony hoe: ‘raha mbola velona koa i jehovah, ilay namoaka ny vahoakan’israely avy tany ejipta!’'),
  ('6ab25b9eff4387290cf6b588', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 23, '“Rehefa akaiky ihany angaha izaho vao Andriamanitra”, hoy i Jehovah, “fa tsy rehefa lavitra koa?”', '“rehefa akaiky ihany angaha izaho vao andriamanitra”, hoy i jehovah, “fa tsy rehefa lavitra koa?”'),
  ('6ab25b9eff4387290cf6b57f', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 14, 'Hitako koa ny zavatra mahatsiravina ataon’ireo mpaminanin’i Jerosalema. Manitsakitsa-bady sy mandainga izy ireo, Ary manohana an’ireo mpanao ratsy. Tsy misy miala amin’ny ratsy fanaony izy ireo. Hoatran’i Sodoma daholo izy ireo amiko, Ary hoatran’i Gomora ny mponina ao.”', 'hitako koa ny zavatra mahatsiravina ataon’ireo mpaminanin’i jerosalema. manitsakitsa-bady sy mandainga izy ireo, ary manohana an’ireo mpanao ratsy. tsy misy miala amin’ny ratsy fanaony izy ireo. hoatran’i sodoma daholo izy ireo amiko, ary hoatran’i gomora ny mponina ao.”'),
  ('6ab25b9eff4387290cf6b577', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 6, 'Hovonjena ny Joda ary hilamina ny tanin’ny Israely amin’ny androny. Ary izao no anarana hiantsoana azy: I Jehovah no Fahamarinantsika.”', 'hovonjena ny joda ary hilamina ny tanin’ny israely amin’ny androny. ary izao no anarana hiantsoana azy: i jehovah no fahamarinantsika.”'),
  ('6ab25b9eff4387290cf6b599', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 40, 'Hataoko menatra sy afa-baraka mandrakizay ianareo, ary tsy hohadinoina mihitsy izany.”’”', 'hataoko menatra sy afa-baraka mandrakizay ianareo, ary tsy hohadinoina mihitsy izany.”’”'),
  ('6ab25b9eff4387290cf6b592', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 33, '“Ary raha manontany anao ity vahoaka ity na ny mpaminany na ny mpisorona hoe: ‘Inona no enta-mavesatr’i Jehovah?’, dia valio hoe: ‘“Ianareo no enta-mavesatra! Koa hariako ianareo”, hoy i Jehovah.’', '“ary raha manontany anao ity vahoaka ity na ny mpaminany na ny mpisorona hoe: ‘inona no enta-mavesatr’i jehovah?’, dia valio hoe: ‘“ianareo no enta-mavesatra! koa hariako ianareo”, hoy i jehovah.’'),
  ('6ab25b9eff4387290cf6b585', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 20, 'Tsy hitony ny fahatezeran’i Jehovah Raha tsy efa vitany sy tanterany ny fikasan’ny fony. Ho azonareo tsara izany any am-parany.', 'tsy hitony ny fahatezeran’i jehovah raha tsy efa vitany sy tanterany ny fikasan’ny fony. ho azonareo tsara izany any am-parany.'),
  ('6ab25b9eff4387290cf6b583', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 18, 'Fa iza no nijoro teo amin’ireo olona akaiky an’i Jehovah Mba hahita sy handre ny teniny? Iza no nanongilan-tsofina mba hihaino ny teniny?', 'fa iza no nijoro teo amin’ireo olona akaiky an’i jehovah mba hahita sy handre ny teniny? iza no nanongilan-tsofina mba hihaino ny teniny?'),
  ('6ab25b9eff4387290cf6b57e', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 13, '“Hitako ny zavatra maharikoriko ataon’ireo mpaminanin’i Samaria. Maminany amin’ny anaran’i Bala izy ireo, Ary mitarika ny Israely vahoakako any amin’ny lalan-diso.', '“hitako ny zavatra maharikoriko ataon’ireo mpaminanin’i samaria. maminany amin’ny anaran’i bala izy ireo, ary mitarika ny israely vahoakako any amin’ny lalan-diso.'),
  ('6ab25b9eff4387290cf6b580', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 15, 'Izao àry no lazain’i Jehovah Tompon’ny tafika mba hanamelohana an’ireo mpaminany ireo: “Hampihinaniko zavamaniry mangidy be izy ireo, Ary hampisotroiko rano misy poizina. Fa miely eran’ilay tany ny fivadiham-pinoana, noho ny ataon’ireo mpaminanin’i Jerosalema.”', 'izao àry no lazain’i jehovah tompon’ny tafika mba hanamelohana an’ireo mpaminany ireo: “hampihinaniko zavamaniry mangidy be izy ireo, ary hampisotroiko rano misy poizina. fa miely eran’ilay tany ny fivadiham-pinoana, noho ny ataon’ireo mpaminanin’i jerosalema.”'),
  ('6ab25b9eff4387290cf6b57a', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 9, 'Ary izao no lazaiko amin’ireo mpaminany: Torotoro ny foko ato anatiko. Mangozohozo daholo ny taolako. Hoatran’ny olona mamo aho, Ary toy ny lehilahy avembenan’ny divay, Noho ny amin’i Jehovah sy ny teniny masina.', 'ary izao no lazaiko amin’ireo mpaminany: torotoro ny foko ato anatiko. mangozohozo daholo ny taolako. hoatran’ny olona mamo aho, ary toy ny lehilahy avembenan’ny divay, noho ny amin’i jehovah sy ny teniny masina.'),
  ('6ab25b9eff4387290cf6b582', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 17, 'Izao no averimberiny amin’ireo tsy manaja ahy: ‘Izao no lazain’i Jehovah: “Hiadana ianareo.”’ Ary izay rehetra mikiry manao izay tian’ny fony kosa ataony hoe: ‘Tsy hisy loza hanjo anareo.’', 'izao no averimberiny amin’ireo tsy manaja ahy: ‘izao no lazain’i jehovah: “hiadana ianareo.”’ ary izay rehetra mikiry manao izay tian’ny fony kosa ataony hoe: ‘tsy hisy loza hanjo anareo.’'),
  ('6ab25b9eff4387290cf6b58e', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 29, '“Tsy hoatran’ny afo ve ny teniko”, hoy i Jehovah, “ary hoatran’ny marotoan’ny mpanefy, izay manapotipotika harambato?”', '“tsy hoatran’ny afo ve ny teniko”, hoy i jehovah, “ary hoatran’ny marotoan’ny mpanefy, izay manapotipotika harambato?”'),
  ('6ab25b9eff4387290cf6b591', '2026-09-22T10:42:38.745Z', '2026-09-22T10:42:38.745Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 23, 32, '“Hosaziko ireo mpaminany manonofy lainga sy mitantara an’izany”, hoy i Jehovah, “ka mitarika ny vahoakako any amin’ny lalan-diso noho izy ireo mandainga sy mirehareha.” “Tsy naniraka na nanome baiko azy ireo anefa aho. Koa tsy hahasoa an’ity vahoaka ity mihitsy izy ireo”, hoy i Jehovah.', '“hosaziko ireo mpaminany manonofy lainga sy mitantara an’izany”, hoy i jehovah, “ka mitarika ny vahoakako any amin’ny lalan-diso noho izy ireo mandainga sy mirehareha.” “tsy naniraka na nanome baiko azy ireo anefa aho. koa tsy hahasoa an’ity vahoaka ity mihitsy izy ireo”, hoy i jehovah.'),
  ('6ab25ba0813aeeb8bffe0b7e', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 20, 'ary ny hafa firenena rehetra ao amin’ny taniny; ny mpanjaka rehetran’i Oza; ny mpanjaka rehetran’ny Filistinina, Askelona, Gaza, Ekrona, ary izay sisa tavela ao Asdoda;', 'ary ny hafa firenena rehetra ao amin’ny taniny; ny mpanjaka rehetran’i oza; ny mpanjaka rehetran’ny filistinina, askelona, gaza, ekrona, ary izay sisa tavela ao asdoda;'),
  ('6ab25ba0813aeeb8bffe0b77', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 13, 'Hotanterahiko amin’izany tany izany ny teny rehetra nanamelohako azy, dia izay rehetra voasoratra ato amin’ity boky ity, araka ny faminaniana nambaran’i Jeremia mba hanamelohana ny firenena rehetra.', 'hotanterahiko amin’izany tany izany ny teny rehetra nanamelohako azy, dia izay rehetra voasoratra ato amin’ity boky ity, araka ny faminaniana nambaran’i jeremia mba hanamelohana ny firenena rehetra.'),
  ('6ab25ba0813aeeb8bffe0b75', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 11, 'Dia ho rava tanteraka ity tany manontolo ity ka hanjary hampihorohoro. Ary hanompo an’ilay mpanjakan’i Babylona mandritra ny 70 taona ireo firenena ireo.”’', 'dia ho rava tanteraka ity tany manontolo ity ka hanjary hampihorohoro. ary hanompo an’ilay mpanjakan’i babylona mandritra ny 70 taona ireo firenena ireo.”’'),
  ('6ab25ba0813aeeb8bffe0b6e', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 4, 'Ary nirahin’i Jehovah tany aminareo ny mpaminany mpanompony rehetra. Imbetsaka izy no naniraka azy ireny tany aminareo, nefa tsy nihaino ianareo na nanongilan-tsofina.', 'ary nirahin’i jehovah tany aminareo ny mpaminany mpanompony rehetra. imbetsaka izy no naniraka azy ireny tany aminareo, nefa tsy nihaino ianareo na nanongilan-tsofina.'),
  ('6ab25ba0813aeeb8bffe0b74', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 10, 'Hataoko tsy misy feon’olona mifaly sy miravoravo intsony eo amin’izy ireo, na feona mpampakatra sy ampakarina, na feona vato fikosoham-bary, na hazavan’ny jiro.', 'hataoko tsy misy feon’olona mifaly sy miravoravo intsony eo amin’izy ireo, na feona mpampakatra sy ampakarina, na feona vato fikosoham-bary, na hazavan’ny jiro.'),
  ('6ab25ba0813aeeb8bffe0b79', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 15, 'Fa izao no nolazain’i Jehovah Andriamanitry ny Israely tamiko: “Raiso etỳ an-tanako ity kaopy misy ny divain’ny fahatezerako ity, ka ampisotroy ny firenena rehetra anirahako anao.', 'fa izao no nolazain’i jehovah andriamanitry ny israely tamiko: “raiso etỳ an-tanako ity kaopy misy ny divain’ny fahatezerako ity, ka ampisotroy ny firenena rehetra anirahako anao.'),
  ('6ab25ba0813aeeb8bffe0b73', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 9, 'dia hampanantsoiko ny firenena rehetra any avaratra”, hoy i Jehovah. “Hampanantsoiko i Nebokadnezara mpanjakan’i Babylona sady mpanompoko. Hoentiko izy ireo ka hiady amin’ity tany ity sy ny mponina eto, ary amin’ireo firenena rehetra manodidina ireo. Dia haringako tanteraka ireo rehetra ireo ka hataoko mihorohoro sy misioka ny olona noho izay hanjo azy. Ary ho rava mandrakizay izy rehetra.', 'dia hampanantsoiko ny firenena rehetra any avaratra”, hoy i jehovah. “hampanantsoiko i nebokadnezara mpanjakan’i babylona sady mpanompoko. hoentiko izy ireo ka hiady amin’ity tany ity sy ny mponina eto, ary amin’ireo firenena rehetra manodidina ireo. dia haringako tanteraka ireo rehetra ireo ka hataoko mihorohoro sy misioka ny olona noho izay hanjo azy. ary ho rava mandrakizay izy rehetra.'),
  ('6ab25ba0813aeeb8bffe0b80', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 22, 'ny mpanjaka rehetran’i Tyro, ny mpanjaka rehetran’i Sidona, ary ireo mpanjakan’ilay nosy any an-dranomasina;', 'ny mpanjaka rehetran’i tyro, ny mpanjaka rehetran’i sidona, ary ireo mpanjakan’ilay nosy any an-dranomasina;'),
  ('6ab25ba0813aeeb8bffe0b6f', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 5, 'Nilaza ireny mpaminany ireny hoe: ‘Samia re miala amin’ny lalan-dratsinareo sy ny ratsy fanaonareo e! Amin’izay ianareo hipetraka ela ao amin’ilay tany nomen’i Jehovah anareo sy ny razambenareo efa hatramin’ny ela.', 'nilaza ireny mpaminany ireny hoe: ‘samia re miala amin’ny lalan-dratsinareo sy ny ratsy fanaonareo e! amin’izay ianareo hipetraka ela ao amin’ilay tany nomen’i jehovah anareo sy ny razambenareo efa hatramin’ny ela.'),
  ('6ab25ba0813aeeb8bffe0b7f', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 21, 'Edoma sy Moaba ary ny Amonita;', 'edoma sy moaba ary ny amonita;'),
  ('6ab25ba0813aeeb8bffe0b7c', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 18, 'Nanomboka tamin’i Jerosalema sy ireo tanànan’i Joda ary ny mpanjakany sy ny andrianany, mba ho rava tanteraka izy ireo, ka hihorohoro sy hisioka ny olona noho izay hanjo azy, ary mba hozonina izy ireo, hoatran’ny amin’izao androany izao.', 'nanomboka tamin’i jerosalema sy ireo tanànan’i joda ary ny mpanjakany sy ny andrianany, mba ho rava tanteraka izy ireo, ka hihorohoro sy hisioka ny olona noho izay hanjo azy, ary mba hozonina izy ireo, hoatran’ny amin’izao androany izao.'),
  ('6ab25ba0813aeeb8bffe0b6b', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 1, 'Nahazo hafatra momba ny vahoakan’ny Joda rehetra i Jeremia, tamin’ny taona fahefatra nanjakan’i Joiakima zanak’i Josia, mpanjakan’ny Joda, izany hoe tamin’ny taona voalohany nanjakan’i Nebokadnezara mpanjakan’i Babylona.', 'nahazo hafatra momba ny vahoakan’ny joda rehetra i jeremia, tamin’ny taona fahefatra nanjakan’i joiakima zanak’i josia, mpanjakan’ny joda, izany hoe tamin’ny taona voalohany nanjakan’i nebokadnezara mpanjakan’i babylona.'),
  ('6ab25ba0813aeeb8bffe0b7b', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 17, 'Koa nalaiko teny an-tanan’i Jehovah ilay kaopy dia nampisotroiko ny firenena rehetra nanirahan’i Jehovah ahy:', 'koa nalaiko teny an-tanan’i jehovah ilay kaopy dia nampisotroiko ny firenena rehetra nanirahan’i jehovah ahy:'),
  ('6ab25ba0813aeeb8bffe0b71', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 7, '“‘Tsy nihaino ahy anefa ianareo’, hoy i Jehovah. ‘Nampahatezitra ahy kosa ianareo noho ny asan’ny tananareo. Koa hahita loza ianareo.’', '“‘tsy nihaino ahy anefa ianareo’, hoy i jehovah. ‘nampahatezitra ahy kosa ianareo noho ny asan’ny tananareo. koa hahita loza ianareo.’'),
  ('6ab25ba0813aeeb8bffe0b78', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 14, 'Fa hataon’ny firenena maro sy mpanjaka lehibe lasa andevony izy ireo. Ary hovaliako araka izay nataony sy araka ny asan’ny tanany izy ireo.’”', 'fa hataon’ny firenena maro sy mpanjaka lehibe lasa andevony izy ireo. ary hovaliako araka izay nataony sy araka ny asan’ny tanany izy ireo.’”'),
  ('6ab25ba0813aeeb8bffe0b6d', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 3, '“Nandritra izay 23 taona izay i Jehovah no niteny tamiko, nanomboka tamin’ny taona faha-13 nanjakan’i Josia zanak’i Amona, mpanjakan’ny Joda, ka hatramin’izao. Ary efa niteny anareo imbetsaka aho, saingy tsy nihaino ianareo.', '“nandritra izay 23 taona izay i jehovah no niteny tamiko, nanomboka tamin’ny taona faha-13 nanjakan’i josia zanak’i amona, mpanjakan’ny joda, ka hatramin’izao. ary efa niteny anareo imbetsaka aho, saingy tsy nihaino ianareo.'),
  ('6ab25ba0813aeeb8bffe0b7a', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 16, 'Dia hisotro izy ireo ka hivembena sy hanao hoatran’ny adala, noho ny sabatra alefako hamely azy ireo.”', 'dia hisotro izy ireo ka hivembena sy hanao hoatran’ny adala, noho ny sabatra alefako hamely azy ireo.”'),
  ('6ab25ba0813aeeb8bffe0b6c', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 2, 'Izao no nolazain’i Jeremia mpaminany momba ny vahoakan’ny Joda rehetra sy ny mponina rehetra eto Jerosalema:', 'izao no nolazain’i jeremia mpaminany momba ny vahoakan’ny joda rehetra sy ny mponina rehetra eto jerosalema:'),
  ('6ab25ba0813aeeb8bffe0b70', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 6, 'Aza manaraka andriamani-kafa na manompo an’ireny na miankohoka aminy, ka hampahatezitra ahy amin’ny asan’ny tananareo. Raha tsy izany, dia hahatonga loza aminareo aho.’', 'aza manaraka andriamani-kafa na manompo an’ireny na miankohoka aminy, ka hampahatezitra ahy amin’ny asan’ny tananareo. raha tsy izany, dia hahatonga loza aminareo aho.’'),
  ('6ab25ba0813aeeb8bffe0b7d', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 19, 'Nampisotroiko koa avy eo i Farao mpanjakan’i Ejipta, ny mpanompony, ny andrianany, ny vahoakany rehetra,', 'nampisotroiko koa avy eo i farao mpanjakan’i ejipta, ny mpanompony, ny andrianany, ny vahoakany rehetra,'),
  ('6ab25ba0813aeeb8bffe0b76', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 12, '“‘Rehefa tapitra anefa ny 70 taona, dia hataoko ampamoaka ny mpanjakan’i Babylona sy izany firenena izany noho ny fahadisoany’, hoy i Jehovah. ‘Ary hataoko tsy misy mponina sy ngazana mandrakizay ny tanin’ny Kaldeanina.', '“‘rehefa tapitra anefa ny 70 taona, dia hataoko ampamoaka ny mpanjakan’i babylona sy izany firenena izany noho ny fahadisoany’, hoy i jehovah. ‘ary hataoko tsy misy mponina sy ngazana mandrakizay ny tanin’ny kaldeanina.'),
  ('6ab25ba0813aeeb8bffe0b72', '2026-09-22T10:42:40.457Z', '2026-09-22T10:42:40.457Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 8, '“Izao àry no lazain’i Jehovah Tompon’ny tafika: ‘“Noho ianareo tsy nankatò ny teniko,', '“izao àry no lazain’i jehovah tompon’ny tafika: ‘“noho ianareo tsy nankatò ny teniko,'),
  ('6ab25ba0813aeeb8bffe0b8e', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 36, 'Izany fa mitaraindraina ny mpiandry ondry, Ary midradradradra ny ondry vaventy, Fa simbain’i Jehovah ny kijanan’izy ireo.', 'izany fa mitaraindraina ny mpiandry ondry, ary midradradradra ny ondry vaventy, fa simbain’i jehovah ny kijanan’izy ireo.'),
  ('6ab25ba0813aeeb8bffe0b88', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 30, '“Ary hilaza an’izao faminaniana rehetra izao amin’izy ireo ianao: ‘Hierona avy any amin’ny avo i Jehovah, Ary hataony re avy any amin’ny fonenany masina ny feony. Hierona mafy amin’ny toerana ipetrahany izy. Hihorakoraka hoatran’ireo manitsakitsaka voaloboka ao anaty lavaka famiazana izy, Ary hihira rehefa resy ny mponina rehetra eto an-tany.’', '“ary hilaza an’izao faminaniana rehetra izao amin’izy ireo ianao: ‘hierona avy any amin’ny avo i jehovah, ary hataony re avy any amin’ny fonenany masina ny feony. hierona mafy amin’ny toerana ipetrahany izy. hihorakoraka hoatran’ireo manitsakitsaka voaloboka ao anaty lavaka famiazana izy, ary hihira rehefa resy ny mponina rehetra eto an-tany.’'),
  ('6ab25ba0813aeeb8bffe0b86', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 28, 'Ary raha tsy mety mandray an’ilay kaopy eny an-tananao izy ireo ka tsy mety misotro, dia lazao aminy hoe: ‘Izao no tenin’i Jehovah Tompon’ny tafika: “Tsy maintsy misotro an’ity ianareo!', 'ary raha tsy mety mandray an’ilay kaopy eny an-tananao izy ireo ka tsy mety misotro, dia lazao aminy hoe: ‘izao no tenin’i jehovah tompon’ny tafika: “tsy maintsy misotro an’ity ianareo!'),
  ('6ab25ba0813aeeb8bffe0b8b', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 33, '“‘Dia hiampatrampatra hatrany amin’ny faran’ny tany ka hatrany amin’ny faran’ny tany ny voavonon’i Jehovah, amin’izany andro izany. Tsy hisaonana na hangonina na halevina ireny, fa ho toy ny zezika eny ambonin’ny tany.’', '“‘dia hiampatrampatra hatrany amin’ny faran’ny tany ka hatrany amin’ny faran’ny tany ny voavonon’i jehovah, amin’izany andro izany. tsy hisaonana na hangonina na halevina ireny, fa ho toy ny zezika eny ambonin’ny tany.’'),
  ('6ab25ba0813aeeb8bffe0b8c', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 34, 'Midradradradrà, ry mpiandry ondry, ary aoka ianareo hitaraindraina! Mihosinkosena amin’ny tany, ry ondry vaventy, Satria tonga ny fotoana hamonoana sy hanaparitahana anareo, Ka hianjera toy ny vazy sarobidy ianareo!', 'midradradradrà, ry mpiandry ondry, ary aoka ianareo hitaraindraina! mihosinkosena amin’ny tany, ry ondry vaventy, satria tonga ny fotoana hamonoana sy hanaparitahana anareo, ka hianjera toy ny vazy sarobidy ianareo!'),
  ('6ab25ba0813aeeb8bffe0b8a', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 32, 'Izao no lazain’i Jehovah Tompon’ny tafika: ‘Henoy izao! Hisy loza hitety firenena, Ary hisy tafio-drivotra mahery hifofofofo avy any amin’ny faritra lavitra indrindra amin’ny tany.', 'izao no lazain’i jehovah tompon’ny tafika: ‘henoy izao! hisy loza hitety firenena, ary hisy tafio-drivotra mahery hifofofofo avy any amin’ny faritra lavitra indrindra amin’ny tany.'),
  ('6ab25ba0813aeeb8bffe0b8d', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 35, 'Tsy misy toerana handosirana ny mpiandry ondry, Ary tsy mahita hitsoahana ireo ondry vaventy.', 'tsy misy toerana handosirana ny mpiandry ondry, ary tsy mahita hitsoahana ireo ondry vaventy.'),
  ('6ab25ba0813aeeb8bffe0b85', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 27, '“Koa lazao amin’izy ireo hoe: ‘Izao no tenin’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Misotroa, manaova mamo, mandoava, ary mianjerà mba tsy ho tafatsangana intsony ianareo, noho ny sabatra alefako hamely anareo.”’', '“koa lazao amin’izy ireo hoe: ‘izao no tenin’i jehovah tompon’ny tafika, andriamanitry ny israely: “misotroa, manaova mamo, mandoava, ary mianjerà mba tsy ho tafatsangana intsony ianareo, noho ny sabatra alefako hamely anareo.”’'),
  ('6ab25ba0813aeeb8bffe0b84', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 26, 'ny mpanjaka rehetra any avaratra, na lavitra na akaiky, izay hifandimby hisotro an’ilay izy, ary ny fanjakana hafa rehetra eto ambonin’ny tany. Aorian’izy ireo, dia hisotro an’ilay izy koa ny mpanjakan’i Sesaka.', 'ny mpanjaka rehetra any avaratra, na lavitra na akaiky, izay hifandimby hisotro an’ilay izy, ary ny fanjakana hafa rehetra eto ambonin’ny tany. aorian’izy ireo, dia hisotro an’ilay izy koa ny mpanjakan’i sesaka.'),
  ('6ab25ba0813aeeb8bffe0b82', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 24, 'ny mpanjaka rehetran’ny Arabo sy ny mpanjaka rehetran’ny firenena hafa mipetraka any an-tany efitra;', 'ny mpanjaka rehetran’ny arabo sy ny mpanjaka rehetran’ny firenena hafa mipetraka any an-tany efitra;'),
  ('6ab25ba0813aeeb8bffe0b90', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 38, 'Nandao ny fonenany toy ny liona tanora izy. Fa lasa nihorohoro ny olona nahita an’izay nanjo ny tanin’izy ireo Satria nampiasaina tsy misy indrafo ny sabatra, Ary tezitra be izy.”', 'nandao ny fonenany toy ny liona tanora izy. fa lasa nihorohoro ny olona nahita an’izay nanjo ny tanin’izy ireo satria nampiasaina tsy misy indrafo ny sabatra, ary tezitra be izy.”'),
  ('6ab25ba0813aeeb8bffe0b8f', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 37, 'Tsy misy zavamananaina intsony ao amin’ireo fonenana nampiadana, Satria tezitra be i Jehovah.', 'tsy misy zavamananaina intsony ao amin’ireo fonenana nampiadana, satria tezitra be i jehovah.'),
  ('6ab25ba0813aeeb8bffe0b81', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 23, 'Dedana, Tema, Boza, ary izay rehetra nokakasana ny fihirifany;', 'dedana, tema, boza, ary izay rehetra nokakasana ny fihirifany;'),
  ('6ab25ba0813aeeb8bffe0b89', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 31, '‘Hisy feo hanakoako hatrany amin’ny faran’ny tany, Satria mifandahatra amin’ireo firenena i Jehovah. Izy mihitsy no hitsara ny olombelona rehetra. Ary hatolony hovonoina amin’ny sabatra ny ratsy fanahy’, hoy i Jehovah.', '‘hisy feo hanakoako hatrany amin’ny faran’ny tany, satria mifandahatra amin’ireo firenena i jehovah. izy mihitsy no hitsara ny olombelona rehetra. ary hatolony hovonoina amin’ny sabatra ny ratsy fanahy’, hoy i jehovah.'),
  ('6ab25ba0813aeeb8bffe0b87', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 29, 'Izao mantsy: Raha ilay tanàna mitondra ny anarako aza no voalohany amin’ireo hasiako loza, dia ianareo indray ve no ho afa-maina?”’ “‘Tsy ho afa-maina mihitsy ianareo, fa hiantso sabatra hamely ny mponina rehetra eto an-tany aho’, hoy i Jehovah Tompon’ny tafika.', 'izao mantsy: raha ilay tanàna mitondra ny anarako aza no voalohany amin’ireo hasiako loza, dia ianareo indray ve no ho afa-maina?”’ “‘tsy ho afa-maina mihitsy ianareo, fa hiantso sabatra hamely ny mponina rehetra eto an-tany aho’, hoy i jehovah tompon’ny tafika.'),
  ('6ab25ba0813aeeb8bffe0b83', '2026-09-22T10:42:40.458Z', '2026-09-22T10:42:40.458Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 25, 25, 'ny mpanjaka rehetran’i Zimry sy ny mpanjaka rehetran’i Elama ary ny mpanjaka rehetran’ny Medianina;', 'ny mpanjaka rehetran’i zimry sy ny mpanjaka rehetran’i elama ary ny mpanjaka rehetran’ny medianina;'),
  ('6ab25ba174116d08a0db50fa', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 14, 'Fa izaho kosa efa eto am-pelatananareo, ka ataovy amiko izay hitanareo fa tsara sy mety.', 'fa izaho kosa efa eto am-pelatananareo, ka ataovy amiko izay hitanareo fa tsara sy mety.'),
  ('6ab25ba174116d08a0db50f6', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 10, 'Rehefa nahare an’izany teny izany ny andrianan’ny Joda, dia niakatra avy any amin’ny tranon’ny mpanjaka mba hankany amin’ny tranon’i Jehovah. Ary nipetraka teo amin’ny fidirana amin’ilay vavahady vaovao amin’ny tranon’i Jehovah izy ireo.', 'rehefa nahare an’izany teny izany ny andrianan’ny joda, dia niakatra avy any amin’ny tranon’ny mpanjaka mba hankany amin’ny tranon’i jehovah. ary nipetraka teo amin’ny fidirana amin’ilay vavahady vaovao amin’ny tranon’i jehovah izy ireo.'),
  ('6ab25ba174116d08a0db50f4', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 8, 'Koa rehefa tapitra voalazan’i Jeremia daholo ny teny nasain’i Jehovah nolazainy tamin’ny vahoaka manontolo, dia nosamborin’ny mpisorona sy ny mpaminany ary ny vahoaka rehetra izy, ka hoy ireo: “Tena ho faty ianao!', 'koa rehefa tapitra voalazan’i jeremia daholo ny teny nasain’i jehovah nolazainy tamin’ny vahoaka manontolo, dia nosamborin’ny mpisorona sy ny mpaminany ary ny vahoaka rehetra izy, ka hoy ireo: “tena ho faty ianao!'),
  ('6ab25ba174116d08a0db5103', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 23, 'Koa nalain’izy ireo avy tany Ejipta i Oria, ary nentiny tany amin’i Joiakima Mpanjaka. Dia novonoin’ny mpanjaka tamin’ny sabatra izy ary natsipiny tany amin’ny fasam-bahoaka ny fatiny.”', 'koa nalain’izy ireo avy tany ejipta i oria, ary nentiny tany amin’i joiakima mpanjaka. dia novonoin’ny mpanjaka tamin’ny sabatra izy ary natsipiny tany amin’ny fasam-bahoaka ny fatiny.”'),
  ('6ab25ba174116d08a0db50fc', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 16, 'Dia hoy ny andriana sy ny vahoaka rehetra tamin’ireo mpisorona sy mpaminany: “Tsy mendrika ny homelohina ho faty io lehilahy io, satria tamin’ny anaran’i Jehovah Andriamanitsika no nitenenany tamintsika.”', 'dia hoy ny andriana sy ny vahoaka rehetra tamin’ireo mpisorona sy mpaminany: “tsy mendrika ny homelohina ho faty io lehilahy io, satria tamin’ny anaran’i jehovah andriamanitsika no nitenenany tamintsika.”'),
  ('6ab25ba174116d08a0db50f8', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 12, 'Dia hoy i Jeremia tamin’ny andriana rehetra sy ny vahoaka rehetra: “I Jehovah no naniraka ahy hilaza ny faminaniana rehetra henonareo teo, hoe hisy loza hanjo an’ity trano ity sy ity tanàna ity.', 'dia hoy i jeremia tamin’ny andriana rehetra sy ny vahoaka rehetra: “i jehovah no naniraka ahy hilaza ny faminaniana rehetra henonareo teo, hoe hisy loza hanjo an’ity trano ity sy ity tanàna ity.'),
  ('6ab25ba174116d08a0db50f2', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 6, 'dia hataoko hoatran’i Silo ity trano ity, ary hampiasa ny anaran’ity tanàna ity ny firenena rehetra eny ambonin’ny tany rehefa manozona.’”’”', 'dia hataoko hoatran’i silo ity trano ity, ary hampiasa ny anaran’ity tanàna ity ny firenena rehetra eny ambonin’ny tany rehefa manozona.’”’”'),
  ('6ab25ba174116d08a0db5102', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 22, 'Dia nirahin’i Joiakima Mpanjaka nankany Ejipta i Elnatana zanak’i Akbora sy ny lehilahy vitsivitsy .', 'dia nirahin’i joiakima mpanjaka nankany ejipta i elnatana zanak’i akbora sy ny lehilahy vitsivitsy .'),
  ('6ab25ba174116d08a0db50f1', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 5, 'sy tsy mihaino ny tenin’ny mpaminany mpanompoko izay nirahiko imbetsaka ho any aminareo nefa tsy nohenoinareo,', 'sy tsy mihaino ny tenin’ny mpaminany mpanompoko izay nirahiko imbetsaka ho any aminareo nefa tsy nohenoinareo,'),
  ('6ab25ba174116d08a0db50ef', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 3, 'Sao dia mba hihaino ihany izy ireo, ka samy hiala amin’ny ratsy fanaony. Dia hiova hevitra aho ka tsy hampihariko aminy indray ilay loza nokasaiko hamelezana azy ireo ho valin’ny ratsy nataony.', 'sao dia mba hihaino ihany izy ireo, ka samy hiala amin’ny ratsy fanaony. dia hiova hevitra aho ka tsy hampihariko aminy indray ilay loza nokasaiko hamelezana azy ireo ho valin’ny ratsy nataony.'),
  ('6ab25ba174116d08a0db50f7', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 11, 'Dia hoy ny mpisorona sy ny mpaminany tamin’ireo andriana sy ny vahoaka rehetra: “Mendrika ny homelohina ho faty ity lehilahy ity, satria naminany fa hisy loza hanjo an’ity tanàna ity. Ary ny sofinareo mihitsy no efa naheno an’izany.”', 'dia hoy ny mpisorona sy ny mpaminany tamin’ireo andriana sy ny vahoaka rehetra: “mendrika ny homelohina ho faty ity lehilahy ity, satria naminany fa hisy loza hanjo an’ity tanàna ity. ary ny sofinareo mihitsy no efa naheno an’izany.”'),
  ('6ab25ba174116d08a0db50f3', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 7, 'Nandre an’i Jeremia niteny an’ireo teny ireo tao an-tranon’i Jehovah ny mpisorona sy ny mpaminany ary ny vahoaka rehetra.', 'nandre an’i jeremia niteny an’ireo teny ireo tao an-tranon’i jehovah ny mpisorona sy ny mpaminany ary ny vahoaka rehetra.'),
  ('6ab25ba174116d08a0db5104', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 24, 'Narovan’i Ahikama zanak’i Safana kosa i Jeremia, ka tsy natolotra hovonoin’ny vahoaka.', 'narovan’i ahikama zanak’i safana kosa i jeremia, ka tsy natolotra hovonoin’ny vahoaka.'),
  ('6ab25ba174116d08a0db50ff', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 19, '“Namono an’i Mika ve i Hezekia mpanjakan’ny Joda sy ny Joda rehetra tamin’izay? Tsy natahotra an’i Jehovah ve i Hezekia ary nitalaho famindram-po tamin’i Jehovah, ka niova hevitra i Jehovah dia tsy nampihariny indray ilay loza efa nolazainy hamelezana azy ireo? Koa tena mitady loza mihitsy isika.', '“namono an’i mika ve i hezekia mpanjakan’ny joda sy ny joda rehetra tamin’izay? tsy natahotra an’i jehovah ve i hezekia ary nitalaho famindram-po tamin’i jehovah, ka niova hevitra i jehovah dia tsy nampihariny indray ilay loza efa nolazainy hamelezana azy ireo? koa tena mitady loza mihitsy isika.'),
  ('6ab25ba174116d08a0db50fd', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 17, 'Nitsangana koa ny anti-panahy sasany tao amin’ilay tany, ka niteny tamin’ny vahoaka rehetra tafavory teo hoe:', 'nitsangana koa ny anti-panahy sasany tao amin’ilay tany, ka niteny tamin’ny vahoaka rehetra tafavory teo hoe:'),
  ('6ab25ba174116d08a0db50fb', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 15, 'Fantaro tsara anefa fa raha mamono ahy ho faty ianareo, dia mamono olona tsy manan-tsiny, ka ho meloka ho nandatsa-dra ianareo sy ity tanàna ity ary ny mponina ato. I Jehovah mihitsy mantsy no naniraka ahy hilaza ny teny rehetra renareo teo!”', 'fantaro tsara anefa fa raha mamono ahy ho faty ianareo, dia mamono olona tsy manan-tsiny, ka ho meloka ho nandatsa-dra ianareo sy ity tanàna ity ary ny mponina ato. i jehovah mihitsy mantsy no naniraka ahy hilaza ny teny rehetra renareo teo!”'),
  ('6ab25ba174116d08a0db5100', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 20, '“Nisy lehilahy hafa koa naminany tamin’ny anaran’i Jehovah, dia i Oria zanak’i Semaia avy any Kiriata-jearima. Naminany hoatran’i Jeremia izy hoe hisy loza hanjo an’ity tanàna ity sy ity tany ity.', '“nisy lehilahy hafa koa naminany tamin’ny anaran’i jehovah, dia i oria zanak’i semaia avy any kiriata-jearima. naminany hoatran’i jeremia izy hoe hisy loza hanjo an’ity tanàna ity sy ity tany ity.'),
  ('6ab25ba174116d08a0db50ed', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 1, 'Izao no nolazain’i Jehovah, rehefa nanomboka nanjaka i Joiakima zanak’i Josia, mpanjakan’ny Joda:', 'izao no nolazain’i jehovah, rehefa nanomboka nanjaka i joiakima zanak’i josia, mpanjakan’ny joda:'),
  ('6ab25ba174116d08a0db5101', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 21, 'Nahare ny tenin’i Oria i Joiakima Mpanjaka sy ny miaramilany matanjaka rehetra ary ny andrianany rehetra. Koa nitady hamono azy ho faty ny mpanjaka. Natahotra i Oria raha vao naheno an’izany, ka nandositra nankany Ejipta.', 'nahare ny tenin’i oria i joiakima mpanjaka sy ny miaramilany matanjaka rehetra ary ny andrianany rehetra. koa nitady hamono azy ho faty ny mpanjaka. natahotra i oria raha vao naheno an’izany, ka nandositra nankany ejipta.'),
  ('6ab25ba174116d08a0db50f9', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 13, 'Koa ahitsio ny lalanareo sy ny ataonareo, ary ankatoavy ny tenin’i Jehovah Andriamanitrareo, dia hiova hevitra i Jehovah ka tsy hampihariny indray ilay loza efa nolazainy hamelezana anareo.', 'koa ahitsio ny lalanareo sy ny ataonareo, ary ankatoavy ny tenin’i jehovah andriamanitrareo, dia hiova hevitra i jehovah ka tsy hampihariny indray ilay loza efa nolazainy hamelezana anareo.'),
  ('6ab25ba174116d08a0db50f0', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 4, 'Lazao amin’izy ireo hoe: “Izao no tenin’i Jehovah: ‘Raha tsy mihaino ahy ianareo ka tsy manaraka ny lalàna nomeko anareo,', 'lazao amin’izy ireo hoe: “izao no tenin’i jehovah: ‘raha tsy mihaino ahy ianareo ka tsy manaraka ny lalàna nomeko anareo,'),
  ('6ab25ba174116d08a0db50ee', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 2, '“Izao no tenin’i Jehovah: ‘Mitsangàna eo an-tokotanin’ny tranon’i Jehovah, ary resaho ny momba ny mponina rehetra ao amin’ny tanànan’i Joda, izay ho avy hivavaka ao an-tranon’i Jehovah. Teneno azy daholo izay asaiko lazainao. Aza misy anesorana na teny iray aza.', '“izao no tenin’i jehovah: ‘mitsangàna eo an-tokotanin’ny tranon’i jehovah, ary resaho ny momba ny mponina rehetra ao amin’ny tanànan’i joda, izay ho avy hivavaka ao an-tranon’i jehovah. teneno azy daholo izay asaiko lazainao. aza misy anesorana na teny iray aza.'),
  ('6ab25ba174116d08a0db50f5', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 9, 'Nahoana ianao no maminany amin’ny anaran’i Jehovah hoe: ‘Ho lasa hoatran’i Silo ity trano ity, ary ity tanàna ity ho rava ka tsy hisy mponina intsony’?” Dia nitangoronan’ny olona rehetra i Jeremia, tao an-tranon’i Jehovah.', 'nahoana ianao no maminany amin’ny anaran’i jehovah hoe: ‘ho lasa hoatran’i silo ity trano ity, ary ity tanàna ity ho rava ka tsy hisy mponina intsony’?” dia nitangoronan’ny olona rehetra i jeremia, tao an-tranon’i jehovah.'),
  ('6ab25ba174116d08a0db50fe', '2026-09-22T10:42:41.085Z', '2026-09-22T10:42:41.085Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 26, 18, '“Naminany i Mika avy any Moreseta tamin’ny andron’i Hezekia mpanjakan’ny Joda, ka nilaza tamin’ny vahoakan’ny Joda rehetra hoe: ‘Izao no lazain’i Jehovah Tompon’ny tafika: “Hasaina hoatran’ny saha i Ziona, Ho lasa korontam-bato mivangongo i Jerosalema, Ary ny tendrombohitra misy an’ilay Trano dia ho toy ny toerana avo any an’ala.”’', '“naminany i mika avy any moreseta tamin’ny andron’i hezekia mpanjakan’ny joda, ka nilaza tamin’ny vahoakan’ny joda rehetra hoe: ‘izao no lazain’i jehovah tompon’ny tafika: “hasaina hoatran’ny saha i ziona, ho lasa korontam-bato mivangongo i jerosalema, ary ny tendrombohitra misy an’ilay trano dia ho toy ny toerana avo any an’ala.”’'),
  ('6ab25ba15bc78544e2222111', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 5, '‘Izaho no nanao ny tany sy ny olombelona ary ny biby eny ambonin’ny tany. Tamin’ny heriko lehibe sy ny sandriko mahery no nanaovako an’izany, ka izay tiako homena azy no omeko azy.', '‘izaho no nanao ny tany sy ny olombelona ary ny biby eny ambonin’ny tany. tamin’ny heriko lehibe sy ny sandriko mahery no nanaovako an’izany, ka izay tiako homena azy no omeko azy.'),
  ('6ab25ba15bc78544e2222120', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 20, 'izay tsy nalain’i Nebokadnezara mpanjakan’i Babylona rehefa nentiny niala teto Jerosalema sy nataony sesitany tany Babylona i Jekonia zanak’i Joiakima, mpanjakan’ny Joda, sy ny olona ambony rehetra teto Joda sy Jerosalema;', 'izay tsy nalain’i nebokadnezara mpanjakan’i babylona rehefa nentiny niala teto jerosalema sy nataony sesitany tany babylona i jekonia zanak’i joiakima, mpanjakan’ny joda, sy ny olona ambony rehetra teto joda sy jerosalema;'),
  ('6ab25ba15bc78544e2222117', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 11, '“‘“‘Fa izay firenena mampidina ny vozony ho eo ambany ziogan’ny mpanjakan’i Babylona sy manompo azy kosa, dia havelako hijanona ao amin’ny taniny’, hoy i Jehovah, ‘mba hamboly sy hipetraka ao.’”’”', '“‘“‘fa izay firenena mampidina ny vozony ho eo ambany ziogan’ny mpanjakan’i babylona sy manompo azy kosa, dia havelako hijanona ao amin’ny taniny’, hoy i jehovah, ‘mba hamboly sy hipetraka ao.’”’”'),
  ('6ab25ba15bc78544e2222122', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 22, '‘“Hoentina any Babylona ireny ary hajanona any mandra-pahatongan’ny andro hahatsiarovako azy”, hoy i Jehovah. “Dia hoentiko miverina avy any ireny, ka haveriko eto amin’ity toerana ity.”’”', '‘“hoentina any babylona ireny ary hajanona any mandra-pahatongan’ny andro hahatsiarovako azy”, hoy i jehovah. “dia hoentiko miverina avy any ireny, ka haveriko eto amin’ity toerana ity.”’”'),
  ('6ab25ba15bc78544e2222121', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 21, 'eny, izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely, momba an’ireo fitaovana sisa tavela ao an-tranon’i Jehovah sy ao an-tranon’ny mpanjakan’ny Joda ary eto Jerosalema:', 'eny, izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely, momba an’ireo fitaovana sisa tavela ao an-tranon’i jehovah sy ao an-tranon’ny mpanjakan’ny joda ary eto jerosalema:'),
  ('6ab25ba15bc78544e222211f', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 19, '“Izao mantsy no lazain’i Jehovah Tompon’ny tafika momba an’ireo andry, ny Ranomasina, ireo kalesy, ary ny fitaovana sisa tavela ato amin’ity tanàna ity,', '“izao mantsy no lazain’i jehovah tompon’ny tafika momba an’ireo andry, ny ranomasina, ireo kalesy, ary ny fitaovana sisa tavela ato amin’ity tanàna ity,'),
  ('6ab25ba15bc78544e222211c', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 16, 'Izao no nolazaiko tamin’ny mpisorona sy ny vahoaka rehetra: “Izao no tenin’i Jehovah: ‘Aza mihaino ny tenin’ireo mpaminany milaza aminareo hoe: “Jereo tsara fa ho tafaverina tsy ho ela avy any Babylona ny fitaovana tao an-tranon’i Jehovah!” Maminany lainga aminareo mantsy izy ireo.', 'izao no nolazaiko tamin’ny mpisorona sy ny vahoaka rehetra: “izao no tenin’i jehovah: ‘aza mihaino ny tenin’ireo mpaminany milaza aminareo hoe: “jereo tsara fa ho tafaverina tsy ho ela avy any babylona ny fitaovana tao an-tranon’i jehovah!” maminany lainga aminareo mantsy izy ireo.'),
  ('6ab25ba15bc78544e2222112', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 6, 'Koa efa nomeko an’i Nebokadnezara mpanjakan’i Babylona sady mpanompoko, ireo tany rehetra ireo. Na ny bibidia aza efa nomeko azy mba hanompo azy.', 'koa efa nomeko an’i nebokadnezara mpanjakan’i babylona sady mpanompoko, ireo tany rehetra ireo. na ny bibidia aza efa nomeko azy mba hanompo azy.'),
  ('6ab25ba15bc78544e222210d', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 1, 'Izao no tenin’i Jehovah tamin’i Jeremia, rehefa nanomboka nanjaka i Joiakima zanak’i Josia, mpanjakan’ny Joda:', 'izao no tenin’i jehovah tamin’i jeremia, rehefa nanomboka nanjaka i joiakima zanak’i josia, mpanjakan’ny joda:'),
  ('6ab25ba15bc78544e222211d', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 17, 'Aza mihaino azy, fa manompoa ny mpanjakan’i Babylona dia ho velona ianareo. Fa nahoana moa no dia ho rava ity tanàna ity?', 'aza mihaino azy, fa manompoa ny mpanjakan’i babylona dia ho velona ianareo. fa nahoana moa no dia ho rava ity tanàna ity?'),
  ('6ab25ba15bc78544e2222118', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 12, 'Izany koa no nolazaiko tamin’i Zedekia mpanjakan’ny Joda. Niteny taminy aho hoe: “Ampidino ho eo ambany ziogan’ny mpanjakan’i Babylona ny vozonareo, ka tompoy izy sy ny vahoakany, dia ho velona ianareo.', 'izany koa no nolazaiko tamin’i zedekia mpanjakan’ny joda. niteny taminy aho hoe: “ampidino ho eo ambany ziogan’ny mpanjakan’i babylona ny vozonareo, ka tompoy izy sy ny vahoakany, dia ho velona ianareo.'),
  ('6ab25ba15bc78544e222211e', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 18, 'Raha tena mpaminany anefa izy ireo ary ny tenin’i Jehovah tokoa no lazainy, dia aoka izy ireo hiangavy an’i Jehovah Tompon’ny tafika mba tsy hoentina any Babylona ny fitaovana sisa tavela ao an-tranon’i Jehovah sy ao an-tranon’ny mpanjakan’ny Joda ary eto Jerosalema.’', 'raha tena mpaminany anefa izy ireo ary ny tenin’i jehovah tokoa no lazainy, dia aoka izy ireo hiangavy an’i jehovah tompon’ny tafika mba tsy hoentina any babylona ny fitaovana sisa tavela ao an-tranon’i jehovah sy ao an-tranon’ny mpanjakan’ny joda ary eto jerosalema.’'),
  ('6ab25ba15bc78544e222211b', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 15, '“‘Fa tsy naniraka an’ireny aho’, hoy i Jehovah, ‘nefa maminany lainga amin’ny anarako izy. Koa raha mihaino azy ianareo dia haparitako, ary ho faty ianareo sy ny mpaminany izay maminany aminareo.’”', '“‘fa tsy naniraka an’ireny aho’, hoy i jehovah, ‘nefa maminany lainga amin’ny anarako izy. koa raha mihaino azy ianareo dia haparitako, ary ho faty ianareo sy ny mpaminany izay maminany aminareo.’”'),
  ('6ab25ba15bc78544e2222115', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 9, '“‘“‘Koa aza mihaino an’ireo mpaminany, mpisikidy, mpanonofy, mpimasy, ary ireo mpilalao ody eo aminareo, izay milaza hoe: “Tsy hanompo ny mpanjakan’i Babylona ianareo!”', '“‘“‘koa aza mihaino an’ireo mpaminany, mpisikidy, mpanonofy, mpimasy, ary ireo mpilalao ody eo aminareo, izay milaza hoe: “tsy hanompo ny mpanjakan’i babylona ianareo!”'),
  ('6ab25ba15bc78544e2222114', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 8, '“‘“‘Hosaziko ny firenena na fanjakana tsy mety manompo an’i Nebokadnezara mpanjakan’i Babylona, sy tsy mety mampidina ny vozony ho eo ambany ziogan’ny mpanjakan’i Babylona. Hamely azy amin’ny sabatra sy ny mosary ary ny areti-mandringana aho’, hoy i Jehovah, ‘mandra-pandringako azy amin’ny alalan’i Nebokadnezara.’', '“‘“‘hosaziko ny firenena na fanjakana tsy mety manompo an’i nebokadnezara mpanjakan’i babylona, sy tsy mety mampidina ny vozony ho eo ambany ziogan’ny mpanjakan’i babylona. hamely azy amin’ny sabatra sy ny mosary ary ny areti-mandringana aho’, hoy i jehovah, ‘mandra-pandringako azy amin’ny alalan’i nebokadnezara.’'),
  ('6ab25ba15bc78544e222210f', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 3, 'ary alefaso any amin’ny mpanjakan’i Edoma, sy ny mpanjakan’i Moaba, sy ny mpanjakan’ny Amonita, sy ny mpanjakan’i Tyro, ary ny mpanjakan’i Sidona. Ireo iraka tonga eto Jerosalema mba hihaona amin’i Zedekia mpanjakan’ny Joda no ampitondray an’izany.', 'ary alefaso any amin’ny mpanjakan’i edoma, sy ny mpanjakan’i moaba, sy ny mpanjakan’ny amonita, sy ny mpanjakan’i tyro, ary ny mpanjakan’i sidona. ireo iraka tonga eto jerosalema mba hihaona amin’i zedekia mpanjakan’ny joda no ampitondray an’izany.'),
  ('6ab25ba15bc78544e222211a', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 14, 'Aza mihaino ny tenin’ireo mpaminany milaza aminareo hoe: ‘Tsy hanompo ny mpanjakan’i Babylona ianareo.’ Maminany lainga aminareo mantsy izy ireo.', 'aza mihaino ny tenin’ireo mpaminany milaza aminareo hoe: ‘tsy hanompo ny mpanjakan’i babylona ianareo.’ maminany lainga aminareo mantsy izy ireo.'),
  ('6ab25ba15bc78544e2222110', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 4, 'Asaivo lazain’izy ireo amin’ny tompony hoe: “‘“Izao no tenin’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely, ka holazainareo amin’ny tomponareo:', 'asaivo lazain’izy ireo amin’ny tompony hoe: “‘“izao no tenin’i jehovah tompon’ny tafika, andriamanitry ny israely, ka holazainareo amin’ny tomponareo:'),
  ('6ab25ba15bc78544e2222119', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 13, 'Fa nahoana moa ianao sy ny vahoakanao no ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana, araka izay nolazain’i Jehovah hoe hanjo an’izay firenena tsy manaiky hanompo ny mpanjakan’i Babylona?', 'fa nahoana moa ianao sy ny vahoakanao no ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana, araka izay nolazain’i jehovah hoe hanjo an’izay firenena tsy manaiky hanompo ny mpanjakan’i babylona?'),
  ('6ab25ba15bc78544e2222116', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 10, 'Maminany lainga aminareo mantsy izy ireo, ka raha mihaino azy ianareo dia hoentina lavitra tsy ho eo amin’ny taninareo. Ary haparitako ianareo dia ho ripaka.', 'maminany lainga aminareo mantsy izy ireo, ka raha mihaino azy ianareo dia hoentina lavitra tsy ho eo amin’ny taninareo. ary haparitako ianareo dia ho ripaka.'),
  ('6ab25ba15bc78544e2222113', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 7, 'Hanompo azy sy ny zanany ary ny zafikeliny ny firenena rehetra, mandra-pahatongan’ny fotoana haharesy ny taniny. Firenena maro sy mpanjaka lehibe no hanao azy ho andevo amin’izay fotoana izay.’', 'hanompo azy sy ny zanany ary ny zafikeliny ny firenena rehetra, mandra-pahatongan’ny fotoana haharesy ny taniny. firenena maro sy mpanjaka lehibe no hanao azy ho andevo amin’izay fotoana izay.’'),
  ('6ab25ba15bc78544e222210e', '2026-09-22T10:42:41.533Z', '2026-09-22T10:42:41.533Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 27, 2, '“Izao no nolazain’i Jehovah tamiko: ‘Manamboara tady sy zioga dia ataovy eo amin’ny vozonao izany,', '“izao no nolazain’i jehovah tamiko: ‘manamboara tady sy zioga dia ataovy eo amin’ny vozonao izany,'),
  ('6ab25ba21f41de91124cea19', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 5, 'Dia namaly an’i Hanania mpaminany i Jeremia mpaminany, teo anatrehan’ny mpisorona sy ny vahoaka rehetra, izay nitsangana tao an-tranon’i Jehovah.', 'dia namaly an’i hanania mpaminany i jeremia mpaminany, teo anatrehan’ny mpisorona sy ny vahoaka rehetra, izay nitsangana tao an-tranon’i jehovah.'),
  ('6ab25ba21f41de91124cea23', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 15, 'Dia niteny tamin’i Hanania mpaminany i Jeremia mpaminany hoe: “Henoy ny teniko, azafady, ry Hanania! Tsy naniraka anao i Jehovah, fa nampino lainga an’ity vahoaka ity ianao.', 'dia niteny tamin’i hanania mpaminany i jeremia mpaminany hoe: “henoy ny teniko, azafady, ry hanania! tsy naniraka anao i jehovah, fa nampino lainga an’ity vahoaka ity ianao.'),
  ('6ab25ba21f41de91124cea21', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 13, '“Mandehana lazao amin’i Hanania hoe: ‘Izao no lazain’i Jehovah: “Zioga hazo no notapahinao, fa zioga vy kosa no hataonao solony.”', '“mandehana lazao amin’i hanania hoe: ‘izao no lazain’i jehovah: “zioga hazo no notapahinao, fa zioga vy kosa no hataonao solony.”'),
  ('6ab25ba21f41de91124cea1a', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 6, 'Hoy i Jeremia mpaminany: “Amena! Enga anie ka hanao an’izany tokoa i Jehovah! Hotanterahin’i Jehovah anie ny faminanianao, ka haveriny avy any Babylona ho eto amin’ity toerana ity tokoa ny fitaovana tao an-tranon’i Jehovah sy ny olona rehetra natao sesitany!', 'hoy i jeremia mpaminany: “amena! enga anie ka hanao an’izany tokoa i jehovah! hotanterahin’i jehovah anie ny faminanianao, ka haveriny avy any babylona ho eto amin’ity toerana ity tokoa ny fitaovana tao an-tranon’i jehovah sy ny olona rehetra natao sesitany!'),
  ('6ab25ba21f41de91124cea1f', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 11, 'Ary hoy i Hanania teo anatrehan’ny vahoaka manontolo: “Izao no lazain’i Jehovah: ‘Hoatr’izao no hanapahako ny ziogan’i Nebokadnezara mpanjakan’i Babylona, ato anatin’ny roa taona, ka tsy ho eo amin’ny vozon’ny firenena rehetra intsony izany.’” Dia lasa nandeha i Jeremia mpaminany.', 'ary hoy i hanania teo anatrehan’ny vahoaka manontolo: “izao no lazain’i jehovah: ‘hoatr’izao no hanapahako ny ziogan’i nebokadnezara mpanjakan’i babylona, ato anatin’ny roa taona, ka tsy ho eo amin’ny vozon’ny firenena rehetra intsony izany.’” dia lasa nandeha i jeremia mpaminany.'),
  ('6ab25ba21f41de91124cea24', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 16, 'Izao àry no lazain’i Jehovah: ‘Hesoriko tsy ho eny ambonin’ny tany ianao. Amin’ity taona ity ianao dia ho faty, satria mampirisika ny olona hikomy amin’i Jehovah.’”', 'izao àry no lazain’i jehovah: ‘hesoriko tsy ho eny ambonin’ny tany ianao. amin’ity taona ity ianao dia ho faty, satria mampirisika ny olona hikomy amin’i jehovah.’”'),
  ('6ab25ba21f41de91124cea1d', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 9, 'Raha misy kosa mpaminany manambara fa hisy fiadanana ka tanteraka ny teniny, dia ho fantatra hoe tena nirahin’i Jehovah tokoa izy.”', 'raha misy kosa mpaminany manambara fa hisy fiadanana ka tanteraka ny teniny, dia ho fantatra hoe tena nirahin’i jehovah tokoa izy.”'),
  ('6ab25ba21f41de91124cea22', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 14, 'Fa izao no tenin’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Hasiako zioga vy eo amin’ny vozon’ireny firenena rehetra ireny, mba hanompoan’izy ireny an’i Nebokadnezara mpanjakan’i Babylona, ka tsy maintsy hanompo azy izy ireny. Na ny bibidia aza homeko azy.”’”', 'fa izao no tenin’i jehovah tompon’ny tafika, andriamanitry ny israely: “hasiako zioga vy eo amin’ny vozon’ireny firenena rehetra ireny, mba hanompoan’izy ireny an’i nebokadnezara mpanjakan’i babylona, ka tsy maintsy hanompo azy izy ireny. na ny bibidia aza homeko azy.”’”'),
  ('6ab25ba21f41de91124cea20', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 12, 'Rehefa avy notapahin’i Hanania mpaminany ilay zioga teny amin’ny vozon’i Jeremia mpaminany, dia niteny tamin’i Jeremia i Jehovah hoe:', 'rehefa avy notapahin’i hanania mpaminany ilay zioga teny amin’ny vozon’i jeremia mpaminany, dia niteny tamin’i jeremia i jehovah hoe:'),
  ('6ab25ba21f41de91124cea1e', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 10, 'Dia nesorin’i Hanania mpaminany teny amin’ny vozon’i Jeremia mpaminany ilay zioga, ka notapahiny.', 'dia nesorin’i hanania mpaminany teny amin’ny vozon’i jeremia mpaminany ilay zioga, ka notapahiny.'),
  ('6ab25ba21f41de91124cea1c', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 8, 'Ela be talohako sy talohanao no efa nisy mpaminany nilaza fa hisy ady sy loza ary areti-mandringana any amin’ny tany maro sy any amin’ireo fanjakana lehibe.', 'ela be talohako sy talohanao no efa nisy mpaminany nilaza fa hisy ady sy loza ary areti-mandringana any amin’ny tany maro sy any amin’ireo fanjakana lehibe.'),
  ('6ab25ba21f41de91124cea18', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 4, '“‘Hampodiko eto koa i Jekonia zanak’i Joiakima, mpanjakan’ny Joda, sy ny Joda rehetra natao sesitany any Babylona’, hoy i Jehovah, ‘satria hotapahiko ny ziogan’ny mpanjakan’i Babylona.’”', '“‘hampodiko eto koa i jekonia zanak’i joiakima, mpanjakan’ny joda, sy ny joda rehetra natao sesitany any babylona’, hoy i jehovah, ‘satria hotapahiko ny ziogan’ny mpanjakan’i babylona.’”'),
  ('6ab25ba21f41de91124cea16', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 2, '“Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Hotapahiko ny ziogan’ny mpanjakan’i Babylona.', '“izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘hotapahiko ny ziogan’ny mpanjakan’i babylona.'),
  ('6ab25ba21f41de91124cea25', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 17, 'Koa maty tamin’ny volana fahafito tamin’iny taona iny ihany i Hanania mpaminany.', 'koa maty tamin’ny volana fahafito tamin’iny taona iny ihany i hanania mpaminany.'),
  ('6ab25ba21f41de91124cea1b', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 7, 'Mba henoy kely anefa izay holazaiko aminao sy amin’ny vahoaka rehetra.', 'mba henoy kely anefa izay holazaiko aminao sy amin’ny vahoaka rehetra.'),
  ('6ab25ba21f41de91124cea15', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 1, 'Tamin’iny taona iny ihany, izany hoe teo am-piandohan’ny fanjakan’i Zedekia mpanjakan’ny Joda, tamin’ny volana fahadimy, tamin’ny taona fahefatra, dia niteny an’izao tamiko, tao an-tranon’i Jehovah teo anatrehan’ny mpisorona sy ny vahoaka rehetra, i Hanania zanak’i Azora, mpaminany avy any Gibeona:', 'tamin’iny taona iny ihany, izany hoe teo am-piandohan’ny fanjakan’i zedekia mpanjakan’ny joda, tamin’ny volana fahadimy, tamin’ny taona fahefatra, dia niteny an’izao tamiko, tao an-tranon’i jehovah teo anatrehan’ny mpisorona sy ny vahoaka rehetra, i hanania zanak’i azora, mpaminany avy any gibeona:'),
  ('6ab25ba21f41de91124cea17', '2026-09-22T10:42:42.082Z', '2026-09-22T10:42:42.082Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 28, 3, 'Ato anatin’ny roa taona, dia haveriko eto amin’ity toerana ity ny fitaovana rehetra tao an-tranon’i Jehovah, izay nalain’i Nebokadnezara mpanjakan’i Babylona teto sy nentiny any Babylona.’”', 'ato anatin’ny roa taona, dia haveriko eto amin’ity toerana ity ny fitaovana rehetra tao an-tranon’i jehovah, izay nalain’i nebokadnezara mpanjakan’i babylona teto sy nentiny any babylona.’”'),
  ('6ab25ba37cfd635da0065d66', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 28, 'Fa nandefa taratasy tatỳ aminay atỳ Babylona mihitsy izy, hilaza hoe: “Mbola haharitra ela izy ity! Koa manorena trano ka mipetraha ao. Manaova tanimboly ka hano ny vokatra avy aminy, ...”’”’”', 'fa nandefa taratasy tatỳ aminay atỳ babylona mihitsy izy, hilaza hoe: “mbola haharitra ela izy ity! koa manorena trano ka mipetraha ao. manaova tanimboly ka hano ny vokatra avy aminy, ...”’”’”'),
  ('6ab25ba37cfd635da0065d5d', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 19, 'Tsy nohenoin’izy ireo mantsy ny teniko izay nampitondraiko an’ireo mpaminany mpanompoko’, hoy i Jehovah, ‘ary imbetsaka aho no naniraka azy ireny tany aminareo.’ “‘Tsy nihaino anefa ianareo’, hoy i Jehovah.', 'tsy nohenoin’izy ireo mantsy ny teniko izay nampitondraiko an’ireo mpaminany mpanompoko’, hoy i jehovah, ‘ary imbetsaka aho no naniraka azy ireny tany aminareo.’ “‘tsy nihaino anefa ianareo’, hoy i jehovah.'),
  ('6ab25ba37cfd635da0065d56', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 12, 'Ary hiantso ahy ianareo ka ho avy hivavaka amiko, dia hihaino anareo aho.’', 'ary hiantso ahy ianareo ka ho avy hivavaka amiko, dia hihaino anareo aho.’'),
  ('6ab25ba37cfd635da0065d55', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 11, '“‘Fa fantatro tsara ny zavatra efa noeritreretiko hatao aminareo’, hoy i Jehovah. ‘Mieritreritra ny hanome anareo fiadanana aho fa tsy loza, mba hanananareo hoavy tsara sy fanantenana.', '“‘fa fantatro tsara ny zavatra efa noeritreretiko hatao aminareo’, hoy i jehovah. ‘mieritreritra ny hanome anareo fiadanana aho fa tsy loza, mba hanananareo hoavy tsara sy fanantenana.'),
  ('6ab25ba37cfd635da0065d64', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 26, '‘Efa notendren’i Jehovah ho mpisorona hisolo an’i Joiada mpisorona ianao, mba ho mpiandraikitra ao an-tranon’i Jehovah, ka hisambotra an’izay olona adala manao hoatran’ny mpaminany sy hangeja azy amin’ny gadra hazo sy gadra vy.', '‘efa notendren’i jehovah ho mpisorona hisolo an’i joiada mpisorona ianao, mba ho mpiandraikitra ao an-tranon’i jehovah, ka hisambotra an’izay olona adala manao hoatran’ny mpaminany sy hangeja azy amin’ny gadra hazo sy gadra vy.'),
  ('6ab25ba37cfd635da0065d4b', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 1, 'Nandefa taratasy avy teto Jerosalema i Jeremia mpaminany, ho an’ny sisa amin’ireo anti-panahy natao sesitany, sy ho an’ny mpisorona sy ny mpaminany ary ny vahoaka rehetra, izay nentin’i Nebokadnezara niala teto Jerosalema sy nataony sesitany any Babylona.', 'nandefa taratasy avy teto jerosalema i jeremia mpaminany, ho an’ny sisa amin’ireo anti-panahy natao sesitany, sy ho an’ny mpisorona sy ny mpaminany ary ny vahoaka rehetra, izay nentin’i nebokadnezara niala teto jerosalema sy nataony sesitany any babylona.'),
  ('6ab25ba37cfd635da0065d5b', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 17, '‘Izao no tenin’i Jehovah Tompon’ny tafika: “Handefasako sabatra sy mosary ary areti-mandringana izy ireo hamely azy, ary hataoko toy ny aviavy lo tsy azo hanina fa ratsy loatra.”’', '‘izao no tenin’i jehovah tompon’ny tafika: “handefasako sabatra sy mosary ary areti-mandringana izy ireo hamely azy, ary hataoko toy ny aviavy lo tsy azo hanina fa ratsy loatra.”’'),
  ('6ab25ba37cfd635da0065d53', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 9, 'Fa ‘maminany lainga aminareo amin’ny anarako izy ireny, nefa tsy naniraka azy aho’, hoy i Jehovah.”’”', 'fa ‘maminany lainga aminareo amin’ny anarako izy ireny, nefa tsy naniraka azy aho’, hoy i jehovah.”’”'),
  ('6ab25ba37cfd635da0065d52', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 8, 'Izao mantsy no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Aza avela hamitaka anareo ny mpaminany sy ny mpisikidy eo aminareo. Ary aza mihaino ny nofiny, izay tantarainy aminareo.', 'izao mantsy no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: “aza avela hamitaka anareo ny mpaminany sy ny mpisikidy eo aminareo. ary aza mihaino ny nofiny, izay tantarainy aminareo.'),
  ('6ab25ba37cfd635da0065d62', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 24, '“Ary izao no holazainao amin’i Semaia avy any Nehelama:', '“ary izao no holazainao amin’i semaia avy any nehelama:'),
  ('6ab25ba37cfd635da0065d59', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 15, '“Nilaza anefa ianareo hoe: ‘Nanendry mpaminany ho anay atỳ Babylona i Jehovah.’', '“nilaza anefa ianareo hoe: ‘nanendry mpaminany ho anay atỳ babylona i jehovah.’'),
  ('6ab25ba37cfd635da0065d65', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 27, 'Koa nahoana ianao no tsy niteny mafy an’i Jeremia avy any Anatota izay manao hoatran’ny mpaminany eo aminareo?', 'koa nahoana ianao no tsy niteny mafy an’i jeremia avy any anatota izay manao hoatran’ny mpaminany eo aminareo?'),
  ('6ab25ba37cfd635da0065d60', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 22, 'Ary izay hanjo azy roa lahy, dia ho lasa fiteny fampiasan’ny Joda rehetra natao sesitany any Babylona rehefa manozona. Hilaza izy ireo hoe: “Enga anie ianao hataon’i Jehovah hoatran’i Zedekia sy Ahaba, izay natonon’ny mpanjakan’i Babylona tao anaty afo!”', 'ary izay hanjo azy roa lahy, dia ho lasa fiteny fampiasan’ny joda rehetra natao sesitany any babylona rehefa manozona. hilaza izy ireo hoe: “enga anie ianao hataon’i jehovah hoatran’i zedekia sy ahaba, izay natonon’ny mpanjakan’i babylona tao anaty afo!”'),
  ('6ab25ba37cfd635da0065d4d', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 3, 'Nampitondrain’i Jeremia an’i Elasa zanak’i Safana sy Gemaria zanak’i Hilkia ilay taratasy. Nirahin’i Zedekia mpanjakan’ny Joda ho any Babylona, any amin’i Nebokadnezara mpanjakan’i Babylona, mantsy izy roa lahy. Izao no voalazan’ilay taratasy:', 'nampitondrain’i jeremia an’i elasa zanak’i safana sy gemaria zanak’i hilkia ilay taratasy. nirahin’i zedekia mpanjakan’ny joda ho any babylona, any amin’i nebokadnezara mpanjakan’i babylona, mantsy izy roa lahy. izao no voalazan’ilay taratasy:'),
  ('6ab25ba37cfd635da0065d68', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 30, 'dia niteny tamin’i Jeremia i Jehovah hoe:', 'dia niteny tamin’i jeremia i jehovah hoe:'),
  ('6ab25ba37cfd635da0065d5a', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 16, '“Fa izao no lazain’i Jehovah amin’ilay mpanjaka mipetraka eo amin’ny seza fiandrianan’i Davida sy amin’ny mponina rehetra ato amin’ity tanàna ity, dia ireo rahalahinareo tsy natao sesitany niaraka taminareo:', '“fa izao no lazain’i jehovah amin’ilay mpanjaka mipetraka eo amin’ny seza fiandrianan’i davida sy amin’ny mponina rehetra ato amin’ity tanàna ity, dia ireo rahalahinareo tsy natao sesitany niaraka taminareo:'),
  ('6ab25ba37cfd635da0065d57', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 13, '“‘Hitady ahy ianareo ka hahita ahy, satria hitady ahy amin’ny fonareo manontolo ianareo.', '“‘hitady ahy ianareo ka hahita ahy, satria hitady ahy amin’ny fonareo manontolo ianareo.'),
  ('6ab25ba37cfd635da0065d5f', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 21, 'Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely, momba an’i Ahaba zanak’i Kolaia sy momba an’i Zedekia zanak’i Mahaseia, izay samy maminany lainga amin’ny anarako: ‘Hatolotro eo an-tanan’i Nebokadnezara mpanjakan’i Babylona izy roa lahy, ka hovonoiny eo imasonareo.', 'izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely, momba an’i ahaba zanak’i kolaia sy momba an’i zedekia zanak’i mahaseia, izay samy maminany lainga amin’ny anarako: ‘hatolotro eo an-tanan’i nebokadnezara mpanjakan’i babylona izy roa lahy, ka hovonoiny eo imasonareo.'),
  ('6ab25ba37cfd635da0065d4c', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 2, 'Efa tsy teto Jerosalema intsony tamin’izay i Jekonia Mpanjaka, ny renin’ny mpanjaka, ny tandapa, ny andrianan’i Joda sy Jerosalema, ny mpanao asa tanana, ary ny mpanefy.', 'efa tsy teto jerosalema intsony tamin’izay i jekonia mpanjaka, ny renin’ny mpanjaka, ny tandapa, ny andrianan’i joda sy jerosalema, ny mpanao asa tanana, ary ny mpanefy.'),
  ('6ab25ba37cfd635da0065d51', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 7, 'Dia ataovy izay hampiadana an’ilay tanàna nandefasako sesitany anareo. Mivavaha amin’i Jehovah ho an’ilay tanàna, satria raha miadana izy io dia hiadana koa ianareo.', 'dia ataovy izay hampiadana an’ilay tanàna nandefasako sesitany anareo. mivavaha amin’i jehovah ho an’ilay tanàna, satria raha miadana izy io dia hiadana koa ianareo.'),
  ('6ab25ba37cfd635da0065d69', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 31, '“Mandefasa hafatra any amin’ny olona rehetra any an-tsesitany hoe: ‘Izao no lazain’i Jehovah momba an’i Semaia avy any Nehelama: “Koa satria naminany taminareo i Semaia nefa tsy nirahiko, ka nampino lainga anareo,', '“mandefasa hafatra any amin’ny olona rehetra any an-tsesitany hoe: ‘izao no lazain’i jehovah momba an’i semaia avy any nehelama: “koa satria naminany taminareo i semaia nefa tsy nirahiko, ka nampino lainga anareo,'),
  ('6ab25ba37cfd635da0065d5e', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 20, '“Henoy àry ny tenin’i Jehovah, ry olona rehetra natao sesitany, izay nalefako niala teto Jerosalema mba ho any Babylona.', '“henoy àry ny tenin’i jehovah, ry olona rehetra natao sesitany, izay nalefako niala teto jerosalema mba ho any babylona.'),
  ('6ab25ba37cfd635da0065d5c', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 18, '“‘Dia henjehiko amin’ny sabatra sy ny mosary ary ny areti-mandringana izy ireo. Hataoko mihorohoro ny fanjakana rehetra eto an-tany mahita an’izay hanjo azy. Hanozona azy ireo ny olona any amin’ny firenena rehetra hanaparitahako azy, sady ho gaga sy hisioka rehefa mahita an’izay hanjo azy, ary handatsa azy.', '“‘dia henjehiko amin’ny sabatra sy ny mosary ary ny areti-mandringana izy ireo. hataoko mihorohoro ny fanjakana rehetra eto an-tany mahita an’izay hanjo azy. hanozona azy ireo ny olona any amin’ny firenena rehetra hanaparitahako azy, sady ho gaga sy hisioka rehefa mahita an’izay hanjo azy, ary handatsa azy.'),
  ('6ab25ba37cfd635da0065d4f', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 5, '‘Manorena trano ka mipetraha ao. Manaova tanimboly ka hano ny vokatra avy aminy.', '‘manorena trano ka mipetraha ao. manaova tanimboly ka hano ny vokatra avy aminy.'),
  ('6ab25ba37cfd635da0065d54', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 10, '“Fa izao no lazain’i Jehovah: ‘Hokarakaraiko ianareo rehefa tapitra ny 70 taona ijanonanareo any Babylona, dia hotanterahiko ny fampanantenako, ka haveriko eto amin’ity toerana ity ianareo.’', '“fa izao no lazain’i jehovah: ‘hokarakaraiko ianareo rehefa tapitra ny 70 taona ijanonanareo any babylona, dia hotanterahiko ny fampanantenako, ka haveriko eto amin’ity toerana ity ianareo.’'),
  ('6ab25ba37cfd635da0065d50', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 6, 'Manambadia ka miteraha zazalahy sy zazavavy. Akao vady ny zanakareo lahy ary ampanambadio ny zanakareo vavy, mba hiteraka zazalahy sy zazavavy koa. Aoka hihabetsaka ianareo fa tsy hihavitsy.', 'manambadia ka miteraha zazalahy sy zazavavy. akao vady ny zanakareo lahy ary ampanambadio ny zanakareo vavy, mba hiteraka zazalahy sy zazavavy koa. aoka hihabetsaka ianareo fa tsy hihavitsy.'),
  ('6ab25ba37cfd635da0065d63', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 25, '‘Izao no tenin’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Nandefa taratasy tamin’ny anaranao ianao, ho an’ny olona rehetra eto Jerosalema sy ho an’i Zefania mpisorona zanak’i Mahaseia ary ho an’ny mpisorona rehetra, nilaza hoe:', '‘izao no tenin’i jehovah tompon’ny tafika, andriamanitry ny israely: “nandefa taratasy tamin’ny anaranao ianao, ho an’ny olona rehetra eto jerosalema sy ho an’i zefania mpisorona zanak’i mahaseia ary ho an’ny mpisorona rehetra, nilaza hoe:'),
  ('6ab25ba37cfd635da0065d67', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 29, 'Rehefa novakin’i Zefania mpisorona teo anatrehan’i Jeremia mpaminany ilay taratasy,', 'rehefa novakin’i zefania mpisorona teo anatrehan’i jeremia mpaminany ilay taratasy,'),
  ('6ab25ba37cfd635da0065d58', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 14, 'Ary hataoko izay hahitanareo ahy’, hoy i Jehovah. ‘Hangoniko izay babo eo aminareo, ary hovoriko avy any amin’ny firenena rehetra sy ny toerana rehetra nanaparitahako anareo ianareo’, hoy i Jehovah. ‘Dia hampodiko ao amin’ilay toerana nialanareo tamin’ianareo nalefako sesitany ianareo.’', 'ary hataoko izay hahitanareo ahy’, hoy i jehovah. ‘hangoniko izay babo eo aminareo, ary hovoriko avy any amin’ny firenena rehetra sy ny toerana rehetra nanaparitahako anareo ianareo’, hoy i jehovah. ‘dia hampodiko ao amin’ilay toerana nialanareo tamin’ianareo nalefako sesitany ianareo.’'),
  ('6ab25ba37cfd635da0065d61', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 23, 'Nanao zavatra manala baraka teo amin’ny Israely mantsy izy roa lahy. Nanitsakitsa-bady izy ireo ka naka vadin’olona. Nilaza lainga tamin’ny anarako koa izy ireo nefa tsy nasaiko nanao an’izany. “‘“Izaho no mahalala an’izay nataony sy vavolombelon’izany”, hoy i Jehovah.’”', 'nanao zavatra manala baraka teo amin’ny israely mantsy izy roa lahy. nanitsakitsa-bady izy ireo ka naka vadin’olona. nilaza lainga tamin’ny anarako koa izy ireo nefa tsy nasaiko nanao an’izany. “‘“izaho no mahalala an’izay nataony sy vavolombelon’izany”, hoy i jehovah.’”'),
  ('6ab25ba37cfd635da0065d4e', '2026-09-22T10:42:43.295Z', '2026-09-22T10:42:43.295Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 4, '“Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely, amin’ny olona rehetra nalefany sesitany avy teto Jerosalema ho any Babylona:', '“izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely, amin’ny olona rehetra nalefany sesitany avy teto jerosalema ho any babylona:');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25ba37cfd635da0065d6a', '2026-09-22T10:42:43.296Z', '2026-09-22T10:42:43.296Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 29, 32, 'dia izao no lazain’i Jehovah: ‘Hosaziko i Semaia avy any Nehelama sy ny taranany. Tsy hisy taranany ho tavela eto amin’ity firenena ity, ary tsy hahita ny zavatra tsara hataoko ho an’ny vahoakako izy’, hoy i Jehovah. ‘Mampirisika ny olona hikomy amin’i Jehovah mantsy izy.’”’”', 'dia izao no lazain’i jehovah: ‘hosaziko i semaia avy any nehelama sy ny taranany. tsy hisy taranany ho tavela eto amin’ity firenena ity, ary tsy hahita ny zavatra tsara hataoko ho an’ny vahoakako izy’, hoy i jehovah. ‘mampirisika ny olona hikomy amin’i jehovah mantsy izy.’”’”'),
  ('6ab25ba39012a668145e1f31', '2026-09-22T10:42:43.862Z', '2026-09-22T10:42:43.862Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 1, 'Niteny tamin’i Jeremia i Jehovah hoe:', 'niteny tamin’i jeremia i jehovah hoe:'),
  ('6ab25ba39012a668145e1f32', '2026-09-22T10:42:43.862Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 2, '“Izao no lazain’i Jehovah Andriamanitry ny Israely: ‘Soraty amin’ny boky izay teny rehetra lazaiko aminao.', '“izao no lazain’i jehovah andriamanitry ny israely: ‘soraty amin’ny boky izay teny rehetra lazaiko aminao.'),
  ('6ab25ba39012a668145e1f40', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 16, 'Koa hisy handrapaka izay rehetra mandrapaka anao, Ary ho lasa babo daholo koa ny fahavalonao. Hisy haka an-keriny ny fananan’izay maka an-keriny ny fanananao, Ary havelako hisy handroba izay rehetra mandroba anao.”', 'koa hisy handrapaka izay rehetra mandrapaka anao, ary ho lasa babo daholo koa ny fahavalonao. hisy haka an-keriny ny fananan’izay maka an-keriny ny fanananao, ary havelako hisy handroba izay rehetra mandroba anao.”'),
  ('6ab25ba39012a668145e1f3f', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 15, 'Fa maninona ianao no mitaraina noho ny fahavoazanao? Tsy mety mijanona ny fanaintainanao! Be ny heloka vitanao ary maro ny fahotanao, Ka izany no nahatonga ahy hanao an’izany taminao.', 'fa maninona ianao no mitaraina noho ny fahavoazanao? tsy mety mijanona ny fanaintainanao! be ny heloka vitanao ary maro ny fahotanao, ka izany no nahatonga ahy hanao an’izany taminao.'),
  ('6ab25ba39012a668145e1f3e', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 14, 'Nanadino anao ireo lehilahy rehetra niaraka taminao. Tsy mitady anao intsony izy ireo. Fa namely anao toy ny famelin’ny fahavalo aho. Nanasazy anao toy ny ataon’ny olona masiaka be aho. Be dia be mantsy ny heloka vitanao ary maro ny fahotanao.', 'nanadino anao ireo lehilahy rehetra niaraka taminao. tsy mitady anao intsony izy ireo. fa namely anao toy ny famelin’ny fahavalo aho. nanasazy anao toy ny ataon’ny olona masiaka be aho. be dia be mantsy ny heloka vitanao ary maro ny fahotanao.'),
  ('6ab25ba39012a668145e1f3c', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 12, 'Fa izao no lazain’i Jehovah: “Tsy misy fanafany ny fahavoazanao. Tsy mety sitrana ny ratranao.', 'fa izao no lazain’i jehovah: “tsy misy fanafany ny fahavoazanao. tsy mety sitrana ny ratranao.'),
  ('6ab25ba39012a668145e1f35', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 5, 'Izao no lazain’i Jehovah: “Maheno feo mangovitra izahay. Horohoro no manjaka, fa tsy fiadanana.', 'izao no lazain’i jehovah: “maheno feo mangovitra izahay. horohoro no manjaka, fa tsy fiadanana.'),
  ('6ab25ba39012a668145e1f47', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 23, 'Hifofofofo toy ny tafio-drivotra ny fahatezeran’i Jehovah. Ho toy ny rivo-mahery mihodinkodina eo amin’ny lohan’ny ratsy fanahy izany.', 'hifofofofo toy ny tafio-drivotra ny fahatezeran’i jehovah. ho toy ny rivo-mahery mihodinkodina eo amin’ny lohan’ny ratsy fanahy izany.'),
  ('6ab25ba39012a668145e1f46', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 22, '“Dia ho lasa vahoakako ianareo, ary izaho ho Andriamanitrareo.”', '“dia ho lasa vahoakako ianareo, ary izaho ho andriamanitrareo.”'),
  ('6ab25ba39012a668145e1f48', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 24, 'Tsy hitony ny fahatezerana mafin’i Jehovah Raha tsy efa vitany sy tanterany ny fikasan’ny fony. Ho azonareo izany any am-parany.', 'tsy hitony ny fahatezerana mafin’i jehovah raha tsy efa vitany sy tanterany ny fikasan’ny fony. ho azonareo izany any am-parany.'),
  ('6ab25ba39012a668145e1f42', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 18, 'Izao no lazain’i Jehovah: “Hiverina any amin’ny tranolain’i Jakoba aho, ka hanangona an’ireo babo Sy hiantra an’ireo tranolainy. Haorina indray eo amin’ilay havoana nisy azy ilay tanàna, Ary ho eo amin’ny toerana tokony hisy azy ilay tilikambo voaro mafy.', 'izao no lazain’i jehovah: “hiverina any amin’ny tranolain’i jakoba aho, ka hanangona an’ireo babo sy hiantra an’ireo tranolainy. haorina indray eo amin’ilay havoana nisy azy ilay tanàna, ary ho eo amin’ny toerana tokony hisy azy ilay tilikambo voaro mafy.'),
  ('6ab25ba39012a668145e1f39', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 9, 'Dia hanompo an’i Jehovah Andriamaniny izy ireo, ary hanompo an’i Davida mpanjakany. Izy no hotendreko hitondra azy ireo.”', 'dia hanompo an’i jehovah andriamaniny izy ireo, ary hanompo an’i davida mpanjakany. izy no hotendreko hitondra azy ireo.”'),
  ('6ab25ba39012a668145e1f3b', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 11, '“Fa ho eo foana aho mba hamonjy anao”, hoy i Jehovah, “Haripako kosa ny firenena rehetra nanaparitahako anao. Ianao anefa tsy mba haripako. Hanariko araka ny antonony ianao, Ary tsy havelako ho afa-maina fotsiny fa hosaziko.”', '“fa ho eo foana aho mba hamonjy anao”, hoy i jehovah, “haripako kosa ny firenena rehetra nanaparitahako anao. ianao anefa tsy mba haripako. hanariko araka ny antonony ianao, ary tsy havelako ho afa-maina fotsiny fa hosaziko.”'),
  ('6ab25ba39012a668145e1f37', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 7, 'Indrisy! Andro mahatsiravina izany. Tsy misy mitovy aminy. Fotoam-pahoriana ho an’i Jakoba izany, Nefa ho voavonjy amin’izany izy.”', 'indrisy! andro mahatsiravina izany. tsy misy mitovy aminy. fotoam-pahoriana ho an’i jakoba izany, nefa ho voavonjy amin’izany izy.”'),
  ('6ab25ba39012a668145e1f34', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 4, 'Izao no tenin’i Jehovah tamin’ny Israely sy Joda:', 'izao no tenin’i jehovah tamin’ny israely sy joda:'),
  ('6ab25ba39012a668145e1f44', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 20, 'Ho toy ny taloha indray ny taranany, Ary ho mafy orina eo anatrehako ny fireneny. Hosaziko izay rehetra mampijaly azy.', 'ho toy ny taloha indray ny taranany, ary ho mafy orina eo anatrehako ny fireneny. hosaziko izay rehetra mampijaly azy.'),
  ('6ab25ba39012a668145e1f36', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 6, 'Mba anontanio, azafady, raha misy lehilahy afaka miteraka. Koa nahoana ny lehilahy matanjaka rehetra no hitako mitazona ny kibony Hoatran’ny vehivavy efa ho teraka? Nahoana no hatsatra ny tarehy rehetra?', 'mba anontanio, azafady, raha misy lehilahy afaka miteraka. koa nahoana ny lehilahy matanjaka rehetra no hitako mitazona ny kibony hoatran’ny vehivavy efa ho teraka? nahoana no hatsatra ny tarehy rehetra?'),
  ('6ab25ba39012a668145e1f38', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 8, '“Amin’izany andro izany”, hoy i Jehovah Tompon’ny tafika, “dia hotapahiko ilay zioga eny amin’ny vozonao ary hotapahiko roa ny tady mangeja anao. Tsy hisy vahiny hanao azy ho andevo intsony.', '“amin’izany andro izany”, hoy i jehovah tompon’ny tafika, “dia hotapahiko ilay zioga eny amin’ny vozonao ary hotapahiko roa ny tady mangeja anao. tsy hisy vahiny hanao azy ho andevo intsony.'),
  ('6ab25ba39012a668145e1f43', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 19, 'Hisy fisaorana avy ao ary hisy feon’olona mihomehy. Hataoko maro be ny taranany, ka tsy ho vitsy izy ireo. Hataoko be dia be izy ireo, Ka tsy ho vitsy an’isa.', 'hisy fisaorana avy ao ary hisy feon’olona mihomehy. hataoko maro be ny taranany, ka tsy ho vitsy izy ireo. hataoko be dia be izy ireo, ka tsy ho vitsy an’isa.'),
  ('6ab25ba39012a668145e1f3a', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 10, '“Koa aza matahotra ianao, ry Jakoba mpanompoko”, hoy i Jehovah, “Ary aza mihorohoro, ry Israely ô! Fa hovonjeko avy any an-tany lavitra ianao, Ary ny taranakao hovonjeko avy any amin’ny tany nahababo azy. Dia hiverina i Jakoba, ka hilamina sy tsy hisy hanakorontana. Tsy hisy hampatahotra azy ireo.”', '“koa aza matahotra ianao, ry jakoba mpanompoko”, hoy i jehovah, “ary aza mihorohoro, ry israely ô! fa hovonjeko avy any an-tany lavitra ianao, ary ny taranakao hovonjeko avy any amin’ny tany nahababo azy. dia hiverina i jakoba, ka hilamina sy tsy hisy hanakorontana. tsy hisy hampatahotra azy ireo.”'),
  ('6ab25ba39012a668145e1f41', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 17, '“Hataoko salama indray anefa ianao, ary hositraniko ny ratranao”, hoy i Jehovah, “Na dia nailikilik’izy ireo aza ianao ka nantsoiny hoe: ‘Ziona, ilay tsy misy mpitady.’”', '“hataoko salama indray anefa ianao, ary hositraniko ny ratranao”, hoy i jehovah, “na dia nailikilik’izy ireo aza ianao ka nantsoiny hoe: ‘ziona, ilay tsy misy mpitady.’”'),
  ('6ab25ba39012a668145e1f45', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 21, 'Ny iray amin’izy ireo no ho lasa olo-manan-kaja eo aminy, Ary avy eo aminy no hivoahan’ilay mpitondra azy. Hasaiko manakaiky ahy izy, ka hanatona ahy.” “Fa raha tsy izany, iza moa no ho sahy hanatona ahy?”, hoy i Jehovah.', 'ny iray amin’izy ireo no ho lasa olo-manan-kaja eo aminy, ary avy eo aminy no hivoahan’ilay mpitondra azy. hasaiko manakaiky ahy izy, ka hanatona ahy.” “fa raha tsy izany, iza moa no ho sahy hanatona ahy?”, hoy i jehovah.'),
  ('6ab25ba39012a668145e1f3d', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 13, 'Tsy misy olona hiteny hiaro anao, Ary tsy misy azo atao hitsaboana ny ferinao. Tsy misy fanafody mahasitrana anao.', 'tsy misy olona hiteny hiaro anao, ary tsy misy azo atao hitsaboana ny ferinao. tsy misy fanafody mahasitrana anao.'),
  ('6ab25ba39012a668145e1f33', '2026-09-22T10:42:43.863Z', '2026-09-22T10:42:43.863Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 30, 3, 'Fa “ho avy ny andro”, hoy i Jehovah, “izay hanangonako an’ireo vahoakako lasa babo, dia ny Israely sy Joda”, hoy i Jehovah. “Hampodiko ao amin’ilay tany nomeko ny razambeny izy ireo, ka ho azony indray ny taniny.”’”', 'fa “ho avy ny andro”, hoy i jehovah, “izay hanangonako an’ireo vahoakako lasa babo, dia ny israely sy joda”, hoy i jehovah. “hampodiko ao amin’ilay tany nomeko ny razambeny izy ireo, ka ho azony indray ny taniny.”’”'),
  ('6ab25ba6fe70b6ef2ab49dbc', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 28, '“Nanara-maso azy ireo aho mba hanongotana, handrodanana, handravana, handringanana, ary hanimbana azy. Hanara-maso azy ireo hoatr’izany koa aho mba hanorenana sy hambolena azy”, hoy i Jehovah.', '“nanara-maso azy ireo aho mba hanongotana, handrodanana, handravana, handringanana, ary hanimbana azy. hanara-maso azy ireo hoatr’izany koa aho mba hanorenana sy hambolena azy”, hoy i jehovah.'),
  ('6ab25ba6fe70b6ef2ab49db3', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 19, 'Fa nanenina aho dia niverina taminao. Rehefa nampahafantarina ahy izany, dia nokapohiko ny feko satria nalahelo aho. Menatra sy afa-baraka aho, Satria nitondra latsa aho noho izay nataoko tamin’izaho mbola tanora.’”', 'fa nanenina aho dia niverina taminao. rehefa nampahafantarina ahy izany, dia nokapohiko ny feko satria nalahelo aho. menatra sy afa-baraka aho, satria nitondra latsa aho noho izay nataoko tamin’izaho mbola tanora.’”'),
  ('6ab25ba6fe70b6ef2ab49dbf', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 31, '“Henoy izao!”, hoy i Jehovah. “Ho avy ny andro hanaovako fifanekena vaovao amin’ny taranak’Israely sy ny taranak’i Joda.', '“henoy izao!”, hoy i jehovah. “ho avy ny andro hanaovako fifanekena vaovao amin’ny taranak’israely sy ny taranak’i joda.'),
  ('6ab25ba6fe70b6ef2ab49dba', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 26, 'Tamin’izay dia nifoha aho, ka nahiratro ny masoko. Ary mamy tamiko ny torimasoko.', 'tamin’izay dia nifoha aho, ka nahiratro ny masoko. ary mamy tamiko ny torimasoko.'),
  ('6ab25ba6fe70b6ef2ab49db6', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 22, 'Mandra-pahoviana ianao no mbola hiroaroa saina, ry zanakavavy mpivadika? Fa namorona zava-baovao eto an-tany i Jehovah, Dia vehivavy maimay hanenjika lehilahy.”', 'mandra-pahoviana ianao no mbola hiroaroa saina, ry zanakavavy mpivadika? fa namorona zava-baovao eto an-tany i jehovah, dia vehivavy maimay hanenjika lehilahy.”'),
  ('6ab25ba6fe70b6ef2ab49db5', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 21, '“Manangàna marika famantaran-dalana ho anao, Ary mametraha takelaka manondro lalana. Diniho tsara ny lalambe, dia ilay lalana tokony halehanao. Ary miverena, ry Israely virjiny ô! Miverena any amin’ireo tanànanao.', '“manangàna marika famantaran-dalana ho anao, ary mametraha takelaka manondro lalana. diniho tsara ny lalambe, dia ilay lalana tokony halehanao. ary miverena, ry israely virjiny ô! miverena any amin’ireo tanànanao.'),
  ('6ab25ba6fe70b6ef2ab49daa', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 10, 'Henoy ny tenin’i Jehovah, ry firenena, Ary ambarao any amin’ireo nosy lavitra izany, ka lazao hoe: “Ilay nampiely ny Israely no hanangona azy. Hikarakara azy toy ny mpiandry ondry mikarakara ny andian’ondriny izy.', 'henoy ny tenin’i jehovah, ry firenena, ary ambarao any amin’ireo nosy lavitra izany, ka lazao hoe: “ilay nampiely ny israely no hanangona azy. hikarakara azy toy ny mpiandry ondry mikarakara ny andian’ondriny izy.'),
  ('6ab25ba6fe70b6ef2ab49da9', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 9, 'Hiverina izy ireo sady hitomany. Hitarika azy ireo aho raha mbola eo am-pitalahoana famindram-po izy ireo. Hoentiko eny amin’ny rano mikoriana izy ireo, Ary lalana mitovy tantana tsy hahatafintohina azy no hitondrako azy. Fa Ray ho an’ny Israely aho, ary i Efraima no lahimatoako.”', 'hiverina izy ireo sady hitomany. hitarika azy ireo aho raha mbola eo am-pitalahoana famindram-po izy ireo. hoentiko eny amin’ny rano mikoriana izy ireo, ary lalana mitovy tantana tsy hahatafintohina azy no hitondrako azy. fa ray ho an’ny israely aho, ary i efraima no lahimatoako.”'),
  ('6ab25ba6fe70b6ef2ab49da1', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 1, '“Amin’izany fotoana izany”, hoy i Jehovah, “dia ho Andriamanitry ny foko rehetra eo amin’ny Israely aho, ary izy ireo ho vahoakako.”', '“amin’izany fotoana izany”, hoy i jehovah, “dia ho andriamanitry ny foko rehetra eo amin’ny israely aho, ary izy ireo ho vahoakako.”'),
  ('6ab25ba6fe70b6ef2ab49db0', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 16, 'Izao no lazain’i Jehovah: “‘Aza midradradradra intsony ary aza mandrotsaka ranomaso, Fa hovalian-tsoa izay nataonao’, hoy i Jehovah. ‘Hiverina avy any amin’ny tanin’ny fahavalo izy ireny.’', 'izao no lazain’i jehovah: “‘aza midradradradra intsony ary aza mandrotsaka ranomaso, fa hovalian-tsoa izay nataonao’, hoy i jehovah. ‘hiverina avy any amin’ny tanin’ny fahavalo izy ireny.’'),
  ('6ab25ba6fe70b6ef2ab49da7', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 7, 'Izao mantsy no lazain’i Jehovah: “Manaova horakora-pifaliana ho an’i Jakoba. Mihobia fa ianao no sangany amin’ireo firenena. Ambarao izany! Derao Andriamanitra, ary milazà hoe: ‘Jehovah ô, mba vonjeo ny vahoakanao, dia izay sisa amin’ny Israely!’', 'izao mantsy no lazain’i jehovah: “manaova horakora-pifaliana ho an’i jakoba. mihobia fa ianao no sangany amin’ireo firenena. ambarao izany! derao andriamanitra, ary milazà hoe: ‘jehovah ô, mba vonjeo ny vahoakanao, dia izay sisa amin’ny israely!’'),
  ('6ab25ba6fe70b6ef2ab49dbe', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 30, 'Fa samy ho fatin’ny fahadisoany ihany ny tsirairay. Izay mihinana voaloboka marikivy no hadilo nify.”', 'fa samy ho fatin’ny fahadisoany ihany ny tsirairay. izay mihinana voaloboka marikivy no hadilo nify.”'),
  ('6ab25ba6fe70b6ef2ab49dbd', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 29, '“Tsy hisy hiteny intsony amin’izany andro izany hoe: ‘Ny ray no nihinana voaloboka marikivy, nefa ny nifin’ny zanany no nadilo.’', '“tsy hisy hiteny intsony amin’izany andro izany hoe: ‘ny ray no nihinana voaloboka marikivy, nefa ny nifin’ny zanany no nadilo.’'),
  ('6ab25ba6fe70b6ef2ab49db8', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 24, 'Hiara-monina ao daholo ny Joda sy ny olona ao amin’ny tanànany rehetra, anisan’izany ny tantsaha sy ireo mpandroaka biby fiompy.', 'hiara-monina ao daholo ny joda sy ny olona ao amin’ny tanànany rehetra, anisan’izany ny tantsaha sy ireo mpandroaka biby fiompy.'),
  ('6ab25ba6fe70b6ef2ab49da5', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 5, 'Ary hamboly voaloboka eny an-tendrombohitr’i Samaria indray ianao. Hamboly ny mpamboly ka hihinana ny vokatra azony.', 'ary hamboly voaloboka eny an-tendrombohitr’i samaria indray ianao. hamboly ny mpamboly ka hihinana ny vokatra azony.'),
  ('6ab25ba6fe70b6ef2ab49dc0', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 32, 'Tsy ho hoatran’ilay fifanekena nataoko tamin’ny razambeny, tamin’ny andro nitantanako azy nivoaka avy tany Ejipta, anefa izany. ‘Nivadika tamin’iny fifanekena nataoko iny mantsy izy ireo, na dia izaho aza no tena tompony’, hoy i Jehovah.”', 'tsy ho hoatran’ilay fifanekena nataoko tamin’ny razambeny, tamin’ny andro nitantanako azy nivoaka avy tany ejipta, anefa izany. ‘nivadika tamin’iny fifanekena nataoko iny mantsy izy ireo, na dia izaho aza no tena tompony’, hoy i jehovah.”'),
  ('6ab25ba6fe70b6ef2ab49db9', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 25, 'Homeko izay ilainy ny reraka, ary hataoko voky izay rehetra reraky ny hanoanana.”', 'homeko izay ilainy ny reraka, ary hataoko voky izay rehetra reraky ny hanoanana.”'),
  ('6ab25ba6fe70b6ef2ab49db4', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 20, '“Tsy zanako tena tiako ve i Efraima, ary zanaka mamin’ny foko? Isaky ny manameloka azy mantsy aho, dia tena mbola mahatsiaro azy ihany. Izany no mahatonga ahy hihetsi-po noho ny aminy. Ary tena hiantra azy aho”, hoy i Jehovah.', '“tsy zanako tena tiako ve i efraima, ary zanaka mamin’ny foko? isaky ny manameloka azy mantsy aho, dia tena mbola mahatsiaro azy ihany. izany no mahatonga ahy hihetsi-po noho ny aminy. ary tena hiantra azy aho”, hoy i jehovah.'),
  ('6ab25ba6fe70b6ef2ab49da8', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 8, 'Hoentiko miverina avy any amin’ilay tany any avaratra izy ireo. Hangoniko avy any amin’ny faritra lavitra indrindra amin’ny tany izy ireo. Ho eo daholo na ny jamba na ny malemy tongotra Na ny vehivavy bevohoka na ny efa ho teraka. Fiangonana lehibe izy ireo rehefa hiverina eto.', 'hoentiko miverina avy any amin’ilay tany any avaratra izy ireo. hangoniko avy any amin’ny faritra lavitra indrindra amin’ny tany izy ireo. ho eo daholo na ny jamba na ny malemy tongotra na ny vehivavy bevohoka na ny efa ho teraka. fiangonana lehibe izy ireo rehefa hiverina eto.'),
  ('6ab25ba6fe70b6ef2ab49da2', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 2, 'Izao no lazain’i Jehovah: “Nahazo sitraka tany an-tany efitra ireo olona tsy matin’ny sabatra, Rehefa nankany amin’ilay tany ialany sasatra ny Israely.”', 'izao no lazain’i jehovah: “nahazo sitraka tany an-tany efitra ireo olona tsy matin’ny sabatra, rehefa nankany amin’ilay tany ialany sasatra ny israely.”'),
  ('6ab25ba6fe70b6ef2ab49dac', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 12, 'Dia ho avy izy ireo ka hihoby eny amin’ny havoanan’i Ziona. Ary ho miramirana izy ireo noho ny hatsaran-toetran’i Jehovah, Noho ny varimbazaha sy ny divay vaovao sy ny menaka, Ary noho ny zanaky ny ondry aman’osy sy ny zanak’omby. Ho toy ny tanimboly azon-drano tsara izy ireo, Ka tsy ho reraka intsony mihitsy.”', 'dia ho avy izy ireo ka hihoby eny amin’ny havoanan’i ziona. ary ho miramirana izy ireo noho ny hatsaran-toetran’i jehovah, noho ny varimbazaha sy ny divay vaovao sy ny menaka, ary noho ny zanaky ny ondry aman’osy sy ny zanak’omby. ho toy ny tanimboly azon-drano tsara izy ireo, ka tsy ho reraka intsony mihitsy.”'),
  ('6ab25ba6fe70b6ef2ab49dad', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 13, '“Amin’izany fotoana izany, dia hifaly sy handihy ny virjiny, Sy ny tovolahy ary ny lehilahy efa antitra. Hovako ho fifaliana ny fahoriany. Hampiononiko izy ireo, ary hampifaliko mba hisinda ny alahelony.', '“amin’izany fotoana izany, dia hifaly sy handihy ny virjiny, sy ny tovolahy ary ny lehilahy efa antitra. hovako ho fifaliana ny fahoriany. hampiononiko izy ireo, ary hampifaliko mba hisinda ny alahelony.'),
  ('6ab25ba6fe70b6ef2ab49dbb', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 27, '“Henoy izao!”, hoy i Jehovah. “Ho avy ny andro hamafazako voa eo amin’ny taranak’Israely sy ny taranak’i Joda, ka olona sy biby fiompy no voa hafafiko.”', '“henoy izao!”, hoy i jehovah. “ho avy ny andro hamafazako voa eo amin’ny taranak’israely sy ny taranak’i joda, ka olona sy biby fiompy no voa hafafiko.”'),
  ('6ab25ba6fe70b6ef2ab49db1', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 17, '‘Misy antenaina ny hoavinao’, hoy i Jehovah. ‘Hiverina ao amin’ny faritra nisy azy ny zanakao lahy.’”', '‘misy antenaina ny hoavinao’, hoy i jehovah. ‘hiverina ao amin’ny faritra nisy azy ny zanakao lahy.’”'),
  ('6ab25ba6fe70b6ef2ab49daf', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 15, '“Izao no lazain’i Jehovah: ‘Misy feo re any Rama, dia feon’olona midradradradra sy mitomany be: Mitomany an’ireo zanany lahy i Rahely. Tsy mety hampiononina izy, Satria tsy eo intsony izy ireny.’”', '“izao no lazain’i jehovah: ‘misy feo re any rama, dia feon’olona midradradradra sy mitomany be: mitomany an’ireo zanany lahy i rahely. tsy mety hampiononina izy, satria tsy eo intsony izy ireny.’”'),
  ('6ab25ba6fe70b6ef2ab49dae', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 14, 'Hataoko afa-po amin’ny sakafo tondraka ny mpisorona, Ary ny vahoakako ho vokin’ny hatsaran-toetrako”, hoy i Jehovah.', 'hataoko afa-po amin’ny sakafo tondraka ny mpisorona, ary ny vahoakako ho vokin’ny hatsaran-toetrako”, hoy i jehovah.'),
  ('6ab25ba6fe70b6ef2ab49dab', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 11, 'Fa hanavotra an’i Jakoba i Jehovah, Ka hamonjy azy eo am-pelatanan’ilay mahery noho izy.', 'fa hanavotra an’i jakoba i jehovah, ka hamonjy azy eo am-pelatanan’ilay mahery noho izy.'),
  ('6ab25ba6fe70b6ef2ab49da4', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 4, 'Haoriko indray ianao ka ho voaorina. Mbola haka ny ampongatapakao indray ianao, ry Israely virjiny ô, Ka hivoaka handihy sy hifaly.', 'haoriko indray ianao ka ho voaorina. mbola haka ny ampongatapakao indray ianao, ry israely virjiny ô, ka hivoaka handihy sy hifaly.'),
  ('6ab25ba6fe70b6ef2ab49db2', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 18, '“Henoko tokoa i Efraima nitaraina hoe: ‘Nanitsy ahy ianao ka nanaiky hahitsy aho, Toy ny zanak’omby mbola tsy nofolahina. Ento miverina aho, dia hiverina avy hatrany, Satria ianao no Jehovah Andriamanitro.', '“henoko tokoa i efraima nitaraina hoe: ‘nanitsy ahy ianao ka nanaiky hahitsy aho, toy ny zanak’omby mbola tsy nofolahina. ento miverina aho, dia hiverina avy hatrany, satria ianao no jehovah andriamanitro.'),
  ('6ab25ba6fe70b6ef2ab49db7', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 23, 'Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Rehefa angoniko ireo mponin’i Joda lasa babo, dia hisy hiteny indray any Joda sy ao amin’ireo tanànany hoe: ‘Hotahin’i Jehovah anie ianao, ry fonenan’ny fahamarinana sy tendrombohitra masina ô!’', 'izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: “rehefa angoniko ireo mponin’i joda lasa babo, dia hisy hiteny indray any joda sy ao amin’ireo tanànany hoe: ‘hotahin’i jehovah anie ianao, ry fonenan’ny fahamarinana sy tendrombohitra masina ô!’'),
  ('6ab25ba6fe70b6ef2ab49da6', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 6, 'Fa ho avy ny andro hiantsoantsoan’ny mpitily eny an-tendrombohitr’i Efraima hoe: ‘Mitsangàna, andao hiakatra any Ziona, any amin’i Jehovah Andriamanitsika!’”', 'fa ho avy ny andro hiantsoantsoan’ny mpitily eny an-tendrombohitr’i efraima hoe: ‘mitsangàna, andao hiakatra any ziona, any amin’i jehovah andriamanitsika!’”'),
  ('6ab25ba6fe70b6ef2ab49da3', '2026-09-22T10:42:46.302Z', '2026-09-22T10:42:46.302Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 3, 'Niseho tamiko avy lavitra i Jehovah, ka nilaza hoe: “Fitiavana mandrakizay no itiavako anao. Izany no nahatonga ahy hitaona anao hanatona ahy, satria tia anao sy tsy mivadika aminao aho.', 'niseho tamiko avy lavitra i jehovah, ka nilaza hoe: “fitiavana mandrakizay no itiavako anao. izany no nahatonga ahy hitaona anao hanatona ahy, satria tia anao sy tsy mivadika aminao aho.'),
  ('6ab25ba6fe70b6ef2ab49dc5', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 37, 'Izao no lazain’i Jehovah: “‘Raha misy mahavita mandrefy ny lanitra ambony, sy mitsidika ny fototry ny tany mba hahalalana an’izay misy any, dia amin’izay ihany aho vao ho afaka handa ny taranak’Israely manontolo, noho izay rehetra nataon’izy ireo’, hoy i Jehovah.”', 'izao no lazain’i jehovah: “‘raha misy mahavita mandrefy ny lanitra ambony, sy mitsidika ny fototry ny tany mba hahalalana an’izay misy any, dia amin’izay ihany aho vao ho afaka handa ny taranak’israely manontolo, noho izay rehetra nataon’izy ireo’, hoy i jehovah.”'),
  ('6ab25ba6fe70b6ef2ab49dc2', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 34, '“Samy tsy hampianatra ny namany sy ny rahalahiny intsony izy ireo hoe: ‘Fantaro i Jehovah!’ Hahafantatra ahy mantsy izy rehetra, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra”, hoy i Jehovah. “Fa havelako ny fahadisoany, ary tsy hotsaroako intsony ny fahotany.”', '“samy tsy hampianatra ny namany sy ny rahalahiny intsony izy ireo hoe: ‘fantaro i jehovah!’ hahafantatra ahy mantsy izy rehetra, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra”, hoy i jehovah. “fa havelako ny fahadisoany, ary tsy hotsaroako intsony ny fahotany.”'),
  ('6ab25ba6fe70b6ef2ab49dc6', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 38, '“Henoy izao!”, hoy i Jehovah. “Ho avy ny andro hanorenana indray ny tanàna ho an’i Jehovah, manomboka eo amin’ny Tilikambon’i Hananela ka hatrany amin’ny Vavahady An-jorony.', '“henoy izao!”, hoy i jehovah. “ho avy ny andro hanorenana indray ny tanàna ho an’i jehovah, manomboka eo amin’ny tilikambon’i hananela ka hatrany amin’ny vavahady an-jorony.'),
  ('6ab25ba6fe70b6ef2ab49dc7', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 39, 'Mbola hohenjanina mahitsy hatrany amin’ny havoanan’i Gareba ny tady fandrefesana, ary hihodina mankany Goa.', 'mbola hohenjanina mahitsy hatrany amin’ny havoanan’i gareba ny tady fandrefesana, ary hihodina mankany goa.'),
  ('6ab25ba6fe70b6ef2ab49dc3', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 35, 'Izao no lazain’i Jehovah, Ilay manome ny masoandro mba hanazava amin’ny andro, Sy manome lalàna mifehy ny volana sy ny kintana mba hanazava amin’ny alina, Ilay mampisamboaravoara ny ranomasina sy mampidoboka ny onjany, Ilay manana anarana hoe Jehovah Tompon’ny tafika:', 'izao no lazain’i jehovah, ilay manome ny masoandro mba hanazava amin’ny andro, sy manome lalàna mifehy ny volana sy ny kintana mba hanazava amin’ny alina, ilay mampisamboaravoara ny ranomasina sy mampidoboka ny onjany, ilay manana anarana hoe jehovah tompon’ny tafika:'),
  ('6ab25ba6fe70b6ef2ab49dc4', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 36, '“‘Raha sanatria ka tsy manan-kery intsony ireny lalàna ireny’, hoy i Jehovah, ‘Dia amin’izay ihany ny taranak’Israely vao tsy ho firenena eo anatrehako intsony.’”', '“‘raha sanatria ka tsy manan-kery intsony ireny lalàna ireny’, hoy i jehovah, ‘dia amin’izay ihany ny taranak’israely vao tsy ho firenena eo anatrehako intsony.’”'),
  ('6ab25ba6fe70b6ef2ab49dc1', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 33, '“Fa izao no fifanekena hataoko amin’ny taranak’Israely, aorian’izany andro izany”, hoy i Jehovah: “Hataoko ao anatin’izy ireo ny lalàko, sady hosoratako ao am-pony. Dia ho Andriamaniny aho, ary izy ireo ho vahoakako.”', '“fa izao no fifanekena hataoko amin’ny taranak’israely, aorian’izany andro izany”, hoy i jehovah: “hataoko ao anatin’izy ireo ny lalàko, sady hosoratako ao am-pony. dia ho andriamaniny aho, ary izy ireo ho vahoakako.”'),
  ('6ab25ba6fe70b6ef2ab49dc8', '2026-09-22T10:42:46.303Z', '2026-09-22T10:42:46.303Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 31, 40, 'Ho masina amin’i Jehovah ny lohasaha rehetra fanariana faty sy lavenona, sy ny tanimboly mikitohatohatra rehetra hatrany amin’ny Lohasahan’i Kidrona, ary hatrany amin’ny zoron’ny Vavahadin-tsoavaly any atsinanana. Tsy hongotana intsony mihitsy izany na horavana.”', 'ho masina amin’i jehovah ny lohasaha rehetra fanariana faty sy lavenona, sy ny tanimboly mikitohatohatra rehetra hatrany amin’ny lohasahan’i kidrona, ary hatrany amin’ny zoron’ny vavahadin-tsoavaly any atsinanana. tsy hongotana intsony mihitsy izany na horavana.”'),
  ('6ab25baeb8bf577c04abd97c', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 11, 'Henon’i Johanana zanak’i Karea sy ny lehiben’ny tafika rehetra niaraka taminy ny ratsy rehetra nataon’i Ismaela zanak’i Netania.', 'henon’i johanana zanak’i karea sy ny lehiben’ny tafika rehetra niaraka taminy ny ratsy rehetra nataon’i ismaela zanak’i netania.'),
  ('6ab25baeb8bf577c04abd97e', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 13, 'Faly ny olona rehetra nentin’i Ismaela, rehefa nahita an’i Johanana zanak’i Karea sy ny lehiben’ny tafika rehetra niaraka taminy.', 'faly ny olona rehetra nentin’i ismaela, rehefa nahita an’i johanana zanak’i karea sy ny lehiben’ny tafika rehetra niaraka taminy.'),
  ('6ab25baeb8bf577c04abd978', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 7, 'Novonoin’i Ismaela zanak’i Netania sy ireo lehilahy niaraka taminy anefa izy ireo rehefa tonga tao an-tanàna. Dia natsipiny tao anaty lavaka fanangonan-drano ny fatin’izy ireo.', 'novonoin’i ismaela zanak’i netania sy ireo lehilahy niaraka taminy anefa izy ireo rehefa tonga tao an-tanàna. dia natsipiny tao anaty lavaka fanangonan-drano ny fatin’izy ireo.'),
  ('6ab25baeb8bf577c04abd977', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 6, 'Koa nivoaka avy tao Mizpa i Ismaela zanak’i Netania mba hitsena azy ireo, ka sady nitomany izy no nandeha. Rehefa nihaona tamin’izy ireo izy, dia niteny hoe: “Andao ho any amin’i Gedalia zanak’i Ahikama.”', 'koa nivoaka avy tao mizpa i ismaela zanak’i netania mba hitsena azy ireo, ka sady nitomany izy no nandeha. rehefa nihaona tamin’izy ireo izy, dia niteny hoe: “andao ho any amin’i gedalia zanak’i ahikama.”'),
  ('6ab25baeb8bf577c04abd980', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 15, 'Fa i Ismaela zanak’i Netania sy ny lehilahy valo niaraka taminy kosa tafatsoaka an’i Johanana, ka nankany amin’ny Amonita.', 'fa i ismaela zanak’i netania sy ny lehilahy valo niaraka taminy kosa tafatsoaka an’i johanana, ka nankany amin’ny amonita.'),
  ('6ab25baeb8bf577c04abd976', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 5, 'dia nisy 80 lahy tonga avy any Sekema sy Silo ary Samaria. Efa nesorin’izy ireo ny volombavany, norovitiny ny akanjony, ary nodidididiany ny vatany. Nivimbina fanatitra varimbazaha sy ditin-kazo manitra izy ireo mba hoentiny ao an-tranon’i Jehovah.', 'dia nisy 80 lahy tonga avy any sekema sy silo ary samaria. efa nesorin’izy ireo ny volombavany, norovitiny ny akanjony, ary nodidididiany ny vatany. nivimbina fanatitra varimbazaha sy ditin-kazo manitra izy ireo mba hoentiny ao an-tranon’i jehovah.'),
  ('6ab25baeb8bf577c04abd97b', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 10, 'Dia nentin’i Ismaela ho babo ny vahoaka sisa rehetra tany Mizpa, anisan’izany ireo zanakavavin’ny mpanjaka sy ny olona rehetra tavela tany Mizpa, izay nankinin’i Nebozaradana lehiben’ny mpiambina tamin’i Gedalia zanak’i Ahikama. Nentin’i Ismaela zanak’i Netania ho babo izy ireo, ary nentiny nankany amin’ny Amonita.', 'dia nentin’i ismaela ho babo ny vahoaka sisa rehetra tany mizpa, anisan’izany ireo zanakavavin’ny mpanjaka sy ny olona rehetra tavela tany mizpa, izay nankinin’i nebozaradana lehiben’ny mpiambina tamin’i gedalia zanak’i ahikama. nentin’i ismaela zanak’i netania ho babo izy ireo, ary nentiny nankany amin’ny amonita.'),
  ('6ab25baeb8bf577c04abd97a', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 9, 'Dia natsipin’i Ismaela tao amin’ny lavaka fanangonan-drano iray lehibe ny fatin’ireo lehilahy rehetra novonoiny. I Asa Mpanjaka no nanao azy io tamin’izy norahonan’i Basa mpanjakan’ny Israely. Io ilay lavaka nofenoin’i Ismaela, zanak’i Netania, faty.', 'dia natsipin’i ismaela tao amin’ny lavaka fanangonan-drano iray lehibe ny fatin’ireo lehilahy rehetra novonoiny. i asa mpanjaka no nanao azy io tamin’izy norahonan’i basa mpanjakan’ny israely. io ilay lavaka nofenoin’i ismaela, zanak’i netania, faty.'),
  ('6ab25baeb8bf577c04abd974', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 3, 'Novonoiny daholo koa ireo Jiosy niaraka tamin’i Gedalia tany Mizpa, sy ireo miaramila kaldeanina tany.', 'novonoiny daholo koa ireo jiosy niaraka tamin’i gedalia tany mizpa, sy ireo miaramila kaldeanina tany.'),
  ('6ab25baeb8bf577c04abd983', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 18, 'noho ny amin’ny Kaldeanina. Natahotra an’ireo Kaldeanina mantsy izy ireo, satria novonoin’i Ismaela zanak’i Netania i Gedalia zanak’i Ahikama, ilay notendren’ny mpanjakan’i Babylona hitondra an’ilay tany.', 'noho ny amin’ny kaldeanina. natahotra an’ireo kaldeanina mantsy izy ireo, satria novonoin’i ismaela zanak’i netania i gedalia zanak’i ahikama, ilay notendren’ny mpanjakan’i babylona hitondra an’ilay tany.'),
  ('6ab25baeb8bf577c04abd97f', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 14, 'Dia niverin-dalana ny olona rehetra nalain’i Ismaela ho babo avy tany Mizpa, ka niaraka tamin’i Johanana zanak’i Karea.', 'dia niverin-dalana ny olona rehetra nalain’i ismaela ho babo avy tany mizpa, ka niaraka tamin’i johanana zanak’i karea.'),
  ('6ab25baeb8bf577c04abd97d', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 12, 'Nangonin’izy ireo àry ny miaramila rehetra, dia niainga izy ireo mba hiady tamin’i Ismaela zanak’i Netania. Ary nahita azy teo akaikin’ny rano be tao Gibeona izy ireo.', 'nangonin’izy ireo àry ny miaramila rehetra, dia niainga izy ireo mba hiady tamin’i ismaela zanak’i netania. ary nahita azy teo akaikin’ny rano be tao gibeona izy ireo.'),
  ('6ab25baeb8bf577c04abd972', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 1, 'Tamin’ny volana fahafito dia tonga tany Mizpa, tany amin’i Gedalia zanak’i Ahikama, i Ismaela zanak’i Netania zanak’i Elisama, ary nisy folo lahy niaraka taminy. Taranaka mpanjaka i Ismaela sady anisan’ny manamboninahitry ny mpanjaka. Raha mbola teo am-pisakafoana tany Mizpa izy ireo,', 'tamin’ny volana fahafito dia tonga tany mizpa, tany amin’i gedalia zanak’i ahikama, i ismaela zanak’i netania zanak’i elisama, ary nisy folo lahy niaraka taminy. taranaka mpanjaka i ismaela sady anisan’ny manamboninahitry ny mpanjaka. raha mbola teo am-pisakafoana tany mizpa izy ireo,'),
  ('6ab25baeb8bf577c04abd982', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 17, 'Dia nandeha izy ireo ka nijanona teo amin’ny toeram-pilasian’i Kimama, teo akaikin’i Betlehema. Nieritreritra ny ho any Ejipta izy ireo,', 'dia nandeha izy ireo ka nijanona teo amin’ny toeram-pilasian’i kimama, teo akaikin’i betlehema. nieritreritra ny ho any ejipta izy ireo,'),
  ('6ab25baeb8bf577c04abd979', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 8, 'Nisy folo lahy tamin’izy ireo anefa niteny tamin’i Ismaela hoe: “Aza vonoina izahay, fa izahay manana tahirina varimbazaha sy vary orza sy menaka ary tantely nafeninay any an-tsaha.” Koa tsy novonoiny niaraka tamin’ireo rahalahiny izy ireo.', 'nisy folo lahy tamin’izy ireo anefa niteny tamin’i ismaela hoe: “aza vonoina izahay, fa izahay manana tahirina varimbazaha sy vary orza sy menaka ary tantely nafeninay any an-tsaha.” koa tsy novonoiny niaraka tamin’ireo rahalahiny izy ireo.'),
  ('6ab25baeb8bf577c04abd981', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 16, 'Nalain’i Johanana zanak’i Karea sy ny lehiben’ny tafika rehetra niaraka taminy, ny vahoaka sisa rehetra avy tany Mizpa, izay nafahany avy teo an-tanan’i Ismaela zanak’i Netania, taorian’ny namonoan’i Ismaela an’i Gedalia zanak’i Ahikama. Nentiny niverina niaraka tamin’izy ireo avy tany Gibeona, na lehilahy, na miaramila, na vehivavy, na ankizy, na tandapa.', 'nalain’i johanana zanak’i karea sy ny lehiben’ny tafika rehetra niaraka taminy, ny vahoaka sisa rehetra avy tany mizpa, izay nafahany avy teo an-tanan’i ismaela zanak’i netania, taorian’ny namonoan’i ismaela an’i gedalia zanak’i ahikama. nentiny niverina niaraka tamin’izy ireo avy tany gibeona, na lehilahy, na miaramila, na vehivavy, na ankizy, na tandapa.'),
  ('6ab25baeb8bf577c04abd975', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 4, 'Ny ampitson’ny namonoana an’i Gedalia, raha mbola tsy nisy nahalala mihitsy izany,', 'ny ampitson’ny namonoana an’i gedalia, raha mbola tsy nisy nahalala mihitsy izany,'),
  ('6ab25baeb8bf577c04abd973', '2026-09-22T10:42:54.809Z', '2026-09-22T10:42:54.809Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 41, 2, 'dia nitsangana i Ismaela zanak’i Netania sy ireo folo lahy niaraka taminy, ka nasian’izy ireo tamin’ny sabatra i Gedalia zanak’i Ahikama, zanak’i Safana. Koa novonoin’i Ismaela ilay olona notendren’ny mpanjakan’i Babylona hitondra an’ilay tany.', 'dia nitsangana i ismaela zanak’i netania sy ireo folo lahy niaraka taminy, ka nasian’izy ireo tamin’ny sabatra i gedalia zanak’i ahikama, zanak’i safana. koa novonoin’i ismaela ilay olona notendren’ny mpanjakan’i babylona hitondra an’ilay tany.'),
  ('6ab25bafa042bf657140b0d6', '2026-09-22T10:42:55.349Z', '2026-09-22T10:42:55.349Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 2, 'Hoy izy ireo tamin’i Jeremia mpaminany: “Mba henoy re ny fitalahoanay e, ka mivavaha amin’i Jehovah Andriamanitrao ho anay rehetra tavela eto! Be dia be mantsy izahay taloha nefa ireo sisa, araka izao hitanao izao.', 'hoy izy ireo tamin’i jeremia mpaminany: “mba henoy re ny fitalahoanay e, ka mivavaha amin’i jehovah andriamanitrao ho anay rehetra tavela eto! be dia be mantsy izahay taloha nefa ireo sisa, araka izao hitanao izao.'),
  ('6ab25bafa042bf657140b0d7', '2026-09-22T10:42:55.349Z', '2026-09-22T10:42:55.349Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 3, 'I Jehovah Andriamanitrao anie hilaza aminay ny lalana tokony halehanay sy izay tokony hataonay!”', 'i jehovah andriamanitrao anie hilaza aminay ny lalana tokony halehanay sy izay tokony hataonay!”'),
  ('6ab25bafa042bf657140b0d8', '2026-09-22T10:42:55.349Z', '2026-09-22T10:42:55.349Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 4, 'Dia namaly azy ireo i Jeremia mpaminany hoe: “Eny àry fa efa re izay! Hivavaka amin’i Jehovah Andriamanitrareo aho araka izany fangatahanareo izany. Ary holazaiko aminareo daholo izay teny havalin’i Jehovah anareo. Tsy hisy teny hafeniko aminareo, na iray aza.”', 'dia namaly azy ireo i jeremia mpaminany hoe: “eny àry fa efa re izay! hivavaka amin’i jehovah andriamanitrareo aho araka izany fangatahanareo izany. ary holazaiko aminareo daholo izay teny havalin’i jehovah anareo. tsy hisy teny hafeniko aminareo, na iray aza.”'),
  ('6ab25bafa042bf657140b0d5', '2026-09-22T10:42:55.349Z', '2026-09-22T10:42:55.349Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 1, 'Dia nanatona an’i Jeremia ny lehiben’ny tafika rehetra, sy Johanana zanak’i Karea, sy Jazania zanak’i Hosaia, ary ny vahoaka manontolo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra.', 'dia nanatona an’i jeremia ny lehiben’ny tafika rehetra, sy johanana zanak’i karea, sy jazania zanak’i hosaia, ary ny vahoaka manontolo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra.'),
  ('6ab25bafa042bf657140b0da', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 6, 'Hankatoavinay ny tenin’i Jehovah Andriamanitray, ilay nasainay nanontanianao, na mety aminay ilay izy na tsia. Amin’izay dia hahita soa izahay satria mankatò ny tenin’i Jehovah Andriamanitray.”', 'hankatoavinay ny tenin’i jehovah andriamanitray, ilay nasainay nanontanianao, na mety aminay ilay izy na tsia. amin’izay dia hahita soa izahay satria mankatò ny tenin’i jehovah andriamanitray.”'),
  ('6ab25bafa042bf657140b0dc', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 8, 'Koa nantsoin’i Jeremia i Johanana zanak’i Karea, sy ny lehiben’ny tafika rehetra niaraka taminy, ary ny vahoaka manontolo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra.', 'koa nantsoin’i jeremia i johanana zanak’i karea, sy ny lehiben’ny tafika rehetra niaraka taminy, ary ny vahoaka manontolo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra.'),
  ('6ab25bafa042bf657140b0e2', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 14, 'fa milaza hoe: “Tsia! Aleonay ihany mankany Ejipta, fa tsy hahita ady izahay rehefa any sady tsy handre feon’anjombona, ary tsy ho ory sakafo. Any izahay no hipetraka.”', 'fa milaza hoe: “tsia! aleonay ihany mankany ejipta, fa tsy hahita ady izahay rehefa any sady tsy handre feon’anjombona, ary tsy ho ory sakafo. any izahay no hipetraka.”'),
  ('6ab25bafa042bf657140b0dd', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 9, 'Dia hoy izy tamin’izy ireo: “Naniraka ahy ianareo mba hitalaho amin’i Jehovah Andriamanitry ny Israely ho anareo, ka izao no lazainy:', 'dia hoy izy tamin’izy ireo: “naniraka ahy ianareo mba hitalaho amin’i jehovah andriamanitry ny israely ho anareo, ka izao no lazainy:'),
  ('6ab25bafa042bf657140b0e9', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 21, 'Dia izany no noteneniko taminareo androany, nefa tsy hankatò ny tenin’i Jehovah Andriamanitrareo ianareo na hanao izay nasainy nolazaiko taminareo.', 'dia izany no noteneniko taminareo androany, nefa tsy hankatò ny tenin’i jehovah andriamanitrareo ianareo na hanao izay nasainy nolazaiko taminareo.'),
  ('6ab25bafa042bf657140b0ea', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 22, 'Koa fantaro tsara fa ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana any amin’ilay toerana tianareo handehanana sy hipetrahana ianareo.”', 'koa fantaro tsara fa ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana any amin’ilay toerana tianareo handehanana sy hipetrahana ianareo.”'),
  ('6ab25bafa042bf657140b0df', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 11, 'Aza atahorana ny mpanjakan’i Babylona, izay atahoranareo.’ “‘Aza matahotra azy’, hoy i Jehovah, ‘fa ho eo foana aho, mba hamonjy sy hanafaka anareo tsy ho azon’ny tanany.', 'aza atahorana ny mpanjakan’i babylona, izay atahoranareo.’ “‘aza matahotra azy’, hoy i jehovah, ‘fa ho eo foana aho, mba hamonjy sy hanafaka anareo tsy ho azon’ny tanany.'),
  ('6ab25bafa042bf657140b0e5', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 17, 'Ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana izay rehetra tapa-kevitra ny ho any Ejipta mba hipetraka any. Tsy hisy hiangana izy ireo ary tsy hisy ho afa-mandositra an’ilay loza hamelezako azy.”’', 'ho fatin’ny sabatra sy ny mosary ary ny areti-mandringana izay rehetra tapa-kevitra ny ho any ejipta mba hipetraka any. tsy hisy hiangana izy ireo ary tsy hisy ho afa-mandositra an’ilay loza hamelezako azy.”’'),
  ('6ab25bafa042bf657140b0d9', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 5, 'Hoy izy ireo tamin’i Jeremia: “I Jehovah anie no ho vavolombelona marina sy mendri-pitokisana hiampanga anay, raha tsy arahinay an-tsakany sy an-davany izay asain’i Jehovah Andriamanitrao lazainao aminay!', 'hoy izy ireo tamin’i jeremia: “i jehovah anie no ho vavolombelona marina sy mendri-pitokisana hiampanga anay, raha tsy arahinay an-tsakany sy an-davany izay asain’i jehovah andriamanitrao lazainao aminay!'),
  ('6ab25bafa042bf657140b0de', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 10, '‘Raha mijanona eto amin’ity tany ity tokoa ianareo, dia haoriko fa tsy horavako, ary hamboleko fa tsy hongotako. Fa hanenina aho noho ny loza namelezako anareo.', '‘raha mijanona eto amin’ity tany ity tokoa ianareo, dia haoriko fa tsy horavako, ary hamboleko fa tsy hongotako. fa hanenina aho noho ny loza namelezako anareo.'),
  ('6ab25bafa042bf657140b0db', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 7, 'Dia nampita ny teniny tamin’i Jeremia i Jehovah rehefa afaka folo andro.', 'dia nampita ny teniny tamin’i jeremia i jehovah rehefa afaka folo andro.'),
  ('6ab25bafa042bf657140b0e4', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 16, 'dia hahatratra anareo any Ejipta ny sabatra izay atahoranareo, ary hanaraka anareo any ny mosary izay mampanahy anareo, ka any ianareo no ho faty.', 'dia hahatratra anareo any ejipta ny sabatra izay atahoranareo, ary hanaraka anareo any ny mosary izay mampanahy anareo, ka any ianareo no ho faty.'),
  ('6ab25bafa042bf657140b0e0', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 12, 'Hamindra fo aminareo aho, dia hamindra fo aminareo izy ka hampody anareo eto amin’ny taninareo.', 'hamindra fo aminareo aho, dia hamindra fo aminareo izy ka hampody anareo eto amin’ny taninareo.'),
  ('6ab25bafa042bf657140b0e3', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 15, 'Dia henoy ny tenin’i Jehovah, ry sisa tavela amin’ny Joda! Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Raha tena tapa-kevitra ny ho any Ejipta ianareo ka mandeha mipetraka any,', 'dia henoy ny tenin’i jehovah, ry sisa tavela amin’ny joda! izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: “raha tena tapa-kevitra ny ho any ejipta ianareo ka mandeha mipetraka any,'),
  ('6ab25bafa042bf657140b0e6', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 18, '“Fa hoy i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Toy ny nanamparako ny hatezerako sy ny fahavinirako tamin’ny mponin’i Jerosalema, no hanamparako ny hatezerako aminareo raha mankany Ejipta ianareo. Hanozona anareo ny olona ary hihorohoro mahita an’izay hanjo anareo. Hanala baraka sy handatsa anareo koa izy ireo. Ary tsy hahita an’ity toerana ity intsony mihitsy ianareo.’', '“fa hoy i jehovah tompon’ny tafika, andriamanitry ny israely: ‘toy ny nanamparako ny hatezerako sy ny fahavinirako tamin’ny mponin’i jerosalema, no hanamparako ny hatezerako aminareo raha mankany ejipta ianareo. hanozona anareo ny olona ary hihorohoro mahita an’izay hanjo anareo. hanala baraka sy handatsa anareo koa izy ireo. ary tsy hahita an’ity toerana ity intsony mihitsy ianareo.’'),
  ('6ab25bafa042bf657140b0e1', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 13, '“‘Fa raha hoy kosa ianareo: “Tsia! Tsy hijanona eto amin’ity tany ity izahay!”, ka tsy mankatò ny tenin’i Jehovah Andriamanitrareo ianareo,', '“‘fa raha hoy kosa ianareo: “tsia! tsy hijanona eto amin’ity tany ity izahay!”, ka tsy mankatò ny tenin’i jehovah andriamanitrareo ianareo,'),
  ('6ab25bafa042bf657140b0e8', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 20, 'hoe hafoinareo ny ainareo noho ny fahadisoanareo. Naniraka ahy ho any amin’i Jehovah Andriamanitrareo mantsy ianareo, ka nilaza hoe: ‘Mivavaha amin’i Jehovah Andriamanitray ho anay. Ary teneno aminay izay rehetra lazain’i Jehovah Andriamanitray, dia hataonay.’', 'hoe hafoinareo ny ainareo noho ny fahadisoanareo. naniraka ahy ho any amin’i jehovah andriamanitrareo mantsy ianareo, ka nilaza hoe: ‘mivavaha amin’i jehovah andriamanitray ho anay. ary teneno aminay izay rehetra lazain’i jehovah andriamanitray, dia hataonay.’'),
  ('6ab25bafa042bf657140b0e7', '2026-09-22T10:42:55.350Z', '2026-09-22T10:42:55.350Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 42, 19, '“Efa niteny anareo i Jehovah, ry sisa amin’ny Joda ô! Aza mankany Ejipta. Fantaro tsara fa efa nampitandrina anareo aho androany', '“efa niteny anareo i jehovah, ry sisa amin’ny joda ô! aza mankany ejipta. fantaro tsara fa efa nampitandrina anareo aho androany'),
  ('6ab25bafb3e8382a64ea46de', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 3, 'Fa i Baroka zanak’i Neria no nampirisika anao hiteny an’izany, amin’izay hatolotra eo an-tanan’ny Kaldeanina izahay, dia ho faty na hatao sesitany any Babylona.”', 'fa i baroka zanak’i neria no nampirisika anao hiteny an’izany, amin’izay hatolotra eo an-tanan’ny kaldeanina izahay, dia ho faty na hatao sesitany any babylona.”'),
  ('6ab25bafb3e8382a64ea46df', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 4, 'Koa tsy nankatoavin’i Johanana zanak’i Karea sy ny lehiben’ ny tafika rehetra ary ny vahoaka manontolo ilay tenin’i Jehovah hoe mijanòna ao Joda.', 'koa tsy nankatoavin’i johanana zanak’i karea sy ny lehiben’ ny tafika rehetra ary ny vahoaka manontolo ilay tenin’i jehovah hoe mijanòna ao joda.'),
  ('6ab25bafb3e8382a64ea46e1', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 6, 'Nentin’izy ireo ny lehilahy, ny vehivavy, ny ankizy, ireo zanakavavin’ny mpanjaka, ary ny olona rehetra navelan’i Nebozaradana lehiben’ny mpiambina hijanona niaraka tamin’i Gedalia zanak’i Ahikama, zanak’i Safana. Nentin’izy ireo koa i Jeremia mpaminany sy Baroka zanak’i Neria.', 'nentin’izy ireo ny lehilahy, ny vehivavy, ny ankizy, ireo zanakavavin’ny mpanjaka, ary ny olona rehetra navelan’i nebozaradana lehiben’ny mpiambina hijanona niaraka tamin’i gedalia zanak’i ahikama, zanak’i safana. nentin’izy ireo koa i jeremia mpaminany sy baroka zanak’i neria.'),
  ('6ab25bafb3e8382a64ea46e4', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 9, '“Makà vato lehibe vitsivitsy dia afeno ao anaty rihitra, eo amin’ilay tokotany biriky, eo amin’ny fidirana amin’ny tranon’i Farao any Tapanesa. Ataovy eo imason’ny lehilahy jiosy izany.', '“makà vato lehibe vitsivitsy dia afeno ao anaty rihitra, eo amin’ilay tokotany biriky, eo amin’ny fidirana amin’ny tranon’i farao any tapanesa. ataovy eo imason’ny lehilahy jiosy izany.'),
  ('6ab25bafb3e8382a64ea46e7', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 12, 'Hodorako ny tranon’ireo andriamanitr’i Ejipta. Dia hodorany ireny ary hoentiny ho babo izy ireo. Hitafy an’i Ejipta toy ny fitafin’ny mpiandry ondry ny lambany izy, ka hilamina tsara ny fialany any.', 'hodorako ny tranon’ireo andriamanitr’i ejipta. dia hodorany ireny ary hoentiny ho babo izy ireo. hitafy an’i ejipta toy ny fitafin’ny mpiandry ondry ny lambany izy, ka hilamina tsara ny fialany any.'),
  ('6ab25bafb3e8382a64ea46e5', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 10, 'Ary lazao amin’izy ireo hoe: ‘Izao no tenin’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: “Hampiantso an’i Nebokadnezara mpanjakan’i Babylona sady mpanompoko aho. Hapetrako eo ambonin’ireo vato nafeniko ireo ny seza fiandrianany, ary hovelariny eo ambonin’ireo ny tranolainy.', 'ary lazao amin’izy ireo hoe: ‘izao no tenin’i jehovah tompon’ny tafika, andriamanitry ny israely: “hampiantso an’i nebokadnezara mpanjakan’i babylona sady mpanompoko aho. hapetrako eo ambonin’ireo vato nafeniko ireo ny seza fiandrianany, ary hovelariny eo ambonin’ireo ny tranolainy.'),
  ('6ab25bafb3e8382a64ea46e3', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 8, 'Dia niteny tamin’i Jeremia tany Tapanesa i Jehovah hoe:', 'dia niteny tamin’i jeremia tany tapanesa i jehovah hoe:'),
  ('6ab25bafb3e8382a64ea46dc', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 1, 'Rehefa voalazan’i Jeremia tamin’ny vahoaka manontolo ireo teny rehetra nolazain’i Jehovah Andriamaniny ireo, izany hoe izay rehetra nasain’i Jehovah Andriamaniny nolazainy tamin’izy ireo,', 'rehefa voalazan’i jeremia tamin’ny vahoaka manontolo ireo teny rehetra nolazain’i jehovah andriamaniny ireo, izany hoe izay rehetra nasain’i jehovah andriamaniny nolazainy tamin’izy ireo,'),
  ('6ab25bafb3e8382a64ea46dd', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 2, 'dia niteny tamin’i Jeremia i Azaria zanak’i Hosaia sy Johanana zanak’i Karea ary ny lehilahy rehetra nanambony tena hoe: “Mandainga ianao! Tsy naniraka anao hilaza aminay i Jehovah Andriamanitray hoe: ‘Aza mandeha mipetraka any Ejipta.’', 'dia niteny tamin’i jeremia i azaria zanak’i hosaia sy johanana zanak’i karea ary ny lehilahy rehetra nanambony tena hoe: “mandainga ianao! tsy naniraka anao hilaza aminay i jehovah andriamanitray hoe: ‘aza mandeha mipetraka any ejipta.’'),
  ('6ab25bafb3e8382a64ea46e6', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 11, 'Dia ho avy hamely an’i Ejipta izy, ka ho tratran’ny loza mahafaty izay natao ho tratran’ny loza mahafaty. Ho lasa babo izay natao ho lasa babo. Ary ho fatin’ny sabatra izay natao ho fatin’ny sabatra.', 'dia ho avy hamely an’i ejipta izy, ka ho tratran’ny loza mahafaty izay natao ho tratran’ny loza mahafaty. ho lasa babo izay natao ho lasa babo. ary ho fatin’ny sabatra izay natao ho fatin’ny sabatra.'),
  ('6ab25bafb3e8382a64ea46e0', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 5, 'Fa nentin’i Johanana zanak’i Karea sy ny lehiben’ny tafika rehetra niaraka tamin’izy ireo kosa ny sisa rehetra amin’ny Joda, izany hoe ireo niverina avy any amin’ny firenena rehetra nanaparitahana azy mba hipetraka tao Joda.', 'fa nentin’i johanana zanak’i karea sy ny lehiben’ny tafika rehetra niaraka tamin’izy ireo kosa ny sisa rehetra amin’ny joda, izany hoe ireo niverina avy any amin’ny firenena rehetra nanaparitahana azy mba hipetraka tao joda.'),
  ('6ab25bafb3e8382a64ea46e8', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 13, 'Dia hopotipotehiny ireo andry ao Beti-semesy any Ejipta, ary hodorany amin’ny afo ny tranon’ireo andriamanitr’i Ejipta.”’”', 'dia hopotipotehiny ireo andry ao beti-semesy any ejipta, ary hodorany amin’ny afo ny tranon’ireo andriamanitr’i ejipta.”’”'),
  ('6ab25bafb3e8382a64ea46e2', '2026-09-22T10:42:55.890Z', '2026-09-22T10:42:55.890Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 43, 7, 'Tsy nankatoavin’izy ireo ny tenin’i Jehovah, ka nankany Ejipta izy ireo ary tonga hatrany Tapanesa mihitsy.', 'tsy nankatoavin’izy ireo ny tenin’i jehovah, ka nankany ejipta izy ireo ary tonga hatrany tapanesa mihitsy.'),
  ('6ab25bb08ff118bc1e73fe84', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 6, 'Koa nanampatra ny hatezerako sy ny fahavinirako aho, ka nandoro an’ireo tanànan’i Joda sy ny lalan’i Jerosalema izany. Dia rava tanteraka sy ngazana ireo, araka ny hita amin’izao.’', 'koa nanampatra ny hatezerako sy ny fahavinirako aho, ka nandoro an’ireo tanànan’i joda sy ny lalan’i jerosalema izany. dia rava tanteraka sy ngazana ireo, araka ny hita amin’izao.’'),
  ('6ab25bb08ff118bc1e73fe97', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 25, 'Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Notanterahinareo sy ny vadinareo izay nolazainareo. Niteny mantsy ianareo hoe: “Tsy maintsy hefainay ny voady nataonay, dia ny hanao sorona ho an’ny Mpanjakavavin’ny Lanitra sy ny handraraka fanatitra zava-pisotro ho azy.” Hanefa ny voadinareo tokoa ianareo vehivavy, ary hanatanteraka ny voadinareo.’', 'izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘notanterahinareo sy ny vadinareo izay nolazainareo. niteny mantsy ianareo hoe: “tsy maintsy hefainay ny voady nataonay, dia ny hanao sorona ho an’ny mpanjakavavin’ny lanitra sy ny handraraka fanatitra zava-pisotro ho azy.” hanefa ny voadinareo tokoa ianareo vehivavy, ary hanatanteraka ny voadinareo.’'),
  ('6ab25bb08ff118bc1e73fe94', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 22, 'Koa tsy zakan’i Jehovah intsony tamin’ny farany ireo zavatra ratsy sy maharikoriko fanaonareo. Dia rava ny taninareo sady tsy misy mponina intsony, ka nahatonga ny olona hihorohoro sy hampiasa ny anarany rehefa manozona, toy ny amin’izao andro izao.', 'koa tsy zakan’i jehovah intsony tamin’ny farany ireo zavatra ratsy sy maharikoriko fanaonareo. dia rava ny taninareo sady tsy misy mponina intsony, ka nahatonga ny olona hihorohoro sy hampiasa ny anarany rehefa manozona, toy ny amin’izao andro izao.'),
  ('6ab25bb08ff118bc1e73fe8d', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 15, 'Namaly an’i Jeremia ny lehilahy rehetra izay nahalala fa nanao sorona ho an’ny andriamani-kafa ny vadiny, sy ny vehivavy rehetra nitsangana teo, izay tena be dia be, ary ny vahoaka manontolo nipetraka tatỳ Ejipta, tao Patrosa. Hoy izy ireo taminy:', 'namaly an’i jeremia ny lehilahy rehetra izay nahalala fa nanao sorona ho an’ny andriamani-kafa ny vadiny, sy ny vehivavy rehetra nitsangana teo, izay tena be dia be, ary ny vahoaka manontolo nipetraka tatỳ ejipta, tao patrosa. hoy izy ireo taminy:'),
  ('6ab25bb08ff118bc1e73fe8a', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 12, 'Ary halaiko ireo sisa amin’ny Joda, dia ireo tapa-kevitra ny ho atỳ Ejipta mba hipetraka atỳ, ka ho ripaka atỳ Ejipta izy rehetra. Ho fatin’ny sabatra sy ho ripaky ny mosary izy ireo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra. Ho fatin’ny sabatra sy ny mosary tokoa izy ireo. Dia hanozona azy ireo ny olona ary hihorohoro mahita an’izay hanjo azy. Hanala baraka sy handatsa azy ireo koa izy ireny.', 'ary halaiko ireo sisa amin’ny joda, dia ireo tapa-kevitra ny ho atỳ ejipta mba hipetraka atỳ, ka ho ripaka atỳ ejipta izy rehetra. ho fatin’ny sabatra sy ho ripaky ny mosary izy ireo, hatramin’ny kely indrindra ka hatramin’ny lehibe indrindra. ho fatin’ny sabatra sy ny mosary tokoa izy ireo. dia hanozona azy ireo ny olona ary hihorohoro mahita an’izay hanjo azy. hanala baraka sy handatsa azy ireo koa izy ireny.'),
  ('6ab25bb08ff118bc1e73fe88', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 10, 'Mbola tsy manetry tena ihany izy ireo hatramin’izao na matahotra. Mbola tsy arahin’izy ireo koa ny lalàna sy fitsipika nomeko anareo sy ny razambenareo.’', 'mbola tsy manetry tena ihany izy ireo hatramin’izao na matahotra. mbola tsy arahin’izy ireo koa ny lalàna sy fitsipika nomeko anareo sy ny razambenareo.’'),
  ('6ab25bb08ff118bc1e73fe85', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 7, '“Ary izao no lazain’i Jehovah Andriamanitry ny tafika, Andriamanitry ny Israely: ‘Nahoana ianareo no mitady loza, ka ho ringana daholo ny lehilahy sy ny vehivavy ary ny ankizy sy ny zaza ao Joda, dia tsy hisy hiangana ianareo?', '“ary izao no lazain’i jehovah andriamanitry ny tafika, andriamanitry ny israely: ‘nahoana ianareo no mitady loza, ka ho ringana daholo ny lehilahy sy ny vehivavy ary ny ankizy sy ny zaza ao joda, dia tsy hisy hiangana ianareo?'),
  ('6ab25bb08ff118bc1e73fe9c', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 30, 'Izao no lazain’i Jehovah: “Hatolotro eo an-tanan’ny fahavalony sy ireo mitady hamono azy i Farao Hofra, mpanjakan’i Ejipta, tahaka ny nanolorako an’i Zedekia mpanjakan’ny Joda teo an-tanan’i Nebokadnezara mpanjakan’i Babylona, izay fahavalony sady nitady hamono azy.”’”', 'izao no lazain’i jehovah: “hatolotro eo an-tanan’ny fahavalony sy ireo mitady hamono azy i farao hofra, mpanjakan’i ejipta, tahaka ny nanolorako an’i zedekia mpanjakan’ny joda teo an-tanan’i nebokadnezara mpanjakan’i babylona, izay fahavalony sady nitady hamono azy.”’”'),
  ('6ab25bb08ff118bc1e73fe9a', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 28, 'Vitsy kely sisa no tsy ho ripaky ny sabatra sy ho tafaverina any Joda. Dia ho fantatry ny sisa rehetra amin’ny Joda, izay tonga nipetraka atỳ Ejipta, hoe ny tenin’iza no marina: Ny teniko sa ny tenin-dry zareo!”’”', 'vitsy kely sisa no tsy ho ripaky ny sabatra sy ho tafaverina any joda. dia ho fantatry ny sisa rehetra amin’ny joda, izay tonga nipetraka atỳ ejipta, hoe ny tenin’iza no marina: ny teniko sa ny tenin-dry zareo!”’”'),
  ('6ab25bb08ff118bc1e73fe81', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 3, 'Nanao zava-dratsy mantsy izy ireo mba hampahatezitra ahy. Nandeha nanao sorona izy ireo ary nanompo andriamani-kafa tsy fantany, sady tsy fantatrareo no tsy fantatry ny razambenareo.', 'nanao zava-dratsy mantsy izy ireo mba hampahatezitra ahy. nandeha nanao sorona izy ireo ary nanompo andriamani-kafa tsy fantany, sady tsy fantatrareo no tsy fantatry ny razambenareo.'),
  ('6ab25bb08ff118bc1e73fe90', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 18, 'Fa hatramin’ny tsy nanaovanay sorona ho an’ny Mpanjakavavin’ny Lanitra sy tsy nandrarahanay fanatitra zava-pisotro ho azy intsony, dia tsy manana na inona na inona izahay sady ripaky ny sabatra sy ny mosary.”', 'fa hatramin’ny tsy nanaovanay sorona ho an’ny mpanjakavavin’ny lanitra sy tsy nandrarahanay fanatitra zava-pisotro ho azy intsony, dia tsy manana na inona na inona izahay sady ripaky ny sabatra sy ny mosary.”'),
  ('6ab25bb08ff118bc1e73fe87', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 9, 'Hadinonareo angaha ny ratsy nataon’ny razambenareo sy nataon’ireo mpanjakan’ny Joda sy ny vadiny, ary ny ratsy nataonareo sy ny vadinareo, tao Joda sy teny amin’ny lalan’i Jerosalema?', 'hadinonareo angaha ny ratsy nataon’ny razambenareo sy nataon’ireo mpanjakan’ny joda sy ny vadiny, ary ny ratsy nataonareo sy ny vadinareo, tao joda sy teny amin’ny lalan’i jerosalema?'),
  ('6ab25bb08ff118bc1e73fe86', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 8, 'Fa maninona ianareo no mampahatezitra ahy amin’ny zavatra ataonareo, ka manao sorona ho an’ireo andriamani-kafa atỳ Ejipta, izay toerana nalehanareo mba honenana? Ho ringana ianareo, ary ny anaranareo no hampiasain’ny firenena rehetra eny ambonin’ny tany rehefa manozona izy ireo.', 'fa maninona ianareo no mampahatezitra ahy amin’ny zavatra ataonareo, ka manao sorona ho an’ireo andriamani-kafa atỳ ejipta, izay toerana nalehanareo mba honenana? ho ringana ianareo, ary ny anaranareo no hampiasain’ny firenena rehetra eny ambonin’ny tany rehefa manozona izy ireo.'),
  ('6ab25bb08ff118bc1e73fe99', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 27, 'Manara-maso azy ireo aho mba hahatonga loza aminy fa tsy soa. Ho ripaky ny sabatra sy ny mosary ny olona rehetra avy any Joda atỳ Ejipta, mandra-pahafongany.', 'manara-maso azy ireo aho mba hahatonga loza aminy fa tsy soa. ho ripaky ny sabatra sy ny mosary ny olona rehetra avy any joda atỳ ejipta, mandra-pahafongany.'),
  ('6ab25bb08ff118bc1e73fe92', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 20, 'Dia hoy i Jeremia tamin’ny vahoaka manontolo, izany hoe ireo lehilahy sy ny vadiny avy ary ny olona rehetra niresaka taminy:', 'dia hoy i jeremia tamin’ny vahoaka manontolo, izany hoe ireo lehilahy sy ny vadiny avy ary ny olona rehetra niresaka taminy:'),
  ('6ab25bb08ff118bc1e73fe8f', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 17, 'Izay teny rehetra efa nolazainay ihany no hotanterahinay: Hanao sorona ho an’ny Mpanjakavavin’ny Lanitra izahay, ary handraraka fanatitra zava-pisotro ho azy, hoatran’ny efa nataonay sy nataon’ny razambenay, sy ny mpanjakanay, ary ny andriananay tao amin’ireo tanànan’i Joda sy teny amin’ny lalan’i Jerosalema. Voky hanina sy niadana izahay tamin’izany, ary tsy nisy loza nanjo anay mihitsy.', 'izay teny rehetra efa nolazainay ihany no hotanterahinay: hanao sorona ho an’ny mpanjakavavin’ny lanitra izahay, ary handraraka fanatitra zava-pisotro ho azy, hoatran’ny efa nataonay sy nataon’ny razambenay, sy ny mpanjakanay, ary ny andriananay tao amin’ireo tanànan’i joda sy teny amin’ny lalan’i jerosalema. voky hanina sy niadana izahay tamin’izany, ary tsy nisy loza nanjo anay mihitsy.'),
  ('6ab25bb08ff118bc1e73fe83', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 5, 'Tsy nihaino anefa izy ireo na nanongilan-tsofina ka tsy niala tamin’ny ratsy fanaony, fa mbola nanao sorona ho an’ny andriamani-kafa ihany.', 'tsy nihaino anefa izy ireo na nanongilan-tsofina ka tsy niala tamin’ny ratsy fanaony, fa mbola nanao sorona ho an’ny andriamani-kafa ihany.'),
  ('6ab25bb08ff118bc1e73fe8e', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 16, '“Tsy hihaino ny teny nolazainao taminay izahay, na dia nolazainao tamin’ny anaran’i Jehovah aza izany.', '“tsy hihaino ny teny nolazainao taminay izahay, na dia nolazainao tamin’ny anaran’i jehovah aza izany.'),
  ('6ab25bb08ff118bc1e73fe8c', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 14, 'Dia tsy hisy ho afa-mandositra na hisy hiangana ny sisa amin’ny Joda, izay nandeha nipetraka atỳ Ejipta. Te hiverina mafy hipetraka any Joda izy ireo, nefa tsy ho tafaverina any, afa-tsy olona vitsy.’”', 'dia tsy hisy ho afa-mandositra na hisy hiangana ny sisa amin’ny joda, izay nandeha nipetraka atỳ ejipta. te hiverina mafy hipetraka any joda izy ireo, nefa tsy ho tafaverina any, afa-tsy olona vitsy.’”'),
  ('6ab25bb08ff118bc1e73fe7f', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 1, 'Izao no hafatra nampitaina tamin’i Jeremia, ho an’ny Jiosy rehetra nipetraka tatỳ Ejipta, dia ireo nipetraka tao Migdola, Tapanesa, Nofa, ary Patrosa:', 'izao no hafatra nampitaina tamin’i jeremia, ho an’ny jiosy rehetra nipetraka tatỳ ejipta, dia ireo nipetraka tao migdola, tapanesa, nofa, ary patrosa:'),
  ('6ab25bb08ff118bc1e73fe82', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 4, 'Nirahiko tany aminareo foana ny mpaminany mpanompoko rehetra. Imbetsaka aho no naniraka azy ireny tany aminareo mba hiteny hoe: “Aza dia manao an’izao zava-maharikoriko halako izao re ianareo e!”', 'nirahiko tany aminareo foana ny mpaminany mpanompoko rehetra. imbetsaka aho no naniraka azy ireny tany aminareo mba hiteny hoe: “aza dia manao an’izao zava-maharikoriko halako izao re ianareo e!”'),
  ('6ab25bb08ff118bc1e73fe96', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 24, 'Hoy ihany i Jeremia tamin’ny vahoaka manontolo sy ny vehivavy rehetra: “Henoy ny tenin’i Jehovah, ry Joda rehetra atỳ Ejipta!', 'hoy ihany i jeremia tamin’ny vahoaka manontolo sy ny vehivavy rehetra: “henoy ny tenin’i jehovah, ry joda rehetra atỳ ejipta!'),
  ('6ab25bb08ff118bc1e73fe9b', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 29, '“‘Homeko famantarana ianareo’, hoy i Jehovah, ‘mba hahalalanareo fa hosaziko eto amin’ity toerana ity ianareo. Ho fantatrareo amin’izay fa tsy maintsy ho tanteraka ny teniko hoe hahita loza ianareo.', '“‘homeko famantarana ianareo’, hoy i jehovah, ‘mba hahalalanareo fa hosaziko eto amin’ity toerana ity ianareo. ho fantatrareo amin’izay fa tsy maintsy ho tanteraka ny teniko hoe hahita loza ianareo.'),
  ('6ab25bb08ff118bc1e73fe89', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 11, '“Koa izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Tapa-kevitra ny hahatonga loza aminareo aho, mba handringanana ny Joda rehetra.', '“koa izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘tapa-kevitra ny hahatonga loza aminareo aho, mba handringanana ny joda rehetra.'),
  ('6ab25bb08ff118bc1e73fe93', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 21, '“Tsaroan’i Jehovah sady tsy afaka ao an-tsainy ny sorona nataonareo sy nataon’ny razambenareo, sy ny mpanjakanareo, sy ny andriananareo, ary ny vahoaka tao amin’ireo tanànan’i Joda sy teny amin’ny lalan’i Jerosalema!', '“tsaroan’i jehovah sady tsy afaka ao an-tsainy ny sorona nataonareo sy nataon’ny razambenareo, sy ny mpanjakanareo, sy ny andriananareo, ary ny vahoaka tao amin’ireo tanànan’i joda sy teny amin’ny lalan’i jerosalema!'),
  ('6ab25bb08ff118bc1e73fe91', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 19, 'Hoy koa ireo vehivavy: “Angaha moa izahay tsy efa nangataka alalana tamin’ny vadinay, rehefa nanao sorona ho an’ny Mpanjakavavin’ny Lanitra, sy nandraraka fanatitra zava-pisotro ho azy? Nangataka alalana izahay vao nanao mofo mitovy bika amin’ilay andriamanibavy mba hatao fanatitra, sy nandraraka fanatitra zava-pisotro ho azy.”', 'hoy koa ireo vehivavy: “angaha moa izahay tsy efa nangataka alalana tamin’ny vadinay, rehefa nanao sorona ho an’ny mpanjakavavin’ny lanitra, sy nandraraka fanatitra zava-pisotro ho azy? nangataka alalana izahay vao nanao mofo mitovy bika amin’ilay andriamanibavy mba hatao fanatitra, sy nandraraka fanatitra zava-pisotro ho azy.”'),
  ('6ab25bb08ff118bc1e73fe8b', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 13, 'Hosaziko ireo mipetraka atỳ Ejipta, toy ny nanasaziako an’i Jerosalema ka namelezako azy tamin’ny sabatra sy ny mosary ary ny areti-mandringana.', 'hosaziko ireo mipetraka atỳ ejipta, toy ny nanasaziako an’i jerosalema ka namelezako azy tamin’ny sabatra sy ny mosary ary ny areti-mandringana.'),
  ('6ab25bb08ff118bc1e73fe95', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 23, 'Tonga aminareo izao loza izao ankehitriny, satria nanao an’ireny sorona ireny ianareo ary nanota tamin’i Jehovah. Tsy nankatò ny tenin’i Jehovah ianareo, sady tsy nanaraka ny lalàny sy ny fitsipiny ary ny fampahatsiahivany.”', 'tonga aminareo izao loza izao ankehitriny, satria nanao an’ireny sorona ireny ianareo ary nanota tamin’i jehovah. tsy nankatò ny tenin’i jehovah ianareo, sady tsy nanaraka ny lalàny sy ny fitsipiny ary ny fampahatsiahivany.”'),
  ('6ab25bb08ff118bc1e73fe98', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 26, '“Koa henoy ny tenin’i Jehovah, ry Joda rehetra mipetraka atỳ Ejipta: ‘“Mianiana amin’ny anarako be voninahitra aho”, hoy i Jehovah, “fa tsy hisy olona avy any Joda hianiana amin’ny anarako intsony eran’i Ejipta, ka hilaza hoe: ‘Raha mbola velona koa i Jehovah Tompo Fara Tampony!’', '“koa henoy ny tenin’i jehovah, ry joda rehetra mipetraka atỳ ejipta: ‘“mianiana amin’ny anarako be voninahitra aho”, hoy i jehovah, “fa tsy hisy olona avy any joda hianiana amin’ny anarako intsony eran’i ejipta, ka hilaza hoe: ‘raha mbola velona koa i jehovah tompo fara tampony!’'),
  ('6ab25bb08ff118bc1e73fe80', '2026-09-22T10:42:56.602Z', '2026-09-22T10:42:56.602Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 44, 2, '“Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Efa hitanareo ny loza rehetra nataoko tamin’i Jerosalema sy ny tanàna rehetra any Joda. Rava tanteraka izy ireo ankehitriny, sady tsy misy mponina.', '“izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘efa hitanareo ny loza rehetra nataoko tamin’i jerosalema sy ny tanàna rehetra any joda. rava tanteraka izy ireo ankehitriny, sady tsy misy mponina.'),
  ('6ab25bb2448d4ef28d65ea8a', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 19, 'Omano ny entana hoentinao any an-tsesitany, Ry zanakavavy mipetraka eto Ejipta ô! Fa hihorohoro ny olona rehefa mahita an’izay hanjo an’i Nofa. Hodorana izy ka tsy hisy mponina.', 'omano ny entana hoentinao any an-tsesitany, ry zanakavavy mipetraka eto ejipta ô! fa hihorohoro ny olona rehefa mahita an’izay hanjo an’i nofa. hodorana izy ka tsy hisy mponina.'),
  ('6ab25bb2448d4ef28d65ea82', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 11, 'Miakara any Gileada mba haka balsama, Ry Ejipta zanakavavy virjiny ô! Very maina ny nampiasanao karazana fanafody be dia be, Fa tsy ho sitrana mihitsy ianao.', 'miakara any gileada mba haka balsama, ry ejipta zanakavavy virjiny ô! very maina ny nampiasanao karazana fanafody be dia be, fa tsy ho sitrana mihitsy ianao.'),
  ('6ab25bb2448d4ef28d65ea81', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 10, '“An’ilay Tompo Fara Tampony, dia i Jehovah Tompon’ny tafika, izany andro izany, ho andro famaliana mba hamaliany an’ireo fahavalony. Hihinana sy ho voky ary hisotro ny ran’izy ireo ny sabatra, ka ho afa-ketaheta. Fa misy sorona ataon’i Jehovah Tompon’ny tafika sady Tompo Fara Tampony ao amin’ilay tany any avaratra, eo akaikin’ny Reniranon’i Eofrata.', '“an’ilay tompo fara tampony, dia i jehovah tompon’ny tafika, izany andro izany, ho andro famaliana mba hamaliany an’ireo fahavalony. hihinana sy ho voky ary hisotro ny ran’izy ireo ny sabatra, ka ho afa-ketaheta. fa misy sorona ataon’i jehovah tompon’ny tafika sady tompo fara tampony ao amin’ilay tany any avaratra, eo akaikin’ny reniranon’i eofrata.'),
  ('6ab25bb2448d4ef28d65ea87', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 16, 'Be dia be no tafintohina ka mianjera. Mifampiresaka izy ireo hoe: “Mitsangàna! Andao hiverina any amin’ny firenentsika sy any amin’ny tanindrazantsika, Fa mamono olona be dia be ny sabatra.”’', 'be dia be no tafintohina ka mianjera. mifampiresaka izy ireo hoe: “mitsangàna! andao hiverina any amin’ny firenentsika sy any amin’ny tanindrazantsika, fa mamono olona be dia be ny sabatra.”’'),
  ('6ab25bb2448d4ef28d65ea8e', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 23, 'Dia hokapain’izy ireo ny alan’i Ejipta’, hoy i Jehovah, ‘na dia hoatran’ny hoe sarotra hitsofohana aza. Fa be lavitra noho ny valala izy ireo ka tsy hita isa.', 'dia hokapain’izy ireo ny alan’i ejipta’, hoy i jehovah, ‘na dia hoatran’ny hoe sarotra hitsofohana aza. fa be lavitra noho ny valala izy ireo ka tsy hita isa.'),
  ('6ab25bb2448d4ef28d65ea80', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 9, 'Miakara, ry soavaly! Aoka ianareo hiriotra mafy toy ny adala, ry kalesy! Aoka handroso ny miaramila, Dia i Kosy sy Pota, izay mitana ampinga, Ary ny Lodima, izay mitana sy manomana tsipìka.', 'miakara, ry soavaly! aoka ianareo hiriotra mafy toy ny adala, ry kalesy! aoka handroso ny miaramila, dia i kosy sy pota, izay mitana ampinga, ary ny lodima, izay mitana sy manomana tsipìka.'),
  ('6ab25bb2448d4ef28d65ea90', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 25, '“Izao no lazain’i Jehovah Tompon’ny tafika, Andriamanitry ny Israely: ‘Hosaziko i Amona ao No, sy Farao, sy Ejipta, sy ny andriamaniny, ary ny mpanjakany, izany hoe i Farao sy izay rehetra matoky azy.’', '“izao no lazain’i jehovah tompon’ny tafika, andriamanitry ny israely: ‘hosaziko i amona ao no, sy farao, sy ejipta, sy ny andriamaniny, ary ny mpanjakany, izany hoe i farao sy izay rehetra matoky azy.’'),
  ('6ab25bb2448d4ef28d65ea8c', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 21, 'Na ny mpikarama an’adiny aza toy ny zanak’omby mifahy, Nefa miverina koa izy ireo ary mandositra daholo. Tsy nahatohitra izy ireo, Fa tonga ny andro hahitany loza, Dia ny fotoana hanasaziana azy.’', 'na ny mpikarama an’adiny aza toy ny zanak’omby mifahy, nefa miverina koa izy ireo ary mandositra daholo. tsy nahatohitra izy ireo, fa tonga ny andro hahitany loza, dia ny fotoana hanasaziana azy.’'),
  ('6ab25bb2448d4ef28d65ea7d', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 6, '‘Tsy afaka mandositra ny haingam-pandeha, ary tsy afaka mitsoaka ny miaramila. Any avaratra, eo amoron’ny Reniranon’i Eofrata, No tafintohina sy lavo izy ireo.’', '‘tsy afaka mandositra ny haingam-pandeha, ary tsy afaka mitsoaka ny miaramila. any avaratra, eo amoron’ny reniranon’i eofrata, no tafintohina sy lavo izy ireo.’'),
  ('6ab25bb2448d4ef28d65ea91', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 26, '“‘Ary hatolotro eo an-tanan’izay mitady hamono azy izy ireo, dia eo an-tanan’i Nebokadnezara mpanjakan’i Babylona sy ny mpanompony. Hisy mponina toy ny taloha anefa i Ejipta aorian’izay’, hoy i Jehovah.', '“‘ary hatolotro eo an-tanan’izay mitady hamono azy izy ireo, dia eo an-tanan’i nebokadnezara mpanjakan’i babylona sy ny mpanompony. hisy mponina toy ny taloha anefa i ejipta aorian’izay’, hoy i jehovah.'),
  ('6ab25bb2448d4ef28d65ea7a', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 3, '“Omano ny ampinga kelinareo sy ny ampinga lehibe, Ary mandehana miady.', '“omano ny ampinga kelinareo sy ny ampinga lehibe, ary mandehana miady.'),
  ('6ab25bb2448d4ef28d65ea78', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 1, 'Izao no tenin’i Jehovah tamin’i Jeremia mpaminany momba an’ireo firenena:', 'izao no tenin’i jehovah tamin’i jeremia mpaminany momba an’ireo firenena:'),
  ('6ab25bb2448d4ef28d65ea8f', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 24, 'Ho menatra i Ejipta zanakavavy. Hataoko resin’ilay vahoaka any avaratra izy.’', 'ho menatra i ejipta zanakavavy. hataoko resin’ilay vahoaka any avaratra izy.’'),
  ('6ab25bb2448d4ef28d65ea85', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 14, '“Lazao atỳ Ejipta izany, ary ambarao ao Migdola. Ambarao ao Nofa sy Tapanesa izany. Teneno hoe: ‘Makà toerana dia miomàna, Fa hisy sabatra handripaka an’ireo manodidina anao.', '“lazao atỳ ejipta izany, ary ambarao ao migdola. ambarao ao nofa sy tapanesa izany. teneno hoe: ‘makà toerana dia miomàna, fa hisy sabatra handripaka an’ireo manodidina anao.'),
  ('6ab25bb2448d4ef28d65ea83', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 12, 'Efa ren’ireo firenena ny fahafaham-barakanao, Ary manenika an’ilay tany ny fitarainanao. Fa mifamingana ireo miaramila, Ka miara-mianjera.”', 'efa ren’ireo firenena ny fahafaham-barakanao, ary manenika an’ilay tany ny fitarainanao. fa mifamingana ireo miaramila, ka miara-mianjera.”'),
  ('6ab25bb2448d4ef28d65ea7f', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 8, 'Miakatra toy ny Reniranon’i Neily i Ejipta, Toy ny renirano tondraka be. Hoy izy: ‘Hiakatra aho ka hanafotra ny tany. Horavako ny tanàna ary haringako ny mponina ao.’', 'miakatra toy ny reniranon’i neily i ejipta, toy ny renirano tondraka be. hoy izy: ‘hiakatra aho ka hanafotra ny tany. horavako ny tanàna ary haringako ny mponina ao.’'),
  ('6ab25bb2448d4ef28d65ea79', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 2, 'Momba an’i Ejipta. Izao no voalaza momba ny tafik’i Farao Neko mpanjakan’i Ejipta izay resin’i Nebokadnezara mpanjakan’i Babylona tany Karkemisy, teo akaikin’ny Reniranon’i Eofrata, tamin’ny taona fahefatra nanjakan’i Joiakima zanak’i Josia, mpanjakan’ny Joda:', 'momba an’i ejipta. izao no voalaza momba ny tafik’i farao neko mpanjakan’i ejipta izay resin’i nebokadnezara mpanjakan’i babylona tany karkemisy, teo akaikin’ny reniranon’i eofrata, tamin’ny taona fahefatra nanjakan’i joiakima zanak’i josia, mpanjakan’ny joda:'),
  ('6ab25bb2448d4ef28d65ea92', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 27, '‘Fa aza matahotra kosa ianao, ry Jakoba mpanompoko, Ary aza mihorohoro, ry Israely ô! Fa hovonjeko avy any an-tany lavitra ianao, Ary ny taranakao hovonjeko avy any amin’ny tany nahababo azy. Dia hiverina i Jakoba, ka hilamina sy tsy hisy hanakorontana. Tsy hisy hampatahotra azy ireo.', '‘fa aza matahotra kosa ianao, ry jakoba mpanompoko, ary aza mihorohoro, ry israely ô! fa hovonjeko avy any an-tany lavitra ianao, ary ny taranakao hovonjeko avy any amin’ny tany nahababo azy. dia hiverina i jakoba, ka hilamina sy tsy hisy hanakorontana. tsy hisy hampatahotra azy ireo.'),
  ('6ab25bb2448d4ef28d65ea89', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 18, '‘Raha mbola velona koa aho’, hoy ilay Mpanjaka, izay manana anarana hoe Jehovah Tompon’ny tafika, ‘Dia hiditra atỳ izy, ka ho toa an’i Tabara, izay miavaka amin’ireo tendrombohitra Sy ho toa an’i Karmela eo amoron’ny ranomasina.', '‘raha mbola velona koa aho’, hoy ilay mpanjaka, izay manana anarana hoe jehovah tompon’ny tafika, ‘dia hiditra atỳ izy, ka ho toa an’i tabara, izay miavaka amin’ireo tendrombohitra sy ho toa an’i karmela eo amoron’ny ranomasina.'),
  ('6ab25bb2448d4ef28d65ea7e', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 7, 'Iza iny miakatra toy ny Reniranon’i Neily iny, Hoatran’ny renirano tondraka be?', 'iza iny miakatra toy ny reniranon’i neily iny, hoatran’ny renirano tondraka be?'),
  ('6ab25bb2448d4ef28d65ea7c', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 5, '‘Maninona izy ireo no hitako mihorohoro hoatr’izao? Mitsoaka izy ireo fa resy ny miaramilany. Mikoropaka mandositra izy ireo ka tsy miherika akory ny miaramilany. Manjaka hatraiza hatraiza ny horohoro’, hoy i Jehovah.', '‘maninona izy ireo no hitako mihorohoro hoatr’izao? mitsoaka izy ireo fa resy ny miaramilany. mikoropaka mandositra izy ireo ka tsy miherika akory ny miaramilany. manjaka hatraiza hatraiza ny horohoro’, hoy i jehovah.'),
  ('6ab25bb2448d4ef28d65ea7b', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 4, 'Asio lasely ny soavaly ka itaingeno, ry mpitaingin-tsoavaly! Makà toerana, ary anaovy ny fiarovan-dohanareo. Ataovy mangirana ny lefona, ary anaovy ny akanjonareo mifono vy.', 'asio lasely ny soavaly ka itaingeno, ry mpitaingin-tsoavaly! makà toerana, ary anaovy ny fiarovan-dohanareo. ataovy mangirana ny lefona, ary anaovy ny akanjonareo mifono vy.'),
  ('6ab25bb2448d4ef28d65ea8d', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 22, '‘Toy ny feona bibilava mikisakisaka ny feony, Satria manenjika mafy azy izy ireo, ary mitondra famaky Hoatran’ny lehilahy mikapa hazo.', '‘toy ny feona bibilava mikisakisaka ny feony, satria manenjika mafy azy izy ireo, ary mitondra famaky hoatran’ny lehilahy mikapa hazo.'),
  ('6ab25bb2448d4ef28d65ea8b', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 20, 'Toy ny ombivavy kely tsara tarehy i Ejipta, Nefa hisy fihitra avy any avaratra ho avy hanaikitra azy.', 'toy ny ombivavy kely tsara tarehy i ejipta, nefa hisy fihitra avy any avaratra ho avy hanaikitra azy.'),
  ('6ab25bb2448d4ef28d65ea84', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 13, 'Izao no tenin’i Jehovah tamin’i Jeremia mpaminany momba ny hahatongavan’i Nebokadnezara mpanjakan’i Babylona mba hanafika an’i Ejipta:', 'izao no tenin’i jehovah tamin’i jeremia mpaminany momba ny hahatongavan’i nebokadnezara mpanjakan’i babylona mba hanafika an’i ejipta:'),
  ('6ab25bb2448d4ef28d65ea93', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 28, 'Koa aza matahotra, ry Jakoba mpanompoko’, hoy i Jehovah, ‘fa ho eo foana aho. Haripako ny firenena rehetra nanaparitahako anao, Fa ianao tsy mba haripako. Hanariko araka ny antonony ianao, Ary tsy havelako ho afa-maina fotsiny fa hosaziko.’”', 'koa aza matahotra, ry jakoba mpanompoko’, hoy i jehovah, ‘fa ho eo foana aho. haripako ny firenena rehetra nanaparitahako anao, fa ianao tsy mba haripako. hanariko araka ny antonony ianao, ary tsy havelako ho afa-maina fotsiny fa hosaziko.’”'),
  ('6ab25bb2448d4ef28d65ea88', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 17, 'Any izy ireo no milaza hoe: ‘Resa-be fotsiny ny an’i Farao mpanjakan’i Ejipta! Tsy nahay nanararaotra fotoana izy.’', 'any izy ireo no milaza hoe: ‘resa-be fotsiny ny an’i farao mpanjakan’i ejipta! tsy nahay nanararaotra fotoana izy.’'),
  ('6ab25bb2448d4ef28d65ea86', '2026-09-22T10:42:58.519Z', '2026-09-22T10:42:58.519Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 46, 15, 'Nahoana ireo lehilahy mahery teo aminao no lasan’ny rano? Tsy nahatohitra izy ireo, Satria natosik’i Jehovah.', 'nahoana ireo lehilahy mahery teo aminao no lasan’ny rano? tsy nahatohitra izy ireo, satria natosik’i jehovah.'),
  ('6ab25bb3026086111093c5d3', '2026-09-22T10:42:59.118Z', '2026-09-22T10:42:59.118Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 47, 5, 'Ho sola i Gaza, Ary hangina i Askelona. Ry sisa tavela eny amin’ny tany lemaka ô, Mandra-pahoviana ianao no handidididy ny vatanao?', 'ho sola i gaza, ary hangina i askelona. ry sisa tavela eny amin’ny tany lemaka ô, mandra-pahoviana ianao no handidididy ny vatanao?'),
  ('6ab25bb3026086111093c5d0', '2026-09-22T10:42:59.118Z', '2026-09-22T10:42:59.118Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 47, 2, 'Izao no tenin’i Jehovah: “Misy rano avy any avaratra. Ho lasa riaka be izany, Ka hanafotra an’ilay tany sy izay rehetra eo aminy, Izany hoe ny tanàna sy ny mponina ao. Hitaraina ny lehilahy, Ary hidradradradra ny mponina rehetra ao amin’ilay tany.', 'izao no tenin’i jehovah: “misy rano avy any avaratra. ho lasa riaka be izany, ka hanafotra an’ilay tany sy izay rehetra eo aminy, izany hoe ny tanàna sy ny mponina ao. hitaraina ny lehilahy, ary hidradradradra ny mponina rehetra ao amin’ilay tany.'),
  ('6ab25bb3026086111093c5d5', '2026-09-22T10:42:59.118Z', '2026-09-22T10:42:59.118Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 47, 7, 'Ataony ahoana moa ny hangina, Nefa i Jehovah no nanome baiko azy? Any Askelona sy eny amin’ny morontsiraka izy No notendreny hanafika.', 'ataony ahoana moa ny hangina, nefa i jehovah no nanome baiko azy? any askelona sy eny amin’ny morontsiraka izy no notendreny hanafika.'),
  ('6ab25bb3026086111093c5d2', '2026-09-22T10:42:59.118Z', '2026-09-22T10:42:59.118Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 47, 4, 'Fa tonga ilay andro handringanana ny Filistinina rehetra. Hesorina tsy ho ao Tyro sy Sidona ny sisa tavela amin’ireo nifanaraka taminy. Haringan’i Jehovah mantsy ny Filistinina, Dia izay sisa tavela avy any amin’ny nosy Kaftora.', 'fa tonga ilay andro handringanana ny filistinina rehetra. hesorina tsy ho ao tyro sy sidona ny sisa tavela amin’ireo nifanaraka taminy. haringan’i jehovah mantsy ny filistinina, dia izay sisa tavela avy any amin’ny nosy kaftora.'),
  ('6ab25bb3026086111093c5cf', '2026-09-22T10:42:59.118Z', '2026-09-22T10:42:59.118Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 47, 1, 'Nampita hafatra tamin’i Jeremia mpaminany momba ny Filistinina i Jehovah, talohan’ny nandresen’i Farao an’i Gaza.', 'nampita hafatra tamin’i jeremia mpaminany momba ny filistinina i jehovah, talohan’ny nandresen’i farao an’i gaza.'),
  ('6ab25bb3026086111093c5d1', '2026-09-22T10:42:59.118Z', '2026-09-22T10:42:59.118Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 47, 3, 'Noho ny fikatrokatroky ny kitron-tsoavaly, Sy ny firodorodon’ny kalesy fitondra miady, Ary ny fitabataban’ny kodiarany, Dia tsy hiverina hamonjy ny zanany na dia ny raim-pianakaviana aza, Satria malemy tsy mahavita na inona na inona intsony ny tanany.', 'noho ny fikatrokatroky ny kitron-tsoavaly, sy ny firodorodon’ny kalesy fitondra miady, ary ny fitabataban’ny kodiarany, dia tsy hiverina hamonjy ny zanany na dia ny raim-pianakaviana aza, satria malemy tsy mahavita na inona na inona intsony ny tanany.'),
  ('6ab25bb3026086111093c5d4', '2026-09-22T10:42:59.118Z', '2026-09-22T10:42:59.118Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 47, 6, '“Ô ry sabatr’i Jehovah ô! Rahoviana ianao vao hangina? Miverena ao anaty tranonao. Mialà sasatra, dia mangìna.', '“ô ry sabatr’i jehovah ô! rahoviana ianao vao hangina? miverena ao anaty tranonao. mialà sasatra, dia mangìna.'),
  ('6ab25bb4274d1d72758d1936', '2026-09-22T10:43:00.030Z', '2026-09-22T10:43:00.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 2, '“‘Koa henoy izao!’, hoy i Jehovah. ‘Ho avy ny andro Handefasako feo fanairana amin’ny ady, ka hataoko mandre an’izany i Raba tanànan’ny Amonita. Ho lasa dongon-tany ngazana izy, Ary hodorana ireo tanàna miankina aminy.’ ‘Dia halain’ny Israely ny tanin’ireo naka ny taniny’, hoy i Jehovah.', '“‘koa henoy izao!’, hoy i jehovah. ‘ho avy ny andro handefasako feo fanairana amin’ny ady, ka hataoko mandre an’izany i raba tanànan’ny amonita. ho lasa dongon-tany ngazana izy, ary hodorana ireo tanàna miankina aminy.’ ‘dia halain’ny israely ny tanin’ireo naka ny taniny’, hoy i jehovah.'),
  ('6ab25bb4274d1d72758d1938', '2026-09-22T10:43:00.030Z', '2026-09-22T10:43:00.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 4, 'Nahoana no mampirehareha anao ireo lohasaha, Dia ireo lemaka azon-drano ao aminao, ry zanakavavy mpivadika? Mitoky amin’ny harenanao ianao, Ka milaza hoe: “Iza no ho sahy hanafika ahy?”’”', 'nahoana no mampirehareha anao ireo lohasaha, dia ireo lemaka azon-drano ao aminao, ry zanakavavy mpivadika? mitoky amin’ny harenanao ianao, ka milaza hoe: “iza no ho sahy hanafika ahy?”’”'),
  ('6ab25bb4274d1d72758d1935', '2026-09-22T10:43:00.030Z', '2026-09-22T10:43:00.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 1, 'Izao no lazain’i Jehovah momba ny Amonita: “Tsy manan-janaka lahy angaha ny Israely? Tsy manana mpandova angaha izy? Koa nahoana no alain’i Malkama ny tanin’i Gada? Ary nahoana ny vahoakany no mipetraka ao amin’ireo tanànan’ny Israely?”', 'izao no lazain’i jehovah momba ny amonita: “tsy manan-janaka lahy angaha ny israely? tsy manana mpandova angaha izy? koa nahoana no alain’i malkama ny tanin’i gada? ary nahoana ny vahoakany no mipetraka ao amin’ireo tanànan’ny israely?”'),
  ('6ab25bb4274d1d72758d1937', '2026-09-22T10:43:00.030Z', '2026-09-22T10:43:00.030Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 3, '‘Midradradradrà, ry Hesbona ô, fa rava i Ay! Aoka ianareo hitaraina, ry tanàna miankina amin’i Raba. Misikìna lamba gony. Midradradradrà ary mandehana mivezivezy eny amin’ireo vala vita amin’ny vato, Fa hatao sesitany i Malkama Sy ny mpisorony ary ny andrianany.', '‘midradradradrà, ry hesbona ô, fa rava i ay! aoka ianareo hitaraina, ry tanàna miankina amin’i raba. misikìna lamba gony. midradradradrà ary mandehana mivezivezy eny amin’ireo vala vita amin’ny vato, fa hatao sesitany i malkama sy ny mpisorony ary ny andrianany.'),
  ('6ab25bb4274d1d72758d1958', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 36, 'Hataoko mifofofofo amin’i Elama ny rivotra efatra avy any amin’ny lafiny efatry ny lanitra. Dia haeliko any amin’ny toerana rehetra itsofan’ireo rivotra ireo izy, ka tsy hisy firenena tsy ho tongan’ireo Elamita naparitaka.’”', 'hataoko mifofofofo amin’i elama ny rivotra efatra avy any amin’ny lafiny efatry ny lanitra. dia haeliko any amin’ny toerana rehetra itsofan’ireo rivotra ireo izy, ka tsy hisy firenena tsy ho tongan’ireo elamita naparitaka.’”'),
  ('6ab25bb4274d1d72758d1956', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 34, 'Izao no tenin’i Jehovah tamin’i Jeremia mpaminany momba an’i Elama, rehefa nanomboka nanjaka i Zedekia mpanjakan’ny Joda:', 'izao no tenin’i jehovah tamin’i jeremia mpaminany momba an’i elama, rehefa nanomboka nanjaka i zedekia mpanjakan’ny joda:'),
  ('6ab25bb4274d1d72758d1954', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 32, 'Hisy hangalatra ny ramevany Ary hisy haka ny biby fiompiny maro be. Haeliko any amin’ny vazan-tany efatra izy ireo, Dia izay nokakasana ny fihirifany. Hahatonga loza aminy avy any amin’ny vazan-tany efatra aho”, hoy i Jehovah.', 'hisy hangalatra ny ramevany ary hisy haka ny biby fiompiny maro be. haeliko any amin’ny vazan-tany efatra izy ireo, dia izay nokakasana ny fihirifany. hahatonga loza aminy avy any amin’ny vazan-tany efatra aho”, hoy i jehovah.'),
  ('6ab25bb4274d1d72758d1953', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 31, '“Mitsangàna ka miakara hiady amin’ilay firenena tsy misy korontana, Izay miadana sy milamina!”, hoy i Jehovah. “Tsy misy varavarana na bara hidiny ny tanànany. Ary mitoka-monina izy.', '“mitsangàna ka miakara hiady amin’ilay firenena tsy misy korontana, izay miadana sy milamina!”, hoy i jehovah. “tsy misy varavarana na bara hidiny ny tanànany. ary mitoka-monina izy.'),
  ('6ab25bb4274d1d72758d193b', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 7, 'Izao no lazain’i Jehovah Tompon’ny tafika momba an’i Edoma: “Tsy misy fahendrena intsony angaha ao Temana? Tsy manana torohevitra tsara intsony angaha ireo mahira-tsaina? Tsy misy ilana azy intsony angaha ny fahendreny?', 'izao no lazain’i jehovah tompon’ny tafika momba an’i edoma: “tsy misy fahendrena intsony angaha ao temana? tsy manana torohevitra tsara intsony angaha ireo mahira-tsaina? tsy misy ilana azy intsony angaha ny fahendreny?'),
  ('6ab25bb4274d1d72758d1955', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 33, '“Dia ho lasa toerana ipetrahan’ny alikadia i Hazora, Ary ho aolo mandrakizay. Tsy hisy hipetraka intsony ao, Ary tsy hisy olona hanorim-ponenana.”', '“dia ho lasa toerana ipetrahan’ny alikadia i hazora, ary ho aolo mandrakizay. tsy hisy hipetraka intsony ao, ary tsy hisy olona hanorim-ponenana.”'),
  ('6ab25bb4274d1d72758d193e', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 10, 'Fa hataoko mangadihady kosa i Esao. Hataoko miharihary ny toeram-piafenany Mba tsy ho afaka hiafina izy. Ho ripaka daholo ny zanany sy ny rahalahiny ary ny mpiara-monina aminy, Ary tsy hisy intsony izy.', 'fa hataoko mangadihady kosa i esao. hataoko miharihary ny toeram-piafenany mba tsy ho afaka hiafina izy. ho ripaka daholo ny zanany sy ny rahalahiny ary ny mpiara-monina aminy, ary tsy hisy intsony izy.'),
  ('6ab25bb4274d1d72758d1959', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 37, '“Hataoko mihorohoro eo anatrehan’ny fahavalony sy eo anatrehan’ireo mitady hamono azy ny Elamita. Hahatonga loza amin’izy ireo aho, ka hanampatra ny hatezerako aminy”, hoy i Jehovah. “Handefa sabatra hamely azy ireo aho, mandra-paharipany tanteraka.”', '“hataoko mihorohoro eo anatrehan’ny fahavalony sy eo anatrehan’ireo mitady hamono azy ny elamita. hahatonga loza amin’izy ireo aho, ka hanampatra ny hatezerako aminy”, hoy i jehovah. “handefa sabatra hamely azy ireo aho, mandra-paharipany tanteraka.”'),
  ('6ab25bb4274d1d72758d1950', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 28, 'Izao no lazain’i Jehovah momba an’i Kedara sy ireo fanjakana ao Hazora izay notafihin’i Nebokadnezara mpanjakan’i Babylona: “Mitsangàna ka miakara any Kedara, Ary aringano ireo zanaky ny Atsinanana.', 'izao no lazain’i jehovah momba an’i kedara sy ireo fanjakana ao hazora izay notafihin’i nebokadnezara mpanjakan’i babylona: “mitsangàna ka miakara any kedara, ary aringano ireo zanaky ny atsinanana.'),
  ('6ab25bb4274d1d72758d194f', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 27, '“Hodorako ny mandan’i Damaskosy, Ka ho levon’ny afo ny tilikambon’i Beni-hadada, dia ireo tilikambo voaro mafy.”', '“hodorako ny mandan’i damaskosy, ka ho levon’ny afo ny tilikambon’i beni-hadada, dia ireo tilikambo voaro mafy.”'),
  ('6ab25bb4274d1d72758d193f', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 11, 'Ilaozy ny kamboty ray ao aminao, Fa hitsimbina ny ain’izy ireny aho. Ary hatoky ahy ny mpitondratena ao aminao.”', 'ilaozy ny kamboty ray ao aminao, fa hitsimbina ny ain’izy ireny aho. ary hatoky ahy ny mpitondratena ao aminao.”'),
  ('6ab25bb4274d1d72758d1951', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 29, 'Ho lasan’olona ny tranolainy, ny ondry aman’osiny, Ny lainy, ary ny fananany rehetra. Hisy haka koa ny ramevany. Dia hisy hiantsoantso hilaza amin’ny mponin’i Kedara hoe: ‘Manjaka hatraiza hatraiza ny horohoro!’”', 'ho lasan’olona ny tranolainy, ny ondry aman’osiny, ny lainy, ary ny fananany rehetra. hisy haka koa ny ramevany. dia hisy hiantsoantso hilaza amin’ny mponin’i kedara hoe: ‘manjaka hatraiza hatraiza ny horohoro!’”'),
  ('6ab25bb4274d1d72758d1940', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 12, 'Fa izao no lazain’i Jehovah: “Raha ireo tsy voasazy hisotro amin’ny kaopy aza tsy maintsy misotro amin’ilay izy, dia ianao indray ve no havela ho afa-maina fotsiny? Tsy havela ho afa-maina ianao, fa tsy maintsy hisotro amin’ilay kaopy.”', 'fa izao no lazain’i jehovah: “raha ireo tsy voasazy hisotro amin’ny kaopy aza tsy maintsy misotro amin’ilay izy, dia ianao indray ve no havela ho afa-maina fotsiny? tsy havela ho afa-maina ianao, fa tsy maintsy hisotro amin’ilay kaopy.”'),
  ('6ab25bb4274d1d72758d193d', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 9, 'Raha misy mpioty voaloboka tonga ao aminao, Tsy hamela sisa hotsimponina ve izy? Raha misy mpangalatra tonga amin’ny alina, Dia izay tiany ihany no halainy.', 'raha misy mpioty voaloboka tonga ao aminao, tsy hamela sisa hotsimponina ve izy? raha misy mpangalatra tonga amin’ny alina, dia izay tiany ihany no halainy.'),
  ('6ab25bb4274d1d72758d195b', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 39, '“Any am-parany anefa, dia mbola hangoniko ireo Elamita lasa babo”, hoy i Jehovah.', '“any am-parany anefa, dia mbola hangoniko ireo elamita lasa babo”, hoy i jehovah.'),
  ('6ab25bb4274d1d72758d1943', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 15, '“Fa nataoko tsy misy dikany ianao eo amin’ireo firenena, Ary nataoko lasa tsinontsinona eo anatrehan’ny olona.', '“fa nataoko tsy misy dikany ianao eo amin’ireo firenena, ary nataoko lasa tsinontsinona eo anatrehan’ny olona.'),
  ('6ab25bb4274d1d72758d1952', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 30, '“Mandosira! Mandehana mitsoaka lavitra be! Mandehana miafina any amin’ny lalina, ry mponin’i Hazora!”, hoy i Jehovah. “Fa mikasa hamely anareo i Nebokadnezara mpanjakan’i Babylona, Ary misy tetika efa noeritreretiny hamelezana anareo.”', '“mandosira! mandehana mitsoaka lavitra be! mandehana miafina any amin’ny lalina, ry mponin’i hazora!”, hoy i jehovah. “fa mikasa hamely anareo i nebokadnezara mpanjakan’i babylona, ary misy tetika efa noeritreretiny hamelezana anareo.”'),
  ('6ab25bb4274d1d72758d194e', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 26, 'Fa hiampatrampatra eny amin’ny tany malalaka ny fatin’ireo tovolahy ao aminy, Ary ho ripaka daholo ny miaramila, amin’izany andro izany”, hoy i Jehovah Tompon’ny tafika.', 'fa hiampatrampatra eny amin’ny tany malalaka ny fatin’ireo tovolahy ao aminy, ary ho ripaka daholo ny miaramila, amin’izany andro izany”, hoy i jehovah tompon’ny tafika.'),
  ('6ab25bb4274d1d72758d194d', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 25, 'Nahoana àry no tsy nilaozana ilay tanàna noderaina fatratra, Ilay tanàna nahafaly?', 'nahoana àry no tsy nilaozana ilay tanàna noderaina fatratra, ilay tanàna nahafaly?'),
  ('6ab25bb4274d1d72758d1945', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 17, '“Hihorohoro ny olona mahita an’izay hanjo an’i Edoma. Ho tsiravina izay mpandalo mahita azy, ka hisioka noho ny loza rehetra hanjo azy.', '“hihorohoro ny olona mahita an’izay hanjo an’i edoma. ho tsiravina izay mpandalo mahita azy, ka hisioka noho ny loza rehetra hanjo azy.'),
  ('6ab25bb4274d1d72758d195a', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 38, '“Dia hapetrako ao Elama ny seza fiandrianako, ary haringako ny mpanjaka sy ny andriana ao aminy”, hoy i Jehovah.', '“dia hapetrako ao elama ny seza fiandrianako, ary haringako ny mpanjaka sy ny andriana ao aminy”, hoy i jehovah.'),
  ('6ab25bb4274d1d72758d194b', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 23, 'Izao no voalaza momba an’i Damaskosy: “Menatra i Hamata sy Arpada, Satria nandre vaovao ratsy. Matahotra be izy ireo. Mitebiteby ny olona, ka toy ny ranomasina tsy mety tony.', 'izao no voalaza momba an’i damaskosy: “menatra i hamata sy arpada, satria nandre vaovao ratsy. matahotra be izy ireo. mitebiteby ny olona, ka toy ny ranomasina tsy mety tony.'),
  ('6ab25bb4274d1d72758d194a', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 22, 'Hanao hoatran’ny voromahery miakatra sy mifaoka ny hazany izy, Ka hamelatra ny elany hifaoka an’i Bozra. Amin’izany andro izany, ny fon’ireo miaramila ao Edoma Dia hitebiteby toy ny fon’ny vehivavy eo am-piterahana.”', 'hanao hoatran’ny voromahery miakatra sy mifaoka ny hazany izy, ka hamelatra ny elany hifaoka an’i bozra. amin’izany andro izany, ny fon’ireo miaramila ao edoma dia hitebiteby toy ny fon’ny vehivavy eo am-piterahana.”'),
  ('6ab25bb4274d1d72758d1941', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 13, '“Mianiana amin’ny tenako aho”, hoy i Jehovah, “fa hihorohoro ny olona mahita an’izay hanjo an’i Bozra. Holatsaina sy horavana izy ary hozonina. Ho rava mandrakizay ny tanànany rehetra.”', '“mianiana amin’ny tenako aho”, hoy i jehovah, “fa hihorohoro ny olona mahita an’izay hanjo an’i bozra. holatsaina sy horavana izy ary hozonina. ho rava mandrakizay ny tanànany rehetra.”'),
  ('6ab25bb4274d1d72758d1957', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 35, '“Izao no lazain’i Jehovah Tompon’ny tafika: ‘Hotapahiko ny tsipìkan’i Elama, dia ny loharanon’ny heriny.', '“izao no lazain’i jehovah tompon’ny tafika: ‘hotapahiko ny tsipìkan’i elama, dia ny loharanon’ny heriny.'),
  ('6ab25bb4274d1d72758d1949', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 21, 'Nihovotrovotra ny tany noho ny fidoboky ny fianjeran’izy ireo. Misy feo mitaraindraina izany! Ary heno hatrany amin’ny Ranomasina Mena ilay izy.', 'nihovotrovotra ny tany noho ny fidoboky ny fianjeran’izy ireo. misy feo mitaraindraina izany! ary heno hatrany amin’ny ranomasina mena ilay izy.'),
  ('6ab25bb4274d1d72758d1946', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 18, 'Toy ny nandravana an’i Sodoma sy Gomora ary ireo tanàna manodidina azy”, hoy i Jehovah, “no hanjo an’i Edoma. Tsy hisy hipetraka intsony ao, ary tsy hisy olona hanorim-ponenana.', 'toy ny nandravana an’i sodoma sy gomora ary ireo tanàna manodidina azy”, hoy i jehovah, “no hanjo an’i edoma. tsy hisy hipetraka intsony ao, ary tsy hisy olona hanorim-ponenana.'),
  ('6ab25bb4274d1d72758d193a', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 6, '“‘Aorian’izany anefa, dia hangoniko ireo Amonita lasa babo’, hoy i Jehovah.”', '“‘aorian’izany anefa, dia hangoniko ireo amonita lasa babo’, hoy i jehovah.”'),
  ('6ab25bb4274d1d72758d1939', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 5, '“Hoy ilay Tompo Fara Tampony, dia i Jehovah Tompon’ny tafika: ‘Hataoko misy zavatra mampahatahotra hanjo anao, Avy amin’ireo rehetra manodidina anao. Haparitaka any amin’ny vazan-tany efatra ianareo, Ary tsy hisy hanangona an’izay mandositra.’”', '“hoy ilay tompo fara tampony, dia i jehovah tompon’ny tafika: ‘hataoko misy zavatra mampahatahotra hanjo anao, avy amin’ireo rehetra manodidina anao. haparitaka any amin’ny vazan-tany efatra ianareo, ary tsy hisy hanangona an’izay mandositra.’”'),
  ('6ab25bb4274d1d72758d1944', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 16, 'Namitaka anao ny fampihorohoroana nataonao Sy ny fireharehan’ny fonao, Ry ilay mipetraka eny an-tsefatsefaky ny harambato Sy monina eny amin’ny havoana avo indrindra. Na manorina ny akaninao eny amin’ny avo toy ny ataon’ny voromahery aza ianao, Dia hampidiniko avy eny”, hoy i Jehovah.', 'namitaka anao ny fampihorohoroana nataonao sy ny fireharehan’ny fonao, ry ilay mipetraka eny an-tsefatsefaky ny harambato sy monina eny amin’ny havoana avo indrindra. na manorina ny akaninao eny amin’ny avo toy ny ataon’ny voromahery aza ianao, dia hampidiniko avy eny”, hoy i jehovah.'),
  ('6ab25bb4274d1d72758d1948', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 20, 'Koa henoy ny fanapahan-kevitr’i Jehovah hamelezana an’i Edoma, sy izay efa noeritreretiny hamelezana ny mponin’i Temana: Hotaritaritina tokoa ny ondrikely. Horavany ny toerana ipetrahan’izy ireo noho ny amin’ireo mponina ao.', 'koa henoy ny fanapahan-kevitr’i jehovah hamelezana an’i edoma, sy izay efa noeritreretiny hamelezana ny mponin’i temana: hotaritaritina tokoa ny ondrikely. horavany ny toerana ipetrahan’izy ireo noho ny amin’ireo mponina ao.'),
  ('6ab25bb4274d1d72758d193c', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 8, 'Miverena ka mandosira! Mandehana miafina any amin’ny lalina, ry mponin’i Dedana! Fa hahatonga loza amin’i Esao aho Rehefa tonga ny fotoana hanasaziako azy.', 'miverena ka mandosira! mandehana miafina any amin’ny lalina, ry mponin’i dedana! fa hahatonga loza amin’i esao aho rehefa tonga ny fotoana hanasaziako azy.'),
  ('6ab25bb4274d1d72758d194c', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 24, 'Tsy manana herim-po intsony i Damaskosy. Te handositra izy nefa tora-kovitra. Mijalijaly sy manaintaina izy Hoatran’ny vehivavy efa ho teraka.', 'tsy manana herim-po intsony i damaskosy. te handositra izy nefa tora-kovitra. mijalijaly sy manaintaina izy hoatran’ny vehivavy efa ho teraka.'),
  ('6ab25bb4274d1d72758d1942', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 14, 'Naheno tatitra avy amin’i Jehovah aho. Nisy olona nirahina hankany amin’ireo firenena hilaza hoe: “Miangòna dia andao hanafika azy, Miomàna hiady aminy!”', 'naheno tatitra avy amin’i jehovah aho. nisy olona nirahina hankany amin’ireo firenena hilaza hoe: “miangòna dia andao hanafika azy, miomàna hiady aminy!”'),
  ('6ab25bb4274d1d72758d1947', '2026-09-22T10:43:00.031Z', '2026-09-22T10:43:00.031Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jeremia', 24, 49, 19, '“Jereo fa hisy olona hiakatra hamely an’ireo kijana tsy nisy mpanafika, toy ny liona miakatra avy ao anaty kirihitrala matevina eny amoron’i Jordana. Hasaiko mandositra avy hatrany anefa izy ka hiala ao amin’ny taniny. Dia hotendreko hitarika azy ilay voafidy. Fa iza moa no hoatr’ahy, ary iza no ho sahy hila ady amiko? Iza no mpiandry ondry mahatohitra ahy?', '“jereo fa hisy olona hiakatra hamely an’ireo kijana tsy nisy mpanafika, toy ny liona miakatra avy ao anaty kirihitrala matevina eny amoron’i jordana. hasaiko mandositra avy hatrany anefa izy ka hiala ao amin’ny taniny. dia hotendreko hitarika azy ilay voafidy. fa iza moa no hoatr’ahy, ary iza no ho sahy hila ady amiko? iza no mpiandry ondry mahatohitra ahy?'),
  ('6ab25bb67a649ef6cd9d87eb', '2026-09-22T10:43:02.609Z', '2026-09-22T10:43:02.609Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 4, 'Misaona ireo lalana mankany Ziona, satria tsy misy olona tonga mamonjy fety. Potika daholo ny vavahadiny, ary misento ny mpisorony. Malahelo be ireo virjiny ao aminy, ary ory dia ory izy. ה [ He ]', 'misaona ireo lalana mankany ziona, satria tsy misy olona tonga mamonjy fety. potika daholo ny vavahadiny, ary misento ny mpisorony. malahelo be ireo virjiny ao aminy, ary ory dia ory izy. ה [ he ]'),
  ('6ab25bb67a649ef6cd9d87ea', '2026-09-22T10:43:02.609Z', '2026-09-22T10:43:02.609Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 3, 'Natao sesitany i Joda ary mijaly sady andevozina. Voatery mipetraka any amin’ireo firenena izy; tsy mahita fiadanana mihitsy izy. Tratran’ireo rehetra nanenjika azy izy tamin’izy tao anatin’ny fahoriana. ד [ Daleta ]', 'natao sesitany i joda ary mijaly sady andevozina. voatery mipetraka any amin’ireo firenena izy; tsy mahita fiadanana mihitsy izy. tratran’ireo rehetra nanenjika azy izy tamin’izy tao anatin’ny fahoriana. ד [ daleta ]'),
  ('6ab25bb67a649ef6cd9d87e9', '2026-09-22T10:43:02.609Z', '2026-09-22T10:43:02.609Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 2, 'Mitomany be izy mandritra ny alina, ary kotsan’ny ranomasony ny takolany. Tsy misy eo ny lehilahy rehetra niarahany mba hampionona azy. Namadika azy daholo ny namany; lasa fahavalony izy ireo. ג [ Gimela ]', 'mitomany be izy mandritra ny alina, ary kotsan’ny ranomasony ny takolany. tsy misy eo ny lehilahy rehetra niarahany mba hampionona azy. namadika azy daholo ny namany; lasa fahavalony izy ireo. ג [ gimela ]'),
  ('6ab25bb67a649ef6cd9d87e8', '2026-09-22T10:43:02.609Z', '2026-09-22T10:43:02.609Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 1, 'Indrisy! Mipetraka irery ankehitriny ilay tanàna be olona fahiny. Lasa toy ny vehivavy maty vady ilay tanàna be mponina teo amin’ireo firenena! Nampanaovina asa an-terivozona ilay andriambavy teo amin’ireo faritany! ב [ Beta ]', 'indrisy! mipetraka irery ankehitriny ilay tanàna be olona fahiny. lasa toy ny vehivavy maty vady ilay tanàna be mponina teo amin’ireo firenena! nampanaovina asa an-terivozona ilay andriambavy teo amin’ireo faritany! ב [ beta ]'),
  ('6ab25bb67a649ef6cd9d87fc', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 21, 'Ren’ny olona hoe misento aho. Tsy misy na iza na iza hampionona ahy. Henon’ny fahavaloko rehetra ny loza manjo ahy. Faly izy ireo satria ianao no nahatonga an’izany. Hataonao anefa izay hiavian’ilay andro efa nambaranao, ka ho lasa hoatr’ahy izy ireo amin’izay. ת [ Tao ]', 'ren’ny olona hoe misento aho. tsy misy na iza na iza hampionona ahy. henon’ny fahavaloko rehetra ny loza manjo ahy. faly izy ireo satria ianao no nahatonga an’izany. hataonao anefa izay hiavian’ilay andro efa nambaranao, ka ho lasa hoatr’ahy izy ireo amin’izay. ת [ tao ]'),
  ('6ab25bb67a649ef6cd9d87f4', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 13, 'Mandatsaka afo avy any amin’ny avo izy mba handoroana ny taolako rehetra. Mamelatra harato hamandrihana ny tongotro izy; tereny hihemotra aho. Ataony lasa vehivavy manirery aho. Marary foana aho tontolo andro. נ [ Nkona ]', 'mandatsaka afo avy any amin’ny avo izy mba handoroana ny taolako rehetra. mamelatra harato hamandrihana ny tongotro izy; tereny hihemotra aho. ataony lasa vehivavy manirery aho. marary foana aho tontolo andro. נ [ nkona ]'),
  ('6ab25bb67a649ef6cd9d87ec', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 5, 'Ireo manohitra azy indray izao no lasa tompony; tsy manana ahiahy ny fahavalony. Fa nataon’i Jehovah vonton’alahelo izy satria nandika lalàna imbetsaka. Nentin’ny fahavalo ho babo ny zanany. ו [ Vao ]', 'ireo manohitra azy indray izao no lasa tompony; tsy manana ahiahy ny fahavalony. fa nataon’i jehovah vonton’alahelo izy satria nandika lalàna imbetsaka. nentin’ny fahavalo ho babo ny zanany. ו [ vao ]'),
  ('6ab25bb67a649ef6cd9d87f8', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 17, 'Mamelatra ny tanany i Ziona, mangataka fanampiana. Tsy misy na iza na iza hampionona azy. Nomen’i Jehovah baiko ny fahavalo rehetra manodidina an’i Jakoba mba hamely azy. Lasa zava-maharikoriko amin’izy ireo i Jerosalema. צ [ Tsade ]', 'mamelatra ny tanany i ziona, mangataka fanampiana. tsy misy na iza na iza hampionona azy. nomen’i jehovah baiko ny fahavalo rehetra manodidina an’i jakoba mba hamely azy. lasa zava-maharikoriko amin’izy ireo i jerosalema. צ [ tsade ]'),
  ('6ab25bb67a649ef6cd9d87f7', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 16, 'Mitomany aho noho izany rehetra izany. Mirotsaka ny ranomasoko. Fa lavitra ahy daholo ny olona afaka mampionona na mampahery ahy. Tsy manana fanantenana intsony ny zanako lahy, fa ny fahavalo no nandresy. פ [ Pe ]', 'mitomany aho noho izany rehetra izany. mirotsaka ny ranomasoko. fa lavitra ahy daholo ny olona afaka mampionona na mampahery ahy. tsy manana fanantenana intsony ny zanako lahy, fa ny fahavalo no nandresy. פ [ pe ]'),
  ('6ab25bb67a649ef6cd9d87f0', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 9, 'Eo amin’ny akanjony ny lotony. Tsy nitsinjo ny hoaviny izy. Nanaitra ny fomba nianjerany; tsy misy na iza na iza hampionona azy. Jehovah ô, jereo ny fahoriako fa mirehareha ny fahavalo. י [ Yôda ]', 'eo amin’ny akanjony ny lotony. tsy nitsinjo ny hoaviny izy. nanaitra ny fomba nianjerany; tsy misy na iza na iza hampionona azy. jehovah ô, jereo ny fahoriako fa mirehareha ny fahavalo. י [ yôda ]'),
  ('6ab25bb67a649ef6cd9d87ef', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 8, 'Nanao fahotana lehibe i Jerosalema, Ka lasa zava-maharikoriko. Izay rehetra zatra nanome voninahitra azy dia lasa manao tsinontsinona azy izao, satria hitan’izy ireo ny fitanjahany. Na izy aza miferinaina sady mihodina tsy mahajery olona satria menatra. ט [ Teta ]', 'nanao fahotana lehibe i jerosalema, ka lasa zava-maharikoriko. izay rehetra zatra nanome voninahitra azy dia lasa manao tsinontsinona azy izao, satria hitan’izy ireo ny fitanjahany. na izy aza miferinaina sady mihodina tsy mahajery olona satria menatra. ט [ teta ]'),
  ('6ab25bb67a649ef6cd9d87f9', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 18, 'Rariny ny an’i Jehovah satria tsy nety nanaraka ny didiny aho. Mihainoa, ry firenena rehetra, ary jereo ny fijaliako. Lasa babo ny virjiny sy ny tovolahy teo amiko. ק [ Kôfa ]', 'rariny ny an’i jehovah satria tsy nety nanaraka ny didiny aho. mihainoa, ry firenena rehetra, ary jereo ny fijaliako. lasa babo ny virjiny sy ny tovolahy teo amiko. ק [ kôfa ]'),
  ('6ab25bb67a649ef6cd9d87f3', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 12, 'Tsy mampaninona anareo rehetra mandalo eo amin’ilay lalana ve izany? Jereo dia diniho! Mba misy fijaliana hoatran’ilay nanjo ahy ve, Dia ilay fijaliana nataon’i Jehovah nihatra tamiko tamin’ny andro naha tezitra be azy? מ [ Mema ]', 'tsy mampaninona anareo rehetra mandalo eo amin’ilay lalana ve izany? jereo dia diniho! mba misy fijaliana hoatran’ilay nanjo ahy ve, dia ilay fijaliana nataon’i jehovah nihatra tamiko tamin’ny andro naha tezitra be azy? מ [ mema ]'),
  ('6ab25bb67a649ef6cd9d87ed', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 6, 'Niala tamin’i Ziona zanakavavy ny hatsaran-tarehiny rehetra. Toy ny serfa tsy mahita kijana ireo andrianany, Ary reraka be izy ireo mandositra eo alohan’ny mpanenjika azy. ז [ Zaina ]', 'niala tamin’i ziona zanakavavy ny hatsaran-tarehiny rehetra. toy ny serfa tsy mahita kijana ireo andrianany, ary reraka be izy ireo mandositra eo alohan’ny mpanenjika azy. ז [ zaina ]'),
  ('6ab25bb67a649ef6cd9d87ee', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 7, 'Mandritra an’ireo andro ijalian’i Jerosalema sy tsy ananany fialofana, dia tsaroany Ny zava-tsarobidy rehetra nananany taloha. Rehefa resin’ny fahavalo ny vahoakany ary tsy nisy nanampy izy, Dia nahita an’izany ny fahavalo ka nihomehy azy noho ny fahavoazany. ח [ Heta ]', 'mandritra an’ireo andro ijalian’i jerosalema sy tsy ananany fialofana, dia tsaroany ny zava-tsarobidy rehetra nananany taloha. rehefa resin’ny fahavalo ny vahoakany ary tsy nisy nanampy izy, dia nahita an’izany ny fahavalo ka nihomehy azy noho ny fahavoazany. ח [ heta ]'),
  ('6ab25bb67a649ef6cd9d87fa', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 19, 'Niantso an’ireo lehilahy niaraka tamiko aho, nefa namadika ahy izy ireo. Maty tao an-tanàna ireo mpisorona sy anti-panahy teo amiko, Raha mbola nitady sakafo mba hitazonana aina. ר [ Resa ]', 'niantso an’ireo lehilahy niaraka tamiko aho, nefa namadika ahy izy ireo. maty tao an-tanàna ireo mpisorona sy anti-panahy teo amiko, raha mbola nitady sakafo mba hitazonana aina. ר [ resa ]'),
  ('6ab25bb67a649ef6cd9d87f5', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 14, 'Nafatotra toy ny zioga ny fandikan-dalàna rehetra nataoko, ka ny tanany no nampifamatotra azy ireny. Napetraka teo amin’ny vozoko ireny, ka nihareraka aho. Natolotr’i Jehovah teo an-tanan’ireo tsy voatohitro aho. ס [ Sameka ]', 'nafatotra toy ny zioga ny fandikan-dalàna rehetra nataoko, ka ny tanany no nampifamatotra azy ireny. napetraka teo amin’ny vozoko ireny, ka nihareraka aho. natolotr’i jehovah teo an-tanan’ireo tsy voatohitro aho. ס [ sameka ]'),
  ('6ab25bb67a649ef6cd9d87f2', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 11, 'Misento daholo ny vahoakan’i Jerosalema. Mitady sakafo izy ireo. Atakalony zavatra hohanina ny zava-tsarobidiny mba tsy hahafaty azy. Jehovah ô, jereo sy diniho fa lasa toy ny vehivavy tsy misy ilana azy aho. ל [ Lameda ]', 'misento daholo ny vahoakan’i jerosalema. mitady sakafo izy ireo. atakalony zavatra hohanina ny zava-tsarobidiny mba tsy hahafaty azy. jehovah ô, jereo sy diniho fa lasa toy ny vehivavy tsy misy ilana azy aho. ל [ lameda ]'),
  ('6ab25bb67a649ef6cd9d87fd', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 22, 'Enga anie hibaribary eo anatrehanao ny faharatsiany rehetra! Ary enga anie hataonao mahita faisana izy ireo, Hoatran’ny nataonao tamiko noho ny fandikan-dalàna rehetra nataoko. Fa misento foana aho, ary marary ny foko.', 'enga anie hibaribary eo anatrehanao ny faharatsiany rehetra! ary enga anie hataonao mahita faisana izy ireo, hoatran’ny nataonao tamiko noho ny fandikan-dalàna rehetra nataoko. fa misento foana aho, ary marary ny foko.'),
  ('6ab25bb67a649ef6cd9d87f6', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 15, 'Nailik’i Jehovah hiala amiko ny lehilahy mahery rehetra. Namory miaramila hamely ahy izy, mba hamotipotehana ny tovolahy eo amiko. Nohitsakitsahin’i Jehovah tao amin’ny lavaka famiazam-boaloboka i Joda zanakavavy virjiny. ע [ Aina ]', 'nailik’i jehovah hiala amiko ny lehilahy mahery rehetra. namory miaramila hamely ahy izy, mba hamotipotehana ny tovolahy eo amiko. nohitsakitsahin’i jehovah tao amin’ny lavaka famiazam-boaloboka i joda zanakavavy virjiny. ע [ aina ]'),
  ('6ab25bb67a649ef6cd9d87fb', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 20, 'Jehovah ô, jereo fa mijaly be aho. Mangotikotika ny ato anatiko. Mitebiteby ny foko ato anatiko, fa nikomy tanteraka aho. Eny ivelany, ripaky ny sabatra ny ankizy; ao an-trano, maty ny olona. ש [ Shina ]', 'jehovah ô, jereo fa mijaly be aho. mangotikotika ny ato anatiko. mitebiteby ny foko ato anatiko, fa nikomy tanteraka aho. eny ivelany, ripaky ny sabatra ny ankizy; ao an-trano, maty ny olona. ש [ shina ]'),
  ('6ab25bb67a649ef6cd9d87f1', '2026-09-22T10:43:02.610Z', '2026-09-22T10:43:02.610Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 1, 10, 'Nalain’ny fahavalo ny zava-tsarobidiny rehetra. Fa hitany niditra tao amin’ny toerany masina ireo firenena, Dia ireo noraranao tsy ho anisan’ny fiangonanao. כ [ Kafa ]', 'nalain’ny fahavalo ny zava-tsarobidiny rehetra. fa hitany niditra tao amin’ny toerany masina ireo firenena, dia ireo noraranao tsy ho anisan’ny fiangonanao. כ [ kafa ]'),
  ('6ab25bb77af255c7c939138a', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 5, 'Nataony fahirano aho; poizina mangidy sy fahoriana no nataony manodidina ahy.', 'nataony fahirano aho; poizina mangidy sy fahoriana no nataony manodidina ahy.'),
  ('6ab25bb77af255c7c9391395', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 16, 'Ataony mikarepoka vatokely ny nifiko ka tapaka. Ataony mitampify ao anaty lavenona aho.', 'ataony mikarepoka vatokely ny nifiko ka tapaka. ataony mitampify ao anaty lavenona aho.'),
  ('6ab25bb77af255c7c939138d', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 8, 'Ary tsy mety mihaino ny vavaka ataoko izy rehefa mitalaho miantso vonjy aho.', 'ary tsy mety mihaino ny vavaka ataoko izy rehefa mitalaho miantso vonjy aho.'),
  ('6ab25bb77af255c7c939138c', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 7, 'Nofefeny ny manodidina ahy mba tsy ho afaka hitsoaka aho. Nofatorany tamin’ny gadra varahina mavesatra aho.', 'nofefeny ny manodidina ahy mba tsy ho afaka hitsoaka aho. nofatorany tamin’ny gadra varahina mavesatra aho.'),
  ('6ab25bb77af255c7c939138f', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 10, 'Toy ny orsa miafina mba hanafika ahy izy, ary toy ny liona mamitsaka mba hamely.', 'toy ny orsa miafina mba hanafika ahy izy, ary toy ny liona mamitsaka mba hamely.'),
  ('6ab25bb77af255c7c9391390', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 11, 'Notereny hivily lalana aho, ary norotidrotehiny. Nataony lasa singan’olona aho sisa.', 'notereny hivily lalana aho, ary norotidrotehiny. nataony lasa singan’olona aho sisa.');
INSERT INTO "bible_verses" ("id", "created_date", "updated_date", "created_by_id", "created_by", "translation", "book", "bookOrder", "chapter", "verse", "text", "normalizedText") VALUES
  ('6ab25bb77af255c7c939138e', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 9, 'Nosakanany tamin’ny vato voapaika ny lalako, Sady nataony niolakolaka. ד [ Daleta ]', 'nosakanany tamin’ny vato voapaika ny lalako, sady nataony niolakolaka. ד [ daleta ]'),
  ('6ab25bb77af255c7c9391394', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 15, 'Novokisany zavatra mangidy aho, ary nosesefany zavamaniry mangidy be. ו [ Vao ]', 'novokisany zavatra mangidy aho, ary nosesefany zavamaniry mangidy be. ו [ vao ]'),
  ('6ab25bb77af255c7c9391388', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 3, 'Tena asian’ny tanany foana aho tontolo andro. ב [ Beta ]', 'tena asian’ny tanany foana aho tontolo andro. ב [ beta ]'),
  ('6ab25bb77af255c7c939138b', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 6, 'Notereny hipetraka tao amin’ny toerana maizina aho, toy ny olona maty efa ela. ג [ Gimela ]', 'notereny hipetraka tao amin’ny toerana maizina aho, toy ny olona maty efa ela. ג [ gimela ]'),
  ('6ab25bb77af255c7c9391393', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 14, 'Lasa nataon’ny olona rehetra fihomehezana aho, sady nataony hirahira tontolo andro.', 'lasa nataon’ny olona rehetra fihomehezana aho, sady nataony hirahira tontolo andro.'),
  ('6ab25bb77af255c7c9391391', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 12, 'Nataony vonona hitifirana ny tsipìkany, ary atsangany aho mba hokendreny amin’ny zana-tsipìka. ה [ He ]', 'nataony vonona hitifirana ny tsipìkany, ary atsangany aho mba hokendreny amin’ny zana-tsipìka. ה [ he ]'),
  ('6ab25bb77af255c7c9391392', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 13, 'Notsatohany tamin’ny zana-tsipìka avy tao amin’ny tranon-jana-tsipìkany ny voako.', 'notsatohany tamin’ny zana-tsipìka avy tao amin’ny tranon-jana-tsipìkany ny voako.'),
  ('6ab25bb77af255c7c9391389', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 4, 'Nataony mihalany ny nofoko sy ny hoditro. Notapatapahiny ny taolako.', 'nataony mihalany ny nofoko sy ny hoditro. notapatapahiny ny taolako.'),
  ('6ab25bb77af255c7c9391387', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 2, 'Noroahiny aho ary asainy mandeha ao anaty haizina, fa tsy ao amin’ny mazava.', 'noroahiny aho ary asainy mandeha ao anaty haizina, fa tsy ao amin’ny mazava.'),
  ('6ab25bb77af255c7c9391386', '2026-09-22T10:43:03.915Z', '2026-09-22T10:43:03.915Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 1, 'Izaho ilay lehilahy nahita ny fahorian’ny olona noho ny tsorakazon’ny fahatezerany.', 'izaho ilay lehilahy nahita ny fahorian’ny olona noho ny tsorakazon’ny fahatezerany.'),
  ('6ab25bb77af255c7c93913bf', '2026-09-22T10:43:03.916Z', '2026-09-22T10:43:03.916Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 58, 'Niaro ahy teo amin’ny fitsarana ianao, Jehovah ô! Navotanao ny aiko.', 'niaro ahy teo amin’ny fitsarana ianao, jehovah ô! navotanao ny aiko.'),
  ('6ab25bb77af255c7c93913b8', '2026-09-22T10:43:03.916Z', '2026-09-22T10:43:03.916Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 51, 'Nalahelo aho nahita an’izay nanjo an’ireo ankizivavy rehetra ao an-tanànako. צ [ Tsade ]', 'nalahelo aho nahita an’izay nanjo an’ireo ankizivavy rehetra ao an-tanànako. צ [ tsade ]'),
  ('6ab25bb77af255c7c9391399', '2026-09-22T10:43:03.916Z', '2026-09-22T10:43:03.916Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 20, 'Hahatsiaro izany tokoa ianao ka hiondrika hanampy ahy.', 'hahatsiaro izany tokoa ianao ka hiondrika hanampy ahy.'),
  ('6ab25bb77af255c7c93913ba', '2026-09-22T10:43:03.916Z', '2026-09-22T10:43:03.916Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 53, 'Nanapitra ny aiko tao anaty lavaka izy ireo; nitora-bato ahy foana izy ireo.', 'nanapitra ny aiko tao anaty lavaka izy ireo; nitora-bato ahy foana izy ireo.'),
  ('6ab25bb77af255c7c93913ab', '2026-09-22T10:43:03.916Z', '2026-09-22T10:43:03.916Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 38, 'Tsy miara-mivoaka amin’ny vavan’ny Avo Indrindra Ny ratsy sy ny tsara.', 'tsy miara-mivoaka amin’ny vavan’ny avo indrindra ny ratsy sy ny tsara.'),
