  ('6ab25bb77af255c7c93913b6', '2026-09-22T10:43:03.916Z', '2026-09-22T10:43:03.916Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Fitomaniana', 25, 3, 49, 'Mirotsaka tsy an-kijanona ny ranomasoko, ary tsy miato mihitsy,', 'mirotsaka tsy an-kijanona ny ranomasoko, ary tsy miato mihitsy,'),
