  ('6ab25c18ee65eaa44602e59d', '2026-09-22T10:44:40.396Z', '2026-09-22T10:44:40.396Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Matio', 40, 8, 20, 'Hoy anefa i Jesosy: “Manan-davaka hisitrihana ny amboadia, ary manana akany ny voro-manidina, fa ny Zanak’olona kosa tsy mba manana an’izay hametrahany ny lohany.”', 'hoy anefa i jesosy: “manan-davaka hisitrihana ny amboadia, ary manana akany ny voro-manidina, fa ny zanak’olona kosa tsy mba manana an’izay hametrahany ny lohany.”'),
