  ('6ab25c1a6612a20540e68a22', '2026-09-22T10:44:42.429Z', '2026-09-22T10:44:42.429Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Matio', 40, 12, 1, 'Indray mandeha, dia nandeha teny an-tanimbary i Jesosy sy ny mpianany. Sabata ny andro tamin’izay. Ary noana ny mpianany ka nioty salohim-bary, dia nihinana.', 'indray mandeha, dia nandeha teny an-tanimbary i jesosy sy ny mpianany. sabata ny andro tamin’izay. ary noana ny mpianany ka nioty salohim-bary, dia nihinana.'),
  ('6ab25c1a6612a20540e68a4c', '2026-09-22T10:44:42.429Z', '2026-09-22T10:44:42.429Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Matio', 40, 12, 43, '“Rehefa mivoaka avy ao amin’ny olona iray ny fanahy maloto, dia mamakivaky toerana karakaina mba hitady toerana hialana sasatra fa tsy mahita.', '“rehefa mivoaka avy ao amin’ny olona iray ny fanahy maloto, dia mamakivaky toerana karakaina mba hitady toerana hialana sasatra fa tsy mahita.'),
