  ('6ab25c1a6612a20540e68a40', '2026-09-22T10:44:42.429Z', '2026-09-22T10:44:42.429Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Matio', 40, 12, 31, '“Noho izany, dia izao no lazaiko aminareo: Izay rehetra mety ho fahotana sy fanevatevana zava-masina dia mbola hahazoana famelan-keloka, fa ny fanevatevana ny fanahy masina kosa tsy hahazoana famelan-keloka.', '“noho izany, dia izao no lazaiko aminareo: izay rehetra mety ho fahotana sy fanevatevana zava-masina dia mbola hahazoana famelan-keloka, fa ny fanevatevana ny fanahy masina kosa tsy hahazoana famelan-keloka.'),
