  ('6ab25c1ce686caccc67fbab0', '2026-09-22T10:44:44.051Z', '2026-09-22T10:44:44.051Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Matio', 40, 15, 20, 'Izany no mandoto ny olona, fa tsy ilay hoe mihinana amin’ny tanana tsy misasa.”', 'izany no mandoto ny olona, fa tsy ilay hoe mihinana amin’ny tanana tsy misasa.”'),
