  ('6ab25c2263ca2f0681d1adde', '2026-09-22T10:44:50.330Z', '2026-09-22T10:44:50.330Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Matio', 40, 23, 35, 'Dia amin’izay hivaly aminareo daholo ny ran’ny olo-marina nalatsaka teto an-tany, hatramin’ny ran’i Abela ka hatramin’ny ran’i Zakaria, zanak’i Barakia, izay novonoinareo teo anelanelan’ny toerana masina sy ny alitara.', 'dia amin’izay hivaly aminareo daholo ny ran’ny olo-marina nalatsaka teto an-tany, hatramin’ny ran’i abela ka hatramin’ny ran’i zakaria, zanak’i barakia, izay novonoinareo teo anelanelan’ny toerana masina sy ny alitara.'),
