  ('6ab25c643777ec846fff9f13', '2026-09-22T10:45:56.443Z', '2026-09-22T10:45:56.443Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 12, 48, 'Fa izay tsy nahalala ny sitrapon’ny tompony kosa, nefa nanao zavatra tokony hikapohana azy, dia ho kely kokoa ny kapoka ho azony. Izay nomena betsaka dia hitakiana betsaka, ary izay nanankinana zavatra betsaka dia bebe kokoa noho ny mahazatra no hotakina aminy.', 'fa izay tsy nahalala ny sitrapon’ny tompony kosa, nefa nanao zavatra tokony hikapohana azy, dia ho kely kokoa ny kapoka ho azony. izay nomena betsaka dia hitakiana betsaka, ary izay nanankinana zavatra betsaka dia bebe kokoa noho ny mahazatra no hotakina aminy.'),
  ('6ab25c643777ec846fff9ef3', '2026-09-22T10:45:56.443Z', '2026-09-22T10:45:56.443Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 12, 16, 'Ary nilaza fanoharana tamin’izy ireo izy hoe: “Namokatra be ny tanin’ny lehilahy mpanankarena iray.', 'ary nilaza fanoharana tamin’izy ireo izy hoe: “namokatra be ny tanin’ny lehilahy mpanankarena iray.'),
