  ('6ab25c646ec61294697ef3b9', '2026-09-22T10:45:56.999Z', '2026-09-22T10:45:56.999Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 13, 13, 'Dia nametra-tanana taminy izy, ka tonga dia nitraka ilay vehivavy ary nanome voninahitra an’Andriamanitra.', 'dia nametra-tanana taminy izy, ka tonga dia nitraka ilay vehivavy ary nanome voninahitra an’andriamanitra.'),
  ('6ab25c646ec61294697ef3ae', '2026-09-22T10:45:56.999Z', '2026-09-22T10:45:56.999Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 13, 2, 'Niteny àry i Jesosy hoe: “Mieritreritra ve ianareo hoe mpanota kokoa noho ny Galilianina hafa rehetra ireny, satria izany no nanjo azy?', 'niteny àry i jesosy hoe: “mieritreritra ve ianareo hoe mpanota kokoa noho ny galilianina hafa rehetra ireny, satria izany no nanjo azy?'),
