  ('6ab25c65b63604daeed9f8ab', '2026-09-22T10:45:57.931Z', '2026-09-22T10:45:57.931Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 15, 31, 'Dia hoy ny rainy: ‘Ianao ange, anaka, teto amiko foana e! Ary anao daholo izay rehetra ananako!', 'dia hoy ny rainy: ‘ianao ange, anaka, teto amiko foana e! ary anao daholo izay rehetra ananako!'),
