  ('6ab25c65b63604daeed9f8a8', '2026-09-22T10:45:57.931Z', '2026-09-22T10:45:57.931Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 15, 28, 'Tezitra anefa ilay zokiny, ka tsy nety niditra. Dia nivoaka ny rainy ka niangavy azy mba handroso.', 'tezitra anefa ilay zokiny, ka tsy nety niditra. dia nivoaka ny rainy ka niangavy azy mba handroso.'),
  ('6ab25c65b63604daeed9f89f', '2026-09-22T10:45:57.931Z', '2026-09-22T10:45:57.931Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 15, 19, 'Tsy mendrika ny hantsoina hoe zanakao intsony aho, fa mba ataovy hoatran’ny iray amin’ireo olona karamainao.”’', 'tsy mendrika ny hantsoina hoe zanakao intsony aho, fa mba ataovy hoatran’ny iray amin’ireo olona karamainao.”’'),
  ('6ab25c65b63604daeed9f89c', '2026-09-22T10:45:57.931Z', '2026-09-22T10:45:57.931Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 15, 16, 'Tena tiany raha mba vokin’ny hanin-kisoa izy. Tsy nisy nanome azy na inona na inona anefa.', 'tena tiany raha mba vokin’ny hanin-kisoa izy. tsy nisy nanome azy na inona na inona anefa.'),
