  ('6ab25c6aa86ff60c5789aa5a', '2026-09-22T10:46:02.577Z', '2026-09-22T10:46:02.577Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 22, 13, 'Lasa àry izy roa lahy, dia hitan’izy ireo daholo izay nolazainy tamin’izy ireo. Ary nokarakarain’izy ireo ny Paska.', 'lasa àry izy roa lahy, dia hitan’izy ireo daholo izay nolazainy tamin’izy ireo. ary nokarakarain’izy ireo ny paska.'),
