  ('6ab25c6cfb2e9b996551daa2', '2026-09-22T10:46:04.380Z', '2026-09-22T10:46:04.380Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 24, 18, 'Ary hoy ilay atao hoe Kleopasy: “Vahiny mipetra-drery any Jerosalema angaha ianao no tsy mahalala ny zava-nitranga tany tato ho ato?”', 'ary hoy ilay atao hoe kleopasy: “vahiny mipetra-drery any jerosalema angaha ianao no tsy mahalala ny zava-nitranga tany tato ho ato?”'),
  ('6ab25c6cfb2e9b996551daa4', '2026-09-22T10:46:04.380Z', '2026-09-22T10:46:04.380Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 24, 20, 'Dia nanolotra azy mba homelohina ho faty ny lehiben’ny mpisorona sy ny mpitondra eo amin’ny Jiosy. Koa nofantsihan-dry zareo teo amin’ny tsato-kazo izy.', 'dia nanolotra azy mba homelohina ho faty ny lehiben’ny mpisorona sy ny mpitondra eo amin’ny jiosy. koa nofantsihan-dry zareo teo amin’ny tsato-kazo izy.'),
  ('6ab25c6cfb2e9b996551daa0', '2026-09-22T10:46:04.380Z', '2026-09-22T10:46:04.380Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Lioka', 42, 24, 16, 'Nahita azy izy roa lahy nefa tsy nahafantatra azy.', 'nahita azy izy roa lahy nefa tsy nahafantatra azy.'),
