  ('6ab25c6dba2620b3e0ddb0ce', '2026-09-22T10:46:05.160Z', '2026-09-22T10:46:05.160Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 1, 18, 'Mbola tsy nisy nahita an’Andriamanitra mihitsy, fa ilay hany andriamanitra nateraka, izay eo akaikin’ny Ray, no nanazava ny momba Azy.', 'mbola tsy nisy nahita an’andriamanitra mihitsy, fa ilay hany andriamanitra nateraka, izay eo akaikin’ny ray, no nanazava ny momba azy.'),
  ('6ab25c6dba2620b3e0ddb0e7', '2026-09-22T10:46:05.160Z', '2026-09-22T10:46:05.160Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 1, 43, 'Te ho any Galilia i Jesosy ny ampitson’iny. Dia nahita an’i Filipo izy, ka niteny hoe: “Andao hanara-dia ahy.”', 'te ho any galilia i jesosy ny ampitson’iny. dia nahita an’i filipo izy, ka niteny hoe: “andao hanara-dia ahy.”'),
