  ('6ab25c6dba2620b3e0ddb0e2', '2026-09-22T10:46:05.160Z', '2026-09-22T10:46:05.160Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 1, 38, 'Dia nitodika i Jesosy, ka nahita azy ireo nanaraka azy, dia nanontany hoe: “Inona no tadiavinareo?” Hoy ireo: “Aiza ianao no mipetraka, Raby ô?”—raha adika izany dia hoe “Mpampianatra ô”—', 'dia nitodika i jesosy, ka nahita azy ireo nanaraka azy, dia nanontany hoe: “inona no tadiavinareo?” hoy ireo: “aiza ianao no mipetraka, raby ô?”—raha adika izany dia hoe “mpampianatra ô”—'),
  ('6ab25c6dba2620b3e0ddb0e1', '2026-09-22T10:46:05.160Z', '2026-09-22T10:46:05.160Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 1, 37, 'Rehefa naheno azy niteny an’izany ireo mpianatra roa lahy ireo, dia nanaraka an’i Jesosy.', 'rehefa naheno azy niteny an’izany ireo mpianatra roa lahy ireo, dia nanaraka an’i jesosy.'),
