  ('6ab25c71f95a03c9a59b7e50', '2026-09-22T10:46:09.009Z', '2026-09-22T10:46:09.009Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 5, 17, 'Hoy anefa izy: “Miasa foana ny Raiko hatramin’izao, dia izaho koa miasa foana.”', 'hoy anefa izy: “miasa foana ny raiko hatramin’izao, dia izaho koa miasa foana.”'),
  ('6ab25c71f95a03c9a59b7e4e', '2026-09-22T10:46:09.009Z', '2026-09-22T10:46:09.009Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 5, 15, 'Dia lasa ilay lehilahy niteny tamin’ny Jiosy hoe i Jesosy no nanasitrana azy.', 'dia lasa ilay lehilahy niteny tamin’ny jiosy hoe i jesosy no nanasitrana azy.'),
