  ('6ab25c72fdf83f9f79a059c6', '2026-09-22T10:46:10.718Z', '2026-09-22T10:46:10.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 7, 12, 'Ary nitakoritsika be momba azy ny vahoaka. Hoy ny sasany: “Olona tsara fanahy izy.” Fa hoy kosa ny hafa: “Tsy tsara fanahy izy, fa mpamita-bahoaka.”', 'ary nitakoritsika be momba azy ny vahoaka. hoy ny sasany: “olona tsara fanahy izy.” fa hoy kosa ny hafa: “tsy tsara fanahy izy, fa mpamita-bahoaka.”'),
  ('6ab25c72fdf83f9f79a059c1', '2026-09-22T10:46:10.718Z', '2026-09-22T10:46:10.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 7, 7, 'Tsy misy antony ankahalan’izao tontolo izao anareo. Izaho anefa halany, satria manaporofo hoe ratsy ny ataony.', 'tsy misy antony ankahalan’izao tontolo izao anareo. izaho anefa halany, satria manaporofo hoe ratsy ny ataony.'),
  ('6ab25c72fdf83f9f79a059bd', '2026-09-22T10:46:10.718Z', '2026-09-22T10:46:10.718Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 7, 3, 'Hoy àry ny rahalahiny taminy: “Mialà eto dia mankanesa any Jodia, mba ho hitan’ny mpianatrao koa ny asa ataonao.', 'hoy àry ny rahalahiny taminy: “mialà eto dia mankanesa any jodia, mba ho hitan’ny mpianatrao koa ny asa ataonao.'),
