  ('6ab25c72fdf83f9f79a059e8', '2026-09-22T10:46:10.719Z', '2026-09-22T10:46:10.719Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 7, 46, 'Namaly ny mpiambina hoe: “Mbola tsy nisy olona niteny hoatr’izany mihitsy.”', 'namaly ny mpiambina hoe: “mbola tsy nisy olona niteny hoatr’izany mihitsy.”'),
  ('6ab25c72fdf83f9f79a059e7', '2026-09-22T10:46:10.719Z', '2026-09-22T10:46:10.719Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 7, 45, 'Avy eo dia niverina tany amin’ny lehiben’ny mpisorona sy ny Fariseo ny mpiambina. Dia hoy ny Fariseo taminy: “Fa maninona no tsy nentinareo nankatỳ izy?”', 'avy eo dia niverina tany amin’ny lehiben’ny mpisorona sy ny fariseo ny mpiambina. dia hoy ny fariseo taminy: “fa maninona no tsy nentinareo nankatỳ izy?”'),
  ('6ab25c72fdf83f9f79a059dc', '2026-09-22T10:46:10.719Z', '2026-09-22T10:46:10.719Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 7, 34, 'Hitady ahy ianareo fa tsy hahita ahy, ary izay misy ahy dia tsy azonareo aleha.”', 'hitady ahy ianareo fa tsy hahita ahy, ary izay misy ahy dia tsy azonareo aleha.”'),
  ('6ab25c72fdf83f9f79a059d8', '2026-09-22T10:46:10.719Z', '2026-09-22T10:46:10.719Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 7, 30, 'Dia nitady hisambotra azy izy ireo, nefa tsy nisy nisambotra azy, satria mbola tsy tonga ny fotoana voatondro ho azy.', 'dia nitady hisambotra azy izy ireo, nefa tsy nisy nisambotra azy, satria mbola tsy tonga ny fotoana voatondro ho azy.'),
