  ('6ab25c769295ce152355a212', '2026-09-22T10:46:14.507Z', '2026-09-22T10:46:14.507Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 11, 25, 'Hoy i Jesosy: “Izaho no fananganana ny maty sy fiainana. Izay maneho finoana ahy, na maty aza, dia ho velona indray.', 'hoy i jesosy: “izaho no fananganana ny maty sy fiainana. izay maneho finoana ahy, na maty aza, dia ho velona indray.'),
  ('6ab25c769295ce152355a232', '2026-09-22T10:46:14.507Z', '2026-09-22T10:46:14.507Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jaona', 43, 11, 57, 'Efa nanome baiko anefa ny lehiben’ny mpisorona sy ny Fariseo fa izay mahafantatra hoe aiza i Jesosy, dia tokony hiteny, mba hahafahan’izy ireo hisambotra azy.', 'efa nanome baiko anefa ny lehiben’ny mpisorona sy ny fariseo fa izay mahafantatra hoe aiza i jesosy, dia tokony hiteny, mba hahafahan’izy ireo hisambotra azy.'),
