  ('6ab25ce4947cc7e38592e36f', '2026-09-22T10:48:04.014Z', '2026-09-22T10:48:04.014Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jakoba', 59, 2, 1, 'Ry rahalahiko, manam-pinoana an’i Jesosy Kristy Tompontsika be voninahitra ianareo, nefa nahoana no mbola manavakavaka ihany?', 'ry rahalahiko, manam-pinoana an’i jesosy kristy tompontsika be voninahitra ianareo, nefa nahoana no mbola manavakavaka ihany?'),
  ('6ab25ce4947cc7e38592e386', '2026-09-22T10:48:04.015Z', '2026-09-22T10:48:04.015Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jakoba', 59, 2, 24, 'Hitanareo àry fa lazaina hoe olo-marina ny olona noho izay ataony, fa tsy noho ny finoany fotsiny.', 'hitanareo àry fa lazaina hoe olo-marina ny olona noho izay ataony, fa tsy noho ny finoany fotsiny.'),
  ('6ab25ce4947cc7e38592e385', '2026-09-22T10:48:04.015Z', '2026-09-22T10:48:04.015Z', 'service_e1c00fac-7dab-4d04-875f-a062a5564d93', NULL, 'malagasy', 'Jakoba', 59, 2, 23, 'Tanteraka àry ny voalazan’ny Soratra Masina hoe: “Naneho finoana an’i Jehovah i Abrahama, ka nekena hoe olo-marina.” Dia nantsoina hoe naman’i Jehovah izy.', 'tanteraka àry ny voalazan’ny soratra masina hoe: “naneho finoana an’i jehovah i abrahama, ka nekena hoe olo-marina.” dia nantsoina hoe naman’i jehovah izy.'),
